P.entries["item:filled-red-waterskin"] = {n="Outre rouge remplie",s="À Moulin-de-Tarren, un puits fournit l’eau claire d’une source pour une épreuve de chaman. L’Outre rouge remplie contient l’eau puisée au puits du village, au milieu des ruines occupées par les Réprouvés.",h="À Moulin-de-Tarren, un puits fournit l’eau claire d’une source pour une épreuve de chaman.",kw={"brine","call of water","outre rouge vide","outre rouge remplie","sapta","chaman","moulin-de-tarren"},ang={["class:Shaman"]="En tant que chaman, transporter cette eau met à l’épreuve votre capacité à trouver et à honorer l’équilibre qui donne la vie dans les recoins les plus décrépits et les plus désolés du monde.",["faction:Horde"]="En tant que champion de la Horde venu de Kalimdor, vous vous rendez à Moulin-de-Tarren, où les Réprouvés luttent contre les forces de l’Alliance dans les Royaumes de l'est."},sec={{t="Un phare dans des terres flétries",b="Brine envoie les novices chamans de son ermitage dans Les Tarides à Moulin-de-Tarren pour s’exercer avec l’eau. Le voyage les mène dans les Contreforts de Hautebrande, où la décrépitude et les morts encerclent la ville. Pourtant, le puits en son cœur fournit toujours une eau de source claire.\n\nPour Brine, cette eau pure qui perdure est un signe de vie dans une terre impie. Elle compare cette source, épargnée par la corruption, à la détermination du chef de guerre Thrall face aux épreuves. Recueillir l’eau permet de vérifier si un novice respecte sa pureté, même dans un environnement hostile."}},faq={{q="Que contient l’Outre rouge remplie ?",a="L’Outre rouge remplie contient de l’eau de source pure, puisée dans le puits public au centre de Moulin-de-Tarren.",al={"quelle eau contient-elle","eau de moulin-de-tarren","contenu de l’outre rouge"}},{q="Pourquoi Brine veut-elle de l’eau de Moulin-de-Tarren ?",a="Brine voit dans la source fraîche de Moulin-de-Tarren un rare signe de pureté au milieu de la décrépitude des Réprouvés. Elle a besoin de cette eau pour préparer du sapta destiné aux épreuves chamaniques de l’eau.",al={"pourquoi moulin-de-tarren","pourquoi brine en a besoin","but de l’outre rouge"}},{q="Comment le puits reste-t-il pur dans une ville de morts-vivants ?",a="Nul ne sait pourquoi la source a échappé à la peste qui l’entoure. Brine dit que les Réprouvés de Moulin-de-Tarren ne reconnaissent peut-être pas la pureté de la source sacrée parmi eux, ou n’y accordent aucune valeur.",al={"pourquoi le puits n’est-il pas flétri","le puits de moulin-de-tarren est-il empoisonné","puits sacré de moulin-de-tarren"}},{q="Quel est le lien entre Thrall et cette quête ?",a="Brine compare le puits propre d’une ville en ruines à Thrall. Il a enduré de grandes souffrances et la captivité, puis en est ressorti fort et sans tache pour guider le peuple orc dans les heures sombres.",al={"comparaison avec thrall","pourquoi parler de thrall"}}},fx={c913c28c={q="D'où vient l'Outre rouge remplie ?",a="Vous l'obtenez en transportant une Outre rouge vide, qui vous est donnée par Brine dans les Tarides, jusqu'aux Contreforts de Hautebrande et en puisant de l'eau pure dans le puits du village de Moulin-de-Tarren. Brine se souvient du puits comme d'une étonnante poche d'eau de source fraîche persistant au milieu d'une colonie des Réprouvés.",al={"origine de l'outre rouge remplie","où obtenir l'outre rouge remplie","qui a fabriqué l'outre rouge remplie"}}},fp="20,170,26.516.0,40.105.0,43.150.0,47.181.0,37.180.0"}
P.entries["item:filled-soul-gem"] = {n="Gemme d'âme capturée",s="Nimboya vous demande d’apporter la Gemme d’âme à Grom'gol, où son peuple attend le retour de Yenniku.",h="Nimboya vous demande d’apporter la Gemme d’âme à Grom'gol, où son peuple attend le retour de Yenniku.",kw={"gemme d'âme capturée","grom'gol","kin'weelay","vue de l'esprit","nimboya","gemme d'âme","yenniku","zanzil"},sec={{t="Une âme restaurée",b="Aux ruines d’Aboraz, au cap Strangleronce, on pose la Gemme d’âme sur la tête de Yenniku pour capturer son âme. Apportez la Gemme d’âme capturée à Nimboya, à Grom'gol, où son peuple attend son retour."}},faq={{q="Qu’est-ce que la Gemme d’âme capturée ?",a="La Gemme d’âme capturée contient l’âme de Yenniku, capturée avec la Gemme d’âme aux ruines d’Aboraz.",al={"gemme capturée","gemme d’âme avec yenniku","contenu de la gemme"}},{q="Qui est Yenniku ?",a="Yenniku est un membre de la tribu de Nimboya, soumis à la volonté de Zanzil the Outcast.",al={"histoire de yenniku","qui est yenniku","yenniku"}},{q="Où dois-je apporter la gemme ?",a="Apportez la Gemme d’âme capturée à Nimboya, à Grom'gol.",al={"où va la gemme","où apporter la gemme","gemme de nimboya"}},{q="Comment la Gemme d’âme a-t-elle été créée ?",a="Kin'weelay a transformé la Vue de l’esprit en Gemme d’âme, qui capture l’âme de Yenniku.",al={"gemme de la vue de l’esprit","comment remplir une gemme d’âme","recette de gemme d’âme"}}},fp="15,92,15.196.0,28.95.1,15.83.0,24.49.0,26.82.1"}
P.entries["item:filled-tainted-ooze-jar"] = {n="Pot de Limon corrompu rempli",s="À Gangrebois, un Pot de Limon corrompu rempli transporte des échantillons de corruption jusqu’à Forgefer. Ils pourraient aider à expliquer comment la vie est apparue sur Azeroth.",h="À Gangrebois, un Pot de Limon corrompu rempli transporte des échantillons de corruption jusqu’à Forgefer.",kw={"ligue des explorateurs","gangrebois","forgefer","laris bringuefourbi","société royale des apothicaires","limon","limon corrompu"},ang={["faction:Alliance"]="En tant qu’éclaireur de l’Alliance, vous surveillez de près la Société royale des apothicaires des Réprouvés. Comprendre pourquoi Fossoyeuse rassemble du limon sur tous les continents est une priorité essentielle pour le renseignement.",["race:Gnome"]="En tant que réfugié gnome à Forgefer, vos travaux scientifiques avec la Ligue des explorateurs peuvent prouver votre valeur et vous permettre de rendre l’hospitalité des nains après la tragédie de Gnomeregan."},sec={{t="Limon du bois corrompu",b="Dans tout le nord de Kalimdor, les limons corrompus portent les traces persistantes de la corruption de Gangrebois. Des chercheurs gnomes fournissent des bocaux pour les conserver en toute sécurité. La plupart des voyageurs évitent ces créatures nocives, mais leurs restes fournissent des échantillons utiles à la philosophie naturelle et à l’étude biologique, loin des bois dévastés."},{t="La grande théorie de Geardawdle",b="Laris Bringuefourbi, un érudit gnome de la Ligue des explorateurs à Forgefer, rassemble les échantillons. La présence commune des limons le fascine, et il a également remarqué l’intérêt que leur porte la Société royale des apothicaires des Réprouvés.\n\nDe nombreux érudits rejettent la théorie de Geardawdle. Il pense que les limons et les vases pourraient être des sécrétions primordiales liées à la création d’Azeroth. Il cherche à en apporter la preuve et à se faire une place parmi les érudits nains après la chute tragique de Gnomeregan."}},faq={{q="Que contient un Pot de Limon corrompu rempli ?",a="Un Pot de Limon corrompu rempli contient un échantillon frais prélevé sur les restes d’un limon corrompu originaire de Gangrebois, scellé dans un bocal de collecte gnome.",al={"que contient le bocal","contenu du bocal de limon corrompu","qu’est-ce qu’un limon corrompu"}},{q="Qui veut ces échantillons de limon ?",a="Laris Bringuefourbi, un chercheur gnome de la Ligue des explorateurs au Hall of Explorers de Forgefer, veut ces échantillons pour ses études d’histoire naturelle.",al={"qui récupère le limon","quête de laris bringuefourbi","qui veut du limon corrompu"}},{q="Pourquoi Laris Bringuefourbi étudie-t-il les limons ?",a="Geardawdle a vu la Société royale des apothicaires rassembler des échantillons de limon et a entrepris d’en comprendre la nature. Il pense que les vases sont des sécrétions primordiales liées à la création d’Azeroth et espère se faire un nom comme scientifique à Forgefer.",al={"pourquoi étudier le limon","théorie de geardawdle sur le limon","pourquoi le gnome veut-il du limon"}},{q="Où ces échantillons sont-ils prélevés ?",a="Vous prélevez les échantillons à Gangrebois en vainquant des limons corrompus, puis en utilisant un bocal de confinement vide sur leurs restes.",al={"où trouver du limon corrompu","emplacement du bocal de limon corrompu","où remplir le bocal"}}},fx={["297c9c04"]={q="D'où vient un Pot de Limon corrompu rempli, et qui l'a fabriqué ?",a="Le bocal est fourni par le chercheur gnome Laris Bringuefourbi à Forgefer, qui fabrique des récipients en verre vides spécialisés pour collecter en toute sécurité des spécimens volatils. Il n'est rempli qu'une fois qu'un aventurier a terrassé un limon corrompu dans les forêts corrompues de Gangrebois et utilisé le bocal pour recueillir les restes gélatineux de la créature.",al={"origine du pot de limon corrompu","qui a fabriqué le pot de limon corrompu","d'où viennent les pots de limon corrompu"}}},fp="23,137,27.291.0,25.431.0,41.136.0,29.148.0,39.233.0,34.115.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Flasque de tourmaline remplie",s="Aux bassins d’Arlithrien, Corithras Ragelune attend la Flasque de tourmaline remplie. L’eau du puits de lune l’aide à surveiller la santé et l’équilibre de l’Arbre-monde en pleine croissance.",h="Aux bassins d’Arlithrien, Corithras Ragelune attend la Flasque de tourmaline remplie.",kw={"corithras ragelune","crown of the earth","flasque de tourmaline remplie","gnarlpine","puits de lune","bassins d'arlithrien","teldrassil","flasque de tourmaline"},ang={["class:Druid"]="En tant que druide, vous portez une flasque liée à l’héritage controversé de l’archidruide Fandral Forteramure. Il a insisté pour planter Teldrassil pendant l’absence inexpliquée de Shan'do Stormrage.",["race:NightElf"]="En tant qu’elfe de la nuit, vous savez que les eaux des puits de lune sont une source spirituelle vitale pour les kaldorei. La corruption qui sévit dans les bosquets Gnarlpine autour de ce puits de lune est un présage inquiétant pour votre nouveau foyer."},sec={{t="Les eaux d’Arlithrien",b="Un puits de lune se trouve sur les rives des bassins d’Arlithrien, au sud-est de The Road to Darnassus. Le chemin menant à son sanctuaire est devenu dangereux. Les furbolgs Gnarlpine étaient autrefois des voisins paisibles, mais ils sont désormais pris d’une violente folie. Corithras Ragelune demande aux voyageurs d’affronter les bosquets hostiles et de rapporter de l’eau. Il espère qu’elle l’aidera à découvrir la corruption qui s’étend à travers le pays."},{t="Les racines de Teldrassil",b="De retour à Dolanaar, Corithras Ragelune raconte comment Teldrassil fut créé. Après la disparition de Shan'do Malfurion Hurlorage, l’archidruide Fandral Forteramure rallia le Cercle des anciens par-delà la mer, à Sombrivage. Ils plantèrent l’arbre et cherchèrent à retrouver l’immortalité qu’ils avaient perdue. L’eau contenue dans la flasque reflète l’état de cette entreprise sacrée. À présent, une maladie inexpliquée se répand parmi les bêtes et les furbolgs."}},faq={{q="À quoi sert la Flasque de tourmaline remplie ?",a="À Dolanaar, Corithras Ragelune demande la Flasque de tourmaline remplie, qui contient de l’eau enchantée du puits de lune. Il recueille l’eau des puits de lune de Teldrassil pour étudier la propagation de la corruption et expliquer l’histoire de l’Arbre-monde aux défenseurs nouvellement arrivés.",al={"utilité de la flasque de tourmaline remplie","but de la flasque de tourmaline","pourquoi remplir la flasque"}},{q="Où se trouve le puits de lune de la Flasque de tourmaline ?",a="Le puits de lune se trouve au sud-est de la porte principale de Darnassus, sur les rives des bassins d’Arlithrien, dans le sud-ouest de Teldrassil. Des furbolgs Gnarlpine enragés disputent la zone.",al={"où remplir la flasque de tourmaline","puits de lune des bassins d’arlithrien","emplacement du puits d’arlithrien"}},{q="Pourquoi les furbolgs près du puits de lune attaquent-ils ?",a="Les furbolgs Gnarlpine vivaient autrefois en paix aux côtés des elfes de la nuit, mais une corruption rampante les afflige. Leur soudaine violence est l’un des signes de la maladie qui touche le jeune Arbre-monde.",al={"pourquoi les gnarlpine sont-ils fous","hostilité des furbolgs à arlithrien","gnarlpine déments"}},{q="Qui est Corithras Ragelune ?",a="Corithras Ragelune est un érudit et gardien elfe de la nuit à Dolanaar. Il guide les jeunes aventuriers dans le rite appelé Crown of the Earth et leur enseigne l’histoire des elfes de la nuit, la plantation de Teldrassil et la disparition de Malfurion Hurlorage.",al={"rôle de corithras","corithras à dolanaar"}}},fx={["360c6167"]={q="Qu'est-ce que la Flasque de tourmaline remplie ?",a="Il s'agit d'une flasque de tourmaline vide remplie des eaux sacrées et luminescentes du puits de lune près des Bassins d'Arlithrien à Teldrassil. Les druides elfes de la nuit utilisent des flasques sculptées dans différents minéraux pour récolter l'eau pure des puits de lune à travers toute l'île, gardant chaque échantillon distinct pour leurs rites sacrés et la purification de la terre.",al={"qu'est-ce que la flasque de tourmaline remplie","objet flasque de tourmaline remplie"}},b07aae52={q="D'où vient la Flasque de tourmaline remplie ?",a="Le récipient est fourni par Corithras Ragelune à Dolanaar. Vous créez la flasque remplie en l'emmenant au sud-est de Darnassus jusqu'au puits de lune situé sur les rives des Bassins d'Arlithrien et en puisant l'eau directement dans le bassin, au milieu des furbolgs Gnarlpine en maraude et agités.",al={"origine de la flasque de tourmaline remplie","d'où vient la flasque de tourmaline remplie"}},c83d83e7={q="Pourquoi Corithras Ragelune veut-il la Flasque de tourmaline remplie ?",a="Corithras Ragelune collecte les eaux des divers puits de lune de Teldrassil pour évaluer et préserver la vitalité spirituelle du jeune arbre-monde. Alors que la corruption s'insinue dans les branches et rend fous les furbolgs Gnarlpine, la collecte et l'examen de l'eau à travers les branches aident les druides à maintenir leur équilibre sacré et à comprendre ce qui afflige leur foyer.",al={"pourquoi corithras veut-il la flasque","utilité de la flasque de tourmaline remplie","pourquoi récolter l'eau de puits de lune"}}},fp="23,170,20.383.0,23.411.1,45.258.0,55.170.0,49.195.0,26.256.0"}
P.entries["item:filled-vessel"] = {n="Récipient rempli",s="À Dolanaar, Corithras Ragelune recueille les eaux des puits de lune de Teldrassil pour Fandral Forteramure, à Darnassus. Le Récipient rempli transporte ces échantillons pour l’aider à étudier les maux de l’Arbre-monde.",h="À Dolanaar, Corithras Ragelune recueille les eaux des puits de lune de Teldrassil pour Fandral Forteramure, à...",kw={"enclave cénarienne","corithras ragelune","crown of the earth","darnassus","fandral forteramure","récipient rempli","eau des puits de lune","teldrassil"},ang={["class:Druid"]="En tant que druide au service de la cause cénarienne, vous apportez ce récipient à l’Archidruide Fandral Forteramure pour votre première mission officielle. Il témoigne de la fragilité persistante du monde vivant de Teldrassil.",["race:NightElf"]="En tant qu’elfe de la nuit, vous savez que les eaux des puits de lune sont des sources de vie sacrées pour votre nouveau foyer. Elles mêlent la magie d’Elune à la croissance incertaine de l’Arbre-monde, privé de bénédictions."},sec={{t="Un mélange d’eaux sacrées",b="Des acolytes elfes de la nuit recueillent l’eau des puits de lune de Teldrassil. L’arbre a été planté sans les bénédictions des Grands Aspects, Alexstrasza et Nozdormu. Ses branches restent donc exposées à la corruption, aux bêtes étranges et aux tribus de furbolgs fous.\n\nÀ Dolanaar, Corithras Ragelune rassemble les fioles et les verse dans le Récipient rempli pour le voyage vers la capitale. Ensemble, ces eaux donnent un échantillon de la vitalité de Teldrassil. L’Archidruide Fandral Forteramure les étudie dans l’Enclave cénarienne, en quête d’un remède aux maux du Grand Arbre."}},faq={{q="Que contient le Récipient rempli ?",a="Le Récipient rempli contient de l’eau recueillie dans plusieurs puits de lune de Teldrassil. Corithras Ragelune rassemble les fioles à Dolanaar.",al={"contenu du récipient","quelle est cette eau","que contient le récipient"}},{q="À qui faut-il remettre le Récipient rempli ?",a="L’Archidruide Fandral Forteramure a besoin du Récipient rempli. Il réside au sommet de l’Enclave cénarienne, à Darnassus.",al={"à qui remettre le récipient rempli","où va le récipient","remise du récipient rempli"}},{q="Pourquoi Fandral Forteramure a-t-il besoin de ces échantillons d’eau ?",a="Les maux de Teldrassil viennent de l’absence des bénédictions des Grands Aspects. La corruption, les animaux agressifs et les furbolgs fous infestent ses branches. Forteramure étudie le mélange des eaux pour comprendre les défauts de l’arbre et chercher un remède.",al={"pourquoi forteramure veut de l’eau","à quoi sert l’eau des puits de lune pour forteramure","pourquoi recueillir l’eau des puits de lune"}},{q="Qui a préparé le récipient ?",a="Corithras Ragelune prépare le récipient à Dolanaar. Il y verse les fioles recueillies par de jeunes aventuriers avant de l’envoyer à Darnassus.",al={"qui a préparé le récipient rempli","qui remet le récipient rempli","récipient rempli de corithras"}}},fp="13,194,29.537.0,33.132.0,28.103.0,51.239.0,24.136.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Final Clue to Sanders' Treasure",s="Sur la côte de la Marche de l’Ouest, les dernières indications du Captain Sanders envoient les chercheurs de trésor en mer. Une note dans une vieille cruche indique l’ouest, vers son trésor enfoui.",h="Sur la côte de la Marche de l’Ouest, les dernières indications du Captain Sanders envoient les chercheurs de...",kw={"captain sanders","coffre","indice","pirate","trésor","marche de l’ouest","cruche de whisky"},ang={["class:Rogue"]="En tant que voleur, vous pouvez suivre les indications du Captain Sanders jusqu’au large et fouiller les côtes de la Marche de l’Ouest à la recherche d’un trésor au-delà des poches des Défias."},sec={{t="Les derniers mots d’un marin",b="Le Captain Sanders a laissé ses dernières indications dans une vieille cruche de whisky sur la côte de la Marche de l’Ouest. Le pirate avait dispersé des notes énigmatiques le long du rivage, et celle-ci complète la piste. Depuis la cruche, les indications pointent plein ouest, vers l’océan. Suivez-les à travers les vagues jusqu’à un rocher isolé au large, où repose son coffre de marin cerclé de fer."}},faq={{q="Que dit l’indice final ?",a="La note indique de partir vers l’ouest depuis la cruche de whisky et de prendre la mer. Un petit îlot au large abrite le coffre au trésor.",al={"texte de l’indice","inscription sur l’indice","indications de sanders"}},{q="Où cet indice a-t-il été trouvé ?",a="L’indice se trouvait dans une vieille cruche de whisky sur la côte de la Marche de l’Ouest. C’était la troisième étape de la piste d’indices du Captain Sanders.",al={"où trouver l’indice final","emplacement de la vieille cruche","emplacement de l’indice"}},{q="Qui était le Captain Sanders ?",a="Le Captain Sanders était un pirate dont les effets et les cartes au trésor ont échoué sur la côte de la Marche de l’Ouest. Avant sa mort, il a laissé des notes et des repères cachés dans les terres, qui mènent à son butin.",al={"qui est le captain sanders","histoire du pirate sanders","qui a caché le trésor"}},{q="Où cet indice mène-t-il finalement ?",a="La note mène vers l’ouest depuis la côte de la Marche de l’Ouest jusqu’à une île isolée. Le coffre de marin du Captain Sanders s’y trouve.",al={"où se trouve le coffre","île de sanders","emplacement de l’île"}}},fx={ed69490f={q="Qu'est-ce que le Final Clue to Sanders' Treasure ?",a="Il s'agit d'un morceau de papier usé retiré de la vieille cruche de whisky du capitaine Sanders le long de la côte de la Marche de l’Ouest. Sentant légèrement les spiritueux et avec de l'encre qui a coulé à cause de l'humidité, cette note marque l'aboutissement d'une chasse au trésor organisée par le défunt capitaine pirate, offrant les dernières directions nécessaires pour découvrir son trésor enterré.",al={"qu'est-ce que le final clue to sanders' treasure","identité de l'indice final","qu'est-ce que cet indice"}},["0f7c35ef"]={q="D'où vient le Final Clue to Sanders' Treasure, et qui l'a fabriqué ?",a="L'indice a été rédigé par le capitaine Sanders lui-même et scellé à l'intérieur d'une vieille cruche près du moulin à vent solitaire sur les falaises de la Marche de l’Ouest. Le capitaine pirate l'a caché comme dernière étape d'un sentier élaboré le long de la côte, s'assurant que seul quelqu'un d'assez déterminé pour suivre ses marqueurs de piste dispersés atteindrait jamais son butin caché.",al={"qui a fabriqué l'indice final","d'où vient l'indice final","origine de l'indice final"}},["9095866c"]={q="Pourquoi quelqu'un voudrait-il le Final Clue to Sanders' Treasure ?",a="Quiconque suit la piste du capitaine Sanders recherche son butin de pirate perdu depuis longtemps. Alors que les indices précédents menaient d'un point de repère côtier à un autre, cette dernière note dirige explicitement celui qui la trouve au-delà des plages de la Marche de l’Ouest et vers la pleine mer, directement vers l'île solitaire où le coffre du capitaine attend.",al={"pourquoi vouloir l'indice final","pourquoi trouver l'indice final","utilité de l'indice final"}}},fp="31,150,24.332.0,29.113.0,26.121.0,24.197.0,37.107.0"}
P.entries["item:final-message-to-the-wildhammer"] = {n="Message final pour les Wildhammer",s="Le Message final pour les Wildhammer est une lance qu’Otho Moji'ko envoie du Village des Revantusk au Nid-de-l’Aigle. Cette sinistre mise en scène doit montrer aux nains Wildhammer que les trolls ne plaisantent pas.",h="Le Message final pour les Wildhammer est une lance qu’Otho Moji'ko envoie du Village des Revantusk au...",kw={"nid-de-l’aigle","message final","plumes de griffon","otho moji'ko","village des revantusk","lance","puits","wildhammer"},ang={["faction:Alliance"]="Pour l’Alliance, la lance est une menace directe plantée au cœur du Nid-de-l’Aigle, parmi les nains Wildhammer.",["race:Troll"]="En tant que troll, vous portez la menace d’Otho Moji'ko au Nid-de-l’Aigle, où il espère que les nains Wildhammer verront la force des Revantusk."},sec={{t="Une lance pour le Nid-de-l’Aigle",b="Au Village des Revantusk, dans les Hinterlands, Otho Moji'ko vous remet une lance couverte de sang et enveloppée de plumes de griffon. Il veut que vous la plantiez près du puits, au centre du Nid-de-l’Aigle, où les nains Wildhammer la verront. Le message est sans détour, et Otho espère que vous reviendrez vivant."}},faq={{q="Qu’est-ce que le Message final pour les Wildhammer ?",a="C’est une lance couverte de sang et enveloppée de plumes de griffon, envoyée par Otho Moji'ko au Nid-de-l’Aigle.",al={"message final","lance des wildhammer","message d’otho"}},{q="Qui vous remet la lance ?",a="Otho Moji'ko vous remet la lance au Village des Revantusk, dans les Hinterlands.",al={"qui est otho","qui la remet","troll qui donne la lance"}},{q="Où faut-il apporter la lance ?",a="Otho veut que vous la plantiez près du puits, au centre du Nid-de-l’Aigle.",al={"où la planter","puits du nid-de-l’aigle","où est le message"}},{q="Pourquoi envoyer une lance ensanglantée ?",a="Otho veut que les nains Wildhammer comprennent que les trolls ne plaisantent pas.",al={"pourquoi la lance","que signifie le message","les trolls ne plaisantent pas"}},{q="Que se passe-t-il quand vous la plantez ?",a="Falstad Wildhammer pousse un cri lorsque vous plantez la lance, et vous passez en mode JcJ.",al={"cri de falstad","poser le message","réaction des wildhammer"}}},fp="31,193,22.278.0,44.93.0,24.73.0,24.67.0,24.71.0,31.78.0"}
P.entries["item:fine-crab-chunks"] = {n="Chair de crabe raffinée",s="Sur la côte de Sombrivage, les Reef Crawlers et les Encrusted Tide Crawlers fournissent de la Chair de crabe raffinée. Gubber Blump en a besoin pour ses recettes.",h="Sur la côte de Sombrivage, les Reef Crawlers et les Encrusted Tide Crawlers fournissent de la Chair de crabe...",kw={"auberdine","crabe","sombrivage","encrusted tide crawler","chair de crabe raffinée","fruit of the sea","gubber blump","reef crawler"},ang={["faction:Alliance"]="Approvisionner les habitants des quais d’Auberdine contribue à soutenir l’avant-poste de l’Alliance à Sombrivage.",["profession:Cooking"]="Gubber Blump connaît de nombreuses façons de cuisiner le crabe, des soupes et salades aux marinades épicées et au crabe surprise de Forgefer."},sec={{t="Fruit de la mer",b="Les Reef Crawlers et les Encrusted Tide Crawlers parcourent les rivages de Sombrivage. Près de l’eau, les voyageurs peuvent les trouver nuisibles ou dangereux, tandis que les cuisiniers apprécient leur chair. Ces morceaux peuvent être bouillis, grillés, frits ou incorporés à des ragoûts."}},faq={{q="Quelles créatures fournissent de la Chair de crabe raffinée ?",a="Les Reef Crawlers et les Encrusted Tide Crawlers qui longent les plages rocheuses et les bas-fonds de Sombrivage fournissent de la Chair de crabe raffinée.",al={"où trouver de la chair de crabe raffinée","quels crabes donnent des morceaux","source de chair de crabe"}},{q="Qui veut de la Chair de crabe raffinée à Sombrivage ?",a="Gubber Blump, un pêcheur installé sur les quais d’Auberdine, cherche de la Chair de crabe raffinée pour ses plats de crabe.",al={"qui a besoin de chair de crabe raffinée","qui remet les morceaux de crabe","gubber blump et le crabe"}},{q="Peut-on préparer ces morceaux en véritables repas ?",a="Gubber Blump rassemble ces morceaux crus au lieu de les utiliser directement dans une recette. La chair de crabe peut être cuite au four, au barbecue, bouillie, grillée, frite ou incorporée à des salades et des ragoûts.",al={"peut-on cuisiner la chair de crabe raffinée","que préparer avec de la chair de crabe raffinée","recettes de crabe"}}},fx={a1097ca6={q="Qu'est-ce que la Chair de crabe raffinée ?",a="La Chair de crabe raffinée est constituée de morceaux de viande de premier choix découpés dans les crabes robustes le long de la côte enveloppée de brume de Sombrivage. Prisés pour leur tendreté et leur polyvalence, ils sont considérés par les amateurs locaux comme le véritable Fruit of the Sea, convenant à presque toutes les préparations imaginables.",al={"qu'est-ce que la chair de crabe raffinée","histoire de la chair de crabe raffinée"}},["09afcf23"]={q="D'où vient la Chair de crabe raffinée ?",a="Ces morceaux de choix sont récoltés directement sur les crustacés sauvages qui rôdent le long de la côte de Sombrivage, en particulier les Reef Crawlers et les Encrusted Tide Crawlers. Ils ne sont pas fabriqués par des mains mortelles, mais découpés frais à partir des créatures qui prospèrent dans les eaux froides.",al={"d'où vient la chair de crabe raffinée","source de la chair de crabe raffinée","origine de la chair de crabe raffinée"}},["1943045a"]={q="Pourquoi Gubber Blump veut-il la Chair de crabe raffinée ?",a="Gubber Blump, un pêcheur excentrique posté sur les quais d'Auberdine, est totalement obsédé par la chair de crabe. Coincé avec sa canne à pêche, il compte sur les voyageurs pour rassembler des morceaux frais afin de pouvoir préparer une gamme infinie de recettes à base de crabe, des plats cuits au four et grillés aux salades et ragoûts de crabe.",al={"pourquoi gubber veut-il la chair de crabe","qui veut la chair de crabe raffinée","pourquoi récolter la chair de crabe raffinée"}}},fp="16,131,16.217.0,38.116.0,40.91.0,40.174.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="Belle peau de traquelune",s="Dans le sud de Sombrivage, Terenthis cherche des peaux de traquelunes adultes. Leur pelage épais et sain peut servir à confectionner une cape enchantée pour ceux qui recherchent Volcor.",h="Dans le sud de Sombrivage, Terenthis cherche des peaux de traquelunes adultes.",kw={"auberdine","sombrivage","belle peau de traquelune","matriarche","traquelune","sire","terenthis","volcor","la sinueuse"},ang={["class:Hunter"]="En tant que chasseur, suivre les sires et matriarches près de La Sinueuse met votre talent à l’épreuve face à certains des prédateurs les plus féroces du littoral de Kalimdor.",["race:NightElf"]="En tant qu’elfe de la nuit, vous respectez la férocité sacrée des traquelunes. On ne prend leur peau qu’en cas d’extrême nécessité, pour aider les proches tombés au combat, comme Volcor."},sec={{t="Les peaux des meneurs de meute",b="Les sires et matriarches traquelunes ont un pelage assez dense et sain pour fournir une belle peau. Ils défendent leur territoire le long de La Sinueuse et plus au sud, vers les frontières d’Orneval. Là, ils chassent avec patience. Les traquelunes ordinaires parcourent les forêts de Sombrivage, mais leur peau est de qualité insuffisante."},{t="Une cape de dissimulation",b="Terenthis d'Auberdine a besoin de cinq peaux intactes pour confectionner une cape destinée aux voyageurs à la recherche de l’elfe de la nuit disparu Volcor. La magie de la nature lie les peaux en une illusion qui atténue la présence du porteur auprès de la faune de Sombrivage. La cape n’agit que tant que son porteur évite les actes agressifs."}},faq={{q="Quelles créatures fournissent une Belle peau de traquelune ?",a="Les sires et matriarches traquelunes fournissent des Belles peaux de traquelune. Les traquelunes ordinaires et les plus jeunes n’ont pas une peau d’assez bonne qualité.",al={"créatures qui donnent une belle peau de traquelune","où trouver des peaux de traquelune","quels félins ont des peaux"}},{q="Où trouve-t-on les traquelunes adultes ?",a="Les traquelunes adultes vivent dans le sud de Sombrivage, en particulier le long de La Sinueuse et plus au sud, vers Orneval.",al={"où trouver les sires et matriarches","emplacement des sires traquelunes","emplacement des matriarches traquelunes"}},{q="Pourquoi Terenthis a-t-il besoin de ces peaux ?",a="Terenthis a besoin de cinq peaux pour confectionner une cape enchantée destinée aux voyageurs à la recherche de l’elfe de la nuit disparu Volcor. Sa magie dissimule le porteur aux bêtes prédatrices.",al={"à quoi servent les peaux","pourquoi ramasser des peaux de traquelune","quête des peaux de terenthis"}},{q="La cape vous rend-elle complètement invisible ?",a="La cape ne vous rend pas complètement invisible. Son illusion naturelle dissuade les bêtes, mais toute action autre que parler à autrui peut briser l’enchantement et dissiper le déguisement.",al={"fonctionnement de la cape","limites de l’illusion de la cape","action qui brise la dissimulation de la cape"}}},fx={["399f6830"]={q="Qu'est-ce qu'une Belle peau de traquelune ?",a="Une Belle peau de traquelune est la peau de premier choix récoltée sur les pères et mères traquelunes matures qui errent dans les étendues sauvages de Sombrivage. Ces redoutables chats sabres de nuit possèdent une fourrure épaisse et souple capable de retenir de délicats enchantements naturels, ce qui rend leurs peaux bien plus prisées et durables que le pelage des spécimens plus jeunes.",al={"belle peau de traquelune","qu'est-ce que la peau de traquelune","belle peau"}},e53e751f={q="D'où vient une Belle peau de traquelune ?",a="Ces peaux proviennent naturellement des plus grands traquelunes adultes qui rôdent sur les côtes et dans les forêts de Sombrivage, en particulier près de la Sinueuse et plus au sud vers la frontière de l'Orneval. Seuls les pères et mères traquelunes adultes ont des peaux suffisamment épaisses et saines pour être considérées comme de belles peaux.",al={"où obtenir la belle peau de traquelune","source de la peau de traquelune","qui donne la belle peau de traquelune"}}},fp="21,164,25.300.0,20.277.1,45.128.0,43.119.0,36.164.0,54.174.0"}
P.entries["item:fire-tar"] = {n="Goudron de feu",s="Dans l’est des Tarides, les lanceurs de sorts Hrufes du clan Tranchecrinière portent du Goudron de feu. Les chamans de la Horde l’apportent à Telf Joolam, qui le prépare en Sapta de feu pour leur permettre de communier avec les esprits du feu.",h="Dans l’est des Tarides, les lanceurs de sorts Hrufes du clan Tranchecrinière portent du Goudron de feu.",kw={"call of fire","sapta de feu","goudron de feu","hommes-cochons","tranchecrinière","totem de chaman","telf joolam","les tarides"},ang={["class:Shaman"]="En tant que chaman, vous devez récolter du Goudron de feu pour accomplir un rite de passage essentiel. Vous cherchez la résonance élémentaire dans le vaste monde, puis vous l’utilisez pour préparer la Sapta de feu et gagner votre Totem de feu.",["faction:Horde"]="En tant que membre de la Horde, vous traversez le Fleuve Furie-du-Sud depuis Durotar pour rejoindre les Tarides et récolter du Goudron de feu. Là, vous affrontez les tribus agressives des Tranchecrinière."},sec={{t="Une concoction des Hrufes",b="Les géomanciens, mystiques et tisse-épines Hrufes du clan Tranchecrinière portent du Goudron de feu. Les hommes-cochons l’utilisent dans leurs rituels et leur magie cruelle, où son pouvoir est accordé aux flammes. Les instructeurs chamans prisent cette substance comme réactif terrestre. Elle aide les sens des mortels à atteindre la fureur brute des éléments."},{t="La voie du Totem de feu",b="De jeunes chamans orcs et trolls se rendent dans les hauteurs escarpées de Durotar auprès de Telf Joolam, où ils forgent leurs totems de feu. Telf leur demande d’apporter une Bourse de réactifs prise aux cultistes de la Lame ardente et du Goudron de feu récolté chez les Tranchecrinière. Il prépare les deux ingrédients en Sapta de feu. Un chaman qui la boit peut percevoir les esprits du feu qui attendent au sommet des pics voisins."}},faq={{q="À quoi sert le Goudron de feu ?",a="Les chamans apportent du Goudron de feu à Telf Joolam, à Durotar. Il le prépare avec des réactifs provenant de la Lame ardente pour en faire une Sapta de feu. Cette décoction permet au chaman de voir les esprits du feu et de communier avec eux afin de gagner un Totem de feu.",al={"utilisation du goudron de feu","effet du goudron de feu","pourquoi le goudron de feu est nécessaire"}},{q="Qui porte du Goudron de feu ?",a="Les hommes-cochons lanceurs de sorts Hrufes portent du Goudron de feu dans l’est des Tarides. On compte parmi eux les géomanciens, les mystiques, les tisse-épines et les Water Seekers du clan Tranchecrinière.",al={"qui lâche du goudron de feu","créatures qui portent du goudron de feu","où trouver du goudron de feu"}},{q="Pourquoi les chamans ont-ils besoin d’ingrédients liés à des lanceurs de sorts hostiles ?",a="Les saptas ont besoin de composants physiques imprégnés de l’élément correspondant. Les lanceurs de sorts Hrufes et les démonistes de la Lame ardente canalisent la chaleur et les flammes destructrices. Leurs matériaux courants renferment l’essence ardente nécessaire pour éveiller la vision élémentaire d’un chaman.",al={"pourquoi le goudron des hommes-cochons","pourquoi les démonistes et les hommes-cochons"}},{q="Où Telf Joolam prépare-t-il la Sapta de feu ?",a="Telf Joolam prépare la Sapta de feu sur une haute falaise qui surplombe les escarpements de Durotar. La falaise se trouve près du chemin entre Tranchecolline et les Tarides. Il apprend aux novices à équilibrer la nature destructrice et créatrice des flammes.",al={"où se trouve telf joolam","remettre le goudron de feu"}}},fx={["1e4fc5f4"]={q="Qu'est-ce que le Goudron de feu ?",a="Le Goudron de feu est une substance élémentaire volatile transportée par les lanceurs de sorts parmi les Razormane quilboar dans les Tarides. Imprégné de l'essence fondamentale du feu, ce brai âcre est prisé par les praticiens de la magie élémentaire pour son affinité naturelle avec la flamme.",al={"qu'est-ce que le goudron de feu","infos sur le goudron de feu","décrire le goudron de feu"}},["006bd002"]={q="D'où vient le Goudron de feu, et qui le fabrique ?",a="Le Goudron de feu est collecté auprès des lanceurs de sorts Razormane quilboar habitant l'est des Tarides, y compris leurs géomanciens, mystiques et tisse-épines. Telf Joolam demande aux initiés de l'apporter comme composant pour son sapta de feu.",al={"qui fabrique le goudron de feu","origine du goudron de feu","d'où vient le goudron de feu"}}},fp="8,178,29.274.0,26.361.0,26.196.0,21.147.0,61.243.0,43.215.0"}
P.entries["item:firebeard-s-head"] = {n="Firebeard's Head",s="Firebeard’s Head est la preuve exigée par le mandat d’Andre Firebeard au Port Gentepression. La loi du port autorise sa tête à le remplacer au procès.",h="Firebeard’s Head est la preuve exigée par le mandat d’Andre Firebeard au Port Gentepression.",kw={"andre firebeard","tête de firebeard","gadgetzan","pirate","chef de la sécurité bilgewhizzle","port gentepression","tanaris","recherché"},sec={{t="Un mandat contraignant",b="Le Chef de la sécurité Bilgewhizzle accepte la tête d’Andre Firebeard comme substitut pour son audience. Le mandat désigne le pirate pour des crimes contre Steamwheedle et Gadgetzan. Une fois la tête remise au port, Bilgewhizzle considère le contrat comme rempli et vous offre une récompense pour vos services."}},faq={{q="Pourquoi le mandat réclame-t-il sa tête ?",a="Le mandat indique que la tête d’Andre Firebeard peut le remplacer s’il est mort ou incapable de se présenter à son audience. Le Chef de la sécurité Bilgewhizzle l’accepte au Port Gentepression.",al={"mandat pour la tête d’andre","pourquoi sa tête","tête de firebeard"}},{q="Qui est Andre Firebeard ?",a="Andre Firebeard est un pirate recherché pour des crimes contre Steamwheedle et Gadgetzan.",al={"andre firebeard","pirate firebeard","qui est andre"}},{q="Qui prend la tête de Firebeard ?",a="Le Chef de la sécurité Bilgewhizzle prend la tête d’Andre Firebeard au Port Gentepression.",al={"qui veut la tête","tête bilgewhizzle","où apporter la tête d’andre"}},{q="Où se trouve le Port Gentepression ?",a="Le Port Gentepression se trouve sur la côte de Tanaris. Le mandat d’Andre Firebeard y est affiché.",al={"emplacement de steamwheedle","port de tanaris","où se trouve le port"}}},fp="16,157,17.284.0,38.172.0,23.81.0,29.80.0,27.92.0"}
P.entries["item:fizzle-s-claw"] = {n="Griffe de Féplouf",s="Dans les Falaises du Tonnerre, la griffe de Fizzle Darkstorm est rapportée à Tranchecolline pour prouver sa mort. Ce démoniste gobelin menaçait la patrie orque sous la bannière de la Lame ardente.",h="Dans les Falaises du Tonnerre, la griffe de Fizzle Darkstorm est rapportée à Tranchecolline pour prouver sa...",kw={"lame ardente","dark storms","durotar","fizzle darkstorm","griffe de féplouf","orgnil marque-l'âme","tranchecolline","falaises du tonnerre"},ang={["class:Warlock"]="En tant que démoniste, vous savez que Fizzle Darkstorm pratiquait les arts gangrenés au service de la Lame ardente. Il a retourné ses talents contre la Horde.",["faction:Horde"]="En tant que membre de la Horde, vous pouvez présenter la griffe de Fizzle à Tranchecolline. Elle contribue à purger Durotar des sectes de l'ombre qui menacent la sécurité de la jeune nation."},sec={{t="Un sinistre trophée",b="Orgnil Marque-l'âme a envoyé des troupes pour débusquer les sectes de l'ombre qui menacent la patrie orque. Il a désigné Fizzle Darkstorm comme instigateur de la corruption dans les Falaises du Tonnerre. Fizzle servait la Lame ardente en tant que démoniste. Sa griffe prouve désormais aux commandants de la Horde qu'il a été tué."},{t="La menace des Falaises du Tonnerre",b="Les Falaises du Tonnerre se trouvent juste au nord-ouest de Tranchecolline, assez près pour menacer les terres environnantes. Des éclaireurs de la Horde ont rapporté la griffe de Fizzle à Tranchecolline. Elle confirme que ses rituels et sa tentative d'établir une présence de la Lame ardente ont été stoppés."}},faq={{q="À qui appartient cette griffe ?",a="La griffe appartenait à Fizzle Darkstorm, un démoniste gobelin affilié à la Lame ardente.",al={"qui est fizzle","fizzle darkstorm","propriétaire de la griffe"}},{q="Pourquoi Orgnil Marque-l'âme veut-il la Griffe de Féplouf ?",a="Orgnil Marque-l'âme veut une preuve de la mort de Fizzle. La Lame ardente agit dans l'ombre, et la griffe confirme que cette menace pour Durotar a été éliminée.",al={"pourquoi vouloir la griffe","griffe orgnil marque-l'âme","preuve de mort"}},{q="Où la griffe a-t-elle été trouvée ?",a="La griffe de Fizzle Darkstorm a été prise dans son camp des Falaises du Tonnerre, au nord-ouest de Tranchecolline, en Durotar.",al={"lieu où se trouve fizzle","où est fizzle","griffe des falaises du tonnerre"}},{q="Que fait la Lame ardente en Durotar ?",a="La Lame ardente cherche à saper la nouvelle patrie orque par la corruption démoniaque, la sorcellerie noire et les troubles civils. Des démonistes comme Fizzle établissent des camps cachés pour semer le chaos dans la région.",al={"lame ardente durotar","pourquoi des sectateurs aux falaises du tonnerre"}}},fx={["0fb0af8e"]={q="Qu'est-ce que la Griffe de Féplouf ?",a="La Griffe de Féplouf est la main coupée de Fizzle Darkstorm, un démoniste gobelin traître allié au culte de la Lame ardente. Elle sert de preuve physique macabre de son décès pour Orgnil Marque-l'âme à Tranchecolline, confirmant que le chef du culte qui causait des problèmes dans les Falaises du Tonnerre a été éliminé de façon permanente.",al={"qu'est-ce que la griffe de féplouf","objet griffe de féplouf","identité de la griffe de féplouf"}}},fp="13,177,13.277.0,27.251.0,29.90.0,44.151.0,25.101.0,43.199.0"}
P.entries["item:flagongut-s-fossil"] = {n="Fossile d'Outrepanse",s="Sur le site de fouilles des Paluns, Outrepanse cherche des réponses dans un ancien fossile. L’Explorers' League conserve le spécimen. Outrepanse pense que la Pierre de Relu peut l’aider à en percer les secrets.",h="Sur le site de fouilles des Paluns, Outrepanse cherche des réponses dans un ancien fossile.",kw={"fouilles","explorers' league","outrepanse","fossile","relu","pierre de relu","les paluns","whelgar"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez aider à protéger les artéfacts du site de fouilles en ruine de Whelgar, avant que les bêtes sauvages ne les détruisent ou que des forces hostiles ne les récupèrent dans le marécage.",["race:Dwarf"]="En tant que nain, vous pouvez voir dans les fossiles comme celui d’Outrepanse des liens avec le passé ancien. L’Explorers' League se consacre à leur découverte."},sec={{t="Fouilles et étude",b="Le Prospecteur Whelgar conserve le fossile sur son site de fouilles, dans les collines méridionales des Paluns. Des expéditions naines à travers Khaz Modan l’ont mis au jour. L’Archéologue Outrepanse pense que cette pierre ancienne recèle des pouvoirs oubliés et voit un lien avec des artéfacts découverts de l’autre côté de la mer, à Sombrivage."},{t="Percer le secret de la relique",b="Outrepanse a trouvé la Pierre de Relu et compris qu’elle pourrait l’aider à déchiffrer le fossile. Des raptors tachetés l’ont pris en embuscade sur la route, et la pierre a été perdue. Il lui faut maintenant le fossile des Excavations de Whelgar et la pierre, à retrouver auprès de la faune des Paluns, pour percer les secrets du spécimen."}},faq={{q="Qu’est-ce que le Fossile d’Outrepanse ?",a="Le Fossile d’Outrepanse est un ancien spécimen récupéré dans les Paluns. L’Explorers' League naine le conserve pour étudier le passé ancien du monde.",al={"qu’est-ce que le fossile","histoire du fossile d’outrepanse"}},{q="Où se trouve le fossile ?",a="Le fossile se trouve dans une grotte, au sommet des Excavations de Whelgar, dans les montagnes méridionales des Paluns. Des raptors tachetés qui ont envahi le site le gardent.",al={"emplacement du fossile","où se trouve le fossile d’outrepanse","grotte du fossile de whelgar"}},{q="Pourquoi faut-il le rapporter à Outrepanse ?",a="Outrepanse pense que la Pierre de Relu peut l’aider à déchiffrer les secrets magiques cachés dans le fossile. Il veut aussi le comparer à des découvertes similaires faites au Kalimdor.",al={"pourquoi outrepanse le veut","que fera outrepanse du fossile"}},{q="Quel est le lien avec Sombrivage ?",a="Outrepanse voit un parallèle entre le spécimen des Paluns et le fossile que le Prospecteur Songerrance a trouvé à Sombrivage. Il pense que la Pierre de Relu pourrait révéler le pouvoir des deux reliques.",al={"lien avec sombrivage","fossile de songerrance"}}},fp="18,180,20.293.0,19.257.1,27.144.0,28.155.0,36.158.0,33.180.0"}
P.entries["item:flatland-cougar-femur"] = {n="Fémur de puma des basses plaines",s="Dans tout Mulgore, les pumas des basses plaines traquent les plaines, et Maur Mande-pluie a besoin de l’un de leurs os. Un Fémur de puma des basses plaines entre dans la composition du remède qu’il cherche contre une morsure venimeuse.",h="Dans tout Mulgore, les pumas des basses plaines traquent les plaines, et Maur Mande-pluie a besoin de l’un de...",kw={"sabot-de-sang","fémur","puma des basses plaines","maur mande-pluie","mazzranache","mulgore"},ang={["class:Hunter"]="En tant que chasseur, vous devez avoir l’œil pour suivre les pumas des basses plaines dans les broussailles ondoyantes de Mulgore. Cette chasse met à l’épreuve votre talent pour abattre proprement un autre prédateur.",["race:Tauren"]="Pour les taurens de Mulgore, la chasse aux pumas des basses plaines met votre vigilance à l’épreuve et fournit des ingrédients essentiels aux remèdes traditionnels des plaines."},sec={{t="Un remède contre une morsure venimeuse",b="Les pumas des basses plaines comptent parmi les chasseurs les plus dangereux de Mulgore. Ils disparaissent dans les broussailles sèches, puis bondissent sur leurs proies. Les chasseurs utilisent leurs peaux et leurs griffes pour le travail du cuir et les trophées. Leurs os massifs servent aussi en médecine locale.\n\nMaur Mande-pluie, de Sabot-de-Sang, porte une blessure venimeuse infligée par Mazzranache, un trotteur rose monstrueux. Il lui faut d’urgence un fémur de puma et des morceaux d’autres bêtes locales. Broyé ou bouilli, l’os fournit ce qu’il faut pour préparer un cataplasme antitoxique qui extrait la fièvre et le venin nécrotique de la morsure purulente."}},faq={{q="À quoi sert le Fémur de puma des basses plaines ?",a="Maur Mande-pluie, à Sabot-de-Sang, a besoin du fémur pour préparer un remède d’urgence. Mazzranache, le célèbre trotteur des plaines, l’a mordu. Il lui faut l’os et la moelle pour préparer un antitoxique avant que son venin virulent ne le tue.",al={"utilité du fémur de puma","à quoi sert cet os","quête du fémur"}},{q="Où trouver un Fémur de puma des basses plaines ?",a="Vous trouverez des Fémurs de puma des basses plaines sur les pumas qui parcourent les plaines centrales et méridionales de Mulgore. Ils rôdent près des collines et dans les hautes herbes autour de Sabot-de-Sang.",al={"où trouver le fémur","emplacement du fémur de puma","quels monstres le donnent"}},{q="Pourquoi Maur Mande-pluie a-t-il besoin précisément d’un os de puma ?",a="Les herboristes et les chamans taurens utilisent les os denses et la moelle des prédateurs dans leurs onguents et leurs teintures traditionnels. Selon eux, les prédateurs les plus puissants de Mulgore fournissent la base réparatrice nécessaire pour neutraliser les toxines les plus virulentes.",al={"pourquoi un os de puma","pourquoi un fémur"}},{q="Qui est Maur Mande-pluie ?",a="Maur Mande-pluie vit à Sabot-de-Sang. Après avoir erré dans les plaines, il a croisé Mazzranache, un trotteur légendaire que son grand-père avait autrefois combattu. Maur a échappé de justesse à une morsure infectée et venimeuse à l’épaule.",al={"maur mande-pluie","qui a besoin de l’os"}}},fx={cc87b9fc={q="Qu'est-ce qu'un Fémur de puma des basses plaines ?",a="Il s'agit d'un os de patte robuste récolté sur les pumas des basses plaines prédateurs qui errent dans les plaines de Mulgore. Denses et résistants, ces os sont souvent recherchés par les guérisseurs et chamans tribaux pour préparer des onguents, cataplasmes et remèdes médicinaux traditionnels.",al={"qu'est-ce que le fémur de puma des basses plaines","objet fémur de puma des basses plaines","qu'est-ce que le fémur de puma"}},["47eeaceb"]={q="D'où vient un Fémur de puma des basses plaines ?",a="Il est obtenu directement auprès des pumas des basses plaines, les prédateurs maigres originaires des prairies de Mulgore. Contrairement aux outils fabriqués ou aux potions brassées, il s'agit d'un trophée naturel brut récolté par les chasseurs qui traquent les bêtes sauvages à travers les plaines vallonnées.",al={"origine du fémur de puma des basses plaines","où obtenir le fémur de puma des basses plaines","qui donne le fémur de puma"}}},fp="21,172,28.545.0,43.216.0,44.178.0,58.226.0,23.224.0"}
P.entries["item:flatland-prowler-claw"] = {n="Griffe de Rôdeur des basses plaines",s="Dans les plaines de Mulgore, les jeunes chasseurs rapportent des Griffes de Rôdeur des basses plaines pour prouver leur détermination et leur savoir-faire aux anciens de Pitons-du-Tonnerre.",h="Dans les plaines de Mulgore, les jeunes chasseurs rapportent des Griffes de Rôdeur des basses plaines pour...",kw={"rôdeur des basses plaines","griffe de rôdeur des basses plaines","cime des chasseurs","melor sabot-de-pierre","mulgore","skorn nuage-blanc","la voie du chasseur","pitons-du-tonnerre"},ang={["class:Hunter"]="En tant que chasseur, vous éprouvez votre vigilance face aux rôdeurs furtifs. Leurs griffes témoignent du respect gagné auprès des tireurs de la Cime des chasseurs, à Pitons-du-Tonnerre.",["race:Tauren"]="En tant que Tauren, vous honorez la chasse comme une tradition spirituelle. Présenter les griffes d’un prédateur rusé des plaines marque vos premiers pas vers le service de votre tribu comme pisteur."},sec={{t="Une preuve de chasseur",b="Les rôdeurs des basses plaines chassent dans les plaines de Mulgore et bondissent sur leurs proies depuis les hautes herbes. Rusés et farouchement attachés à leur territoire, ils représentent un danger pour les voyageurs. Pour les jeunes chasseurs, les traquer est une rude épreuve.\n\nRécolter leurs griffes est une tradition reconnue. Skorn Nuage-blanc envoie les nomades prometteurs rapporter les griffes à Melor Sabot-de-pierre, à la Cime des chasseurs de Pitons-du-Tonnerre. Elles prouvent leur détermination et leur savoir-faire sur le terrain tandis qu’ils suivent la voie du chasseur."}},faq={{q="À quoi servent les Griffes de Rôdeur des basses plaines ?",a="Les jeunes chasseurs apportent quatre Griffes de Rôdeur des basses plaines à Melor Sabot-de-pierre, à la Cime des chasseurs de Pitons-du-Tonnerre. Ces griffes prouvent leur habileté et leur courage, ainsi que leur aptitude à suivre la voie du chasseur.",al={"utilité des griffes de rôdeur","pourquoi récolter des griffes de rôdeur","griffes de la voie du chasseur"}},{q="Qui vous demande de les récolter ?",a="Skorn Nuage-blanc demande aux pisteurs prometteurs de récolter les griffes des rôdeurs de Mulgore avant de se présenter à Melor Sabot-de-pierre.",al={"qui veut les griffes de rôdeur","donneur de quête des griffes de rôdeur"}},{q="Pourquoi les rôdeurs des basses plaines sont-ils des proies de choix ?",a="Les rôdeurs des basses plaines sont des carnivores robustes et furtifs, originaires des plaines de Mulgore. Traquer et vaincre ces prédateurs vigilants met à l’épreuve la patience et l’instinct de combat qu’exige la tradition taurène d’un chasseur.",al={"pourquoi chasser les rôdeurs des basses plaines","les rôdeurs sont-ils dangereux"}}},fx={cc11ac90={q="Qu'est-ce qu'une Griffe de Rôdeur des basses plaines ?",a="Il s'agit d'une griffe récoltée sur un Rôdeur des basses plaines, l'un des chats sauvages prédateurs qui errent dans les plaines herbeuses de Mulgore. Parmi les chasseurs taurens, présenter ces griffes sert de preuve tangible de la ruse, de la patience et des compétences de pistage émergentes d'un jeune chasseur.",al={"griffe de rôdeur des basses plaines","qu'est-ce que la griffe de rôdeur"}},a7640831={q="D'où viennent les Griffe de Rôdeur des basses plaines ?",a="Ces griffes proviennent directement des Rôdeurs des basses plaines prédateurs qui rôdent dans les prairies balayées par le vent de Mulgore. Plutôt que d'être fabriquées ou manufacturées, elles doivent être proprement récoltées par un chasseur après avoir traqué et vaincu les bêtes agiles dans la nature.",al={"où obtenir les griffes de rôdeur","comment obtenir les griffes de rôdeur"}},b4c8d82b={q="Pourquoi quelqu'un voudrait-il des Griffe de Rôdeur des basses plaines ?",a="Skorn Nuage-blanc demande aux aspirants voyageurs de rassembler ces griffes pour prouver leur valeur à Melor Sabot-de-pierre au sommet de la halte des Chasseurs aux Pitons-du-Tonnerre. La chasse est l'un des plus grands honneurs de la culture tauren, et offrir les griffes de tels prédateurs robustes et rusés démontre que vous possédez les compétences et l'esprit naissants requis pour suivre The Hunter's Path.",al={"pourquoi récolter les griffes de rôdeur","qui a besoin de griffes de rôdeur","pourquoi melor sabot-de-pierre veut-il les griffes"}}},fp="21,138,16.457.0,41.189.0,29.129.0,52.196.0"}
P.entries["item:foreman-s-blackjack"] = {n="Matraque du contremaître",s="Dans la Vallée des épreuves, la Matraque du contremaître maintient les péons de Durotar au travail. Les contremaîtres se servent de ce gourdin gainé de cuir pour réveiller les ouvriers qui s’endorment pendant les premiers travaux de construction de la Horde.",h="Dans la Vallée des épreuves, la Matraque du contremaître maintient les péons de Durotar au travail.",kw={"matraque","durotar","matraque du contremaître","péons paresseux","péon","thazz'ril","vallée des épreuves"},ang={["faction:Horde"]="La matraque rappelle le travail nécessaire pour dompter Durotar. Pour s’établir sur cette terre hostile, chaque ouvrier doit travailler sans relâche.",["race:Orc"]="Pour les jeunes Orcs qui entrent dans la Vallée des épreuves, manier la matraque constitue une première leçon sur la hiérarchie de la Horde. Ceux qui n’ont ni la force ni l’esprit d’un guerrier sont envoyés au travail et maintenus dans le rang par la force."},sec={{t="Un outil du labeur des Orcs",b="Durotar a besoin de réserves de bois pour bâtir le nouveau foyer de la Horde. Dans la Vallée des épreuves, les péons travaillent, et le Contremaître Thazz'ril maintient les équipes en mouvement avec la Matraque du contremaître. Son coup alourdi réveille les ouvriers qui somnolent à l’ombre des arbres de la vallée. Elle est conçue pour les réveiller, pas pour les tuer. Dans la nouvelle Horde, la vie de péon consiste à travailler dur, sans gloire, sous une poigne de fer."}},faq={{q="À quoi sert la Matraque du contremaître ?",a="Les contremaîtres confient la matraque aux jeunes aventuriers pour discipliner les péons endormis dans la Vallée des épreuves. Un coup réveille le péon assoupi, qui retourne couper et transporter du bois.",al={"utilisation de la matraque","pourquoi utiliser la matraque","gourdin de péon"}},{q="À qui appartient cette matraque ?",a="La Matraque du contremaître appartient au Contremaître Thazz'ril. Ce maître du labeur est posté dans la Vallée des épreuves, où il supervise la collecte de bois brut pour la jeune colonie orc.",al={"qui donne la matraque","propriétaire de la matraque du contremaître"}},{q="Pourquoi les péons s’endorment-ils au travail ?",a="Les péons orcs travaillent jusqu’à l’épuisement à ramasser du bois sous le soleil implacable de Durotar. Quand la fatigue les accable, ils font souvent la sieste sans permission sous les rares arbres de la vallée.",al={"pourquoi les péons sont paresseux","péons paresseux endormis"}},{q="Puis-je garder la Matraque du contremaître après avoir terminé la tâche ?",a="Non. Le contremaître exige qu’on lui rende l’outil dès que les tire-au-flanc ont été remis au travail. Il reste entre les mains des maîtres du labeur chargés de faire respecter les quotas.",al={"garder la matraque","puis-je garder la matraque du contremaître"}}},fx={["4e7ef009"]={q="Qu'est-ce que la Matraque du contremaître ?",a="La Matraque du contremaître est une lourde matraque enveloppée de cuir portée par le Contremaître Thazz'ril dans la Vallée des épreuves. C'est un outil de discipline sans fioritures, conçu non pas pour infliger des blessures graves en temps de guerre, mais pour asséner un coup sec et cinglant qui fait sursauter les travailleurs endormis pour les remettre sur pied.",al={"qu'est-ce que la matraque","objet matraque du contremaître","qu'est-ce que la matraque du contremaître"}},["9e33a4a7"]={q="Pourquoi le Contremaître Thazz'ril veut-il récupérer la matraque ?",a="Le Contremaître Thazz'ril compte sur la matraque pour gérer ses équipes de travail dans la Vallée des épreuves. Sans elle, il a peu de moyens de forcer les peons épuisés et démotivés à continuer de couper et de transporter du bois pour la Horde. Une fois que vous avez aidé à ramener les ouvriers à leurs tâches, il s'attend à ce que son outil essentiel lui soit rendu.",al={"pourquoi rendre la matraque","pourquoi thazz'ril a besoin de la matraque","pourquoi vouloir la matraque"}}},fp="19,184,22.379.0,41.186.0,24.173.0,48.178.0,50.137.0"}
P.entries["item:forged-steel-bars"] = {n="Barres d'acier forgé",s="Dans le nord des Tarides, les Barres d'acier forgé de Thun'grim Firegaze ont disparu. Les récupérer prouve qu'un guerrier est résolu à reprendre des biens volés.",h="Dans le nord des Tarides, les Barres d'acier forgé de Thun'grim Firegaze ont disparu.",kw={"tarides","forged steel","barres d'acier forgé","coffre en fer","razormane","coffre en fer volé","thun'grim firegaze"},ang={["class:Warrior"]="Récupérer l'acier volé de Thun'grim prouve qu'un guerrier sait retrouver des voleurs et affronter des bandes de quilboars dangereux. Thun'grim offre une arme sur mesure en échange.",["profession:Blacksmithing"]="Ces barres raffinées montrent la différence entre la ferraille grossière des tribus et l'acier de qualité forgé par les forgerons de la Horde."},sec={{t="Métal volé",b="Thun'grim Firegaze est un forgeron orc malvoyant qui possède un camp dans le nord des Tarides. Lors d'un raid nocturne, des quilboars Razormane lui ont pris son coffre en fer. Ils l'ont distrait avec des grognements et des ébrouements tandis que d'autres s'enfuyaient avec le coffre.\n\nLes quilboars ne savaient pas travailler l'acier fin. Ils ont donc laissé le coffre intact près d'un chariot en ruine dans leur campement au nord-ouest. Les barres sont toujours là, prêtes à être récupérées par des guerriers déterminés."}},faq={{q="À qui appartiennent ces Barres d'acier forgé ?",a="Les barres appartiennent à Thun'grim Firegaze, un armurier et fabricant d'armes orc qui vit dans un camp du nord des Tarides.",al={"à qui appartiennent les barres","acier de thun'grim","à qui est cet acier"}},{q="Pourquoi les quilboars les ont-ils volées ?",a="Les quilboars Razormane les ont volées en pillant les objets de valeur de Thun'grim. Sachant qu'il voyait mal, ils l'ont nargué et distrait pendant que d'autres emportaient son coffre en fer.",al={"pourquoi voler de l'acier","motif des quilboars","vol des razormane"}},{q="Les quilboars ont-ils utilisé l'acier ?",a="Non. Les Razormanes n'avaient pas le savoir-faire nécessaire pour travailler un acier aussi finement raffiné. Ils ont laissé le coffre fermé près d'un chariot brisé dans leur campement.",al={"les quilboars ont-ils forgé quelque chose","qu'ont fait les quilboars de l'acier"}},{q="Que proposera Thun'grim en échange ?",a="Thun'grim offre une arme forgée aux guerriers en herbe qui bravent les campements quilboars et rapportent toutes les barres.",al={"récompense pour l'acier forgé","qu'est-ce que je reçois pour l'acier"}}},fx={["4e666297"]={q="Que sont les Barres d'acier forgé ?",a="Ces barres sont une réserve de métal raffiné de haute qualité appartenant au forgeron Thun'grim Firegaze. Conservées en lieu sûr dans un coffre en fer à son camp, elles représentent des matériaux de choix destinés à forger des armes robustes. Bien qu'elles soient brutes et non façonnées en armes finies, leur qualité de fabrication surpasse de loin les débris grossiers habituels des Tarides.",al={"que sont les barres d'acier forgé","infos barres d'acier forgé","barres d'acier volées"}}},fp="17,144,12.419.0,33.114.0,32.173.0,31.136.0,45.110.0"}
P.entries["item:forked-mudrock-tongue"] = {n="Forked Mudrock Tongue",s="Les Forked Mudrock Tongues proviennent des tortues Mudrock qui vivent sur la côte du Marécage d’Âprefange. Morgan Stern les veut pour une nouvelle soupe qu’il espère servir à Hurlevent.",h="Les Forked Mudrock Tongues proviennent des tortues Mudrock qui vivent sur la côte du Marécage d’Âprefange.",kw={"blue recluse","marécage d’âprefange","forked mudrock tongue","morgan stern","mudrock soup and bugs","langue mudrock","tortue mudrock","theramore"},ang={["profession:Cooking"]="En tant que cuisinier, vous vous demandez peut-être quelle saveur Morgan espère tirer de ces langues. Il teste des techniques pour en faire ressortir le goût particulier dans son Mudrock Soup and Bugs."},sec={{t="La requête d’un cuisinier",b="Morgan Stern recherche des Forked Mudrock Tongues à Theramore. Il pense qu’elles ont une saveur particulière et veut les essayer dans son Mudrock Soup and Bugs. Les tortues vivent sur la côte, surtout autour de la baie."}},faq={{q="D’où viennent les Forked Mudrock Tongues ?",a="Elles proviennent des tortues Mudrock qui vivent sur la côte du Marécage d’Âprefange, surtout autour de la baie.",al={"origine des langues mudrock","où trouver des langues","où trouver des langues fourchues"}},{q="Pourquoi Morgan Stern les veut-il ?",a="Morgan Stern veut tester leur saveur particulière dans son Mudrock Soup and Bugs.",al={"pourquoi morgan veut des langues","recette de morgan","soupe et insectes"}},{q="Qui est Morgan Stern ?",a="Morgan Stern est un cuisinier de Theramore qui travaille sur un plat appelé Mudrock Soup and Bugs.",al={"qui est morgan stern","qui est morgan","cuisinier de theramore"}},{q="Où Morgan espère-t-il servir ce plat ?",a="Morgan espère servir le Mudrock Soup and Bugs au Blue Recluse, à Hurlevent.",al={"où servir la soupe","plat du blue recluse","restaurant de hurlevent"}}},fp="21,156,18.209.0,42.90.0,32.78.0,20.83.0,41.77.0"}
P.entries["item:fragments-of-rok-alim"] = {n="Fragments de Rok'Alim",s="Dans Mille pointes, les fragments de pierre de Rok'Alim témoignent de la victoire d'un guerrier. Dorn Traqueur-des-plaines, à La niche érodée, les veut comme preuve que Rok'Alim est tombé en combat singulier.",h="Dans Mille pointes, les fragments de pierre de Rok'Alim témoignent de la victoire d'un guerrier.",kw={"dorn traqueur-des-plaines","élémentaire","fragments","pilonneur","rok'alim","test of strength","mille pointes","la niche érodée"},ang={["class:Shaman"]="En tant que chaman, vous pouvez étudier l'inflexibilité de Rok'Alim, qui illustre la ténacité des élémentaires. C'est un ancien esprit de la terre, lié au monde avant les pactes chamaniques modernes.",["race:Tauren"]="En tant que tauren, affronter les plus grands dangers du pays met à l'épreuve votre harmonie, votre endurance et votre force face aux vestiges du passé primordial d'Azeroth."},sec={{t="Vestiges d'un pouvoir ancien",b="Rok'Alim le Pilonneur arpente toujours les plaines du canyon, au sud de la voie principale. La plupart des élémentaires disparurent d'Azeroth après le bannissement des Dieux très anciens, mais quelques-uns, puissants, survécurent sans être invoqués par des mortels. Les centaures des environs reconnaissent Rok'Alim au fracas de ses poings de pierre, qui écrasent tout sur leur passage. Sa défaite laisse des morceaux déchiquetés de roche dense et animée, preuve de la puissance d'un guerrier."},{t="L'épreuve de la force",b="Dorn Traqueur-des-plaines a besoin des fragments pour le Test of Strength. L'ermite tauren accorde une grande importance aux rites spirituels et martiaux de La niche érodée. L'initié doit affronter un être à la force brute implacable. Rapporter à Dorn les morceaux meurtris de Rok'Alim prouve le courage et la puissance nécessaires pour survivre aux pires périls de Kalimdor."}},faq={{q="Que sont les Fragments de Rok'Alim ?",a="Les Fragments de Rok'Alim sont des morceaux brisés de Rok'Alim le Pilonneur, un ancien élémentaire de terre qui rôde dans les canyons du nord-ouest de Mille pointes. Ils prouvent qu'il a été vaincu.",al={"fragments de rokalim","que sont les fragments de rokalim","pierre de rokalim"}},{q="Qui veut ces fragments de pierre ?",a="Dorn Traqueur-des-plaines veut ces fragments de pierre pour le Test of Strength. L'ermite tauren vit à La niche érodée, en haut des falaises du canyon de Mille pointes.",al={"qui prend les fragments de rokalim","rendre les fragments de rokalim","quête de dorn traqueur-des-plaines"}},{q="Pourquoi Rok'Alim est-il important ?",a="Rok'Alim a survécu depuis l'époque des Dieux très anciens, alors que la plupart des élémentaires disparurent après leur bannissement, à moins d'être invoqués par des mortels. Les tribus centaures des canyons le connaissent sous le nom de Pilonneur, à cause du fracas de ses poings qui écrasent ses proies.",al={"pourquoi rokalim est spécial","histoire de rokalim","qui est rokalim le pilonneur"}},{q="Où trouve-t-on Rok'Alim ?",a="Rok'Alim parcourt le bassin nord-ouest de Mille pointes, au sud de la route principale de la région, parmi les aiguilles de grès.",al={"emplacement de rokalim","trouver rokalim le pilonneur","où apparaît rokalim"}}},fx={ab6946f8={q="D'où viennent les Fragments de Rok'Alim ?",a="Ces fragments sont les morceaux brisés de Rok'Alim le Pilonneur, un énorme élémentaire de roche qui erre dans le fond du canyon au nord-ouest des Mille pointes. Contrairement aux élémentaires invoqués par des lanceurs de sorts mortels, Rok'Alim est un ancien survivant de l'époque des Dieux très anciens, possédant assez de pouvoir inné pour rester lié au monde même après la chute de ses maîtres. Ils n'ont pas été façonnés par des mains mortelles, mais brisés directement à partir de sa forme de pierre vivante.",al={"origine des fragments de rok'alim","d'où viennent les fragments de rok'alim","qui a créé les fragments de rok'alim"}}},fp="21,180,28.394.0,18.321.0,35.174.0,32.159.0,28.236.0,24.112.0"}
P.entries["item:frostwolf-banner"] = {n="Bannière loup-de-givre",s="Dans la Vallée d'Alterac, les recrues de la Horde cherchent la Bannière loup-de-givre dans la Caverne des Follepattes. La rapporter est un rite ancestral qui éveille leur esprit guerrier et leur vaut leur premier insigne de clan.",h="Dans la Vallée d'Alterac, les recrues de la Horde cherchent la Bannière loup-de-givre dans la Caverne des...",kw={"vallée d'alterac","bannière loup-de-givre","gnolls","insigne","proving grounds","maître de guerre laggrond","caverne des follepattes"},ang={["faction:Horde"]="Sous l'autorité du Maître de guerre Laggrond, rapporter la bannière consacre officiellement un guerrier au sein du Frostwolf Clan.",["race:Orc"]="En tant qu'orc, rapporter un étendard de clan pris aux gnolls sauvages honore l'héritage du Frostwolf Clan et celui des ancêtres de Thrall, dans les Montagnes d’Alterac."},sec={{t="Un rite de passage",b="Dans la Vallée d'Alterac, les nouveaux guerriers qui veulent rejoindre le Frostwolf Clan doivent faire preuve de cran. Le Maître de guerre Laggrond les envoie au sud, dans la Caverne des Follepattes, où des gnolls territoriaux occupent des couloirs humides et hostiles. Ils doivent atteindre la bannière cachée et la rapporter intacte. Cela prouve leur courage, éveille leur rage de combat et vaut à chaque guerrier l'insigne d'initié du Frostwolf Clan."}},faq={{q="Pourquoi la Bannière loup-de-givre se trouve-t-elle dans une caverne de gnolls ?",a="Le Maître de guerre Laggrond et le clan font de la présence de la bannière dans la Caverne des Follepattes une épreuve d'initiation. Les nouveaux combattants doivent pénétrer en territoire gnoll et affronter le danger pour éveiller leur esprit guerrier et chasser toute complaisance.",al={"pourquoi la bannière est dans la caverne des follepattes","les gnolls ont la bannière","emplacement de la bannière loup-de-givre"}},{q="À qui dois-je rapporter la Bannière loup-de-givre ?",a="Rapportez la bannière au Maître de guerre Laggrond, dans la Vallée d'Alterac. La lui présenter accueille une recrue dans les rangs du Frostwolf Clan et lui vaut un insigne attestant son statut.",al={"qui veut la bannière loup-de-givre","rendre la quête de la bannière","laggrond bannière"}},{q="Pourquoi l'étendard a-t-il un aspect inhabituel pour un emblème loup-de-givre ?",a="Le Maître de guerre Laggrond reconnaît dans la bannière un étendard d'épreuve du clan, bien que ses marques ressemblent à d'anciens insignes tribaux. Certains de ces symboles sont associés aux premiers clans orcs de l'ancienne Horde.",al={"symbole de twilight hammer sur la bannière","la bannière a un mauvais aspect","motif de la bannière loup-de-givre"}}},fx={cf6c63b1={q="Qu'est-ce que la Bannière loup-de-givre ?",a="La Bannière loup-de-givre est un étendard tribal représentant le Frostwolf Clan dans la Vallée d'Alterac. Bien que son sceau ressemble étrangement à une iconographie de clan ancienne plutôt qu'à leur écusson habituel, elle demeure un symbole honoré de la présence et de l'autorité du clan dans la vallée gelée.",al={"qu'est-ce que la bannière loup-de-givre","lore bannière loup-de-givre","à propos de la bannière loup-de-givre"}},["518ec450"]={q="Pourquoi le Maître de guerre Laggrond veut-il que la Bannière loup-de-givre soit récupérée ?",a="Le Maître de guerre Laggrond exige que tous les nouveaux venus cherchant à combattre aux côtés des Frostwolves dans la Vallée d'Alterac subissent un rite de combat. Récupérer la bannière dans les profondeurs de la Caverne des Follepattes infestée de gnolls prouve votre courage, éveille votre esprit de guerrier et vous permet d'obtenir l'insigne d'initié du clan.",al={"pourquoi récupérer la bannière loup-de-givre","pourquoi laggrond veut la bannière","but de la bannière loup-de-givre"}}},fp="16,187,17.384.0,48.208.0,40.160.0,57.196.0"}
P.entries["item:frozen-ectoplasm"] = {n="Frozen Ectoplasm",s="Mux Brouillemana a besoin de Frozen Ectoplasm provenant des esprits Highborne agités du Berceau-de-l’Hiver. C’est l’une des trois substances spectrales qu’il recherche pour ses travaux sur les morts.",h="Mux Brouillemana a besoin de Frozen Ectoplasm provenant des esprits Highborne agités du Berceau-de-l’Hiver.",kw={"highborne anguished","ectoplasme","alambic ectoplasmique","frozen ectoplasm","hunting for ectoplasm","mux brouillemana","highborne suffering","berceau-de-l’hiver"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous reconnaîtrez peut-être l’Alambic ectoplasmique de Mux, son appareil pour récolter des substances spectrales."},sec={{t="Esprits de l’hiver",b="Près du lac du Berceau-de-l’Hiver, les Highborne Anguished et Suffering laissent derrière eux du Frozen Ectoplasm. Mux Brouillemana vous demande d’en récolter avec un Alambic ectoplasmique, ainsi que du Scorched Ectoplasm de Silithus et du Stable Ectoplasm des Maleterres de l’Est. Il espère que ces trois substances lui permettront d’atteindre les âmes qui n’ont pas entièrement quitté ce monde."}},faq={{q="Où trouver du Frozen Ectoplasm ?",a="Les Highborne Anguished et Suffering près du lac du Berceau-de-l’Hiver laissent du Frozen Ectoplasm derrière eux.",al={"emplacement du frozen ectoplasm","où trouver le frozen ectoplasm","ectoplasme du berceau-de-l’hiver"}},{q="À quoi sert le Frozen Ectoplasm ?",a="Mux Brouillemana en a besoin pour Hunting for Ectoplasm, qui demande de récolter trois sortes d’ectoplasme avec un Alambic ectoplasmique.",al={"utilité du frozen ectoplasm","à quoi ça sert","utilité de l’ectoplasme"}},{q="Qui veut du Frozen Ectoplasm ?",a="Mux Brouillemana, à Gadgetzan, veut du Frozen Ectoplasm, ainsi que du Scorched Ectoplasm et du Stable Ectoplasm.",al={"mux et l’ectoplasme","qui en a besoin","mux brouillemana"}},{q="Pourquoi Mux veut-il de l’ectoplasme ?",a="Mux espère utiliser les énergies d’un autre monde contenues dans l’ectoplasme pour atteindre les âmes qui n’ont pas entièrement quitté ce monde.",al={"pourquoi l’ectoplasme","le plan de mux","atteindre les âmes"}},{q="Quels esprits laissent du Frozen Ectoplasm ?",a="Les esprits Highborne Anguished et Suffering du Berceau-de-l’Hiver laissent du Frozen Ectoplasm.",al={"d’où vient l’ectoplasme","ectoplasme des highborne","butin des esprits gelés"}}},fp="16,166,14.350.0,33.94.0,29.134.0,27.96.0,28.112.0,36.85.0"}
P.entries["item:full-leaden-collection-phial"] = {n="Flasque plombée lourde remplie",s="À Kharanos, Ozzie Virevolt cherche un échantillon prélevé sur les troggs de Gnomeregan. Il espère qu’il guérira les gnomes lépreux irradiés, ou qu’il donnera un rhum dangereusement puissant.",h="À Kharanos, Ozzie Virevolt cherche un échantillon prélevé sur les troggs de Gnomeregan.",kw={"flasque plombée lourde remplie","gnogaine","gnomeregan","trogg irradié","kharanos","fiole de prélèvement plombée","gnome lépreux","ozzie virevolt"},ang={["profession:Engineering"]="L’enveloppe de plomb reflète les protocoles de sécurité gnomes pour manipuler des retombées toxiques et instables lors des essais en laboratoire.",["race:Gnome"]="Pour les gnomes exilés de Dun Morogh, transporter cet échantillon toxique ravive le souvenir de la catastrophe qui a empoisonné leur foyer ancestral. Il leur donne l’espoir désespéré de sauver leurs proches corrompus."},sec={{t="Un breuvage toxique",b="Un revêtement de plomb protège son porteur des retombées vertes instables qui imprègnent Gnomeregan. Les conseillers du Grand Bricoleur Mekkatorque ont inondé les couloirs inférieurs de radiations toxiques pour arrêter les troggs envahisseurs. Au lieu de cela, la catastrophe a transformé les troggs et les gnomes survivants en créatures irradiées et démentes.\n\nLes Envahisseurs irradiés et les Pillards irradiés laissent des résidus liquides que récupèrent les bricoleurs réfugiés à Kharanos. Ozzie Virevolt et Esbrouf Fulgurouage s’en servent comme matière première pour leurs expériences sur des remèdes."},{t="Remède ou concoction",b="Ozzie Virevolt mène des expériences frénétiques pour remédier aux retombées, tandis que Gnoarn reste déterminé à reconquérir la ville. Ozzie espère que le liquide soignera un gnome lépreux capturé et peut-être même sa propre calvitie. Dans les laboratoires gnomes, la frontière entre un antidote miraculeux et une boisson hautement volatile reste dangereusement mince."}},faq={{q="Pourquoi la fiole est-elle en plomb ?",a="Le revêtement de plomb de la fiole protège son porteur des intenses retombées radioactives recueillies sur les troggs contaminés de Gnomeregan. Il peut ainsi la rapporter à Kharanos sans tomber malade ni mourir.",al={"pourquoi une fiole en plomb","pourquoi une flasque en plomb","utilité de la fiole de prélèvement plombée"}},{q="Qui veut de ce liquide irradié ?",a="Ozzie Virevolt, un chercheur gnome de Kharanos, veut étudier ces retombées irradiées pour trouver un remède contre la lèpre des gnomes. Esbrouf Fulgurouage l’aide.",al={"qui a besoin de la fiole","quête d’ozzie virevolt","qui récupère la gnogaine"}},{q="D’où vient la radiation dans la fiole ?",a="Les résidus vert lumineux proviennent des Envahisseurs irradiés et des Pillards irradiés, des troggs qui rôdent dans les couloirs contaminés menant à Gnomeregan.",al={"comment remplir la fiole","emplacement des troggs irradiés","origine de la lueur verte"}},{q="Ozzie guérit-il vraiment les gnomes lépreux avec ce liquide ?",a="Les expériences d’Ozzie sont chaotiques et leurs résultats incertains. Sa concoction vise à guérir un gnome lépreux capturé et à lui rendre ses cheveux, mais la science gnome exige souvent des essais répétés et des échantillons affinés pour obtenir des résultats sûrs et fiables.",al={"le remède fonctionne-t-il","résultat de la gnogaine","le gnome lépreux est-il guéri"}}},fx={["32cc4509"]={q="Qu'est-ce que la Flasque plombée lourde remplie ?",a="C'est une lourde flasque protégée par du plomb, remplie de retombées radioactives vertes et lumineuses prélevées directement sur les troggs contaminés qui infestent Gnomeregan. Son épaisse enveloppe de plomb empêche les dangereux résidus radioactifs d'empoisonner la personne qui la transporte.",al={"qu'est-ce que la flasque plombée","flasque plombée remplie","qu'est-ce que cette flasque"}}},fp="28,161,12.485.0,18.331.1,30.195.0,32.163.0,48.145.0,50.226.0"}
P.entries["item:fungal-spores"] = {n="Spores fongiques",s="Dans les oasis des Tarides, les Spores fongiques gonflent dans les champignons qui poussent sur les rives. Les eaux stimulent la vie alentour, et la Société royale des apothicaires récolte les spores pour ses alchimistes.",h="Dans les oasis des Tarides, les Spores fongiques gonflent dans les champignons qui poussent sur les rives.",kw={"apothicaire helbrim","société des apothicaires","tarides","la croisée","les bassins oubliés","spores fongiques","champignon gonflé","oasis luxuriante","l'oasis stagnante"},ang={["profession:Herbalism"]="En tant qu’herboriste, vous pouvez voir comment les eaux vivifiantes des oasis des Tarides transforment les champignons qui poussent alentour.",["race:Undead"]="En tant que mort-vivant, vous savez que la Société royale des apothicaires apprécie les ingrédients régionaux rares pour ses recherches. Les champignons altérés de Kalimdor offrent une autre option que les plantes gangrenées de Lordaeron."},sec={{t="La vitalité des oasis",b="Les oasis des Tarides abritent une vie inhabituelle au milieu des plaines arides. Aux Bassins oubliés, à l’Oasis luxuriante et à l’oasis stagnante, l’eau ne fait pas qu’étancher la soif. Elle stimule et transforme les plantes et les animaux alentour. Sur les rives humides, des champignons gonflent de spores qui concentrent la puissance des eaux et favorisent la croissance. Les naturalistes étudient ces changements, tandis que la Société royale des apothicaires récolte les champignons pour ses alchimistes."},{t="L’alchimie des Réprouvés",b="Les apothicaires en poste à l’étranger récoltent des ingrédients locaux inhabituels pour leurs laboratoires et leurs collègues. À la Croisée, l’Apothicaire Helbrim expédie des réactifs, notamment à l’Apothecary Zamah, à Pitons-du-Tonnerre. Les spores sont précieuses pour préparer de puissants mélanges chimiques. Des forces mystérieuses sous le sol de Kalimdor ont altéré leurs propriétés naturelles, les rendant utiles aux Réprouvés."}},faq={{q="Où trouve-t-on ces spores ?",a="Les Spores fongiques poussent dans des champignons gonflés le long des rives des principales oasis des Tarides : les Bassins oubliés, l’Oasis luxuriante et l’oasis stagnante.",al={"emplacements des spores","où trouver des spores fongiques","emplacements des champignons gonflés"}},{q="Pourquoi les Réprouvés s’y intéressent-ils ?",a="Les eaux des oasis ont imprégné les spores d’une énergie vitale intense. L’Apothicaire Helbrim les utilise dans de puissants mélanges pour la Société royale des apothicaires et son collègue Apothecary Zamah, à Pitons-du-Tonnerre.",al={"pourquoi helbrim veut des spores","utilisation des spores par les apothicaires","à quoi servent les spores"}},{q="Pourquoi les champignons des oasis sont-ils si grands ?",a="L’énergie vitale inhabituelle des eaux des oasis des Tarides transforme les plantes et les animaux alentour. Les champignons qui poussent sur les rives se gonflent de spores altérées.",al={"pourquoi les champignons sont-ils altérés","effet de l’eau des oasis","mystère des oasis"}},{q="Qui réclame ces spores ?",a="À la Croisée, dans les Tarides, l’Apothicaire Helbrim demande aux aventuriers de récolter des spores pour ses recherches.",al={"qui a besoin de spores fongiques","donneur de quête des spores","apothicaire helbrim"}}},fx={["3c4c96db"]={q="Que sont ces Spores fongiques ?",a="Ce sont des spores puissantes récoltées sur les champignons chargés qui poussent autour des oasis des Tarides, comme les Bassins oubliés. Nourris par les énergies vitales étranges et altérées qui circulent dans les eaux de l'oasis, les champignons produisent des spores imprégnées de propriétés biologiques inhabituelles qui intriguent les alchimistes.",al={"que sont les spores fongiques","infos spores fongiques","que sont les spores"}},["02f1bc1b"]={q="Pourquoi l'Apothicaire Helbrim veut-il les Spores fongiques ?",a="L'Apothicaire Helbrim à La Croisée recherche les spores pour la Société royale des apothicaires. Il trouve les propriétés altérées des champignons de l'oasis particulièrement utiles pour composer une concoction expérimentale, qu'il a l'intention de livrer à son associée, l'Apothecary Zamah, aux Pitons-du-Tonnerre.",al={"pourquoi helbrim veut les spores","pourquoi vouloir les spores fongiques","qui a besoin des spores fongiques"}}},fp="13,178,21.429.0,16.379.0,29.151.0,40.200.0,52.133.0,24.104.0"}
P.entries["item:furen-s-instructions"] = {n="Instructions de Furen",s="À Hurlevent, Furen Barbe-longue remet aux guerriers éprouvés de l’Alliance la liste des matériaux pour Fire Hardened Mail.",h="À Hurlevent, Furen Barbe-longue remet aux guerriers éprouvés de l’Alliance la liste des matériaux pour Fire...",kw={"corne carbonisée","fire hardened mail","furen barbe-longue","instructions de furen","corne galvanisée","kraal de tranchebauge","croc d'araignée brûlé","les serres-rocheuses","fiole de phlogiston","les paluns"},ang={["class:Warrior"]="En tant que guerrier de l’Alliance, vous affrontez de féroces bêtes et des houlgers pour gagner une lourde armure de mailles.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez voir comment la recette de Furen associe des réactifs de bêtes à de rares distillats alchimiques pour tremper l’armure au-delà des méthodes de forge ordinaires."},sec={{t="Les exigences d’un maître forgeron",b="Furen Barbe-longue propose une cotte de mailles résistante à un guerrier qui a fait ses preuves dans des travaux de forge plus simples. L’armurier nain exige que le guerrier aille chercher lui-même les composants rares. Son parchemin détaille les matériaux nécessaires et l’envoie les récolter à travers les continents."},{t="Des composants exotiques",b="Le parchemin impose un dangereux périple à travers les Royaumes de l'est et Kalimdor. Des dizaines de crochets d’araignée brûlés proviennent des grottes humides des Paluns. Les maillons renforcés nécessitent aussi des cornes de chimères cracheuses de feu dans les crêtes des Serres-Rocheuses. La liste réclame une Corne galvanisée de la matriarche chimère et une Fiole de Phlogiston volatile, conservée au plus profond du Kraal de Tranchebauge, bastion houlger."}},faq={{q="Que sont les Instructions de Furen ?",a="Les Instructions de Furen sont la liste écrite que Furen Barbe-longue remet aux guerriers de l’Alliance à Hurlevent. Elle indique les matériaux exotiques nécessaires à la fabrication de Fire Hardened Mail.",al={"instructions de furen","que sont les instructions de furen","liste de furen"}},{q="Qui est Furen Barbe-longue ?",a="Furen Barbe-longue est un maître armurier nain du Quartier des Nains de Hurlevent. Il met les guerriers chevronnés à l’épreuve et leur fabrique des protections durables.",al={"qui est furen","furen barbe-longue","furen hurlevent"}},{q="D’où viennent les matériaux de la liste ?",a="La liste réclame des crochets d’araignée brûlés des Paluns, des cornes calcinées et une Corne galvanisée de chimères des Serres-Rocheuses, ainsi qu’une Fiole de Phlogiston provenant de Roogug, au Kraal de Tranchebauge.",al={"où trouver les objets","emplacement des matériaux de furen","matériaux de la liste de furen"}},{q="Que forge Furen avec ces matériaux ?",a="Furen utilise ces matériaux et ses secrets de forge pour fabriquer une pièce de Fire Hardened Mail spécialement conçue pour le guerrier.",al={"quelle armure furen fabrique","récompense fire hardened mail","récompense de fabrication de furen"}}},fx={["82702a01"]={q="D'où viennent les Instructions de Furen et qui les a créées ?",a="Furen Barbe-longue, un forgeron nain accompli travaillant à Hurlevent, a écrit ce document lui-même. Connaissant les secrets de la fabrication d'une armure de mailles exceptionnelle, il a rédigé ce registre détaillé pour souligner les composants rares nécessaires à travers le monde afin qu'un guerrier ambitieux sache précisément ce qu'il doit chercher.",al={"qui a écrit les instructions de furen","d'où viennent les instructions de furen","origine instructions de furen"}},["42eefba8"]={q="Pourquoi les Instructions de Furen sont-elles importantes ?",a="Ces instructions servent de guide pour une pénible chasse aux trésors à travers Kalimdor et les Royaumes de l'est. Furen exige que vous les gardiez à portée de main tout en rassemblant des crocs calcinés, des cornes de chimère et du phlogiston alchimique, en veillant à rapporter les réactifs exacts dont il a besoin pour forger une armure trempée par le feu.",al={"pourquoi ai-je besoin des instructions de furen","pourquoi les instructions de furen sont recherchées","but des instructions de furen"}}},fp="20,106,24.279.0,17.410.0,29.161.0,23.147.0,45.191.0,43.117.0"}
P.entries["item:furen-s-notes"] = {n="Notes de Furen",s="À Hurlevent, les Notes de Furen transmettent ses découvertes en métallurgie et en forge d’armures aux artisans de l’Alliance. Furen Barbe-longue forgeait des protections pour les guerriers vétérans, puis en envoyait des copies afin d’aider ses confrères forgerons à perfectionner leur travail.",h="À Hurlevent, les Notes de Furen transmettent ses découvertes en métallurgie et en forge d’armures aux...",kw={"forge","quartier des nains","furen","furen barbe-longue","notes de furen","grimand elmore","klockmort spannerspan","mathiel"},ang={["class:Warrior"]="En tant que guerrier, vos épreuves d’armure à Hurlevent vous mènent directement à ces notes. Elles consignent des idées pratiques façonnées par les exigences du combat en première ligne.",["profession:Blacksmithing"]="En tant que forgeron, vous voyez le savoir spécialisé en forge d’armures circuler entre les artisans nains, elfes et gnomes de l’Alliance."},sec={{t="Les découvertes d’un maître",b="Dans le Quartier des Nains de Hurlevent, Furen Barbe-longue forge des armements spécialisés pour les guerriers. Tout en travaillant, il consigne ses méthodes et ses découvertes. Le travail des métaux chez les nains ne cesse d’évoluer, alors il réalise plusieurs copies pour que d’autres forgerons puissent s’en servir et les approfondir. Ses notes décrivent des façons de tremper, de renforcer et de façonner les armures contre les coups mortels."},{t="Envoyées dans toute l’Alliance",b="Furen envoie des copies à des contacts de confiance parmi les artisans de l’Alliance. Grimand Elmore peut railler un forgeron qu’il prétend avoir formé, mais les notes contiennent tout de même des idées utiles. Certaines copies traversent la Grande mer jusqu’aux artisans elfes de la nuit, notamment à Mathiel, sur la Terrasse des Guerriers de Darnassus. Leurs besoins communs au combat rapprochent leurs différentes traditions."}},faq={{q="Que contiennent les Notes de Furen ?",a="Les Notes de Furen décrivent les techniques de forge d’armures et les découvertes en métallurgie mises au point par Furen Barbe-longue lorsqu’il fabriquait des armures sur mesure pour des guerriers aguerris.",al={"que sont les notes de furen","que contiennent les notes de furen","contenu des notes de furen"}},{q="Qui est Furen Barbe-longue ?",a="Furen Barbe-longue est un maître forgeron d’armures nain du Quartier des Nains de Hurlevent. Il guide les guerriers en devenir et fabrique des équipements de guerre défensifs spécialisés.",al={"qui les a écrites","qui est furen","furen barbe-longue"}},{q="Pourquoi Grimand Elmore se met-il en colère à propos des notes ?",a="Grimand Elmore affirme avoir enseigné à Furen tout ce que le nain sait. Il s’irrite à l’idée que son ancien élève puisse lui apprendre quelque chose de nouveau, même s’il reconnaît que les notes décrivent des techniques qui méritent d’être essayées.",al={"pourquoi grimand est-il furieux","réaction de grimand elmore","grimand est-il fier"}},{q="Qui reçoit des copies des Notes de Furen ?",a="Furen envoie des copies à des collègues de confiance dans toute l’Alliance, notamment au forgeron d’armes Grimand Elmore à Hurlevent, au forgeron elfe de la nuit Mathiel à Darnassus et au forgeron gnome Klockmort Spannerspan à Forgefer.",al={"qui reçoit les notes de furen","où vont les notes","livrer les notes de furen"}},{q="Comment Mathiel réagit-il aux notes ?",a="Mathiel, un forgeron elfe de la nuit établi sur la Terrasse des Guerriers de Darnassus, accueille avec enthousiasme les découvertes de Furen. Il les considère comme une grande découverte et comme un honneur de les intégrer à son propre travail.",al={"réaction de mathiel","mathiel à darnassus","que pense mathiel"}}},fx={["224f803f"]={q="Pourquoi quelqu'un voudrait-il les Notes de Furen ?",a="Les notes documentent des techniques de forge révolutionnaires que Furen Barbe-longue a développées tout en forgeant une armure de guerrier spécialisée. Les forgerons de l'Alliance — tels que Mathiel à Darnassus et Grimand Elmore à Hurlevent — sont susceptibles d'en tirer des connaissances métallurgiques précieuses. Même les artisans sceptiques quant au talent de Furen, comme Elmore, reconnaissent les idées innovantes qu'elles contiennent et qu'ils sont impatients de tester sur leurs propres enclumes.",al={"pourquoi les forgerons veulent les notes de furen","valeur des notes de furen","pourquoi partager les notes de furen"}}},fp="13,223,22.332.0,30.350.0,39.157.0,23.146.0,50.205.0,37.212.0,36.183.0"}
P.entries["item:furlbrow-s-deed"] = {n="Titre de propriété de Froncebouille",s="Près de leur chariot brisé, à la frontière de la Marche de l’Ouest, Theodore et Verna Froncebouille ont perdu leur ferme au profit de la Confrérie défias. Leur titre de propriété est aux mains des bandits, et avec lui leur foyer et leurs moyens de subsistance.",h="Près de leur chariot brisé, à la frontière de la Marche de l’Ouest, Theodore et Verna Froncebouille ont perdu...",kw={"titre de propriété","défias","ferme","furlbrow","theodore","verna","chariot","marche de l’ouest"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez apporter un peu de réconfort à ceux qui ont été chassés de chez eux, alors que le royaume manque de soldats.",["race:Human"]="En tant qu’humain, vous pouvez constater les dégâts causés par les Défias à l’ordre public dans les terres proches de Hurlevent, jusque dans le vol de simples titres de propriété."},sec={{t="Terres volées et revendications falsifiées",b="Theodore Furlbrow et Verna ont signé le titre de propriété pour assurer la possession de leur ferme familiale dans la Marche de l’Ouest. Après que la Confrérie défias eut envahi la région, des bandits les ont chassés de chez eux et ont emporté le titre dans la Forêt d’Elwynn. Des notes au verso montrent que les voleurs prévoyaient de le copier et de falsifier des revendications sur d’autres propriétés. Les Furlbrow ont perdu leurs moyens de subsistance et pris la route, sans foyer où retourner."}},faq={{q="Pourquoi la Confrérie défias a-t-elle volé le titre de propriété ?",a="Les notes sur le titre montrent que les Défias voulaient étudier son sceau et ses signatures, puis falsifier des revendications sur les fermes saisies dans toute la Marche de l’Ouest.",al={"pourquoi voler le titre de propriété","pourquoi les bandits voulaient le titre","but du titre pour les défias"}},{q="À qui appartient ce titre de propriété ?",a="Le titre appartient au Fermier Froncebouille, Theodore Furlbrow, et à sa femme Verna. Des hors-la-loi ont chassé les fermiers de la Marche de l’Ouest de leur ferme.",al={"à qui appartient le titre des furlbrow","qui est furlbrow","à qui est ce titre"}},{q="Où peut-on trouver les Furlbrow ?",a="Vous trouverez Theodore et Verna juste après la frontière de la Marche de l’Ouest, près de leur chariot brisé sur la route principale venant de la Forêt d’Elwynn.",al={"où sont les furlbrow","emplacement du fermier froncebouille","où rapporter le titre"}},{q="Pourquoi les Furlbrow tiennent-ils encore au titre de propriété s’ils ont fui ?",a="Les Furlbrow savent que la Marche de l’Ouest est désormais trop dangereuse pour les honnêtes gens. Pourtant, une preuve de propriété leur donne l’espoir de récupérer leurs terres si la paix revient.",al={"pourquoi veulent-ils récupérer le titre","les furlbrow reviendront-ils"}}},fx={["4593623b"]={q="D'où vient le Titre de propriété de Froncebouille et qui l'a fait ?",a="Le titre est un acte de propriété officiel pour une étendue de terres agricoles dans la Marche de l’Ouest, signé par Theodore Furlbrow et contresigné par sa femme, Verna. Il établissait leur droit de propriété légitime sur leur ferme familiale avant que les bandits des Defias ne les rackettent et ne la leur volent.",al={"origine titre de propriété de froncebouille","qui a fait le titre de propriété de froncebouille","d'où vient le titre de propriété"}}},fp="15,205,29.380.0,34.129.0,29.121.0,33.116.0,60.150.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="Montre de Froncebouille",s="Dans la Marche de l’Ouest, le Fermier Froncebouille cherche la montre à gousset qu’il a perdue quand des bandits défias l’ont chassé de chez lui. Le père de Verna la lui a offerte le jour de leur mariage.",h="Dans la Marche de l’Ouest, le Fermier Froncebouille cherche la montre à gousset qu’il a perdue quand des...",kw={"benny blaanco","défias","fermier froncebouille","montre de froncebouille","the forgotten heirloom","verna froncebouille","armoire","marche de l’ouest"},ang={["faction:Alliance"]="Aider les Froncebouille à récupérer leur héritage montre à quel point la couronne de Hurlevent a échoué à protéger les fermiers travailleurs de la Marche de l’Ouest contre le banditisme organisé."},sec={{t="Un souvenir dans les ruines",b="Des bandits défias ont chassé le Fermier Froncebouille et Verna de leur maison, au champ de citrouilles des Froncebouille, en pleine nuit. Dans leur fuite, il a laissé la montre dans une armoire de la ferme envahie. Benny Blaanco et ses coupe-jarrets montent la garde à proximité.\n\nLe couple campe désormais au bord de la route. La montre est l’un des rares vestiges de leur ancienne vie que les hors-la-loi n’ont pas abîmés."}},faq={{q="Pourquoi la montre à gousset est-elle si importante pour le Fermier Froncebouille ?",a="Le père de Verna a offert la montre au Fermier Froncebouille le jour de leur mariage. Après que la Confrérie défias leur a pris leurs terres, leur maison et leurs moyens de subsistance, elle reste leur dernier bien chargé d’émotion.",al={"pourquoi froncebouille veut sa montre","importance de la montre de froncebouille","qui a offert la montre à froncebouille"}},{q="Où se trouve la montre à gousset ?",a="La montre se trouve dans une armoire de la ferme des Froncebouille, parmi les champs de citrouilles à l’ouest de la route principale où les Froncebouille sont bloqués.",al={"où se trouve la montre à gousset","emplacement de l’armoire de froncebouille","comment trouver la montre"}},{q="Qui garde la montre ?",a="La Confrérie défias a pris le contrôle de la ferme. Benny Blaanco et ses hommes rôdent près de l’armoire.",al={"qui a la montre de froncebouille","garde de la montre dans la marche de l’ouest","montre de benny blaanco"}},{q="Les défias ont-ils directement volé la montre ?",a="Les défias n’ont pas directement volé la montre. Les Froncebouille ont fui dans la panique quand les bandits ont attaqué le champ de citrouilles, et le Fermier Froncebouille a oublié de l’emporter. Elle est restée dans l’armoire de leur chambre tandis que la ferme était envahie.",al={"les défias ont-ils pris la montre","la montre a-t-elle été volée"}}},fx={["42b91745"]={q="Qu'est-ce que la Montre de Froncebouille ?",a="C'est un héritage familial chéri appartenant au Fermier Froncebouille. La montre lui a été offerte par le père de sa femme Verna en cadeau pour leur jour de mariage. Lorsque la The Defias Brotherhood a envahi leur ferme de citrouilles, le couple a dû fuir pour sauver sa vie au milieu de la nuit, laissant par inadvertance le précieux garde-temps derrière eux dans leur armoire.",al={"qu'est-ce que la montre de froncebouille","montre de poche froncebouille","montre de poche du fermier froncebouille"}},ba43cdcd={q="D'où vient la Montre de Froncebouille et qui l'a fabriquée ?",a="La montre appartenait à l'origine au père de Verna Froncebouille, qui l'a offerte au Fermier Froncebouille le jour du mariage du couple. L'artisan spécifique ou la ville de fabrication sont inconnus, mais pour les fermiers déplacés, elle représente l'un des rares témoignages durables de leur famille et de leur vie d'avant, avant que les Defias ne les chassent de leurs terres.",al={"qui a fait la montre de poche de froncebouille","où froncebouille a-t-il obtenu la montre","origine montre de poche froncebouille"}}},fp="23,161,23.356.0,56.202.0,31.136.0,26.107.0,40.219.0"}
P.entries["item:gadrin-s-parchment"] = {n="Gadrin's Parchment",s="Le parchemin de Gadrin se lit à Shadra'Alor, dans Les Hinterlands. Ses mots invoquent Shadra, dont Apothicaire Lydon convoite le venin au Moulin-de-Tarren.",h="Le parchemin de Gadrin se lit à Shadra'Alor, dans Les Hinterlands.",kw={"apothicaire lydon","gadrin","parchemin de gadrin","hinterlands","parchemin","shadra","shadra'alor","venin","witherbark"},sec={{t="À Shadra'Alor",b="Au cœur du territoire des Witherbark, le parchemin de Gadrin se lit à l’autel de Shadra'Alor. Ses mots invoquent Shadra, la déesse-araignée. Apothicaire Lydon recherche son venin au Moulin-de-Tarren."}},faq={{q="À quoi sert le parchemin de Gadrin ?",a="Le parchemin de Gadrin se lit à Shadra'Alor pour invoquer Shadra, la déesse-araignée.",al={"à quoi sert un parchemin","utilisation du parchemin de gadrin"}},{q="Où lire le parchemin ?",a="Lisez le parchemin de Gadrin à l’autel de Shadra'Alor, au cœur du territoire des Witherbark, dans Les Hinterlands.",al={"où utiliser le parchemin","emplacement de l’autel de shadra"}},{q="Qui est Shadra ?",a="Shadra est la déesse-araignée invoquée en lisant le parchemin de Gadrin à Shadra'Alor.",al={"shadra araignée","déesse-araignée"}},{q="Qui veut le venin de Shadra ?",a="Apothicaire Lydon, au Moulin-de-Tarren, recherche le venin de Shadra.",al={"pour qui le venin","venin de lydon"}}},fp="18,137,14.182.0,32.75.0,30.101.0,14.79.0,25.53.0"}
P.entries["item:gaea-seed"] = {n="Graine de Gaïa",s="Le long du lac Mirkfallon, les Graines de Gaïa redonnent espoir aux terres blessées des Serres-Rocheuses.",h="Le long du lac Mirkfallon, les Graines de Gaïa redonnent espoir aux terres blessées des Serres-Rocheuses.",kw={"le val calciné","cycle of rebirth","mère-terre","graine de gaïa","lac mirkfallon","les serres-rocheuses","retraite de roche-soleil","tammra champ-des-vents"},ang={["class:Shaman"]="En tant que chamane, vous savez que les rites élémentaires et la bénédiction de la Mère-Terre peuvent accélérer la croissance et contribuer à guérir les terres meurtries.",["race:Tauren"]="En tant que tauren, vous partagez le devoir sacré des habitants de la Retraite de Roche-Soleil : guérir les terres abîmées par les guerres et l'exploitation forestière venues d'ailleurs."},sec={{t="Réceptacles du renouveau",b="Les Graines de Gaïa s'échouent sur les rives du lac Mirkfallon ou y poussent, dans les Serres-Rocheuses. Petites et fibreuses, elles ressemblent à des noix de coco et résistent aux conditions rudes. Les conflits et l'industrie ont meurtri la terre, alors les chamans se tournent vers ces graines pour contribuer à la guérir."},{t="Bénédictions de la Mère-Terre",b="À la Retraite de Roche-Soleil, la chamane tauren Tammra Champ-des-vents ramasse des Graines de Gaïa face aux ravages qui frappent les sommets. Les chamans bénissent les coques dormantes grâce au pouvoir de la Mère-Terre, par des chants traditionnels et des rites élémentaires. La bénédiction accélère leur croissance. Elles deviennent de robustes jeunes pousses capables de prendre racine dans un sol brûlé et stérile, comme au Val calciné."}},faq={{q="Où trouve-t-on les Graines de Gaïa ?",a="Les Graines de Gaïa s'échouent sur les rives du lac Mirkfallon, dans les montagnes au nord de la Retraite de Roche-Soleil, dans les Serres-Rocheuses.",al={"emplacement de la graine de gaïa","où trouver les graines de gaïa","comment obtenir une graine de gaïa"}},{q="À quoi servent les Graines de Gaïa ?",a="À la Retraite de Roche-Soleil, Tammra Champ-des-vents ramasse des Graines de Gaïa pour leur donner une bénédiction élémentaire. Les graines bénies aident à restaurer la végétation dans les lieux dévastés, comme le Val calciné.",al={"utilité des graines de gaïa","pourquoi ramasser les graines de gaïa","que fait tammra avec les graines de gaïa"}},{q="Pourquoi les chamans doivent-ils imprégner les graines ?",a="Le feu, la guerre et l'exploitation forestière ont gravement endommagé certaines parties des Serres-Rocheuses. Le pouvoir de la Mère-Terre accélère la croissance des graines et les fortifie pour qu'elles prennent racine dans un sol ravagé.",al={"pourquoi bénir les graines","magie chamanique des graines de gaïa"}},{q="À quoi ressemblent les Graines de Gaïa ?",a="Les Graines de Gaïa ressemblent à de petites coques brunes et rondes, ou à des noix de coco, au bord de l'eau du lac Mirkfallon.",al={"apparence des graines de gaïa","comment repérer les graines de gaïa"}}},fx={["0f706426"]={q="Qu'est-ce qu'une Graine de Gaïa ?",a="Une Graine de Gaïa est un noyau de vie robuste, semblable à une noix de coco, originaire des Serres-Rocheuses. Dotées d'une résilience naturelle, ces graines détiennent un potentiel végétatif puissant que les chamans taurens exploitent grâce aux bénédictions de la Mère Terre pour apporter une croissance réparatrice aux terres marquées par la cupidité industrielle et la guerre.",al={"que sont les graines de gaïa","infos graine de gaïa","qu'est-ce qu'une graine de gaïa"}},e9a7441d={q="D'où vient une Graine de Gaïa ?",a="Les Graines de Gaïa sont des merveilles botaniques naturelles trouvées uniquement le long du rivage du Lac Mirkfallon, niché haut dans les Serres-Rocheuses au nord de la Retraite de Roche-Soleil. Elles ne sont pas façonnées par des mains mortelles, mais sont plutôt des cadeaux naturels de la Mère Terre, fleurissant naturellement autour des rives du lac.",al={"qui a créé la graine de gaïa","origine graine de gaïa","d'où viennent les graines de gaïa"}},["3509f4c5"]={q="Pourquoi Tammra Champ-des-vents veut-elle des Graines de Gaïa ?",a="Tammra Champ-des-vents, une chamane à la Retraite de Roche-Soleil, recherche des Graines de Gaïa pour guérir la nature sauvage dévastée des Serres-Rocheuses. L'exploitation forestière continue et les combats ont dévasté la région, en particulier les terres brûlées du Val calciné. En rassemblant ces graines, elle peut canaliser la bénédiction de la Mère Terre et son pouvoir chamanique en elles, accélérant leur croissance pour reconstituer la terre en ruine.",al={"pourquoi récolter des graines de gaïa","qui veut des graines de gaïa","pourquoi quelqu'un voudrait une graine de gaïa"}}},fp="9,162,18.243.0,28.359.1,27.103.0,29.172.0,39.167.0,29.103.0"}
P.entries["item:gaffer-jack"] = {n="Rouage électrique",s="Au large d’Auberdine, des pièces de Rouage électrique reposent sous les vagues de Sombrivage. Crackboum Tournelevier a perdu une caisse pendant sa traversée en mer.",h="Au large d’Auberdine, des pièces de Rouage électrique reposent sous les vagues de Sombrivage.",kw={"auberdine","sombrivage","pêche","rouage électrique","forgefer","stintle pegs","crackboum tournelevier"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous savez combien il est frustrant de perdre du matériel spécialisé comme des Gaffer Jacks. Sans eux, des mécanismes délicats tels que les stintle pegs ne peuvent pas être calibrés.",["race:Gnome"]="En tant que gnome, vous pourriez trouver peu orthodoxe de quitter Forgefer pour mener une vie tranquille à Auberdine. Perdre une caisse de pièces indispensables par-dessus le bastingage après avoir trop bu, c’est une autre histoire."},sec={{t="Perdu en mer",b="Le bricoleur gnome Crackboum Tournelevier a réservé un passage pour Auberdine afin de trouver le calme, loin des ateliers et des tavernes de Forgefer. Pendant la traversée, il a trop bu et a fait tomber tout un conteneur de Gaffer Jacks par-dessus bord. Ces petites fixations ont sombré dans les eaux côtières de Sombrivage. Sans elles, Crackboum ne pouvait pas régler ses stintle pegs."},{t="Récupération sous-marine",b="Des Gaffer Jacks ont sombré dans les vagues le long du rivage de Sombrivage, où des pêcheurs patients en accrochent parfois à leur ligne. Récupérer ces pièces permet à Crackboum d’assembler ses étranges engins. Trouver de minuscules pièces métalliques en pleine mer demande de la patience et de la chance."}},faq={{q="À quoi sert un Rouage électrique ?",a="Crackboum Tournelevier a besoin de Gaffer Jacks pour régler les stintle pegs de ses inventions expérimentales.",al={"utilité du rouage électrique","à quoi sert un rouage électrique","usage du rouage électrique"}},{q="Comment ces pièces se sont-elles retrouvées dans l’océan près d’Auberdine ?",a="Crackboum Tournelevier a quitté les Royaumes de l’est par la mer, en quête de calme loin de Forgefer. Il a trop bu pendant la traversée et a accidentellement fait tomber sa caisse de Gaffer Jacks par-dessus bord, dans les eaux de Sombrivage.",al={"pourquoi les gaffer jacks sont dans l’eau","qui a fait tomber les gaffer jacks","rouage électrique perdu"}},{q="Qui veut récupérer les Gaffer Jacks ?",a="Crackboum Tournelevier, un inventeur gnome excentrique installé à Auberdine, veut récupérer huit Gaffer Jacks pour pouvoir continuer à construire ses étranges inventions.",al={"qui a besoin de gaffer jacks","où remettre les gaffer jacks","qui récupère les gaffer jacks"}},{q="Où trouver des Gaffer Jacks ?",a="Des Gaffer Jacks reposent sous l’eau le long des côtes de Sombrivage. Les pêcheurs en accrochent parfois à leur ligne dans les vagues près du rivage.",al={"où trouver des gaffer jacks","comment trouver des gaffer jacks","emplacement des gaffer jacks"}}},fx={["1164a7e3"]={q="Qu'est-ce qu'un Rouage électrique ?",a="Un Rouage électrique est un composant d'ingénierie spécialisé utilisé par des bricoleurs comme Crackboum Tournelevier. Plus précisément, Crackboum compte sur eux pour régler correctement ses chevilles de maintien, ce qui en fait un élément indispensable de sa boîte à outils d'invention.",al={"qu'est-ce qu'un rouage électrique","lore rouages électriques","que sont les rouages électriques"}}},fp="11,130,11.333.0,14.253.0,31.95.0,51.206.0,33.152.0,32.112.0"}
P.entries["item:gahz-ridian-detector"] = {n="Gahz'ridian Detector",s="Le Gahz'ridian Detector est un appareil conçu par Marvon Rivetseeker pour retrouver les ornements dispersés dans Tanaris. Il l’aide à réunir des matériaux pour étudier les gravures trollesques.",h="Le Gahz'ridian Detector est un appareil conçu par Marvon Rivetseeker pour retrouver les ornements dispersés...",kw={"pilier brisé","ruines d'estelune","gahz'ridian","gahz'ridian detector","ornement en gahz'ridian","gahz'rilla","marvon rivetseeker","ruines de sudelune","tanaris"},sec={{t="À la recherche dans le désert",b="Marvon Rivetseeker a créé le Gahz'ridian Detector pour retrouver les ornements taillés dans le Gahz'ridian. Il y a bien longtemps, les trolls façonnaient ces ornements à l’image de Gahz'rilla, qu’ils vénéraient comme une divinité. Les gravures sont dispersées dans Tanaris, et beaucoup se trouvent près du Pilier brisé, des Ruines d'Estelune et des Ruines de Sudelune."}},faq={{q="Qui a créé le Gahz'ridian Detector ?",a="Marvon Rivetseeker, scientifique et chasseur de trésors à Tanaris, a inventé le Gahz'ridian Detector.",al={"qui a créé le détecteur","appareil de marvon","inventeur du détecteur"}},{q="Que trouve le détecteur ?",a="Le Gahz'ridian Detector aide à retrouver les ornements taillés dans le Gahz'ridian, un matériau nommé d’après Gahz'rilla.",al={"que trouve le détecteur","trouver le gahz'ridian","utilité du détecteur"}},{q="Qui a créé les ornements en Gahz'ridian ?",a="Les trolls qui occupaient autrefois Tanaris ont taillé les ornements en Gahz'ridian il y a bien longtemps.",al={"qui a créé les ornements","gravures trollesques","origine des ornements"}},{q="Pourquoi les ornements ont-ils la forme de Gahz'rilla ?",a="Les ornements s’inspirent de Gahz'rilla, une hydre que les trolls vénéraient comme une divinité.",al={"pourquoi des ornements de gahz'rilla","gravures d’hydre","idole de gahz'rilla"}},{q="Où trouver les ornements en Gahz'ridian ?",a="Les ornements en Gahz'ridian sont dispersés dans Tanaris, surtout autour du Pilier brisé, des Ruines d'Estelune et des Ruines de Sudelune.",al={"où trouver les ornements","lieux du gahz'ridian","ornements de tanaris"}}},fp="20,184,15.304.0,34.98.0,28.105.0,35.75.0,45.86.0,39.114.0"}
P.entries["item:gahz-ridian-ornament"] = {n="Gahz'ridian Ornament",s="Les Gahz'ridian Ornaments sont des reliques gravées dispersées dans Tanaris. Marvon Rivetseeker les étudie pour trouver des indices sur les trolls qui vivaient autrefois ici.",h="Les Gahz'ridian Ornaments sont des reliques gravées dispersées dans Tanaris.",kw={"pilier brisé","détecteur","ruines d'estelune","gahz'ridian","gahz'rilla","marvon rivetseeker","ornement","ruines de sudelune","tanaris","trolls"},sec={{t="Reliques gravées",b="Marvon Rivetseeker cherche des Gahz'ridian Ornaments dans Tanaris. Selon lui, les trolls qui occupaient autrefois ce désert les ont gravés à l'image de Gahz'rilla, l'hydre qu'ils vénéraient. Les ornements sont faits d'une substance que Marvon appelle le Gahz'ridian, du nom de cette créature révérée. Il en a déjà rassemblé quelques-uns et en veut davantage pour ses recherches."}},faq={{q="Que sont les Gahz'ridian Ornaments ?",a="Les Gahz'ridian Ornaments sont des gravures réalisées par les trolls qui vivaient autrefois dans Tanaris. Elles représentent Gahz'rilla, une hydre que les trolls vénéraient.",al={"gahz'ridian","qu'est-ce que gahz'ridian","signification des ornements"}},{q="Qui veut les ornements ?",a="Marvon Rivetseeker, un scientifique et chasseur de trésors de Tanaris, veut des Gahz'ridian Ornaments pour ses recherches.",al={"qui veut gahz'ridian","ornements marvon","où rapporter les ornements"}},{q="Où trouver les Gahz'ridian Ornaments ?",a="Les ornements sont dispersés dans Tanaris, notamment autour du Pilier brisé, des Ruines d'Estelune et des Ruines de Sudelune.",al={"emplacements du gahz'ridian","où trouver les ornements","ruines du gahz'ridian"}},{q="Qu'est-ce que Gahz'rilla ?",a="Gahz'rilla est une hydre que les trolls de Tanaris vénéraient comme une divinité. Les ornements sont gravés à son image.",al={"signification de gahz'rilla","dieu hydre","divinité troll"}},{q="À quoi sert le détecteur ?",a="Marvon Rivetseeker a inventé le Gahz'ridian Detector pour aider à trouver les ornements dispersés dans Tanaris.",al={"détecteur de gahz'ridian","chercheur d'ornements","comment trouver gahz'ridian"}}},fp="20,142,13.341.0,31.135.0,24.108.0,39.112.0,19.108.0,25.106.0"}
P.entries["item:gallywix-s-head"] = {n="Tête de Bisbiwix",s="À Orgrimmar, la Main brisée attend la preuve que Puzik Bisbiwix a été tué. Sa tête montrera que le surveillant de la KapitalRisk a été exécuté.",h="À Orgrimmar, la Main brisée attend la preuve que Puzik Bisbiwix a été tué.",kw={"tarides","bisbiwix","orgrimmar","puzik","main brisée","shenthul","la videfange","kapitalrisk"},ang={["class:Rogue"]="En tant que voleur, récupérer la Tête de Bisbiwix prouve votre maîtrise de l’infiltration clandestine, de la furtivité et de l’assassinat ciblé pour la Main brisée.",["faction:Horde"]="En tant que membre de la Horde, vous contribuez à contenir les incursions industrielles prédatrices de la KapitalRisk, qui menacent les frontières des Tarides et de Durotar."},sec={{t="Une sinistre preuve d’élimination",b="Le Grand contremaître Puzik Bisbiwix dirigeait les opérations de la KapitalRisk depuis une tour au nord de la Videfange. Quand la nouvelle est tombée que la KapitalRisk préparait quelque chose à grande échelle, la Main brisée a envoyé des agents démanteler l’installation. Apportez la Tête de Bisbiwix à Shenthul, à Orgrimmar. Elle prouve que le surveillant a été exécuté et confirme la place du voleur au sein de la guilde."},{t="L’incursion à la Videfange",b="L’ordre de prendre la Tête de Bisbiwix exige aussi de voler une cache de mixture altérée de Zanzil et d’éliminer le personnel empoisonné de la tour. Les agents assassinent Bisbiwix au sommet de son perchoir, puis rapportent sa tête à la Faille des Ombres. Cet acte confirme que le grand projet de la KapitalRisk dans les Tarides a été brisé."}},faq={{q="À qui appartient cette tête ?",a="Cette tête appartient au Grand contremaître Puzik Bisbiwix, un superviseur gobelin qui dirige les opérations de la KapitalRisk à la Videfange, dans le nord des Tarides.",al={"qui est bisbiwix","puzik bisbiwix","origine de la tête de bisbiwix"}},{q="Qui veut la Tête de Bisbiwix ?",a="Shenthul veut la Tête de Bisbiwix. C’est un maître des voleurs et un agent de la Main brisée, dans la Faille des Ombres à Orgrimmar.",al={"à qui remettre la tête","remettre la tête de bisbiwix","tête pour shenthul"}},{q="Pourquoi la Main brisée veut-elle sa mort ?",a="Puzik Bisbiwix dirigeait la tour de la KapitalRisk au nord de la Videfange, où la KapitalRisk préparait quelque chose à grande échelle. Il gardait aussi la dernière cache de mixture altérée de Zanzil dans son coffre. La Main brisée l’a condamné à mort pour démanteler l’opération et s’emparer de la mixture.",al={"pourquoi tuer bisbiwix","raison de l’assassinat de bisbiwix"}},{q="Où se trouve Puzik Bisbiwix ?",a="Puzik Bisbiwix se trouve tout en haut de la tour de la KapitalRisk, juste au nord de la Videfange, dans le nord des Tarides.",al={"où se trouve bisbiwix","emplacement de bisbiwix","boss de la tour de la videfange"}}},fx={["862bd188"]={q="D'où vient la Tête de Bisbiwix ?",a="La tête est tranchée du Grand contremaître Puzik Gallywix, un superviseur gobelin supervisant les opérations à la tour de la KapitalRisk au nord de La Videfange dans les Tarides. Chargé par la Main brisée d'infiltrer la place forte et d'éliminer ses habitants, un assassin réclame la tête du contremaître directement sur son cadavre au sommet de la tour comme preuve que l'opération a été décisivement brisée.",al={"où obtenir la tête de bisbiwix","origine tête de bisbiwix","comment obtenir la tête de bisbiwix"}}},fp="15,144,27.371.0,24.322.1,19.152.0,26.119.0,42.285.0,32.117.0"}
P.entries["item:galvanized-horn"] = {n="Corne galvanisée",s="Dans le Val calciné, les armuriers recherchent des Cornes galvanisées prélevées sur des matriarches chimères. Leurs excroissances durcies servent à fabriquer des armures spécialisées pour les guerriers.",h="Dans le Val calciné, les armuriers recherchent des Cornes galvanisées prélevées sur des matriarches chimères.",kw={"le val calciné","matriarche chimère","fire hardened mail","furen barbe-longue","corne galvanisée","orm stonehoof","les serres-rocheuses"},ang={["class:Warrior"]="En tant que guerrier, tuer une matriarche et récupérer sa Corne galvanisée met à l'épreuve votre endurance et votre puissance. Vous prouvez ainsi votre valeur aux maîtres armuriers de Hurlevent ou des Pitons-du-Tonnerre.",["profession:Blacksmithing"]="En tant que forgeron, cette corne montre comment des matériaux organiques durcis dans des conditions extrêmes peuvent égaler, voire surpasser, les métaux ouvrés pour renforcer des armures sur mesure."},sec={{t="Trophée du Val calciné",b="Les matriarches chimères rôdent dans le Val calciné, dans les Serres-Rocheuses. Les cendres, les flammes et la survie durcissent leurs cornes. Les jeunes chimères donnent des cornes noircies et cassantes, mais celles des matriarches sont aussi solides que du métal traité. Furen Barbe-longue, à Hurlevent, et Orm Stonehoof, aux Pitons-du-Tonnerre, en recherchent chacun une comme preuve de valeur martiale et comme composant d'une armure de mailles exceptionnelle."}},faq={{q="D'où vient une Corne galvanisée ?",a="Une Corne galvanisée provient d'une matriarche chimère du Val calciné, dans l'ouest des Serres-Rocheuses.",al={"où trouver la corne galvanisée","comment obtenir la corne galvanisée","butin corne galvanisée"}},{q="Pourquoi les forgerons recherchent-ils cette corne en particulier ?",a="Les maîtres armuriers apprécient la densité de la corne et sa résistance à la chaleur. Ils s'en servent pour renforcer des armures spécialisées en mailles et en plaques.",al={"à quoi sert la corne galvanisée","utilisation corne galvanisée"}},{q="Qui accepte la Corne galvanisée ?",a="Furen Barbe-longue, à Hurlevent, recherche la corne pour fabriquer une armure durcie par le feu destinée aux guerriers de l'Alliance. Orm Stonehoof, aux Pitons-du-Tonnerre, la recherche comme preuve de force et pour façonner un heaume de guerrier destiné à la Horde.",al={"qui a besoin de la corne galvanisée","à qui remettre la corne galvanisée"}},{q="En quoi diffère-t-elle d'une Corne carbonisée ordinaire ?",a="Les Cornes carbonisées ordinaires proviennent de jeunes chimères moins développées. Une Corne galvanisée provient d'une matriarche adulte et possède une structure plus dense et trempée, idéale pour le travail des maîtres forgerons.",al={"corne carbonisée ou corne galvanisée","est-ce différent d'une corne carbonisée"}}},fx={["39b0e048"]={q="Qu'est-ce qu'une Corne galvanisée ?",a="Une Corne galvanisée est une corne rare et durcie prélevée sur une Matriarche chimère habitant les montagnes des Serres-Rocheuses en Kalimdor. Contrairement aux cornes de chimère ordinaires, celle-ci a été endurcie par l'environnement hostile et ravagé par le feu du Val calciné, la rendant exceptionnellement résistante et prisée des maîtres forgerons de l'Alliance comme de la Horde.",al={"identité de la corne galvanisée","qu'est-ce qu'une corne galvanisée","lore de la corne galvanisée"}}},fp="15,140,26.367.0,39.107.0,38.131.0,32.205.0,47.173.0"}
P.entries["item:gan-zulah-s-head"] = {n="Gan'zulah's Head",s="Gan'zulah's Head est prélevée sur le chef des Bloodscalp à Zul'Kunda. Au Campement Grom'gol, elle est apportée à un chaudron bouillonnant dans le cadre des recherches sur Yenniku.",h="Gan'zulah's Head est prélevée sur le chef des Bloodscalp à Zul'Kunda.",kw={"bloodscalp","chaudron","sombrelance","gan'zulah","gan'zulah's head","grom'gol","nimboya","yenniku","zul'kunda"},ang={["faction:Horde"]="En tant que membre de la Horde, vous aidez les Sombrelance au Campement Grom'gol à découvrir la vérité sur Yenniku auprès de leurs ennemis Bloodscalp.",["race:Troll"]="En tant que troll, vous êtes au cœur du conflit entre les Sombrelance et le clan Bloodscalp, dont Nimboya recherche la tête du chef."},sec={{t="La tête d'un chef",b="À Zul'Kunda, dans le nord-ouest de la Vallée de Strangleronce, on recherche Gan'zulah's Head ainsi que la tête de Nezzliok the Dire. Nimboya vous demande de les apporter au chaudron bouillonnant du Campement Grom'gol. Les Sombrelance espèrent que les chefs défunts révéleront la vérité sur Yenniku."}},faq={{q="Qui était Gan'zulah ?",a="Gan'zulah était le chef des trolls Bloodscalp de Zul'Kunda, un ennemi de la tribu Sombrelance.",al={"gan zulah","chef bloodscalp","histoire de gan'zulah"}},{q="D'où vient Gan'zulah's Head ?",a="Gan'zulah's Head est prélevée sur Gan'zulah, dans les Ruines de Zul'Kunda, dans la Vallée de Strangleronce.",al={"d'où vient la tête","emplacement de gan zulah's head","trouver gan'zulah"}},{q="Pourquoi Nimboya veut-il cette tête ?",a="Nimboya veut que Gan'zulah's Head et la tête de Nezzliok soient placées dans le chaudron bouillonnant du Campement Grom'gol, dans l'espoir d'apprendre la vérité sur Yenniku.",al={"pourquoi cette tête","ce que veut nimboya","tête pour nimboya"}},{q="À quoi sert le chaudron ?",a="Les Sombrelance placent les têtes de Gan'zulah et de Nezzliok dans le chaudron, dans l'espoir de faire parler les chefs défunts de Yenniku.",al={"chaudron bouillonnant","chaudron de grom'gol","à quoi sert le chaudron"}},{q="Qui est Yenniku ?",a="Yenniku est un troll Sombrelance dont le sort demeure inconnu de Nimboya et de son peuple.",al={"yenniku","où est yenniku","recherche de yenniku"}}},fp="16,150,14.262.0,18.95.0,38.89.0,31.146.0,25.125.1,15.82.0"}
P.entries["item:gargantuan-tumor"] = {n="Tumeur gargantuesque",s="Dans Teldrassil, on préleva une excroissance sur Oakenscowl, près du Lac Al'Ameth. Sa flétrissure révèle la maladie qui se propage parmi les créatures alentour.",h="Dans Teldrassil, on préleva une excroissance sur Oakenscowl, près du Lac Al'Ameth.",kw={"corruption","tumeur gargantuesque","lac al'ameth","oakenscowl","teldrassil","scion"},ang={["class:Druid"]="En tant que druide veillant sur les jeunes branches de Teldrassil, vous voyez combien la nature y est vulnérable à la corruption révélée par cette tumeur.",["race:NightElf"]="En tant qu’elfe de la nuit, vous voyez un ancien scion respecté réduit à l’état de monstre fou et flétri, signe des problèmes qui menacent votre nouvelle patrie."},sec={{t="Flétrissure du lac",b="Oakenscowl se cache dans une caverne près de la rive sud du Lac Al'Ameth. Autrefois noble ancien scion, il a succombé à une vile affliction. Une énorme excroissance l’a empoisonné et a altéré son comportement. La tumeur a aussi répandu la souillure parmi la faune environnante.\n\nL’excroissance a été tranchée pour mettre fin aux ravages d’Oakenscowl et permettre aux chercheurs locaux de l’étudier. Ils espèrent découvrir comment le mal a pris racine dans les branches du jeune Arbre-Monde."}},faq={{q="D’où vient la Tumeur gargantuesque ?",a="La Tumeur gargantuesque vient d’Oakenscowl, un grand scion corrompu qui vit dans une caverne sur la rive sud du Lac Al'Ameth, à Teldrassil.",al={"origine de la tumeur","obtenir la tumeur gargantuesque","butin d’oakenscowl"}},{q="Qu’est-ce qui fait pousser cette tumeur sur Oakenscowl ?",a="La tumeur révèle l’étrange corruption qui empoisonne les scions et la faune autour du Lac Al'Ameth. Oakenscowl était autrefois un grand chef de son espèce, mais l’excroissance a fini par le submerger.",al={"pourquoi oakenscowl a une tumeur","maladie des scions","corruption du lac al'ameth"}},{q="Qui veut étudier cette tumeur ?",a="Des enquêteurs locaux veulent étudier la tumeur et découvrir comment soigner ou enrayer l’étrange pourriture qui afflige les scions des environs.",al={"qui récupère la tumeur","rendre la tumeur gargantuesque","rendre la quête d’oakenscowl"}}},fx={b9b4574c={q="Qu'est-ce que la Tumeur gargantuesque ?",a="C'est une excroissance massive et grotesque coupée sur Oakenscowl, un ancien sylvaride corrompu qui rôde dans une grotte le long de la rive sud du lac Al'Ameth. La tumeur empoisonne visiblement la créature et la rend folle, alimentant la propagation d'une putréfaction artificielle et d'une affliction à travers les eaux locales et la faune environnante.",al={"qu'est-ce qu'une tumeur gargantuesque","tumeur gargantuesque","tumeur d'oakenscowl"}}},fp="16,140,20.455.0,42.131.0,48.171.0,30.121.0"}
P.entries["item:garrick-s-head"] = {n="Tête de Garrick",s="Dans le Vignoble de Comté-du-Nord, la tête coupée de Garrick Padfoot prouve que le coupe-jarret est mort. Les autorités de l’Abbaye de Comté-du-Nord l’exigent avant de verser la prime.",h="Dans le Vignoble de Comté-du-Nord, la tête coupée de Garrick Padfoot prouve que le coupe-jarret est mort.",kw={"prime","adjoint willem","forêt d’elwynn","garrick padfoot","tête de garrick","abbaye de comté-du-nord","vallée de comté-du-nord"},ang={["class:Rogue"]="En tant que voleur, éliminer Padfoot montre aux voyous du coin que le banditisme se heurte à des lames meurtrières maniées par des professionnels.",["race:Human"]="En tant qu’humain, rapporter la tête de Padfoot porte un premier coup à l’anarchie qui se répand dans la Forêt d’Elwynn."},sec={{t="La fin d’un bandit",b="Pendant des semaines, Garrick Padfoot et sa bande ont harcelé les fermiers et les marchands de la Vallée de Comté-du-Nord. Les défenses de Hurlevent étaient mises à rude épreuve, et les gardes locaux étaient occupés par les kobolds et les bandits Defias. Garrick s’est donc caché dans une cabane près du vignoble et a attaqué les caravanes de passage. L’Adjoint Willem a offert une prime pour la mort du hors-la-loi, en quête de quelqu’un pour le tuer et rapporter une preuve."}},faq={{q="Qui était Garrick Padfoot ?",a="Garrick Padfoot était un coupe-jarret qui terrorisait les fermiers, les ouvriers viticoles et les marchands itinérants de la Vallée de Comté-du-Nord. Il a établi un avant-poste avec sa bande à l’est de l’Abbaye de Comté-du-Nord, de l’autre côté de la rivière.",al={"qui est garrick","histoire de garrick padfoot","qui était padfoot"}},{q="Pourquoi faut-il une tête coupée pour toucher la prime ?",a="L’Adjoint Willem et les autorités de Comté-du-Nord exigent une preuve de la mort de Garrick avant de verser la prime.",al={"pourquoi sa tête","preuve de sa mort","pourquoi rapporter la tête de garrick"}},{q="Où Garrick Padfoot se cachait-il ?",a="Padfoot se cachait dans une petite cabane en bois à l’est de l’Abbaye de Comté-du-Nord, de l’autre côté du pont sur la rivière, près du Vignoble de Comté-du-Nord.",al={"où est garrick","emplacement de la cabane de garrick","où trouver garrick padfoot"}},{q="Qui verse la prime pour la tête de Garrick ?",a="L’Adjoint Willem a proposé la prime et la verse lorsqu’il reçoit la tête de Garrick. Il est posté juste devant l’entrée de l’Abbaye de Comté-du-Nord.",al={"qui veut la tête de garrick","où remettre la tête de garrick","qui a rapporté la tête de garrick"}}},fx={cb1a40d1={q="Qu'est-ce que la Tête de Garrick ?",a="Cette tête tranchée est la preuve macabre de la disparition de Garrick Padfoot, un coupe-jarret notoire qui a terrorisé les fermiers et marchands locaux à travers la vallée de Comté-du-Nord. Rapporter ce trophée à l'abbaye confirme que sa bande de brigands a perdu son chef.",al={"qu'est-ce que la tête de garrick","objet tête de garrick","à qui appartient cette tête"}},["79b2de99"]={q="D'où vient la Tête de Garrick ?",a="Elle est réclamée directement auprès de Garrick Padfoot lui-même. Ce Voleur a établi son campement dans une petite cahute nichée près du vignoble de Comté-du-Nord, de l'autre côté de la rivière à l'est, entouré de sbires loyaux protégeant son butin.",al={"où obtenir la tête de garrick","qui laisse tomber la tête de garrick","source de la tête de garrick"}}},fp="14,162,14.369.0,24.197.0,51.103.0,33.116.0,39.134.0"}
P.entries["item:gazlowe-s-ledger"] = {n="Grand livre de Gazleu",s="Une cargaison de Baie-du-Butin a disparu, et Gazlowe compare ses registres au manifeste du port de Cabestan.",h="Une cargaison de Baie-du-Butin a disparu, et Gazlowe compare ses registres au manifeste du port de Cabestan.",kw={"baie-du-butin","dizzywig","southsea freebooters","gazlowe","grand livre","cabestan","cargaison","steamwheedle"},ang={["class:Rogue"]="En tant que voleur, vous pouvez entrevoir les échanges de contrebande, les importations de valeur et la piraterie sur la côte des Tarides dans le registre commercial privé d'un patron gobelin.",["faction:Horde"]="En tant que membre de la Horde, vous pouvez commercer à Cabestan, un port neutre. Aidez Gazlowe à retrouver les cargaisons volées et à préserver de bonnes relations avec les autorités locales de Steamwheedle."},sec={{t="Registres commerciaux de Cabestan",b="Gazlowe tient un registre personnel des marchandises à Cabestan. Il recense les caisses importées, les cargaisons expédiées et les stocks entreposés. Lorsqu'une cargaison de Baie-du-Butin disparaît, il compare les marchandises attendues aux registres du quai tenus par Wharfmaster Dizzywig."},{t="Découvrir le vol",b="Gazlowe et les autres gobelins comparent le grand livre aux registres portuaires de Dizzywig. La cargaison n'a jamais atteint l'entrepôt du port de Cabestan, ce qui confirme les soupçons de Gazlowe : les caisses ont été prises avant d'arriver à terre. Les Southsea Freebooters, qui rôdent le long de La Côte des marchands toute proche, sont en cause."}},faq={{q="Qu'est-ce que le Grand livre de Gazleu ?",a="Le Grand livre de Gazleu recense les marchandises attendues et entreposées à Cabestan. Lorsqu'une cargaison disparaît, Gazlowe l'envoie aux quais pour comparer ses entrées aux registres portuaires.",al={"grand livre de gazleu","registre de cabestan","livre d'inventaire de gazlowe"}},{q="Qui doit examiner le grand livre ?",a="Wharfmaster Dizzywig compare le Grand livre de Gazleu à ses registres d'expédition. Il supervise les quais de Cabestan et peut déterminer si des marchandises ont été égarées ou n'ont jamais été déchargées.",al={"à qui remettre le grand livre","destinataire du grand livre","grand livre de dizzywig"}},{q="Quelle cargaison manquait dans le grand livre ?",a="Gazlowe attendait sa dernière cargaison de Baie-du-Butin. Dizzywig ne relève rien d'anormal dans ses registres, mais des marchandises venues d'Undermine attendent que Gazlowe vienne les récupérer.",al={"que manque-t-il à gazlowe","cargaison manquante"}},{q="Que se passe-t-il après la vérification du grand livre ?",a="Dizzywig vérifie si la cargaison est passée par les quais. Lorsqu'il découvre que ce n'est pas le cas, le grand livre retourne à Gazlowe, confirmant que les Southsea Freebooters ont probablement intercepté la cargaison en mer.",al={"que devient le grand livre","après la vérification de dizzywig"}}},fx={d44950a4={q="D'où vient le Grand livre de Gazleu et qui le détient ?",a="Ce Grand livre de Gazleu appartient à Gazlowe, le chef gobelin supervisant la ville portuaire de Cabestan. Il sert de registre d'inventaire personnel, documentant le fret entrant et sortant expédié à travers la Grande mer entre Cabestan et d'autres centres commerciaux gobelins comme Baie-du-Butin.",al={"qui a créé le grand livre de gazleu","d'où vient le grand livre de gazleu","origine du grand livre de gazleu"}},c4547cde={q="Pourquoi le Grand livre de Gazleu est-il nécessaire en ce moment ?",a="Gazlowe soupçonne qu'une cargaison provenant de Baie-du-Butin, arrivée avec un long retard, a été volée par les Southsea Freebooters. Avant de tirer des conclusions hâtives, il a besoin que vous portiez son Grand livre de Gazleu jusqu'au maître de quai Dizzywig sur les docks pour comparer les registres d'inventaire avec les journaux du port et écarter toute erreur administrative.",al={"pourquoi vouloir le grand livre de gazleu","pourquoi avoir besoin du grand livre de gazleu","à quoi sert le grand livre de gazleu"}}},fp="16,103,28.271.0,20.278.1,25.169.0,32.170.0,37.165.0,41.193.1"}
P.entries["item:gem-of-anacondra"] = {n="Gemme d'Anacondra",s="Dans les Cavernes des lamentations, Dame Anacondra porte l’une des quatre gemmes du Rêve. Ces pierres sont détenues par les chefs serpents corrompus et liées au cauchemar qui gagne les Tarides.",h="Dans les Cavernes des lamentations, Dame Anacondra porte l’une des quatre gemmes du Rêve.",kw={"gemme du rêve","druides du croc","gemme d'anacondra","dame anacondra","leaders of the fang","nara wildmane","cavernes des lamentations"},ang={["class:Druid"]="En tant que druide cénarien, vous avez le devoir solennel d’abattre une sœur qui a livré son esprit et ses formes au Cauchemar d’émeraude corrupteur.",["race:Tauren"]="En tant que tauren, vous aidez Nara Wildmane de Pitons-du-Tonnerre en récupérant la gemme. Alors, les sombres visions qui troublent le sommeil des Shu’halo sur la Cime des Anciens pourraient se dissiper."},sec={{t="Un foyer corrompu",b="Lorsque Naralex sombra dans un profond sommeil, il cherchait à ramener l’eau et la vie dans les Tarides arides. Puis le Cauchemar d’émeraude s’insinua dans ses pensées et pervertit ses disciples les plus proches. Dame Anacondra et ses complices abandonnèrent leurs anciennes voies pour devenir les druides du Croc. Leur but était de restaurer la terre, mais il se mua en une illusion toxique.\n\nDame Anacondra porte l’une des quatre gemmes du Rêve détenues par ces chefs serpents. La gemme concentre leur lien corrompu avec le Rêve d’émeraude et ancre le cauchemar dans le réseau de cavernes."},{t="Purifier la vision",b="Nara Wildmane et les druides cénariens de Pitons-du-Tonnerre sont tourmentés par des visions dans leur sommeil. Les visages malfaisants des chefs du Croc les hantent. Ils réclament la Gemme d’Anacondra et les pierres de Cobrahn, Pythas et Serpentis pour confirmer que Dame Anacondra a été abattue. Réunissez-les toutes les quatre, et le cauchemar oppressant pourra quitter l’esprit des gardiens de l’équilibre de Kalimdor."}},faq={{q="Qu’est-ce que la Gemme d’Anacondra ?",a="Dame Anacondra porte la Gemme d’Anacondra dans les Cavernes des lamentations. C’est l’une des quatre gemmes du Rêve détenues par les chefs des druides du Croc corrompus.",al={"qu’est-ce que la gemme d’anacondra","gemme d’anacondra","à quoi sert la gemme d’anacondra"}},{q="Qui veut cette gemme ?",a="Nara Wildmane, une druidesse tauren de la Cime des Anciens à Pitons-du-Tonnerre, recherche cette gemme et les trois autres gemmes du Rêve. Elle espère libérer son esprit des cauchemars et protéger les Tarides.",al={"qui prend la gemme d’anacondra","où rendre la gemme d’anacondra","rendre la gemme d’anacondra"}},{q="Où trouver la Gemme d’Anacondra ?",a="Dame Anacondra porte la gemme dans les tunnels souterrains sinueux des Cavernes des lamentations, au centre des Tarides.",al={"où est-elle obtenue","qui fait tomber la gemme d’anacondra","emplacement de dame anacondra"}},{q="Pourquoi les gemmes du Rêve sont-elles importantes ?",a="Les chefs corrompus des druides du Croc détiennent les quatre gemmes. Les réunir confirme que les meneurs ont été éliminés et brise leur emprise sur la corruption du Rêve d’émeraude dans la région.",al={"pourquoi quatre gemmes","rôle des gemmes du rêve","gemmes des leaders of the fang"}}},fx={["2e0de493"]={q="D'où vient la Gemme d'Anacondra et qui l'a fabriquée ?",a="La gemme est portée par Dame Anacondra au plus profond des Cavernes des lamentations. Bien que le maître exact qui l'a taillée ou enchantée soit inconnu, elle sert de gemme de rêve détenue par les quatre chefs des Druides du Croc. Autrefois membres d'un noble cercle dédié à la guérison des Tarides, ces elfes de la nuit corrompus canalisent désormais leurs visions tordues du Rêve d'émeraude dans ces pierres.",al={"origine de la gemme d'anacondra","qui a fabriqué la gemme d'anacondra","où anacondra a-t-elle obtenu sa gemme"}}},fp="16,175,17.541.0,20.369.1,29.153.0,19.180.0,40.112.0,33.201.0"}
P.entries["item:gem-of-cobrahn"] = {n="Gemme de Cobrahn",s="Dans les Cavernes des lamentations, le Seigneur Cobrahn porte une gemme de rêve façonnée par la corruption. Nara Wildmane en a besoin comme preuve de sa défaite.",h="Dans les Cavernes des lamentations, le Seigneur Cobrahn porte une gemme de rêve façonnée par la corruption.",kw={"gemme de rêve","druides du croc","gemme de cobrahn","leaders of the fang","seigneur cobrahn","nara wildmane","cavernes des lamentations"},ang={["class:Druid"]="En tant que druide cénarien, reprendre la Gemme de Cobrahn marque la fin tragique, mais nécessaire, d'un frère déchu qui a abandonné l'harmonie de la nature pour le Cauchemar d'émeraude.",["race:Tauren"]="En tant que Tauren, vous savez que les druides de Pitons-du-Tonnerre surveillent de près les Tarides. Prendre directement la gemme de Cobrahn protège les plaines et les terrains de chasse de la corruption contre nature."},sec={{t="Un foyer de rêves corrompus",b="Naralex pénétra dans le Rêve d'émeraude pour restaurer les plaines arides de Kalimdor. Son cauchemar déforma les Cavernes des lamentations et détourna ses disciples de leur objectif. Cobrahn abandonna les voies pacifiques du Cercle cénarien et prit la forme d'un serpent. Il porte désormais l'une des quatre gemmes de rêve qui ancrent l'emprise des Leaders of the Fang sur les voies navigables souterraines. Grâce à elle, il canalise des rêves déformés qui menacent de transformer les Tarides en marécage venimeux."},{t="Rétablir l'équilibre",b="Nara Wildmane, une druide taurène de Pitons-du-Tonnerre, souffre des cauchemars envoyés par les druides du Croc renégats. Elle cherche à purifier les sources souterraines et à protéger Kalimdor de leur vision. Le Seigneur Cobrahn et ses trois conspirateurs détiennent chacun une gemme de rêve. Rapporter la gemme de Cobrahn aux druides cénariens met fin à son influence corruptrice sur Naralex endormi."}},faq={{q="Qu'est-ce que la Gemme de Cobrahn ?",a="Dans les Cavernes des lamentations, le Seigneur Cobrahn porte la Gemme de Cobrahn. Cette gemme de rêve canalise le pouvoir déformé par son cauchemar.",al={"gemme de cobrahn","qu'est-ce que la gemme de cobrahn"}},{q="Qui veut la Gemme de Cobrahn ?",a="Nara Wildmane, une druide taurène de la Cime des Anciens, à Pitons-du-Tonnerre, veut la Gemme de Cobrahn et trois autres gemmes pour mettre fin aux druides du Croc.",al={"qui a besoin de la gemme de cobrahn","remettre la gemme de cobrahn","qui récupère la gemme de cobrahn"}},{q="Combien de gemmes faut-il pour terminer la quête ?",a="Il faut quatre gemmes : la Gemme de Cobrahn, la Gemme d'Anacondra, la Gemme de Pythas et la Gemme de Serpentis. Chacune est détenue par l'un des quatre chefs serpents des cavernes.",al={"combien de gemmes de rêve","gemmes des leaders of the fang","toutes les gemmes du croc"}},{q="Qui est le Seigneur Cobrahn ?",a="Le Seigneur Cobrahn était autrefois un disciple de Naralex. Quand la vision de Naralex devint un cauchemar, Cobrahn et plusieurs autres druides prirent une forme de serpent et fondèrent les druides du Croc.",al={"qui est cobrahn","histoire du seigneur cobrahn","cobrahn"}}},fp="14,123,27.439.0,17.357.1,27.116.0,29.138.0,47.172.0,20.172.0"}
P.entries["item:gem-of-pythas"] = {n="Gemme de Pythas",s="Dans les Cavernes des lamentations, le Seigneur Pythas détient l'une des quatre gemmes de rêve corrompues. Ensemble, elles alimentent le cauchemar qui déforme l'oasis souterraine et menace les Tarides.",h="Dans les Cavernes des lamentations, le Seigneur Pythas détient l'une des quatre gemmes de rêve corrompues.",kw={"tarides","gemme de rêve","druids of the fang","gemme de pythas","seigneur pythas","nara wildmane","cavernes des lamentations"},ang={["class:Druid"]="En tant que druide cénarien, retrouver la gemme est un devoir solennel. Elle témoigne de la chute des proches de Naralex, devenus des abominations serpentines.",["race:Tauren"]="En tant que tauren, vous savez que les rites dévoyés des cavernes menacent le fragile équilibre des Tarides. Récupérer ces gemmes est essentiel pour protéger la patrie de vos chamans et de vos druides."},sec={{t="Un réceptacle du cauchemar",b="Naralex est entré dans le Rêve d'émeraude pour restaurer les Tarides arides. Là, sa vision est devenue un cauchemar vivant. Ses plus proches disciples ont sombré avec lui et sont devenus les Druids of the Fang. À présent, ils cherchent à transformer le monde de la surface en une jungle venimeuse.\n\nLe Seigneur Pythas détient l'une des quatre gemmes de rêve qui ancrent la corruption dans les cavernes. La pierre canalise les desseins obscurs des druides. Elle prouve aussi aux druides de Pitons-du-Tonnerre que la transe déviante de Pythas a été rompue."}},faq={{q="À quoi sert la Gemme de Pythas ?",a="Apportez la gemme à Nara Wildmane, à Pitons-du-Tonnerre, avec celles de Cobrahn, d'Anacondra et de Serpentis. Ensemble, les quatre gemmes achèvent le travail qui met fin aux agissements des chefs renégats des Druids of the Fang.",al={"utilité de la gemme de pythas","que faire de la gemme de pythas","quête de la gemme de pythas"}},{q="Qui porte cette gemme ?",a="Le Seigneur Pythas porte la gemme. C'est un druide elfe de la nuit déchu qui vit au plus profond des Cavernes des lamentations, dans les Tarides.",al={"qui lâche la gemme de pythas","emplacement de pythas","où trouver la gemme de pythas"}},{q="Pourquoi les druides de Pitons-du-Tonnerre veulent-ils la gemme ?",a="La corruption des Cavernes des lamentations hante Nara Wildmane et les druides cénariens de Pitons-du-Tonnerre. Récupérer les gemmes prouve que les quatre chefs dévoyés ont été tués et endigue le cauchemar avant qu'il ne se répande davantage dans les Tarides.",al={"pourquoi nara veut les gemmes","nara wildmane et pythas"}},{q="Existe-t-il d'autres gemmes comme celle-ci ?",a="Oui. Chacun des quatre chefs porte une gemme de rêve au fond des cavernes. Les autres sont Dame Anacondra, le Seigneur Cobrahn et le Seigneur Serpentis.",al={"autres gemmes de rêve","gemmes des crocs","gemmes des cavernes des lamentations"}}},fx={["3d8d64d3"]={q="Qu'est-ce que la Gemme de Pythas ?",a="La Gemme de Pythas est l'une des quatre gemmes de rêve portées par les chefs des Druides du Croc au sein des Cavernes des lamentations. Détenue par le Seigneur Pythas, cette relique incarne la sombre folie serpentine qui a corrompu ces elfes de la nuit autrefois nobles, liant leurs visions tordues du Rêve d'émeraude sous une forme physique.",al={"gemme de pythas","qu'est-ce que la gemme de pythas","qu'est-ce que cette gemme"}}},fp="13,170,25.468.0,35.195.0,21.114.0,48.234.0,35.134.0"}
P.entries["item:gem-of-serpentis"] = {n="Gemme de Serpentis",s="Au fond des Cavernes des lamentations, le Seigneur Serpentis garde la Gemme de Serpentis près de lui. Cette gemme de rêve enchantée lie sa volonté à la vision corrompue qui remodèle les cavernes et menace les Tarides.",h="Au fond des Cavernes des lamentations, le Seigneur Serpentis garde la Gemme de Serpentis près de lui.",kw={"druids of the fang","gemme de serpentis","leaders of the fang","seigneur serpentis","nara wildmane","les tarides","cavernes des lamentations"},ang={["class:Druid"]="En tant que druide, vous percevez le danger que représentent Serpentis et les gemmes de rêve de sa cabale. Communier profondément avec le Rêve exige une vigilance et une discipline spirituelles constantes.",["race:Tauren"]="En tant que tauren, vous savez que briser l’emprise de Serpentis sur la gemme aide à libérer les chamans et les druides des Pitons-du-Tonnerre des visions sombres qui troublent leur sommeil à Mulgore."},sec={{t="Au cœur du rêve serpentin",b="Naralex sombra dans le sommeil dans les Cavernes des lamentations, où le Cauchemar d’émeraude le rejoignit. Ses disciples les plus dévoués devinrent les fanatiques Druids of the Fang. Le Seigneur Serpentis dirige une partie de la cabale, aux côtés de trois autres chefs. Chacun porte une gemme de rêve enchantée qui lie leur volonté commune à la vision corrompue. Récupérer la gemme de Serpentis brise son emprise sur la vie des cavernes et frappe les chefs qui dirigent la corruption à travers les Tarides."},{t="Une preuve pour les Pitons-du-Tonnerre",b="Les druides taurens de la Cime des Anciens, aux Pitons-du-Tonnerre, sont en proie à de terribles cauchemars causés par la corruption sous la savane. Nara Wildmane en fait partie. Les gemmes de Serpentis, Cobrahn, Anacondra et Pythas prouvent que les chefs de l’ordre dissident ont succombé. Les récupérer atténue l’emprise du cauchemar sur le Cercle cénarien à Mulgore."}},faq={{q="D’où vient la Gemme de Serpentis ?",a="Le Seigneur Serpentis porte la gemme au fond des voies sinueuses des Cavernes des lamentations. Il est l’un des quatre chefs des Druids of the Fang.",al={"qui laisse tomber la gemme de serpentis","où trouver la gemme de serpentis","emplacement de la gemme de serpentis"}},{q="À quoi sert la gemme ?",a="Cette gemme est l’une des quatre que les chefs des Druids of the Fang utilisent pour canaliser le cauchemar qui déforme l’oasis souterraine. Nara Wildmane, aux Pitons-du-Tonnerre, la cherche pour prouver la défaite du Seigneur Serpentis.",al={"pourquoi avoir la gemme de serpentis","à quoi sert la gemme de serpentis"}},{q="Qui veut les quatre gemmes de rêve ?",a="Nara Wildmane vous demande de lui apporter les gemmes de Cobrahn, Anacondra, Pythas et Serpentis. C’est une druide de la Cime des Anciens, aux Pitons-du-Tonnerre. Ensemble, ces gemmes peuvent libérer la région de l’emprise du cauchemar.",al={"qui récupère les gemmes","rendre la gemme de serpentis","rendre les gemmes des leaders of the fang"}},{q="Qui était le Seigneur Serpentis avant de porter cette gemme ?",a="Le Seigneur Serpentis était autrefois un disciple de Naralex qui entra dans les cavernes pour rendre leur végétation luxuriante aux Tarides. Le Cauchemar d’émeraude pervertit ses espoirs et fit naître en lui le désir fanatique de remodeler le monde à l’image des serpents.",al={"histoire du seigneur serpentis","qui est serpentis"}}},fx={["58ca37b7"]={q="Qu'est-ce que la Gemme de Serpentis ?",a="La Gemme de Serpentis est l'une des quatre gemmes de rêve détenues par les chefs des Druides du Croc au sein des Cavernes des lamentations. Portée par le Seigneur Serpentis lui-même, elle sert d'emblème et d'instrument aux druides corrompus qui cherchent à tordre les Tarides pour qu'elles correspondent à leurs sombres visions.",al={"lore de la gemme de serpentis","qu'est-ce que la gemme de serpentis","gemme du seigneur serpentis"}}},fp="16,191,29.465.0,23.330.1,42.141.0,31.209.0,30.208.0,48.207.0"}
P.entries["item:gem-of-the-serpent"] = {n="Gemme du serpent"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Bras mécanique de Gerenzo",s="Dans les Serres-Rocheuses, des agents gobelins cherchent le Bras mécanique de Gerenzo pour prouver sa mort et éliminer la concurrence. Ce membre greffé appartenait à l’ingénieur renégat Gerenzo Wrenchwhistle.",h="Dans les Serres-Rocheuses, des agents gobelins cherchent le Bras mécanique de Gerenzo pour prouver sa mort et...",kw={"bras","lac de la combe","gerenzo","bras mécanique","krachevalve","les serres-rocheuses","wrenchwhistle","ziz fizziks"},ang={["profession:Engineering"]="Le bras illustre deux traditions d’ingénierie différentes. Les gnomes sacrifient volontiers leur propre biologie au profit de la précision mécanique, tandis que les gobelins privilégient les ajouts externes et la puissance de feu brute.",["race:Gnome"]="Gerenzo incarne un sombre excès de l’ingéniosité gnome. Il a poussé le remplacement mécanique bien au-delà des prothèses médicales conventionnelles, jusqu’à une augmentation corporelle morbide."},sec={{t="Une invention étrange",b="Au-dessus du lac de la Combe, l’ingénieur renégat Gerenzo Wrenchwhistle greffa des engrenages vrombissants et du métal sur son corps défaillant. Le gnome renégat remplaça ses membres naturels par une machinerie complexe. Le bricoleur gobelin Ziz Fizziks veut éliminer Gerenzo pour impressionner ses supérieurs. Ce bras distinctif est la preuve de la mort de l’ingénieur dont il a besoin."},{t="Philosophie gnome, critique gobeline",b="Ziz Fizziks ne voit guère l’intérêt de couper un bras fonctionnel pour le remplacer par un bras mécanique. Selon lui, un véritable ingénieur gobelin garderait ses deux bras naturels et s’en ferait greffer un troisième, mécanique. Malgré tout, rapporter le membre tranché satisfait Krachevalve. Cela aide aussi Ziz à demander une affectation à Gadgetzan ou à Terremine."}},faq={{q="D’où vient le Bras mécanique de Gerenzo ?",a="Gerenzo Wrenchwhistle supervise les opérations d’exploitation forestière et d’ingénierie, en hauteur au-dessus du lac de la Combe, près de la roue à eau dans les Serres-Rocheuses. Le bras vient de lui.",al={"qui fait tomber le bras de gerenzo","emplacement du bras de gerenzo","où trouver le bras mécanique de gerenzo"}},{q="Pourquoi Ziz Fizziks veut-il ce bras ?",a="Ziz Fizziks a besoin d’une preuve à remettre à son supérieur, Krachevalve, que Gerenzo est mort. La prothèse unique de Gerenzo ne peut être ni contrefaite ni confondue avec celle de quelqu’un d’autre.",al={"pourquoi ziz veut le bras","où rendre la quête du bras","preuve de la mort de gerenzo"}},{q="Pourquoi Gerenzo a-t-il remplacé son propre bras ?",a="Selon Ziz Fizziks, la chair de Gerenzo semblait pourrir. Gerenzo greffa de la machinerie sur son corps et remplaça ses membres défaillants par des équivalents mécaniques, par désespoir ou par obsession pour l’expérimentation gnome.",al={"pourquoi gerenzo est un cyborg","chair de gerenzo en décomposition","pourquoi un bras mécanique"}}},fx={["379afa91"]={q="Qu'est-ce que le Bras mécanique de Gerenzo ?",a="Il s'agit de la prothèse cybernétique rudimentaire greffée directement sur le corps de Gerenzo Wrenchwhistle, un contremaître gnome malade rôdant près de la roue à aubes au-dessus du lac de la Combe. Plutôt que de vivre avec de la chair naturelle, Gerenzo a augmenté son corps en putréfaction avec des rouages d'horlogerie et un placage métallique, faisant de ce membre mécanique complexe son trait le plus reconnaissable.",al={"qu'est-ce que le bras de gerenzo","objet bras de gerenzo","bras mécanique de gerenzo"}}},fp="24,189,19.329.0,35.317.1,46.165.0,35.157.0,36.221.0"}
P.entries["item:ghost-hair-comb"] = {n="Peigne fantôme",s="Au Bois de la Pénombre, Madame Eva envoie à Marie l'aveugle le Peigne fantôme, dont les dents retiennent ses cheveux spectraux.",h="Au Bois de la Pénombre, Madame Eva envoie à Marie l'aveugle le Peigne fantôme, dont les dents retiennent ses...",kw={"marie l'aveugle","sombre-comté","bois de la pénombre","peigne fantôme","mèche de cheveux fantômes","madame eva"},ang={["class:Priest"]="En tant que prêtre, vous percevez la vanité mortelle et le profond tourment spirituel dans le rejet angoissé du peigne par Marie. Ce tourment est familier aux morts agités du Bois de la Pénombre.",["profession:Tailoring"]="En tant que couturier, vous reconnaissez le textile étrange que forment les mèches prises dans le peigne. Elles sont filées à partir d'un chagrin spectral, et non de laine de mouton ou de soie."},sec={{t="Une vanité tragique",b="Madame Eva envoie le Peigne fantôme de Sombre-Comté à Marie l'aveugle, qui vit dans une demeure isolée et délabrée aux confins du Bois de la Pénombre. À sa vue, le fantôme recule d'horreur. Marie doit accepter qu'elle n'est plus la belle femme vivante dont elle se souvient. Accablée de chagrin, elle repousse le peigne, laissant des mèches de ses cheveux spectraux emmêlées dans ses dents."},{t="Filé dans le chagrin",b="Madame Eva reçoit le Peigne fantôme à Sombre-Comté, avec les cheveux spectraux de Marie l'aveugle encore pris entre ses dents. Eva recueille les délicates mèches et les file pour en faire une Mèche de cheveux fantômes. Dans le royaume ombrageux du Bois de la Pénombre, ce fil mystique sert à coudre et à lier des créations occultes."}},faq={{q="Qu'est-ce que le Peigne fantôme ?",a="Madame Eva de Sombre-Comté envoie le Peigne fantôme à Marie l'aveugle, un esprit. Le peigne retient des mèches de ses cheveux spectraux, qu'Eva file pour en faire une Mèche de cheveux fantômes.",al={"peigne fantôme","à quoi sert ce peigne","peigne d'eva"}},{q="Pourquoi Marie l'aveugle crie-t-elle et rejette-t-elle le peigne ?",a="Marie l'aveugle rejette le peigne parce qu'il lui rappelle la beauté mortelle qu'elle a perdue. Il l'oblige à voir qu'elle est désormais un monstre spectral terrifiant, et non la belle femme dont elle se souvient de son vivant.",al={"pourquoi marie l'aveugle crie","réaction de marie l'aveugle au peigne","pourquoi marie a jeté le peigne"}},{q="À qui faut-il rendre le peigne ?",a="Madame Eva, la devineresse et mage des campagnes qui vit à Sombre-Comté, réclame le Peigne fantôme pour recueillir les cheveux fantomatiques qu'il retient.",al={"qui veut le peigne","où apporter le peigne","à qui rendre le peigne"}},{q="À quoi servent les cheveux fantomatiques ?",a="Madame Eva file les mèches spectrales pour en faire une Mèche de cheveux fantômes. Dans le Bois de la Pénombre, cette matière inhabituelle sert aux rituels occultes et à l'artisanat.",al={"utilité des cheveux fantomatiques","qu'est-ce que la mèche de cheveux fantômes","utilité de la mèche de cheveux fantômes"}}},fp="15,113,15.349.0,16.279.1,28.162.0,47.204.0,28.134.0,32.135.0"}
P.entries["item:ghost-hair-thread"] = {n="Mèche de cheveux fantômes",s="À Sombre-Comté, Madame Eva file des Mèches de cheveux fantômes venues du monde des esprits. Leur pouvoir occulte peut lier les esprits ou insuffler la vie à des objets inanimés. Abercrombie en demande pour protéger sa masure des fantômes agités.",h="À Sombre-Comté, Madame Eva file des Mèches de cheveux fantômes venues du monde des esprits.",kw={"abercrombie","sombre-comté","bois de la pénombre","mèche de cheveux fantômes","madame eva","colline-aux-corbeaux","esprits"},ang={["class:Warlock"]="En tant que démoniste, vous reconnaîtrez peut-être dans le pouvoir de cette mèche, qui lie les esprits et donne vie à la matière inanimée, les arts sombres de la manipulation des âmes et de l'asservissement des constructions.",["profession:Tailoring"]="Les couturiers travaillent généralement la laine, la soie et la tisse-mage. Le fil fantomatique de Madame Eva montre que des essences surnaturelles peuvent aussi être filées en un tissu capable de retenir des enchantements."},sec={{t="Filée dans le monde des esprits",b="Madame Eva file à Sombre-Comté la Mèche de cheveux fantômes, un fil spectral aux pouvoirs étranges. Selon Eva, il peut lier les esprits malveillants ou insuffler de la vitalité aux objets inanimés. Dans le Bois de la Pénombre, on l'utilise pour les rituels et les protections."},{t="La protection d'Abercrombie",b="Abercrombie vit dans une masure délabrée, juste au nord du Cimetière de Colline-aux-Corbeaux. L'ermite demande aux voyageurs de lui apporter de la Mèche de cheveux fantômes depuis Sombre-Comté. Il dit qu'il doit en tendre sur ses fenêtres et son encadrement de porte pour empêcher les morts-vivants errants d'entrer chez lui. Que pourrait faire d'autre cette mèche ?"}},faq={{q="Qu'est-ce que la Mèche de cheveux fantômes ?",a="Madame Eva file la Mèche de cheveux fantômes à Sombre-Comté. Son pouvoir occulte peut lier les esprits ou insuffler la vie à des objets inanimés.",al={"cheveux fantômes","qu'est-ce que la mèche de cheveux fantômes","fil fantôme"}},{q="Pourquoi Abercrombie veut-il de la Mèche de cheveux fantômes ?",a="Abercrombie dit qu'il doit tendre de la Mèche de cheveux fantômes sur ses fenêtres et sa porte pour repousser les esprits agités près du Cimetière de Colline-aux-Corbeaux.",al={"fil d'abercrombie","pourquoi abercrombie veut du fil","protection d'abercrombie"}},{q="Qui file cette mèche ?",a="Madame Eva, la voyante de Sombre-Comté, file la mèche et la fournit sur demande.",al={"qui file la mèche de cheveux fantômes","fil de madame eva"}},{q="Les joueurs peuvent-ils utiliser cette mèche en couture ?",a="Non. La Mèche de cheveux fantômes ne peut pas servir dans les recettes de couture habituelles. Elle est destinée à Abercrombie.",al={"couture avec la mèche de cheveux fantômes","peut-on fabriquer avec la mèche de cheveux fantômes"}}},fp="17,214,24.220.0,18.290.1,26.120.0,44.129.0,21.86.0,41.96.0"}
P.entries["item:ghost-o-plasm"] = {n="Ghost-o-Plasm",s="Ghost-o-Plasm est une énergie spectrale recueillie auprès des Magrami Spectres en Désolace. Hornizz Brimbuzzle espère la vendre aux centaures Magram.",h="Ghost-o-Plasm est une énergie spectrale recueillie auprès des Magrami Spectres en Désolace.",kw={"énergie spectrale","ghost-o-plasm","ghostoplasm","hornizz brimbuzzle","aimant","centaures magram","spectres magrami","vallée des ossements"},ang={["faction:Horde"]="En tant que membre de la Horde, vous aidez Hornizz à négocier avec les centaures Magram en leur proposant un étrange commerce d’énergie spectrale.",["race:Gnome"]="En tant que gnome, vous reconnaîtrez peut-être l’ingéniosité des aimants à fantômes de Hornizz, mais son plan dépend du prix que les centaures Magram accepteront de payer."},sec={{t="Récolté dans la vallée",b="Entre les deux grands squelettes appelés les Dead Goliaths, une caisse d’aimants à fantômes attire les Magrami Spectres de la Vallée des Ossements. Leur Ghost-o-Plasm, voilà ce que veut Hornizz Brimbuzzle. Il espère que les centaures Magram le paieront cher, mais il doit encore les convaincre de la nature de cette étrange substance."}},faq={{q="Qu’est-ce que Ghost-o-Plasm ?",a="Ghost-o-Plasm est une énergie spectrale prélevée sur les Magrami Spectres en Désolace.",al={"ghost-o-plasm","substance fantomatique","qu’est-ce que cette substance visqueuse"}},{q="Où trouver Ghost-o-Plasm ?",a="Les Magrami Spectres de la Vallée des Ossements fournissent du Ghost-o-Plasm lorsqu’une caisse d’aimants à fantômes les attire.",al={"où trouver ghost-o-plasm","obtenir ghost-o-plasm","lieu où trouver la substance fantomatique"}},{q="Qui veut du Ghost-o-Plasm ?",a="Hornizz Brimbuzzle veut du Ghost-o-Plasm et espère le vendre aux centaures Magram.",al={"qui a besoin de ghost-o-plasm","affaire de hornizz","vendre de l’énergie spectrale"}},{q="Pourquoi Hornizz en veut-il ?",a="Hornizz pense que les centaures Magram paieront cher pour de l’énergie spectrale capturée.",al={"pourquoi hornizz en veut","pourquoi recueillir la substance fantomatique","énergie spectrale des centaures"}}},fp="13,135,22.304.0,22.72.0,30.99.0,24.81.0,25.77.0"}
P.entries["item:ghoul-fang"] = {n="Croc de goule",s="Dans le Bois de la Pénombre, les voyageurs affrontent les ténèbres qui gagnent la forêt, et les Crocs de goule servent aux talismans protecteurs de Madame Eva. Ces crocs sont essentiels à son travail à Sombre-Comté.",h="Dans le Bois de la Pénombre, les voyageurs affrontent les ténèbres qui gagnent la forêt, et les Crocs de...",kw={"sombre-comté","bois de la pénombre","croc de goule","goules","madame eva","totem d'affliction","mort-vivant"},ang={["faction:Alliance"]="En tant qu’aventurier de l’Alliance venu aider Sombre-Comté assiégé, vous pouvez faire des horreurs du Bois de la Pénombre des outils de survie contre la souillure qui gagne, semblable au Fléau."},sec={{t="Trophées des morts agités",b="Des morts-vivants voraces hantent les bois et les tombes du Bois de la Pénombre. Des mangeurs de chair se tapissent près des lieux d’inhumation, tandis que des cadavres pourrissants rôdent parmi les arbres. Prélever un croc sur ces créatures est une tâche sinistre. C’est la preuve qu’on a survécu aux morts qui menacent les frontières de Sombre-Comté."},{t="Composants occultes",b="Madame Eva est la diseuse de bonne aventure et mystique de Sombre-Comté. Elle voit de terribles présages autour des voyageurs qui traversent le Bois de la Pénombre. Elle enchante donc le Totem d'affliction avec des crocs de goule, des doigts de squelette et du venin d’arachnide. Ce talisman retourne les forces obscures de la forêt contre les assaillants et protège son porteur."}},faq={{q="Où trouver des Crocs de goule ?",a="Diverses goules hantent les cimetières et les chemins isolés du Bois de la Pénombre. Parmi elles se trouvent les Plague Spreaders, les Brain Eaters, les Bone Chewers, les Fetid Corpses, les cadavres pourrissants et les mangeurs de chair.",al={"où trouver des crocs de goule","qui donne des crocs de goule","emplacement des crocs de goule"}},{q="Qui veut des Crocs de goule ?",a="Madame Eva, la mystique de Sombre-Comté, a besoin de Crocs de goule pour fabriquer le Totem d'affliction défensif.",al={"qui a besoin de crocs de goule","remise des crocs de goule","quête de madame eva"}},{q="Pourquoi Madame Eva en a-t-elle besoin ?",a="Madame Eva sent le danger se resserrer autour des voyageurs. Elle associe les crocs à des doigts de squelette et du venin d’araignée pour enchanter un totem protecteur qui punit quiconque s’en prend à son porteur.",al={"pourquoi des crocs de goule","composants du totem d'affliction","que fait madame eva des crocs"}}},fx={["7c703fef"]={q="Qu'est-ce qu'un Croc de goule ?",a="Un Croc de goule est une dent pointue arrachée à la gueule des goules mort-vivantes qui hantent le bois de la Pénombre. Souillés par le fléau nécromantique et une faim dévorante, ces crocs conservent un vestige de la magie noire qui anime les morts-vivants, en faisant des réactifs puissants pour des charmes protecteurs et des rituels occultes.",al={"qu'est-ce qu'un croc de goule","lore du croc de goule","à propos du croc de goule"}},["87f3f6fc"]={q="D'où vient un Croc de goule ?",a="Ces crocs proviennent des diverses goules mort-vivantes errant dans les ombres du bois de la Pénombre, comme les Plague Spreaders, Brain Eaters, Bone Chewers et Flesh Eaters. Ils ne sont pas fabriqués à la main, mais récupérés directement sur les mâchoires des morts errants.",al={"origine du croc de goule","d'où viennent les crocs de goule","qui laisse tomber des crocs de goule"}}},fp="10,182,29.255.0,15.302.0,31.170.0,22.98.0,30.189.0"}
P.entries["item:ghoul-rib"] = {n="Côte de goule",s="Dans le Bois de la Pénombre, Abercrombie rassemble des Côtes de goule pour protéger sa cabane des morts. Il affirme qu’une effigie terrifiante éloignera de chez lui ces horreurs dévoreuses de chair.",h="Dans le Bois de la Pénombre, Abercrombie rassemble des Côtes de goule pour protéger sa cabane des morts.",kw={"abercrombie","repaire des mendiants","mâcheur d’os","sombre-comté","bois de la pénombre","dévoreur de chair","côte de goule","ghoulish effigy","mort-vivant"},ang={["class:Paladin"]="Manipuler les os profanés des morts agités est une tâche sinistre. Aider un ermite isolé à affronter des horreurs voraces s’accorde avec le devoir de votre paladin de protéger les vivants du Bois de la Pénombre.",["class:Priest"]="La force pervertie qui ranime ces os témoigne de l’ombre profonde qui pèse sur le Bois de la Pénombre. Les villageois tombés deviennent des charognards voraces."},sec={{t="Une protection macabre",b="Les goules hantent le Bois de la Pénombre sous de nombreuses formes. On y trouve des Dévoreurs de chair, des Mâcheurs d’os, des Mangeurs de cerveaux, des Pourrissants et des Propagateurs de peste.\n\nAbercrombie vit seul dans une cabane au nord du Cimetière de Colline-aux-Corbeaux. Il demande aux voyageurs leurs côtes solides et pourries. Sa demeure se trouve au-delà de la protection des Veilleurs à Sombre-Comté. Il affirme donc avoir besoin d’une effigie terrifiante pour éloigner les morts."},{t="Soupçons autour de la cabane",b="La demande de morceaux de goule d’Abercrombie soulève des questions. Les palissades de Sombre-Comté pourraient lui offrir un abri, et des protections consacrées pourraient garder sa demeure. Pourtant, l’ermite insiste pour rassembler des restes nécromantiques bruts afin de protéger sa cabane isolée."}},faq={{q="Quelles créatures portent des Côtes de goule ?",a="Plusieurs sortes de goules du Bois de la Pénombre portent des Côtes de goule. On compte parmi elles les Dévoreurs de chair, les Mâcheurs d’os, les Mangeurs de cerveaux, les Pourrissants et les Propagateurs de peste. Ces créatures hantent les vieux cimetières, les ruines au bord des routes et les fermes abandonnées de toute la forêt.",al={"où trouver des côtes de goule","quelles goules ont des côtes","sources de côtes de goule"}},{q="Pourquoi Abercrombie veut-il ces os ?",a="Abercrombie affirme que sa demeure est trop éloignée de Sombre-Comté pour que les Veilleurs puissent le protéger. Il demande des côtes pour fabriquer un épouvantail grossier ou une effigie, qu’il croit capable de tenir les morts-vivants errants à l’écart de ses murs.",al={"pourquoi abercrombie a besoin de côtes","utilité de l’effigie macabre","que fait abercrombie des côtes"}},{q="Les épouvantails éloignent-ils vraiment les goules ?",a="Les goules sont poussées par la faim ou par de sombres forces nécromantiques et ne ressentent généralement aucune peur. Abercrombie affirme tout de même qu’un épouvantail fait d’os protégera sa demeure.",al={"l’effigie fonctionne-t-elle","les effigies effraient-elles les morts-vivants","les goules ont-elles peur des épouvantails"}},{q="Où se trouve la cabane d’Abercrombie ?",a="La cabane d’Abercrombie se trouve dans l’ouest du Bois de la Pénombre, juste au nord du Cimetière de Colline-aux-Corbeaux.",al={"emplacement d’abercrombie","où se trouve l’ermite","où rendre les côtes de goule"}}},fx={["3e8ffb18"]={q="Qu'est-ce qu'une Côte de goule ?",a="Une Côte de goule est exactement ce que son nom indique : un os provenant des morts-vivants réanimés et pourris qui rôdent dans le bois de la Pénombre. Dépouillés de démons tels que les Flesh Eaters, Brain Eaters et Bone Chewers, ces restes portent encore la faible souillure de la magie infecte qui anime les morts marchants dans cette forêt dévastée.",al={"infos sur la côte de goule","qu'est-ce que les côtes de goule","objet côte de goule"}},f2829c95={q="D'où viennent les Côtes de goule ?",a="Ces côtes proviennent directement des diverses goules hantant les routes et les tumulus sombres du bois de la Pénombre. Ce sont des restes squelettiques naturels plutôt que des reliques artisanales, récoltées sur des monstruosités mort-vivantes comme les Plague Spreaders et les Rotted Ones qui errent bien au-delà de la relative sécurité de Sombre-Comté.",al={"source de la côte de goule","où obtenir des côtes de goule","qui a fabriqué les côtes de goule"}}},fp="9,161,15.373.0,27.237.1,32.238.0,38.200.0,40.163.0,37.84.0"}
P.entries["item:giant-crocolisk-skin"] = {n="Peau de crocilisque géant",s="Dans les Paluns, les marchands de Port de Menethil ont besoin des peaux épaisses de crocilisques géants. Les chasser est périlleux, et certains chasseurs en sont ressortis mutilés.",h="Dans les Paluns, les marchands de Port de Menethil ont besoin des peaux épaisses de crocilisques géants.",kw={"apprentice's duties","crocilisque","peau de crocilisque géant","james halloran","port de menethil","les paluns"},ang={["class:Hunter"]="Pour un chasseur, traquer les crocilisques géants le long de la côte met à l’épreuve votre aptitude à suivre des bêtes aquatiques tout en évitant les eaux marécageuses."},sec={{t="Un commerce dangereux",b="Les tourbières et les cours d’eau des Paluns abritent d’énormes crocilisques dont la peau résiste à la pourriture due à l’humidité des marais. À Port de Menethil, des artisans comme James Halloran comptent sur des livraisons régulières pour fabriquer des articles en cuir robustes. Pour atteindre une bête adulte, il faut braver les eaux profondes et affronter un prédateur féroce : chaque peau s’arrache de haute lutte."},{t="La folie de l’apprenti",b="Le jeune apprenti de Halloran récoltait autrefois ces peaux épaisses. Incapable de vaincre les bêtes adultes des marais, le garçon est tombé dans une embuscade sur la côte nord. Des crocilisques géants l’ont mutilé, et il est désormais aux soins d’une sage-femme locale. Selon elle, il pourrait s’en sortir. Après l’attaque, Halloran a engagé des aventuriers chevronnés pour chasser les prédateurs et obtenir les peaux dont il a besoin."}},faq={{q="À quoi servent les peaux de crocilisque géant ?",a="James Halloran, un marchand de Port de Menethil, utilise les peaux de crocilisque géant pour fabriquer des articles en cuir robustes, capables de résister à l’humidité des marais.",al={"utilisation de la peau de crocilisque","pourquoi récolter des peaux de crocilisque géant","utilité des peaux de halloran"}},{q="Où trouve-t-on les crocilisques qui fournissent ces peaux ?",a="Les Giant Wetlands Crocolisks parcourent la côte et les eaux marécageuses à l’intérieur des terres, au nord de Port de Menethil. On les trouve dans les hauts-fonds, au-delà des campements murlocs locaux.",al={"emplacement des crocilisques géants","où trouver des crocilisques géants","côte des crocilisques dans les paluns"}},{q="Qu’est-il arrivé à l’apprenti de Halloran ?",a="L’apprenti de Halloran est parti seul récolter des peaux dans les marais. Des crocilisques géants l’ont mutilé, et il est désormais aux soins d’une sage-femme de Port de Menethil. Selon elle, il pourrait s’en sortir.",al={"apprenti blessé","apprenti de halloran","qui a perdu une jambe"}},{q="En quoi ces peaux diffèrent-elles des peaux de jeune crocilisque ?",a="Les jeunes crocilisques donnent des peaux plus fines et plus souples. Les crocilisques géants adultes donnent des peaux plus épaisses et plus résistantes, mais en tuer un exige une solide expérience du combat.",al={"peau de jeune crocilisque ou de géant","différence entre les cuirs de crocilisque"}}},fx={["406c8fec"]={q="Qu'est-ce qu'une Peau de crocilisque géant ?",a="C'est la peau épaisse et durable prélevée sur les crocilisques géants errant dans les marais des Paluns. Prisée des travailleurs du cuir et des artisans pour sa robustesse et sa taille, récolter une telle dépouille n'est pas une tâche facile, car ces prédateurs comptent parmi les bêtes les plus vicieuses rôdant dans les voies navigables.",al={"qu'est-ce qu'une peau de crocilisque géant","peau de crocilisque géant","infos sur la peau de crocilisque"}},bd43ba97={q="D'où vient la Peau de crocilisque géant et qui l'a fabriquée ?",a="La peau est récoltée naturellement sur des crocilisques géants des Paluns vivant dans les marais au nord le long de la côte au-delà des cabanes murlocs. Plutôt que d'être fabriquée par un artisan, elle doit être écorchée directement sur les carcasses de ces bêtes des marais massives.",al={"qui a fabriqué la peau de crocilisque géant","d'où viennent les peaux de crocilisque géant","source de la peau de crocilisque géant"}},c37602c5={q="Pourquoi James Halloran veut-il des Peaux de crocilisque géant ?",a="James Halloran, un artisan du port de Menethil, a besoin de ces peaux pour son commerce. Il a initialement envoyé son jeune apprenti les rassembler, mais après que le garçon a été déchiqueté par les bêtes voraces et laissé aux soins d'une sage-femme, Halloran s'est tourné vers des aventuriers chevronnés pour sécuriser les matériaux et venger son protégé.",al={"pourquoi halloran veut-il des peaux","qui veut des peaux de crocilisque géant","pourquoi avoir besoin de peaux de crocilisque géant"}}},fp="20,143,17.317.0,22.358.1,40.145.0,56.154.0,39.169.0,52.154.0"}
P.entries["item:gloom-weed"] = {n="Herbe des ténèbres",s="Dans les Clairières de Tirisfal, l’Herbe des ténèbres pousse entre Le Glas et Brill. Gordo la cueille par erreur en cherchant du Doom Weed.",h="Dans les Clairières de Tirisfal, l’Herbe des ténèbres pousse entre Le Glas et Brill.",kw={"abomination","brill","doom weed","herbe des ténèbres","gordo","maître holland","clairières de tirisfal"},ang={["profession:Herbalism"]="En tant qu’herboriste confirmé, vous pouvez détecter l’Herbe des ténèbres avec Découverte d’herbes et la repérer plus facilement dans les sous-bois ombragés de Tirisfal.",["race:Undead"]="En tant que Réprouvé fraîchement parti du Glas, vous pouvez apprendre en allant chercher de l’Herbe des ténèbres à quel point les abominations travaillent mal et avec quelle brusquerie parlent les alchimistes de Fossoyeuse."},sec={{t="Une récolte par erreur",b="L’Herbe des ténèbres pousse à l’ouest de Brill et à l’est de la Ferme des Solliden. Elle est inoffensive et n’a pas la puissance alchimique recherchée par la Société royale des apothicaires. Gordo, une imposante abomination, erre sur la route et arrache des herbes de ses mains maladroites. Il a mal compris les ordres de son maître et continue donc à cueillir la mauvaise plante.\n\nGordo demande ensuite aux voyageurs de porter les herbes à Maître Holland, dans le cimetière de Brill. L’apothicaire s’agace de cette erreur."}},faq={{q="À quoi sert l’Herbe des ténèbres ?",a="Les alchimistes réprouvés ont peu d’usage pour l’Herbe des ténèbres. Gordo la cueille parce qu’il la confond avec le Doom Weed, l’herbe demandée par son maître.",al={"usage de l’herbe des ténèbres","effets de l’herbe des ténèbres","qui a besoin d’herbe des ténèbres"}},{q="Où pousse l’Herbe des ténèbres ?",a="L’Herbe des ténèbres pousse dans les Clairières de Tirisfal, entre Brill et Le Glas. Vous en trouverez le long de la route et dans les prés à l’est de la Ferme des Solliden.",al={"où trouver l’herbe des ténèbres","emplacement de l’herbe des ténèbres","lieux où trouver l’herbe des ténèbres"}},{q="Qui est Gordo et pourquoi la cueille-t-il ?",a="Gordo est une abomination envoyée par Maître Holland pour ramasser des réactifs. Ses mains sont maladroites et son esprit simple : il arrache les mauvaises plantes et demande aux passants de l’aider.",al={"qui est gordo","pourquoi gordo cueille des herbes","abomination gordo"}},{q="Que voulait réellement Maître Holland ?",a="Maître Holland a besoin de Doom Weed pour ses expériences dans le cimetière de Brill. Quand des voyageurs lui apportent de l’Herbe des ténèbres, il se moque de leur erreur et les envoie cueillir l’herbe dont il a besoin.",al={"herbe pour maître holland","de quoi maître holland a-t-il besoin","doom weed ou herbe des ténèbres"}}},fx={bc1ac336={q="Qu'est-ce que l'Herbe des ténèbres ?",a="L'Herbe des ténèbres est une plante sauvage ordinaire à l'aspect maladif qui pousse dans le sol maudit des Clairières de Tirisfal, principalement trouvée le long des routes et dans les champs ouverts entre Brill et Le Glas. Elle ne possède aucun pouvoir magique ou propriété alchimique précieuse. En vérité, c'est à peine plus qu'une mauvaise herbe commune de bord de route — l'équivalent de la pâquerette en Tirisfal — qui réussit à prospérer malgré les conditions dévastées de la campagne.",al={"qu'est-ce que l'herbe des ténèbres","lore de l'herbe des ténèbres","plante herbe des ténèbres"}},defb981c={q="Pourquoi quelqu'un voudrait-il de l'Herbe des ténèbres ?",a="Pratiquement personne ne veut réellement de l'Herbe des ténèbres. La seule raison pour laquelle quiconque en ramasse est que Gordo, une abomination à l'esprit lent errant dans les champs près de Brill, a complètement mal compris ses instructions. Son maître, l'apothicaire junior Holland, l'avait envoyé récolter de la précieuse Doom weed pour des expériences des Réprouvés, mais l'esprit lourd de Gordo a confondu les noms et a envoyé des voyageurs inconscients cueillir de l'inutile Herbe des ténèbres à la place.",al={"qui veut de l'herbe des ténèbres","pourquoi ramasser de l'herbe des ténèbres","pourquoi collecter de l'herbe des ténèbres"}}},fp="10,118,18.441.0,28.137.0,27.131.0,38.172.0,38.180.0"}
P.entries["item:glowing-ember"] = {n="Braise rougeoyante",s="Au Shrine of Eternal Flame, une Braise rougeoyante réveille le brasero de l’épreuve des chamans. Elle provient d’une Minor Manifestation of Fire des falaises de Durotar.",h="Au Shrine of Eternal Flame, une Braise rougeoyante réveille le brasero de l’épreuve des chamans.",kw={"call of fire","sapta de feu","braise rougeoyante","minor manifestation of fire","shrine of eternal flame","telf joolam","torche de la flamme dormante"},ang={["class:Shaman"]="En tant que chaman, vous éprouvez votre détermination face au feu vivant lors de ce rite de passage, avant de commander votre totem."},sec={{t="Au cœur des flammes",b="Un chaman en devenir boit du Sapta de feu pour voir les esprits ardents sur la crête près de Telf Joolam. Là, l’initié affronte une Minor Manifestation of Fire. Lorsque l’élémentaire succombe, sa forme physique ne laisse qu’une braise fumante. Une chaleur élémentaire brute pulse encore en elle, porteuse de l’étincelle nécessaire pour réveiller le brasero sacré au Shrine of Eternal Flame."},{t="Allumer la torche",b="Quand la Braise rougeoyante entre dans la vasque froide du brasero de la montagne, des flammes blanches jaillissent. La flamme du brasero permet à l’initié d’allumer la Torche de la flamme dormante. Cette torche enferme l’essence indomptable du feu dans un réceptacle que l’initié peut emporter en descendant la montagne, comme preuve de sa maîtrise des éléments."}},faq={{q="D’où vient la Braise rougeoyante ?",a="Vous récupérez la braise sur une Minor Manifestation of Fire vaincue au sommet, au-dessus du Shrine of Eternal Flame, à Durotar.",al={"obtenir la braise rougeoyante","butin de braise rougeoyante","où trouver la braise rougeoyante"}},{q="À quoi sert la braise ?",a="Vous placez la braise dans le brasero de métal au Shrine of Eternal Flame. Sa flamme intense et rythmée allume la Torche de la flamme dormante cérémonielle.",al={"à quoi sert la braise rougeoyante","utilisation de la braise rougeoyante","braise du brasero"}},{q="Pourquoi les chamans doivent-ils utiliser le Sapta de feu pour l’obtenir ?",a="Les esprits élémentaires au sommet de la montagne échappent à la vue des simples mortels. En buvant du Sapta de feu, vous accordez vos sens au plan élémentaire et révélez la Minor Manifestation of Fire, que vous pouvez alors défier.",al={"pourquoi utiliser le sapta","ne voit pas l’élémentaire de feu","sapta de feu et braise"}},{q="Qui envoie les chamans chercher cette braise ?",a="Telf Joolam, un ermite des falaises de Durotar, prépare le Sapta de feu et guide les initiés chamans dans l’épreuve qui consiste à vaincre l’esprit de la flamme.",al={"qui donne la quête","braise de telf joolam","donneur de quête de call of fire"}}},fx={["8d7073a8"]={q="Qu'est-ce que la Braise rougeoyante ?",a="La Braise rougeoyante est le vestige fumant récolté sur une Manifestation de feu mineure sur le pic surplombant Durotar. Il s'agit d'un morceau concentré de flamme vivante laissé derrière une fois que l'esprit est vaincu, détenant assez de chaleur élémentaire innée pour allumer les feux dormants au sommet de l'autel sacré de la montagne.",al={"qu'est-ce que la braise rougeoyante","lore de la braise rougeoyante","objet braise rougeoyante"}}},fp="13,157,17.352.0,18.308.1,39.125.0,27.150.0,49.206.0,39.144.0"}
P.entries["item:glowing-fruit"] = {n="Fruit luminescent",s="Sous d’étranges frondes de Teldrassil, le Fruit luminescent brille de sa propre lumière. Denalan, au lac Al'Ameth, étudie sa réaction au sol de l’Arbre-monde.",h="Sous d’étranges frondes de Teldrassil, le Fruit luminescent brille de sa propre lumière.",kw={"botanique","denalan","fruit luminescent","lac al'ameth","plante","teldrassil","timberlings"},ang={["class:Druid"]="En tant que druide en harmonie avec l’équilibre de Teldrassil, vous pouvez considérer les plantes étrangères qui réagissent étrangement à son sol comme une menace pour le jeune Arbre-monde.",["profession:Herbalism"]="En tant qu’herboriste, vous pouvez voir dans l’étrange lueur du fruit le signe d’une interaction inhabituelle entre des graines étrangères et un sol enchanté."},sec={{t="Un spécimen curieux",b="Sous d’inhabituelles frondes de Teldrassil, le Fruit luminescent est rond et resplendissant. Le botaniste Denalan, au lac Al'Ameth, sait qu’il est étranger à l’Arbre-monde. Il pense que ses graines viennent de contrées lointaines, de l’autre côté de la mer. Sa réaction au sol riche et enchanté de Teldrassil montre comment les plantes étrangères peuvent affecter le jeune Arbre-monde."}},faq={{q="Qu’est-ce que le Fruit luminescent ?",a="Trouvé sous d’inhabituelles frondes de Teldrassil, le Fruit luminescent est rond et brille de sa propre lumière. Il réagit étrangement au sol local.",al={"fruit luminescent teldrassil","qu’est-ce que ce fruit","quête du fruit étrange"}},{q="D’où vient ce fruit ?",a="Denalan pense que le Fruit luminescent est étranger à Teldrassil. Il soupçonne que ses graines viennent de contrées lointaines, peut-être des Royaumes de l'est.",al={"origine du fruit","d’où viennent les graines","est-il indigène"}},{q="Qui veut examiner le Fruit luminescent ?",a="Au lac Al'Ameth, le chercheur elfe de la nuit Denalan veut étudier le Fruit luminescent. Il étudie les frondaisons et l’écosystème de Teldrassil, et s’intéresse aux plantes étrangères qui réagissent au sol de l’Arbre-monde.",al={"qui a besoin du fruit","où apporter le fruit luminescent","denalan fruit"}}},fp="13,151,18.318.0,26.136.0,31.143.0,39.201.0"}
P.entries["item:glowing-gem"] = {n="Gemme luminescente",s="Au Lac Falathim, la Gemme luminescente reste aux mains des murlocs depuis la mort de Teronis, parti à sa recherche. Sa magie pourrait aider à restaurer le bâton de Dartol.",h="Au Lac Falathim, la Gemme luminescente reste aux mains des murlocs depuis la mort de Teronis, parti à sa...",kw={"astranaar","bâton de purification","dartol","gemme luminescente","lac iris","murloc","raene mène-loup","shael'dryn","teronis"},ang={["class:Druid"]="En tant que druide, vous vous souciez des recherches de Teronis sur la corruption qui se répand, ainsi que de la relique qu'il espérait restaurer.",["race:NightElf"]="En tant qu'Elfe de la nuit, récupérer la gemme et poursuivre la mission de Teronis rend hommage à l'éclaireur tombé au combat. Cela aide les Sentinelles à protéger Orneval contre la corruption qui se répand."},sec={{t="Une relique perdue de Dartol",b="Les murlocs détiennent la Gemme luminescente près du Lac Falathim. La pierre recèle une magie latente. Teronis venait d'Astranaar pour trouver un moyen de repousser la corruption qui se répand dans les forêts d'Orneval. Il est mort au bord du lac, et la gemme est restée parmi les charognards du rivage."},{t="Restaurer le bâton",b="Une fois la Gemme luminescente et le journal de Teronis récupérés, la cheffe des Sentinelles Raene Mène-loup envoie le porteur vers le nord-est, auprès de Shael'dryn. La dryade veille sur un puits de lune voisin. Elle sait comment lier la gemme aux autres pièces manquantes du bâton de Dartol, afin de poursuivre le travail de Teronis."}},faq={{q="D'où vient la Gemme luminescente ?",a="Les murlocs transportent la Gemme luminescente sur les rives et dans les eaux peu profondes autour du sanctuaire du Lac Falathim, dans l'ouest d'Orneval. Teronis y a péri.",al={"emplacement de la gemme luminescente","qui lâche la gemme luminescente","où trouver la gemme luminescente"}},{q="Pourquoi Teronis recherchait-il cette gemme ?",a="Teronis cherchait un moyen de purifier la souillure qui gagne Orneval. Ses recherches désignaient la Gemme luminescente comme une pièce essentielle à la reconstruction du bâton magique conçu par Dartol.",al={"quête de teronis","pourquoi teronis voulait la gemme","utilité de la gemme"}},{q="À qui dois-je apporter la Gemme luminescente ?",a="Montrez la Gemme luminescente et le journal de Teronis à Raene Mène-loup, à Astranaar. Puis apportez la pierre vers le nord-est, à Shael'dryn, la dryade du puits de lune à l'est du Lac Iris.",al={"qui a besoin de la gemme luminescente","rendre la gemme luminescente","que faire de la gemme"}},{q="Qu'est-ce que le bâton de Dartol ?",a="Dartol a créé ce bâton comme instrument magique. Ses pièces ont été dispersées dans la forêt, et la Gemme luminescente est nécessaire pour le reconstituer.",al={"bâton de dartol","qu'a créé dartol"}}},fx={["464fc9d6"]={q="Qu'est-ce que la Gemme luminescente ?",a="La Gemme luminescente est une pierre enchantée nécessaire pour recréer le bâton fabriqué par Dartol. Teronis l'a cherchée durant ses recherches sur la corruption d'Orneval, et Raene Mène-loup dirige la quête des morceaux restants du bâton.",al={"qu'est-ce que la gemme luminescente","parlez-moi de la gemme luminescente","lore de la gemme luminescente"}}},fp="11,131,22.265.0,17.285.1,37.142.0,37.167.0,37.166.0,26.137.0"}
P.entries["item:glowing-soul-gem"] = {n="Gemme d'âme luminescente",s="À Ordil'Aran, la Gemme d'âme luminescente sert les desseins de la secte de la Dark Strand dans le nord d'Orneval. La sorcellerie ténébreuse imprègne la pierre, qui renferme l'esprit d'une victime inconsciente.",h="À Ordil'Aran, la Gemme d'âme luminescente sert les desseins de la secte de la Dark Strand dans le nord...",kw={"althalaxx","secte de la dark strand","dark strand","delgren le purificateur","gemme d'âme luminescente","poste de maestra","ordil'aran","gemme d'âme"},ang={["class:Priest"]="En tant que Prêtre, vous pouvez sentir l'agonie de l'esprit emprisonné dans la gemme. L'artefact doit être purifié pour que l'âme trouve la paix.",["class:Warlock"]="En tant que Démoniste, vous connaissez l'art de piéger les esprits dans des pierres d'âme. La gemme de la Dark Strand est une forme plus grossière de manipulation des âmes par la nécromancie."},sec={{t="Un réceptacle de sorcellerie ténébreuse",b="Au nord-est du Poste de Maestra, les ruines d'Ordil'Aran abritent la secte de la Dark Strand et ses maîtres des ombres. Les agents de la secte portent des Gemmes d'âme luminescentes, des réceptacles enchantés qui capturent et tourmentent les âmes des morts. Les pierres canalisent l'énergie magique et lient les esprits aux desseins de la secte."},{t="Les secrets d'Ordil'Aran",b="Au Poste de Maestra, Delgren le Purificateur étudie les gemmes pour affaiblir l'influence de la Dark Strand dans le nord de Kalimdor. Leurs enchantements renferment de sombres formules arcaniques et une âme prisonnière qui crie de l'intérieur. Ces formules révèlent des expériences qui relient les sectateurs d'Orneval à leurs semblables de la Tour d'Althalaxx."}},faq={{q="Qu'est-ce que la Gemme d'âme luminescente ?",a="La secte de la Dark Strand utilise la Gemme d'âme luminescente comme une pierre d'âme enchantée. La magie des ombres piège les esprits à l'intérieur, permettant à la secte de puiser dans leur essence pour pratiquer la sorcellerie.",al={"qu'est-ce qu'une gemme d'âme","gemme d'âme sombrivage","lore de la gemme d'âme luminescente"}},{q="D'où vient cette Gemme d'âme ?",a="Les membres de la secte de la Dark Strand transportent la gemme depuis les ruines d'Ordil'Aran, dans le nord d'Orneval. Parmi ceux qui la portent, on trouve des sectateurs, des assassins, des exécuteurs et des adeptes.",al={"qui fait tomber la gemme d'âme","emplacement de la gemme d'âme luminescente","gemme d'ordil'aran"}},{q="Qui veut cette Gemme d'âme, et pourquoi ?",a="Au Poste de Maestra, Delgren le Purificateur recherche la gemme. Il pense que ses enchantements révéleront la source secrète du pouvoir de la secte et ses projets.",al={"gemme d'âme de delgren","pourquoi delgren veut la gemme d'âme","gemme d'âme du poste de maestra"}},{q="Que se passe-t-il quand on déchiffre la Gemme d'âme ?",a="Déchiffrer les enchantements de la gemme libère le fantôme piégé à l'intérieur. L'âme tourmentée est délivrée, et les pratiques de la Dark Strand sont dévoilées.",al={"que contient la gemme d'âme","fantôme dans la gemme d'âme"}}},fp="16,179,24.294.0,25.318.1,29.167.0,35.167.0,32.161.0,45.143.1"}
P.entries["item:glutton-shackle"] = {n="Bracelet de Glouton",s="Dans la Forêt des Pins-Argentés, les Bracelets de Glouton renforcent la sorcellerie défaillante d’Arugal. L’archimage fou les a créés pour les worgens Moonrage Glutton.",h="Dans la Forêt des Pins-Argentés, les Bracelets de Glouton renforcent la sorcellerie défaillante d’Arugal.",kw={"arugal","dalar tisselaube","bracelet de glouton","moonrage glutton","le sépulcre","forêt des pins-argentés","worgen"},ang={["class:Mage"]="En tant que mage, vous reconnaîtrez peut-être les critiques acerbes de Dalar Tisselaube à l’égard des techniques bâclées d’Arugal. Les béquilles enchantées matérielles qui stabilisent de simples sorts de transmutation et d’invocation sont la marque d’un mage médiocre.",["race:Undead"]="En tant que Réprouvé, vous savez qu’il est essentiel de rassembler ces bracelets pour neutraliser la menace des worgens qui pèse directement sur les frontières du Sépulcre."},sec={{t="Un soutien à une magie fragile",b="Les worgens sauvages infestent la Forêt des Pins-Argentés, et les mages entraînés des Réprouvés y voient la preuve d’un travail arcanique médiocre. Dalar Tisselaube, un arcaniste accompli en poste au Sépulcre, méprise l’archimage Arugal. Il le traite d’incapable, indigne du Kirin Tor.\n\nDalar Tisselaube a découvert qu’Arugal s’appuyait sur des reliques enchantées pour renforcer ses sorts fragiles. Les imposants Moonrage Gluttons qui rôdent dans le nord de la Forêt des Pins-Argentés portent des Bracelets de Glouton. Ces ancres magiques renforcent la malédiction qui lie les bêtes."},{t="Au service des contre-mesures réprouvées",b="Arugal a lié des enchantements bruts directement à de lourds bracelets de fer. Même après la mort de leurs porteurs, les bracelets conservent une énergie magique. Dalar Tisselaube veut que des agents réprouvés lui rapportent ces bracelets afin d’en étudier la fabrication et d’en siphonner les réserves.\n\nEn examinant les enchantements grossiers du métal, les Réprouvés espèrent percer les mystères de la malédiction des worgens. Ils comptent orchestrer la chute du maître des bêtes retranché dans le Donjon d’Ombrecroc."}},faq={{q="Qu’est-ce qu’un Bracelet de Glouton ?",a="Les worgens Moonrage Glutton de la Forêt des Pins-Argentés portent des Bracelets de Glouton, des entraves de fer enchantées. L’archimage Arugal a fabriqué ces bracelets pour renforcer leurs porteurs par la magie et soutenir ses sorts défaillants.",al={"que sont les bracelets de glouton","histoire des bracelets de glouton","entraves des worgens"}},{q="Pourquoi Dalar Tisselaube veut-il des Bracelets de Glouton ?",a="Dalar Tisselaube veut étudier les enchantements grossiers d’Arugal et siphonner l’énergie magique qui subsiste dans les bracelets. Comprendre les objets qu’Arugal utilisait pour stabiliser ses bêtes peut aider les Réprouvés à contrer sa magie.",al={"pourquoi récupérer les bracelets","quête de dalar tisselaube","bracelets pour le sépulcre"}},{q="Qui fabrique ces bracelets ?",a="L’archimage Arugal a enchanté les bracelets. Ancien mage de Dalaran, il a invoqué les worgens pour combattre le Fléau, puis a perdu la raison et soumis ses créations à sa volonté au moyen de babioles magiques.",al={"qui a fabriqué les bracelets","bracelets d’arugal","origine des bracelets"}},{q="Où trouve-t-on les créatures qui portent ces bracelets ?",a="Les Moonrage Gluttons rôdent dans les bois et les fermes abandonnées du centre et du nord de la Forêt des Pins-Argentés. Ils se déplacent souvent en meutes avec d’autres worgens Moonrage corrompus.",al={"où apparaissent les gloutons","emplacement des moonrage glutton","bracelets des worgens des pins-argentés"}}},fp="15,143,25.512.0,33.458.1,26.198.0,48.218.0,25.190.0,53.170.0"}
P.entries["item:glyph-of-azora"] = {n="Glyphe d'Azora",s="Depuis la Tour d’Azora, Theocritus surveille les menaces au-delà de la Forêt d’Elwynn. Ses glyphes portent plus loin le pouvoir de l’Œil d’Azora et lui permettent de lire les pensées et les plans de ses ennemis.",h="Depuis la Tour d’Azora, Theocritus surveille les menaces au-delà de la Forêt d’Elwynn.",kw={"glyphe d'azora","morganth","les carmines","scrutation","donjon de guet-de-pierre","theocritus","tour d’azora","tour d'ilgalar"},ang={["class:Mage"]="En tant que mage, vous pouvez recourir à la divination arcanique pour étendre la scrutation par le cristal à la télépathie ciblée et aux relais sensoriels à distance.",["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez utiliser les glyphes pour recueillir des renseignements sur Morganth et les orcs Rochenoire du Donjon de Guet-de-pierre."},sec={{t="Des yeux au-delà de la frontière",b="Depuis sa tour dans la Forêt d’Elwynn, Theocritus surveille les puissances hostiles. L’Œil d’Azora lui permet de voir au loin, mais pas de sonder les esprits ni les plans de ses adversaires. Il place donc de petits focalisateurs appelés Glyphes d’Azora sur des surfaces éloignées. Chacun ancre sa magie et lui permet de lire les intentions ennemies et de projeter sa voix à des kilomètres pour parler avec ses agents de terrain."},{t="Espionnage dans les Carmines",b="Dans les Carmines, Theocritus place des glyphes en territoire hostile. Il fixe le premier à une antique statue de lion qui domine la Tour d'Ilgalar. Son rival, le sombre sorcier Morganth, détient cette forteresse. Grâce au glyphe, Theocritus pénètre dans l’esprit de Morganth et découvre un différend avec les orcs Rochenoire du Donjon de Guet-de-pierre voisin. Pour en connaître la cause, il envoie un second glyphe dans les hauteurs de la tour de guet intacte du donjon, dissimulé dans une jarre d’alcool abandonnée."}},faq={{q="À quoi sert le Glyphe d'Azora ?",a="Theocritus utilise un Glyphe d'Azora pour étendre la portée de l’Œil d’Azora. Placé dans un lieu éloigné, il ancre sa magie et lui permet de lire les pensées et les plans de ses adversaires, ainsi que de parler avec ses agents de terrain à des kilomètres.",al={"à quoi sert le glyphe d’azora","pourquoi utiliser le glyphe d’azora","fonction du glyphe d’azora"}},{q="Qui a créé le Glyphe d'Azora ?",a="Theocritus a créé le Glyphe d'Azora. Il vit dans la Tour d’Azora, près de la frontière orientale de la Forêt d’Elwynn.",al={"qui a créé le glyphe","créateur du glyphe d’azora","glyphe de theocritus"}},{q="Où les Glyphes d’Azora sont-ils placés ?",a="Un glyphe est fixé à une antique statue de lion qui domine la Tour d'Ilgalar. Un second est caché dans une jarre d’alcool abandonnée, dans la tour de guet intacte du Donjon de Guet-de-pierre.",al={"où placer le glyphe","lieux où placer les glyphes","où va le glyphe"}},{q="Pourquoi Theocritus espionne-t-il la Tour d'Ilgalar ?",a="La Tour d'Ilgalar est la forteresse de Morganth. Ce sombre sorcier renégat est le rival de Theocritus, et le glyphe permet à ce dernier de lire ses pensées et ses plans.",al={"pourquoi espionner morganth","theocritus et ilgalar","rivalité avec morganth"}},{q="Comment le glyphe permet-il à Theocritus de parler aux autres ?",a="Fixé à une surface éloignée, le glyphe ancre la magie de Theocritus. Il lui permet de projeter sa voix à des kilomètres pour parler avec ses agents de terrain.",al={"glyphe parlant","voix de theocritus dans le glyphe","le glyphe peut-il parler"}}},fx={["16152ed3"]={q="Qu'est-ce que le Glyphe d'Azora ?",a="Le Glyphe d'Azora est un marqueur arcanique enchanté fabriqué par le mage Theocritus à la Tour d’Azora. Utilisés conjointement avec son foyer de divination, l'Oeil d'Azora, ces pierres gravées servent de postes d'écoute à distance. Une fois apposé sur une surface près d'une zone d'intérêt, un glyphe permet à Theocritus de se plonger dans les esprits et les pensées de ses cibles à travers de grandes distances, ainsi que de projeter sa voix vers quiconque se tient à ses côtés.",al={"qu'est-ce que le glyphe d'azora","objet glyphe d'azora","parlez-moi du glyphe d'azora"}},["7c5a9e02"]={q="Pourquoi Theocritus veut-il que vous plantiez le Glyphe d'Azora ?",a="Theocritus compte sur ces glyphes pour mener une espionnage approfondi contre des adversaires dangereux dans les Carmines. Bien que l'Oeil d'Azora lui permette de voir des lieux à distance, il ne peut pas percer les esprits sans un conduit à proximité. Placer un glyphe près de la Tour d'Ilgalar lui permet de sonder les pensées et les projets futurs de son rival, le mage renégat Morganth, tandis qu'en planter un autre près du Donjon de Guet-de-pierre l'aide à démêler les conflits de Morganth avec les orcs Rochenoire.",al={"pourquoi planter le glyphe d'azora","pourquoi theocritus veut-il le glyphe placé","but du glyphe d'azora"}}},fp="14,161,22.362.0,21.468.1,42.206.0,31.107.0,37.168.0,49.150.0,55.136.0"}
P.entries["item:glyphic-letter"] = {n="Lettre glyphée",s="À l’Abbaye de Comté-du-Nord, la Lettre glyphée convie les novices prometteurs à étudier les arcanes. Après avoir servi la garnison, ils sont appelés à l’étage auprès de Khelden Bremen, le mage de l’abbaye chargé de leur formation.",h="À l’Abbaye de Comté-du-Nord, la Lettre glyphée convie les novices prometteurs à étudier les arcanes.",kw={"arcanes","forêt d’elwynn","lettre glyphée","khelden bremen","maître des mages","maréchal mcbride","abbaye de comté-du-nord"},ang={["class:Mage"]="En tant que Mage, cette missive marquée vous appelle à l’étage pour commencer l’étude formelle des traditions arcaniques de l’Alliance auprès de Khelden Bremen.",["race:Human"]="En tant qu’humain, vous commencez votre service au sein des disciplines magiques de Hurlevent avec cette convocation. L’Abbaye de Comté-du-Nord accueille des étudiants des arcanes depuis les débuts du royaume."},sec={{t="Une convocation aux arcanes",b="Khelden Bremen scelle la Lettre glyphée de son insigne. Les apprentis lanceurs de sorts la reçoivent après avoir fait preuve de discipline dans la Vallée de Comté-du-Nord. La convocation les éloigne des tâches de terrain élémentaires pour les faire bénéficier d’un enseignement magique dédié au sein de l’abbaye.\n\nAvant qu’ils n’abordent les arcanes, Bremen met la détermination de chaque élève à l’épreuve. Leurs forces sont dangereuses, leur examen implacable et leurs fardeaux lourds."}},faq={{q="Qu’est-ce que la Lettre glyphée ?",a="Khelden Bremen rédige et scelle la Lettre glyphée pour convoquer les apprentis à leur formation. Elle invite les aspirants mages humains à le retrouver dans les chambres supérieures de l’Abbaye de Comté-du-Nord pour suivre un enseignement formel des arcanes.",al={"quelle est cette lettre","objet lettre glyphée","lettre de khelden"}},{q="Qui envoie la Lettre glyphée ?",a="Khelden Bremen, le mage chargé de la formation à l’Abbaye de Comté-du-Nord, scelle la lettre de son insigne. Le commandement de la garnison la remet à l’apprenti après qu’il a fait ses preuves contre la vermine des environs.",al={"qui l’a écrite","qui m’a donné la lettre glyphée","expéditeur de la lettre"}},{q="Où dois-je apporter la Lettre glyphée ?",a="Apportez la lettre à l’intérieur de l’Abbaye de Comté-du-Nord. Entrez derrière le Maréchal McBride, suivez le couloir de gauche, montez les escaliers et cherchez la salle du fond où Khelden Bremen enseigne les arcanes.",al={"où aller","où se trouve khelden bremen","emplacement de khelden"}},{q="Pourquoi Khelden convoque-t-il les jeunes mages ?",a="Khelden veut éprouver votre détermination. Il vous avertit que l’étude des arcanes inspire crainte et respect, et qu’elle implique d’affronter de puissantes forces. Il doit savoir si vous avez la volonté d’endurer ce destin.",al={"pourquoi khelden me convoque","raison du maître des mages","que veut khelden"}}},fx={["4321b6bd"]={q="Pourquoi Khelden Bremen veut-il que la Lettre glyphée vous soit remise ?",a="La lettre sert de convocation officielle et d'épreuve de volonté pour les mages débutants. Scellée de son insigne personnel, la note de Khelden Bremen expose le chemin périlleux et intimidant des arcanes, vous mettant en garde contre la peur et les défis qui accompagnent la poursuite du savoir interdit. Vous la remettre garantit que vous êtes prêt à faire face à ce destin avant qu'il n'entreprenne votre formation officielle.",al={"pourquoi la lettre glyphée","pourquoi ai-je reçu la lettre glyphée","but de la lettre glyphée"}}},fp="14,180,23.390.0,27.190.0,29.183.0,35.185.0,38.193.0"}
P.entries["item:glyphic-memorandum"] = {n="Note de service glyphée",s="Dans la Vallée des Frigères, la Note de service glyphée appelle les mages novices à Courbenclume. Marryk Nurribit l'a rédigée pour guider les nouveaux lanceurs de sorts dans leur apprentissage officiel des arcanes.",h="Dans la Vallée des Frigères, la Note de service glyphée appelle les mages novices à Courbenclume.",kw={"courbenclume","vallée des frigères","dun morogh","note de service glyphée","mage","marryk nurribit"},ang={["class:Mage"]="En tant que mage dans Dun Morogh, vous commencez votre apprentissage officiel des arcanes auprès de Marryk Nurribit grâce à cette note.",["race:Gnome"]="En tant que mage gnome au début de votre exil, votre maître vous exhorte à vous concentrer sur vos études et à éviter Gnomeregan, votre patrie perdue."},sec={{t="Un appel à Courbenclume",b="Les lanceurs de sorts novices reçoivent la Note de service glyphée après leurs premières tâches dans la Vallée des Frigères. Marryk Nurribit, le maître des mages local, les convoque à l'intérieur de Courbenclume. Il leur donne des conseils simples : apprenez vos incantations, gardez des pièces pour votre entraînement et la bière de la taverne, et tenez-vous à l'écart de Gnomeregan, ravagée par les radiations."}},faq={{q="Qu'est-ce que la Note de service glyphée ?",a="La Note de service glyphée convoque les mages fraîchement arrivés dans la Vallée des Frigères. Elle les dirige vers le maître des arcanes à l'intérieur de Courbenclume.",al={"note glyphée","note de mage","qu'est-ce que la note de service glyphée"}},{q="Qui a rédigé cette note de service ?",a="Marryk Nurribit a rédigé la note. Il forme les mages à Courbenclume, dans Dun Morogh.",al={"qui l'a rédigée","qui a envoyé la note de service glyphée","auteur de la note"}},{q="Quels conseils le maître donne-t-il en réponse à la note ?",a="Lorsque vous présentez la note, Marryk conseille la modération. Gardez des pièces pour vos sorts et la bière de la taverne, et évitez les couloirs radioactifs de Gnomeregan.",al={"conseils de marryk","que dit marryk"}}},fx={c67a7a55={q="Pourquoi Marryk Nurribit veut-il que vous lui apportiez la Note de service glyphée ?",a="La note de service sert d'invitation et de convocation pour les mages en herbe commençant dans la Vallée des Frigères. En la remettant à Marryk Nurribit à Courbenclume, vous établissez le contact avec votre maître de mage local. Il profite de l'occasion pour offrir des conseils aux novices, vous rappeler de rester à l'écart de Gnomeregan, désormais déchue, et proposer un enseignement formel des arts arcaniques dès que vous avez quelques pièces à dépenser.",al={"pourquoi apporter la note de service glyphée","pourquoi marryk veut-il la note de service","pourquoi vouloir la note de service glyphée"}}},fp="18,158,21.305.0,31.126.0,26.81.0,64.131.0"}
P.entries["item:glyphic-scroll"] = {n="Rouleau glyphé",s="Au Glas, le Rouleau glyphé convoque les mages réprouvés récemment relevés à l’église. Le sceau d’Isabella invite les lanceurs de sorts novices à commencer leur apprentissage des arcanes dans la non-mort.",h="Au Glas, le Rouleau glyphé convoque les mages réprouvés récemment relevés à l’église.",kw={"arcanes","le glas","rouleau glyphé","isabella","mage","rouleau","tirisfal"},ang={["class:Mage"]="En tant que mage réprouvé, vous recevez votre première convocation officielle à une formation. La non-mort ne vous épargne pas l’attrait corrupteur de la magie des arcanes.",["race:Undead"]="En tant que Réprouvé, vous vous réappropriez le savoir arcanique et en faites une arme pour garantir votre souveraineté face au Fléau et aux ennemis vivants."},sec={{t="Une convocation de l’église",b="Après avoir éliminé les morts-vivants décérébrés du Fléau dans le cimetière du Glas, les mages réprouvés récemment éveillés trouvent un rouleau scellé. Isabella, l’instructrice des mages de la colonie, les convoque au sanctuaire paroissial en ruine. Là, les nouveaux mages commencent à étudier les arcanes sous la bannière des Réprouvés. La mort les a libérés de la faiblesse des mortels, mais les tentations corruptrices de la magie demeurent."}},faq={{q="Qu’est-ce que le Rouleau glyphé ?",a="Le Rouleau glyphé convoque les mages réprouvés récemment relevés au Glas pour commencer leur apprentissage des arcanes. Leur instructrice Isabella le scelle et les invite à la retrouver dans l’église de la ville.",al={"à quoi sert cet objet","utilisation du rouleau glyphé","que fait le rouleau"}},{q="Qui envoie le Rouleau glyphé ?",a="Isabella envoie le Rouleau glyphé aux morts-vivants récemment relevés qui ont des dispositions pour les arcanes. Elle forme les mages dans l’église en ruine du Glas.",al={"qui l’a écrit","qui me l’a donné","expéditeur du rouleau"}},{q="Pourquoi Isabella veut-elle former de nouveaux mages réprouvés ?",a="Isabella forme les mages réprouvés qui partagent la douleur de la mort et le désir de reconquérir leur patrie et leur destin. Elle leur apprend à développer leur pouvoir arcanique pour détruire ceux qui s’opposent aux Réprouvés, tout en les mettant en garde contre la dépendance à la magie et la corruption.",al={"motif d’isabella","pourquoi former des mages"}}},fp="14,167,25.355.0,27.176.0,29.139.0,51.253.0"}
P.entries["item:glyphic-tablet"] = {n="Tablette glyphée",s="Dans la Vallée des épreuves, Gornek remet la Tablette glyphée aux mages trolls Sombrelance novices. Son appel les envoie auprès de Mai'ah, qui leur enseigne la magie des arcanes.",h="Dans la Vallée des épreuves, Gornek remet la Tablette glyphée aux mages trolls Sombrelance novices.",kw={"arcanes","durotar","tablette glyphée","gornek","mai'ah","mage troll","vallée des épreuves"},ang={["class:Mage"]="En tant que mage, vous commencez votre apprentissage des arcanes Sombrelance par l'avertissement de Mai'ah : l'attrait corrupteur de la magie est votre plus grand péril.",["race:Troll"]="En tant que troll Sombrelance, vous recevez cette tablette pour commencer votre voie aux côtés des voies traditionnelles des chamans et des guerriers."},sec={{t="La première convocation d'un mage",b="Les recrues Sombrelance qui ont une affinité avec la puissance des arcanes reçoivent la Tablette glyphée dans la Vallée des épreuves. Gornek la remet aux jeunes mages tandis qu'ils accomplissent leurs premières tâches dans les canyons rouges. Sur l'ardoise, Mai'ah, une mage troll chevronnée qui se trouve à l'extérieur de l'Antre, les invite à la rencontrer.\n\nLes Sombrelance suivent des traditions arcaniques différentes de celles des académies érudites des humains ou des hauts-elfes. Mai'ah leur propose un enseignement et les avertit solennellement. La magie brute corrompt et trompe, et les dangers qu'elle fait courir à l'esprit d'un mage dépassent ceux de tout soldat ennemi."}},faq={{q="À quoi sert la Tablette glyphée ?",a="La Tablette glyphée convoque un mage troll novice auprès de Mai'ah, dans la Vallée des épreuves, pour qu'elle lui apprenne à lancer correctement des sorts.",al={"à quoi sert la tablette glyphée","utilité de la tablette glyphée","pourquoi ai-je la tablette glyphée"}},{q="Qui envoie la Tablette glyphée ?",a="Mai'ah écrit le texte de la tablette, et Gornek la remet aux jeunes recrues trolls dans la Vallée des épreuves.",al={"qui a écrit la tablette glyphée","qui m'a donné la tablette glyphée"}},{q="Pourquoi les mages trolls doivent-ils être mis en garde contre la magie ?",a="Mai'ah avertit que la magie des arcanes corrompt, nourrit l'arrogance et peut donner aux lanceurs de sorts un sentiment d'invincibilité. Ses dangers invisibles sont plus meurtriers que ceux des rivaux physiques.",al={"que dit mai'ah","la magie est-elle dangereuse"}},{q="D'autres races de la Horde peuvent-elles recevoir cette tablette ?",a="Les mages trolls reçoivent la Tablette glyphée dans la Vallée des épreuves. Les mages orcs reçoivent un Parchemin glyphé qui les convoque auprès de Mai'ah.",al={"les orcs peuvent-ils recevoir la tablette glyphée","la tablette glyphée est-elle réservée aux trolls"}}},fx={be25ec39={q="Qu'est-ce que la Tablette glyphée ?",a="La Tablette glyphée est un message gravé envoyé aux mages trolls novices commençant leurs épreuves dans la Vallée des épreuves. Remise par l'intermédiaire de Gornek, elle vous convoque pour rencontrer Mai'ah, la maître de mage locale, afin que vous puissiez commencer formellement votre instruction dans les arts arcaniques.",al={"qu'est-ce que la tablette glyphée","objet tablette glyphée","à propos de la tablette glyphée"}},["28b4f0b5"]={q="Pourquoi quelqu'un voudrait-il la Tablette glyphée ?",a="La tablette n'est pas recherchée pour le pouvoir ou la richesse, mais sert de convocation formelle et de jeton d'introduction. Elle garantit que les jeunes mages trolls se présentent à Mai'ah, qui profite de la réunion pour prodiguer des avertissements cruciaux concernant les dangers corrupteurs inhérents à la pratique de la magie arcanique.",al={"pourquoi vouloir la tablette glyphée","qui a besoin de la tablette glyphée","pourquoi garder la tablette glyphée"}}},fp="14,152,22.518.0,42.114.0,29.94.0,46.154.0,42.130.0"}
P.entries["item:glyphs-of-summoning"] = {n="Glyphes d'invocation",s="À Orgrimmar, les démonistes préparent les Glyphes d'invocation pour appeler un marcheur du vide. Les inscriptions proviennent de l'ancienne Tablette de Verga et attirent une créature du Néant distordu dans un cercle d'invocation, où elle peut être liée au service du démoniste.",h="À Orgrimmar, les démonistes préparent les Glyphes d'invocation pour appeler un marcheur du vide.",kw={"la faille de l'ombre","gan'rul oeil-sanglant","glyphes d'invocation","neeru fireblade","orgrimmar","tablette de verga","the binding","marcheur du vide"},ang={["class:Warlock"]="En tant que démoniste de la Horde, vous devez franchir un rite de passage essentiel. Les glyphes vous permettent de prouver votre maîtrise du Vide et de vous assurer les services d'un marcheur du vide."},sec={{t="Un pacte forgé dans l'ombre",b="Dans la Faille de l'Ombre, les démonistes étudient les arts sombres, loin des gardes du Chef de guerre. Pour un démoniste en herbe qui apprend auprès de Gan'rul Oeil-sanglant, commander un marcheur du vide marque une étape importante. Les Glyphes d'invocation s'appuient sur la Tablette de Verga et relient Azeroth au Néant.\n\nDans la tente de Neeru Fireblade, le démoniste dispose les glyphes dans un cercle d'invocation. Ils ouvrent un passage et attirent une Creature of the Void dans le monde des mortels. Avant que Gan'rul ne lui enseigne les dernières méthodes d'asservissement, le démoniste doit vaincre la créature au combat."}},faq={{q="À quoi servent les Glyphes d'invocation ?",a="Les glyphes sont des inscriptions rituelles utilisées dans le cercle d'invocation, dans la tente de Neeru Fireblade à Orgrimmar. Ils appellent un marcheur du vide hostile depuis le Néant distordu, et le démoniste doit le maîtriser pour apprendre à l'invoquer.",al={"effet des glyphes d'invocation","but des glyphes d'invocation","utiliser les glyphes d'invocation"}},{q="D'où viennent les Glyphes d'invocation ?",a="Gan'rul Oeil-sanglant, le maître des démonistes dans la Faille de l'Ombre, fournit les glyphes. Ils s'appuient sur le savoir préservé sur la Tablette de Verga.",al={"où trouver les glyphes d'invocation","qui donne les glyphes d'invocation"}},{q="Où le rituel d'invocation a-t-il lieu ?",a="Le rituel a lieu dans la tente de Neeru Fireblade, de l'autre côté de la caverne, dans la Faille de l'Ombre à Orgrimmar.",al={"où invoquer un marcheur du vide","emplacement du cercle d'invocation à orgrimmar","cercle de neeru fireblade"}},{q="Pourquoi les démonistes doivent-ils vaincre la créature invoquée ?",a="Un démoniste doit établir sa domination pour contrôler sans danger un démon ou une créature du Vide. Vaincre la créature invoquée prouve sa détermination et permet à Gan'rul Oeil-sanglant de lui enseigner comment soumettre les créatures de son espèce à sa volonté.",al={"pourquoi combattre le marcheur du vide","maîtriser un marcheur du vide"}}},fx={["094a8ca5"]={q="Que sont les Glyphes d'invocation ?",a="Les Glyphes d'invocation sont des inscriptions arcaniques et démoniaques transcrites directement depuis la Tablette de Verga. Confiés aux démonistes en formation par Gan'rul Oeil-sanglant sous Orgrimmar, ils contiennent les incantations précises nécessaires pour déchirer le voile et appeler un marcheur du Vide hostile depuis le Néant pour l'asservir.",al={"que sont les glyphes d'invocation","lore des glyphes d'invocation","qu'est-ce que les glyphes d'invocation"}},fd669514={q="Pourquoi Gan'rul Oeil-sanglant veut-il récupérer les Glyphes d'invocation ?",a="Gan'rul Oeil-sanglant exige que vous rapportiez les glyphes accompagnés de la preuve de votre victoire afin qu'il puisse terminer votre formation. Une fois que vous avez démontré que vous avez la force d'invoquer et de soumettre un marcheur du Vide déchaîné, Gan'rul utilise les glyphes et votre maîtrise démontrée pour vous apprendre à lier définitivement de telles entités à votre service.",al={"pourquoi rendre les glyphes d'invocation","pourquoi gan'rul veut-il les glyphes d'invocation","pourquoi les glyphes d'invocation sont-ils recherchés"}}},fp="19,242,23.539.0,42.207.0,43.139.0,40.109.0,53.218.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="Indicateur Gnoam",s="Dans les Mortemines, Shoni la Shilencieuse cherche une source d’énergie pour l’expédition vers Gnomeregan. L’Indicateur Gnoam peut alimenter des foreuses destinées à percer la roche autour de l’ancien foyer des gnomes.",h="Dans les Mortemines, Shoni la Shilencieuse cherche une source d’énergie pour l’expédition vers Gnomeregan.",kw={"les mortemines","indicateur gnoam","gnomeregan","gyrodrillmatic","shoni la shilencieuse","sneed","déchiqueteur de sneed","indicateur sprecklesprocket"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous voyez comment cette alimentation intacte pourrait faire fonctionner des machines capables de percer les barrières rocheuses souterraines de Gnomeregan.",["race:Gnome"]="En tant que gnome, vous pouvez rapprocher chaque pièce récupérée du forage vers votre foyer perdu et de l’expulsion des troggs."},sec={{t="Une source d’énergie vitale",b="Au cœur du bastion défias, le déchiqueteur de Sneed coupe du bois sous la supervision du contremaître gobelin Sneed. Son noyau énergétique compact alimente de lourdes machines d’abattage et des lames de coupe. L’Indicateur Gnoam fournit une énergie constante à la machine, ce qui en fait une précieuse pièce de récupération dans les tunnels de la Marche de l’Ouest."},{t="Percer jusqu’à Gnomeregan",b="À Hurlevent, l’inventrice gnome Shoni la Shilencieuse a choisi le déchiqueteur des Mortemines pour une expédition de plus grande envergure. Les forces gnomes cherchent à reprendre Gnomeregan aux troggs qui l’ont envahie, mais des accès souterrains scellés leur barrent la route. Shoni prévoit d’alimenter de lourds Gyrodrillmatic Excavationators avec l’Indicateur Gnoam. Ces machines pourraient forer la roche autour de la techno-cité perdue et ouvrir une voie inattendue pour une attaque souterraine."}},faq={{q="Qu’est-ce que l’Indicateur Gnoam ?",a="L’Indicateur Gnoam est une alimentation à haut rendement provenant d’un déchiqueteur gobelin au cœur des Mortemines. Il peut alimenter de lourdes foreuses souterraines.",al={"indicateur sprecklesprocket","qu’est-ce que cet indicateur","quel est cet objet"}},{q="D’où vient l’Indicateur Gnoam ?",a="L’Indicateur Gnoam provient du déchiqueteur de Sneed, une machine industrielle à débiter le bois dans les scieries des Mortemines. Le contremaître gobelin Sneed la dirige.",al={"qui le fait tomber","comment obtenir l’indicateur sprecklesprocket","butin du déchiqueteur"}},{q="Pourquoi Shoni la Shilencieuse en a-t-elle besoin ?",a="Shoni la Shilencieuse a besoin de l’indicateur pour alimenter des Gyrodrillmatic Excavationators. Ces machines peuvent percer la roche autour de Gnomeregan et ouvrir une voie permettant aux gnomes alliés à l’Alliance d’attaquer les troggs.",al={"pourquoi shoni le veut","objet de quête de shoni"}},{q="L’indicateur relève-t-il de la technologie gobeline ou gnome ?",a="L’indicateur provient d’un déchiqueteur gobelin en état de marche dans les Mortemines, et Shoni prévoit de l’utiliser dans des foreuses gnomes. On ne sait pas qui a conçu cette pièce à l’origine.",al={"est-ce de la technologie gobeline","appareil gnome ou gobelin"}}},fp="22,198,20.274.0,20.444.0,35.152.0,48.156.0,35.211.0,45.170.0"}
P.entries["item:gnoll-paw"] = {n="Patte de gnoll",s="À la Colline des Sentinelles, les primes pour les pattes de gnoll aident à défendre les fermes de la Marche de l’Ouest contre les meutes Riverpaw. The People's Militia paie pour toute preuve que des patrouilles ont tué des gnolls.",h="À la Colline des Sentinelles, les primes pour les pattes de gnoll aident à défendre les fermes de la Marche...",kw={"danuvin","patte de gnoll","patrouilles dans la marche de l'ouest","the people's militia","riverpaw","colline des sentinelles","marche de l’ouest"},ang={["class:Hunter"]="En tant que chasseur, vous pouvez suivre les meutes Riverpaw dans les plaines ouvertes de la Marche de l’Ouest tout en contribuant à protéger les avant-postes ruraux.",["faction:Alliance"]="Pour les champions de l’Alliance, accepter les primes de The People's Militia aide à protéger le grenier occidental de Hurlevent contre les bêtes errantes et les bandits organisés."},sec={{t="Prime de The People's Militia",b="The People's Militia défend la Marche de l’Ouest depuis la Colline des Sentinelles. L’armée royale est absente, et la couronne semble ignorer les problèmes des campagnes. Les citoyens ordinaires et les volontaires affrontent donc les hors-la-loi, les mécanoïdes renégats et les gnolls Riverpaw.\n\nLe Capitaine Danuvin offre des primes en échange de preuves que des gnolls ont été tués. Leurs pattes montrent que les patrouilles ont fouillé les broussailles au lieu de se reposer sous la tour de garde."},{t="Une menace coordonnée",b="Les gnolls Riverpaw cherchent leur nourriture dans les plaines de la Marche de l’Ouest. Les observateurs de la milice ont remarqué des signes de coordination étroite entre les meutes et les voleurs défias basés autour des Mortemines. Les gnolls terrorisent les fermes et s’en prennent aux convois de ravitaillement, contribuant ainsi à protéger les bandits de la résistance locale.\n\nRapporter des pattes de gnoll aide à garder ouvertes les routes entre la Colline des Sentinelles et la Forêt d’Elwynn."}},faq={{q="Pourquoi le Capitaine Danuvin veut-il des pattes de gnoll ?",a="Le Capitaine Danuvin demande des pattes de gnoll pour prouver qu’une patrouille a traversé les plaines de la Marche de l’Ouest et tué des gnolls. Avec peu de moyens et sans aide de la couronne, la milice paie des primes pour obtenir ces preuves.",al={"pourquoi récolter des pattes","pattes de gnoll du capitaine danuvin","à quoi servent les pattes de gnoll"}},{q="Quels gnolls donnent ces pattes ?",a="Ces pattes proviennent de gnolls Riverpaw qui rôdent dans les prairies, les collines et les fermes abandonnées de la Marche de l’Ouest.",al={"où trouver des pattes de gnoll","quels gnolls ont des pattes","emplacement des pattes de gnoll"}},{q="Les gnolls agissent-ils seuls dans la Marche de l’Ouest ?",a="Non. Le Capitaine Danuvin et la milice soupçonnent les gnolls Riverpaw de collaborer avec les bandits et les voleurs basés autour des Mortemines. Ensemble, ils menacent les fermes locales.",al={"les gnolls travaillent-ils avec les défias","lien entre les gnolls et les mortemines","qui commande les gnolls"}},{q="Pourquoi Hurlevent ne s’occupe-t-elle pas de la menace des gnolls ?",a="Hurlevent a largement laissé la Marche de l’Ouest se débrouiller seule, en raison des troubles intérieurs et de la paralysie politique. Les fermiers locaux et The People's Militia assument presque toute la défense des campagnes.",al={"pourquoi l’armée de hurlevent n’intervient-elle pas","où est l’armée","pourquoi la milice combat-elle les gnolls"}}},fx={aa4b645a={q="Qu'est-ce qu'une Patte de gnoll ?",a="Une Patte de gnoll est une main tranchée prise sur un gnoll Patte-de-rivière rôdant dans les plaines de la Marche de l’Ouest. Pour la Milice populaire stationnée à la Colline des Sentinelles, ces trophées macabres servent de preuve physique indéniable qu'un aventurier a activement patrouillé le territoire et éliminé les meutes de gnolls agressives menaçant les fermes locales.",al={"qu'est-ce qu'une patte de gnoll","objet patte de gnoll","que sont les pattes de gnoll"}},["96952327"]={q="D'où viennent les Pattes de gnoll ?",a="Ces pattes proviennent directement des gnolls sauvages Patte-de-rivière disséminés à travers les prairies et les fermes abandonnées de la Marche de l’Ouest. Les gnolls féraux errent dans la région pour s'en prendre aux fermiers et se coordonner avec les hors-la-loi, faisant de leurs pattes tranchées une sinistre prime prise directement sur les pillards tombés au combat.",al={"où obtenir des pattes de gnoll","qui lâche des pattes de gnoll","source de la patte de gnoll"}}},fp="9,161,21.403.0,20.379.1,41.199.0,29.98.0,40.159.1,50.195.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Boule de gomme de Gnomeregan",s="À la Sanssaint, les Boules de gomme de Gnomeregan parviennent aux voyageurs grâce aux gnomes exilés. Une friandise aide Jesper, malade, à célébrer la fête à l’orphelinat de Hurlevent.",h="À la Sanssaint, les Boules de gomme de Gnomeregan parviennent aux voyageurs grâce aux gnomes exilés.",kw={"friandise","boule de gomme de gnomeregan","sanssaint","forgefer","jesper","hurlevent","talvash del kissel"},ang={["faction:Alliance"]="Vous parcourez les communautés humaines, naines et gnomes pour réunir cette friandise. La fête de saison témoigne des liens étroits qui unissent l’Alliance.",["race:Gnome"]="Même si les gnomes n’ont pas leur propre ville reconquise, leur friandise emblématique rejoint celles des grandes capitales de l’Alliance pendant la Sanssaint."},sec={{t="L’ingéniosité gnome",b="Dans le Mystic Ward de Forgefer, Talvash del Kissel donne des Boules de gomme de Gnomeregan aux voyageurs qui se prêtent à ses tours de la Sanssaint. Les aubergistes de l’Alliance offrent des friandises de leurs terres, mais les gnomes exilés n’ont pas d’auberge dans leur propre capitale. La catastrophe radioactive les a chassés de leur royaume souterrain. Ils partagent tout de même leurs friandises si particulières avec l’Alliance."},{t="Une friandise pour Jesper",b="Jesper, malade, séjourne à l’orphelinat de Hurlevent, sur la Place de la Cathédrale, et ne peut pas parcourir les continents pour aller de porte en porte. Les voyageurs réunissent donc quatre friandises régionales des capitales de l’Alliance et les lui apportent : une Boule de gomme de Gnomeregan, un Nougat de Hurlevent, un Bonbon à la menthe de Forgefer et un Massepain de Darnassus."}},faq={{q="D’où vient la Boule de gomme de Gnomeregan ?",a="Talvash del Kissel distribue des Boules de gomme de Gnomeregan dans le Mystic Ward de Forgefer si vous vous prêtez à l’un de ses tours de la Sanssaint.",al={"qui donne la boule de gomme de gnomeregan","comment obtenir la boule de gomme","emplacement de la boule de gomme"}},{q="Pourquoi cette friandise n’est-elle pas distribuée à Gnomeregan ?",a="Les Troggs ont envahi Gnomeregan et l’ont irradiée, poussant les gnomes survivants à l’exil. Beaucoup vivent désormais aux côtés des nains à Forgefer, notamment Talvash del Kissel.",al={"pourquoi forgefer","pourquoi talvash est à forgefer"}},{q="À quoi sert cette friandise ?",a="Vous apportez cette friandise à Jesper, un orphelin malade de l’orphelinat de Hurlevent, sur la Place de la Cathédrale. C’est l’une des quatre friandises de fête réunies pour lui pendant la Sanssaint.",al={"à quoi sert la boule de gomme","friandise de jesper"}},{q="Quelles autres friandises faut-il réunir avec celle-ci ?",a="Jesper demande aussi un Nougat de Hurlevent, un Bonbon à la menthe de Forgefer et un Massepain de Darnassus. Vous réunissez chaque friandise dans sa capitale de l’Alliance respective.",al={"autres friandises","friandises de la sanssaint"}}},fx={["243db981"]={q="Qu'est-ce qu'une Boule de gomme de Gnomeregan ?",a="Une Boule de gomme de Gnomeregan est une confiserie festive représentant le peuple gnome, distribuée pendant la fête de la Sanssaint. Bien qu'elle porte le nom de la merveille technologique perdue de Gnomeregan, la friandise est distribuée par des gnomes réfugiés dans la capitale naine de Forgefer, notamment le bricoleur Talvash del Kissel.",al={"qu'est-ce qu'une boule de gomme de gnomeregan","bonbon boule de gomme de gnomeregan","lore de la boule de gomme gnome"}}},fp="18,142,28.371.0,18.281.0,42.121.0,46.162.0,28.168.0,45.130.0"}
P.entries["item:gnomish-tools"] = {n="Outils gnomes",s="Sur la côte de Durotar, la Horde récupère des outils gnomes de la flotte de Portvaillant. Ces appareils pourraient apprendre à ses artisans le fonctionnement de l’ingénierie de l’Alliance et comment l’adapter pour survivre.",h="Sur la côte de Durotar, la Horde récupère des outils gnomes de la flotte de Portvaillant.",kw={"durotar","ingénierie","gar'thok","outils gnomes","portvaillant","tranchecolline","côte des naufrages","donjon de tiragarde"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez aider à récupérer l’équipement perdu de l’Alliance pour l’étudier. Comprendre les plans ennemis et les mécanismes étrangers pourrait aider la Horde à se défendre contre de futures invasions navales.",["profession:Engineering"]="En tant qu’ingénieur, vous pouvez étudier ces nécessaires pour mieux comprendre le savoir-faire précis des bricoleurs de l’Alliance, leurs mécanismes d’horlogerie et leur miniaturisation."},sec={{t="Épaves englouties",b="La flotte du grand amiral Daelin Portvaillant transportait d’immenses réserves d’équipement moderne jusqu’à Durotar. Portvaillant mena Kul Tiras et les forces de l’Alliance sur ses rivages, avec à bord du matériel sophistiqué fabriqué par leurs alliés gnomes. Après la destruction de la flotte le long de la Côte des naufrages, à l’est du Donjon de Tiragarde, de délicats nécessaires mécaniques sombrèrent sous les flots. Des boîtes à outils étanches reposent encore parmi les poutres pourrissantes et les coques couvertes de bernacles dans les hauts-fonds."},{t="Des yeux à Orgrimmar",b="Gar'Thok, qui supervise Tranchecolline, a envoyé des éclaireurs de la Horde récupérer les outils dans la tombe aquatique de la flotte de Portvaillant. Les orcs savent que les humains et les gnomes maîtrisent l’ingénierie, notamment les engins de siège, la construction navale et l’horlogerie mécanique. Les nécessaires sont donc acheminés par caravane aux artisans et aux érudits d’Orgrimmar. La Horde compte y étudier les inventions de l’Alliance, apprendre à contrer les machines de guerre ennemies et adapter les innovations étrangères pour assurer sa propre survie."}},faq={{q="Pourquoi trouve-t-on des outils gnomes au large de la côte de Durotar ?",a="La flotte du grand amiral Daelin Portvaillant transportait les outils lorsque Kul Tiras attaqua Durotar. Quand l’armada fut brisée et sombra le long de la Côte des naufrages, à l’est du Donjon de Tiragarde, sa cargaison navale se déposa au fond de l’océan.",al={"pourquoi des outils gnomes ici","origine des outils gnomes","comment les outils sont arrivés à durotar"}},{q="Pourquoi la Horde veut-elle ces outils ?",a="Gar'Thok, de Tranchecolline, veut que les outils soient récupérés et envoyés à Orgrimmar. En étudiant le travail minutieux des ingénieurs de l’Alliance, la Horde espère comprendre les machines ennemies et fabriquer son propre équipement amélioré.",al={"pourquoi gar'thok veut des outils","utilité des outils gnomes pour la horde","à quoi servent les outils"}},{q="Où trouve-t-on les outils ?",a="Les outils se trouvent dans des boîtes éparpillées dans les épaves englouties et autour de celles-ci, le long de la Côte des naufrages de Durotar, juste à l’est du Donjon de Tiragarde. Beaucoup reposent sous l’eau ou sur des coques brisées à moitié submergées.",al={"emplacement des outils gnomes","où trouver les outils gnomes","emplacement des boîtes à outils gnomes"}}},fx={bc7dc32b={q="Qu'est-ce que ces Outils gnomes ?",a="Ce sont des instruments mécaniques spécialisés fabriqués par les gnomes de l'Alliance. Très prisés pour leur précision et leur conception complexe, ils représentent l'une des ingénieries les plus sophistiquées d'Azeroth. Transportés à bord des navires de guerre du Grand Amiral Proudmoore pour entretenir et réparer les machines avancées de l'Alliance, ils ont été éparpillés sur le fond marin au large de Durotar lorsque sa flotte a fait naufrage.",al={"que sont les outils gnomes","infos sur les outils gnomes"}}},fp="13,208,14.447.0,17.457.0,53.225.0,36.204.0,26.188.0"}
P.entries["item:goggles-of-gem-hunting"] = {n="Lunettes de chasse aux gemmes",s="Les Lunettes de chasse aux gemmes, appareil gnome, révèlent les trésors sous-marins des Hautes-terres Arathies. Leur enchantement révèle les gemmes enfouies dans la pierre au fond de la mer.",h="Les Lunettes de chasse aux gemmes, appareil gnome, révèlent les trésors sous-marins des Hautes-terres...",kw={"hautes-terres arathies","docteur draxlegauge","gemmes elfiques","crique de faldir","lunettes","lunettes de chasse aux gemmes","professeur phizzlethorpe","trésor englouti"},ang={["profession:Engineering"]="En tant qu'ingénieur, vous pourrez admirer comment les lunettes du Docteur Draxlegauge allient la fabrication gnome à l'enchantement du Professeur Phizzlethorpe.",["race:Gnome"]="En tant que gnome, vous pourrez apprécier l'ingéniosité du Docteur Draxlegauge dans cet appareil conçu pour trouver des gemmes sous la mer."},sec={{t="Sous les flots",b="Au large de la Crique de Faldir, le Docteur Draxlegauge prête les Lunettes de chasse aux gemmes à l'équipage du capitaine O'Breen. Le Professeur Phizzlethorpe imprègne l'appareil d'une pierre enchantée, lui donnant le pouvoir de repérer les gemmes sous l'eau. Le trésor repose sous l'eau depuis si longtemps que ses gemmes se sont calcifiées en une épaisse couche de pierre. Draxlegauge demande que les lunettes lui soient rendues une fois les recherches terminées."}},faq={{q="Qui a fabriqué les lunettes ?",a="Le Docteur Draxlegauge a construit les Lunettes de chasse aux gemmes, et le Professeur Phizzlethorpe les a imprégnées d'une pierre enchantée.",al={"fabricant des lunettes","qui les a construites","lunettes de draxlegauge"}},{q="À quoi servent les lunettes ?",a="Les lunettes permettent à leur porteur de repérer les gemmes sous la mer, même lorsque celles-ci se sont calcifiées en une épaisse couche de pierre.",al={"fonctionnement des lunettes","trouver des gemmes","lunettes de chasse aux gemmes"}},{q="Où utilise-t-on les lunettes ?",a="Les Lunettes de chasse aux gemmes servent à explorer les fonds marins au large de la Crique de Faldir, dans les Hautes-terres Arathies.",al={"où utiliser les lunettes","emplacement des lunettes","lunettes de la crique de faldir"}},{q="Pourquoi le capitaine O'Breen veut-il les gemmes ?",a="Le Docteur Draxlegauge vous demande de trouver les gemmes englouties pour le capitaine O'Breen. Le récit fourni ne donne aucune autre raison à l'intérêt du capitaine.",al={"le capitaine veut des gemmes","pourquoi recueillir des gemmes elfiques","trésor d'o'breen"}}},fp="22,175,17.367.0,21.126.0,23.109.0,27.98.0,39.145.0"}
P.entries["item:gold-dust"] = {n="Poussière d'or",s="Dans la Forêt d’Elwynn, la Poussière d'or passe des mains des kobolds à celles des acheteurs locaux. Les mineurs cherchent toujours des filons entiers.",h="Dans la Forêt d’Elwynn, la Poussière d'or passe des mains des kobolds à celles des acheteurs locaux.",kw={"elwynn","fargodeep","poussière d'or","comté-de-l’or","goldtooth","jasperlode","kobold","remy deux fois"},ang={["class:Rogue"]="En tant que voleur, vous pouvez découvrir comment le monde interlope fait circuler la poussière brute et non tracée par l'intermédiaire de marchands louches comme Remy « Deux fois », dissimulant ainsi des richesses aux magistrats de Hurlevent.",["profession:Mining"]="En tant que mineur, vous recherchez au pic et à la batée des filons de cuivre et d'étain. La poussière des kobolds laisse penser que les galeries souterraines d’Elwynn recèlent des filons plus riches que ne le révèlent les relevés habituels."},sec={{t="Une bourse pleine de débris",b="Les kobolds creusent dans les mines de Fargodeep et Veine-de-jaspe, sous la Forêt d’Elwynn. Au lieu de raffiner la poussière d'or qu'ils trouvent, ils la gardent dans leurs poches et leurs bourses. Les colporteurs et receleurs locaux convoitent ces débris, dans l'espoir de faire du profit sans payer les taxes officielles de fonte."},{t="Le marché noir de Comté-de-l’Or",b="À Comté-de-l’Or, Remy « Deux fois » demande aux voyageurs de lui rapporter la poussière d'or récupérée. Il prétend offrir le meilleur prix du village et échange des pièces et des jetons suspects contre de la poussière brute, pour le compte d'associés anonymes. Les voyageurs récupèrent l'or auprès des kobolds, tandis que les courtiers s'enrichissent sous le nez des gardes de Hurlevent."}},faq={{q="D'où vient la Poussière d'or ?",a="Les kobolds de toute la Forêt d’Elwynn transportent de la Poussière d'or. Mineurs, tunneliers, géomanciens et leur chef Goldtooth la récoltent et l'amassent en creusant les collines.",al={"comment obtenir de la poussière d'or","butin de poussière d'or","où trouver de la poussière d'or"}},{q="Quelles mines abritent le plus de kobolds portant de la Poussière d'or ?",a="Les kobolds chargés de poussière infestent la mine de Fargodeep, au sud de Comté-de-l’Or, et la Mine Veine-de-jaspe, au nord-est.",al={"où se trouvent les mines","meilleure mine pour la poussière d'or","emplacement des mines"}},{q="Qui achète la Poussière d'or dans la Forêt d’Elwynn ?",a="Remy « Deux fois », un marchand louche installé devant l’Auberge de la Fierté du Lion, à Comté-de-l’Or, achète les bourses de Poussière d'or récupérées en échange d'argent et de jetons fournis par ses associés.",al={"qui veut de la poussière d'or","remy deux fois poussière d'or","rendre la poussière d'or"}},{q="Pourquoi les kobolds transportent-ils de la poussière plutôt que des lingots ?",a="Les kobolds manquent de discipline et de moyens pour fondre correctement le minerai. En creusant la roche avec des pioches grossières, ils en accumulent la poussière d'or sur leurs affaires et dans de petites bourses qu'ils portent comme des bibelots brillants.",al={"pourquoi les kobolds ont de la poussière","or des kobolds"}}},fx={["38570104"]={q="Qu'est-ce que la Poussière d'or ?",a="La Poussière d'or consiste en de fines parcelles brutes d'or précieux extraites par les infestations de kobolds tapies sous la Forêt d’Elwynn. Plutôt que de la monnaie raffinée ou des lingots fondus, il s'agit du résidu brut que les kobolds extraient directement des riches filons dans des endroits comme les mines de Fargodeep et Jasperlode.",al={"qu'est-ce que la poussière d'or","objet poussière d'or","à propos de la poussière d'or"}},["4a74ebdb"]={q="Pourquoi Remy « Deux fois » veut-il de la Poussière d'or ?",a="Remy « Deux fois » au Comté-de-l’Or achète de la poussière d'or brute pour son propre commerce et ses associés louches. Les kobolds ont peu le sens de la fonte des lingots, laissant beaucoup de richesses minérales non répertoriées sur leurs corps pour quiconque est assez audacieux pour les leur prendre et les revendre.",al={"pourquoi remy veut-il la poussière d'or","pourquoi vouloir la poussière d'or","pourquoi remy deux fois veut-il la poussière d'or"}}},fp="9,107,22.262.0,24.318.1,31.158.0,53.101.0,36.153.0,44.201.0"}
P.entries["item:golem-oil"] = {n="Golem Oil",s="L’huile Golem Oil est récoltée sur les golems et les élémentaires de la Gorge des Vents brûlants. Velarok Windblade en a besoin pour préparer une torche destinée aux quatre tours de guet.",h="L’huile Golem Oil est récoltée sur les golems et les élémentaires de la Gorge des Vents brûlants.",kw={"élémentaires","flamme parfaite","golem oil","golems","hearts of flame","gorge des vents brûlants","tours de guet","torch of flawless flame","velarok windblade"},sec={{t="De l’huile pour la torche",b="Velarok Windblade demande quatre globes de Golem Oil dans la Gorge des Vents brûlants. Il lui en faut avec quatre Hearts of Flame pour fabriquer la Torch of Flawless Flame, destinée à embraser les quatre tours de guet. Les golems et les élémentaires de ces terres sont les premières créatures à chercher pour trouver ces matériaux."}},faq={{q="À quoi sert Golem Oil ?",a="Velarok Windblade utilise quatre globes de Golem Oil et quatre Hearts of Flame pour fabriquer la Torch of Flawless Flame.",al={"utilisation de golem oil","pourquoi récolter golem oil"}},{q="Qui a besoin de Golem Oil ?",a="Velarok Windblade demande du Golem Oil dans la Gorge des Vents brûlants pour pouvoir fabriquer la Torch of Flawless Flame.",al={"qui veut l’huile","huile de velarok"}},{q="Où trouver Golem Oil ?",a="Les golems et les élémentaires de la Gorge des Vents brûlants sont les premières créatures à chercher pour trouver du Golem Oil.",al={"où trouver golem oil","source d’huile"}},{q="De quelle quantité de Golem Oil Velarok a-t-il besoin ?",a="Velarok Windblade demande quatre globes de Golem Oil.",al={"combien de globes","quantité d’huile"}},{q="À quoi doit servir la Torch of Flawless Flame ?",a="La Torch of Flawless Flame doit embraser les quatre tours de guet.",al={"torche de la flamme parfaite","but de la torche"}}},fp="9,144,17.275.0,22.111.0,20.98.0,27.89.0,37.52.0,48.74.0"}
P.entries["item:golm-fragment"] = {n="Fragment Golm",s="Sur le site de fouilles du sud des Paluns, le Fragment Golm fait partie des quatre morceaux manquants de la Pierre de Goaz. Les archéologues nains en ont besoin pour reconstituer les anciennes inscriptions des Titans.",h="Sur le site de fouilles du sud des Paluns, le Fragment Golm fait partie des quatre morceaux manquants de la...",kw={"site de fouilles","pierre de goaz","fragment golm","uncovering the past","les paluns","whelgar"},ang={["faction:Alliance"]="En tant que membre de l'Alliance, vous aidez la Ligue des explorateurs à préserver de précieuses connaissances anciennes avant que les raptors ne submergent le site de fouilles.",["race:Dwarf"]="En tant que nain, vous pouvez aider à reconstituer la Pierre de Goaz et découvrir vos origines liées aux Titans ainsi que l'histoire cachée sous Khaz Modan."},sec={{t="Un morceau de la Pierre de Goaz",b="Le Fragment Golm repose parmi les vestiges du chantier de Whelgar, dans le sud des Paluns. Le Prospecteur Whelgar a découvert la monumentale Pierre de Goaz peu avant que des raptors ne repoussent la Ligue des explorateurs. Son inscription avait été sectionnée en quatre endroits. Après l'invasion du site, le fragment est resté au milieu de la terre et des caisses renversées, caché dans une boîte à reliques ancienne jusqu'à ce que des explorateurs puissent le récupérer."},{t="Secrets des Titans",b="Le Fragment Golm complète un texte cryptique des Titans lorsqu'il est assemblé avec les fragments Ados, Modr et Neru. La reconstitution de la Pierre de Goaz permet à Whelgar de déchiffrer des lignes évoquant un plan divin, une prophétie funeste et d'anciennes entités enchaînées sous terre. L'inscription révèle un savoir plus ancien et plus dangereux que le seul héritage nain."}},faq={{q="À quoi sert le Fragment Golm ?",a="Le Prospecteur Whelgar a besoin du Fragment Golm et de trois autres morceaux pour reconstituer la Pierre de Goaz sur le site de fouilles des Paluns, pendant Uncovering the Past.",al={"utilité du fragment golm","pourquoi avoir besoin du fragment golm","quête du fragment golm"}},{q="Où trouver le Fragment Golm ?",a="Le Fragment Golm se trouve dans des reliques anciennes et sous la terre meuble du site de fouilles infesté de raptors, dans les collines du sud des Paluns.",al={"emplacement du fragment golm","trouver le fragment golm","où se trouve le fragment golm"}},{q="Que dit la Pierre de Goaz une fois reconstituée ?",a="La première traduction de Whelgar parle d'un plan divin et d'une prophétie funeste. Il lui faut les quatre fragments pour continuer à déchiffrer l'écriture incomplète des Titans.",al={"traduction de la pierre de goaz","que dit la tablette","traduction de whelgar"}},{q="Quels autres fragments faut-il pour reconstituer la pierre ?",a="Pour assembler la tablette, il vous faut les fragments Ados, Modr et Neru, ainsi que le fragment Golm.",al={"autres fragments de la tablette","morceaux de la pierre de goaz","quatre fragments"}}},fx={["523a83d7"]={q="Qu'est-ce que le Fragment Golm ?",a="Le Fragment Golm est l'un des quatre morceaux manquants brisés de la Pierre de Goaz, une relique ancienne découverte sur le site de fouilles dans Les Paluns. Il porte des inscriptions archaïques qui s'intègrent dans le récit cryptique de la tablette plus grande.",al={"qu'est-ce que le fragment golm","lore du fragment golm","qu'est-ce que la pièce golm"}},["890266ad"]={q="D'où vient le Fragment Golm et qui l'a fabriqué ?",a="Le fragment provenait à l'origine de la Pierre de Goaz, sculptée il y a longtemps en écriture titane. Il a été mis au jour lors de la fouille archéologique naine sur le site de fouilles des Paluns, avant que des raptors hostiles ne submergent la zone et n'en dispersent les morceaux brisés.",al={"qui a fabriqué le fragment golm","origine du fragment golm","d'où vient le fragment golm"}},["6695e471"]={q="Pourquoi le Prospecteur Whelgar veut-il le Fragment Golm ?",a="Le Prospecteur Whelgar a besoin du Fragment Golm ainsi que de ses morceaux complémentaires pour assembler la Pierre de Goaz complète. Sans cela, le texte traduit s'arrête brusquement, laissant des détails cruciaux sur un plan divin et une prophétie funeste manquants.",al={"pourquoi whelgar a-t-il besoin du fragment golm","qui veut le fragment golm","pourquoi chercher le fragment golm"}}},fp="13,178,25.394.0,21.324.1,35.148.0,37.127.0,44.151.1,52.83.0"}
P.entries["item:goodsteel-ledger"] = {n="Goodsteel Ledger",s="Le Goodsteel Ledger est une copie d’une liste conservée dans la Gorge des Vents brûlants. Elle énumère les marchandises que Krinkle Goodsteel souhaite recevoir à Gadgetzan.",h="Le Goodsteel Ledger est une copie d’une liste conservée dans la Gorge des Vents brûlants.",kw={"balanced flameberge","gadgetzan","registre de goodsteel","krinkle goodsteel","registre de tanaris","overdue package","gorge des vents brûlants","solid crystal leg shaft"},sec={{t="Le Goodsteel Ledger",b="Près d’une latrine, dans la Gorge des Vents brûlants, se trouve le Goodsteel Ledger, une copie destinée à Krinkle Goodsteel, à Gadgetzan. Ses pages énumèrent les marchandises qu’il recherche dans plusieurs endroits. Lui apporter le registre lance la recherche des objets qui y sont mentionnés."}},faq={{q="Qu’est-ce que le Goodsteel Ledger ?",a="Le Goodsteel Ledger est une copie de la liste des marchandises demandées par Krinkle Goodsteel, trouvée dans la Gorge des Vents brûlants.",al={"registre de goodsteel","liste de goodsteel","registre de tanaris"}},{q="Où trouver le registre ?",a="Le Goodsteel Ledger se trouve près d’une latrine, dans la Gorge des Vents brûlants.",al={"emplacement du registre","où se trouve le registre de goodsteel","registre de la gorge des vents brûlants"}},{q="Qui est Krinkle Goodsteel ?",a="Krinkle Goodsteel est un gnome de Gadgetzan qui recherche des marchandises de la Gorge des Vents brûlants et d’autres endroits.",al={"krinkle","type de goodsteel","qui veut le registre"}},{q="Que contient le registre ?",a="Le registre énumère Solid Crystal Leg Shafts, un Overdue Package et Goodsteel's Balanced Flameberge.",al={"que contient la liste","objets du registre","marchandises recherchées par goodsteel"}},{q="Où dois-je l’apporter ?",a="Apportez la copie du registre à Krinkle Goodsteel, à Gadgetzan, puis rassemblez les marchandises qui y sont énumérées.",al={"où apporter le registre","apporter le registre à krinkle","goodsteel à gadgetzan"}}},fp="16,131,10.229.0,29.102.0,27.58.0,25.103.0,26.99.0,23.98.0"}
P.entries["item:goodsteel-s-balanced-flameberge"] = {n="Goodsteel's Balanced Flameberge",s="Goodsteel’s Balanced Flameberge est l’un des objets recherchés par Krinkle Goodsteel pour son travail à Tanaris. Sa piste mène de la Gorge des Vents brûlants au Marais des Chagrins.",h="Goodsteel’s Balanced Flameberge est l’un des objets recherchés par Krinkle Goodsteel pour son travail à...",kw={"flameberge","gadgetzan","goodsteel’s balanced flameberge","jarquia","krinkle goodsteel","registre de tanaris","marais des chagrins"},sec={{t="Une place sur la liste",b="Dans la Gorge des Vents brûlants, le registre de Krinkle Goodsteel mentionne une flameberge équilibrée parmi les marchandises qu’il souhaite recevoir à Gadgetzan. Jarquia, un murloc de la côte est du Marais des Chagrins, porte l’arme. Une fois trouvée, elle peut être rapportée à Krinkle avec les autres marchandises de la liste."}},faq={{q="Qui veut la flameberge ?",a="Krinkle Goodsteel, à Gadgetzan, veut la flameberge équilibrée, qui figure dans son registre.",al={"qui en a besoin","épée de krinkle","qui veut cette arme"}},{q="Où trouver Goodsteel’s Balanced Flameberge ?",a="Jarquia, un murloc de la côte est du Marais des Chagrins, porte Goodsteel’s Balanced Flameberge.",al={"où se trouve la flameberge","trouver l’épée de goodsteel","où est jarquia"}},{q="Pourquoi veut-on cette flameberge ?",a="Krinkle Goodsteel a demandé cette arme parmi plusieurs marchandises inscrites dans son registre.",al={"pourquoi krinkle en a besoin","à quoi sert-elle","pourquoi récupérer cette épée"}},{q="« Flameberge » est-il bien orthographié ?",a="Le nom emploie « flameberge », bien que le mot s’écrive généralement « flamberge ».",al={"orthographe de flamberge","faute dans flameberge","est-ce une flamberge"}}},fp="31,162,19.280.0,25.92.0,51.106.0,29.84.0,39.83.0"}
P.entries["item:gordon-s-crate"] = {n="Caisse de Gordon",s="À Fossoyeuse, la Caisse de Gordon contient des armes pour la garnison isolée du Sépulcre. Les forces réprouvées de la Forêt des Pins-Argentés ont besoin de cette livraison.",h="À Fossoyeuse, la Caisse de Gordon contient des armes pour la garnison isolée du Sépulcre.",kw={"maître des chauves-souris","garde noir podrig","caisse de gordon","karos razok","michael garrett","ravitaillement de la forêt des pins-argentés","le sépulcre","fossoyeuse"},ang={["faction:Horde"]="En tant que membre de la Horde, vous voyez les routes aériennes des Réprouvés acheminer rapidement fournitures et courriers à travers Lordaeron, territoire disputé.",["race:Undead"]="En tant que Mort-vivant, vous savez que chaque livraison d'armes et d'équipement depuis la capitale contribue à défendre les fragiles frontières de Lady Sylvanas dans la Forêt des Pins-Argentés."},sec={{t="Ravitaillement de la Forêt des Pins-Argentés",b="Les Réprouvés envoient des fournitures depuis Fossoyeuse pour tenir la Forêt des Pins-Argentés. La Caisse de Gordon transporte des armes pour les défenseurs du Garde noir Podrig au Sépulcre. Les sentinelles y affrontent des worgens, des bêtes sauvages et des vestiges de l'humanité dans les bois."},{t="La route des maîtres des chauves-souris",b="Les routes depuis la capitale sont dangereuses et lentes, alors les précieuses cargaisons voyagent avec les maîtres des chauves-souris de Fossoyeuse. La Caisse de Gordon est destinée à Michael Garrett, le maître des chauves-souris installé au-dessus du Quartier des Marchands de la ville. Il organise le voyage à dos de chauve-souris dressée jusqu'au perchoir de Karos Razok au Sépulcre."}},faq={{q="Que contient la Caisse de Gordon ?",a="La Caisse de Gordon contient des armes et du matériel de combat essentiel, réquisitionnés à Fossoyeuse pour renforcer les sentinelles du Garde noir dans la Forêt des Pins-Argentés.",al={"contenu de la caisse de gordon","que contient la caisse"}},{q="À qui la Caisse de Gordon est-elle destinée ?",a="La Caisse de Gordon est destinée au Garde noir Podrig, au Sépulcre. Michael Garrett, maître des chauves-souris de Fossoyeuse, organise son transport aérien.",al={"qui reçoit la caisse de gordon","où va la caisse"}},{q="Pourquoi transporter la caisse par chauve-souris plutôt que par un courrier à pied ?",a="La Forêt des Pins-Argentés reste disputée et dangereuse. Les chauves-souris dressées, sous la supervision de Michael Garrett et de Karos Razok, transportent rapidement les cargaisons par les airs, à l'abri des menaces des routes terrestres.",al={"pourquoi transporter la caisse par les airs","caisse transportée par chauve-souris"}},{q="Pourquoi Michael Garrett vous demande-t-il de vous rendre d'abord au Sépulcre ?",a="Les chauves-souris des Réprouvés retournent instinctivement à la capitale. Pour qu'elles puissent voler sans risque vers une base éloignée comme le Sépulcre, vous devez d'abord établir le contact avec son maître des chauves-souris local, Karos Razok.",al={"pourquoi établir une route aérienne","condition pour voler en chauve-souris"}}},fx={df26763c={q="Qu'est-ce que la Caisse de Gordon ?",a="La Caisse de Gordon est une cargaison d'armes et de fournitures militaires vitales conditionnée à Fossoyeuse. Elle est spécifiquement préparée pour être transportée par un maître des chauves-souris vers l'avant-poste isolé des Réprouvés au Sépulcre.",al={"caisse de gordon","qu'est-ce que cette caisse"}},e23fc119={q="D'où vient la Caisse de Gordon et qui l'a préparée ?",a="La caisse provient de Fossoyeuse, où Gordon a emballé les fournitures de la garnison avant d'organiser sa livraison aux maîtres des chauves-souris.",al={"d'où vient la caisse de gordon","qui a emballé la caisse de gordon","qui a préparé la caisse de gordon"}},a5301c7a={q="Pourquoi quiconque voudrait-il la Caisse de Gordon ?",a="Le Garde noir Podrig et les soldats stationnés au Sépulcre ont désespérément besoin de cette cargaison. La caisse contient des armes nécessaires pour garantir que les Gardes noirs locaux défendant la Forêt des Pins-Argentés soient bien armés et ne soient pas pris au dépourvu face à leurs ennemis.",al={"pourquoi la caisse de gordon est-elle nécessaire","pourquoi apporter la caisse de gordon au sépulcre","qui a besoin de la caisse de gordon"}}},fp="14,148,23.233.0,23.282.0,30.142.0,42.134.0,65.191.0,66.192.0"}
P.entries["item:gordunni-cobalt"] = {n="Gordunni Cobalt",s="À l’Avant-poste des Gordunni, des lueurs bleues dans la terre attirent l’attention d’Orwin Gizzmick. Il espère que le cobalt enfoui lui rapportera un bon prix.",h="À l’Avant-poste des Gordunni, des lueurs bleues dans la terre attirent l’attention d’Orwin Gizzmick.",kw={"camp mojache","cobalt","féralas","gordunni","cobalt gordunni","avant-poste des gordunni","orwin gizzmick","pelle d’orwin"},sec={{t="Du bleu dans la terre",b="Nouvellement arrivé à Féralas, Orwin Gizzmick veut des échantillons du minerai que les ogres Gordunni enfouissent dans leur avant-poste. Il vous prête sa pelle et vous indique le nord depuis le Camp Mojache. Cherchez la lueur bleue parmi les monticules de terre ; Orwin veut le cobalt pour sa valeur marchande."}},faq={{q="Qui veut le cobalt Gordunni ?",a="Orwin Gizzmick, au Camp Mojache, veut douze échantillons de cobalt Gordunni.",al={"qui veut du cobalt","orwin et le cobalt","minerai de gizzmick"}},{q="Où trouver du cobalt Gordunni ?",a="Le cobalt se trouve dans des monticules de terre à l’Avant-poste des Gordunni, au nord du Camp Mojache, à Féralas.",al={"emplacement du cobalt","où trouver du cobalt","terre bleue"}},{q="Pourquoi le cobalt est-il enfoui ?",a="Les ogres Gordunni enfouissent le minerai pour empêcher les autres de mettre la main dessus.",al={"pourquoi enfoui","ogres qui enfouissent le cobalt","terre des gordunni"}},{q="Que veut faire Orwin du cobalt ?",a="Orwin espère trouver quelqu’un qui paiera un bon prix pour le cobalt.",al={"pourquoi orwin le veut","prix du cobalt","vendre du cobalt"}}},fp="15,127,16.277.0,30.71.0,33.85.0,25.82.0,36.69.0"}
P.entries["item:gordunni-orb"] = {n="Orbe Gordunni",s="Un Orbe Gordunni est un puissant objet magique pris aux Gordunni, en Féralas. Sa magie pourrait révéler le but de leur sombre cérémonie.",h="Un Orbe Gordunni est un puissant objet magique pris aux Gordunni, en Féralas.",kw={"camp mojache","sombre cérémonie","darkbriar lodge","féralas","gordunni","orbe gordunni","seigneur-mage","rok orhan","uthel'nay"},ang={["class:Mage"]="En tant que Mage, vous pouvez comprendre pourquoi Rok Orhan cherche l'orbe : sa magie pourrait révéler davantage sur la cérémonie des Gordunni.",["faction:Horde"]="En tant que membre de la Horde, vous pouvez aider Rok Orhan, du Camp Mojache, à en apprendre davantage sur les Gordunni et à préparer leur chute."},sec={{t="Orbe d'un mage",b="Rok Orhan, au Camp Mojache, cherche un Orbe Gordunni pour en apprendre davantage sur les Gordunni et leur magie. L'orbe est récupéré auprès de l'un des seigneurs-mages Gordunni. Son pouvoir pourrait aider à découvrir le but de leur sombre cérémonie."},{t="À Orgrimmar",b="Rok Orhan envoie l'Orbe Gordunni à Uthel'nay, à Darkbriar Lodge, à Orgrimmar. Uthel'nay reconnaît son grand pouvoir et vous avertit qu'il est dangereux."}},faq={{q="Qu'est-ce que l'Orbe Gordunni ?",a="L'Orbe Gordunni est un puissant objet magique détenu par les seigneurs-mages Gordunni, en Féralas.",al={"orbe gordunni","quel orbe","orbe de mage"}},{q="Qui veut l'orbe ?",a="Rok Orhan, au Camp Mojache, cherche l'orbe pour en apprendre davantage sur les Gordunni et leur magie.",al={"qui veut l'orbe","orbe de rok orhan","orbe du camp mojache"}},{q="À quoi sert l'orbe ?",a="Rok Orhan espère que le pouvoir de l'orbe aidera à en apprendre davantage sur la sombre cérémonie des Gordunni.",al={"but de l'orbe","pourquoi avoir besoin de l'orbe","à quoi sert-il"}},{q="Qui peut examiner l'orbe ?",a="Uthel'nay, à Darkbriar Lodge, à Orgrimmar, peut vous en apprendre davantage sur l'orbe.",al={"qui examine l'orbe","uthel'nay","mage et orbe"}},{q="Pourquoi l'orbe est-il dangereux ?",a="Uthel'nay affirme que l'Orbe Gordunni est très puissant et dangereux.",al={"danger de l'orbe","orbe dangereux","est-il puissant"}}},fp="12,141,12.213.0,12.147.0,25.85.0,18.89.0,25.89.0,24.70.0,25.63.0"}
P.entries["item:gorishi-queen-brain"] = {n="Gorishi Queen Brain",s="Le Gorishi Queen Brain est un spécimen prélevé sur la reine de la Balafre sinueuse. Des chercheurs de Gadgetzan veulent l’étudier pour en apprendre davantage sur les silithides et la force qui pourrait les contrôler.",h="Le Gorishi Queen Brain est un spécimen prélevé sur la reine de la Balafre sinueuse.",kw={"gadgetzan","gorishi","gorishi hive queen","gorishi queen brain","cristal de la ruche","intelligence malveillante","silithides","la balafre sinueuse","cratère d’un’goro"},sec={{t="Un esprit à étudier",b="Les chercheurs de Gadgetzan cherchent à obtenir le Gorishi Queen Brain après l’invocation de la Gorishi Hive Queen depuis sa chambre, au sud du Cratère d’Un’Goro. Ils soupçonnent que les silithides obéissent peut-être à une intelligence malveillante et espèrent que le cerveau de la reine les aidera à la comprendre. Leurs découvertes pourraient révéler davantage de choses sur la ruche que sur sa reine seule."}},faq={{q="Qu’est-ce que le Gorishi Queen Brain ?",a="Le Gorishi Queen Brain est un spécimen prélevé sur la Gorishi Hive Queen pour être étudié par des chercheurs de Gadgetzan.",al={"cerveau de la reine","cerveau gorishi","qu’est-ce que ce cerveau"}},{q="D’où vient le Gorishi Queen Brain ?",a="Il provient de la Gorishi Hive Queen, dans la Balafre sinueuse, au sud du Cratère d’Un’Goro.",al={"origine du cerveau","emplacement du cerveau de la reine","reine gorishi"}},{q="Pourquoi les chercheurs veulent-ils le cerveau de la reine ?",a="Les chercheurs de Gadgetzan espèrent que ce cerveau les aidera à comprendre les silithides et l’intelligence malveillante qu’ils soupçonnent de les contrôler.",al={"pourquoi vouloir le cerveau","à quoi sert le cerveau","étudier la reine"}},{q="Comment invoque-t-on la Gorishi Hive Queen ?",a="Un Gorishi Queen Lure utilisé sur un cristal dans les couveuses de la ruche est censé attirer la reine hors de son antre.",al={"invoquer la reine","leurre gorishi","comment attirer la reine"}},{q="La reine est-elle la seule présence silithide ?",a="Les chercheurs doutent que la Gorishi Hive Queen représente toute la présence des silithides.",al={"autres silithides","silithides encore présents","est-ce tout"}}},fp="19,174,15.327.0,32.110.0,45.88.0,42.137.0,39.95.0,40.97.0"}
P.entries["item:gorishi-queen-lure"] = {n="Gorishi Queen Lure",s="Le Gorishi Queen Lure attire la Gorishi Hive Queen hors de sa chambre, dans le Cratère d’Un’Goro. Des chercheurs de Gadgetzan ont besoin du cerveau de la reine pour étudier les silithid.",h="Le Gorishi Queen Lure attire la Gorishi Hive Queen hors de sa chambre, dans le Cratère d’Un’Goro.",kw={"gadgetzan","gorishi","gorishi hive","gorishi queen lure","cristal de la ruche","reine","cerveau de la reine","silithid","cratère d’un’goro"},sec={{t="Une ruche s’éveille",b="Dans la Gorishi Hive du Cratère d’Un’Goro, on pense qu’un cristal accorde les silithid entre eux à travers leur réseau de ruches. Le leurre est utilisé sur ce cristal pour attirer la reine. Des chercheurs de Gadgetzan veulent étudier son cerveau, car ils craignent qu’une intelligence malveillante ne contrôle les silithid."}},faq={{q="À quoi sert le Gorishi Queen Lure ?",a="Le Gorishi Queen Lure s’utilise sur un cristal de la Gorishi Hive pour attirer la Gorishi Hive Queen.",al={"utilisation du leurre à reine","rôle du leurre gorishi","fonctionnement du leurre"}},{q="Où utilise-t-on le leurre ?",a="Le leurre s’utilise sur un cristal des couveuses de la Gorishi Hive, dans le Cratère d’Un’Goro.",al={"où utiliser le leurre à reine","emplacement du leurre","où se trouve la gorishi hive"}},{q="Qui a fourni le leurre ?",a="Des chercheurs de Gadgetzan fournissent le Gorishi Queen Lure afin d’attirer la reine pour l’étudier.",al={"qui a fourni le leurre","origine du leurre","leurre de gadgetzan"}},{q="Pourquoi les chercheurs veulent-ils le cerveau de la reine ?",a="Les chercheurs ont besoin du cerveau de la Gorishi Hive Queen pour étudier les silithid et déterminer si une intelligence malveillante les contrôle.",al={"pourquoi le cerveau de la reine","raison du cerveau gorishi","à quoi sert le cerveau"}},{q="Qu’est-ce que le cristal de la ruche ?",a="On pense que le cristal accorde les silithid entre eux à travers leur réseau de ruches.",al={"cristal de la ruche","cristal des silithid","rôle du cristal"}}},fp="18,175,14.272.0,36.99.0,23.86.0,22.96.0,42.134.0,32.73.0"}
P.entries["item:grape-manifest"] = {n="Manifeste des vendanges",s="À l’abbaye de Comté-du-Nord, la récolte retrouvée de Milly Osworth rejoint les réserves après le vol des brigands.",h="À l’abbaye de Comté-du-Nord, la récolte retrouvée de Milly Osworth rejoint les réserves après le vol des...",kw={"frère neals","elwynn","manifeste des vendanges","milly osworth","abbaye de comté-du-nord","vignoble","vin"},ang={["profession:Cooking"]="En tant que cuisinier, vous voyez comment les récoltes des champs approvisionnent les réserves de l’abbaye et contribuent à nourrir sa communauté monastique.",["race:Human"]="En tant qu’humain, vous découvrez les premières difficultés du cœur de Hurlevent. Même la vie monastique et les récoltes les plus modestes ont besoin d’une défense armée contre les hors-la-loi qui rôdent."},sec={{t="Registre de la récolte",b="L’abbaye de Comté-du-Nord dépend des fermes voisines pour sa nourriture et ses boissons. La récolte perdue a mis ses réserves en danger. À présent, les caisses ont été récupérées, et les intendants peuvent équilibrer les stocks et préparer les tonneaux pour la fermentation. Le manifeste de Milly Osworth consigne les quantités nécessaires à leur planification."},{t="Le cellérier de l’abbaye",b="Frère Neals supervise la nourriture et les boissons de l’abbaye de Comté-du-Nord. Il aime goûter son vin dans le calme du clocher. Savoir que les raisins arrivent permet de fournir des boissons aux moines et aux recrues de passage. Chaque boisseau sauvé renforce les réserves de l’abbaye et apporte une bénédiction de la Sainte Lumière."}},faq={{q="Qu’est-ce que le Manifeste des vendanges ?",a="Le Manifeste des vendanges de Milly Osworth consigne la récolte récupérée dans son vignoble envahi. Il répertorie les raisins frais destinés à l’abbaye de Comté-du-Nord.",al={"qu’est-ce que le manifeste des vendanges","objet manifeste des vendanges"}},{q="Qui reçoit le manifeste ?",a="Frère Neals reçoit le manifeste de Milly Osworth. Il supervise les réserves de nourriture et de vin de l’abbaye et goûte souvent les cuvées dans le clocher de l’abbaye de Comté-du-Nord.",al={"qui reçoit le manifeste des vendanges","à qui donner le manifeste des vendanges","où va le manifeste des vendanges"}},{q="Pourquoi les raisins étaient-ils en danger ?",a="Les brigands Defias ont chassé Milly Osworth de son vignoble dans la vallée de Comté-du-Nord. La récolte était menacée et l’abbaye a perdu ses fruits frais jusqu’à l’intervention des recrues.",al={"pourquoi fallait-il sauver les raisins","brigands du vignoble","qu’est-il arrivé à la récolte de milly"}},{q="Que fait Frère Neals des raisins ?",a="Frère Neals utilise les raisins pour réapprovisionner les réserves de nourriture de l’abbaye et faire fermenter du vin frais de Comté-du-Nord. Ce vin approvisionne la fraternité qui y réside et les défenseurs de passage.",al={"à quoi servent les raisins","vin de l’abbaye"}}},fx={a2f30a46={q="D'où vient le Manifeste des vendanges et qui l'a fait ?",a="Le manifeste est rédigé par Milly Osworth, une fermière travaillant dans les vignobles de la Vallée de Comté-du-Nord. Après que vous l'ayez aidée à repousser les brigands Defias qui ont envahi ses champs et récupéré sa récolte, elle prépare ce registre pour documenter le rendement sauvé.",al={"qui a écrit le manifeste des vendanges","d'où vient le manifeste des vendanges","origine du manifeste des vendanges"}},cbb35726={q="Pourquoi le Manifeste des vendanges est-il nécessaire ?",a="Frère Neals gère les réserves de nourriture et de boisson pour l'Abbaye de Comté-du-Nord. Milly envoie le manifeste pour l'informer que sa récolte a été sauvée des bandits, permettant aux vignerons de l'abbaye de compter sur des fruits frais pour presser leur vin.",al={"pourquoi frère neals veut-il le manifeste des vendanges","but du manifeste des vendanges","pourquoi avoir besoin du manifeste des vendanges"}}},fp="14,104,23.282.0,20.303.0,27.142.0,26.154.0,30.162.0,43.168.0"}
P.entries["item:gray-bear-tongue"] = {n="Langue d'ours gris",s="Dans les Contreforts de Hautebrande, l’Apothicaire Lydon cherche des langues d’ours gris pour les expériences de la Société royale des apothicaires.",h="Dans les Contreforts de Hautebrande, l’Apothicaire Lydon cherche des langues d’ours gris pour les expériences...",kw={"apothicaire lydon","big samras","elixir de souffrance","langue d'ours gris","contreforts de hautebrande","société royale des apothicaires","moulin-de-tarren"},ang={["race:Undead"]="En tant que mort-vivant, vous aidez la Société royale des apothicaires à créer de nouvelles pestes contre les vivants. Vous récoltez des composants organiques sur la faune locale."},sec={{t="Recherches d’apothicaire à Hautebrande",b="Plusieurs variétés robustes d’ours gris rôdent dans les terres sauvages autour du Moulin-de-Tarren. L’Apothicaire Lydon utilise leurs langues comme ingrédient de base pour des solutions mortelles, dont l’Elixir de souffrance."}},faq={{q="Qui veut des langues d’ours gris ?",a="Au Moulin-de-Tarren, dans les Contreforts de Hautebrande, l’Apothicaire Lydon cherche des langues d’ours gris pour ses agents meurtriers expérimentaux.",al={"qui a besoin de langues d’ours","apothicaire lydon langues","remettre des langues d’ours"}},{q="À quoi l’apothicaire utilise-t-il ces langues ?",a="Lydon utilise les langues d’ours gris comme ingrédient organique principal dans l’Elixir de souffrance. Cette concoction est conçue pour aider à décimer les populations humaines vivantes de Hautebrande. L’Ichor de Rampemousse est un autre ingrédient.",al={"pourquoi lydon veut des langues","utilité des langues d’ours","ingrédients de l’elixir de souffrance"}},{q="Quelles créatures donnent ces langues ?",a="Les langues d’ours gris proviennent des ours gris des Contreforts de Hautebrande : ours gris ordinaires, ours gris anciens, ours gris féroces et Big Samras, une bête tristement célèbre.",al={"où trouver des langues d’ours","quels ours donnent des langues","ours de hautebrande"}}},fx={["57051fe5"]={q="Qu'est-ce qu'une Langue d'ours gris ?",a="C'est exactement ce que son nom indique : une langue fraîchement prélevée sur l'un des ours gris sauvages qui rôdent dans les Contreforts de Hautebrande. Bien que peu ragoûtantes pour la plupart des voyageurs, les alchimistes et les chercheurs parmi les Réprouvés apprécient les tissus animaux pour leurs propriétés chimiques spécifiques lors de la formulation de nouvelles décoctions.",al={"qu'est-ce qu'une langue d'ours gris","objet langue d'ours gris","que sont les langues d'ours gris"}},["4de594f1"]={q="D'où provient une Langue d'ours gris ?",a="Ces langues sont récoltées directement sur les ours gris qui rôdent dans les forêts et les collines entourant le Moulin-de-Tarren, dans les Contreforts de Hautebrande. Les chasseurs peuvent les obtenir sur des ours gris communs, des spécimens anciens, des variantes vicieuses ou des bêtes notables comme Big Samras.",al={"source langue d'ours gris","d'où viennent les langues d'ours gris","qui donne les langues d'ours gris"}}},fp="16,112,32.187.0,28.112.0,47.207.0,35.162.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-i"] = {n="Les vertes collines de Strangleronce - Chapter I",s="Les pages éparses des Vertes collines de Strangleronce ont été rassemblées dans le chapitre I. Barnil réunit les chapitres pour le manuscrit de Master Nesingwary.",h="Les pages éparses des Vertes collines de Strangleronce ont été rassemblées dans le chapitre I.",kw={"barnil","chapitre i","chapitre un","les vertes collines de strangleronce","manuscrit","master nesingwary","pages éparses","vallée de strangleronce"},sec={{t="Pages éparses",b="Une rafale a traversé le camp de Master Nesingwary et dispersé les pages de son manuscrit dans toute la Vallée de Strangleronce. Barnil en a rassemblé beaucoup, mais il manquait encore des pages pour les quatre chapitres. Ce chapitre fait partie du livre que Barnil reconstitue, et il est prêt à organiser les pages une fois qu’elles auront été retrouvées."}},faq={{q="Qu’est-ce que le chapitre I ?",a="Le chapitre I est l’une des quatre parties du manuscrit éparpillé de Master Nesingwary, Les vertes collines de Strangleronce.",al={"vertes collines chapitre un","livre chapitre i","que contient ce chapitre"}},{q="Qui est Barnil ?",a="Barnil aide à reconstituer le manuscrit de Master Nesingwary et demande les chapitres lorsqu’ils sont terminés.",al={"qui est barnil","qui veut les pages","manuscrit de barnil"}},{q="Pourquoi les pages sont-elles éparpillées ?",a="Une violente rafale a traversé le camp de Master Nesingwary et dispersé des pages du manuscrit dans toute la jungle.",al={"pages envolées","pourquoi des pages manquent","pages du manuscrit"}},{q="Qui a écrit Les vertes collines de Strangleronce ?",a="Master Nesingwary est l’auteur des Vertes collines de Strangleronce, un roman que Barnil aide à reconstituer.",al={"livre de nesingwary","qui a écrit les vertes collines","manuscrit de master nesingwary"}}},fp="40,160,15.305.0,18.115.0,14.109.0,28.117.0,43.104.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-ii"] = {n="Les vertes collines de Strangleronce - Chapter II",s="Le chapitre II est l’une des quatre parties du manuscrit dispersé de Master Nesingwary, Les vertes collines de Strangleronce. Il faut rassembler ses pages pour que Barnil puisse remettre les chapitres en ordre et rendre le livre à Nesingwary.",h="Le chapitre II est l’une des quatre parties du manuscrit dispersé de Master Nesingwary, Les vertes collines...",kw={"barnil","chapitre 2","chapitre ii","les vertes collines de strangleronce","manuscrit","nesingwary","pages dispersées","vallée de strangleronce"},sec={{t="Pages dispersées",b="Barnil avait rassemblé la majeure partie du manuscrit lorsqu’une bourrasque traversa le camp de Master Nesingwary. Les pages du chapitre II furent dispersées dans la Vallée de Strangleronce avec le reste. Vous pouvez aider Barnil à remettre les quatre chapitres en ordre, puis les lui rapporter."}},faq={{q="Qu’est-ce que le chapitre II ?",a="Le chapitre II est une partie du manuscrit de Master Nesingwary, Les vertes collines de Strangleronce.",al={"chapitre 2","vertes collines chapitre ii"}},{q="Qui rassemble les chapitres ?",a="Barnil rassemble et organise les chapitres dispersés pour Master Nesingwary.",al={"qui veut les pages","pages de barnil"}},{q="Pourquoi les pages sont-elles dispersées ?",a="Une forte bourrasque a traversé le camp de Master Nesingwary et dispersé les pages du manuscrit dans la jungle.",al={"qu’est-il arrivé aux pages","le vent a emporté les pages"}},{q="Que dois-je faire des chapitres ?",a="Rassemblez les quatre chapitres et rapportez-les à Barnil pour qu’il les organise pour Master Nesingwary.",al={"où rapporter les chapitres","de quoi barnil a-t-il besoin"}},{q="Qui a écrit Les vertes collines de Strangleronce ?",a="Master Nesingwary est l’auteur de Les vertes collines de Strangleronce.",al={"livre de nesingwary","roman de master nesingwary"}}},fp="41,210,15.253.0,19.93.0,30.81.0,28.116.0,35.97.0,43.68.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-iii"] = {n="Les vertes collines de Strangleronce - Chapter III",s="Le chapitre III est l’une des quatre parties éparses du manuscrit de Master Nesingwary, Les vertes collines de Strangleronce. Barnil rassemble les pages au camp de la Vallée de Strangleronce.",h="Le chapitre III est l’une des quatre parties éparses du manuscrit de Master Nesingwary, Les vertes collines...",kw={"barnil","chapitre trois","les vertes collines de strangleronce","manuscrit","nesingwary","pages éparpillées","vallée de strangleronce"},sec={{t="Pages éparses",b="Une rafale traversa le camp de Master Nesingwary, dans la Vallée de Strangleronce, et dispersa les pages du manuscrit dans la jungle. Barnil en rassembla la plupart, mais les quatre chapitres restent incomplets. Il collecte les pages pour remettre le manuscrit en ordre."}},faq={{q="Qu’est-ce que le chapitre III ?",a="Le chapitre III est l’une des quatre parties du manuscrit éparpillé de Master Nesingwary, Les vertes collines de Strangleronce.",al={"chapitre trois","chapitre trois des vertes collines"}},{q="Qui rassemble les pages ?",a="Barnil rassemble les pages éparpillées et organise les chapitres pour Master Nesingwary.",al={"qui veut les pages","pages de barnil"}},{q="Pourquoi les pages sont-elles éparpillées ?",a="Une forte rafale a traversé le camp de Master Nesingwary et dispersé les pages du manuscrit dans toute la jungle.",al={"qu’est-il arrivé aux pages","le vent a dispersé les pages"}},{q="Comment s’intitule le manuscrit ?",a="Le manuscrit s’intitule Les vertes collines de Strangleronce.",al={"livre de nesingwary","livre des vertes collines"}}},fp="42,178,15.266.0,20.117.0,28.90.0,28.114.0,30.58.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-iv"] = {n="Les vertes collines de Strangleronce - Chapter IV",s="Dans la Vallée de Strangleronce, Barnil doit remettre en ordre le manuscrit éparpillé de Master Nesingwary. Le chapitre IV est l’une des quatre pièces nécessaires pour compléter le livre.",h="Dans la Vallée de Strangleronce, Barnil doit remettre en ordre le manuscrit éparpillé de Master Nesingwary.",kw={"barnil","chapitre quatre","chapitre iv","les vertes collines de strangleronce","manuscrit","master nesingwary","pages éparpillées","vallée de strangleronce"},sec={{t="Pages éparpillées",b="Une bourrasque a traversé le camp de Master Nesingwary et dispersé des pages de son roman dans la jungle. Barnil en a rassemblé la plupart, mais les pages manquantes doivent encore être récupérées et réparties en quatre chapitres. Le chapitre IV doit rejoindre les trois autres avant que le manuscrit puisse être rendu à Barnil."}},faq={{q="Qu’est-ce que le chapitre IV ?",a="Le chapitre IV est l’un des quatre chapitres du roman de Master Nesingwary, Les vertes collines de Strangleronce.",al={"chapitre quatre","vertes collines chapitre iv","livre chapitre 4"}},{q="Qui a besoin de ce chapitre ?",a="Barnil rassemble les chapitres du manuscrit de Master Nesingwary et les réclame une fois les quatre réunis.",al={"qui veut le chapitre iv","à qui donner le chapitre quatre","pages de barnil"}},{q="Pourquoi les pages sont-elles éparpillées ?",a="Une forte bourrasque a traversé le camp de Master Nesingwary et dispersé des pages de son manuscrit dans la jungle.",al={"pourquoi des pages partout","qu’est-il arrivé au livre","le vent a dispersé les pages"}},{q="De quoi parle Les vertes collines de Strangleronce ?",a="C’est un roman de Master Nesingwary. Les chapitres réunis doivent permettre d’en compléter le manuscrit.",al={"roman de nesingwary","livre des vertes collines","qu’est-ce que le manuscrit"}}},fp="41,192,15.301.0,19.104.0,23.114.0,28.119.0,47.95.0"}
P.entries["item:gregor-s-remains"] = {n="Cadavre de Gregor",s="Le Cadavre de Gregor est recherché pour régler un vieux compte. Il appartenait à Gregor Agamand, issu de la famille la plus riche des Clairières de Tirisfal.",h="Le Cadavre de Gregor est recherché pour régler un vieux compte.",kw={"agamand","brill","coleman","deaths in the family","farthing","gregor","moulins","cadavre","fléau"},ang={["faction:Horde"]="Éliminer les forces du Fléau aux Moulins d'Agamand réduit la menace qui pèse encore sur les Clairières de Tirisfal.",["race:Undead"]="La tragédie des Agamand rappelle le sort de nombreux Réprouvés : des gens ordinaires trahis par l'orgueil des nobles et abandonnés aux horreurs de la peste."},sec={{t="Un héritage de ruines",b="Avant la Troisième guerre, les Agamand possédaient de grandes richesses et de vastes terres dans le nord des Clairières de Tirisfal. Lorsque le Fléau envahit Lordaeron, les patriarches de la famille choisirent l'orgueil plutôt que la fuite. Ils fortifièrent leurs moulins et exhortèrent leurs fidèles ouvriers à affronter les morts-vivants.\n\nLa défense échoua. Le domaine tomba, et ceux qui avaient tenu bon furent massacrés puis réanimés dans la non-mort. Gregor Agamand devint un serviteur décérébré du roi-liche, hantant les moulins que sa famille avait jadis dirigés."},{t="Le prix de la vengeance",b="Certains échappèrent à l'emprise du roi-liche et rejoignirent les Réprouvés, mais le souvenir de cette défense les blesse encore. Coleman Farthing, un ancien ouvrier du moulin désormais en poste à Brill, reproche à l'orgueil des Agamand d'avoir condamné son âme à une putréfaction éternelle. Il recherche le Cadavre de Gregor pour se venger personnellement du maître qui a mené sa maisonnée à la damnation."}},faq={{q="Qui était Gregor Agamand ?",a="Gregor Agamand était un membre éminent de la dynastie Agamand, la famille propriétaire des terres la plus riche des Clairières de Tirisfal avant la Troisième guerre. À l'arrivée de la peste de la non-mort, il fortifia son domaine avec sa famille au lieu de fuir. Le Fléau massacra tous ceux qui s'y trouvaient, puis les réanima.",al={"histoire de gregor","qui est gregor","gregor agamand"}},{q="Pourquoi Coleman Farthing veut-il le Cadavre de Gregor ?",a="Coleman Farthing travaillait autrefois aux Moulins d'Agamand. Il en veut à la famille d'avoir persuadé ses ouvriers de rester et de combattre le Fléau, un choix qui les a tous condamnés à la non-mort. Il recherche le Cadavre de Gregor pour assouvir une vengeance longtemps différée.",al={"pourquoi coleman veut le cadavre","rancune de coleman farthing","pourquoi récupérer les os de gregor"}},{q="Où trouver le Cadavre de Gregor ?",a="La forme réanimée de Gregor Agamand, dans les Moulins d'Agamand, au nord des collines des Clairières de Tirisfal, laisse tomber le cadavre.",al={"où trouver gregor","emplacement de gregor","gregor aux moulins d'agamand"}},{q="Les Agamand font-ils partie des Réprouvés ?",a="Non. Gregor Agamand et les siens restent des serviteurs décérébrés liés au Fléau, contrairement aux Réprouvés qui se sont libérés sous les ordres de la reine Sylvanas.",al={"gregor est-il réprouvé","les agamand font-ils partie du fléau","qui contrôle gregor"}}},fx={["6dd1de2a"]={q="Qu'est-ce que le Cadavre de Gregor ?",a="Il s'agit des restes physiques de Gregor Agamand, l'un des héritiers de la célèbre dynastie Agamand. Après avoir succombé à la peste de la non-mort, Gregor s'est relevé en tant que serviteur sans esprit du Fléau, hantant les ruines des moulins autrefois prospères de sa famille jusqu'à ce qu'il soit définitivement abattu.",al={"qu'est-ce que le cadavre de gregor","objet cadavre de gregor","qu'est-ce que cadavre de gregor"}},["45ae8d93"]={q="D'où provient le Cadavre de Gregor ?",a="Ces restes sont ce qu'il subsiste de Gregor Agamand après qu'il a été abattu aux Moulins d'Agamand, dans l'ouest des Clairières de Tirisfal. Lorsque le Fléau a balayé Lordaeron, sa famille a fortifié son domaine et a exhorté ses ouvriers à se défendre, pour finalement être tous massacrés et relevés sous forme de morts-vivants.",al={"origine cadavre de gregor","qui a fait le cadavre de gregor","d'où vient le cadavre de gregor"}}},fp="16,123,16.482.0,22.346.0,23.279.0,48.232.0,33.109.0,38.134.0"}
P.entries["item:grelin-s-report"] = {n="Rapport de Grelin",s="Dans la Vallée des Frigères, le Rapport de Grelin transmet à Kharanos des nouvelles des trolls Crindegivre. Il relie les éclaireurs de Courbenclume à Senir Blanchebarbe et à Forgefer.",h="Dans la Vallée des Frigères, le Rapport de Grelin transmet à Kharanos des nouvelles des trolls Crindegivre.",kw={"vallée des frigères","grelin blanchebarbe","rapport de grelin","sénat de forgefer","kharanos","montagnard thalos","senir blanchebarbe"},ang={["race:Dwarf"]="En tant que nain, porter ce rapport vous fait quitter les zones d’entraînement sûres de Frigère pour rejoindre le cœur de Dun Morogh et servir Forgefer.",["race:Gnome"]="En tant que réfugié gnome, remettre le message de Grelin vous permet de faire vos preuves auprès des montagnards nains en traversant les cols partagés de Dun Morogh."},sec={{t="Une dépêche au-delà des troggs",b="Grelin Blanchebarbe a observé les trolls Crindegivre dans la Vallée des Frigères et estime qu’ils ne représentent pas une grande menace. Les montagnards déjà sur place peuvent s’en charger, avec des mercenaires payés sur les fonds du Sénat. Grelin confie donc son rapport à un voyageur compétent plutôt qu’à son apprenti maladroit. Le trajet passe par la Passe des Frigères infestée de troggs.\n\nLe document indique au Montagnard Thalos que vous voyagez pour une affaire urgente. Grâce à lui, vous pouvez franchir son barrage et pénétrer dans les étendues enneigées de Dun Morogh."},{t="Des plumes froissées à Kharanos",b="À la Distillerie Tonnebière de Kharanos, Senir Blanchebarbe reçoit le rapport de terrain de Grelin destiné à Forgefer. Son frère a invoqué le nom du Roi Magni Barbe-de-Bronze tout au long du document, et Senir le remarque avec une résignation amusée. Grelin prétend que le Roi a approuvé ses actes. Senir s’attend à ce que cet appel à l’autorité royale fasse des vagues au Sénat de Forgefer."}},faq={{q="Quel est le but du Rapport de Grelin ?",a="Le Rapport de Grelin transmet à Senir, à Kharanos, l’évaluation des trolls Crindegivre de la Vallée des Frigères par Grelin Blanchebarbe. Il indique qu’ils ne représentent pas une grande menace et que les montagnards locaux peuvent s’en charger, avec des mercenaires payés par le Sénat.",al={"qu’est-ce que le rapport de grelin","pourquoi envoyer le rapport","but du rapport de grelin"}},{q="Pourquoi Grelin ne peut-il pas le remettre lui-même ?",a="Grelin reste dans la Vallée des Frigères pour surveiller les trolls. Il a d’abord envisagé d’envoyer son apprenti, mais le dangereux passage par le tunnel infesté de troggs l’a poussé à confier les documents à un voyageur aguerri au combat.",al={"pourquoi ne pas le remettre soi-même","pourquoi le confier à un aventurier"}},{q="Pourquoi le Montagnard Thalos vous laisse-t-il passer avec le rapport ?",a="Le Montagnard Thalos garde le tunnel qui mène de la Vallée des Frigères afin de protéger les civils des féroces troggs. Le Rapport de Grelin prouve que vous voyagez pour une affaire urgente concernant la défense des nains, alors Thalos vous laisse passer.",al={"pourquoi thalos me laisse passer","barrage du tunnel","troggs de la passe des frigères"}},{q="Pourquoi le Sénat de Forgefer est-il contrarié par le rapport ?",a="Senir Blanchebarbe affirme que Grelin a invoqué le nom du roi Magni tout au long du rapport. Les deux frères s’accordent à dire que les politiciens de Forgefer ont besoin d’un électrochoc, mais Senir s’attend à ce que l’appel de Grelin à l’autorité royale fasse des vagues au Sénat.",al={"pourquoi le sénat est furieux","faire des vagues","réaction de senir"}}},fx={cdcce173={q="Qu'est-ce que le Rapport de Grelin ?",a="Il s'agit d'une dépêche écrite par Grelin Blanchebarbe dans la Vallée des Frigères, adressée à son frère Senir Blanchebarbe à Kharanos. Elle détaille les observations locales et les questions urgentes dans la vallée, bien que Grelin ait invoqué le nom du roi Magni Bronzebeard avec suffisamment de liberté dans ses pages pour susciter la controverse parmi les sénateurs à Forgefer.",al={"qu'est-ce que le rapport de grelin","rapport de grelin"}},["9a092709"]={q="D'où provient le Rapport de Grelin et qui l'a rédigé ?",a="Le document a été rédigé par Grelin Blanchebarbe alors qu'il était en poste dans la Vallée des Frigères. Plutôt que de le confier à son apprenti, Grelin a décidé de le remettre entre les mains d'un voyageur capable pour garantir son voyage en toute sécurité vers l'est à travers le tunnel infesté de troggs menant vers le reste de Dun Morogh.",al={"qui a écrit le rapport de grelin","d'où vient le rapport de grelin","qui a fait le rapport de grelin"}},["6be6ebf1"]={q="Pourquoi quelqu'un voudrait-il le Rapport de Grelin ?",a="Son frère, Senir Blanchebarbe, attend la dépêche à Kharanos pour coordonner leurs conclusions avant de transmettre leurs rapports combinés à Forgefer. Le document est également vital pour vous personnellement : présenter la preuve d'une affaire officielle des Blanchebarbe est la seule raison pour laquelle le Montagnard Thalos vous autorise à passer par le dangereux tunnel infesté de troggs pour quitter la Vallée des Frigères.",al={"pourquoi le rapport de grelin est nécessaire","pourquoi senir veut le rapport de grelin"}}},fp="15,155,26.493.0,29.370.0,39.233.0,36.218.0,57.195.0,50.236.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Journal de Grelin Blanchebarbe",s="Grelin Blanchebarbe consigne l'activité des trolls Crine-de-givre dans un journal de terrain de la Vallée des Frigères. Grik'nir the Cold le vole et l'emporte dans The Troll Cave.",h="Grelin Blanchebarbe consigne l'activité des trolls Crine-de-givre dans un journal de terrain de la Vallée des...",kw={"vallée des frigères","dun morogh","repaire des crins-de-givre","grelin blanchebarbe","grik'nir the cold","senir blanchebarbe","journal volé"},ang={["race:Dwarf"]="En tant que nain, récupérer le journal de Grelin permet de préserver des connaissances essentielles sur la menace des trolls Crine-de-givre près des terrains d'entraînement de Forgefer."},sec={{t="Registre d'éclaireur",b="Grelin Blanchebarbe observe les trolls Crine-de-givre près de la Vallée des Frigères et note leurs actes. Son carnet relié en cuir consigne leur force, leur organisation et le danger qu'ils représentent. Grik'nir the Cold s'empare du journal lors d'un affrontement ou d'une embuscade. La brute troll marquée l'emporte dans The Troll Cave, privant Grelin des notes dont il a besoin pour achever son rapport. Il demande donc aux aventuriers de passage de récupérer le livre."},{t="Dépêche pour Senir",b="Grelin Blanchebarbe étudie les notes récupérées et estime que la menace des trolls Crine-de-givre dans la Vallée des Frigères est temporairement contenue. Grâce à ses notes, il achève une dépêche sur le soulèvement des Crine-de-givre. Des courriers portent le message scellé à son frère, Senir Blanchebarbe, en poste ailleurs dans Dun Morogh."}},faq={{q="Qui a volé le journal de Grelin Blanchebarbe ?",a="Grik'nir the Cold a volé le journal de Grelin Blanchebarbe. La brute troll Crine-de-givre, couverte de marques, l'a emporté dans The Troll Cave, dans la Vallée des Frigères.",al={"qui a pris le journal","qui détient le journal de grelin","voleur du journal de grelin"}},{q="Que contient le journal ?",a="Le journal de Grelin Blanchebarbe contient des notes de terrain sur les trolls Crine-de-givre de la région, le danger qu'ils représentent et la sécurité de la Vallée des Frigères.",al={"contenu du journal","que contient le journal","notes de grelin blanchebarbe"}},{q="Que se passe-t-il après la récupération du journal ?",a="Grelin utilise les notes récupérées pour achever un rapport sur les trolls. Il demande à un aventurier de le porter à son frère, Senir Blanchebarbe.",al={"que fait grelin du journal","après le journal volé"}},{q="Pourquoi ce journal est-il si important pour Grelin ?",a="Grelin a besoin de son journal pour préparer un rapport précis sur le soulèvement des Crine-de-givre à l'intention des autorités naines et de son frère Senir Blanchebarbe. Sans lui, l'état des défenses de la Vallée des Frigères reste incertain.",al={"pourquoi grelin veut-il le récupérer","importance du journal"}}},fx={["15978139"]={q="Qu'est-ce que le Journal de Grelin Blanchebarbe ?",a="Il s'agit d'un carnet personnel tenu par Grelin Blanchebarbe, un observateur en poste dans la Vallée des Frigères. À l'intérieur, Grelin consigne ses observations concernant l'activité locale des trolls Frostmane et prépare des rapports de terrain détaillant la situation défensive de la vallée.",al={"qu'est-ce que le journal de grelin blanchebarbe","journal de grelin","carnet de grelin"}},["9ed18e74"]={q="D'où provient le Journal de Grelin Blanchebarbe et qui l'a créé ?",a="Le journal a été compilé directement par le nain Grelin Blanchebarbe pendant sa surveillance de la Vallée des Frigères. Cependant, il lui a été arraché et emporté au fond de la grotte de trolls voisine par la brute Frostmane Grik'nir the Cold.",al={"qui a fait le journal de grelin","d'où vient le journal de grelin","origine journal de grelin"}}},fp="27,163,16.436.0,17.302.1,38.142.0,31.134.0,44.133.1,43.198.0"}
P.entries["item:grell-earring"] = {n="Boucle d'oreille de grell",s="À Bashal'Aran, la Boucle d'oreille de grell porte des traces du sceau qui lie Asterion.",h="À Bashal'Aran, la Boucle d'oreille de grell porte des traces du sceau qui lie Asterion.",kw={"asterion","bashal'aran","sombrivage","boucle d'oreille de grell","sceau","esprit vil","grell sauvage"},ang={["class:Mage"]="En tant que mage, vous pouvez voir comment le métal conserve avec le temps des traces de la magie ambiante des anciens sceaux de protection.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous voyez des ruines sacrées envahies par des esprits portant du laiton récupéré. Ce spectacle vous rappelle à quel point les domaines autrefois grandioses de l'ancien Kalimdor sont tombés en ruine."},sec={{t="Traces dans le laiton",b="Les grells sauvages et les esprits vils ramassent des débris parmi les ruines de Bashal'Aran et les façonnent en boucles d'oreilles. La plupart des mortels n'y voient que des babioles sans valeur. Mais Asterion, un ancien Elfe de la nuit lié à ces lieux sous la forme d'un spectre tourmenté, étudie la magie qu'elles conservent. Il espère que ces traces le mèneront au sceau ancien qui l'emprisonne."}},faq={{q="D'où viennent les boucles d'oreilles de grell ?",a="Les grells sauvages et les esprits vils transportent ces boucles d'oreilles dans les ruines de Bashal'Aran, une ancienne colonie des Elfes de la nuit à Sombrivage.",al={"butin de boucle d'oreille de grell","où trouver des boucles d'oreilles de grell","qui donne des boucles d'oreilles de grell"}},{q="Pourquoi Asterion veut-il ces boucles d'oreilles ?",a="Asterion est un ancien esprit retenu captif à Bashal'Aran par une puissante magie. Il cherche des traces du sceau qui lie son âme depuis des siècles.",al={"boucles d'oreilles d'asterion","pourquoi ramasser des boucles d'oreilles de grell","utilité de la boucle d'oreille de grell"}},{q="Comment ces boucles d'oreilles aident-elles Asterion à chercher le sceau ?",a="Asterion espère jeter un sort sur les boucles d'oreilles et suivre la trace du sceau qui emprisonne sa forme spectrale à Bashal'Aran.",al={"les boucles d'oreilles sont-elles magiques","les grells connaissent-ils la magie"}},{q="Asterion trouve-t-il ce dont il a besoin dans les boucles d'oreilles ?",a="Les boucles d'oreilles ne contiennent pas le sceau lui-même. Leurs traces montrent que les créatures se sont récemment approchées de lui, guidant Asterion plus profondément dans les ruines.",al={"les boucles d'oreilles ont-elles fonctionné","emplacement du sceau d'asterion"}}},fx={f6dd1a4f={q="Qu'est-ce qu'une Boucle d'oreille de grell ?",a="Une Boucle d'oreille de grell est une simple parure portée par les grells sauvages et les vils esprits qui infestent les ruines de Bashal'Aran à Sombrivage. Bien qu'il s'agisse de babioles banales en soi, ces accessoires récupérés ont absorbé les subtiles émanations magiques des ruines et de toutes les reliques que les créatures ont manipulées.",al={"qu'est-ce qu'une boucle d'oreille de grell","lore boucle d'oreille de grell","qu'est-ce que la boucle d'oreille de grell"}}},fp="13,75,19.322.0,34.120.0,38.141.0,54.116.0,51.146.0"}
P.entries["item:grenka-s-claw"] = {n="Griffe de Grenka",s="À Mille pointes, la Griffe de Grenka témoigne de la survie au fond de la Tanière des Volplumes. À la niche érodée, Dorn Traqueur-des-plaines la reçoit comme preuve de l’endurance d’un aventurier en herbe sur les hauteurs du canyon.",h="À Mille pointes, la Griffe de Grenka témoigne de la survie au fond de la Tanière des Volplumes.",kw={"dorn traqueur-des-plaines","grenka bloodscreech","griffe de grenka","harpie","tanière des volplumes","screeching canyon","test of endurance","mille pointes","la niche érodée"},ang={["faction:Horde"]="Débarrasser les profondeurs de la Tanière des Volplumes et tuer Grenka Bloodscreech atténue la menace des harpies, qui harcèlent sans cesse les voyageurs autour du Poste de Librevent.",["race:Tauren"]="L’ancien Dorn Traqueur-des-plaines considère comme son devoir sacré de préparer les jeunes champions de la Horde à affronter un monde plus vaste et plus rude, grâce à la sagesse et à la ténacité des rites taurens."},sec={{t="Un trophée d’endurance",b="Les harpies cachent de la nourriture dans la Tanière des Volplumes, à l’ouest du Poste de Librevent, et défendent férocement leur territoire. Dorn Traqueur-des-plaines envoie de jeunes champions dans les perchoirs les plus profonds pour détruire les réserves de nourriture de la nuée et mettre leur force à l’épreuve. Une telle intrusion attire la fureur de Grenka Bloodscreech. Rapporter sa serre malfaisante prouve qu’un guerrier a résisté à des vagues successives de harpies enragées et survécu à l’assaut féroce de leur matriarche."}},faq={{q="À quoi sert la Griffe de Grenka ?",a="À la niche érodée, à Mille pointes, Dorn Traqueur-des-plaines accepte la griffe comme preuve de victoire. La lui remettre achève le Test of Endurance et montre que vous pouvez survivre à un long combat.",al={"utilité de la griffe de grenka","pourquoi ai-je besoin de la griffe de grenka","quête de la griffe de grenka"}},{q="Qui est Grenka Bloodscreech ?",a="Grenka Bloodscreech est une puissante harpie de la Tanière des Volplumes, dans Screeching Canyon, le long des falaises méridionales de Mille pointes. Elle surgit lorsque des intrus menacent la nuée en détruisant ses réserves de nourriture.",al={"qui est grenka","histoire de grenka bloodscreech","qu’est-ce que grenka"}},{q="Où dois-je apporter la griffe une fois que je l’ai obtenue ?",a="Apportez la griffe à Dorn Traqueur-des-plaines, à la niche érodée, dans les hauteurs de Mille pointes. Il l’accepte comme preuve que vous avez réussi l’épreuve d’endurance physique.",al={"où rapporter la griffe de grenka","qui veut la griffe de grenka"}},{q="Pourquoi Dorn Traqueur-des-plaines exige-t-il ce trophée en particulier ?",a="Dorn Traqueur-des-plaines guide les jeunes voyageurs à travers de rudes épreuves pour préparer leur esprit, leur âme et leur corps à de plus grands périls. Tuer Grenka et s’emparer de sa griffe prouve qu’un guerrier peut endurer l’embuscade d’une nuée et l’assaut direct de sa redoutable cheffe.",al={"pourquoi dorn veut la griffe","utilité de la griffe"}}},fx={cd538a11={q="Qu'est-ce que la Griffe de Grenka ?",a="La Griffe de Grenka est un trophée physique pris sur Grenka Bloodscreech, une redoutable harpie vivant au fond de la Tanière des Volplumes, dans le canyon des Cris. Sectionnée sur la créature vicieuse après avoir provoqué et survécu à la colère de sa volée, la griffe sert de preuve indéniable qu'un aventurier en herbe possédait l'endurance et les prouesses martiales pour résister à une brutale épreuve de combat.",al={"griffe de grenka","qu'est-ce que la griffe de grenka","à propos de la griffe de grenka"}}},fp="13,207,21.408.0,31.187.0,27.199.0,42.163.0,55.244.0"}
P.entries["item:grimtotem-horn"] = {n="Grimtotem Horn",s="Les cornes Grimtotem sont prises aux taurens Grimtotem à l’ouest du Camp Mojache, en Féralas. Krueg Tranche-tête les réclame après avoir appris que la tribu se trouve dans les environs.",h="Les cornes Grimtotem sont prises aux taurens Grimtotem à l’ouest du Camp Mojache, en Féralas.",kw={"belgrom","camp mojache","féralas","grimtotem","corne grimtotem","cornes grimtotem","krueg skullsplitter","tauren"},ang={["faction:Horde"]="En tant que voyageur de la Horde, vous entendez dans l’avertissement de Krueg que les Grimtotem représentent un danger pour les terres et les villages de la Horde."},sec={{t="Prises en Féralas",b="À l’ouest du Camp Mojache, les taurens Grimtotem portent ces cornes. Krueg Tranche-tête vous demande de lui en rapporter une collection après avoir appris que le clan se trouve en Féralas. Il dit que Belgrom a mis une prime sur les Grimtotem et vous avertit qu’ils sont dangereux."}},faq={{q="D’où viennent les cornes Grimtotem ?",a="Les taurens Grimtotem portent ces cornes à l’ouest du Camp Mojache, en Féralas.",al={"origine des cornes","origine corne grimtotem"}},{q="Qui veut ces cornes ?",a="Krueg Tranche-tête, au Camp Mojache, vous demande de lui rapporter des cornes Grimtotem.",al={"qui veut les cornes","cornes krueg"}},{q="Pourquoi Krueg les veut-il ?",a="Krueg réclame les cornes après avoir appris que des taurens Grimtotem se trouvent dans les environs. Il dit que Belgrom s’intéresse à la tribu et a mis une prime sur ses membres.",al={"pourquoi récolter les cornes","utilité des cornes"}},{q="Qui sont les Grimtotem ?",a="Les Grimtotem sont un clan tauren présent à l’ouest du Camp Mojache, en Féralas.",al={"qui sont les grimtotem","taurens grimtotem"}}},fp="14,150,16.239.0,35.65.0,20.74.0,25.151.0,22.70.0"}
P.entries["item:grimtotem-satchel"] = {n="Sacoche du Totem-sinistre",s="Au plus profond d’Orgrimmar, la Sacoche du Totem-sinistre reste entre les mains de Maur Totem-sinistre. Les troggs ont tué le tauren dans le Gouffre de Ragefeu, mais il a protégé la sacoche en mourant. Son retour à Pitons-du-Tonnerre attire l’attention de Magatha Totem-sinistre.",h="Au plus profond d’Orgrimmar, la Sacoche du Totem-sinistre reste entre les mains de Maur Totem-sinistre.",kw={"cime des anciens","totem-sinistre","magatha totem-sinistre","maur totem-sinistre","gouffre de ragefeu","rahauro","sacoche","pitons-du-tonnerre","trogg"},ang={["faction:Horde"]="Un messager mort du clan Grimtotem gisait au plus profond des tunnels sous la capitale de Thrall. Le Gouffre de Ragefeu recèle des dangers au-delà de ses bêtes.",["race:Tauren"]="Un membre du clan Grimtotem s’est aventuré au plus profond d’Orgrimmar, et Magatha a appris ce qu’il y avait trouvé sur la Cime des Anciens. Les manœuvres du clan au sein des tribus taurens unies restent discrètes et inquiétantes."},sec={{t="Une dernière étreinte",b="Les troggs ont tué Maur Totem-sinistre au plus profond du Gouffre de Ragefeu, sous Orgrimmar. Quand on a retrouvé son corps, le tauren tenait toujours un simple sac en cuir. Il s’était battu pour le protéger tandis que les troggs l’encerclaient. Que pouvait-il contenir pour qu’il le défende au péril de sa vie ?"},{t="L’intérêt de l’Elder Crone",b="Rahauro, sur la Cime des Anciens à Pitons-du-Tonnerre, accepte la sacoche pour Magatha Totem-sinistre, matriarche du clan Grimtotem. Maur servait Magatha, qui a appris qu’il avait trouvé quelque chose d’étrange dans les cavernes sous Orgrimmar avant sa mort. Elle a prévu une récompense pour le retour du sac en bon état. Magatha s’intéresse de près à la découverte de Maur."}},faq={{q="Où trouver la Sacoche du Totem-sinistre ?",a="La Sacoche du Totem-sinistre a été trouvée sous le corps de Maur Totem-sinistre, au plus profond du Gouffre de Ragefeu, la caverne volcanique sous Orgrimmar. Ses bras la tenaient encore quand les troggs l’ont tué.",al={"emplacement de la sacoche","où se trouve la sacoche","comment trouver la sacoche"}},{q="À qui appartient la sacoche ?",a="La sacoche appartenait à Maur Totem-sinistre, un membre du clan Grimtotem qui s’était aventuré dans le Gouffre de Ragefeu. Il la tenait serrée contre lui quand les troggs ont attaqué.",al={"à qui appartient la sacoche","propriétaire de la sacoche de maur"}},{q="Qui veut récupérer la sacoche ?",a="Rahauro, sur la Cime des Anciens à Pitons-du-Tonnerre, accepte la sacoche pour Magatha Totem-sinistre. Magatha a prévu une récompense pour le retour des effets personnels de son frère de clan tombé au combat.",al={"qui reçoit la sacoche","à qui remettre la sacoche","qui veut la sacoche du totem-sinistre"}},{q="Pourquoi un Totem-sinistre portait-il cela sous Orgrimmar ?",a="Maur Totem-sinistre servait Magatha Totem-sinistre, qui s’intéressait au Gouffre de Ragefeu. Il s’y est rendu pour parler aux troggs et y a trouvé quelque chose d’étrange, mais il est mort avant de pouvoir le lui montrer.",al={"pourquoi maur était au gouffre de ragefeu","que faisait le totem-sinistre à orgrimmar"}},{q="Que contient la sacoche ?",a="Quand Rahauro reçoit la sacoche à Pitons-du-Tonnerre, son contenu reste scellé. Magatha espère qu’elle renferme des indices sur l’étrange découverte de Maur dans le gouffre.",al={"contenu de la sacoche","que contient le sac"}}},fp="17,225,12.266.0,26.343.1,37.178.0,31.135.0,31.165.0,50.190.0,27.153.0"}
P.entries["item:grizzled-bear-heart"] = {n="Coeur de vieil ours",s="Dans la Forêt des Pins-Argentés, les vieux ours fournissent des cœurs à la Société royale des apothicaires pour ses recherches sur The New Plague.",h="Dans la Forêt des Pins-Argentés, les vieux ours fournissent des cœurs à la Société royale des apothicaires...",kw={"a recipe for death","apothicaire renferrel","coeur de vieil ours","maître apothicaire faranell","the new plague","vieux vile mâchoire","société royale des apothicaires","forêt des pins-argentés","sang du grouillement"},ang={["class:Hunter"]="En tant que chasseur, traquer les énormes ours de la Forêt des Pins-Argentés, dont Vieux Vile mâchoire, met votre patience et votre savoir-faire en matière de dépouillement à l’épreuve, tandis que vous recherchez des échantillons biologiques.",["race:Undead"]="En tant que Réprouvé, récolter ces organes aide directement le Maître apothicaire Faranell à concevoir une arme contre le Fléau d’Arthas et les mortels vivants qui menacent Lordaeron."},sec={{t="Un réactif pour The New Plague",b="La Société royale des apothicaires travaille sans relâche à créer un fléau capable d’exterminer à la fois le Fléau et l’humanité vivante. Dans la Forêt des Pins-Argentés, l’Apothicaire Renferrel a découvert que les toxines du cœur d’un vieil ours donnent une concoction particulièrement mortelle lorsqu’elles sont mêlées à de l’ichor d’arachnide.\n\nDes coursiers et des loyalistes réprouvés traquent les féroces vieux ours, les vieux ours géants et la bête errante Vieux Vile mâchoire. Ils en prélèvent les cœurs et les apportent au Maître apothicaire Faranell, au plus profond de l’Apothicarium de Fossoyeuse."}},faq={{q="À quoi sert un Cœur de vieil ours ?",a="La Société royale des apothicaires utilise les Cœurs de vieil ours comme réactifs biologiques expérimentaux. L’Apothicaire Renferrel a découvert que les toxines de ces cœurs peuvent être distillées en un élixir mortel pour aider les Réprouvés à préparer The New Plague.",al={"utilité du cœur d’ours","quête du cœur d’ours","recette de réactifs mortels"}},{q="Qui veut ces cœurs d’ours ?",a="Dans la Forêt des Pins-Argentés, l’Apothicaire Renferrel charge les voyageurs de récolter ces cœurs ainsi que du Sang du Grouillement et de les apporter au Maître apothicaire Faranell, dans l’Apothicarium de Fossoyeuse.",al={"qui veut le cœur d’ours","faranell cœur d’ours","à qui donner le cœur d’ours"}},{q="D’où viennent les Cœurs de vieil ours ?",a="Les Cœurs de vieil ours proviennent des ours qui parcourent la Forêt des Pins-Argentés, notamment les féroces vieux ours, les vieux ours géants et la bête errante Vieux Vile mâchoire.",al={"où trouver des cœurs d’ours","quels ours donnent un cœur","emplacement du cœur d’ours"}},{q="Pourquoi la Société royale des apothicaires a-t-elle besoin de toxines animales naturelles ?",a="La Société royale des apothicaires recherche des agents biologiques capables de contaminer et de détruire les chairs vivantes et la physiologie des morts-vivants. Les propriétés chimiques uniques des tissus cardiaques des robustes ours de la Forêt des Pins-Argentés forment une base réactive idéale lorsqu’ils sont mélangés à du sang d’araignée virulent.",al={"pourquoi les apothicaires utilisent le venin d’ours","pourquoi des cœurs d’animaux pour la peste"}}},fx={["9ca08a87"]={q="Qu'est-ce qu'un Coeur de vieil ours ?",a="C'est l'organe frais récolté sur les féroces ours gris qui rôdent dans la Forêt des Pins-Argentés. Bien qu'il s'agisse d'un organe banal à première vue, le cœur contient une toxine biologique naturelle et résiliente qui en fait un réactif séduisant pour les expériences alchimiques.",al={"qu'est-ce qu'un coeur de vieil ours","info coeur d'ours","lore coeur de vieil ours"}}},fp="19,114,28.520.0,39.234.0,28.188.0,40.156.0,65.274.0"}
P.entries["item:grizzled-scalp"] = {n="Scalp vieilli",s="Au sud d’Auberdine, des ours des chardons vieillis rôdent dans les forêts de Sombrivage, et leurs peaux épaisses servent à Crackboum Tournelevier.",h="Au sud d’Auberdine, des ours des chardons vieillis rôdent dans les forêts de Sombrivage, et leurs peaux...",kw={"auberdine","buzzbox 525","sombrivage","scalp vieilli","ours des chardons vieilli","bière d’ours des chardons","crackboum tournelevier"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous voyez comment le savoir-faire gnome camoufle des alambics automatisés en réseaux de communication pour les réparations sur le terrain.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous protégez la faune de Sombrivage et voyez d’un mauvais œil le braconnage abusif ainsi que les alambics gnomes dissimulés dans la nature."},sec={{t="Une fermentation particulière",b="Au sud d’Auberdine, des ours des chardons vieillis rôdent le long de la route, et les chasseurs recherchent leurs peaux rêches. Quatre scalps déposés dans Buzzbox 525 en révèlent l’usage. Crackboum Tournelevier utilise des bigobox dissimulées aux quatre coins de Sombrivage comme des alambics. Les Elfes de la nuit désapprouvent le brassage clandestin dans leurs colonies, alors Crackboum compte sur les aventuriers pour rassembler des scalps d’ours et d’autres ingrédients insolites pour sa chère bière d’ours des chardons."}},faq={{q="Où trouver des scalps vieillis ?",a="Des ours des chardons vieillis et leur matriarche, Den Mother, rôdent dans les forêts au sud d’Auberdine, le long de la route principale de Sombrivage.",al={"emplacement des scalps vieillis","qui donne des scalps vieillis","scalp d’ours des chardons"}},{q="À quoi servent les scalps vieillis ?",a="Déposez les scalps dans Buzzbox 525, un terminal mécanique caché dans les buissons, au bord de la route, loin au sud d’Auberdine.",al={"usage des scalps vieillis","que faire des scalps vieillis"}},{q="Pourquoi Buzzbox 525 a-t-elle besoin de scalps d’ours ?",a="Crackboum Tournelevier utilise son réseau de bigobox dissimulées pour distiller de l’alcool à l’abri des regards des Elfes de la nuit. Les scalps servent à préparer sa bière d’ours des chardons.",al={"pourquoi crackboum veut des scalps","utilité de buzzbox 525"}},{q="Pourquoi Crackboum cache-t-il son brassage dans les contrées sauvages de Sombrivage ?",a="Crackboum dissimule ses alambics dans les broussailles des contrées sauvages, car les Elfes de la nuit d’Auberdine s’opposent au brassage bruyant et non autorisé dans leurs bosquets sacrés. Ces mécanismes cachés tiennent son trafic d’alcool à l’abri des regards.",al={"pourquoi cacher buzzbox","alcool de crackboum à sombrivage"}}},fx={["903811df"]={q="Qu'est-ce qu'un Scalp vieilli ?",a="Un Scalp vieilli est la couronne épaisse et poilue récoltée sur les ours robustes errant dans les terres sauvages de Sombrivage. Ces bêtes aguerries endurent le climat nordique rigoureux, développant des peaux résilientes et hérissées que les trappeurs et les inventeurs curieux prisent pour leur densité unique.",al={"qu'est-ce qu'un scalp vieilli","info scalp vieilli","parlez-moi des scalps vieillis"}},e940f924={q="D'où provient un Scalp vieilli ?",a="Ces scalps proviennent des ours chardons matures originaires de Sombrivage, principalement les ours chardons vieillis et la féroce Mère des tanières. Plutôt que des produits artisanaux, ce sont des trophées bruts prélevés directement sur les bêtes sauvages errant au sud d'Auberdine.",al={"d'où viennent les scalps vieillis","source scalp vieilli","qui donne des scalps vieillis"}}},fp="14,129,23.410.1,33.127.0,34.117.0,38.137.1,60.214.1"}
P.entries["item:groddoc-liver"] = {n="Groddoc Liver",s="Le Groddoc Liver provient des singes de Féralas. Rhapsody Shindigger en a besoin pour préparer une boisson qui, il l’espère, lui déliera la langue au sujet d’un vol terrifiant au-dessus d’un marais.",h="Le Groddoc Liver provient des singes de Féralas.",kw={"féralas","groddoc ape","groddoc liver","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard"},sec={{t="Un ingrédient amer",b="Rhapsody Shindigger demande du Groddoc Liver dans les Hinterlands, ainsi que des Roc Gizzards et des Ironfur Livers. Il compte distiller ces trois ingrédients pour préparer un Kalimdor Kocktail. Selon lui, cette boisson pourrait l’aider à parler des horreurs d’un vol au-dessus d’un marais."}},faq={{q="D’où vient le Groddoc Liver ?",a="Le Groddoc Liver provient des Groddoc Apes de Féralas.",al={"où trouver groddoc liver","origine du groddoc liver"}},{q="Qui veut du Groddoc Liver ?",a="Rhapsody Shindigger, dans les Hinterlands, demande trois Groddoc Liver pour préparer son Kalimdor Kocktail.",al={"qui a besoin de ce foie","foie pour rhapsody"}},{q="À quoi sert le Groddoc Liver ?",a="Rhapsody Shindigger utilise le Groddoc Liver avec des Roc Gizzards et des Ironfur Livers pour préparer un Kalimdor Kocktail.",al={"utilité du groddoc liver","pourquoi ce foie"}},{q="Pourquoi Rhapsody prépare-t-il cette boisson ?",a="Rhapsody dit qu’il lui faut une boisson plus forte avant de pouvoir vous raconter un vol terrifiant au-dessus d’un marais.",al={"pourquoi ce cocktail","rhapsody veut une boisson"}}},fp="13,159,19.254.0,34.49.0,24.99.0,31.100.0,33.103.0"}
P.entries["item:gryshka-s-letter"] = {n="Lettre de Gryshka",s="Gryshka l'aubergiste envoie un mot de remerciement à Zargh après avoir reçu de la viande fraîche des Tarides. Sa lettre présente aussi aux jeunes coursiers de la Horde les routes des Wind Rider.",h="Gryshka l'aubergiste envoie un mot de remerciement à Zargh après avoir reçu de la viande fraîche des Tarides.",kw={"tarides","la croisée","doras","gryshka","lettre de gryshka","viande","orgrimmar","wind rider","zargh"},ang={["faction:Horde"]="La livraison de la Lettre de Gryshka présente aux jeunes aventuriers de la Horde le réseau aérien des wyvernes qui relie Durotar et les Tarides."},sec={{t="Une aubergiste reconnaissante",b="Gryshka l'aubergiste remercie Zargh pour les steaks qu'il lui envoie des Tarides à Orgrimmar. Elle se souvient du jour où il s'est coupé un doigt en préparant de la viande. Même ensanglanté par son métier, lui dit-elle, il reste beau."},{t="Coursier sur les routes aériennes",b="Pour rapporter la Lettre de Gryshka à La Croisée, vous vous présentez à Doras, le maître des Wind Rider au sommet du plateau d'Orgrimmar. Montrez-lui que vous avez déjà parlé à Devrak à La Croisée. Doras présente ensuite aux jeunes coursiers les routes aériennes des wyvernes qui relient les colonies de Durotar et des Tarides."}},faq={{q="Qui a écrit la Lettre de Gryshka ?",a="Gryshka l'aubergiste, qui tient une taverne dans la Vallée de la Force à Orgrimmar, a écrit cette lettre après avoir reçu de la viande fraîche.",al={"qui a écrit cette lettre","auteur de la lettre de gryshka","expéditeur"}},{q="À qui la lettre est-elle destinée ?",a="La lettre est adressée à Zargh, un boucher de La Croisée, dans les Tarides, qui a fourni de la viande à Gryshka.",al={"destinataire","qui reçoit la lettre de gryshka","où va la lettre"}},{q="Que contient la lettre ?",a="Gryshka remercie Zargh pour ses morceaux de viande et se souvient du jour où il s'est coupé un doigt en préparant de la viande. Elle le taquine en lui disant qu'il reste beau même ensanglanté.",al={"texte de la lettre","que dit gryshka","contenu de la lettre"}},{q="Pourquoi Doras doit-il voir la lettre ?",a="Doras est le maître des Wind Rider d'Orgrimmar. Gryshka vous demande de lui montrer que vous avez parlé à Devrak à La Croisée, afin que Doras puisse vous présenter les routes aériennes des wyvernes.",al={"pourquoi montrer la lettre à doras","doras the wind rider master","maître de vol d'orgrimmar"}}},fx={["950e527c"]={q="Qu'est-ce que la Lettre de Gryshka ?",a="Il s'agit d'un message de gratitude manuscrit rédigé par Gryshka l'aubergiste d'Orgrimmar. Elle l'a rédigé en réponse à une livraison spéciale de viande envoyée à son auberge, avec l'intention d'en faire à la fois une note de remerciement et un geste d'affection coquet à rapporter dans les Tarides.",al={"qu'est-ce que la lettre de gryshka","objet lettre de gryshka","à propos de la lettre de gryshka"}},["0c09fbc7"]={q="Pourquoi quelqu'un voudrait-il la Lettre de Gryshka ?",a="Le boucher Zargh, à la Croisée, attend avec impatience de savoir comment sa viande de premier choix a été reçue. Gryshka souhaite qu'elle soit livrée pour témoigner de ses remerciements sincères et lui rendre son affection, tandis que Doras the wind rider master a simplement besoin de confirmer votre destination pour organiser le vol de retour à travers les Tarides.",al={"pourquoi livrer la lettre de gryshka","qui veut la lettre de gryshka","pourquoi zargh veut la lettre de gryshka"}}},fp="16,165,20.205.0,30.294.0,27.119.0,31.108.0,34.137.0,38.176.0"}
P.entries["item:gunther-s-spellbook"] = {n="Grimoire de Gunther",s="Dans les Clairières de Tirisfal, l’enchantement de Bethor marque le Grimoire de Gunther. Le tome peut révéler à son propriétaire que d’autres mages ont échappé à l’emprise du Roi-Liche.",h="Dans les Clairières de Tirisfal, l’enchantement de Bethor marque le Grimoire de Gunther.",kw={"arcanus","bethor","dalaran","gunther","glacéclat","kirin tor","grimoire","tirisfal"},ang={["class:Mage"]="En tant que mage, vous partagez les racines arcaniques de Dalaran avec les chefs magiques des Réprouvés et les praticiens qui parcourent seuls les étendues sauvages.",["race:Undead"]="En tant que mort-vivant, vous savez que les Réprouvés recherchent de puissants morts-vivants qui se sont libérés de l’emprise du Roi-Liche."},sec={{t="Un gage d’une ancienne amitié",b="Gunther Arcanus étudiait autrefois la magie à Dalaran avec Bethor Glacéclat et Thule Ravenclaw. Tous trois appartenaient au Kirin Tor. Lorsque le Fléau de la non-mort balaya Lordaeron, Gunther succomba puis se releva parmi les morts-vivants. Avec le temps, il brisa l’emprise du Fléau sur son esprit.\n\nGunther croyait être seul et pensait que les agents du Roi-Liche le traquaient. Il devint donc profondément hostile aux étrangers. Après la récupération du tome, Bethor imprégna ses pages d’un enchantement arcanique. La signature de Bethor marque cette magie, afin que Gunther reconnaisse la présence de son ancien compagnon et découvre qu’un autre mage a préservé sa volonté."}},faq={{q="À qui appartient ce grimoire ?",a="Gunther Arcanus possède le grimoire et vit sur une île isolée du lac Etincelant, dans les Clairières de Tirisfal.",al={"à qui appartient le livre","propriétaire du livre de gunther","propriétaire du grimoire"}},{q="Pourquoi Bethor a-t-il enchanté le grimoire ?",a="Bethor a placé un sort personnel sur le tome pour prouver qu’il a survécu à Lordaeron et échappé à l’emprise du Roi-Liche. Il espère que Gunther le croira et s’alliera aux Réprouvés.",al={"pourquoi enchanter le livre","sort de bethor sur le livre","magie du livre"}},{q="Pourquoi Gunther se méfie-t-il quand on lui rend le livre ?",a="Gunther croit que quiconque s’approche de sa retraite pourrait être un agent du Fléau envoyé pour le réduire de nouveau en esclavage. Au début, il pense que vous n’êtes que le voleur qui a pris son tome.",al={"pourquoi gunther est-il furieux","gunther en colère","gunther hostile"}},{q="Comment Gunther et Bethor se connaissaient-ils ?",a="Avant le Fléau de la non-mort, Gunther, Bethor Glacéclat et Thule Ravenclaw étudiaient la magie ensemble à Dalaran. Ils étaient amis et apprentis du Kirin Tor.",al={"passé de bethor et gunther","lien avec le kirin tor","amis de dalaran"}}},fp="19,150,22.608.1,24.107.1,37.179.0,52.162.0,43.144.1"}
P.entries["item:gyromechanic-gear"] = {n="Engrenage gyromécanique",s="À Kharanos, des inventeurs cherchent des engrenages gyromécaniques pour une expérience audacieuse. Ils espèrent inverser les mutations des gnomes lépreux.",h="À Kharanos, des inventeurs cherchent des engrenages gyromécaniques pour une expérience audacieuse.",kw={"gnomeregan","engrenage gyromécanique","kharanos","gnome lépreux","operation recombobulation","esbrouf fulgurouage","recombobulateur","rouage de rééquilibrage"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous connaissez la conception complexe et les tolérances serrées des pièces gyromécaniques gnomes. Elles régulent les machines instables du prototype.",["race:Gnome"]="En tant que gnome, chaque engrenage que vous récupérez rapproche les bricoleurs d’une chance de sauver leurs proches irradiés dans les neiges, à l’extérieur de Gnomeregan."},sec={{t="Des composants pour le Recombobulateur",b="Les radiations ont balayé Gnomeregan pendant que les gnomes tentaient de chasser les troggs. Beaucoup de survivants sont devenus des gnomes lépreux fous et irradiés. Ozzie Virevolt et Esbrouf Fulgurouage n’abandonneront pas leurs proches transformés. Ils ont donc conçu le Recombobulateur, une machine censée annuler les effets des radiations.\n\nSon prototype a besoin de mécanismes précis capables de supporter la pression instable à l’intérieur, notamment des engrenages gyromécaniques et des Rouages de restabilisation. La chute de Gnomeregan a mis fin à la fabrication locale. Les inventeurs doivent maintenant récupérer ces pièces délicates sur les gnomes lépreux hostiles qui errent dans Dun Morogh."}},faq={{q="À quoi sert un engrenage gyromécanique ?",a="Esbrouf Fulgurouage, à Kharanos, a besoin d’engrenages gyromécaniques comme pièces essentielles du Recombobulateur. Le prototype les utilisera avec des Rouages de restabilisation pour tenter de soigner les gnomes lépreux irradiés.",al={"utilité de l’engrenage gyromécanique","fonction de l’engrenage gyromécanique","quête de l’engrenage gyromécanique"}},{q="D’où viennent ces engrenages ?",a="Ces engrenages sont récupérés sur les gnomes lépreux aux abords de Gnomeregan et sur Gibblewilt, dans Dun Morogh.",al={"où trouver l’engrenage gyromécanique","butin de l’engrenage gyromécanique","qui lâche l’engrenage gyromécanique"}},{q="Le Recombobulateur peut-il vraiment soigner les gnomes lépreux ?",a="Esbrouf Fulgurouage fait confiance aux plans d’Ozzie et pense que des changements aux pistons de combustion et au gel électrogommeux peuvent rétablir leurs proches. La machine n’a pas été testée à grande échelle contre l’empoisonnement par les radiations.",al={"le recombobulateur fonctionne-t-il","peut-on soigner les gnomes lépreux","succès du recombobulateur"}},{q="Pourquoi les gnomes ne peuvent-ils pas simplement forger de nouveaux engrenages ?",a="La chute de Gnomeregan a brisé l’industrie gnome et rendu inaccessibles ses meilleurs outils, ateliers et fonderies automatisées. Récupérer du matériel de précision intact aux abords de la ville est souvent plus rapide que fabriquer des pièces à la main.",al={"pourquoi récupérer des engrenages","pourquoi ne pas fabriquer des engrenages gyromécaniques"}}},fx={["93a017f3"]={q="Qu'est-ce qu'un Engrenage gyromécanique ?",a="Un Engrenage gyromécanique est un composant ingénieusement conçu pour des machines gnomiques complexes. Utilisées à l'origine dans les vastes ouvrages mécaniques de Gnomeregan, ces pièces de précision sont désormais éparpillées parmi les ruines et récupérées par les misérables créatures rôdant à l'extérieur de la cité technologique déchue.",al={"qu'est-ce qu'un engrenage gyromécanique","info engrenage gyromécanique","à propos des engrenages gyromécaniques"}}},fp="17,121,30.581.0,37.195.0,31.94.0,50.211.0,40.221.0"}
P.entries["item:hallowed-letter"] = {n="Lettre bénie",s="Dans la Vallée de Comté-du-Nord, la Prêtresse Anetta appelle les jeunes prêtres à l’Abbaye de Comté-du-Nord. Sa lettre ouvre leur étude de la Lumière sacrée.",h="Dans la Vallée de Comté-du-Nord, la Prêtresse Anetta appelle les jeunes prêtres à l’Abbaye de Comté-du-Nord.",kw={"anetta","forêt d’elwynn","lettre bénie","lumière sacrée","abbaye de comté-du-nord","prêtre","prêtresse anetta"},ang={["class:Priest"]="En tant que prêtre, ce message vous reconnaît comme un instrument de la Lumière sacrée et vous lie aux instructeurs de l’Abbaye de Comté-du-Nord.",["race:Human"]="En tant qu’humain, vous perpétuez la tradition de devoir sacré de la Vallée de Comté-du-Nord, observée là-bas depuis avant la Première guerre."},sec={{t="Un appel à la foi",b="La marque personnelle de la Prêtresse Anetta figure sur la Lettre bénie. Elle parvient aux prêtres novices après leurs premières épreuves contre les camps de kobolds de la Vallée de Comté-du-Nord. Elle voit une étincelle de la Lumière sacrée en chaque novice et l’exhorte à entrer dans l’abbaye pour la servir. De sombres forces rôdent encore à travers Azeroth après la Troisième guerre. Le clergé rassemble ceux qui peuvent soigner, protéger et guider un empire qui lutte pour maintenir l’ordre."}},faq={{q="Qu’est-ce que la Lettre bénie ?",a="La Lettre bénie est le message de la Prêtresse Anetta aux prêtres qui viennent d’arriver à l’Abbaye de Comté-du-Nord. Elle les convoque à leur premier cours.",al={"qu’est-ce que la lettre bénie","objet lettre bénie","lettre de prêtre au comté-du-nord"}},{q="Qui a écrit la lettre ?",a="L’insigne de la Prêtresse Anetta marque la lettre. Elle forme et guide les jeunes prêtres humains qui arrivent au Comté-du-Nord.",al={"qui a envoyé la lettre","qui en est l’auteur","expéditeur de la lettre"}},{q="Pourquoi le clergé appelle-t-il de nouveaux novices en ce moment ?",a="Azeroth reste en proie au tumulte, et des vestiges de la Légion ardente la hantent encore. Kalimdor affronte de nouvelles épreuves, tandis que Hurlevent a besoin de guérisseurs compatissants et de dirigeants pour reconstruire la ville et protéger ses habitants.",al={"pourquoi les prêtres ont-ils besoin d’aide","état du monde","lore des prêtres après la troisième guerre"}},{q="Que dois-je faire après avoir lu la lettre ?",a="Portez la lettre à l’Abbaye de Comté-du-Nord et adressez-vous à la Prêtresse Anetta. Elle acceptera votre engagement envers la Lumière et vous formera à de nouvelles disciplines sacerdotales au fil de votre voyage.",al={"où apporter la lettre","rendre la quête de la lettre bénie","à qui parler"}}},fx={["0a342f04"]={q="Pourquoi la Prêtresse Anetta veut-elle que vous ayez la Lettre bénie ?",a="La Prêtresse Anetta envoie la lettre pour convoquer les initiés prometteurs de la Lumière sacrée au sein de l'Abbaye de Comté-du-Nord. Reconnaissant que vous avez montré des promesses dans la défense de la vallée, elle souhaite se présenter, guider votre dévotion spirituelle et offrir une instruction plus approfondie dans les arts sacrés de la prêtrise.",al={"pourquoi lettre bénie","pourquoi anetta a envoyé la lettre","but de la lettre bénie"}}},fp="15,128,15.424.0,28.147.0,21.113.0,58.196.0,42.179.0"}
P.entries["item:hallowed-rune"] = {n="Rune bénie",s="Dans la Vallée des Frigères, Branstock Khalder envoie la Rune bénie aux prêtres novices pour débuter leur formation à Courbenclume.",h="Dans la Vallée des Frigères, Branstock Khalder envoie la Rune bénie aux prêtres novices pour débuter leur...",kw={"courbenclume","branstock khalder","vallée des frigères","dun morogh","rune bénie","prêtre","troggs"},ang={["class:Priest"]="En tant que prêtre, vous commencez votre formation officielle sous la Lumière sacrée dans la Vallée des Frigères avec la Rune bénie.",["race:Dwarf"]="En tant que nain, vous alliez le respect de la Lumière au devoir envers Forgefer en défendant votre patrie montagneuse contre les troggs."},sec={{t="Un appel à la Lumière",b="La Rune bénie porte les enseignements de la Lumière sacrée. Un jeune prêtre prouve sa détermination en aidant les montagnards et les défenseurs de la vallée. Branstock l’envoie ensuite à Courbenclume, où il lui apprend à soigner les blessures et à manier la puissance sacrée contre les troggs qui menacent Dun Morogh."}},faq={{q="Qu’est-ce que la Rune bénie ?",a="La Rune bénie est une pierre sacrée gravée de conseils destinés aux prêtres novices. Branstock Khalder la leur envoie pour les appeler à commencer leur instruction spirituelle et magique à Courbenclume.",al={"qu’est-ce que cet objet","objet rune bénie","but de la rune"}},{q="Qui vous envoie la Rune bénie ?",a="Branstock Khalder, le maître des prêtres nain de Courbenclume, envoie la Rune bénie aux prêtres novices de la Vallée des Frigères.",al={"qui a envoyé la rune","qui m’a donné cette rune","rune de branstock"}},{q="Que faire après avoir reçu la Rune bénie ?",a="Lisez la rune, puis rendez-vous dans la grande salle de Courbenclume et présentez-vous à Branstock Khalder. Il vous propose de vous enseigner de nouvelles prières et de nouveaux sorts.",al={"où apporter la rune","que faire de la rune bénie"}},{q="Pourquoi Branstock veut-il former si vite les prêtres novices ?",a="Branstock veut former les prêtres novices, car les troggs continuent d’envahir la Vallée des Frigères. Les montagnards ont besoin de soins et de puissance sacrée pour défendre Dun Morogh.",al={"pourquoi faut-il des prêtres","problème des troggs et des prêtres"}}},fx={fac25589={q="Pourquoi la Rune bénie m'a-t-elle été donnée ?",a="La rune agit comme une convocation formelle et un message adressé aux prêtres novices travaillant dans la Vallée des Frigères. Branstock Khalder l'envoie pour appeler les aspirants acolytes de la Lumière sacrée à Courbenclume afin qu'il puisse les instruire dans leur foi et leur enseigner des sorts sacrés vitaux pour la défense de la vallée.",al={"pourquoi ai-je la rune bénie","but de la rune bénie","pourquoi rune bénie"}}},fp="13,114,22.281.0,26.185.0,35.121.0,51.138.0,58.152.0"}
P.entries["item:hallowed-scroll"] = {n="Parchemin béni",s="Au Glas, le Parchemin béni appelle les prêtres réprouvés nouvellement éveillés à la chapelle en ruine. Scellé par le Sombre clerc Duesten, il inaugure leur apprentissage de la foi, de la volonté et de l’ombre.",h="Au Glas, le Parchemin béni appelle les prêtres réprouvés nouvellement éveillés à la chapelle en ruine.",kw={"le glas","duesten","réprouvés","parchemin béni","lumière","prêtre","tirisfal"},ang={["class:Priest"]="En tant que prêtre réprouvé, ce parchemin marque votre rupture avec la foi humaine traditionnelle. Il vous oriente vers vos propres convictions et les arts obscurs du Cult of the Forgotten Shadow.",["race:Undead"]="En tant que voyageur mort-vivant, vous recevez cet appel tandis que le Glas rassemble en urgence les êtres nouvellement éveillés et les forme pour les intégrer aux forces de Sylvanas."},sec={{t="Un appel aux sans-foi",b="Les prêtres réprouvés récemment relevés sentent leur lien avec le monde changer violemment. Le Glas est reconquis dans le chaos, et le Parchemin béni les envoie chercher conseil dans la chapelle en ruine de la colonie. Le sceau du Sombre clerc Duesten marque le parchemin. Il ordonne aux nouveaux prêtres de se présenter pour recevoir un enseignement officiel sur les croyances pratiques du sacerdoce réprouvé."},{t="La voie de l’autonomie",b="Le Sombre clerc Duesten dit aux prêtres qui répondent à l’appel d’abandonner leurs anciens enseignements. La Sainte Lumière, les esprits ancestraux et les pactes démoniaques ne peuvent leur servir de béquilles. Le parchemin inaugure une discipline fondée sur la volonté de chaque prêtre. Ses enseignements les appellent à survivre et à régner par la conviction, faisant de la foi un moyen de se maîtriser et de dominer."}},faq={{q="Qu’est-ce que le Parchemin béni ?",a="Le Parchemin béni appelle les prêtres réprouvés récemment relevés au Glas. Il leur ordonne de se présenter auprès du Sombre clerc Duesten, dans la chapelle locale, pour recevoir un enseignement officiel.",al={"que signifie ce parchemin","but du parchemin béni","objet parchemin béni"}},{q="Qui a envoyé le Parchemin béni ?",a="Le sceau personnel du Sombre clerc Duesten marque le Parchemin béni. Il forme les prêtres dans l’église abandonnée du Glas.",al={"qui a écrit le parchemin béni","qui a envoyé le parchemin","parchemin de duesten"}},{q="Qu’enseigne le Sombre clerc Duesten quand vous lui apportez le parchemin ?",a="Le Sombre clerc Duesten enseigne aux prêtres morts-vivants à ne plus dépendre de la Sainte Lumière, des esprits ancestraux ni des pouvoirs d’outre-monde. Il affirme que les Réprouvés ont survécu grâce à leur volonté propre et exhorte les jeunes prêtres à croire en eux-mêmes pour guider et dominer les autres.",al={"que dit duesten","croyances des prêtres réprouvés","histoire des prêtres du glas"}}},fx={["758c1904"]={q="Pourquoi le Sombre clerc Duesten veut-il que vous ayez le Parchemin béni ?",a="Le Sombre clerc Duesten utilise le parchemin scellé pour convoquer les prêtres Réprouvés récemment relevés à l'église du Glas. Plutôt que de vous laisser vous accrocher à la Lumière oubliée ou aux esprits ancestraux, il a l'intention de vous instruire dans la sombre philosophie de la prêtrise Réprouvée, en comptant strictement sur votre propre volonté inébranlable pour exercer le pouvoir et survivre dans un monde hostile.",al={"pourquoi parchemin béni","pourquoi duesten parchemin béni","but du parchemin béni"}}},fp="15,183,26.374.0,25.351.0,28.161.0,29.118.0,66.279.0"}
P.entries["item:hallowed-sigil"] = {n="Sceau béni",s="À Sombrevallon, le Sceau béni appelle les jeunes initiés elfes de la nuit à Aldrassil. Shanda l’envoie pour les appeler au service d’Elune.",h="À Sombrevallon, le Sceau béni appelle les jeunes initiés elfes de la nuit à Aldrassil.",kw={"aldrassil","sceau béni","initié","kaldorei","prêtre","sombrevallon","shanda","teldrassil"},ang={["class:Priest"]="En tant que prêtre elfe de la nuit, vous recevez le Sceau béni comme première convocation à une formation officielle auprès de The Sisterhood of Elune.",["race:NightElf"]="En tant que dévot kaldorei, le sceau marque le début de votre service, alors que des voyageurs de l’Alliance commencent à arriver sur les branches de Teldrassil."},sec={{t="Un appel à la prêtrise",b="Les jeunes prêtres elfes de la nuit de Sombrevallon reçoivent le Sceau béni d’un messager des bois. Des marques sacrées couvrent le jeton, qui porte une convocation personnelle de Shanda, la formatrice des prêtres à Aldrassil. Lisez le message, puis montez jusqu’au grand creux d’Aldrassil. Là, la convocation présente l’acolyte à The Sisterhood of Elune et marque le début de son service auprès des Kaldorei, tandis que de nouveaux voyageurs arrivent sur Teldrassil."}},faq={{q="Qu’est-ce que le Sceau béni ?",a="Les jeunes prêtres elfes de la nuit de Sombrevallon reçoivent le Sceau béni, un jeton sacré portant une convocation. Il indique à l’initié qu’il doit retrouver Shanda, son mentor.",al={"qu’est-ce que le sceau béni","sceau de prêtre à sombrevallon"}},{q="Qui envoie le Sceau béni ?",a="Un messager des bois transporte le Sceau béni pour Shanda, la formatrice des prêtres à l’intérieur d’Aldrassil.",al={"qui a envoyé ce sceau","jeton de prêtre de shanda"}},{q="Où dois-je apporter le sceau ?",a="Portez le sceau à Shanda, à l’intérieur d’Aldrassil, au cœur de Sombrevallon, sur Teldrassil. Lisez la convocation, puis présentez-lui le jeton pour rencontrer pour la première fois les mentors de votre prêtrise.",al={"où apporter le sceau béni","remettre le sceau béni"}}},fx={["71c8963a"]={q="Pourquoi Shanda veut-elle que le Sceau béni lui soit rapporté ?",a="Le sceau sert de convocation formelle et de jeton d'introduction pour les prêtres elfes de la nuit novices. La prêtresse Shanda l'a envoyé par l'intermédiaire d'un messager pour vous appeler à Aldrassil, en veillant à ce que vous recherchiez ses conseils alors que le vaste monde s'éveille et que des voyageurs arrivent sur les branches de Teldrassil. Le rapporter confirme que vous avez bien reçu son message et que vous êtes prêt à commencer votre formation sacrée.",al={"pourquoi apporter le sceau béni à shanda","pourquoi shanda veut-elle le sceau","utilité du sceau béni"}}},fp="14,133,27.408.0,27.149.0,29.96.0,30.188.0"}
P.entries["item:hallowed-tablet"] = {n="Tablette bénie",s="Dans la Vallée des épreuves, la Tablette bénie appelle les jeunes prêtres Sombrelance à Ken'jai. Ses mots inaugurent leur apprentissage de la communion avec les esprits.",h="Dans la Vallée des épreuves, la Tablette bénie appelle les jeunes prêtres Sombrelance à Ken'jai.",kw={"sombrelance","durotar","gornek","tablette bénie","ken'jai","prêtre troll","vallée des épreuves"},ang={["class:Priest"]="La tablette marque le début de votre formation officielle de prêtre en Durotar et établit votre lien avec Ken'jai, votre mentor.",["race:Troll"]="Pour les Sombrelance, la prêtrise implique une communion étroite avec les esprits et les loa. La tablette vous invite à suivre ces traditions spirituelles ancestrales."},sec={{t="Un appel des esprits",b="Gornek remet la Tablette bénie à un prêtre troll prometteur qui fait ses premiers pas dans la Vallée des épreuves. Une invitation personnelle de Ken'jai, le maître des prêtres devant l'Antre, y est inscrite. Ken'jai interprète les signes et entend les murmures des esprits.\n\nAinsi, lorsque de jeunes Sombrelance dotés d'un potentiel spirituel arrivent en Durotar, les esprits lui font savoir qu'ils sont là. La tablette demande à l'initié de lire son message et de chercher les conseils de Ken'jai pour canaliser l'autorité spirituelle."}},faq={{q="Qu'est-ce que la Tablette bénie ?",a="Dans la Vallée des épreuves, Gornek remet aux prêtres trolls novices une tablette de pierre gravée. Son message les dirige vers Ken'jai, leur maître des prêtres.",al={"quel est cet objet","histoire de la tablette bénie","à quoi sert la tablette"}},{q="Qui a envoyé la tablette ?",a="Ken'jai a envoyé la tablette par l'intermédiaire de Gornek. Les esprits ont prédit l'arrivée d'un nouvel acolyte, alors Ken'jai, le maître des prêtres devant l'Antre, a fait transmettre un message.",al={"qui l'a écrite","qui me l'a donnée","auteur de la tablette"}},{q="Pourquoi les prêtres trolls doivent-ils voir Ken'jai ?",a="Les prêtres Sombrelance communient avec les esprits et les commandent. Ken'jai guide les initiés à mesure que leur lien spirituel se renforce, afin que les esprits soient disposés à leur enseigner des pouvoirs plus puissants.",al={"rôle de ken'jai","pourquoi voir ken'jai"}}},fp="15,147,26.486.0,28.144.0,20.144.0,41.186.0"}
P.entries["item:hammertoe-s-amulet"] = {n="Amulette de Hammertoe",s="L’Amulette de Hammertoe est un souvenir de Nain lié à ses recherches sur le passé d’Uldaman. Dans les Terres Ingrates, elle transmet son œuvre à ceux qui l’ont connu.",h="L’Amulette de Hammertoe est un souvenir de Nain lié à ses recherches sur le passé d’Uldaman.",kw={"amulette","terres ingrates","nains","hammertoe","historien karnik","prospecteur ryedol","parchemins","clan shadowforge","uldaman"},ang={["race:Dwarf"]="En tant que Nain, les recherches de Hammertoe sur les origines de son peuple touchent à votre propre héritage. Son amulette transmet ses travaux aux érudits qui l’ont connu."},sec={{t="La mission d’un Nain",b="Blessé dans les Terres Ingrates, Hammertoe vous demande de porter son amulette au Prospecteur Ryedol. Hammertoe cherchait les origines de son peuple et tentait d’empêcher le clan Shadowforge de trouver les parchemins. Ryedol connaît ses recherches, et Hammertoe lui fait confiance pour décider de la suite."},{t="À Forgefer",b="Après avoir appris ce qui est arrivé à Hammertoe, Ryedol vous envoie auprès de l’Historien Karnik, à Forgefer. Karnik et Hammertoe avaient travaillé ensemble à retrouver des artefacts perdus dans Uldaman. L’amulette transmet leur œuvre à Karnik, qui comprend qu’elle représente bien plus que le deuil de son compagnon."}},faq={{q="Qui était Hammertoe ?",a="Hammertoe était un Nain qui cherchait les origines de son peuple dans Uldaman. Il s’efforçait aussi d’empêcher le clan Shadowforge de trouver les parchemins.",al={"hammertoe nain","qui est hammertoe","histoire de hammertoe"}},{q="Pourquoi Hammertoe me confie-t-il son amulette ?",a="Hammertoe vous demande de porter l’amulette au Prospecteur Ryedol, dans les Terres Ingrates. Ryedol connaît les recherches de Hammertoe et peut décider de la suite.",al={"pourquoi l’amulette","pourquoi l’amulette de hammertoe","que faire de l’amulette"}},{q="Qui est le Prospecteur Ryedol ?",a="Le Prospecteur Ryedol est le Nain à qui Hammertoe confie son amulette et ses travaux à Uldaman.",al={"qui est ryedol","prospecteur"}},{q="Pourquoi l’amulette est-elle importante ?",a="L’amulette appartenait à Hammertoe et représente les recherches qu’il menait dans Uldaman sur les origines de son peuple. Ryedol et l’Historien Karnik connaissent ses travaux.",al={"importance de l’amulette","qu’a-t-elle de spécial","à quoi sert l’amulette"}},{q="Qui est l’Historien Karnik ?",a="L’Historien Karnik se trouve à Forgefer et travaillait avec Hammertoe à retrouver des artefacts perdus dans Uldaman. Ryedol vous envoie auprès de lui avec l’amulette.",al={"qui est karnik","historien"}},{q="Qu’essayait d’empêcher Hammertoe ?",a="Hammertoe cherchait à empêcher le clan Shadowforge de trouver les parchemins dans Uldaman.",al={"objectif de shadowforge","pourquoi arrêter shadowforge","parchemins d’uldaman"}}},fp="18,150,18.291.0,12.285.0,18.143.0,38.147.0,25.88.0,28.149.0,24.136.0,34.82.0"}
P.entries["item:hand-of-dagun"] = {n="Main de Dagun",s="La Main de Dagun est une relique recherchée par Gerrig Poigne-d'os à Forgefer. C'est l'un des trois objets qu'il demande en échange du Sommaire de Yagyin.",h="La Main de Dagun est une relique recherchée par Gerrig Poigne-d'os à Forgefer.",kw={"dagun","gerrig poigne-d'os","main de dagun","legacy heart","poison","relique","etoile de xil'yeh","sommaire de yagyin"},ang={["faction:Alliance"]="Pour l'Alliance, la requête de Gerrig Poigne-d'os est l'occasion de contribuer au début d'un nouveau chapitre de son ordre."},sec={{t="Une relique pour Poigne-d'os",b="Gerrig Poigne-d'os demande la Main de Dagun ainsi que deux autres reliques. Il lui faut les trois avant de vous remettre une copie du Sommaire de Yagyin, un texte lié au début d'un nouveau chapitre de son ordre."}},faq={{q="Qu'est-ce que la Main de Dagun ?",a="La Main de Dagun est une relique que Gerrig Poigne-d'os demande avec l'Etoile de Xil'yeh et le Legacy Heart.",al={"main de dagun","qu'est-ce que la main"}},{q="Qui veut la Main de Dagun ?",a="Gerrig Poigne-d'os, à Forgefer, vous demande de lui apporter la Main de Dagun et deux autres reliques.",al={"qui veut la main de dagun","main de poigne-d'os","qui en a besoin"}},{q="Pourquoi Gerrig Poigne-d'os en a-t-il besoin ?",a="Gerrig a besoin de la Main de Dagun, l'une des trois reliques qu'il demande avant de vous remettre une copie du Sommaire de Yagyin.",al={"pourquoi poigne-d'os la veut","pourquoi a-t-il besoin de la main","à quoi sert-elle"}},{q="Que fait la Main de Dagun ?",a="On dit que la Main de Dagun porte un poison qui transforme sa victime en membre d'une ancienne race.",al={"pouvoirs de la main de dagun","que fait-elle","main empoisonnée"}}},fp="13,138,20.193.0,26.100.0,28.90.0,33.110.0,31.97.1"}
P.entries["item:hand-of-dextren-ward"] = {n="Main de Dextren Ward",s="À Sombre-Comté, des familles en deuil attendent la preuve que Dextren Ward a été exécuté dans la Stormwind Stockade. Sa main tranchée est envoyée en ville, signe que justice lui a été rendue.",h="À Sombre-Comté, des familles en deuil attendent la preuve que Dextren Ward a été exécuté dans la Stormwind...",kw={"sombre-comté","dextren ward","bois de la pénombre","ebonlocke","main de dextren ward","chambre des nobles","millstipe","morbent fel","la prison"},ang={["class:Mage"]="En tant que mage, vous savez que Ward n’était pas un lanceur de sorts. Les corps qu’il déterrait alimentaient les arts sombres de Morbent Fel. La mort de Ward frappe donc ceux qui font commerce avec les morts.",["faction:Alliance"]="Pour l’Alliance, l’emprisonnement de Ward révèle le profond fossé entre la lointaine Chambre des nobles de Hurlevent et les colons abandonnés des confins du Bois de la Pénombre."},sec={{t="Le prix d’un profanateur",b="Lord Ebonlocke a condamné Dextren Ward à mort après l’avoir surpris en train de déterrer des corps dans les cimetières du Bois de la Pénombre. Ward les vendait au nécromancien Morbent Fel. Hurlevent est intervenue avant que Sombre-Comté puisse l’exécuter et l’a emmené à La Prison. Pour les familles en deuil, la main de Ward prouve que le profanateur a été exécuté, malgré la clémence malvenue de la Chambre des nobles."},{t="Un message aux nobles",b="La demande du Conseiller Millstipe pour obtenir la main tranchée de Ward défie aussi la couronne. Le Bois de la Pénombre se sent abandonné par l’élite de Hurlevent, qui refuse son aide militaire tout en affirmant son autorité quand cela lui convient. En exécutant un prisonnier dans le plus profond donjon de la capitale et en réclamant sa main, le conseil de Sombre-Comté signifie à la Chambre des nobles qu’il appliquera ses propres lois quand les nobles font défaut."}},faq={{q="Qui était Dextren Ward ?",a="Dextren Ward a été surpris en train de déterrer des cadavres dans les cimetières de Sombre-Comté et de les vendre au nécromancien Morbent Fel. Le Bois de la Pénombre l’a condamné à la décapitation, mais les autorités de Hurlevent l’ont emmené à La Prison au lieu d’exécuter la sentence.",al={"histoire de dextren ward","qui est dextren ward","crime de ward"}},{q="Pourquoi Sombre-Comté veut-elle sa main ?",a="Le Conseiller Millstipe réclame la main tranchée de Ward comme preuve de son exécution. Cela permet aux familles dont les ancêtres ont été dépouillés de leurs tombes de faire leur deuil et indique à la Chambre des nobles que la justice de Sombre-Comté ne peut être annulée.",al={"pourquoi sa main tranchée","pourquoi couper la main de ward","preuve de millstipe"}},{q="Où trouve-t-on la Main de Dextren Ward ?",a="La main est prélevée directement sur Dextren Ward, dans les salles les plus profondes du côté gauche de la Stormwind Stockade. Il combat comme un guerrier et pousse un cri effrayant qui fait fuir ses ennemis.",al={"où trouver ward","emplacement de ward dans la prison","emplacement de dextren ward"}},{q="Pourquoi Hurlevent a-t-elle emprisonné Ward au lieu de l’exécuter ?",a="La Chambre des nobles a revendiqué sa juridiction sur Ward et l’a emprisonné à La Prison au lieu de laisser Sombre-Comté appliquer sa condamnation à mort. Les dirigeants de Sombre-Comté y voient une ingérence corrompue qui méprise le sort de la ville frontalière.",al={"pourquoi ward a-t-il été épargné","ward et la chambre des nobles de hurlevent","ward emprisonné"}}},fx={["48b9455f"]={q="Qu'est-ce que la Main de Dextren Ward ?",a="C'est la main coupée de Dextren Ward, un célèbre pilleur de tombes et profanateur de morts qui a été surpris en train de vendre des cadavres du cimetière de Sombre-Comté au nécromancien Morbent Fel. Prise comme preuve matérielle de son assassinat à l'intérieur de la Stormwind Stockade, elle sert de sinistre confirmation que la peine de mort prononcée par Lord Bouclenoire a enfin été exécutée.",al={"qu'est-ce que la main de dextren ward","objet main de dextren ward","main de dextren ward"}},b59a9a35={q="D'où vient la Main de Dextren Ward ?",a="Elle provient directement du corps de Dextren Ward, tranchée par votre propre lame à l'intérieur de sa cellule à la Stormwind Stockade. Plutôt que d'être forgée ou fabriquée, elle est prise comme un trophée de justice irréfutable à remettre au Conseiller Millstipe dans le Bois de la Pénombre.",al={"d'où vient la main de dextren ward","qui a fait la main de dextren ward","origine de la main de dextren ward"}}},fp="20,181,16.374.0,23.378.1,21.246.0,33.225.0,40.189.0,57.245.0"}
P.entries["item:hand-of-iruxos"] = {n="Hand of Iruxos",s="La Hand of Iruxos est un artefact répugnant qui peut ouvrir des portails démoniaques et refermer ceux qu'elle a ouverts. Taiga Crin-sage en a besoin pour contribuer à bannir les portails du Convent de Mannoroc.",h="La Hand of Iruxos est un artefact répugnant qui peut ouvrir des portails démoniaques et refermer ceux qu'elle...",kw={"lame ardente","portails démoniaques","hand of iruxos","iruxos","convent de mannoroc","proie-de-l'ombre","taiga crin-sage"},sec={{t="Une vision macabre",b="À Proie-de-l'Ombre, Taiga Crin-sage vous remet la Hand of Iruxos et vous demande de la transporter jusqu'au Convent de Mannoroc. Les cultistes de la Lame ardente y ont ouvert des portails qui font venir des démons dans le monde. La main peut refermer les portails qu'elle a ouverts, et Taiga a besoin de son pouvoir pour endiguer la menace démoniaque grandissante."}},faq={{q="Qu'est-ce que la Hand of Iruxos ?",a="C'est une relique sinistre qui ouvre des portails démoniaques et peut refermer ceux qu'elle a ouverts.",al={"hand of iruxos","main d'iruxos"}},{q="Qui me remet la Hand of Iruxos ?",a="Taiga Crin-sage, à Proie-de-l'Ombre, vous remet la Hand of Iruxos et vous demande de l'utiliser contre les portails du Convent de Mannoroc.",al={"qui a la main","main taiga"}},{q="Où utiliser la Hand of Iruxos ?",a="Taiga Crin-sage vous demande d'utiliser la Hand of Iruxos pour bannir les portails démoniaques du Convent de Mannoroc.",al={"emplacement de la main","où utiliser la main"}},{q="Pourquoi y a-t-il des démons au Convent de Mannoroc ?",a="Les cultistes de la Lame ardente ont ouvert au Convent de Mannoroc des portails qui font venir des démons dans le monde.",al={"démons mannoroc","pourquoi des démons"}},{q="La Hand of Iruxos peut-elle refermer des portails ?",a="La Hand of Iruxos peut refermer les portails démoniaques qu'elle a ouverts.",al={"refermer les portails","main et portail"}}},fp="14,172,16.299.0,27.82.0,32.127.0,34.94.0,39.94.0,37.59.0"}
P.entries["item:handful-of-oats-classic"] = {n="Poignée d'avoine",s="Dans la Marche de l’Ouest, la vieille Blanchy a besoin d’avoine après la panne du chariot des Froissabotte.",h="Dans la Marche de l’Ouest, la vieille Blanchy a besoin d’avoine après la panne du chariot des Froissabotte.",kw={"blanchy","froissabotte","céréales","poignée d'avoine","avoine","sacs d’avoine","marche de l’ouest"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance dans la Marche de l’Ouest, vous pouvez offrir un petit geste de compassion aux réfugiés bloqués comme les Froissabotte, en ramassant de l’avoine sur la frontière délaissée de Hurlevent."},sec={{t="Du fourrage parmi les ruines",b="La Marche de l’Ouest nourrissait autrefois le royaume de Hurlevent. Aujourd’hui, ses fermes sont envahies par la végétation ou contrôlées par les bandits défias et des moissonneuses automates détraquées. Des sacs de céréales et d’avoine restent près des granges et des dépendances, ainsi que dans les champs envahis. Les voyageurs et les réfugiés dont le chariot tombe en panne sur les routes poussiéreuses peuvent ramasser l’avoine restante pour leurs chevaux de trait épuisés."}},faq={{q="À quoi sert l’avoine ?",a="L’avoine nourrit Blanchy, la jument épuisée de la famille Froissabotte. Leur chariot est tombé en panne sur une route de la Marche de l’Ouest, la laissant affamée et épuisée.",al={"à quoi sert l’avoine","pourquoi ramasser de l’avoine","utilisation de la poignée d’avoine"}},{q="Où trouver cette avoine ?",a="Des sacs d’avoine sont éparpillés dans les fermes abandonnées de la Marche de l’Ouest. Cherchez surtout au sud-ouest.",al={"où trouver de l’avoine","emplacement des sacs d’avoine","comment obtenir de l’avoine"}},{q="Pourquoi les sacs d’avoine sont-ils sans surveillance ?",a="La Confrérie défias s’est soulevée soudainement, tandis que des machines agricoles détraquées ravageaient les champs. Les fermiers ont fui précipitamment, abandonnant les récoltes et d’autres provisions dans leurs champs et leurs granges.",al={"pourquoi les sacs sont abandonnés","qui a laissé l’avoine"}}},fx={["67495104"]={q="Qu'est-ce qu'une Poignée d'avoine ?",a="Une Poignée d'avoine est une simple nourriture pour le bétail ramassée dans les sacs de toile de jute laissés éparpillés dans les fermes de la Marche de l’Ouest. Aux jours fertiles, ces grains nourrissaient les chevaux de trait et les bêtes de labour du royaume. Aujourd'hui, avec les champs abandonnés aux golems des moissons renégats et aux bandits, l'avoine en vrac fait partie des rares restes de fourrage propre laissés pour une bête de somme affamée.",al={"qu'est-ce qu'une poignée d'avoine","objet poignée d'avoine","qu'est-ce que la poignée d'avoine"}},a4d08151={q="Pourquoi quelqu'un voudrait-il une Poignée d'avoine ?",a="Verna Froncebouille en a désespérément besoin pour nourrir Blanchy, le cheval de trait dévoué de sa famille. Après que les Froncebouille aient fui leur foyer, leur chariot est tombé en panne sur la route, laissant Blanchy épuisée, affamée et à bout de forces. Quelques poignées de grain nourrissant sont tout ce qui maintient la fidèle jument en vie pendant que la famille reste bloquée.",al={"qui veut une poignée d'avoine","pourquoi ramasser de l'avoine","pourquoi avoir besoin d'une poignée d'avoine"}}},fp="15,75,22.347.0,35.137.0,30.94.0,37.187.0"}
P.entries["item:handful-of-stardust"] = {n="Poignée de poussière d'étoile",s="Dans les ruines de Chimétoile, le givre recouvre les buissons au sud d'Astranaar. Les guérisseurs elfes de la nuit utilisent cette poudre pour faire tomber les fortes fièvres.",h="Dans les ruines de Chimétoile, le givre recouvre les buissons au sud d'Astranaar.",kw={"orneval","astranaar","orendil","pelturas","cataplasme","relara","les ruines de chimétoile","poussière d'étoile"},ang={["profession:Herbalism"]="Récoltez à la main la poussière d'étoile sur les buissons lumineux. Elle témoigne de l'usage que font les elfes de la nuit des plantes locales rares pour leurs remèdes.",["race:NightElf"]="En tant qu'elfe de la nuit défendant Orneval, vous pouvez voir le lien entre les remèdes locaux, les ruines antiques de votre peuple et ses traditions herboristes."},sec={{t="Un remède végétal rafraîchissant",b="La poussière d'étoile s'accroche aux arbustes des ruines de Chimétoile, au sud d'Astranaar. Sa fine poudre brille comme le givre. Des esprits élémentaires rôdent parmi les pierres brisées, mais les plantes y prospèrent et absorbent une lueur rare. Les guérisseurs elfes de la nuit transforment ces résidus en cataplasmes contre les fièvres intenses et persistantes. Ils les utilisent lorsque les onguents ordinaires et les eaux des puits de lune ne suffisent pas à soulager les malades."},{t="L'espoir d'un père",b="Pelturas Blanchelune, un père inquiet d'Astranaar, suivit les conseils de l'herboriste Orendil Largefeuille et partit chercher la poudre. Sa jeune fille, Relara, souffrait d'un mal magique tenace et de cauchemars. Une bénédiction provenant d'une pierre touchée par Elune apaisa d'abord son esprit, mais sa forte fièvre persistait. Pelturas chercha de la poussière d'étoile pour préparer une pâte rafraîchissante et lui sauver la vie."}},faq={{q="Où trouver la Poignée de poussière d'étoile ?",a="Récoltez la poussière d'étoile sur les buissons lumineux des ruines de Chimétoile, au sud d'Astranaar, dans le centre d'Orneval.",al={"emplacement de la poussière d'étoile","où trouver la poussière d'étoile","buissons couverts de poussière d'étoile"}},{q="À quoi sert cette poussière d'étoile ?",a="Les guérisseurs elfes de la nuit utilisent cette poudre dans des cataplasmes contre les fièvres intenses et persistantes. Pelturas Blanchelune en chercha pour préparer une pâte rafraîchissante pour sa fille, Relara.",al={"utilisation de la poussière d'étoile","remède de pelturas","utilité de la poussière d'étoile"}},{q="Quels dangers menacent les buissons de poussière d'étoile ?",a="Des élémentaires d'eau hostiles rôdent près du rivage et parmi les piliers écroulés des ruines de Chimétoile, où poussent les buissons.",al={"ennemis des ruines de chimétoile","créatures des ruines de chimétoile"}},{q="La poussière d'étoile est-elle liée à la déesse Elune ?",a="Les ruines portent un nom évoquant les étoiles, mais les herboristes recommandent la poussière d'étoile pour sa nature givrée et rafraîchissante, comme remède physique.",al={"la poussière d'étoile est-elle magique","lien entre elune et la poussière d'étoile"}}},fx={["8cce1335"]={q="Qu'est-ce qu'une Poignée de poussière d'étoile ?",a="Une Poignée de poussière d'étoile est une poudre scintillante et givrée collectée sur le feuillage brillant dans les anciennes Ruines de Chimétoile d'Orneval. Ce résidu botanique rare possède des propriétés apaisantes et magiques rafraîchissantes, ce qui le rend inestimable pour préparer de puissants cataplasmes à base de plantes pour traiter les fièvres persistantes et mortelles.",al={"qu'est-ce qu'une poignée de poussière d'étoile","qu'est-ce que la poussière d'étoile","lore de l'objet poussière d'étoile"}}},fp="19,128,23.366.0,15.368.1,39.106.0,31.160.0,42.126.0,41.119.0"}
P.entries["item:hardened-tortoise-shell"] = {n="Carapace de tortue durcie",s="Dans les Salines, les pilotes cherchent des carapaces assez résistantes pour contenir un carburant dangereux. À la Piste des mirages, les pilotes gnomes prisent les carapaces de tortue durcies, prélevées sur les tortues éclatantes, car elles résistent aux carburants expérimentaux volatils et corrosifs.",h="Dans les Salines, les pilotes cherchent des carapaces assez résistantes pour contenir un carburant dangereux.",kw={"carapace de tortue durcie","piste des mirages","voiture-fusée","les salines","tortue éclatante","lachnouf zéboulon"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous comprenez pourquoi des carapaces organiques pourraient convenir à des réservoirs de carburant sous haute pression. Quand un carburant brassé par les gnomes fait fondre les conduites en alliage ordinaire, des matériaux naturels résistants peuvent les remplacer.",["race:Gnome"]="En tant que gnome, vous pourriez voir dans une tortue du désert un récipient léger et résistant pour un dangereux carburant de fusée."},sec={{t="Une armure naturelle face aux dangers de la vitesse",b="Les tortues éclatantes, des hargneuses aux foreuses, parcourent les Salines. Leurs carapaces les protègent du sel et des prédateurs errants. La chimie expérimentale gnome peut corroder ou faire éclater les réservoirs métalliques. C’est pourquoi les mécaniciens comme Lachnouf Zéboulon prisent ces carapaces comme matière première pour fabriquer des réservoirs de fortune résistants aux acides et capables de contenir des propergols de fusée volatils."}},faq={{q="Où trouver des carapaces de tortue durcies ?",a="Dans les vastes étendues salines des Salines, à Mille pointes, vous trouverez des carapaces de tortue durcies sur les Sparkleshell Snappers, les Borers et les tortues éclatantes ordinaires.",al={"où trouver des carapaces de tortue","emplacement des carapaces durcies","emplacement des tortues éclatantes"}},{q="Pourquoi Lachnouf Zéboulon veut-il ces carapaces ?",a="Lachnouf Zéboulon veut utiliser ces carapaces pour fabriquer des réservoirs de carburant. Son frère conçoit un carburant de fusée extrêmement puissant et corrosif, qui risque de faire fondre le châssis de leur voiture de course. Lachnouf compte évider ces carapaces résistantes et les renforcer.",al={"pourquoi vouloir des carapaces","utilisation des carapaces par lach nouf","à quoi servent les carapaces"}},{q="Les outils d’atelier ordinaires permettent-ils de les façonner facilement ?",a="Non. Ces carapaces sont d’une dureté anormale. Les mécaniciens gnomes s’attendent à user une boîte à outils entière d’instruments en métal pour les tailler, les percer et les façonner en réservoirs.",al={"les carapaces sont-elles difficiles à façonner","outils pour plier les carapaces"}}},fx={cc86b908={q="Qu'est-ce qu'une Carapace de tortue durcie ?",a="C'est la carapace extérieure naturelle exceptionnellement durable récoltée sur les grandes tortues à carapace étincelante qui parcourent les plaines salées. Ces carapaces sont connues pour être beaucoup plus résistantes que les peaux de bêtes ordinaires ou le placage standard, résistant à la friction, au sel et à une érosion chimique intense.",al={"qu'est-ce qu'une carapace de tortue durcie","objet carapace de tortue durcie","carapace durcie"}},["4ed6fee7"]={q="D'où vient une Carapace de tortue durcie ?",a="Ces carapaces sont totalement naturelles et non fabriquées. Elles sont récoltées directement sur les tortues à carapace étincelante, les tortues carnassières et les foreuses qui prospèrent dans la nature sauvage, dure et brûlée par le soleil, des Salines dans les Mille pointes.",al={"origine de la carapace de tortue durcie","qui a fait la carapace de tortue durcie","d'où viennent les carapaces durcies"}}},fp="23,236,36.355.0,43.181.0,45.238.0,46.156.0"}
P.entries["item:hardened-tumor"] = {n="Tumeur durcie",s="Dans la Forêt des Pins-Argentés, la Société royale des apothicaires étudie une excroissance rare chez les murlocs Vile-Nageoire. L’apothicaire Berard l’a signalée avant que la malédiction d’Arugal ne fasse de lui un serviteur sans esprit.",h="Dans la Forêt des Pins-Argentés, la Société royale des apothicaires étudie une excroissance rare chez les...",kw={"apothicaire faranell","apothicaire renferrel","berard","les îles de l'aube","tumeur durcie","lac lordamere","murloc","the new plague","vile-nageoire"},ang={["race:Undead"]="En tant que mort-vivant, vous aidez maître apothicaire Faranell à faire avancer ses recherches sur The New Plague. Vous servez Lady Sylvanas et les Réprouvés dans leur lutte contre les adversaires vivants et morts-vivants."},sec={{t="Une rare anomalie biologique",b="Au bord du lac Lordamere, les murlocs Vile-Nageoire développent parfois une excroissance calcifiée rare. L’apothicaire Berard l’a signalée en étudiant la faune près des frontières orientales de la Forêt des Pins-Argentés. Elle n’apparaît que chez les spécimens adultes du littoral et des îles de l’aube. Sa cause reste incertaine, mais la Société royale des apothicaires a remarqué la densité de son tissu."},{t="Un ingrédient pour The New Plague",b="Après que la malédiction d’Arugal eut fait de Berard un serviteur sans esprit, son journal fut retrouvé à Bois-du-Bûcher et remis à l’apothicaire Renferrel, au Sépulcre. Renferrel a vu le potentiel de ces travaux et envoyé des agents réprouvés récupérer une Tumeur durcie et des mousses aquatiques indigènes.\n\nMaître apothicaire Faranell supervise l’Apothicarium à Fossoyeuse. Il recherche des réactifs capables de résister à la décomposition ou de modifier la matière biologique, et a ajouté cette excroissance aux recherches de la Société sur The New Plague."}},faq={{q="Qu’est-ce qu’une Tumeur durcie ?",a="Une Tumeur durcie est une masse calcifiée anormale et rare qui se forme chez les murlocs Vile-Nageoire autour du lac Lordamere. L’apothicaire Berard l’a découverte, et ses propriétés biologiques inhabituelles la rendent résistante à la décomposition physique ordinaire.",al={"qu’est-ce que cette tumeur","histoire de la tumeur","butin tumeur durcie"}},{q="Pourquoi la Société royale des apothicaires la recherche-t-elle ?",a="La Société royale des apothicaires recueille des spécimens toxiques et biologiques inhabituels pour ses travaux sur The New Plague. Maître apothicaire Faranell estime que la résistance de la tumeur et sa composition cellulaire pourraient servir aux expériences sur le chancre.",al={"pourquoi l’apothicaire veut la tumeur","recette usage tumeur de la mort","faranell et la tumeur"}},{q="Où trouve-t-on ces tumeurs ?",a="Les murlocs Vile-Nageoire de la Forêt des Pins-Argentés portent ces tumeurs, notamment près des îles de l’aube, dans l’est du lac Lordamere, et le long des rives du village au nord-est du Moulin-de-l’Ambre.",al={"où trouver une tumeur durcie","quels murlocs donnent la tumeur","emplacement de la tumeur"}},{q="Qui était l’apothicaire Berard ?",a="L’apothicaire Berard était un apothicaire de la Société royale des apothicaires affecté dans la Forêt des Pins-Argentés. Il étudiait la flore et la faune locales ainsi que les mutations des murlocs, et découvrit l’utilité des mousses et des tumeurs durcies des îles de l’aube. La malédiction d’Arugal fit de lui un serviteur sans esprit à Bois-du-Bûcher.",al={"qui est berard","histoire de berard","journal de berard"}}},fx={["9aa7efc6"]={q="D'où vient une Tumeur durcie ?",a="Les Tumeurs durcies sont des excroissances biologiques anormales trouvées sur les murlocs Vile-Nageoire vivant autour du Lac Lordamere dans la Forêt des Pins-Argentés. Elles ne sont pas fabriquées par des mains mortelles, mais plutôt récoltées sur la chair de ces créatures amphibies corrompues. L'Apothicaire Berard a documenté leur existence pour la première fois dans ses recherches sur le terrain, notant qu'il est remarquablement rare de trouver un murloc portant une excroissance aussi inhabituellement dense et calcifiée.",al={"origine de la tumeur durcie","d'où viennent les tumeurs durcies","qui a fait la tumeur durcie"}}},fp="14,179,25.353.0,23.477.1,25.212.0,46.223.0,29.175.0,26.287.0"}
P.entries["item:harpy-lieutenant-ring"] = {n="Anneau de lieutenant harpie",s="Dans les Collines arides, l’Anneau de lieutenant harpie indique le rang des Witchwing Slayers qui commandent la volée. À La Croisée, Darsok Vivedague demande ces anneaux comme preuve de leur mort.",h="Dans les Collines arides, l’Anneau de lieutenant harpie indique le rang des Witchwing Slayers qui commandent...",kw={"la croisée","darsok vivedague","les collines arides","anneau de lieutenant harpie","les tarides","witchwing","witchwing slayer"},ang={["class:Rogue"]="En tant que voleur, vous apprécierez peut-être les frappes précises que recherche Darsok Vivedague. Faufillez-vous dans les nids des harpies et tuez leurs commandantes.",["faction:Horde"]="En tant que membre de la Horde, vous affrontez les harpies Witchwing qui harcèlent les lignes de ravitaillement entre Durotar, Mulgore et les avant-postes du nord. Briser leur commandement aide à sécuriser le passage des caravanes de la Horde dans les Tarides."},sec={{t="Insignes de rang",b="Les Witchwing Slayers dirigent les attaques contre les voyageurs de la Horde dans les Tarides. Leurs anneaux les distinguent des pillards ordinaires, qui combattent sans grande coordination. Darsok Vivedague et les défenseurs de La Croisée ont besoin des anneaux pris aux tueuses tombées au combat. Ils confirment qu’une partie du commandement des harpies a été brisée."}},faq={{q="Qui porte ces anneaux ?",a="Les Witchwing Slayers portent ces anneaux en tant que lieutenants de la volée Witchwing des Collines arides.",al={"qui fait tomber l’anneau de lieutenant harpie","anneaux des witchwing slayers","quelles harpies ont des anneaux"}},{q="Où trouver les Witchwing Slayers ?",a="Les Witchwing Slayers nichent dans les Collines arides, au nord-ouest de La Croisée, dans le nord des Tarides.",al={"emplacement des witchwing slayers","où sont les lieutenants harpies","harpies des collines arides"}},{q="Pourquoi Darsok Vivedague les veut-il ?",a="Darsok veut ces anneaux comme preuve que les Witchwing Slayers ont été tuées. Leur mort brise une partie du commandement de la volée.",al={"pourquoi récupérer les anneaux de harpie","anneaux de darsok vivedague"}},{q="Les pillards harpies ordinaires portent-ils ces anneaux ?",a="Non. Ces anneaux distinguent les Witchwing Slayers des harpies ordinaires, qui sont des subalternes de rang inférieur.",al={"les pillards peuvent-ils faire tomber des anneaux","les pillards witchwing ont-ils des anneaux"}}},fx={["105f77c8"]={q="Qu'est-ce qu'un Anneau de lieutenant harpie ?",a="Ces anneaux sont des ornements distinctifs portés par les tueuses Aile-de-sorcière des Collines arides. Au sein de leurs perchoirs, les tueuses agissent en tant que lieutenants, commandant les harpies subalternes au nom de leurs matriarches. Pour les éclaireurs de la Horde surveillant les Tarides, ces bijoux servent de preuve identifiable du rang au sein de la troupe vicieuse.",al={"qu'est-ce qu'un anneau de lieutenant harpie","identité de l'anneau harpie","lore de l'anneau de lieutenant harpie"}}},fp="21,180,14.331.0,24.88.0,37.94.0,38.129.0,43.96.0"}
P.entries["item:hatecrest-naga-scale"] = {n="Hatecrest Naga Scale",s="Les Hatecrest Naga Scales proviennent des nagas qui menacent l’île de Sardor, en Féralas. Latronicus Moonspear, au Bastion de Pennelune, veut affaiblir la présence des nagas et étudier ce qu’on peut en tirer.",h="Les Hatecrest Naga Scales proviennent des nagas qui menacent l’île de Sardor, en Féralas.",kw={"bastion de pennelune","hatecrest naga scale","hatecrest naga scales","latronicus moonspear","nagas","pratt","ile de sardor"},ang={["race:NightElf"]="En tant qu’Elfe de la nuit, vous aidez Latronicus à défendre les intérêts du Bastion de Pennelune sur l’île de Sardor. Il affirme que son peuple recherche la paix, mais qu’il défendra ce qui lui appartient."},sec={{t="Des écailles pour Pennelune",b="Latronicus Moonspear vous demande d’apporter dix Hatecrest Naga Scales au Bastion de Pennelune. Il craint que les nagas ne tentent de s’emparer de l’île de Sardor et veut donc réduire leur présence avant que la menace ne grandisse. Les écailles doivent être en bon état. Une fois qu’il les aura, il compte les envoyer à Pratt pour les étudier et voir si elles peuvent servir à l’artisanat."}},faq={{q="À quoi servent les Hatecrest Naga Scales ?",a="Latronicus Moonspear veut dix Hatecrest Naga Scales en bon état afin de réduire la présence des nagas sur l’île de Sardor. Il compte aussi les envoyer à Pratt pour voir si elles peuvent servir à l’artisanat.",al={"pourquoi des écailles","utilité des hatecrest naga scales","but des écailles"}},{q="Qui veut les écailles ?",a="Latronicus Moonspear, au Bastion de Pennelune, demande dix Hatecrest Naga Scales.",al={"qui a besoin des écailles","écailles de latronicus","à qui les écailles"}},{q="Pourquoi Pennelune veut-elle affaiblir les nagas ?",a="Latronicus craint que les nagas Hatecrest ne tentent de s’emparer de l’île de Sardor. Il veut donc réduire leur présence avant qu’ils n’y parviennent.",al={"pourquoi combattre les hatecrest","menace des nagas","pourquoi l’île de sardor"}},{q="Que pourrait faire Pratt avec les écailles ?",a="Latronicus compte envoyer les écailles à Pratt, qui pourra peut-être en tirer un objet utile.",al={"écailles pour pratt","artisanat avec les écailles","écailles et artisanat"}}},fp="20,205,22.331.0,35.182.0,21.82.0,45.127.0,36.98.0"}
P.entries["item:hatefury-claw"] = {n="Hatefury Claw"}
P.entries["item:hatefury-horn"] = {n="Hatefury Horn",s="Un Hatefury Horn est prélevé sur l’un des satyres des ruines de Sargeron, à l’est de Nijel’s Point. Kreldig Ungor rassemble des cornes et des griffes pour une liste de réactifs envoyée depuis Kharanos.",h="Un Hatefury Horn est prélevé sur l’un des satyres des ruines de Sargeron, à l’est de Nijel’s Point.",kw={"hatefury claw","hatefury horn","satyre hatefury","kreldig ungor","leftwitch","combe de nijel","réactifs","sargeron"},ang={["race:Gnome"]="En tant que gnome, vous connaissez peut-être la réputation de Leftwitch : cette mage de Kharanos a envoyé une liste de réactifs aux Reclaimers."},sec={{t="Un réactif de Sargeron",b="À l’est de Nijel’s Point, les satyres Hatefury hantent les ruines de Sargeron. Leurs cornes font partie des réactifs dont Kreldig Ungor a besoin pour Leftwitch, une mage gnome de Kharanos. Kreldig demande dix cornes ainsi que dix Hatefury Claws, sans pouvoir garantir leur qualité."}},faq={{q="D’où viennent les Hatefury Horns ?",a="Les satyres Hatefury des ruines de Sargeron, à l’est de Nijel’s Point, portent ces cornes.",al={"source des hatefury horns","où trouver des cornes","cornes de satyre"}},{q="Qui veut des Hatefury Horns ?",a="Kreldig Ungor rassemble dix Hatefury Horns pour une liste de réactifs envoyée par Leftwitch, une mage gnome de Kharanos.",al={"qui a besoin de hatefury horns","cornes pour kreldig","réactifs pour les reclaimers"}},{q="Pourquoi Kreldig les rassemble-t-il ?",a="Kreldig rassemble ces cornes comme réactifs pour Leftwitch, à Kharanos.",al={"utilité des cornes","réactifs de leftwitch","à quoi servent les cornes"}},{q="De quoi Kreldig a-t-il besoin d’autre ?",a="Kreldig demande aussi dix Hatefury Claws.",al={"autres réactifs","hatefury claws","que faire des cornes"}}},fp="13,166,23.263.0,34.78.0,25.105.0,31.64.0,28.41.0"}
P.entries["item:head-of-arugal"] = {n="Tête d'Arugal",s="Au Donjon d’Ombrecroc, la Tête d’Arugal est prise à l’archimage fou qui commande les worgens. Les Réprouvés du Sépulcre la réclament comme preuve de sa chute.",h="Au Donjon d’Ombrecroc, la Tête d’Arugal est prise à l’archimage fou qui commande les worgens.",kw={"arugal","arugal must die","dalar tisselaube","tête d'arugal","le sépulcre","donjon d'ombrecroc","forêt des pins-argentés"},ang={["class:Mage"]="En tant que mage, vous voyez dans la tête tranchée d’un ancien archimage du Kirin Tor un avertissement contre la folie et la ruine que peuvent entraîner des invocations désespérées, même chez les praticiens les plus doués.",["race:Undead"]="En tant que Réprouvé, vous contribuez à éliminer un sorcier dangereux de la lisière sud de la Forêt des Pins-Argentés et à sécuriser ces terres pour la Dame noire."},sec={{t="Trophée de l’archimage fou",b="L’archimage Arugal commande les worgens depuis le Donjon d’Ombrecroc, dans la Forêt des Pins-Argentés. Au Sépulcre, Dalar Tisselaube ordonne de récupérer sa tête tranchée. Les Réprouvés voient la chute d’Arugal comme un coup porté aux bêtes qui entravent l’emprise de dame Sylvanas sur la Forêt des Pins-Argentés. Apportez la tête à Dawnweaver, et elle prouvera que la sorcellerie d’Arugal a été arrachée à ces terres."}},faq={{q="Qui veut la Tête d’Arugal ?",a="Dalar Tisselaube, un émissaire au Sépulcre, dans la Forêt des Pins-Argentés, veut la tête dans le cadre de la mission appelée Arugal Must Die.",al={"qui veut la tête d’arugal","remettre la tête d’arugal","qui prend la tête d’arugal"}},{q="Où obtenir la Tête d’Arugal ?",a="La Tête d’Arugal s’obtient sur l’archimage Arugal, qui vit au sommet du Donjon d’Ombrecroc, au-dessus du Bois-du-Bûcher et des bois de la Forêt des Pins-Argentés.",al={"comment obtenir la tête d’arugal","butin de la tête d’arugal","où trouver la tête d’arugal"}},{q="Pourquoi les Réprouvés veulent-ils la mort d’Arugal ?",a="Les Réprouvés veulent la mort d’Arugal, car lui et sa meute de worgens les empêchent de faire de la Forêt des Pins-Argentés un bastion sûr pour dame Sylvanas et Fossoyeuse.",al={"pourquoi tuer arugal","raison des réprouvés contre arugal","pourquoi dalar veut la mort d’arugal"}},{q="Que se passe-t-il après avoir remis la tête ?",a="Après avoir reçu la tête, Dalar Tisselaube jure d’éradiquer les vestiges des sorts d’Arugal. Il déclare la Forêt des Pins-Argentés libérée de l’emprise du mage fou.",al={"après la mort d’arugal","résultat d’arugal must die"}}},fx={c9f64370={q="Qu'est-ce que la Tête d'Arugal ?",a="La Tête d'Arugal est la tête coupée de l'archimage Arugal, l'ancien magicien fou de Dalaran qui a libéré les worgens sur la Forêt des Pins-Argentés. Prise dans sa forteresse du Donjon d'Ombrecroc, elle sert de preuve matérielle indéniable que le sorcier fou a enfin été tué et que ses magies noires ont été brisées.",al={"qu'est-ce que la tête d'arugal","objet tête d'arugal","tête d'arugal"}},["10305f38"]={q="D'où vient la Tête d'Arugal ?",a="La tête est réclamée directement auprès de l'archimage Arugal dans les hauteurs du Donjon d'Ombrecroc. Après avoir envahi la forteresse maudite et vaincu l'archimage fou au combat, vous l'abattez et prenez sa tête pour confirmer son décès.",al={"où obtenir la tête d'arugal","qui lâche la tête d'arugal","origine de la tête d'arugal"}}},fp="14,152,26.345.0,29.128.0,39.144.0,37.160.0,41.147.1"}
P.entries["item:head-of-bangalash"] = {n="Head of Bangalash",s="Hemet Nesingwary cherche Head of Bangalash dans la Vallée de Strangleronce. Le grand tigre blanc est la dernière proie de sa chasse.",h="Hemet Nesingwary cherche Head of Bangalash dans la Vallée de Strangleronce.",kw={"chasseur de gros gibier","head of bangalash","hemet nesingwary","trophée de chasse","king bangalash","vallée de strangleronce","tigre blanc"},ang={["class:Hunter"]="En tant que chasseur, la traque de King Bangalash par Hemet est une mesure de son talent pour chasser et suivre une piste."},sec={{t="Le grand tigre blanc",b="Hemet Nesingwary traque King Bangalash depuis longtemps. Après les chasses à Sin'Dall, Bhag'thera et Tethis, le grand tigre blanc est le trophée qu'il convoite encore. La tête du tigre prouvera que la chasse est terminée."}},faq={{q="Qui veut Head of Bangalash ?",a="Hemet Nesingwary veut Head of Bangalash comme trophée de sa chasse à King Bangalash.",al={"qui veut la tête du tigre","trophée de hemet","à qui est-ce destiné"}},{q="Qu'est-ce que Bangalash ?",a="King Bangalash est un grand tigre blanc de la Vallée de Strangleronce.",al={"qui est bangalash","tigre blanc","tigre roi"}},{q="Pourquoi Hemet veut-il la tête ?",a="Hemet traque King Bangalash depuis longtemps et considère le tigre comme le véritable trophée de la chasse.",al={"pourquoi hemet le veut","chasse à bangalash","pourquoi tuer bangalash"}},{q="Quelles chasses ont précédé celle de Bangalash ?",a="Hemet cite Sin'Dall, Bhag'thera et Tethis parmi les chasses précédant celle de King Bangalash.",al={"gros gibier précédent","sin'dall bhag'thera tethis","qu'a chassé hemet"}}},fp="17,123,21.207.0,32.89.0,18.60.0,29.97.0,33.91.0"}
P.entries["item:head-of-baron-vardus"] = {n="Head of Baron Vardus",s="La tête tranchée du baron Vardus prouve qu’Austrivage traque l’ancien noble d’Alterac. Le magistrat Maleb réclame justice pour les violences infligées à la ville.",h="La tête tranchée du baron Vardus prouve qu’Austrivage traque l’ancien noble d’Alterac.",kw={"alterac","baron vardus","tête du baron vardus","magistrat maleb","austrivage","strahnbrande","syndicat"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous pouvez voir Austrivage réclamer justice contre un noble du Syndicat qui a envoyé ses hommes contre la ville."},sec={{t="Un baron déchu",b="Le contrat portant le nom du baron Vardus mène d’Austrivage aux repaires du Syndicat en Alterac. Vardus est un noble de l’ancien royaume, connu pour son cœur froid et ses méthodes brutales. Le magistrat Maleb veut le faire répondre de ses actes après qu’il a envoyé ses hommes contre Austrivage. La tête du baron est la preuve qu’exige Maleb."}},faq={{q="Qui était le baron Vardus ?",a="Le baron Vardus était un noble de l’ancien royaume d’Alterac, connu pour son cœur froid et ses méthodes brutales.",al={"qui est vardus","baron vardus","histoire de vardus"}},{q="Pourquoi Austrivage veut-elle sa tête ?",a="Le magistrat Maleb affirme que Vardus a envoyé ses hommes contre Austrivage et veut le faire répondre de ses actes.",al={"pourquoi tuer vardus","austrivage veut vardus","vardus recherché"}},{q="Où trouver le baron Vardus ?",a="Vardus se trouve parmi les repaires du Syndicat en Alterac, peut-être dans les ruines de Strahnbrande ou dans la vallée au nord de celles-ci.",al={"où est vardus","lieu où se trouve vardus","trouver le baron"}},{q="À qui remettre la tête ?",a="Le magistrat Maleb, à Austrivage, reçoit la tête du baron Vardus comme preuve que la traque est terminée.",al={"qui veut la tête","tête pour maleb","tête de vardus"}}},fp="20,163,19.327.0,21.105.0,34.96.0,32.115.0,22.93.1"}
P.entries["item:head-of-bazil-thredd"] = {n="Tête de Bazil Thredd",s="Le Gardien Thelwater exige la preuve que la révolte de la Prison a été écrasée. La tête tranchée de Bazil Thredd doit prouver que le chef rebelle est mort et que les défias ne contrôlent plus la prison d’Hurlevent.",h="Le Gardien Thelwater exige la preuve que la révolte de la Prison a été écrasée.",kw={"bazil thredd","défias","tête de bazil thredd","prison","the stockade riots","gardien thelwater"},ang={["faction:Alliance"]="Pour l’Alliance, la tête tranchée de Thredd apaise la panique immédiate dans la capitale. Elle prouve que la justice de la couronne peut atteindre les rebelles de la Prison."},sec={{t="Preuve de la fin de la trahison",b="Bazil Thredd a mené la révolte dans la Prison, sous Hurlevent. Depuis son quartier cellulaire, il dirigeait les émeutes avec l’aide de détenus défias fidèles. Le Gardien Thelwater se méfie des étrangers et peine à maintenir l’ordre. Il exige la tête de Thredd pour prouver que le meneur est mort et éprouver l’allégeance de The Adventurer à Hurlevent."}},faq={{q="Qui réclame la Tête de Bazil Thredd ?",a="À l’entrée de la Prison, le Gardien Thelwater réclame la tête de Bazil Thredd. Il veut la preuve que le meneur est mort avant de révéler ce qu’il sait des conspirateurs de Thredd.",al={"qui a besoin de la tête de thredd","où rendre la tête de thredd","donneur de quête de la tête de thredd"}},{q="Qui était Bazil Thredd ?",a="Bazil Thredd était un membre haut placé de la Confrérie défias, emprisonné sous Hurlevent. Lorsque les prisonniers se sont révoltés, il a pris les commandes et coordonné le soulèvement depuis le quartier cellulaire est.",al={"qui est bazil thredd","histoire de thredd","qu’a fait bazil"}},{q="Où trouver Bazil Thredd ?",a="Bazil Thredd se trouve dans l’aile est de la Prison, au fond du quartier, dans une cellule centrale. Des détenus défias qui lui sont fidèles gardent la cellule.",al={"où se trouve thredd","emplacement de thredd","comment trouver bazil thredd"}}},fx={["4fd859a6"]={q="Qu'est-ce que la Tête de Bazil Thredd ?",a="C'est la tête coupée de Bazil Thredd, le prisonnier orchestrant la rébellion au plus profond de la prison. Pour le Gardien Thelwater, la présentation de ce sinistre trophée sert de preuve matérielle indéniable que le meneur de la révolte carcérale a été définitivement éliminé.",al={"qu'est-ce que la tête de bazil thredd","objet tête de bazil thredd","tête de bazil thredd"}},fe91a8a0={q="D'où vient la Tête de Bazil Thredd ?",a="Elle est prise directement sur Bazil Thredd après que vous l'ayez affronté et tué dans sa cellule au sein de la Stormwind Stockade, où il dirige le soulèvement sous la protection de ses gardes brutaux.",al={"où obtenir la tête de bazil thredd","comment obtenir la tête de bazil thredd","source de la tête de bazil thredd"}}},fp="20,202,22.327.0,35.171.0,21.197.0,28.143.0"}
P.entries["item:head-of-deepfury"] = {n="Tête de Furie-du-fond",s="À la Stormwind Stockade, Kam Furie-du-fond meurt dans les émeutes de la prison. Sa tête tranchée répond au grief des défenseurs nains de Dun Modr et marque la fin d’un conspirateur Sombrefer.",h="À la Stormwind Stockade, Kam Furie-du-fond meurt dans les émeutes de la prison.",kw={"deepfury","dun modr","tête de furie-du-fond","kam furie-du-fond","tresse-longue","motley garmason","prison","viaduc de thandol"},ang={["faction:Alliance"]="La demande de la tête de Deepfury révèle des tensions au sein de l’Alliance. Les autorités humaines de Hurlevent privilégient la prudence juridique, tandis que les montagnards de Forgefer réclament une justice sévère.",["race:Dwarf"]="Pour les nains de Forgefer, prendre la tête de Deepfury répond au grief causé par la traîtrise des Sombrefer au Viaduc de Thandol."},sec={{t="La justice d’un conspirateur",b="Kam Furie-du-fond était détenu à la Stormwind Stockade pour des raisons politiques. La diplomatie humaine lui avait épargné l’exécution. Roggo a découvert que Deepfury avait planifié l’attaque du Viaduc de Thandol, où sont morts des soldats du roi Magni et des proches de Tresse-longue le Macabre. Les montagnards de Forgefer à Dun Modr ne pouvaient accepter qu’il reste emprisonné. Lié par le devoir à son poste, Motley Garmason a envoyé des champions de l’Alliance dans la prison en révolte pour prendre la tête de Deepfury et venger les nains."}},faq={{q="Qui était Kam Furie-du-fond ?",a="Kam Furie-du-fond était un nain Sombrefer qui a contribué à planifier le sabotage du Viaduc de Thandol, le pont terrestre entre Les Paluns et les Hautes-terres Arathies. Sa conspiration a tué des défenseurs nains, dont le frère de Tresse-longue le Macabre.",al={"histoire de kam furie-du-fond","qui est deepfury","passé de kam furie-du-fond"}},{q="Pourquoi Kam Furie-du-fond était-il à la Stormwind Stockade plutôt qu’exécuté ?",a="Les autorités de Hurlevent ont gardé Deepfury en vie pour des raisons politiques. Les montagnards de Forgefer ont jugé cette retenue scandaleuse et ont exigé sa mort.",al={"pourquoi deepfury était emprisonné","pourquoi la prison"}},{q="Qui réclame la Tête de Furie-du-fond ?",a="Motley Garmason, en poste à Dun Modr, dans le nord des Paluns, réclame la tête. Lié par l’honneur à son poste aux côtés de Tresse-longue le Macabre, il envoie quelqu’un accomplir ce qu’il ne peut faire lui-même.",al={"qui prend la tête de deepfury","quête furie profonde"}},{q="Que permet le retour de la tête ?",a="Rapporter la tête tranchée de Deepfury à Dun Modr répond au grief des familles naines endeuillées. Cela venge le frère tué de Tresse-longue le Macabre et montre que les manœuvres politiques des humains n’effaceront pas les crimes contre Forgefer.",al={"pourquoi rapporter la tête de deepfury","résultat de furie profonde"}}},fx={["42407f6f"]={q="Qu'est-ce que la Tête de Furie-du-fond ?",a="C'est la tête coupée de Kam Furie-du-fond, un nain Sombrefer incarcéré au plus profond de la Stormwind Stockade. Vous la revendiquez comme preuve matérielle irréfutable que le conspirateur derrière l'assaut désastreux sur le Viaduc de Thandol a enfin fait face à la justice.",al={"tête de furie-du-fond","qu'est-ce que la tête de furie-du-fond","tête de kam furie-du-fond"}},ff6e9a29={q="D'où vient la Tête de Furie-du-fond ?",a="La tête est prise directement sur Kam Furie-du-fond lui-même dans les cellules de la prison sous Hurlevent. Bien qu'il ait été enfermé par les autorités humaines plutôt qu'exécuté, vous devez l'abattre dans sa cellule pour la récupérer.",al={"où obtenir la tête de furie-du-fond","qui lâche la tête de furie-du-fond","source de la tête de furie-du-fond"}}},fp="16,185,23.478.0,21.230.0,57.148.0,31.183.0,44.228.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="Tête de Gath'Ilzogg",s="Dans les Carmines, la chute de Gath'Ilzogg brise le commandement des Rochenoires qui assiègent le Donjon de Guet-de-pierre et soulage désespérément Comté-du-Lac.",h="Dans les Carmines, la chute de Gath'Ilzogg brise le commandement des Rochenoires qui assiègent le Donjon de...",kw={"rochenoire","gath'ilzogg","comté-du-lac","magistrat salomon","les carmines","guet-de-pierre","donjon de guet-de-pierre"},ang={["faction:Alliance"]="Alors que la capitale est distraite par des querelles internes, les volontaires de l'Alliance doivent défendre les Carmines et abattre eux-mêmes les chefs des Rochenoires.",["race:Human"]="Pour les habitants de Hurlevent, abattre Gath'Ilzogg venge le massacre de colons innocents et la chute humiliante du Donjon de Guet-de-pierre."},sec={{t="Un seigneur de guerre mis à prix",b="Gath'Ilzogg menait l'assaut des Rochenoires qui s'est emparé du Donjon de Guet-de-pierre et en a chassé les défenseurs. Depuis, la vallée subissait des raids incessants. Comté-du-Lac était au bord de la ruine, et Hurlevent envoyait presque aucun renfort militaire. Le Magistrat Salomon a donc mis le seigneur de guerre à prix.\n\nGath'Ilzogg est tombé dans les niveaux supérieurs fortifiés du donjon. Sa mort brise le commandement local des Rochenoires. Pour Comté-du-Lac, c'est le premier pas vers la reconquête du donjon au nom du royaume."}},faq={{q="Qui était Gath'Ilzogg ?",a="Gath'Ilzogg était un puissant seigneur de guerre orc des Rochenoires. Il a mené la conquête du Donjon de Guet-de-pierre et dirigé des raids contre les établissements des Carmines, poussant Comté-du-Lac au bord de l'effondrement.",al={"qui est gath'ilzogg","histoire de gath'ilzogg","boss de guet-de-pierre"}},{q="Où faut-il apporter la tête une fois récupérée ?",a="Vous apportez la tête au Magistrat Salomon, à l'hôtel de ville de Comté-du-Lac. Elle prouve que la prime affichée sur le tableau des avis de la ville a été réclamée.",al={"qui veut la tête","rendre la tête de gath'ilzogg","prime du magistrat salomon"}},{q="Que signifie la mort de Gath'Ilzogg pour Comté-du-Lac ?",a="La mort de Gath'Ilzogg prive les envahisseurs rochenoires de leur principal tacticien dans les Carmines. De nombreux orcs des Rochenoires restent retranchés dans tout Guet-de-pierre, mais la rupture de leur chaîne de commandement donne aux défenseurs locaux une chance de tenir la région.",al={"comté-du-lac est-il sauvé","importance de tuer gath'ilzogg"}},{q="Où Gath'Ilzogg a-t-il été trouvé ?",a="Gath'Ilzogg occupait les hauteurs du Donjon de Guet-de-pierre, au cœur de la fortification conquise. Ses gardes du corps et ses lieutenants étaient avec lui.",al={"où se trouve gath'ilzogg","emplacement du donjon de guet-de-pierre"}}},fx={a1bebb0c={q="Pourquoi le Magistrat Salomon veut-il la Tête de Gath'Ilzogg ?",a="Le Magistrat Salomon a affiché une forte prime exigeant une preuve matérielle de la mort du seigneur de guerre. Gath'Ilzogg était responsable du massacre d'humains innocents et de l'envahissement du Donjon de Guet-de-pierre. Voir sa tête livrée assure aux dirigeants de Comté-du-Lac que la menace immédiate a été brisée, offrant une justification et l'espoir de reprendre le donjon.",al={"pourquoi solomon veut-il la tête de gath'ilzogg","pourquoi apporter la tête de gath'ilzogg","prime sur la tête de gath'ilzogg"}},["0b5a65b1"]={q="Qu'est-ce que la Tête de Gath'Ilzogg ?",a="C'est la tête tranchée de Gath'Ilzogg, le seigneur de guerre orc Blackrock qui a dirigé l'assaut contre le Donjon de Guet-de-pierre et organisé les raids menaçant Comté-du-Lac. La trancher fournit une preuve matérielle irréfutable que le chef brutal orchestrant la campagne Blackrock dans les Carmines a enfin été éliminé.",al={"qu'est-ce que la tête de gath'ilzogg","tête de gath'ilzogg"}},ca6d6fe9={q="D'où vient la Tête de Gath'Ilzogg ?",a="La tête est prélevée directement sur Gath'Ilzogg après sa mort dans les hauteurs du Donjon de Guet-de-pierre. Retranché dans la forteresse qu'il avait conquise, le seigneur de guerre préparait de nouvelles attaques contre les habitants des Carmines, jusqu'à ce qu'un aventurier brave son bastion et emporte sa tête comme trophée.",al={"d'où vient la tête de gath'ilzogg","qui a pris la tête de gath'ilzogg","origine tête de gath'ilzogg"}}},fp="19,133,18.453.0,20.185.0,39.133.0,49.230.0,28.152.0"}
P.entries["item:head-of-grimson"] = {n="Tête de Grimson",s="À la Mine du gouffre d'Elem, la Tête de Grimson prouve que les Réprouvés se sont emparés de ses richesses. Dalar Tisselaube reçoit le trophée au Sépulcre, et les minerais de la mine peuvent approvisionner les campagnes de Varimathras.",h="À la Mine du gouffre d'Elem, la Tête de Grimson prouve que les Réprouvés se sont emparés de ses richesses.",kw={"arugal","dalar tisselaube","mine du gouffre d'elem","crimson the pale","tête de grimson","le sépulcre","forêt des pins-argentés","varimathras"},ang={["profession:Mining"]="La Mine du gouffre d'Elem est l'un des principaux gisements de la Forêt des Pins-Argentés. Son contremaître a disparu, et le minerai brut est désormais disponible pour les lignes de ravitaillement de la Horde.",["race:Undead"]="En tant que Réprouvé, vous vous emparer de la mine accomplissez les plans du haut commandement de Fossoyeuse. Cela prouve votre détermination à reprendre aux vestiges rendus fous les infrastructures vitales de Lordaeron."},sec={{t="Sécuriser la Mine du gouffre d'Elem",b="Les Darkstalkers, des éclaireurs réprouvés, ont repéré une menace grandissante dans les collines du sud-est. Les enchantements ténébreux de l'archimage Arugal ont corrompu les ouvriers de la Mine du gouffre d'Elem et rendu fou son contremaître, Grimson the Pale. Depuis le Sépulcre, Dalar Tisselaube a envoyé des champions tuer Grimson et rapporter sa tête tranchée. Ce trophée prouve que la mine est libérée de la magie dévoyée, laissant ses richesses souterraines aux forces de Varimathras."},{t="Un trophée pour le seigneur de l'effroi",b="La tête de Grimson marque la fin de son règne sur la Mine du gouffre d'Elem. Depuis la disparition du contremaître, les Réprouvés peuvent exploiter ses riches filons minéraux et fabriquer des armes et des armures avec le minerai. Ces ressources soutiennent leur avancée dans la Forêt des Pins-Argentés et les régions voisines de Lordaeron."}},faq={{q="Qui était Grimson the Pale ?",a="Grimson the Pale supervisait la Mine du gouffre d'Elem, dans les collines du sud-est de la Forêt des Pins-Argentés. La magie de l'ombre d'Arugal l'a corrompu, ainsi que les autres mineurs, jusqu'à l'intervention des Réprouvés.",al={"qui est crimson","histoire de crimson the pale","passé de crimson"}},{q="Pourquoi Dalar Tisselaube veut-elle la tête de Grimson ?",a="Dalar Tisselaube veut la tête de Grimson comme preuve de la mort du contremaître corrompu. Varimathras veut les minerais de la mine pour soutenir l'effort de guerre des Réprouvés, et la mort de Grimson brise la résistance des mineurs corrompus dans ses galeries.",al={"pourquoi dalar veut sa tête","utilité de la tête de crimson","pourquoi prendre sa tête"}},{q="Où se trouve la Mine du gouffre d'Elem ?",a="La Mine du gouffre d'Elem se trouve dans les collines au sud-est du Sépulcre, dans la Forêt des Pins-Argentés. Les Réprouvés disputent ses minerais aux vestiges corrompus par la magie d'Arugal.",al={"où se trouve la mine du gouffre d'elem","lieu où se trouve crimson","emplacement de la mine en forêt des pins-argentés"}},{q="Quel rôle Varimathras joue-t-il dans cette tâche ?",a="Varimathras dirige l'expansion des Réprouvés dans Lordaeron depuis Fossoyeuse. Les ressources de la mine servent ses projets en fournissant les matières premières nécessaires à son effort de guerre dans la Forêt des Pins-Argentés.",al={"rôle de varimathras","pourquoi varimathras veut la mine","varimathras dans la forêt des pins-argentés"}}},fx={["923cacb6"]={q="D'où vient la Tête de Grimson ?",a="Ce lugubre trophée provient directement de la Mine du gouffre d'Elem, située dans les collines au sud-est du Sépulcre. Il est tranché sur les épaules de Grimson le Pâle, le contremaître corrompu de la mine. Grimson a succombé aux magies sauvages s'échappant de Pyrewood et du Donjon d'Ombrecroc, tenant la mine jusqu'à ce qu'il soit abattu sur ordre de Dalar Tisselaube.",al={"où obtenir la tête de grimson","qui laisse tomber la tête de grimson","origine de la tête de grimson"}},f0354d96={q="Qu'est-ce que la Tête de Grimson ?",a="La Tête de Grimson est la tête coupée de Grimson le Pâle, prise comme preuve de sa mort. Autrefois un simple contremaître, Grimson a été déformé par la corruption magique noire libérée à travers les Pins-Argentés par l'archimage Arugal. Réclamer sa tête marque la fin de son commandement sur la Mine du gouffre d'Elem, sécurisant une preuve indéniable que la direction corrompue de la mine est tombée.",al={"tête de grimson","qu'est-ce que la tête de grimson"}}},fp="15,198,27.409.0,26.275.1,25.184.0,46.226.0,36.158.0,45.173.0"}
P.entries["item:head-of-kelris"] = {n="Tête de Kelris",s="Aux Profondeurs de Brassenoire, l’Aube d’argent cherche la tête de Kelris pour confirmer sa chute et la fin de ses sacrifices.",h="Aux Profondeurs de Brassenoire, l’Aube d’argent cherche la tête de Kelris pour confirmer sa chute et la fin...",kw={"aku'mai","aube d'argent","bashana totem-runique","profondeurs de brassenoire","blackfathom villainy","tête de kelris","selgorm","seigneur du crépuscule kelris"},ang={["faction:Alliance"]="En tant que champion de l’Alliance, vous apportez la tête de Kelris au Veilleur de l'aube Selgorm, à Darnassus. Vous vengez la profanation d’un ancien temple des Elfes de la nuit dédié à Elune.",["faction:Horde"]="En tant qu’aventurier de la Horde, vous présentez la tête de Kelris à Bashana Totem-runique, aux Pitons-du-Tonnerre. Vous gagnez la confiance du Cercle cénarien et prouvez votre dévouement à purifier Kalimdor de la corruption."},sec={{t="Un trophée de ruine",b="Dans les Profondeurs de Brassenoire, le Seigneur du crépuscule Kelris dirigeait des sacrifices à Aku'mai, serviteur monstrueux d’un dieu très ancien. Prendre sa tête marque la fin de son règne sur les cultistes du Marteau du crépuscule et leurs alliés nagas dans la caverne. La tête doit parvenir à la surface pour que les chefs sachent que ses cérémonies sanglantes ont pris fin."},{t="Une preuve pour l’Aube",b="Pendant des mois, l’Aube d’argent a cru Kelris mort ou disparu. Puis son influence est réapparue avec les ombres qui s’étendaient sur Kalimdor. Remise aux agents de Darnassus ou des Pitons-du-Tonnerre, sa tête permet de régler les primes en suspens et confirme que sa tentative de plonger le monde dans le chaos primordial a été stoppée."}},faq={{q="Qui était le Seigneur du crépuscule Kelris ?",a="Le Seigneur du crépuscule Kelris dirigeait la secte du Marteau du crépuscule dans les Profondeurs de Brassenoire. Allié aux nagas, il sacrifiait des innocents à Aku'mai, une hydre au service d’un dieu très ancien. Il cherchait le pouvoir des ténèbres et le chaos antique.",al={"qui est kelris","histoire de kelris","seigneur du crépuscule kelris"}},{q="Qui veut la tête de Kelris ?",a="Les champions de l’Alliance apportent la tête de Kelris au Veilleur de l'aube Selgorm, à Darnassus. Les aventuriers de la Horde la remettent à Bashana Totem-runique, à la Cime des Anciens, aux Pitons-du-Tonnerre. Selgorm sert l’Aube d’argent, tandis que Bashana appartient au Cercle cénarien.",al={"qui prend la tête de kelris","remettre la tête de kelris","à qui donner la tête de kelris"}},{q="Pourquoi l’Aube d’argent s’intéresse-t-elle à Kelris ?",a="L’Aube d’argent traque les menaces qui pèsent sur Azeroth. Kelris lui avait longtemps échappé. Son culte d’un dieu très ancien et ses sacrifices d’innocents menaçaient l’équilibre de Kalimdor.",al={"pourquoi l’aube d’argent s’intéresse à kelris","aube d’argent aux profondeurs de brassenoire"}},{q="Où trouve-t-on la tête ?",a="La tête de Kelris se trouve sur son cadavre, dans son sanctuaire au cœur des Profondeurs de Brassenoire. Les cavernes se situent sous la grève de Zoram, sur la côte d’Orneval.",al={"où trouver la tête de kelris","emplacement de la tête de kelris"}}},fx={c257c517={q="Qu'est-ce que la Tête de Kelris ?",a="Il s'agit de la tête tranchée du Seigneur du crépuscule Kelris, le chef des cultistes du Marteau du crépuscule qui s'étaient implantés au plus profond des ruines des Profondeurs de Brassenoire. Elle sert de preuve macabre et irréfutable que le sinistre maître du culte dans le Temple englouti a été terrassé et que ses rituels ont pris fin.",al={"tête de kelris","qu'est-ce que la tête de kelris","objet tête de kelris"}},["0e645b89"]={q="D'où provient la Tête de Kelris ?",a="La tête est prélevée directement sur le Seigneur du crépuscule Kelris dans les profondeurs des Profondeurs de Brassenoire, le long de la grève de Zoram. Vous devez vous frayer un chemin parmi ses cultistes fanatiques et ses serviteurs aberrants pour abattre le seigneur du crépuscule dans son sanctuaire intérieur avant de pouvoir la récupérer.",al={"où obtenir la tête de kelris","origine de la tête de kelris","comment obtenir la tête de kelris"}}},fp="14,116,16.305.0,18.291.0,29.202.0,29.236.0,43.156.0,27.139.0"}
P.entries["item:head-of-lathoric-the-black"] = {n="Head of Lathoric the Black",s="La tête de Lathoric the Black est une preuve rapportée de la Gorge des Vents brûlants à Thorius, à Forgefer. Elle est liée au danger qui entoure Obsidion.",h="La tête de Lathoric the Black est une preuve rapportée de la Gorge des Vents brûlants à Thorius, à Forgefer.",kw={"tête de lathoric the black","heart of obsidion","forgefer","lathoric","obsidion","gorge des vents brûlants","thorius"},ang={["race:Dwarf"]="En tant que nain, vous rapportez à Thorius, à Forgefer, une preuve du danger qui règne dans la Gorge des Vents brûlants."},sec={{t="Un gage sinistre",b="Thorius, à Forgefer, vous demande de lui rapporter la tête de Lathoric the Black depuis la Gorge des Vents brûlants. Cette tête prouve la mort de Lathoric et accompagne le Heart of Obsidion."}},faq={{q="De qui cette tête provient-elle ?",a="Cette tête provient de Lathoric the Black, que l’on trouve dans la Gorge des Vents brûlants.",al={"tête de lathoric"}},{q="Pourquoi Thorius la veut-il ?",a="Thorius vous demande de rapporter la tête à Forgefer comme preuve liée au danger qui entoure Obsidion.",al={"pourquoi la tête pour thorius","preuve pour thorius"}},{q="Où dois-je apporter la tête ?",a="Apportez la tête de Lathoric the Black à Thorius, à Forgefer.",al={"remettre la tête","où apporter la tête de lathoric"}},{q="Qu’est-ce qui accompagne la tête ?",a="Le Heart of Obsidion accompagne la tête jusqu’à Thorius.",al={"cœur avec la tête","objets d’obsidion"}}},fp="26,138,12.183.0,21.67.0,25.97.0,25.61.0,24.58.0"}
P.entries["item:head-of-nagaz"] = {n="Head of Nagaz",s="La tête de Nagaz prouve que les recherches du Magistrate Maleb dans les Montagnes d’Alterac ont atteint l’Argus Wake. Maleb craint que le groupe ne menace le Syndicat.",h="La tête de Nagaz prouve que les recherches du Magistrate Maleb dans les Montagnes d’Alterac ont atteint...",kw={"montagnes d’alterac","argus shadow mages","argus wake","conseil noir","tête de nagaz","nagaz","austrivage","strahnbrande","syndicat","les hauteurs"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance, vous portez les inquiétudes du Magistrate Maleb d’Austrivage jusqu’aux Hauteurs, où le Syndicat est le plus puissant."},sec={{t="Une preuve pour Maleb",b="Dans les Hauteurs, au nord de Strahnbrande, Nagaz dirige les Argus Shadow Mages mentionnés dans une lettre remise au Magistrate Maleb. Maleb soupçonne l’Argus Wake de s’être allié au Syndicat. La tête de Nagaz apporte à Austrivage la preuve que les émissaires ont été retrouvés."}},faq={{q="Qui était Nagaz ?",a="Nagaz était membre de l’Argus Wake et dirigeait des Argus Shadow Mages dans les Hauteurs.",al={"qui est nagaz","nagaz personnage"}},{q="Où trouver Nagaz ?",a="Nagaz se trouve dans les Hauteurs des Montagnes d’Alterac, au nord de Strahnbrande.",al={"lieu où se trouve nagaz","où trouver nagaz"}},{q="Pourquoi le Magistrate Maleb veut-il la tête de Nagaz ?",a="Le Magistrate Maleb veut prouver que Nagaz et les Argus Shadow Mages se trouvent dans les Hauteurs, où il craint que l’Argus Wake ne menace le Syndicat.",al={"pourquoi la tête de nagaz","maleb veut la tête"}},{q="Qu’est-ce que l’Argus Wake ?",a="L’Argus Wake est un groupe dont Nagaz, l’un des membres, a écrit au Syndicat. Maleb craint que son alliance avec le Syndicat ne constitue une menace.",al={"signification de l’argus wake","qui sont les argus wake"}},{q="Que font les Argus Shadow Mages ?",a="Les Argus Shadow Mages sont des émissaires de l’Argus Wake, retrouvés aux côtés de Nagaz dans les Hauteurs.",al={"mages argus","mages de l’ombre"}}},fp="13,155,15.256.0,14.79.0,23.70.0,46.144.0,23.131.0,38.89.0"}
P.entries["item:head-of-overseer-maltorius"] = {n="Head of Overseer Maltorius",s="Head of Overseer Maltorius est la preuve d’une prime dans la Gorge des Vents brûlants. Le capitaine de guet Lolo Longstriker vous demande de le rapporter du Chaudron.",h="Head of Overseer Maltorius est la preuve d’une prime dans la Gorge des Vents brûlants.",kw={"chaudron","head of overseer maltorius","lolo longstriker","maltorius","surveillant maltorius","gorge des vents brûlants","la fosse aux scories","confrérie du thorium"},ang={["race:Dwarf"]="En tant que nain, vous affrontez un commandant Sombrefer dans la Fosse aux scories, où son équipe travaille dans le Chaudron."},sec={{t="Une prime dans la Gorge",b="Le capitaine de guet Lolo Longstriker offre une prime pour Maltorius, un nain Sombrefer qui commande l’équipe de la Fosse aux scories, dans le Chaudron. L’ordre le désigne comme un agent renégat de la Confrérie du thorium. Sa tête tranchée est la preuve que Longstriker vous demande de rapporter des profondeurs de la Fosse aux scories."}},faq={{q="Qui était le surveillant Maltorius ?",a="Le surveillant Maltorius était un nain Sombrefer et le commandant de l’équipe de la Fosse aux scories, dans le Chaudron. La prime le désigne comme un agent renégat de la Confrérie du thorium.",al={"qui est maltorius"}},{q="Où trouver Maltorius ?",a="Maltorius se trouve au fond de la Fosse aux scories, dans le Chaudron, au cœur de la Gorge des Vents brûlants.",al={"emplacement de maltorius","où est maltorius"}},{q="Pourquoi Maltorius est-il recherché ?",a="L’ordre de prime désigne Maltorius comme un agent renégat de la Confrérie du thorium et ordonne sa mort.",al={"pourquoi maltorius est recherché","prime pour maltorius"}},{q="Qui veut la tête de Maltorius ?",a="Le capitaine de guet Lolo Longstriker offre la prime et vous demande de rapporter la tête de Maltorius comme preuve.",al={"qui a offert la prime","lolo maltorius"}},{q="Qu’est-ce que Head of Overseer Maltorius ?",a="C’est la tête tranchée de Maltorius, rapportée comme preuve de la prime dans la Gorge des Vents brûlants.",al={"tête de maltorius","objet tête"}}},fp="26,151,21.281.0,27.148.0,27.76.0,24.88.0,27.104.0,39.82.0"}
P.entries["item:head-of-targorr"] = {n="Tête de Targorr",s="Dans la Stormwind Stockade, des nobles ont suspendu l’exécution de Targorr. Cet orc a autrefois servi Gath'Ilzogg dans Les Carmines, et le Garde Berton, à Comté-du-Lac, exige maintenant une preuve de sa mort.",h="Dans la Stormwind Stockade, des nobles ont suspendu l’exécution de Targorr.",kw={"rochenoire","gath'ilzogg","garde berton","tête de targorr","comté-du-lac","les carmines","prison","targorr","targorr le terrifiant"},ang={["faction:Alliance"]="Pour les champions de l’Alliance qui défendent Les Carmines, la mort de Targorr venge les défenseurs massacrés de Comté-du-Lac et contourne la bureaucratie corrompue des nobles de Hurlevent.",["race:Human"]="En tant qu’humain, vous partagez peut-être la rancœur des soldats et des gardes de la ville envers Targorr, qui a torturé des soldats capturés du Royaume de Hurlevent pendant l’offensive du Clan Rochenoire."},sec={{t="Une exécution retardée",b="Targorr le Terrifiant était le bourreau redouté du seigneur de guerre Gath'Ilzogg, du Clan Rochenoire, dans Les Carmines. Avant sa capture, il a torturé et massacré des défenseurs du Royaume de Hurlevent. Condamné à mort dans la Stormwind Stockade, il a été épargné après l’intervention de nobles de Hurlevent. Des gardes comme Berton soupçonnent des manigances et de la corruption dans la capitale."},{t="Justice aux confins",b="Le Garde Berton craint que Targorr ne devienne un pion politique ou n’organise une évasion. Il engage donc un champion venu d’ailleurs pour entrer dans la prison en proie aux troubles et achever ce que les tribunaux ont reporté. Prendre la tête de Targorr permet de contourner un système judiciaire paralysé. Cela apporte aussi une conclusion aux familles endeuillées et aux défenseurs assiégés de Comté-du-Lac, qui ont souffert sous les lames du bourreau."}},faq={{q="Qui était Targorr le Terrifiant ?",a="Targorr le Terrifiant était un célèbre bourreau orc du Clan Rochenoire dans Les Carmines. Sous les ordres du seigneur de guerre Gath'Ilzogg, il torturait et exécutait les soldats et défenseurs de Hurlevent capturés.",al={"targorr","histoire de targorr","qui est targorr"}},{q="Pourquoi Targorr est-il gardé en vie dans la Prison ?",a="Des nobles de Hurlevent ont mystérieusement suspendu la condamnation à mort de Targorr par une intervention bureaucratique. Les gardes de Comté-du-Lac soupçonnent des manigances politiques et de la corruption, et craignent qu’on le garde comme monnaie d’échange.",al={"pourquoi ne pas exécuter targorr","sursis à l’exécution de targorr","procès dans la prison"}},{q="Qui veut la tête de Targorr ?",a="Le Garde Berton, posté devant l’Auberge de Comté-du-Lac, veut la tête tranchée de Targorr. Après avoir vu le carnage causé par Targorr dans Les Carmines, Berton veut la preuve que le bourreau ne pourra jamais être libéré.",al={"qui prend la tête de targorr","garde berton","remettre la tête de targorr"}},{q="Où trouve-t-on Targorr ?",a="Targorr le Terrifiant est détenu dans la Stormwind Stockade, derrière des barreaux de fer, dans les blocs de cellules centraux où les prisonniers se révoltent.",al={"emplacement de targorr","trouver targorr","où dans la prison"}}},fx={["1b8c229f"]={q="Qu'est-ce que la Tête de Targorr ?",a="Il s'agit de la tête tranchée de Targorr le Terrifiant, le célèbre bourreau suprême qui servait sous les ordres du seigneur de guerre de Rochenoire, Gath'Ilzogg. Targorr fut capturé et détenu dans la Stormwind Stockade, condamné à mort pour avoir torturé et exécuté de courageux défenseurs du royaume.",al={"qu'est-ce que la tête de targorr","infos sur la tête de targorr","description de la tête de targorr"}},["29061798"]={q="D'où vient la Tête de Targorr ?",a="La tête provient de Targorr le Terrifiant lui-même, enfermé au plus profond de la Stormwind Stockade. Après qu'un noble de Hurlevent a suspendu son exécution prévue, le Garde Berton charge un aventurier de prendre les choses en main, de se faufiler dans les cellules de la prison pour trancher la tête de cet orc impitoyable.",al={"d'où vient la tête de targorr","qui laisse tomber la tête de targorr","origine de la tête de targorr"}}},fp="15,187,19.344.0,16.356.0,26.183.0,43.205.0,25.202.0,23.118.0"}
P.entries["item:head-of-vancleef"] = {n="Tête de VanCleef",s="À la Colline des Sentinelles, la tête de VanCleef prouve à la Marche de l’Ouest que le chef défias est tombé. Rapportée des Mortemines, elle apporte à la People's Militia une victoire chèrement acquise.",h="À la Colline des Sentinelles, la tête de VanCleef prouve à la Marche de l’Ouest que le chef défias est tombé.",kw={"les mortemines","edwin vancleef","gryan roidemantel","tête de vancleef","people's militia","colline des sentinelles","marche de l’ouest"},ang={["class:Rogue"]="Edwin VanCleef fut l’un des maîtres renégats les plus meurtriers de l’histoire humaine. Sa mort met fin à une carrière sans égale dans l’ombre et le sabotage.",["faction:Alliance"]="Pour la People's Militia, la tête de VanCleef apporte une victoire libératrice. Elle révèle aussi combien la Maison des nobles de Hurlevent a peu agi pendant les heures les plus sombres de la Marche de l’Ouest."},sec={{t="La chute du maître",b="Les colons de la Marche de l’Ouest ont besoin de preuves que le danger est passé. Pendant des mois, Edwin VanCleef a dirigé la terreur de la Confrérie défias depuis le sanctuaire le plus profond des Mortemines. Des hors-la-loi armés, des ingénieurs gobelins et un colossal juggernaut de guerre le protégeaient là-bas.\n\nGryan Roidemantel dirige la People's Militia et exige une preuve matérielle avant de déclarer la campagne sûre. La tête tranchée de VanCleef est rapportée au grand jour. Elle assure aux défenseurs épuisés que l’architecte de leur ruine ne peut plus menacer la Marche de l’Ouest."},{t="Une sombre victoire",b="La mort de VanCleef répond à l’appel de Roidemantel pour le bien de la Marche de l’Ouest, mais la vue de sa tête pèse lourdement. Il fut jadis le maître bâtisseur vénéré qui reconstruisit Hurlevent après la Première Guerre. La trahison et les dettes impayées l’entraînèrent, lui et la Guilde des maçons, dans une rébellion de hors-la-loi.\n\nSa mort met fin à la campagne de la milice locale et révèle l’échec du royaume à régler ses troubles intérieurs. Des fermiers volontaires et des aventuriers étrangers ont dû rendre la haute justice."}},faq={{q="Qui veut la Tête de VanCleef ?",a="Gryan Roidemantel, capitaine de la People's Militia à la Colline des Sentinelles, dans la Marche de l’Ouest, veut la tête pour mettre un terme à la longue campagne contre la Confrérie défias.",al={"à qui remettre cet objet","qui prend la tête de vancleef","où va la tête de vancleef"}},{q="Pourquoi Gryan Roidemantel exige-t-il précisément sa tête ?",a="La Confrérie défias a tenu la Marche de l’Ouest sous son joug si longtemps que les rumeurs sur la mort de VanCleef ne convaincraient personne. Roidemantel a besoin d’une preuve matérielle pour rassurer les fermiers accablés et leur montrer que le combat de la milice n’a pas été vain.",al={"pourquoi prendre sa tête","pourquoi la tête de vancleef"}},{q="Où trouve-t-on la tête ?",a="La tête est prélevée sur Edwin VanCleef, à bord de son cuirassé de guerre secret, au bout des Mortemines, sous Ruisselune, dans le sud-ouest de la Marche de l’Ouest.",al={"où trouver la tête de vancleef","comment obtenir la tête de vancleef"}},{q="La prise de la tête de VanCleef met-elle fin à la Confrérie défias ?",a="Roidemantel voit la mort de VanCleef comme le début de la fin pour la confrérie. Des groupes dissidents, des bandits renégats et des sympathisants rôdent encore dans la Marche de l’Ouest, la Forêt d’Elwynn et au-delà.",al={"les défias sont-ils détruits","que deviennent les défias"}}},fx={["4a1d52aa"]={q="Qu'est-ce que la Tête de VanCleef ?",a="La Tête de VanCleef est la tête tranchée d'Edwin VanCleef, le cerveau derrière The Defias Brotherhood qui se cachait au fond des Mortemines. Elle sert de preuve macabre et indiscutable que le chef du soulèvement des hors-la-loi a finalement été abattu.",al={"qu'est-ce que la tête de vancleef","objet tête de vancleef","tête d'edwin vancleef"}}},fp="16,176,26.514.0,14.475.1,31.167.0,56.249.0,27.149.0,55.192.0"}
P.entries["item:heart-of-flame-quest-item"] = {n="Heart of Flame",s="Un Heart of Flame est l’un des matériaux dont Velarok Windblade a besoin dans la Gorge des Vents brûlants. Il l’aidera à préparer une torche pour attaquer les quatre tours de guet.",h="Un Heart of Flame est l’un des matériaux dont Velarok Windblade a besoin dans la Gorge des Vents brûlants.",kw={"golem oil","heart of flame","hearts of flame","gorge des vents brûlants","tours de guet","the flawless flame","torch of flawless flame","velarok windblade"},sec={{t="Pour la torche",b="Velarok Windblade a besoin de quatre Hearts of Flame et de quatre globes de Golem Oil dans la Gorge des Vents brûlants. Avec ces matériaux, il peut fabriquer une torche of flawless flame. Il compte mettre le feu aux quatre tours de guet et frapper avant que leurs défenseurs puissent réagir."}},faq={{q="À quoi sert un Heart of Flame ?",a="Velarok Windblade a besoin de quatre Hearts of Flame pour fabriquer une torche of flawless flame. Il compte s’en servir pour mettre le feu aux quatre tours de guet.",al={"utilité du heart of flame","pourquoi le heart of flame","cœur de flamme"}},{q="Qui veut le Heart of Flame ?",a="Velarok Windblade veut quatre Hearts of Flame, ainsi que quatre globes de Golem Oil, pour fabriquer la torche qu’il projette de créer.",al={"qui en a besoin","velarok et le heart of flame","qui veut le cœur de flamme"}},{q="Où trouver des Hearts of Flame ?",a="Les golems et les élémentaires de la Gorge des Vents brûlants sont les créatures que Velarok vous indique pour trouver des Hearts of Flame.",al={"emplacement du heart of flame","où trouver le cœur de flamme","hearts of flame dans la gorge des vents brûlants"}},{q="De combien de Hearts of Flame Velarok a-t-il besoin ?",a="Velarok a besoin de quatre Hearts of Flame pour fabriquer la torche of flawless flame.",al={"nombre de hearts of flame","combien de cœurs de flamme","besoin de quatre cœurs"}},{q="À quoi sert la torche of flawless flame ?",a="Velarok compte se servir de la torche pour mettre le feu à quatre tours de guet et ouvrir la voie à une offensive.",al={"torche of flawless flame","but de la torche","pourquoi quatre tours"}}},fp="14,156,13.244.0,29.137.0,29.115.0,32.103.0,43.71.0,40.102.0"}
P.entries["item:heart-of-isha-awak"] = {n="Cœur d'Isha Awak",s="Sur la Côte des marchands, au sud de Cabestan, des chasseurs traquent le cœur d'Isha Awak. Mahren Skyseer le veut comme preuve que le Deep Doom a été vaincu.",h="Sur la Côte des marchands, au sud de Cabestan, des chasseurs traquent le cœur d'Isha Awak.",kw={"deep doom","cœur d'isha awak","isha awak","mahren skyseer","la côte des marchands","cabestan","les tarides"},ang={["class:Hunter"]="En tant que chasseur, vous devez faire preuve de courage en traquant et en terrassant le Deep Doom sous les vagues de la Côte des marchands.",["race:Tauren"]="En tant que chasseur tauren, vous poursuivez Isha Awak en communion avec les prédateurs les plus féroces de la nature, sous la conduite de l'ancienne Mahren Skyseer."},sec={{t="Trophée du Deep Doom",b="Isha Awak rôde dans la mer au large de la Côte des marchands, au sud de Cabestan. Marins et habitants du littoral vénèrent et craignent tous l'immense batteur appelé Deep Doom. Il a tué de nombreux humains qui se sont aventurés sur le rivage.\n\nMahren Skyseer, une mystique tauren, voit en lui un prédateur honorable plutôt qu'une menace dépourvue de raison. Elle croit que son esprit féroce réside dans son cœur. Elle envoie donc de courageux chasseurs dans les flots pour vaincre Isha Awak sur son propre territoire et réclamer son cœur comme trophée et offrande spirituelle."}},faq={{q="Qu'est-ce que le Cœur d'Isha Awak ?",a="Le Cœur d'Isha Awak provient du batteur géant qui rôde dans les eaux au sud de Cabestan. Les chasseurs le réclament comme preuve d'avoir vaincu le Deep Doom pour Mahren Skyseer.",al={"cœur d'isha awak","qu'est-ce que ce cœur"}},{q="Qui veut le Cœur d'Isha Awak ?",a="Mahren Skyseer, une voyante tauren installée le long de la Côte des marchands au sud de Cabestan, veut que les chasseurs rapportent le cœur. Elle cherche à honorer la puissance de la bête et à s'approprier son esprit.",al={"qui prend le cœur","à qui donner le cœur","mahren skyseer"}},{q="Où trouve-t-on Isha Awak ?",a="Isha Awak vit dans l'océan, au large de la Côte des marchands, dans les Tarides orientales, au sud de Cabestan.",al={"emplacement d'isha awak","où se trouve isha awak","où trouver isha awak"}},{q="Pourquoi Mahren Skyseer veut-elle le cœur ?",a="Mahren Skyseer considère Isha Awak comme un chasseur honorable et un adversaire digne. En tuant la bête et en tenant son cœur, le chasseur accueille en lui l'esprit de la créature marine.",al={"pourquoi tuer isha awak","pourquoi mahren veut le cœur"}}},fx={["1c3e01c4"]={q="D'où provient le Cœur d'Isha Awak ?",a="Le cœur n'est pas un artefact fabriqué, mais un organe prélevé directement sur Isha Awak, la puissante bête marine connue sous le nom de \"Deep Doom\". La créature hante les eaux au large de la côte des Tarides, au sud de Cabestan, crainte par les humains locaux dont elle a dévoré les proches. Terrasser ce prédateur primitif des mers et lui arracher le cœur est le seul moyen de l'obtenir.",al={"origine du cœur d'isha awak","d'où vient le cœur d'isha awak","qui a créé le cœur d'isha awak"}}},fp="18,147,23.489.0,31.174.0,33.189.0,25.94.0,39.171.0"}
P.entries["item:heart-of-mokk"] = {n="Heart of Mokk",s="Le Heart of Mokk est prélevé sur Mokk the Savage, au cap Strangleronce. Fin Fizracket le cherche comme remède à la fièvre de Strangleronce.",h="Le Heart of Mokk est prélevé sur Mokk the Savage, au cap Strangleronce.",kw={"le cap strangleronce","fin fizracket","heart of mokk","mokk the savage","fièvre de strangleronce","sorcier-docteur unbagwa"},sec={{t="Un remède contre la fièvre",b="Fin Fizracket est frappé d'une fièvre mortelle à Baie-du-Butin et pense que seul le cœur de Mokk the Savage peut le guérir. Le Sorcier-docteur Unbagwa, caché dans une grotte du cap méridional, peut invoquer la bête blanche insaisissable. Le cœur est ce qu'il faut à Fin pour retrouver ses forces."}},faq={{q="Qu'est-ce que le Heart of Mokk ?",a="Le Heart of Mokk est le cœur de Mokk the Savage, une bête blanche insaisissable au cap Strangleronce.",al={"cœur de mokk","objet cœur","qu'est-ce que le heart of mokk"}},{q="Qui a besoin du Heart of Mokk ?",a="Fin Fizracket, à Baie-du-Butin, cherche le Heart of Mokk comme remède à la fièvre de Strangleronce.",al={"qui le veut","cœur de fin fizracket","qui a besoin de mokk"}},{q="D'où vient le Heart of Mokk ?",a="Le Heart of Mokk provient de Mokk the Savage, au cap Strangleronce.",al={"où trouver le cœur","emplacement de mokk","trouver le heart of mokk"}},{q="Comment invoquer Mokk ?",a="Le Sorcier-docteur Unbagwa, dans une grotte cachée au sud du cap, peut invoquer Mokk the Savage.",al={"invoquer mokk","où est unbagwa","sorcier-docteur mokk"}}},fp="13,131,14.263.0,26.99.0,28.85.0,39.70.0,25.88.0"}
P.entries["item:heart-of-obsidion"] = {n="Heart of Obsidion",s="Le Heart of Obsidion est la preuve dont Thorius a besoin dans la Gorge des Vents brûlants. Il témoigne du danger qui menace encore ces terres.",h="Le Heart of Obsidion est la preuve dont Thorius a besoin dans la Gorge des Vents brûlants.",kw={"heart of obsidion","forgefer","lathoric the black","obsidion","old gods","ragnaros","gorge des vents brûlants","thorius"},ang={["race:Dwarf"]="En tant que nain, Thorius est profondément touché par la trahison de Forgefer. Il craint que l’influence des Old Gods menace son peuple."},sec={{t="Un cœur rapporté",b="Thorius, à Forgefer, demande le Heart of Obsidion après l’avertissement de Dorius. Le cœur, pris à Obsidion dans la Gorge des Vents brûlants, est rapporté avec le Head of Lathoric the Black. Thorius doit voir les deux pour croire ce qui s’est passé."},{t="Le chagrin de Thorius",b="En voyant le Heart of Obsidion et la tête de Lathoric, Thorius blêmit. Il apprend que son propre frère a tendu le piège et trahi Forgefer. Thorius craint que l’influence des Old Gods reste forte dans ces terres et que Ragnaros puisse corrompre même les nobles et les honorables."}},faq={{q="Qu’est-ce que le Heart of Obsidion ?",a="Le Heart of Obsidion est un trophée pris à Obsidion dans la Gorge des Vents brûlants.",al={"heart of obsidion","cœur d’obsidion"}},{q="Qui demande le Heart of Obsidion ?",a="Thorius, à Forgefer, demande le Heart of Obsidion ainsi que le Head of Lathoric the Black.",al={"qui veut le cœur d’obsidion","cœur de thorius"}},{q="Pourquoi Thorius veut-il le cœur ?",a="Thorius a besoin du Heart of Obsidion et du Head of Lathoric the Black comme preuves de la trahison.",al={"pourquoi le cœur","quelle preuve thorius demande"}},{q="Que prouve le cœur ?",a="Avec la tête de Lathoric, le cœur prouve à Thorius que l’avertissement au sujet d’un piège était fondé.",al={"preuve du cœur","qu’est-il arrivé à thorius"}}},fp="17,117,16.245.0,15.273.1,30.71.0,32.93.0,32.96.1,26.94.1"}
P.entries["item:heartswood"] = {n="Coeur du bois",s="Au nord-ouest d’Orneval, le Coeur du bois provient d’un arbre enraciné dans les Ruines d’Ordil'Aran. L’arbre a poussé là où deux amants d’autrefois ont péri, et son bois attire les succubes lorsque des démonistes cherchent à les invoquer.",h="Au nord-ouest d’Orneval, le Coeur du bois provient d’un arbre enraciné dans les Ruines d’Ordil'Aran.",kw={"anathera","orneval","gakin le tisse-noir","coeur du bois","latherion","ordil'aran","succube"},ang={["class:Warlock"]="Pour les démonistes de l’Alliance, obtenir le Coeur du bois est un rite de passage dirigé par Gakin le Tisse-noir. Sa résonance fournit l’appât émotionnel nécessaire pour contraindre et asservir une succube servante.",["race:NightElf"]="En tant qu’elfe de la nuit, vous pouvez voir cet arbre comme un mémorial sacré dédié à ceux qui sont tombés durant la guerre des Anciens. Les démonistes et les cultistes qui coupent son bois offensent la mémoire des ancêtres disparus."},sec={{t="Un monument au dévouement",b="Parmi les pierres elfiques des Ruines d’Ordil'Aran, au nord-ouest d’Orneval, un arbre singulier a pris racine. La légende raconte qu’Anathera et Latherion, deux amants, sont tombés côte à côte là-bas durant la guerre des Anciens, il y a des milliers d’années. L’arbre du Coeur du bois a poussé sur la terre où ils sont morts. Aujourd’hui encore, le bois qui en est tiré porte le souvenir de leur dévouement. Ceux qui étudient les liens émotionnels et spirituels s’y intéressent."},{t="Un outil d’asservissement",b="Le Coeur du bois attire l’attention des succubes, des démons attirés par la passion, le désir et l’exploitation émotionnelle. À Hurlevent, les démonistes humains et gnomes qui étudient auprès de Gakin le Tisse-noir recherchent ce bois rare pour en faire un leurre rituel. Sa résonance avec le sacrifice des amants peut servir d’appât pour attirer une succube à travers le Néant et la faire venir dans un cercle d’invocation. Là, le praticien peut la lier à sa volonté."}},faq={{q="Qu’est-ce que le Coeur du bois ?",a="Le Coeur du bois provient d’un arbre qui a poussé dans les Ruines d’Ordil'Aran, en Orneval, là où deux amants elfes de la nuit ont péri ensemble durant la guerre des Anciens.",al={"arbre du coeur du bois","qu’est-ce que le coeur du bois","histoire du coeur du bois"}},{q="Qui étaient Anathera et Latherion ?",a="Anathera et Latherion étaient des amants qui ont combattu côte à côte durant la guerre des Anciens. Ils sont tombés au combat, et leur dernière étreinte a nourri la terre où l’arbre du Coeur du bois a poussé, signe durable de leur dévouement.",al={"anathera et latherion","amants du coeur du bois","qui est mort au coeur du bois"}},{q="Pourquoi les démonistes ont-ils besoin du Coeur du bois ?",a="Les succubes sont des démons attirés par le désir et la manipulation émotionnelle. Les démonistes se servent de la résonance du Coeur du bois avec un amour éternel comme appât pour attirer une succube dans le monde physique et l’invoquer.",al={"pourquoi les démonistes veulent le coeur du bois","succube du coeur du bois","utilité du coeur du bois"}},{q="Où trouve-t-on le Coeur du bois ?",a="Le Coeur du bois provient des Ruines d’Ordil'Aran, dans la forêt du nord-ouest d’Orneval, près de la frontière de Sombrivage.",al={"emplacement du coeur du bois","où se trouve le coeur du bois","coeur du bois ruines d’ordil'aran"}}},fx={["61f35e8f"]={q="D'où vient le Bois-cœur et qui l'a créé ?",a="Le Bois-cœur n'est pas façonné par des mains mortelles, mais récolté sur un arbre solitaire qui a poussé dans les ruines des Ruines d'Ordil'Aran, au nord-ouest de l'Orneval. Lors de la guerre ancestrale catastrophique il y a des millénaires, deux amants nommés Anathera et Latherion tombèrent ensemble au combat. Là où ils rendirent leur dernier souffle, l'arbre prit racine et grandit, se dressant comme un monument vivant à leur dévotion éternelle.",al={"origine du bois-cœur","d'où vient le bois-cœur","comment le bois-cœur a-t-il été créé"}}},fp="10,201,22.420.0,21.390.1,19.157.0,32.223.0,32.184.0,30.113.0"}
P.entries["item:heartswood-core"] = {n="Noyau du cœur du bois",s="Sous Hurlevent, les démonistes se servent du Noyau du cœur du bois pour invoquer une succube. Gakin le Tisse-noir fournit ce focalisateur enchanté, façonné dans le bois d’un arbre ancien, pour ouvrir un passage vers le Néant distordu.",h="Sous Hurlevent, les démonistes se servent du Noyau du cœur du bois pour invoquer une succube.",kw={"gakin le tisse-noir","noyau du cœur du bois","slaughtered lamb","hurlevent","succube","cercle d’invocation","the binding","démoniste"},ang={["class:Warlock"]="En tant que démoniste de l’Alliance, vous vous servez du Noyau du cœur du bois pour invoquer et maîtriser votre première succube pendant votre formation."},sec={{t="Un focalisateur vers le Néant",b="Sous l’auberge du Slaughtered Lamb, dans le Quartier des Mages de Hurlevent, les démonistes accomplissent des rites à l’abri des regards de la garde de la cité. Le Noyau du cœur du bois canalise la magie qui amorce un rituel d’asservissement. Façonné dans le bois d’un arbre ancien, il conserve assez de pouvoir résiduel pour percer le voile entre les mondes. Dans un cercle d’invocation consacré, un novice concentre ses arts sombres à travers le noyau et ouvre un passage vers le Néant distordu. Une succube franchit la brèche."},{t="L’épreuve de l’asservissement",b="Un démoniste qui invoque un démon doit prouver sa domination sur sa nature rusée et séductrice avant de pouvoir le contrôler. Gakin confie le Noyau du cœur du bois aux praticiens prometteurs afin qu’ils affrontent le démon invoqué en combat. Les succubes exploitent les faiblesses et peuvent submerger les esprits fragiles. Cette rencontre est un rite de passage mortel. Le démoniste en herbe doit soumettre le démon et rapporter le noyau épuisé à Gakin, prouvant ainsi que sa volonté est assez forte pour asservir définitivement son serviteur."}},faq={{q="À quoi sert le Noyau du cœur du bois ?",a="Les démonistes se servent du Noyau du cœur du bois dans le cercle d’invocation sous le Slaughtered Lamb pour ouvrir un passage vers le Néant distordu. Une succube entre dans notre monde, et vous devez la combattre et l’asservir.",al={"utilité du noyau du cœur du bois","utilisation du noyau du cœur du bois","but du noyau du cœur du bois"}},{q="Qui fournit le Noyau du cœur du bois ?",a="Gakin le Tisse-noir fournit le Noyau du cœur du bois. C’est un maître démoniste qui forme les novices dans les catacombes cachées sous le Slaughtered Lamb, dans le Quartier des Mages de Hurlevent.",al={"où obtenir le noyau du cœur du bois","qui donne le noyau du cœur du bois"}},{q="Où faut-il utiliser le noyau ?",a="Utilisez le Noyau du cœur du bois dans le cercle d’invocation des cryptes sous le Slaughtered Lamb, profondément enfouies sous les rues de Hurlevent.",al={"emplacement du noyau du cœur du bois","où invoquer une succube"}},{q="Que se passe-t-il après le rituel ?",a="Après avoir invoqué la succube, vainquez-la au combat et renvoyez-la dans le Néant. Puis rapportez le Noyau du cœur du bois à Gakin le Tisse-noir pour apprendre à commander le démon à volonté.",al={"que faire après l’invocation","rendre le noyau du cœur du bois"}}},fx={["34d5c17e"]={q="Qu'est-ce que le Noyau du cœur du bois ?",a="Le Noyau du cœur du bois est une relique occulte enchantée conçue spécifiquement pour les rituels d'invocation. Préparé par des pratiquants de magie noire, il agit comme un catalyseur magique assez puissant pour percer le voile entre les mondes et attirer une succube depuis le Néant distordu vers un cercle d'invocation.",al={"lore du noyau du cœur du bois","qu'est-ce que le noyau du cœur du bois","objet cœur du bois"}},a2df89b9={q="D'où vient le Noyau du cœur du bois et qui l'a fabriqué ?",a="Le noyau est préparé en utilisant du Cœur du bois brut récupéré dans les ruines d'Ordil'Aran à Orneval, façonné et imprégné de pouvoir sous la direction de Gakin le Tisse-noir. Gakin confie la relique terminée aux démonistes prometteurs qui étudient sous The Slaughtered Lamb à Hurlevent.",al={"qui a fabriqué le noyau du cœur du bois","origine du noyau du cœur du bois","comment le noyau du cœur du bois a été fabriqué"}},cef9a99d={q="Pourquoi Gakin veut-il que le Noyau du cœur du bois soit utilisé ?",a="Un démoniste cherchant à lier une succube a besoin d'un ancrage d'une immense puissance pour ouvrir un passage vers le vide. Sans le Noyau du cœur du bois, vous ne pouvez pas terminer le sortilège d'invocation nécessaire pour manifester le démon et soumettre son esprit traître.",al={"pourquoi utiliser le noyau du cœur du bois","lore de l'utilité du noyau du cœur du bois","pourquoi vouloir le noyau du cœur du bois"}}},fp="15,202,22.443.0,20.458.1,37.194.0,33.176.0,28.125.0,42.179.0"}
P.entries["item:heavy-leaden-collection-phial"] = {n="Flasque plombée lourde",s="À Kharanos, Ozzie Virevolt propose la Flasque plombée lourde pour ses recherches en décontamination. Elle doit recueillir les émanations irradiées instables des mutants au cœur de Gnomeregan et les contenir.",h="À Kharanos, Ozzie Virevolt propose la Flasque plombée lourde pour ses recherches en décontamination.",kw={"gnomeregan","hall of gears","flasque plombée lourde","ozzie virevolt","flasque","retombées radioactives","the only cure is more green glow"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous pouvez utiliser la flasque pour recueillir des retombées volatiles. Même avec un récipient adapté, plusieurs tentatives peuvent être nécessaires pour obtenir un échantillon.",["race:Gnome"]="En tant que gnome, chaque portion de retombées volatiles contenue dans la flasque vous rapproche de la reconquête de Gnomeregan et de la compréhension de la folie chimique qui vous a pris votre foyer."},sec={{t="Un récipient blindé",b="La Flasque plombée lourde recueille des résidus volatils sur les créatures vivantes et irradiées de Gnomeregan. Il est difficile de contenir les retombées. Plusieurs tentatives peuvent être nécessaires pour obtenir un échantillon adéquat."},{t="À la recherche d’un remède",b="Ozzie Virevolt fournit la flasque pour ses recherches visant à inverser les terribles mutations qui frappent les gnomes lépreux. Les échantillons antérieurs prélevés sur les troggs de surface étaient trop faibles pour une analyse chimique utile.\n\nAvec la flasque plombée, les chercheurs espèrent recueillir des échantillons sur des bêtes virulentes, notamment des gelées irradiées et des rôdeurs dans le Hall of Gears. Ils cherchent les éléments actifs dans les retombées toxiques de la ville, puis espèrent mettre au point un antidote efficace."}},faq={{q="À quoi sert la Flasque plombée lourde ?",a="La flasque siphonne les émanations radioactives concentrées des créatures vivantes et irradiées de Gnomeregan. À Kharanos, les chercheurs utilisent les échantillons dans des essais de décontamination.",al={"à quoi sert cette flasque","utilité de la flasque","qu’est-ce qu’une flasque plombée"}},{q="Qui fournit la Flasque plombée lourde ?",a="Ozzie Virevolt, un chercheur gnome de Kharanos, à Dun Morogh, fournit la flasque pour ses recherches visant à guérir les gnomes lépreux irradiés et affligés.",al={"qui fournit la flasque","où obtenir la flasque","personne qui donne la quête de la flasque"}},{q="Pourquoi la flasque est-elle en plomb lourd ?",a="La flasque est décrite comme lourde et plombée, mais sa fabrication précise n’est pas expliquée. Ozzie prévient qu’il est difficile de contenir les retombées radioactives et que l’échantillon se décomposera rapidement.",al={"pourquoi une flasque en plomb","pourquoi du plomb lourd"}},{q="Quelles créatures faut-il échantillonner avec la flasque ?",a="La flasque doit être utilisée sur des horreurs vivantes et luminescentes au cœur de Gnomeregan. Cela comprend des gelées irradiées, des rôdeurs et des horreurs qui rôdent dans les niveaux inférieurs du Hall of Gears.",al={"sur quoi l’utiliser","créatures à cibler","quels monstres brillent"}}},fx={ca9f55e0={q="Pourquoi Ozzie Virevolt veut-il que la Flasque plombée lourde lui soit rapportée ?",a="Ozzie Virevolt a besoin que la flasque et un échantillon de matière radioactive à haut potentiel soient rapportés à son atelier de Kharanos. Ayant précédemment testé des spécimens de troggs plus faibles et les ayant jugés insuffisants, il a besoin de radiations pures et non corrompues provenant directement des créatures à l'intérieur de Gnomeregan pour faire avancer ses expériences visant à soigner les gnomes lépreux affligés.",al={"pourquoi rendre la flasque plombée lourde","pourquoi ozzie veut-il la flasque","pourquoi la flasque de collection est-elle nécessaire"}}},fp="29,212,17.202.0,17.442.0,51.172.0,47.150.0,36.193.0,47.175.0"}
P.entries["item:hezrul-s-head"] = {n="Tête d'Hezrul",s="À l’Oasis luxuriante, Hezrul Bloodmark commande les centaures Kolkar des Tarides. Sa tête doit être remise à Regthar Deathgate, à l’ouest de la Croisée, pour prouver que leur chef est tombé.",h="À l’Oasis luxuriante, Hezrul Bloodmark commande les centaures Kolkar des Tarides.",kw={"bloodmark","centaure","la croisée","deathgate","hezrul","kolkar","lushwater","regthar"},ang={["faction:Horde"]="En tant que membre de la Horde, réclamer la tête du chef Kolkar garantit des droits vitaux sur l’eau de l’Oasis luxuriante et protège les voyageurs de la Horde qui traversent les Tarides.",["race:Orc"]="En tant qu’orc, vous pouvez voir les Kolkar comme des vauriens indisciplinés, dont la fureur cède face à la discipline guerrière orque. Pour Regthar, ce trophée prouve l’honneur martial."},sec={{t="La décapitation des Kolkar",b="Hezrul Bloodmark dirige son clan Kolkar depuis l’Oasis luxuriante, au sud de la Croisée. Les centaures contrôlent les oasis des Tarides et menacent les voies de ravitaillement de la Horde ainsi que ses jeunes colonies.\n\nRegthar Deathgate est un vétéran orc chargé de sécuriser les terres à l’ouest de la Croisée. Il voit chez les Kolkar une rage féroce, mais peu de discipline. Il exige donc la tête tranchée d’Hezrul pour briser le commandement du clan et disperser les combattants survivants, affaiblissant ainsi leurs attaques contre la Horde."}},faq={{q="À qui appartient cette tête ?",a="Hezrul Bloodmark dirige le clan des centaures Kolkar dans le centre des Tarides.",al={"qui est hezrul","identité d’hezrul","à qui est cette tête"}},{q="Où trouver Hezrul Bloodmark ?",a="Hezrul mène sa bande autour de l’Oasis luxuriante, au sud de la Croisée, dans les Tarides.",al={"emplacement d’hezrul","où est hezrul","trouver hezrul"}},{q="Qui veut la Tête d’Hezrul ?",a="Regthar Deathgate, un orc installé dans un avant-poste militaire sur la route à l’ouest de la Croisée, veut la Tête d’Hezrul comme preuve de la défaite d’Hezrul.",al={"remettre la tête d’hezrul","qui prend la tête d’hezrul","regthar deathgate"}},{q="Pourquoi la Horde exige-t-elle sa tête au lieu de simplement le chasser ?",a="La Horde doit être certaine de la mort d’Hezrul. Les centaures sont instables et enclins aux luttes intestines. La disparition de leur chef brise leur commandement et réduit la menace qu’ils font peser sur la Croisée.",al={"pourquoi tuer hezrul","pourquoi prendre sa tête","menace des centaures"}}},fx={["67b3da29"]={q="D'où vient la Tête d'Hezrul ?",a="Cette tête tranchée provient de Hezrul Bloodmark, un chef centaure rusé et brutal qui se trouve à l'Oasis luxuriante, au sud de la Croisée. Hezrul dirige la tribu Kolkar dans la région, orchestrant ses attaques contre les avant-postes de la Horde et les villages voisins jusqu'à sa mort.",al={"origine de la tête d'hezrul","d'où vient la tête d'hezrul","de qui provient la tête d'hezrul"}}},fp="13,177,23.465.0,29.70.0,32.85.0,24.143.0,69.186.0"}
P.entries["item:high-potency-radioactive-fallout"] = {n="Matière radioactive à haut potentiel",s="Dans les profondeurs de Gnomeregan, des chercheurs étudient des retombées radioactives concentrées. Ils espèrent comprendre comment la boue a affligé les gnomes lépreux et trouver un remède.",h="Dans les profondeurs de Gnomeregan, des chercheurs étudient des retombées radioactives concentrées.",kw={"gnomeregan","lueur verte","hall of gears","matière radioactive à haut potentiel","limace irradiée","gnome lépreux","ozzie virevolt"},ang={["profession:Engineering"]="Les retombées volatiles se dégradent rapidement. Transportez-les dans des fioles en plomb spécialement conçues pour vous protéger de l'exposition.",["race:Gnome"]="Chaque échantillon de retombées toxiques provenant des profondeurs de Gnomeregan apporte un fragile espoir d'inverser la mutation qui a déchiré votre peuple lors de la chute de la ville."},sec={{t="Directement à la source",b="Au fond du Hall of Gears, des horreurs irradiées, des rôdeurs et des limaces parcourent les niveaux les plus bas de Gnomeregan. Les chercheurs installés à l'extérieur de la capitale déchue ont besoin de retombées prélevées sur ces créatures vivantes. Les échantillons grattés sur les charognards contaminés à l'extérieur sont trop faibles pour leurs travaux.\n\nLa boue se dégrade rapidement. Elle doit être scellée dans une fiole en plomb et parvenir aux chercheurs avant de perdre son pouvoir."},{t="À la recherche d'un remède",b="Ozzie Virevolt et ses collègues cherchent un remède pour les gnomes lépreux. Ils pensent que les secrets de la boue irradiée pourraient leur montrer la voie. Lors de l'invasion des troggs, des émanations toxiques ont déformé ces survivants et les ont rendus fous.\n\nLes gnomes lépreux restent prisonniers d'un cauchemar vivant. Pour les chercheurs, les expéditions dangereuses dans les ruines valent le risque."}},faq={{q="D'où viennent ces retombées radioactives ?",a="Les retombées proviennent de créatures vivantes irradiées dans les niveaux inférieurs du Hall of Gears de Gnomeregan, notamment des limaces, des horreurs et des rôdeurs.",al={"où trouver les retombées","lieu des retombées","source des retombées radioactives"}},{q="Pourquoi cet échantillon est-il nécessaire ?",a="Les chercheurs gnomes, dont Ozzie Virevolt, ont besoin d'un échantillon concentré des radiations de Gnomeregan pour étudier l'affliction et chercher un remède pour les gnomes lépreux.",al={"qui veut les retombées","but des retombées","pourquoi recueillir les retombées"}},{q="Pourquoi faut-il le manipuler avec tant de précautions ?",a="Les retombées se dégradent rapidement et perdent leur pouvoir. Il faut les transporter dans une fiole en plomb et les rapporter aux chercheurs avant qu'elles ne se dégradent.",al={"dégradation des retombées","pourquoi une fiole en plomb","retombées instables"}},{q="Pourquoi les résidus des troggs ne convenaient-ils pas ?",a="Les résidus des troggs à l'extérieur de la ville étaient trop faibles et impurs pour les analyses. Les chercheurs ont besoin de retombées brutes et concentrées provenant de créatures au cœur de Gnomeregan irradiée.",al={"pourquoi pas la lueur des troggs","radiations des troggs et retombées","échec du précédent échantillon"}}},fx={["30a827ed"]={q="Qu'est-ce que la Matière radioactive à haut potentiel ?",a="Ces retombées sont un résidu concentré et volatil récolté directement sur les vases, horreurs et rôdeurs profondément irradiés qui s'agitent dans les salles en ruine de Gnomeregan. Hautement instable et brillant d'une énergie toxique virulente, il représente le contaminant brut persistant au cœur même du désastre.",al={"qu'est-ce que la matière radioactive à haut potentiel","lore de la matière radioactive","qu'est-ce que cette matière radioactive"}}},fp="32,146,21.383.0,24.362.0,46.145.0,26.163.0,36.138.0,45.166.0"}
P.entries["item:highborne-relic-classic"] = {n="Relique de bien-Né",s="À Sombrivage, les esprits s’agrippent encore aux Highborne Relics, que les érudits elfes de la nuit cherchent à détruire. Leur magie en sommeil pourrait causer d’autres ravages.",h="À Sombrivage, les esprits s’agrippent encore aux Highborne Relics, que les érudits elfes de la nuit cherchent...",kw={"ameth'aran","arcanique","sombrivage","highborne","relique de bien-né","sentinelles","thundris windweaver"},ang={["class:Mage"]="En tant que mage, vous pourriez trouver fascinant le savoir-faire arcanique des reliques. Les autorités locales des elfes de la nuit exigent leur destruction.",["race:NightElf"]="Pour les elfes de la nuit, ces reliques rappellent l’arrogance arcanique qui a déchiré leur ancienne civilisation."},sec={{t="Vestiges de la Fracture",b="Il y a dix mille ans, la caste des Highborne a dévasté l’ancien Kalimdor par sa magie arcanique imprudente. Leurs domaines sont en ruines à travers Sombrivage. À Ameth'Aran, des apparitions gémissantes errent parmi les colonnes effondrées, toujours agrippées aux instruments de leur ancienne sorcellerie. La souillure arcanique lie les reliques à ces esprits, qui refusent de lâcher les objets liés à leur perte."},{t="Purifier la souillure arcanique",b="Après la Grande Fracture, la plupart des elfes de la nuit ont renoncé à la magie arcanique. Leurs érudits considèrent désormais les reliques comme un grave danger. Les rapports des Sentinelles sont parvenus à Thundris Windweaver, à Auberdine, qui envoie des voyageurs arracher les reliques aux esprits maudits. Une fois rassemblées, les reliques sont détruites afin d’empêcher que les anciens méfaits et les erreurs catastrophiques des Highborne ne se reproduisent."}},faq={{q="D’où viennent les Highborne Relics ?",a="Dans le sud de Sombrivage, les esprits qui hantent Ameth'Aran portent des Highborne Relics parmi les ruines antiques à l’est de la route principale. Les fantômes gémissants s’y agrippent au milieu des pierres.",al={"où trouver les highborne relics","qui donne les highborne relics","emplacement des reliques"}},{q="Pourquoi Thundris Windweaver veut-il ces reliques ?",a="Thundris Windweaver craint la corruption arcanique qui imprègne les reliques. Il les rassemble pour les détruire et empêcher quiconque de ranimer la dangereuse sorcellerie des Highborne.",al={"pourquoi récupérer les reliques","que deviennent les reliques","objectif de windweaver"}},{q="Pourquoi les esprits des Highborne hantent-ils encore Ameth'Aran ?",a="Ces esprits sont d’anciens nobles Highborne qui ont péri lorsque le monde s’est brisé, il y a dix mille ans. Leurs âmes tourmentées restent liées aux ruines de leur ancienne cité, maudites par leur orgueil et leur attachement à la magie arcanique.",al={"pourquoi les fantômes hantent ameth'aran","qui sont les highborne maudits","pourquoi des fantômes à sombrivage"}},{q="Peut-on utiliser les Highborne Relics sans danger ?",a="Non. Les elfes de la nuit considèrent que les reliques sont souillées par les pratiques arcaniques débridées qui ont déclenché la Grande Fracture. Leur magie en sommeil est dangereuse, aussi les érudits exigent leur destruction plutôt que leur étude.",al={"peut-on utiliser les highborne relics","les reliques sont-elles dangereuses"}}},fx={["9b193d00"]={q="Qu'est-ce qu'une Relique de bien-Né ?",a="Une Relique de bien-Né est un ancien instrument magique fabriqué par les sorciers bien-nés de l'ancien Kalimdor. Ces outils enchantés survivent entre les mains des esprits agités qui hantent les ruines brisées d'Ameth'Aran, portant la souillure persistante de la sorcellerie arcanique qui a précipité le Grand Cataclysme.",al={"qu'est-ce qu'une relique de bien-né","lore des reliques de bien-né","que sont ces reliques"}}},fp="15,141,25.381.0,24.381.0,36.173.0,47.157.0,50.228.0,33.202.0"}
P.entries["item:highperch-venom-sac"] = {n="Glande à venin de Haut-perchoir",s="À Haut-perchoir, les wyvernes portent un venin recherché par des acheteurs de tout Kalimdor. Leurs sacs alimentent le commerce même là où les bêtes ne volent pas.",h="À Haut-perchoir, les wyvernes portent un venin recherché par des acheteurs de tout Kalimdor.",kw={"fiora longears","heartrazor","haut-perchoir","poison","theramore","mille pointes","sac de venin","wyverne"},ang={["class:Rogue"]="En tant que Voleur, vous pouvez trouver certaines des toxines naturelles les plus puissantes de Kalimdor dans le venin paralysant concentré des wyvernes sauvages des Mille pointes.",["faction:Alliance"]="En tant que membre de l'Alliance, vous pouvez attaquer les nids de Haut-perchoir pour obtenir de précieux réactifs commerciaux et éliminer des wyvernes sauvages que la Horde pourrait autrement capturer et dompter comme montures."},sec={{t="Une récolte puissante",b="Des wyvernes sauvages nichent dans les escarpements de Haut-perchoir, dans les Mille pointes. Leurs queues barbelées injectent un venin qui peut paralyser ou tuer leurs proies. La Horde domestique souvent les wyvernes pour en faire des coursiers du vent. Dans tout Kalimdor, alchimistes, chasseurs et marchands paient cher leurs sacs de venin."},{t="Un acheteur lointain",b="Le venin de Haut-perchoir parvient à des acheteurs loin du centre de Kalimdor. À Theramore, la haute-elfe Fiora Longears paie cher les sacs frais récoltés dans les couvées de Haut-perchoir. Elle recherche des sacs gonflés de venin, que l'on trouve surtout sur les jeunes wyvernes ou les femelles fertiles. Loin de leur habitat désertique, elle fait commerce de ces réactifs dangereux."}},faq={{q="Quelles créatures portent ces sacs de venin ?",a="Les wyvernes sauvages de Haut-perchoir portent ces sacs. On trouve notamment les Highperch Wyverns, les Patriarchs, les Consorts et la matriarche Heartrazor.",al={"où trouver les sacs de venin","qui donne le venin de haut-perchoir","butin de venin de wyverne"}},{q="Pourquoi Fiora Longears veut-elle ce venin à Theramore ?",a="Fiora Longears sait que le venin de wyverne est très prisé dans certains milieux marchands, parfois davantage que les montures. Elle paie les voyageurs qui se rendent à Haut-perchoir, dans les Mille pointes, pour qu'ils rapportent des sacs intacts à vendre.",al={"pourquoi fiora veut du venin","acheteur de venin à theramore","qui achète le venin de wyverne"}},{q="Tous les sacs de venin de wyverne sont-ils identiques ?",a="Les sacs varient en puissance et en volume. Les plus recherchés sont gonflés de poison, généralement ceux des jeunes wyvernes ou des femelles fertiles en âge de se reproduire.",al={"qualité du venin de wyverne","sacs de venin éclatants"}},{q="Comment la Horde utilise-t-elle ces wyvernes par rapport à l'Alliance ?",a="La Horde capture et élève des wyvernes comme montures aériennes et éclaireurs appelés coursiers du vent. Des marchands indépendants et des contacts de l'Alliance dépourvus de réseaux de domestication récoltent ces bêtes pour leurs réactifs mortels.",al={"utilisation des wyvernes par la horde","les orcs utilisent-ils le venin"}}},fx={["98761a97"]={q="Qu'est-ce qu'une Glande à venin de Haut-perchoir ?",a="Une Glande à venin de Haut-perchoir est un organe récolté sur les wyvernes sauvages qui nichent sur la mesa imposante de Haut-perchoir dans les Mille pointes. Bien que les wyvernes soient surtout connues à travers Kalimdor comme des montures ailées utilisées par la Horde, leur venin est prisé pour sa puissance pure. Les glandes prélevées sur les bêtes au sommet de Haut-perchoir sont particulièrement riches et gonflées de cette toxine mortelle, ce qui en fait un prix lucratif pour les alchimistes et les commerçants qui traitent des réactifs animaux exotiques.",al={"qu'est-ce qu'une glande à venin de haut-perchoir","glande à venin de haut-perchoir","glande à venin de wyverne"}}},fp="19,123,16.261.0,15.310.0,38.125.0,53.203.0,36.137.0,66.206.0"}
P.entries["item:highperch-wyvern-egg"] = {n="Oeuf de wyverne de Haut-perchoir",s="À Haut-perchoir, les recrues de la Horde cherchent des œufs de wyverne pour en faire des montures. Les nids se trouvent au-dessus des mesas des Mille pointes.",h="À Haut-perchoir, les recrues de la Horde cherchent des œufs de wyverne pour en faire des montures.",kw={"elu","poste de librevent","haut-perchoir","oeuf de wyverne de haut-perchoir","mille pointes","wind rider","wyverne"},ang={["class:Hunter"]="En tant que chasseur, vous devez savoir lire les signes laissés par les féroces prédateurs qui gardent Haut-perchoir. Les wyvernes adultes défendent leurs nids avec leurs griffes et leur dard venimeux.",["faction:Horde"]="En tant que membre de la Horde, vous savez que des déplacements aériens fiables assurent les communications et la préparation militaire sur les vastes territoires de Kalimdor. De nouvelles wyvernes sont essentielles aux deux."},sec={{t="Nids sur la mesa",b="Haut-perchoir offre aux wyvernes indigènes un lieu où se percher et élever leurs petits au-dessus des Mille pointes. Des sentiers escarpés serpentent le long des parois du canyon jusqu'aux aires de nidification, où les wyvernes adultes gardent leurs nids. Dans leurs coquilles solides et chaudes, les petits attendent d'affronter les cieux rigoureux de Kalimdor."},{t="Élever de nouveaux Wind Riders",b="La Horde a besoin de plus de wyvernes dressées pour ses réseaux de messagers et d'éclaireurs à travers Kalimdor. Au Poste de Librevent, des recrues comme le tauren Elu cherchent des œufs intacts dans les nids sauvages. Elles élèvent les petits dès leur éclosion, dans l'espoir de nouer le lien qui fera d'eux des montures fiables pour un Wind Rider."}},faq={{q="Où trouve-t-on ces œufs ?",a="Les œufs se trouvent dans les nids de Haut-perchoir, une mesa le long des parois rocheuses à l'ouest des Mille pointes. Un sentier y grimpe depuis le fond du canyon.",al={"emplacement des œufs","où trouver des œufs de wyverne","emplacement des œufs de haut-perchoir"}},{q="Pourquoi la Horde ramasse-t-elle des œufs de wyverne sauvages ?",a="Les rangs des Wind Riders de la Horde s'étoffent, et les wyvernes dressées sont rares. Des recrues comme Elu ramassent des œufs et élèvent les petits dès leur naissance pour qu'ils servent dans les airs.",al={"pourquoi voler des œufs de wyverne","à quoi servent les œufs","but de la quête des œufs d'elu"}},{q="Les wyvernes adultes sont-elles hostiles aux ramasseurs d'œufs ?",a="Oui. Les wyvernes sauvages défendent farouchement leurs nids et attaquent les intrus qui s'aventurent à Haut-perchoir pour déranger leurs couvées.",al={"les wyvernes attaquent-elles","les wyvernes protègent-elles leurs petits"}},{q="Qui récupère ces œufs au Poste de Librevent ?",a="Elu, un aspirant Wind Rider en poste au Poste de Librevent, ramasse des œufs pour commencer à dresser sa propre monture.",al={"qui récupère les œufs de wyverne","elu au poste de librevent"}}},fx={efbaa71b={q="Qu'est-ce qu'un Oeuf de wyverne de Haut-perchoir ?",a="Ce sont les œufs viables de wyvernes sauvages nichant au sommet des mesas des canyons des Mille pointes. Dans leurs coquilles robustes reposent les petits non éclos des prédateurs ailés de Kalimdor, très recherchés par ceux qui souhaitent élever des montures aériennes loyales dès leur plus jeune âge.",al={"qu'est-ce qu'un oeuf de wyverne de haut-perchoir","infos sur l'oeuf de wyverne","que sont ces œufs"}},bbfa5024={q="D'où viennent les Oeufs de wyverne de Haut-perchoir ?",a="Ils sont pondus par des wyvernes sauvages dans leurs nids au sommet des falaises de Haut-perchoir, un plateau élevé s'élevant au-dessus des canyons des Mille pointes. Les wyvernes adultes gardent farouchement leurs nids contre les prédateurs et les charognards audacieux.",al={"d'où viennent les oeufs de wyverne de haut-perchoir","qui a pondu les œufs","origine de l'oeuf de wyverne"}}},fp="20,116,17.269.0,23.290.0,27.139.0,44.168.0,48.118.0,40.107.0"}
P.entries["item:hildelve-s-journal"] = {n="Journal d'Hildelve",s="À Dun Morogh, le Journal d'Hildelve consigne les derniers mots d'un nain tué par un ours féroce. Ses pages racontent l'attaque et son appel à la vengeance.",h="À Dun Morogh, le Journal d'Hildelve consigne les derniers mots d'un nain tué par un ours féroce.",kw={"dun morogh","hildelve","ours griffe-de-glace","journal","mangeclaw","pilote martèlepied","brigade des sapeurs"},ang={["faction:Alliance"]="En tant que membre de l'Alliance, vous renforcez les liens entre l'Alliance et la Brigade des sapeurs de Forgefer en récupérant les effets personnels de soldats tombés au combat comme Hildelve.",["race:Dwarf"]="En tant que nain, vous pouvez honorer l'esprit inflexible des pilotes qui affrontent le froid glacial et les bêtes sauvages pour sécuriser les hauteurs de Khaz Modan."},sec={{t="Les derniers mots d'un pilote",b="Le pilote nain Hildelve s'est aventuré seul dans Dun Morogh après la panne de son char à vapeur. Il a laissé son partenaire, le Pilote Martèlepied, auprès des chars et a exploré les crêtes balayées par la neige à la recherche du minerai de chiron dont il avait entendu parler. Dans son journal, Hildelve écrit que Mangeclaw, un ours griffe-de-glace monstrueux, l'a traqué pendant des jours avant de l'attaquer.\n\nHildelve s'est battu avec bravoure et a repoussé l'ours, mais Mangeclaw l'a mutilé et l'a laissé grièvement blessé dans le froid. Ses dernières heures ont été atroces. Avant le retour de l'ours, Hildelve n'a formulé qu'une demande : que quiconque trouverait son corps traque Mangeclaw et venge sa mort."},{t="Retour à la Brigade des sapeurs",b="Le Pilote Martèlepied, camarade d'Hildelve, est posté près de l'Avant-poste de la porte Nord, dans l'est de Dun Morogh. Martèlepied appartient à la Brigade des sapeurs de Forgefer et craignait le pire lorsque son partenaire n'est pas revenu de sa recherche de minerai. Le journal et la griffe tranchée de Mangeclaw prouvent que le dernier souhait d'Hildelve a été exaucé et que son esprit repose en paix."}},faq={{q="Qui était Hildelve ?",a="Hildelve était un nain qui pilotait un char à vapeur pour la Brigade des sapeurs de Forgefer. Après la panne de son char, il s'est aventuré seul dans Dun Morogh à la recherche de minerai de chiron. Mangeclaw l'a tué avant qu'il puisse rentrer.",al={"histoire d'hildelve","qui est hildelve","pilote nain hildelve"}},{q="Qu'est-ce que Mangeclaw ?",a="Mangeclaw est un ours griffe-de-glace particulièrement grand et féroce qui rôde sur les crêtes enneigées de Dun Morogh. Il a pris Hildelve en embuscade alors que celui-ci était immobilisé et l'a grièvement mutilé. Puis Mangeclaw est revenu pour mettre fin à ses jours.",al={"qui est mangeclaw","qu'est-ce qui a tué hildelve","ours qui a tué hildelve"}},{q="À qui remettre le journal ?",a="Le Pilote Martèlepied reçoit le journal. Ce camarade d'Hildelve pilote des engins de siège et est posté près de l'Avant-poste de la porte Nord, dans l'est de Dun Morogh. Il cherchait des nouvelles du pilote disparu.",al={"où remettre le journal","qui reçoit le journal d'hildelve","remettre le journal d'hildelve"}},{q="Que demande Hildelve dans son journal ?",a="Hildelve demande à quiconque trouvera sa dépouille de traquer Mangeclaw et de venger sa mort. Dans les dernières pages du journal, il nomme la bête qui l'a attaqué et formule sa demande, sachant que ses blessures lui seront fatales.",al={"dernier souhait d'hildelve","que contient le journal","dernier souhait d'un pilote"}}},fx={b58cc0e1={q="Qu'est-ce que le Journal d'Hildelve ?",a="Ce journal de bord battu appartenait à Hildelve, un pilote nain abattu de la Brigade des sapeurs de Forgefer. Trouvé aux côtés de ses restes dans les étendues gelées de Dun Morogh, il relate ses derniers instants éprouvants — documentant sa survie après une attaque brutale initiale par le grand ours Mangeclaw, et écrivant son dernier souhait de vengeance avant que la bête ne revienne pour l'achever.",al={"qu'est-ce que ce journal","lore du journal d'hildelve","à propos du journal d'hildelve"}},["308c8265"]={q="D'où vient le Journal d'Hildelve et qui l'a écrit ?",a="Le journal a été rédigé par le pilote Hildelve lui-même au cours de son épreuve à Dun Morogh. Après que son char à vapeur soit tombé en panne, il est parti à la recherche de minerai de chiron à pied et a été mutilé par l'ours Mangeclaw ; il a tenu ce journal personnel jusqu'à sa mort, laissant derrière lui un témoignage écrit de sa lutte et sa dernière requête.",al={"qui a écrit le journal","d'où vient le journal d'hildelve","origine du journal d'hildelve"}},["856dae3f"]={q="Pourquoi quelqu'un voudrait-il le Journal d'Hildelve ?",a="Son collègue pilote de char à vapeur, le Pilote Martèlepied, cherchait désespérément des nouvelles de son camarade disparu. Le journal offre une preuve définitive du sort d'Hildelve et honore sa dernière demande de représailles contre le monstre qui a pris sa vie, apportant une conclusion à ses amis de la Brigade des sapeurs de Forgefer.",al={"pourquoi garder le journal d'hildelve","qui veut le journal","pourquoi rapporter le journal d'hildelve"}}},fp="18,145,21.567.0,27.344.1,17.205.0,18.207.0,42.179.0,42.197.0"}
P.entries["item:hillsbrad-human-skull"] = {n="Crâne d'humain de Hautebrande",s="À Hautebrande, les Réprouvés ramassent les crânes des Humains qu’ils ont tués. Au Moulin-de-Tarren, ils les gardent en sombres souvenirs de l’assaut contre les colonies locales.",h="À Hautebrande, les Réprouvés ramassent les crânes des Humains qu’ils ont tués.",kw={"darthalia","hautebrande","samsa","crâne","austrivage","moulin-de-tarren","trophée"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous voyez les fermiers et les soldats de Hautebrande réduits à des bibelots, signe de la cruauté de la campagne réprouvée en Lordaeron.",["race:Undead"]="En tant que Réprouvé, vous pouvez voir ces crânes comme une vengeance et un sombre rappel de vos proches vivants qui vous rejettent."},sec={{t="Trophées d’une guerre amère",b="Les forces réprouvées du Moulin-de-Tarren combattent les Humains d’Austrivage et des colonies voisines. Lors de la bataille de Hautebrande, les Trépasseurs et les soldats exécutent la purge ordonnée par Darthalia. Les gardes de faction veulent leur part du massacre.\n\nLe Nécrogarde Samsa ramasse les crânes des combattants en première ligne. Il prend plaisir à garder les restes de ceux parmi lesquels les Réprouvés ont autrefois vécu. Ces trophées marquent les tueries tandis que le conflit fait rage."}},faq={{q="Qui veut ces crânes humains ?",a="Le Nécrogarde Samsa, une sentinelle réprouvée au Moulin-de-Tarren, ramasse les crânes. Jaloux des soldats envoyés combattre et piller Hautebrande tandis qu’il monte la garde, il demande aux aventuriers de passage de lui en apporter trente pour sa collection personnelle.",al={"qui veut des crânes","qui prend les crânes humains","crânes du nécrogarde samsa"}},{q="Où ramasse-t-on les crânes d’humains de Hautebrande ?",a="Les Réprouvés ramassent les crânes des combattants et des ouvriers humains dans les Contreforts de Hautebrande. Beaucoup sont pris près des fermes, des mines et des fortifications tenues par les Humains, attaquées lors de la bataille de Hautebrande.",al={"où trouver des crânes","récolter des crânes humains","qui laisse tomber des crânes humains"}},{q="Pourquoi les Réprouvés collectent-ils les restes humains ?",a="Certains Réprouvés collectent des restes humains par haine et par humour noir. Des soldats comme Samsa gardent les crânes comme curiosités et comme preuve que Hautebrande approche de la défaite.",al={"pourquoi les réprouvés veulent des crânes","collection de crânes des réprouvés"}}},fx={["0091f8c0"]={q="Qu'est-ce qu'un Crâne d'humain de Hautebrande ?",a="Ce sont les trophées macabres tranchés sur les défenseurs humains tombés au combat et les citadins éparpillés à travers les Contreforts de Hautebrande. Alors que le conflit fait rage entre les Réprouvés de Moulin-de-Tarren et les humains vivants de Hautebrande, de tels jetons macabres servent de preuve tangible des pertes de l'Alliance dans le territoire contesté.",al={"que sont les crânes d'humain de hautebrande","objet crâne d'humain de hautebrande","infos sur le crâne d'humain de hautebrande"}},["9eb161fa"]={q="D'où vient un Crâne d'humain de Hautebrande et qui l'a fabriqué ?",a="Ces crânes sont prélevés directement sur les humains mortels habitant les Contreforts de Hautebrande, récoltés par des combattants de la Horde engagés dans la guerre frontalière en cours. Plutôt que d'être fabriqués, ce sont des restes morbides du champ de bataille réclamés sur les soldats, fermiers et citoyens tués défendant les colonies humaines locales contre les Réprouvés.",al={"origine du crâne d'humain de hautebrande","d'où viennent les crânes d'humain de hautebrande","qui fabrique les crânes d'humain de hautebrande"}},a9ea879b={q="Pourquoi le Nécrogarde Samsa veut-il des crânes humains de Hautebrande ?",a="Le Nécrogarde Samsa, en poste au Moulin-de-Tarren, envie profondément les guerriers envoyés piller et combattre les vivants. Bloqué derrière les lignes de front, il collectionne ces crânes comme de précieux Souvenirs of Death pour partager par procuration le massacre des défenseurs humains de Hautebrande.",al={"pourquoi samsa veut des crânes","qui veut les crânes humains de hautebrande et pourquoi","pourquoi collecter les crânes humains de hautebrande"}}},fp="21,143,24.447.0,29.227.0,42.203.0,42.160.0"}
P.entries["item:hillsbrad-town-registry"] = {n="Registre municipal de Hautebrande",s="Dans les Champs de Hautebrande, l'hôtel de ville conserve les noms et les droits fonciers de ceux qui restent. Le Registre municipal de Hautebrande consigne l'ordre civique de la ville, et les Réprouvés le convoitent tandis qu'ils attaquent le bastion humain.",h="Dans les Champs de Hautebrande, l'hôtel de ville conserve les noms et les droits fonciers de ceux qui restent.",kw={"battle of hillsbrad","darthalia","champs de hautebrande","hôtel de ville de hautebrande","registre municipal de hautebrande","magistrat burnside"},ang={["faction:Horde"]="Pour la Horde, s'emparer du registre municipal aide à briser l'autorité humaine dans les contreforts et à consolider le bastion des Réprouvés au Moulin-de-Tarren.",["race:Human"]="En tant qu'humain, vous pouvez constater que le registre atteste officiellement l'existence et les droits des habitants qui restent à Hautebrande. Sa perte porterait un coup dur à la communauté de la région."},sec={{t="Un registre de défiance",b="Le Registre municipal de Hautebrande consigne les noms et les droits des habitants. Il se trouve dans l'hôtel de ville, près de l'estrade du magistrat Burnside. Depuis le Moulin-de-Tarren, les Réprouvés s'efforcent de briser la résistance humaine dans les contreforts. La Grande exécutrice Darthalia envoie des champions de la Horde dans l'hôtel de ville pour tuer le conseil et s'emparer du registre.\n\nSes pages recensent la population de Hautebrande, les foyers et les droits administratifs. Les Réprouvés s'en serviraient pour démanteler l'ordre civique de la ville et en apprendre davantage sur les survivants et leurs biens."}},faq={{q="Où se trouve le Registre municipal de Hautebrande ?",a="Le Registre municipal de Hautebrande se trouve dans un coin de l'hôtel de ville, dans les Champs de Hautebrande, près des escaliers menant à l'estrade du magistrat Burnside.",al={"emplacement du registre","où se trouve le registre municipal","trouver le registre de hautebrande"}},{q="Pourquoi les Réprouvés veulent-ils le voler ?",a="La Grande exécutrice Darthalia cherche à démanteler le pouvoir humain dans les contreforts. Le registre recense les citoyens, les foyers, les droits administratifs et les biens de la ville, et renseigne ainsi les Réprouvés sur la communauté survivante.",al={"pourquoi voler le registre","quête du registre de darthalia","rôle du registre"}},{q="Qui protège le registre ?",a="Le magistrat Burnside et les Hillsbrad Councilmen protègent le registre. Ils maîtrisent la magie défensive et se rassemblent dans l'hôtel de ville et autour de celui-ci.",al={"qui protège le registre","défenseurs de l'hôtel de ville"}}},fx={["188a667c"]={q="Qu'est-ce que le Registre municipal de Hautebrande ?",a="Le Registre municipal de Hautebrande est un registre officiel conservé dans l'hôtel de ville de la colonie des Champs de Hautebrande. Tenus à jour par l'administration humaine locale sous le magistrat Burnside, il documente les affaires civiles, la population et la gouvernance de l'une des possessions survivantes de l'Alliance dans les contreforts.",al={"qu'est-ce que le registre municipal de hautebrande","registre de hautebrande","qu'est-ce que le registre"}}},fp="23,209,20.486.0,42.136.0,37.220.0,24.138.0"}
P.entries["item:hinterlands-honey-ripple"] = {n="Houle au miel des Hinterlands",s="Des caisses de Houle au miel des Hinterlands se trouvent dans une base abandonnée de la Horde, près du Rocher de l’Affût. Dran Droffers veut les bouteilles pour un projet d’emballage.",h="Des caisses de Houle au miel des Hinterlands se trouvent dans une base abandonnée de la Horde, près du Rocher...",kw={"dran droffers","houle au miel des hinterlands","houle au miel","caisses de la horde","malton","houle","rocher de l'affût"},ang={["faction:Horde"]="Les bouteilles se trouvent dans des caisses, dans une ancienne base de la Horde près du Rocher de l’Affût."},sec={{t="Caisses au Rocher de l’Affût",b="Les caisses du Rocher de l’Affût contiennent de la Houle au miel des Hinterlands, une boisson singulière recherchée par Dran Droffers. L’ancienne base de la Horde se trouve au milieu de ruines couvertes de vase, où il faut ramasser les bouteilles avec précaution. Leur emballage intact est essentiel au projet de Dran."}},faq={{q="Où trouver de la Houle au miel des Hinterlands ?",a="La Houle au miel des Hinterlands se trouve dans des caisses autour de l’ancienne base de la Horde, près du Rocher de l’Affût.",al={"lieu de la houle au miel","où trouver la houle","bouteilles des hinterlands"}},{q="Qui recherche la Houle au miel ?",a="Dran Droffers recherche de la Houle au miel des Hinterlands pour un projet d’emballage impliquant le père de Malton.",al={"qui recherche la houle","dran droffers et la houle","houle pour qui"}},{q="Pourquoi Dran veut-il des bouteilles intactes ?",a="Dran dit que les bouteilles ne doivent pas être abîmées, car les secousses altèrent le bouquet de la boisson. Il a des emballages vides pour la Houle au miel.",al={"pourquoi garder les bouteilles intactes","ne pas abîmer la houle","emballage de la houle"}},{q="Qu’est-ce que la Houle au miel des Hinterlands ?",a="C’est une boisson en bouteille conservée dans des caisses, dans l’ancienne base de la Horde près du Rocher de l’Affût.",al={"houle au miel","qu’est-ce que la houle","boisson des hinterlands"}}},fp="24,138,20.263.0,42.86.0,27.96.1,38.127.0,33.81.0"}
P.entries["item:hippogryph-muisek"] = {n="Hippogryph Muisek",s="Hippogryph Muisek préserve les esprits des hippogriffes Frayfeather de Féralas. Un druide des plateaux sauvages vous demande de les capturer avec un Muisek Vessel.",h="Hippogryph Muisek préserve les esprits des hippogriffes Frayfeather de Féralas.",kw={"féralas","frayfeather","les plateaux sauvages","hippogriffe","hippogryph muisek","muisek vessel","esprit"},ang={["race:NightElf"]="En tant qu’elfe de la nuit, vous savez que les hippogriffes sont des compagnons fidèles aux esprits inébranlables. Le druide cherche à préserver ces esprits en toute sécurité."},sec={{t="Esprits préservés",b="Parmi les hippogriffes Frayfeather des plateaux sauvages, vous devez en capturer dix avec le Muisek Vessel. Les elfes de la nuit gardent depuis longtemps les hippogriffes comme fidèles compagnons, et leurs esprits sont inébranlables. Le réceptacle préserve chaque esprit après la mort de sa créature."}},faq={{q="Qu’est-ce que le Hippogryph Muisek ?",a="Hippogryph Muisek est l’esprit préservé d’un hippogriffe Frayfeather, capturé dans un Muisek Vessel.",al={"hippogryph muisek","objet muisek"}},{q="Où trouver les hippogriffes Frayfeather ?",a="Les hippogriffes Frayfeather vivent dans les plateaux sauvages, au sud du druide qui vous demande de les capturer.",al={"lieu des hippogriffes","où trouver les frayfeather"}},{q="Pourquoi capturer les hippogriffes ?",a="Le druide veut préserver leur muisek, car un esprit libéré à la mort de sa créature peut prendre la forme d’une créature plus puissante et menacer les environs.",al={"pourquoi le muisek","capturer des hippogriffes"}},{q="Combien faut-il d’hippogriffes ?",a="Le druide vous demande de capturer dix hippogriffes Frayfeather.",al={"combien d’hippogriffes","nombre de muisek"}}},fp="17,160,17.263.0,26.99.0,40.101.0,28.155.1,32.58.0"}
P.entries["item:hippogryph-muisek-vessel"] = {n="Hippogryph Muisek Vessel",s="Le Hippogryph Muisek Vessel conserve les esprits des hippogriffes de Féralas. Il sert à capturer leur muisek dans les plateaux sauvages.",h="Le Hippogryph Muisek Vessel conserve les esprits des hippogriffes de Féralas.",kw={"frayfeather","les plateaux sauvages","hippogriffe","muisek d'hippogriffe","hippogryph muisek vessel","muisek","zor arbre-solitaire"},ang={["race:NightElf"]="Les hippogriffes sont depuis longtemps les fidèles compagnons des elfes de la nuit, et préserver leurs esprits est important pour Zor Arbre-solitaire."},sec={{t="Un esprit préservé",b="Après avoir prouvé que vous savez vous servir du récipient, Zor Arbre-solitaire vous demande de capturer le muisek des hippogriffes. Les hippogriffes Frayfeather vivent dans les plateaux sauvages, au sud de chez lui. Leurs esprits sont depuis longtemps les fidèles compagnons des elfes de la nuit. Zor craint qu'un esprit libéré après la mort de l'animal ne devienne une créature plus puissante et ne cherche vengeance."}},faq={{q="À quoi sert le Hippogryph Muisek Vessel ?",a="Le récipient capture le muisek des hippogriffes afin que leurs esprits puissent être préservés.",al={"à quoi sert le récipient","utilisation du récipient à hippogriffes"}},{q="Où utiliser le récipient ?",a="Les hippogriffes Frayfeather se trouvent dans les plateaux sauvages, au sud de Zor Arbre-solitaire.",al={"où utiliser le récipient à muisek","récipient des plateaux sauvages"}},{q="Pourquoi capturer le muisek des hippogriffes ?",a="Le récipient préserve le muisek des hippogriffes. Zor Arbre-solitaire craint qu'un esprit libéré après la mort ne devienne une créature plus puissante et ne cherche vengeance.",al={"pourquoi les capturer","esprits des hippogriffes"}},{q="Les hippogriffes ont-ils de l'importance pour les elfes de la nuit ?",a="Les hippogriffes sont depuis longtemps les fidèles compagnons des elfes de la nuit.",al={"hippogriffes des elfes de la nuit","compagnons hippogriffes"}}},fp="24,137,18.341.0,42.72.0,26.78.0,30.145.0,41.73.0"}
P.entries["item:hollow-vulture-bone"] = {n="Os creux de vautour",s="Dans les Salines, des vautours tournent au-dessus du sel tandis que des équipes gobelines ramassent leurs os. À la Piste des mirages, les mécaniciens utilisent ces restes creux pour alléger leurs bolides-fusées sans les fragiliser.",h="Dans les Salines, des vautours tournent au-dessus du sel tandis que des équipes gobelines ramassent leurs os.",kw={"os creux de vautour","load lightening","piste des mirages","pozzik","charognard","les salines","mille pointes"},ang={["class:Hunter"]="En tant que chasseur, vous pouvez pister les robustes vautours charognards qui parcourent le lit de sel aveuglant.",["profession:Engineering"]="Les coureurs gobelins utilisent des os creux de vautour pour gagner du poids là où le fer et le bronze seraient lourds. Leur choix témoigne d’une approche pragmatique de la conception des bolides."},sec={{t="Matériaux de course des Salines",b="À la Piste des mirages, les équipes gobelines cherchent tous les moyens d’accélérer leurs bolides-fusées. Le poids ralentit une voiture, alors elles utilisent les ressources du désert en plus du fer et du cuivre. Les os creux de vautour sont légers, mais assez solides pour les mécanismes de direction, les supports internes et les petites pièces de renfort. Pozzik et les autres bricoleurs en chef les ramassent auprès des charognards locaux pour gagner quelques secondes sur la piste."}},faq={{q="Pourquoi les gobelins veulent-ils des os de vautour ?",a="Pozzik et d’autres ingénieurs gobelins utilisent les os creux de vautour pour alléger leurs bolides-fusées. Ces os sont légers et assez solides pour les mécanismes de direction et les petits supports.",al={"pourquoi des os","utilisation gobeline des os","utilisation des os par pozzik"}},{q="D’où viennent ces os ?",a="Les charognards des Salines et les vautours des Salines fournissent ces os autour des Salines, à Mille pointes, en particulier près des gigantesques restes squelettiques éparpillés dans le désert de sel.",al={"où trouver des os creux de vautour","emplacement des os de vautour","comment obtenir des os de vautour"}},{q="Qui est Pozzik ?",a="Pozzik est un ingénieur gobelin et le mécanicien en chef de la Piste des mirages. Il règle et modifie les bolides-fusées pour affronter l’équipe gnome menée par Féplouf Zéboulon.",al={"qui est pozzik","pozzik et la piste des mirages","qui récupère les os"}}},fx={["2d4c7633"]={q="Qu'est-ce qu'un Os creux de vautour ?",a="Il s'agit d'os légers et robustes récupérés sur les oiseaux charognards qui tournoient au-dessus des Salines. Le squelette aviaire est naturellement creux pour faciliter le vol, ce qui le rend particulièrement adapté à l'ingénierie mécanique où chaque gramme économisé compte. À la Piste des mirages, les ingénieurs gobelins les utilisent pour fabriquer des pièces structurelles résistantes et des composants de direction pour leurs voitures-fusées.",al={"qu'est-ce qu'un os creux de vautour","os creux de vautour"}}},fp="19,195,29.384.0,38.158.0,31.189.0,14.164.0"}
P.entries["item:honorary-picks"] = {n="Pioche d'honneur",s="À Forgefer, les pioches d’honneur sont destinées aux apprentis mineurs de Brock Cherchepierre, à Thelsamar. Des griffons transportent ces outils cérémoniels jusqu’au Loch Modan, où ils marquent le passage des élèves au travail dans les filons de minerai.",h="À Forgefer, les pioches d’honneur sont destinées aux apprentis mineurs de Brock Cherchepierre, à Thelsamar.",kw={"brock cherchepierre","gryth thurden","pioche d'honneur","forgefer","loch modan","pioches de mineur","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="En tant que mineur, vous connaissez la valeur d’une pioche solide. Un outil honorifique marque l’entrée d’un novice dans la profession.",["race:Dwarf"]="En tant que nain, vous connaissez les liens de parenté et le savoir-faire qui s’expriment lorsqu’on offre aux apprentis des outils forgés à Forgefer pour travailler dans les provinces."},sec={{t="Des outils pour la prochaine génération",b="Le travail des mineurs entretient les grandes forges et fournit aux nains le fer et la pierre dont ils ont besoin. À Thelsamar, Brock Cherchepierre enseigne le métier aux jeunes apprentis. Les pioches d’honneur de Forgefer marquent les élèves prêts à travailler dans les gisements de minerai à ciel ouvert du Loch Modan."},{t="À l’épreuve des lignes de griffons",b="Les pioches empruntent le réseau de griffons de l’Alliance, qui relie Forgefer à ses colonies éloignées. À la Grande Forge de Forgefer, Gryth Thurden réceptionne l’envoi. Il l’expédie par-dessus les montagnes à Thorgrum Borrelson, à Thelsamar."}},faq={{q="À quoi servent les pioches d’honneur ?",a="Les élèves mineurs de Brock Cherchepierre, au Loch Modan, reçoivent les pioches d’honneur. Ces outils cérémoniels sont prêts à être utilisés par les apprentis dans les filons de minerai de toute la région.",al={"que sont les pioches d’honneur","utilisation des pioches d’honneur","but des pioches d’honneur"}},{q="Qui envoie les pioches, et qui les reçoit ?",a="Les pioches sont préparées à Forgefer et remises à Gryth Thurden au perchoir des griffons de la ville. De là, elles volent vers l’est jusqu’à Thelsamar, où Brock Cherchepierre, le maître mineur, les réceptionne.",al={"qui reçoit les pioches d’honneur","livraison des pioches d’honneur","destinataire des pioches d’honneur"}},{q="Pourquoi faut-il livrer les pioches par griffon ?",a="Les griffons transportent rapidement les pioches entre Forgefer et le Loch Modan, en suivant les routes aériennes établies de l’Alliance. Cet itinéraire apprend aussi aux voyageurs à emprunter ces routes. Les pioches pourraient également être transportées à pied par le Passage de la porte Nord.",al={"pourquoi faire voler les pioches","pourquoi prendre un griffon","vol des pioches d’honneur"}},{q="Les pioches d’honneur sont-elles de vraies armes ou des outils que vous pouvez équiper ?",a="Non. Le coursier transporte les pioches comme cargaison pour les élèves mineurs de Brock Cherchepierre. Ils ont hâte de les utiliser dans les gisements de minerai du Loch Modan.",al={"peut-on équiper les pioches d’honneur","les pioches d’honneur sont-elles un objet","les pioches d’honneur sont-elles utilisables"}}},fx={a7b14bb4={q="Que sont les Pioches d'honneur ?",a="Les Pioches d'honneur sont un ensemble d'outils de minage cérémoniels ou commémoratifs fabriqués à Forgefer. Elles sont destinées à être présentées aux mineurs novices qui apprennent le métier sous la direction de prospecteurs expérimentés dans les collines du Loch Modan.",al={"que sont les pioches d'honneur","objet pioche d'honneur","histoire des pioches d'honneur"}},["0ecadd79"]={q="D'où viennent les Pioches d'honneur et qui les a fabriquées ?",a="Les pioches sont obtenues dans la capitale naine de Forgefer. Fabriquées par des forgerons de montagne qualifiés dans La Grande Forge de la ville, elles sont regroupées spécifiquement pour être transportées vers les instructeurs formant des apprentis au-delà des frontières de Dun Morogh.",al={"qui a fabriqué les pioches d'honneur","origine des pioches d'honneur","d'où viennent les pioches"}},["1a632b74"]={q="Pourquoi quelqu'un voudrait-il les Pioches d'honneur ?",a="L'instructeur de minage Brock Cherchepierre à Thelsamar a demandé ces pioches pour les offrir à ses étudiants novices. En tant qu'apprentis prospecteurs travaillant dans le Loch Modan, les étudiants attendent avec impatience ces honneurs et ces outils pour commencer à exploiter les riches filons minéraux de la région.",al={"pourquoi livrer les pioches d'honneur","qui veut les pioches d'honneur","pourquoi brock veut les pioches"}}},fp="14,202,29.256.0,25.237.0,37.165.0,43.192.0,49.237.0,61.144.0"}
P.entries["item:horn-of-arra-chea"] = {n="Corne d'Arra'chea",s="Dans tout Mulgore, de jeunes chasseurs traquent Arra'chea à la demande de Cairne Sabot-de-Sang. La corne prouve qu'ils savent trouver du gibier et subvenir aux besoins des Shu'halo.",h="Dans tout Mulgore, de jeunes chasseurs traquent Arra'chea à la demande de Cairne Sabot-de-Sang.",kw={"arra'chea","cairne sabot-de-sang","corne d'arra'chea","kodo","mulgore","rites of the earthmother","pitons-du-tonnerre"},ang={["class:Hunter"]="En tant que chasseur, traquer le parcours circulaire d'Arra'chea à travers Mulgore met à l'épreuve les talents de filature et de survie en milieu sauvage que votre vocation valorise.",["race:Tauren"]="En tant que Tauren, présenter la corne d'Arra'chea au High Chieftain Cairne marque un rite de passage. Cela prouve que vous êtes prêt à subvenir aux besoins de votre peuple et à le défendre au sommet des Pitons-du-Tonnerre."},sec={{t="L'épreuve d'un chef",b="Après les Rites of the Earthmother, un jeune peut prendre sa place au sommet des Pitons-du-Tonnerre. Pourtant, le High Chieftain Cairne Sabot-de-Sang demande encore à son peuple de prouver sa valeur. Pour les Tauren, la chasse lie leur identité à une harmonie durable avec la terre. Cairne envoie donc de jeunes chasseurs traquer Arra'chea, un kodo mâle massif et solitaire qui parcourt les prairies en contrebas. Rapporter la corne du taureau prouve qu'ils savent pister une proie sur de vastes distances."},{t="Subvenir aux besoins de la tribu",b="La corne d'Arra'chea contribue à la subsistance des Pitons-du-Tonnerre et témoigne de la force du chasseur. Les Tauren utilisent chaque partie d'une bête abattue. Le trophée indique au High Chieftain où Arra'chea est tombé. Des groupes de collecte peuvent alors descendre dans les plaines et récupérer l'épaisse peau et la viande abondante du kodo pour la jeune capitale."}},faq={{q="Qu'est-ce que la Corne d'Arra'chea ?",a="La corne d'Arra'chea provient du puissant kodo insaisissable qui parcourt les plaines de Mulgore. Les chasseurs l'apportent à Cairne Sabot-de-Sang comme rite de passage et preuve de leur talent de pisteur.",al={"corne d'arrachea","qu'est-ce que cette corne"}},{q="Qui est Arra'chea ?",a="Arra'chea est un kodo mâle renommé qui parcourt les prairies au nord-est des Pitons-du-Tonnerre. Sa force et son vaste itinéraire migratoire en font une proie difficile pour les chasseurs qui doivent prouver leur valeur à la tribu.",al={"arrachea","qui est arrachea","lore d'arrachea"}},{q="Pourquoi Cairne Sabot-de-Sang demande-t-il ce trophée ?",a="Cairne Sabot-de-Sang demande ce trophée parce qu'il attend de son peuple qu'il prouve constamment sa valeur. Traquer et tuer Arra'chea témoigne du dévouement d'un chasseur aux traditions de la Terre-mère et fournit des ressources à la communauté.",al={"pourquoi cairne veut la corne","cairne arrachea","corne rites de la terre-mère"}},{q="Que devient le reste de la bête après sa mort ?",a="Les Tauren utilisent chaque partie de l'animal chassé. Une fois la mise à mort confirmée par la corne, Cairne envoie un groupe de collecte dans Mulgore pour rapporter la peau et la viande aux Pitons-du-Tonnerre.",al={"viande d'arrachea","tradition de chasse des tauren","dépouille d'arrachea"}}},fx={["0ff92160"]={q="D'où vient la Corne d'Arra'chea et qui l'a fabriquée ?",a="La corne n'est pas un artefact fabriqué, mais un trophée naturel prélevé sur Arra'chea, un puissant kodo qui parcourt les plaines de Mulgore en contrebas des Pitons-du-Tonnerre. Pour la réclamer, un chasseur doit traquer la grande bête dans les prairies ouvertes et l'abattre lors d'un combat honorable.",al={"origine de la corne d'arra'chea","d'où vient la corne d'arra'chea","qui a fabriqué la corne d'arra'chea"}}},fp="17,138,18.421.0,23.316.0,30.173.0,17.199.0,46.233.0,57.169.0"}
P.entries["item:horn-of-awakening"] = {n="Corne de l'éveil",s="Sur la route d'Orneval, Kerlonian Eternombre transporte la Corne de l'éveil. Elle le réveille dès que le sommeil le gagne.",h="Sur la route d'Orneval, Kerlonian Eternombre transporte la Corne de l'éveil.",kw={"orneval","sombrivage","druid of the claw","rêve d'émeraude","corne de l'éveil","kerlonian eternombre","poste de maestra"},ang={["class:Druid"]="En tant que druide, vous savez que les druide de la Griffe ont passé des générations endormis dans les tertres funéraires, en communion avec le Rêve d'émeraude. Le retour à l'éveil peut les laisser hébétés et désorientés.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous voyez dans le voyage somnolent de Kerlonian combien il peut être difficile pour vos druides de se réveiller après leur long sommeil dans le Rêve d'émeraude."},sec={{t="Un remède pour druides somnolents",b="Kerlonian Eternombre ne s'est réveillé que récemment après des siècles passés dans le Rêve d'émeraude. Pourtant, rester éveillé lui pèse. Le Druid of the Claw voyage vers le sud, en direction du Poste de Maestra, et confie la corne aux voyageurs prêts à l'escorter.\n\nQuand l'épuisement gagne Kerlonian sur le sentier sauvage, un son clair le fait sursauter et le réveille. Il se remet sur pied avant que des bêtes sauvages ou des sectateurs ne puissent l'atteindre."}},faq={{q="Où trouve-t-on la Corne de l'éveil ?",a="La corne se trouve dans le coffre de Kerlonian, près du campement de Kerlonian Eternombre, dans le sud de Sombrivage, près de la frontière d'Orneval.",al={"emplacement de la corne","où trouver la corne de l'éveil","coffre de kerlonian"}},{q="Pourquoi Kerlonian a-t-il besoin de la corne pour rester éveillé ?",a="Après avoir dormi pendant des âges dans le Rêve d'émeraude, Kerlonian peine à rester éveillé comme un mortel. De soudaines et profondes siestes le surprennent souvent en chemin.",al={"pourquoi kerlonian dort","pourquoi s'endort-il","sommeil dans le rêve d'émeraude"}},{q="Où Kerlonian essaie-t-il d'aller ?",a="Kerlonian essaie de rejoindre le Poste de Maestra, dans le nord d'Orneval, pour rencontrer Liladris Moonriver.",al={"destination de kerlonian","où se dirige-t-il","escorte vers le poste de maestra"}}},fx={["061d2ee3"]={q="Qu'est-ce que la Corne de l'éveil ?",a="La Corne de l'éveil est un instrument personnel appartenant au druide elfe de la nuit Kerlonian Eternombre. Ayant récemment émergé du Rêve d'émeraude, Kerlonian souffre d'accès de sommeil profond et inopportun lors de ses voyages. Il garde cette corne en sécurité dans son coffre, spécifiquement pour qu'une escorte puisse en jouer afin de le réveiller chaque fois qu'il s'effondre le long de la route.",al={"corne de l'éveil","qu'est-ce que cette corne","corne de kerlonian"}}},fp="17,119,26.391.0,37.127.0,47.148.0,32.93.0"}
P.entries["item:horn-of-echeyakee"] = {n="Corne d'Echeyakee",s="À La Croisée, Sergra Darkthorn remet aux chasseurs la Corne d'Echeyakee, à sonner près des anciens ossements de kodo au nord-est. Son appel fait surgir le légendaire prédateur blanc des Tarides.",h="À La Croisée, Sergra Darkthorn remet aux chasseurs la Corne d'Echeyakee, à sonner près des anciens ossements...",kw={"tarides","la croisée","echeyakee","corne","ossements de kodo","sergra darkthorn","brume blanche"},ang={["class:Hunter"]="En tant que chasseur, vous affrontez Echeyakee lors d'un rite de passage légendaire. Vos sens sont mis à l'épreuve face à un prédateur réputé dans toutes les Tarides pour sa discrétion presque parfaite.",["race:Tauren"]="En tant que Tauren, vous savez que la chasse d'Echeyakee revêt une importance spirituelle. Votre peuple voit dans sa mise à mort rapide et sans douleur à la fois la miséricorde et la dure nécessité de la mort."},sec={{t="Appeler Brume blanche",b="Les chasseurs reçoivent la corne lors d'une épreuve de chasse. Son appel invoque Echeyakee, dont le nom signifie « Brume blanche » en taur-ahe. Les chasseurs taurens révèrent le roi des félins de la savane, incarnation de la miséricorde et de la mort. Son attaque fulgurante ne laisse à sa proie aucun temps pour éprouver terreur ou souffrance. La corne a sa place dans son antre, parmi les ossements de kodo géants, derrière les collines au nord-est de La Croisée."}},faq={{q="À quoi sert la Corne d'Echeyakee ?",a="La corne appelle Echeyakee, le félin blanc insaisissable de la savane. Sonnez-la près des ossements de kodo géants au nord-est de La Croisée, et la bête apparaît pour affronter un chasseur.",al={"utiliser la corne d'echeyakee","à quoi sert la corne d'echeyakee"}},{q="D'où vient la corne ?",a="À La Croisée, dans les Tarides, Sergra Darkthorn, une chasseuse orque, remet la corne à ceux qui veulent prouver leur discrétion et leur talent de pisteur.",al={"qui remet la corne","origine de la corne d'echeyakee"}},{q="Que signifie le nom Echeyakee ?",a="En taur-ahe, la langue des Taurens, Echeyakee signifie « Brume blanche ». Ce nom évoque son pelage pâle et son passage silencieux dans les herbes sèches.",al={"signification d'echeyakee","signification de brume blanche"}},{q="Où sonner la corne ?",a="Sonnez la corne parmi les côtes de kodo géants et les restes squelettiques derrière les collines au nord-est de La Croisée, là où rôde le lion blanc.",al={"où utiliser la corne","emplacement d'echeyakee"}}},fx={eb6b337d={q="Qu'est-ce que la Corne d'Echeyakee ?",a="La Corne d'Echeyakee est un instrument de chasse rituel remis aux chasseurs prometteurs à La Croisée par Sergra Darkthorn. Soufflée parmi les ossements de kodo géants au nord-est de la colonie, son appel attire Echeyakee lui-même, le lion blanc vénéré par les taurens comme le roi des félins de la savane.",al={"corne d'echeyakee","qu'est-ce que cette corne","qu'est-ce que la corne d'echeyakee"}},["5884ea69"]={q="Pourquoi Sergra Darkthorn vous donne-t-elle la Corne d'Echeyakee ?",a="Sergra Darkthorn fournit la corne comme outil essentiel pour tester vos prouesses. Echeyakee rôde dans les plaines, invisible comme un Mist blanc, ce qui le rend presque impossible à traquer par la seule vue. L'appel de la corne défie le grand prédateur, l'incitant à sortir pour combattre afin que vous puissiez réclamer sa peau et prouver vos talents de chasseur.",al={"pourquoi ai-je besoin de la corne d'echeyakee","pourquoi la corne d'echeyakee","but de la corne d'echeyakee"}}},fp="17,207,21.375.0,35.165.0,30.144.0,34.134.0,27.135.0"}
P.entries["item:huge-gnoll-claw"] = {n="Grande griffe de gnoll",s="Dans le sud-ouest d’Elwynn, la mort de Lardeur est prouvée par son énorme griffe. Les autorités de Hurlevent à Comté-de-l’Or l’exigent avant de verser la prime.",h="Dans le sud-ouest d’Elwynn, la mort de Lardeur est prouvée par son énorme griffe.",kw={"prime","forêt d’elwynn","comté-de-l’or","lardeur","grande griffe de gnoll","maréchal dughan","riverpaw"},ang={["class:Hunter"]="En tant que chasseur, vous montrer capable de traquer et de chasser les bêtes en rapportant la griffe d’un prédateur qui venait régulièrement à bout de groupes armés témoigne de votre talent.",["faction:Alliance"]="Pour l’Alliance, récupérer la griffe de Lardeur débarrasse le cœur du royaume de sa terreur des bois la plus célèbre. Elle prouve votre vaillance au maréchal Dughan et à la garnison éprouvée de Comté-de-l’Or."},sec={{t="Preuve du chasseur de primes",b="Depuis des mois, Lardeur terrorise les bois méridionaux de La Lisière. Les patrouilles n’ont pas réussi à l’arrêter, et la garnison locale ne parvient ni à encercler ni à maîtriser la brute. L’armée de Hurlevent est dispersée dans toute la Forêt d’Elwynn ; elle a donc offert une prime pour sa tête. Le maréchal Dughan, à Comté-de-l’Or, exige une preuve irréfutable avant de payer. L’énorme griffe de Lardeur ne laisse aucun doute : le célèbre maraudeur est tombé."}},faq={{q="À quoi sert la Grande griffe de gnoll ?",a="Apportez la griffe de Lardeur au maréchal Dughan à Comté-de-l’Or pour prouver sa mort et toucher la prime offerte.",al={"que faire de la griffe de lardeur","utilité de la grande griffe de gnoll","qui veut la griffe"}},{q="D’où vient cette griffe ?",a="Lardeur porte cette griffe. Ce gnoll d’élite rôde près des campements Riverpaw, le long des frontières sud-ouest de La Lisière, dans la Forêt d’Elwynn.",al={"qui donne la griffe","comment obtenir la grande griffe de gnoll","où trouver la grande griffe de gnoll"}},{q="Pourquoi le maréchal Dughan veut-il une griffe plutôt que la tête ?",a="Lardeur est anormalement grand pour un gnoll, et ses griffes immenses sont distinctives et immédiatement reconnaissables. L’une d’elles prouve à l’armée de Hurlevent que le célèbre maraudeur a été tué.",al={"pourquoi la griffe comme preuve de mort","pourquoi pas la tête de lardeur","preuve pour la prime de dughan"}},{q="Puis-je obtenir une autre griffe si je la perds ?",a="Oui. Si vous perdez la griffe avant de l’apporter au maréchal Dughan, vous pouvez retourner chasser Lardeur dans le sud-ouest de la Forêt d’Elwynn et en récupérer une autre.",al={"grande griffe de gnoll perdue","peut-on récupérer la griffe","réapparition de la griffe de lardeur"}}},fx={d9093290={q="Qu'est-ce que la Grande griffe de gnoll ?",a="La Grande griffe de gnoll est la preuve physique tranchée de la disparition de Lardeur, un gnoll notoire et massif qui terrorise le sud-ouest de la Forêt d’Elwynn. Parce que Lardeur a déjoué toutes les tentatives de capture des autorités locales, cette serre distinctive sert de preuve indéniable pour le Maréchal Dughan que la brute a enfin été tuée.",al={"qu'est-ce que la grande griffe de gnoll","infos sur la grande griffe de gnoll","griffe de lardeur"}},["7983cdb8"]={q="Pourquoi le Maréchal Dughan veut-il la Grande griffe de gnoll ?",a="Le Maréchal Dughan et l'armée de Hurlevent ont mis une prime sur Lardeur après que la bête géante a évité et vaincu leurs patrouilles. Dughan exige la griffe massive du gnoll comme preuve de sa mort avant de verser la prime à Comté-de-l’Or, mettant enfin un terme au casse-tête que Lardeur causait à ses hommes.",al={"pourquoi dughan veut la griffe","qui veut la grande griffe de gnoll","pourquoi vouloir la grande griffe de gnoll"}}},fp="15,140,21.406.0,37.104.0,31.138.0,56.179.0,36.142.0"}
P.entries["item:humbert-s-sword"] = {n="Epée d'Humbert",s="À Dun Garok, l'Épée d'Humbert repose parmi les nains qui l'ont prise dans son camp. Le Nécrogarde Humbert avait quitté son poste pour ramasser du bois en surveillant la forteresse.",h="À Dun Garok, l'Épée d'Humbert repose parmi les nains qui l'ont prise dans son camp.",kw={"darthalia","nécrogarde humbert","dun garok","hautebrande","epée d'humbert","moulin-de-tarren"},ang={["faction:Horde"]="Récupérer l'épée soutient les opérations plus vastes de la Horde contre l'enclave naine de Dun Garok. Ces opérations comprennent aussi la collecte de sang nain et d'insignes militaires.",["race:Undead"]="La Grande exécutrice Darthalia impose une discipline stricte aux forces réprouvées de Hautebrande. Les sentinelles comme Humbert cherchent désespérément à cacher leurs erreurs lorsqu'elles baissent leur garde."},sec={{t="Un moment d'inattention",b="Un matin, le Nécrogarde Humbert quitta son poste dissimulé près de Dun Garok pour ramasser du bois et faire bouillir de l'eau. La Grande exécutrice Darthalia l'avait envoyé surveiller la présence naine sur place. Pendant son absence, une patrouille naine découvrit son campement et pilla son équipement, dont sa lame personnelle. Humbert a désormais besoin d'agents de la Horde pour fouiller la forteresse et la récupérer."},{t="Le butin des nains",b="Les défenseurs de Dun Garok ont emporté les affaires d'Humbert derrière les barricades de la forteresse. Fusiliers, montagnards et prêtres se passent des provisions dans la garnison. Pour trouver le voleur, il faut fouiller les défenseurs dans les tranchées et les redoutes."}},faq={{q="À qui appartient cette épée ?",a="L'épée appartient au Nécrogarde Humbert, une sentinelle réprouvée en poste au Moulin-de-Tarren, chargée d'explorer Dun Garok.",al={"à qui appartient cette épée","propriétaire de humbert","qui est humbert"}},{q="Comment les nains ont-ils obtenu l'épée d'Humbert ?",a="Un matin, Humbert quitta son campement d'éclaireur juste à l'extérieur de Dun Garok pour ramasser du bois. Pendant son absence, une patrouille naine saccagea le camp et emporta son équipement.",al={"comment les nains l'ont obtenue","pourquoi les nains ont l'épée","comment l'épée a été volée"}},{q="Pourquoi Humbert tient-il tant à récupérer son épée ?",a="La Grande exécutrice Darthalia a ordonné à Humbert de surveiller Dun Garok, et il a besoin de son arme pour le faire. Avec autant de nains dans la garnison, il ne peut pas retrouver le voleur seul.",al={"pourquoi humbert veut son épée","que se passe-t-il si humbert perd son épée","pourquoi humbert y tient"}},{q="Où trouver l'épée ?",a="L'épée se trouve parmi les forces naines de Dun Garok, dans le sud-est des Contreforts de Hautebrande. Vous pouvez la récupérer sur les montagnards, les fusiliers ou les prêtres postés dans toute la place forte.",al={"où l'épée tombe","emplacement de l'épée","comment trouver l'épée d'humbert"}}},fp="15,163,25.357.0,17.242.0,20.116.0,40.156.0,50.171.0,29.181.0"}
P.entries["item:huntsman-malkhor-s-bones"] = {n="Huntsman Malkhor's Bones",s="Les os de Huntsman Malkhor sont des restes retrouvés dans une fosse de boue à Jintha'alor. Le Veneur Markhor les cherche pour offrir une sépulture convenable à son frère jumeau.",h="Les os de Huntsman Malkhor sont des restes retrouvés dans une fosse de boue à Jintha'alor.",kw={"hinterlands","ossements de malkhor","veneur markhor","jintha'alor","malkhor","angoisse de la séparation","fosse de boue","frère jumeau","vilebranch"},sec={{t="Les restes d'un frère",b="À Jintha'alor, dans les Hinterlands, les os de Huntsman Malkhor reposent dans une fosse à déchets, parmi les vases des Vilebranch. Le Veneur Markhor vous demande de les récupérer avec le crâne de son frère. Il espère apporter les restes à Yayo'jin pour leur offrir une sépulture convenable."}},faq={{q="Où se trouvent les os de Malkhor ?",a="Les os de Huntsman Malkhor reposent dans une fosse de boue à Jintha'alor, près du sommet du temple.",al={"emplacement des os de malkhor","où trouver les os"}},{q="Qui veut les os de Malkhor ?",a="Le Veneur Markhor, au Village des Revantusk, veut récupérer les restes de son frère jumeau afin de lui offrir une sépulture convenable.",al={"qui a besoin des os","os du frère de markhor"}},{q="Qui était Malkhor ?",a="Huntsman Malkhor était le frère jumeau du Veneur Markhor. Les Vilebranch l'ont capturé et tué lors d'un raid.",al={"histoire de malkhor","jumeau de markhor"}},{q="Pourquoi récupérer les os ?",a="Markhor espère apporter les restes de Malkhor à Yayo'jin pour lui offrir une sépulture convenable.",al={"importance des os","sépulture de malkhor"}},{q="Qu'est-il arrivé aux restes de Malkhor ?",a="Les Vilebranch ont donné les restes de Malkhor en pâture aux vases et aux loups de Jintha'alor.",al={"restes de malkhor","qu'est-il arrivé à ses os"}}},fp="24,151,19.239.0,26.88.0,26.105.0,16.103.1,22.72.0,35.76.1"}
P.entries["item:huntsman-malkhor-s-skull"] = {n="Huntsman Malkhor's Skull",s="Huntsman Malkhor's Skull fait partie des restes que le Veneur Markhor recherche à Jintha'alor. Il espère offrir à son frère jumeau une sépulture digne de lui.",h="Huntsman Malkhor's Skull fait partie des restes que le Veneur Markhor recherche à Jintha'alor.",kw={"huntsman malkhor","veneur markhor","jintha'alor","crâne de malkhor","village des revantusk","angoisse de séparation","vilebranch"},sec={{t="Les restes d'un frère",b="Parmi les crânes de Jintha'alor se trouve celui de Huntsman Malkhor, frère jumeau du Veneur Markhor du Village des Revantusk. Les Vilebranch ont tué Malkhor et abandonné ses restes aux limons et aux loups près des hauteurs du temple. Markhor vous demande de récupérer le crâne et les os afin que l'âme de son frère repose en paix."}},faq={{q="À qui appartient ce crâne ?",a="Ce crâne appartient à Huntsman Malkhor, le frère jumeau du Veneur Markhor du Village des Revantusk.",al={"crâne de malkhor","à qui appartient le crâne","huntsman malkhor"}},{q="Où se trouve le crâne de Malkhor ?",a="Le crâne de Malkhor repose dans un tas de crânes sur la terrasse supérieure de Jintha'alor.",al={"emplacement du crâne","où se trouve le crâne","crâne de jintha'alor"}},{q="Qui veut retrouver les restes de Malkhor ?",a="Le Veneur Markhor veut que vous récupériez le crâne et les os de son frère jumeau afin qu'il ait une sépulture digne de lui.",al={"qui veut les restes","frère de markhor","angoisse de séparation"}},{q="Comment Malkhor est-il mort ?",a="Les Vilebranch ont tué Malkhor lors d'un raid et ont donné ses restes en pâture aux limons et aux loups.",al={"qu'est-il arrivé à malkhor","mort de malkhor","vilebranch ont tué"}},{q="Pourquoi Markhor recherche-t-il les restes ?",a="Markhor espère faire préparer les restes de Malkhor pour une sépulture digne de lui et apaiser son âme.",al={"pourquoi récupérer le crâne","sépulture de malkhor","restes du frère"}}},fp="24,137,19.321.0,29.97.0,25.75.0,28.93.0,20.80.1,41.95.0"}
P.entries["item:hyacinth-mushroom"] = {n="Champignon jacinthe",s="À Sombrevallon, les champignons jacinthes poussent parmi les arbres et les racines de Teldrassil. Les herboristes elfes de la nuit les utilisent en médecine, tandis que les grells et les grellkins les cherchent pour se nourrir.",h="À Sombrevallon, les champignons jacinthes poussent parmi les arbres et les racines de Teldrassil.",kw={"antidote","dirania brillargent","grell","grellkin","champignon jacinthe","iverron","sombrevallon","teldrassil"},ang={["profession:Herbalism"]="Aucune formation officielle n’est nécessaire pour cueillir ces champignons à Sombrevallon. En tant qu’herboriste novice, vous pouvez apprendre comment ils aident à neutraliser les toxines de la forêt.",["race:NightElf"]="En tant que jeune elfe de la nuit en formation à Sombrevallon, vous pouvez cueillir des plantes sauvages comme les champignons jacinthes pour aider à nourrir votre peuple."},sec={{t="La flore de Sombrevallon",b="Parmi les arbres et les racines d’Aldrassil, à Sombrevallon, les champignons jacinthes aident les guérisseurs de la forêt à soigner les jeunes sentinelles et les recrues elfes de la nuit blessées par des créatures venimeuses. Les araignées de la grotte de Sombrefil comptent parmi les dangers qu’ils affrontent. Les guérisseurs utilisent ces champignons dans des décoctions apaisantes et des antivenins. Les grells corrompus en font aussi des réserves."}},faq={{q="À quoi servent les champignons jacinthes ?",a="Dirania Brillargent utilise les champignons jacinthes pour préparer un antidote destiné à Iverron, un jeune elfe de la nuit empoisonné par des araignées venimeuses alors qu’il explorait la grotte de Sombrefil.",al={"utilisation du champignon jacinthe","à quoi sert-il","remède pour iveron"}},{q="Où poussent les champignons jacinthes ?",a="À Sombrevallon, sur Teldrassil, les champignons jacinthes poussent au sol, près des grands troncs et des racines, ainsi qu’au pied des rochers.",al={"emplacement des champignons","où trouver des champignons jacinthes","champignons de sombrevallon"}},{q="Pourquoi les grells transportent-ils des champignons jacinthes ?",a="Les grells et les grellkins cherchent des champignons jacinthes dans le sud de Sombrevallon et en font des réserves dans leurs campements.",al={"les grells lâchent des champignons","pourquoi les grells en ont-ils","champignons grellkins"}},{q="Les champignons jacinthes sont-ils eux-mêmes toxiques ?",a="Non. Les guérisseurs locaux utilisent sans danger les champignons jacinthes dans des cataplasmes et des antivenins.",al={"le champignon jacinthe est-il toxique","champignon vénéneux"}}},fx={["77b7a797"]={q="Qu'est-ce qu'un Champignon jacinthe ?",a="Le Champignon jacinthe est un champignon indigène que l'on trouve dans les branches sombres de Teldrassil, en particulier à la base des arbres et sur les pierres moussues de Sombrevallon. Remarquables pour leur valeur médicinale, ces champignons des bois possèdent des propriétés naturelles capables de contrer le venin lorsqu'ils sont correctement infusés avec d'autres flores locales.",al={"qu'est-ce qu'un champignon jacinthe","infos sur le champignon jacinthe","à propos des champignons jacinthe"}}},fp="17,161,19.329.0,37.158.0,33.121.0,42.102.0,44.84.0"}
P.entries["item:hypercapacitor-gizmo"] = {n="Hypercapaciteur bidulotron",s="Dans les Mille pointes, l’Hypercapaciteur bidulotron gît parmi les débris d’une caravane gobeline. Une panthère en cage le portait au cou, et même son propriétaire ignore son utilité.",h="Dans les Mille pointes, l’Hypercapaciteur bidulotron gît parmi les débris d’une caravane gobeline.",kw={"centaures","panthère enragée","bidule","hypercapaciteur","mille pointes","poste de blanc-relais","wizlo braquecoquard"},ang={["faction:Horde"]="Les voyageurs qui prêtent main-forte au Poste de Blanc-relais aident à repousser les centaures agressifs et à récupérer les curiosités perdues dans les caravanes en ruine, au fond du canyon.",["profession:Engineering"]="Le bidule évoque l’ingénierie gobeline : un appareil complexe au nom grandiose, construit avec enthousiasme avant même que quiconque décide de son utilité."},sec={{t="Une étrange relique de caravane",b="Des maraudeurs centaures ont tendu une embuscade à une caravane gobeline qui traversait les Mille pointes et ont presque tout pillé. Wizlo Braquecoquard, seul survivant, a rampé jusqu’au Poste de Blanc-relais. Il a laissé derrière lui son meilleur bidule, fixé au cou d’une panthère féroce et enragée, enfermée dans une cage de transport. Les centaures craignaient la bête et ont laissé la cage intacte dans les décombres fumants."},{t="Bricolage à l’aveuglette",b="Wizlo appelle fièrement l’Hypercapaciteur bidulotron son meilleur bidule, même s’il reconnaît ignorer son utilité. L’appareil mêle ambition et pièces instables. Wizlo ne peut que continuer à bricoler, sans savoir à quoi il pourrait servir."}},faq={{q="Qu’est-ce que l’Hypercapaciteur bidulotron ?",a="L’Hypercapaciteur bidulotron appartient à Wizlo Braquecoquard, un ingénieur gobelin. Même Wizlo ignore son utilité, alors il compte l’étudier jusqu’à en découvrir la fonction.",al={"qu’est-ce qu’un bidule","hypercapaciteur","à quoi sert le bidule"}},{q="Comment l’appareil s’est-il retrouvé au cou d’une panthère ?",a="Des centaures ont attaqué et pillé la caravane de Wizlo, dans le nord des Mille pointes. Dans le chaos, l’appareil a été fixé au cou d’une panthère enragée, enfermée dans une cage de voyage. Les centaures superstitieux craignaient la bête et l’ont laissée tranquille.",al={"pourquoi la panthère a un bidule","comment la panthère l’a obtenu"}},{q="Qui veut récupérer l’Hypercapaciteur bidulotron ?",a="Wizlo Braquecoquard veut récupérer l’Hypercapaciteur bidulotron. Seul survivant de la caravane, il a trouvé refuge au Poste de Blanc-relais, un campement tauren dans le nord-ouest des Mille pointes.",al={"qui veut le bidule","bidule de wizlo"}},{q="Pourquoi les centaures ne l’ont-ils pas volé ?",a="Les centaures ont pillé la caravane, mais ils craignaient la panthère féroce dans sa cage. Ils ont laissé la bête et son collier de métal intacts parmi les ruines.",al={"pourquoi les centaures ne l’ont pas pris","centaures et panthère"}}},fx={["240fe489"]={q="D'où vient l'Hypercapaciteur bidulotron et qui l'a fabriqué ?",a="L'appareil était en possession du bricoleur gobelin Wizlo Braquecoquard, qui voyageait avec une caravane à travers les Mille pointes avant que des centaures ne les attaquent. Bien que Wizlo le revendique comme son précieux bidulotron, son inventeur précis reste un mystère ; même Wizlo admet qu'il ne comprend pas totalement ce que cette machine curieuse fait réellement.",al={"qui a fabriqué l'hypercapaciteur bidulotron","origine de l'hypercapaciteur bidulotron","où wizlo a-t-il obtenu l'hypercapaciteur"}}},fp="20,178,25.378.0,21.227.0,33.172.0,50.235.0,40.175.0,32.147.0"}
P.entries["item:ignition-key"] = {n="Clé de contact",s="À La Videfange, Wizzlecrank attend la Clé de contact pour libérer une déchiqueteuse volée.",h="À La Videfange, Wizzlecrank attend la Clé de contact pour libérer une déchiqueteuse volée.",kw={"clé de contact","déchiqueteuse","la videfange","krachevalve","supervisor lugwizzle","kapitalrisk","wizzlecrank"},ang={["profession:Engineering"]="La Clé de contact déverrouille une déchiqueteuse dotée de commandes perfectionnées. Sa régulation de vitesse et la précision du mouvement de son bras surpassent celles des modèles gobelins habituels."},sec={{t="Un rouage de l’espionnage",b="Wizzlecrank, agent de Krachevalve à Cabestan, attend à l’intérieur d’une déchiqueteuse de la KapitalRisk, à La Videfange. Envoyé pour voler la machine, il a découvert que sa colonne de manœuvre était verrouillée. Il a donc feint une panne mécanique sous le regard des contremaîtres, dans l’espoir que quelqu’un apporte la Clé de contact.\n\nLe Supervisor Lugwizzle garde la clé au sommet du derrick pétrolier central. Elle déverrouille la colonne de manœuvre de la déchiqueteuse et permet à Wizzlecrank de contrôler son bras, sa vitesse et sa rotation."}},faq={{q="Où trouver la Clé de contact ?",a="Le Supervisor Lugwizzle garde la Clé de contact dans la salle de contrôle, au sommet du derrick pétrolier de La Videfange, où il supervise les travaux de forage.",al={"emplacement de la clé de contact","qui laisse tomber la clé de contact","comment obtenir la clé de contact"}},{q="Pourquoi Wizzlecrank a-t-il besoin de cette clé précise ?",a="La déchiqueteuse perfectionnée de la KapitalRisk possède une colonne de manœuvre verrouillée. Sans la clé, Wizzlecrank ne peut pas contrôler sa rotation, sa vitesse, sa stabilité ni son bras assez bien pour l’éloigner.",al={"pourquoi avoir besoin de la clé","à quoi sert la clé","utilité de la clé de déchiqueteuse"}},{q="Qui veut faire voler la déchiqueteuse ?",a="Krachevalve, un ingénieur gobelin de Cabestan, a organisé le vol pour obtenir les plans d’ingénierie supérieurs de la KapitalRisk.",al={"qui a envoyé wizzlecrank","pourquoi voler la déchiqueteuse","déchiqueteuse de cabestan"}},{q="Que se passe-t-il une fois la clé remise ?",a="Avec la clé, Wizzlecrank déverrouille la colonne de manœuvre et démarre le moteur de la déchiqueteuse. Il doit ensuite foncer à travers les travailleurs hostiles de La Videfange pour s’échapper en direction de Cabestan.",al={"après avoir remis la clé","the escape","que faire ensuite"}}},fx={["762c90b7"]={q="Qu'est-ce que la Clé de contact ?",a="La Clé de contact est une clé opérationnelle utilisée pour déverrouiller la colonne de mouvement d'un déchiqueteur de la KapitalRisk dans La Videfange. Sans elle, les commandes de la lourde machine d'abattage restent verrouillées, laissant le pilote incapable de diriger ou de conduire.",al={"qu'est-ce que la clé de contact","utilisation de la clé de contact","clé de déchiqueteur"}},["8801ec8f"]={q="D'où vient la Clé de contact ?",a="La clé appartient aux opérations de forage et d'abattage de la KapitalRisk dans La Videfange. Elle est détenue par le Superviseur Lugwizzle, qui supervise le site depuis la salle de contrôle au sommet du derrick pétrolier central.",al={"qui a fabriqué la clé de contact","origine de la clé de contact","d'où vient la clé"}}},fp="12,80,28.444.0,36.136.0,44.180.0,30.124.0,39.169.1"}
P.entries["item:ilkrud-magthrull-s-tome"] = {n="Tome d'Ilkrud Magthrull",s="Au Sanctuaire de Scarfeu, Delgren le Purificateur s’intéresse au Tome d’Ilkrud Magthrull. Ses pages relient le démoniste aux sectateurs de la Tour d’Althalaxx.",h="Au Sanctuaire de Scarfeu, Delgren le Purificateur s’intéresse au Tome d’Ilkrud Magthrull.",kw={"orneval","delgren le purificateur","sanctuaire de scarfeu","ilkrud magthrull","poste de maestra","tome","tour d'althalaxx","démoniste"},ang={["class:Paladin"]="Paladin, vous aidez frère Delgren, un compagnon d’armes de la Lumière sacrée qui combat l’ombre et la corruption dans les étendues sauvages d’Orneval.",["class:Warlock"]="Démoniste, vous pouvez étudier le grimoire de Magthrull, qui consigne de sombres pactes ainsi que l’asservissement de marcheurs du Vide et de succubes au Sanctuaire de Scarfeu corrompu."},sec={{t="Un Grimoire de Corruption",b="Au Sanctuaire de Scarfeu, dans le sud-ouest d’Orneval, Ilkrud Magthrull tient une position sur des terres empoisonnées par l’influence démoniaque. Le redoutable démoniste orc est entouré de serviteurs invoqués. Son tome personnel consigne d’ignobles rituels et des communications ténébreuses. Delgren le Purificateur, paladin de l’Aube d’argent, sait depuis longtemps que Magthrull se trouve là. Il est urgent de récupérer le livre, car il relie le démoniste aux sombres sectateurs rassemblés à la Tour d’Althalaxx."},{t="Démêler les complots",b="Après la mort de Magthrull, son tome est remis à Delgren au Poste de Maestra. Delgren étudie les écrits du démoniste pour comprendre le réseau qui coordonne l’activité démoniaque de part et d’autre de la frontière entre Sombrivage et Orneval. Le texte révèle des renseignements essentiels sur les conspirateurs de l’ombre qui dirigent la corruption se répandant dans le nord de Kalimdor."}},faq={{q="À qui appartient ce tome ?",a="Le tome appartient à Ilkrud Magthrull. Ce puissant démoniste orc s’est établi parmi les ruines démoniaques du Sanctuaire de Scarfeu, dans le sud-ouest d’Orneval.",al={"qui est ilkrud magthrull","qui a écrit le tome","ilkrud magthrull"}},{q="Où trouve-t-on le tome ?",a="Le tome est récupéré sur Ilkrud Magthrull, au Sanctuaire de Scarfeu, au sud du sanctuaire d’Aessina, en Orneval.",al={"emplacement du tome","comment obtenir le tome","où trouver ilkrud"}},{q="Pourquoi Delgren le Purificateur veut-il le livre ?",a="Delgren veut étudier les écrits de Magthrull et découvrir les liens entre les adorateurs locaux des démons et les sectateurs de la Tour d’Althalaxx.",al={"pourquoi delgren veut le tome","que contient le tome","but du livre de delgren"}},{q="Que se passe-t-il après la récupération du tome ?",a="Au Poste de Maestra, Delgren examine le texte pour déchiffrer les communications démoniaques de Magthrull et découvrir comment démanteler le réseau des sectateurs.",al={"remettre le tome","que fait delgren du livre"}}},fx={["5352c240"]={q="D'où vient le Tome d'Ilkrud Magthrull et qui l'a fabriqué ?",a="Le livre contient les écrits personnels et les recherches obscures d'Ilkrud Magthrull, un puissant démoniste orc résidant au milieu de la corruption démoniaque du Sanctuaire de Scarfeu dans le sud-ouest de l'Orneval. Rédigé par le démoniste lui-même, le volume compile ses sorts noirs et ses notes, gardés à portée de main jusqu'à sa chute.",al={"qui a écrit le tome d'ilkrud magthrull","origine du tome d'ilkrud","d'où vient le tome"}}},fp="23,159,24.434.0,19.342.1,19.142.0,24.109.0,44.139.0,41.138.0"}
P.entries["item:incantations-from-the-nether"] = {n="Les Incantations du Néant",s="Sous Orgrimmar, la Lame brûlante détient les Incantations du Néant, un grimoire de magie démoniaque. Sylvanas Coursevent et Varimathras convoitent son savoir gangrené pour les Réprouvés.",h="Sous Orgrimmar, la Lame brûlante détient les Incantations du Néant, un grimoire de magie démoniaque.",kw={"les incantations du néant","gouffre de ragefeu","lame brûlante","conseil des ombres","les sorts de l'ombre","sylvanas","le pouvoir de détruire","varimathras"},ang={["class:Warlock"]="Les tomes provenant directement du Néant recèlent une puissante magie gangrenée, convoitée par les adeptes ambitieux des arts obscurs.",["race:Undead"]="Récupérer le livre aide le cercle rapproché de la Dame noire à Fossoyeuse. Ces connaissances obscures sont nécessaires pour mener la guerre contre le Fléau."},sec={{t="Dons de la Légion",b="La Lame brûlante œuvre dans les tunnels enflammés du Gouffre de Ragefeu, sous les rues de pierre rouge d’Orgrimmar. Cette secte souterraine est liée au Conseil des ombres. Ses sectateurs convoitent les Incantations du Néant, un grimoire de rites démoniaques offert par des agents de la Légion ardente. Ils se servent de ses secrets pour comploter une trahison dans la capitale orque. La rumeur de ce tome est parvenue aux quartiers royaux de Fossoyeuse."},{t="Ambitions des Réprouvés",b="Varimathras envoie de loyaux aventuriers de la Horde au fond du Gouffre de Ragefeu récupérer les Incantations du Néant et leur volume jumeau, Les Sorts de l’Ombre. Sylvanas Coursevent et son lieutenant seigneur de l’effroi estiment que de telles reliques gangrenées sont gâchées entre les mains de sectateurs à la vision médiocre. La Dame noire entend manier le pouvoir du Néant forgé dans le livre contre le Roi-liche et faire payer le Fléau."}},faq={{q="Où trouve-t-on le livre Les Incantations du Néant ?",a="Les sectateurs et démonistes de la Lame brûlante portent les Incantations du Néant dans le Gouffre de Ragefeu, le réseau de cavernes volcaniques sous Orgrimmar.",al={"où trouver les incantations du néant","qui donne les incantations du néant","lieu des incantations du néant"}},{q="Qui convoite ce livre, et pourquoi ?",a="Dame Sylvanas Coursevent et le seigneur de l’effroi Varimathras convoitent le livre. Ils jugent les sectateurs de la Lame brûlante mesquins et à la vision médiocre, et veulent sa magie démoniaque pour combattre le Roi-liche.",al={"qui a besoin des incantations du néant","pourquoi sylvanas veut-elle ce livre","quête du livre de varimathras"}},{q="Qu’est-ce que la Lame brûlante ?",a="La Lame brûlante est une secte secrète de démonistes et de sectateurs qui œuvre sous Orgrimmar et est alliée au Conseil des ombres. Ses membres servent la Légion ardente et cherchent secrètement à saper la nouvelle Horde de Thrall.",al={"histoire de la lame brûlante","qui sont les membres de la lame brûlante"}},{q="Quel autre livre accompagne celui-ci ?",a="Varimathras réclame deux volumes : les Incantations du Néant et les Sorts de l’Ombre. Il faut les prendre tous deux aux sectateurs du Gouffre de Ragefeu pour accomplir sa mission.",al={"autre livre pour varimathras","pouvoir de détruire les livres"}}},fx={e0d58fa2={q="Que sont Les Incantations du Néant ?",a="Les Incantations du Néant sont un grimoire sombre contenant de la magie gangrenée offerte par la Légion ardente. Il est tombé entre les mains de la Lame ardente, un culte caché du Conseil des ombres opérant au plus profond des gouffres ardents sous Orgrimmar. Aux côtés de son tome frère, Les Sorts de l'Ombre, le livre contient de puissants rituels démoniaques que les démonistes du culte étudient pour exploiter les pouvoirs du Néant distordu.",al={"que sont les incantations du néant","livre les incantations du néant","quel genre de livre sont les incantations du néant"}}},fp="28,178,19.393.0,17.383.1,53.136.0,28.188.0,26.215.0,40.164.0"}
P.entries["item:incendia-agave"] = {n="Agave d'incendia",s="Sous la Cime de Noir-nuage, l'Agave d'incendia pousse dans le Boiling Pool. Un chaman compétent peut l'enchanter pour allumer le feu sacré de la vie.",h="Sous la Cime de Noir-nuage, l'Agave d'incendia pousse dans le Boiling Pool.",kw={"arikara","boiling pool","cime de noir-nuage","agave d'incendia","magatha totem-sinistre","sacred fire","mille pointes"},ang={["class:Shaman"]="En tant que chaman, vous pouvez utiliser l'art élémentaire brut pour transformer cette plante aquatique en une poudre assez puissante pour allumer les flammes sacrées d'un rituel.",["profession:Herbalism"]="En tant qu'herboriste, votre instinct de pistage vous aide à repérer les touffes épineuses d'Agave d'incendia sur le fond trouble du Boiling Pool."},sec={{t="Une herbe rare du désert",b="Dans les Mille pointes, l'Agave d'incendia pousse dans le Boiling Pool et aux alentours, sous la Cime de Noir-nuage. Des élémentaires de vapeur errants gardent cette plante rare et la rendent difficile à récolter. Bien qu'elle pousse sous l'eau, elle porte des éléments naturels adaptés aux rituels de flammes."},{t="Feu sacré",b="L'Ancienne Magatha Totem-sinistre, sur la Cime des Anciens à Pitons-du-Tonnerre, peut enchanter des brassées d'Agave d'incendia récoltées pour en faire une poudre mystique. Les ritualistes taurens utilisent cette poudre pour allumer le brasero cérémoniel et invoquer le serpent des vents vengeur Arikara."}},faq={{q="Où pousse l'Agave d'incendia ?",a="L'Agave d'incendia pousse dans le lac du Boiling Pool et aux alentours, sous la Cime de Noir-nuage, dans le nord des Mille pointes. Une grande partie de la plante est immergée au fond du lac.",al={"où trouver l'agave","emplacement de l'agave d'incendia","où se trouve l'agave"}},{q="À quoi sert l'Agave d'incendia ?",a="Dix brassées d'Agave d'incendia sont récoltées et transformées en poudre rituelle. À Pitons-du-Tonnerre, Magatha Totem-sinistre l'enchante pour allumer le feu sacré de la vie et invoquer Arikara.",al={"utilité de l'agave d'incendia","pourquoi récolter l'agave","à quoi sert l'agave"}},{q="Qui peut enchanter l'Agave d'incendia ?",a="Sur la Cime des Anciens à Pitons-du-Tonnerre, Magatha Totem-sinistre possède le savoir rituel nécessaire pour enchanter l'Agave d'incendia. C'est une chaman influente.",al={"qui enchante l'agave","magatha agave","qui transforme l'agave en poudre"}},{q="Quels dangers entourent l'Agave d'incendia ?",a="Des élémentaires de vapeur hostiles rôdent dans les eaux et sur les rives du Boiling Pool. Ils résistent particulièrement bien aux sorts de givre et de feu.",al={"dangers de l'agave","qui garde l'agave","dangers du boiling pool"}}},fx={d4005c78={q="Qu'est-ce que l'Agave d'incendia ?",a="L'Agave d'incendia est une herbe épineuse exceptionnellement rare qui ne prospère qu'autour et à l'intérieur des eaux fumantes du Boiling Pool dans les Mille pointes. Bien qu'elle pousse dans les profondeurs au bord du lac, elle recèle de puissantes propriétés ardentes latentes, ce qui en fait un composant essentiel pour les rituels nécessitant un pouvoir élémentaire une fois correctement raffinée par un chaman qualifié.",al={"qu'est-ce que l'agave d'incendia","plante agave d'incendia","quel genre de plante est l'agave d'incendia"}}},fp="14,136,18.272.0,15.238.1,31.165.0,32.172.0,35.131.0,41.131.0"}
P.entries["item:incendia-powder"] = {n="Poudre d'incendia",s="À la Cime de Noir-nuage, la Poudre d'incendia invoque un esprit sacré. Magatha Totem-sinistre l'enchante sur la Cime des Anciens, aux Pitons-du-Tonnerre, pour qu'elle soit utilisée dans les Mille pointes.",h="À la Cime de Noir-nuage, la Poudre d'incendia invoque un esprit sacré.",kw={"arikara","cime de noir-nuage","poudre d'incendia","motega crin-de-feu","feu sacré de la vie","mille pointes","poste de blanc-relais"},ang={["class:Shaman"]="En tant que chaman, vous voyez la flamme élémentaire et les protections spirituelles s'unir pour éveiller des êtres ancestraux endormis.",["race:Tauren"]="En tant que tauren, vous savez que les poudres rituelles peuvent raviver les feux funéraires, là où la tradition sacrée rejoint la défense des chefs tribaux."},sec={{t="Une étincelle d'invocation",b="La Poudre d'incendia porte la magie chamanique jusqu'au feu sacré au sommet de la Cime de Noir-nuage. Sur la Cime des Anciens, aux Pitons-du-Tonnerre, Magatha Totem-sinistre la confie aux voyageurs. Répandez-la sur le brasero consacré où reposent les morts, et elle fera apparaître Arikara, un serpent ailé vengeur."},{t="Présages inquiétants",b="Magatha Totem-sinistre a conçu les rites à l'origine de la Poudre d'incendia. Elle pensait que les changements dans les coutumes taurens avaient poussé d'anciens esprits à traquer le grand chef Cairne Sabot-de-Sang. Elle a donc enchanté la poudre pour attirer l'apparition au grand jour et la détruire. Le féroce serpent apparaît, mais des questions demeurent sur les raisons du réveil d'Arikara."}},faq={{q="À quoi sert la Poudre d'incendia ?",a="À la Cime de Noir-nuage, dans les Mille pointes, répandez la Poudre d'incendia dans le feu sacré de la vie. La flamme fera apparaître Arikara, le serpent spirituel vengeur.",al={"utilité de la poudre d'incendia","pourquoi ai-je besoin de poudre d'incendia","que fait la poudre d'incendia"}},{q="Qui a préparé l'enchantement de la poudre ?",a="Magatha Totem-sinistre a transformé l'agave d'incendia récoltée en poudre raffinée sur la Cime des Anciens, aux Pitons-du-Tonnerre. Motega Crin-de-feu, du Poste de Blanc-relais, avait signalé la présence d'Arikara.",al={"qui a créé la poudre d'incendia","qui a enchanté la poudre d'incendia"}},{q="Où faut-il utiliser la poudre ?",a="Répandez la poudre dans le brasero sacré d'une aiguille funéraire isolée, au sein de la Cime de Noir-nuage, très haut au-dessus des canyons salés des Mille pointes.",al={"emplacement de la poudre d'incendia","où jeter la poudre d'incendia","où utiliser la poudre d'incendia"}},{q="Pourquoi fallait-il invoquer Arikara ?",a="Magatha Totem-sinistre craint que les changements dans les traditions taurens aient irrité Arikara, et que le serpent traque Cairne Sabot-de-Sang. Elle demande qu'Arikara soit invoqué et tué avant qu'il ne fasse du mal à Cairne.",al={"pourquoi invoquer arikara","pourquoi combattre arikara"}}},fx={["53c7ed7b"]={q="Qu'est-ce que la Poudre d'incendia ?",a="La Poudre d'incendia est un réactif raffiné et purifié, imprégné de magie rituelle. Lorsqu'elle est dispersée sur le Sacred Fire de vie au sommet de la Cime de Noir-nuage dans les Mille pointes, son enchantement tissé agit comme un signal qui attire Arikara, l'esprit serpent du vent vengeur.",al={"qu'est-ce que la poudre d'incendia","histoire de la poudre d'incendia","qu'est-ce que la poudre"}}},fp="15,164,20.287.0,15.324.1,33.156.0,43.164.0,38.153.0,36.192.0"}
P.entries["item:insane-scribbles"] = {n="Gribouillages déments",s="À Sombrivage, des sectateurs transportent des Gribouillages déments arrachés au Twilight Tome, un fragment de sombre littérature. L’écriture dansante et les motifs déformés troublent l’esprit. Les anciens protecteurs de la forêt étudient les pages pour découvrir les desseins du Marteau du crépuscule.",h="À Sombrivage, des sectateurs transportent des Gribouillages déments arrachés au Twilight Tome, un fragment de...",kw={"sombrivage","gribouillages déments","folie","old gods","onu","twilight tome","marteau du crépuscule"},ang={["class:Priest"]="En tant que prêtre, vous reconnaîtrez peut-être dans cette écriture tortueuse une dangereuse attaque de folie, opposée à la clarté de la Lumière.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous savez que les reliques du Marteau du crépuscule menacent la paix ancienne de Sombrivage et ses terres sacrées."},sec={{t="Un manuscrit dément",b="Le Twilight Tome peut menacer la santé mentale des mortels. Son écriture se contorsionne sur le parchemin, et ses volutes gracieuses se muent sous les yeux du lecteur en images grotesques. Même une seule feuille arrachée, appelée Gribouillages déments, laisse son porteur étourdi et désorienté. Le texte a peu de sens, mais le parchemin vibre d’une magie primordiale et immémoriale, liée aux puissances ténébreuses enfouies sous Azeroth."},{t="Des indices pour les Anciens",b="Onu, l’Ancien qui veille sur le Bosquet des Anciens, étudie les gribouillages pour repérer ce qui ravage Sombrivage. Onu reconnaît dans l’énergie chaotique qui imprègne le parchemin l’œuvre des Old Gods. Les défenseurs de Kalimdor cherchent donc à reconstituer les gribouillages et à découvrir pourquoi le Marteau du crépuscule s’est rassemblé le long des rivages embrumés."}},faq={{q="Que se passe-t-il si vous essayez de lire ces gribouillages ?",a="Le texte se laisse difficilement traduire. Quand vous regardez le parchemin, ses lettres ondulent et les motifs qui les entourent se tordent en formes horrifiantes. Bientôt, vous êtes pris de vertiges et d’épuisement mental à force d’essayer de les déchiffrer.",al={"lire les gribouillages déments","que dit le texte","peut-on lire les gribouillages"}},{q="D’où ces gribouillages ont-ils été arrachés ?",a="Les gribouillages ont été arrachés au Twilight Tome, un grimoire immonde conservé par les sectateurs du Marteau du crépuscule qui opèrent à Sombrivage.",al={"origine des gribouillages","origine du twilight tome"}},{q="Qui peut comprendre ou étudier les gribouillages ?",a="Onu, l’Ancien du savoir, examine le parchemin récupéré. Fort de siècles de savoir, Onu perçoit l’ancienne magie primordiale qui lie l’encre et cherche à découvrir les desseins de la secte dans la région.",al={"qui veut les gribouillages","onu et les gribouillages"}},{q="Quel genre de pouvoir émane du parchemin ?",a="Le parchemin pulse d’une magie chaotique et primordiale liée aux Old Gods, les divinités ténébreuses adorées par le Marteau du crépuscule.",al={"quelle magie imprègne les gribouillages","type de magie"}}},fx={["12486380"]={q="Que sont les Gribouillages déments ?",a="Il s'agit d'une page unique et démence, arrachée au texte sombre connu sous le nom de Tome du Crépuscule. L'écriture qui y figure nage, danse et se tord en formes grotesques sous vos yeux, dégageant une aura magique chaotique et primordiale qui menace de submerger vos sens si vous fixez la page trop longtemps.",al={"que sont les gribouillages déments","lore des gribouillages déments","qu'est-ce que ce parchemin"}},b40c7e7e={q="Pourquoi Onu veut-il les Gribouillages déments ?",a="L'ancien Onu perçoit la touche chaotique des Dieux très anciens tissée dans le parchemin. Il cherche à étudier ces écrits retrouvés dans l'espoir de déchiffrer ce que le culte secret du Marteau du crépuscule manigance au sein des forêts et des rivages de Sombrivage.",al={"pourquoi onu veut les gribouillages déments","qui veut les gribouillages","pourquoi apporter les gribouillages à onu"}}},fp="16,246,22.397.0,22.356.1,48.213.0,37.122.0,42.200.0,47.123.0"}
P.entries["item:inscribed-bark"] = {n="Ecorce gravée",s="À Teldrassil, l’Ecorce gravée porte à l’Archidruide Fandral Forteramure le rapport de l’Oracle Tree. Il décrit la santé des branches et les menaces qui troublent encore les bois.",h="À Teldrassil, l’Ecorce gravée porte à l’Archidruide Fandral Forteramure le rapport de l’Oracle Tree.",kw={"cercle cénarien","darnassus","fandral forteramure","ecorce gravée","oracle tree","teldrassil"},ang={["class:Druid"]="En tant que druide, vous reconnaissez dans l’Ecorce gravée le message urgent d’un ancien allié. Il évoque l’équilibre fragile et les afflictions qui troublent le jeune Arbre-Monde.",["race:NightElf"]="En tant que Kaldorei, vous savez que les messages gravés sur l’écorce ancienne lient la nature à ses gardiens. Ils relient les bosquets sauvages aux terrasses de marbre de Darnassus."},sec={{t="Un message de l’Oracle Tree",b="L’Oracle Tree envoie l’Ecorce gravée au Cercle cénarien, à Darnassus. Après que vous avez chassé les harpies de leurs nids, l’arbre ancien vous confie son message. Il craint que les sentiers contaminés de Teldrassil ne soient dangereux pour les coursiers ordinaires. Le rapport informe l’Archidruide Fandral Forteramure des victoires récentes et du fléau plus profond qui étreint encore les bois."}},faq={{q="Qu’est-ce que l’Ecorce gravée ?",a="L’Ecorce gravée porte à l’Archidruide Fandral Forteramure, à Darnassus, le rapport de l’Oracle Tree. Il décrit la santé des branches et les dangers qui les menacent.",al={"qu’est-ce que l’écorce gravée","écorce de l’oracle tree","utilité de l’écorce gravée"}},{q="Qui envoie ce message et pourquoi ?",a="L’Oracle Tree vous confie l’Ecorce gravée après que vous avez chassé les harpies de leurs nids. Méfiant à l’idée d’envoyer des messagers ordinaires sur les sentiers menacés de la forêt, il remet son rapport à un voyageur qui a fait ses preuves.",al={"qui a écrit l’écorce gravée","qui donne l’écorce gravée","messager de l’oracle tree"}},{q="Comment l’Archidruide Fandral Forteramure réagit-il au message ?",a="Fandral reconnaît le répit apporté par l’élimination des harpies, mais affirme que des problèmes plus profonds persistent. Le rapport ravive son inquiétude : son travail sur Teldrassil pourra-t-il rendre aux elfes de la nuit l’immortalité qu’ils ont perdue ?",al={"réaction de fandral à l’écorce","que dit fandral au sujet de l’écorce"}}},fp="14,166,25.352.0,23.152.0,31.202.0,58.213.1"}
P.entries["item:insect-analysis-report"] = {n="Rapport d'analyse d'insecte",s="Le Rapport d'analyse d'insecte révèle une menace grandissante et urgente en Tanaris. Le Grand Géomètre Radiésthéflop en fait une copie pour que l'avertissement parvienne à d'autres.",h="Le Rapport d'analyse d'insecte révèle une menace grandissante et urgente en Tanaris.",kw={"radiésthéflop","gadgetzan","rapport d'analyse d'insecte","analyse de parties d'insectes","pestlezugg","silithid","tanaris","zilzibin drumlore"},ang={["faction:Alliance"]="L'avertissement du rapport concerne les silithid, que Zilzibin Drumlore identifie comme une menace pour l'Alliance comme pour la Horde.",["faction:Horde"]="Le rapport vise à avertir votre faction au sujet des silithid, une menace qui, selon Zilzibin Drumlore, pèse sur la Horde comme sur l'Alliance."},sec={{t="Un avertissement de Tanaris",b="À Gadgetzan, le Grand Géomètre Radiésthéflop demande que le rapport soit largement diffusé. L'Alchimiste Pestlezugg estime que toute personne sachant lire doit connaître le danger. Radiésthéflop accepte d'en faire une copie que vous pourrez remettre à votre faction."},{t="Le savant du quartier de Drag",b="À Orgrimmar, Zilzibin Drumlore étudie les formes de vie et l'histoire d'Azeroth. Il reconnaît dans le rapport les créatures appelées silithid et avertit qu'elles pourraient rapidement dévorer le désert de Tanaris. Il les décrit comme les instruments d'une menace qui pèse sur la Horde comme sur l'Alliance."}},faq={{q="Qu'est-ce que le Rapport d'analyse d'insecte ?",a="Le Rapport d'analyse d'insecte décrit les silithid, une grave menace qui se répand depuis Tanaris.",al={"rapport sur les insectes","rapport d'analyse","que contient le rapport"}},{q="Qui a rédigé le rapport ?",a="Le Grand Géomètre Radiésthéflop envoie le rapport pour qu'il soit étudié et diffusé plus largement.",al={"qui a rédigé le rapport","rapport de radiésthéflop","d'où vient le rapport"}},{q="Pourquoi Radiésthéflop fait-il une copie ?",a="L'Alchimiste Pestlezugg demande une copie afin que l'avertissement soit diffusé parmi les membres de votre faction.",al={"pourquoi copier le rapport","obtenir un double","partager le rapport"}},{q="Qui est Zilzibin Drumlore ?",a="Zilzibin Drumlore est un érudit troll d'Orgrimmar qui étudie les formes de vie et l'histoire d'Azeroth.",al={"qui est zil","histoire de zilzibin","érudit troll"}},{q="Quelles créatures le rapport décrit-il ?",a="Zilzibin identifie les créatures du rapport comme des silithid, qui menacent Tanaris ainsi que la Horde et l'Alliance.",al={"quels insectes","rapport sur les silithid","que sont ces insectes"}}},fp="22,163,22.232.0,23.264.1,35.89.0,21.87.0,34.93.0,25.95.0,40.116.0"}
P.entries["item:intact-raptor-horn"] = {n="Corne de raptor intacte",s="Dans les Tarides, les chasseurs recherchent des Raptor Horns entières. Mebok Mizzyrix, de Cabestan, espère en tirer des toniques, se fiant aux rumeurs selon lesquelles ces raptors seraient rusés.",h="Dans les Tarides, les chasseurs recherchent des Raptor Horns entières.",kw={"corne intacte","ishamuhale","mebok mizzyrix","corne de raptor","cabestan","smart drinks","sunscale scytheclaw","takk the leaper"},ang={["class:Hunter"]="En tant que chasseur, prélever une corne de trophée intacte exige de tuer proprement certains des prédateurs les plus féroces des savanes.",["profession:Cooking"]="En tant que cuisinier, vous entendrez peut-être dire que Mebok prévoit de réduire les cornes en poudre pour les faire infuser dans du vin. Les survivants pragmatiques préfèrent utiliser les parties de raptor pour fabriquer des outils plutôt que pour préparer des mets appétissants."},sec={{t="Un ingrédient douteux",b="Les chasseurs prisent les peaux, les serres et les trophées de raptor, mais il est plus difficile de prélever des Raptor Horns entières sur le terrain. Mebok Mizzyrix est un alchimiste gobelin excentrique de Cabestan. Il croit que les raptors des Tarides sont plus rusés que leurs congénères d’ailleurs et soupçonne que leur intelligence réside dans leurs cornes. Il espère donc broyer des cornes entières pour en faire des toniques et mettre en bouteille ce prétendu génie dans des boissons à vendre."},{t="À la poursuite des meutes",b="Une corne destinée au brassage doit provenir d’un prédateur particulièrement féroce, pas de n’importe quel jeune raptor. Les Sunscale Scytheclaws rôdent dans les plaines du sud et aux frontières du nord, près d’Orneval. Takk the Leaper et l’insaisissable Ishamuhale sont de redoutables terreurs de la savane. Leurs cornes robustes peuvent résister intactes aux affrontements de la chasse."}},faq={{q="Qui veut ces Raptor Horns intactes ?",a="Mebok Mizzyrix, marchand gobelin et brasseur en herbe de Cabestan, recherche des cornes intactes. Il croit qu’elles détiennent la clé de sa prochaine combine pour gagner de l’argent.",al={"qui veut des cornes de raptor","acheteur de cornes","qui achète des cornes de raptor"}},{q="Pourquoi les cornes doivent-elles être intactes ?",a="Mebok prévoit de broyer des cornes entières en une poudre fine à avaler. Les chasseurs jettent les cornes ébréchées ou brisées, ou les considèrent comme épuisées, car elles n’ont pas toute la puissance qu’il espère exploiter dans ses recettes.",al={"pourquoi intactes","cornes brisées"}},{q="Quels raptors en portent ?",a="Les Sunscale Scytheclaws adultes en portent aux extrémités nord et sud des Tarides. Des raptors tristement célèbres, dont Ishamuhale et Takk the Leaper, en portent aussi.",al={"où trouver des cornes","quels raptors","qui donne des cornes intactes"}},{q="Les cornes de raptor rendent-elles vraiment plus intelligent ?",a="Les raptors des Tarides font preuve d’une ruse et d’une coordination inhabituelles en meute. Personne n’a prouvé que leur intelligence réside dans leurs cornes ni qu’elle puisse se transmettre à quelqu’un par une boisson.",al={"les smart drinks fonctionnent-elles","les raptors sont-ils intelligents","intelligence des raptors"}}},fx={["41f89fc5"]={q="Qu'est-ce qu'une Corne de raptor intacte ?",a="Une Corne de raptor intacte est une corne crânienne non endommagée prélevée sur les raptors prédateurs qui rôdent dans les Tarides. Ces cornes sont prisées par les habitants entreprenants qui pensent que leur état impeccable préserve l'essence naturelle et la ruse de ces bêtes.",al={"corne de raptor intacte qu'est-ce que c'est","qu'est-ce qu'une corne de raptor"}},b3ef4089={q="D'où viennent les cornes de raptor intactes ?",a="Ces cornes poussent naturellement sur la tête des raptors des Tarides, notamment les griffes-faucheuses écailles-de-soleil ainsi que des bêtes notoires comme Ishamuhale et Takk le Sauteur. Ce sont des trophées biologiques prélevés directement sur les raptors abattus dans toutes les savanes.",al={"d'où viennent les cornes de raptor","qui laisse tomber une corne de raptor intacte"}}},fp="18,157,25.376.0,19.322.0,36.152.0,35.210.0,25.168.0,42.162.0"}
P.entries["item:intrepid-strongbox-key"] = {n="Clé du coffre de l'Intrépide",s="Sur l’épave de l’Intrépide, le capitaine Halyndor porte toujours la clé de son coffre. Cette clé rouillée en fer gardait jadis un objet mystérieux à bord du navire de l’Alliance condamné, au large des Paluns.",h="Sur l’épave de l’Intrépide, le capitaine Halyndor porte toujours la clé de son coffre.",kw={"capitaine halyndor","équipage maudit","glorin front-d'acier","intrépide","épave","coffre","the third fleet","les paluns"},ang={["class:Priest"]="En tant que prêtre, vous pouvez apporter l’artefact maudit à Glorin Front-d’acier, à Port de Menethil, pour qu’il le purifie. Ainsi, les âmes de l’équipage seront libérées de leur tourment.",["faction:Alliance"]="En tant que membre de l’Alliance, vous savez que la clé appartenait à un commandant de The Third Fleet, disparue au large de Port de Menethil. Sa perte reste une blessure vive pour les survivants du port."},sec={{t="Le secret d’un capitaine",b="L’Intrépide a sombré avec The Third Fleet au large des Paluns. Son équipage est devenu des esprits maudits et tourmentés. Le capitaine Halyndor veillait sur un objet mystérieux, enfermé dans le lourd coffre du navire. À présent, son fantôme arpente le pont inondé, la clé rouillée qui l’ouvre à la main."},{t="Briser le lien",b="La clé du capitaine Halyndor ouvre le coffre de l’Intrépide. Une relique maudite, à l’intérieur, retient l’équipage dans son tourment. Glorin Front-d’acier, un prêtre nain à Port de Menethil, peut purifier la relique."}},faq={{q="Qui porte la Clé du coffre de l’Intrépide ?",a="Le capitaine Halyndor porte la clé tandis qu’il arpente le pont supérieur de l’épave du nord, au large de la côte nord-ouest des Paluns.",al={"qui a la clé","butin de la clé de l’intrépide","clé de halyndor"}},{q="Qu’ouvre la Clé du coffre de l’Intrépide ?",a="La clé ouvre le coffre verrouillé de l’Intrépide, immergé dans la coque éventrée, sous le pont du capitaine.",al={"qu’ouvre-t-elle","emplacement du coffre de l’intrépide","où se trouve le coffre"}},{q="Pourquoi le coffre était-il fermé à clé ?",a="Le capitaine Halyndor a enfermé un objet maudit dans le coffre pour le cacher et le garder en sécurité. Après le naufrage de la flotte, le mal qui y persistait a lié l’équipage à la non-mort.",al={"que contenait le coffre","pourquoi était-il fermé"}},{q="Qui peut purifier l’objet maudit dans le coffre ?",a="Glorin Front-d’acier, un prêtre nain à Port de Menethil, peut purifier l’artefact maudit une fois le coffre déverrouillé.",al={"qui peut le purifier","coffre de glorin front-d’acier"}}},fx={b4277111={q="Qu'est-ce que la Clé du coffre de l'Intrépide ?",a="Il s'agit d'une clé de navire rouillée conservée par le capitaine Halyndor à bord de l'épave de l'Intrépide. Même après sa mort, le capitaine maudit garde la clé avec zèle, car c'est le seul moyen d'ouvrir le coffre renforcé du navire caché dans la coque brisée.",al={"clé du coffre de l'intrépide","quelle est la clé","clé de l'intrépide"}},["90ec2e74"]={q="Pourquoi la Clé du coffre de l'Intrépide est-elle nécessaire ?",a="La clé est nécessaire pour ouvrir le coffre de l'Intrépide et récupérer la relique sombre qui y est enfermée. Le second Fitzsimmons pense que cet artefact entreposé est à l'origine de l'horrible malédiction qui lie Halyndor et son équipage à l'épave, et l'ouverture du coffre est la première étape pour la lever.",al={"pourquoi ai-je besoin de la clé","pourquoi récupérer la clé","but de la clé de l'intrépide"}}},fp="22,188,18.260.0,17.194.1,39.122.0,42.110.0,34.154.0,49.114.0"}
P.entries["item:invisibility-liquor"] = {n="Potion d'invisibilité",s="Maybell Maclure échappe à la vue de sa famille grâce à la Potion d'invisibilité pour retrouver Tommy Joe Champierreux. Leurs familles restent liées par une querelle amère.",h="Maybell Maclure échappe à la vue de sa famille grâce à la Potion d'invisibilité pour retrouver Tommy Joe...",kw={"crystal kelp","forêt d’elwynn","potion d'invisibilité","maybell maclure","querelle des champierreux","the escape","tommy joe champierreux"},ang={["class:Mage"]="En tant que mage, vous savez que les arcanistes du Kirin Tor consacrent des années à maîtriser les illusions et les sorts d'invisibilité. Les habitants d'Elwynn en font une imitation rudimentaire à base d'alcool fermenté et de varech détrempé.",["race:Human"]="En tant qu'humain, vous savez que la querelle rurale entre les clans des Champierreux et des Maclure atteint des sommets d'amertume."},sec={{t="Une potion pour des amants contrariés",b="Tommy Joe Champierreux cherche à retrouver Maybell Maclure en secret. Mais la querelle de leurs familles éloigne leurs foyers, et leurs proches les surveillent de près. Le secret ordinaire ne suffit pas. La Potion d'invisibilité permet à qui la boit de traverser les terres agricoles disputées sans être vu."},{t="Une alchimie peu orthodoxe en Elwynn",b="Des Crystal Kelp Fronds provenant des eaux où vivent les murlocs entrent dans la préparation. Maybell Maclure boit la potion et disparaît. Puis elle s'éclipse dans les bois pour un rendez-vous secret."}},faq={{q="Quel est l'effet de la Potion d'invisibilité ?",a="Pendant un court moment, la Potion d'invisibilité rend invisible la personne qui la boit. Sa magie est contenue dans une boisson alcoolisée.",al={"effets de la potion","breuvage d'invisibilité","quel est son effet"}},{q="Qui utilise la Potion d'invisibilité ?",a="Maybell Maclure reçoit la Potion d'invisibilité pour échapper à la vue de sa famille et retrouver Tommy Joe Champierreux, malgré la querelle de leurs foyers.",al={"qui la boit","potion de maybell maclure"}},{q="Comment la potion est-elle préparée ?",a="Des Crystal Kelp Fronds cueillies dans les lits des rivières et sur les rives des lacs de la Forêt d’Elwynn entrent dans la préparation. Les murlocs s'emparent de ces plantes.",al={"ingrédients de la potion","potion au crystal kelp"}},{q="Les joueurs peuvent-ils boire la Potion d'invisibilité ?",a="Non. La Potion d'invisibilité est destinée à Maybell Maclure, pour qu'elle puisse s'éclipser sans que sa famille la voie.",al={"puis-je la boire","boire la potion d'invisibilité"}}},fx={["19edabb3"]={q="Qu'est-ce que la Potion d'invisibilité ?",a="La Potion d'invisibilité est un puissant breuvage alchimique concocté dans la Forêt d’Elwynn. Bien qu'il s'agisse ostensiblement d'une boisson alcoolisée, elle possède des propriétés magiques dérivées de frondes de varech cristallin, conférant temporairement à quiconque la boit une invisibilité totale aux yeux des mortels.",al={"qu'est-ce que la potion d'invisibilité","lore de la potion d'invisibilité","quel genre de boisson est la potion d'invisibilité"}},f0e7bc08={q="Pourquoi quelqu'un voudrait-il une Potion d'invisibilité ?",a="Cette liqueur est recherchée pour résoudre une romance interdite. Maybell Maclure et Tommy Joe Champierreux se retrouvent dans des camps opposés à cause de la querelle amère qui déchire leurs familles à Elwynn, et le breuvage permet à Maybell de se faufiler sans être vue par ses proches vigilants pour rendre visite à son bien-aimé.",al={"pourquoi avoir besoin de la potion d'invisibilité","qui veut la potion d'invisibilité","pourquoi veulent-ils la potion"}}},fp="19,148,32.249.0,25.180.1,33.110.0,33.143.0,23.120.0,53.91.0"}
P.entries["item:iron-pike"] = {n="Clou en fer",s="À Comté-du-Lac, les bâtisseurs ont besoin de clous en fer pour réparer le pont Everstill Bridge. Des gnolls des Carmines ont volé la cargaison venue de Hurlevent, laissant la ville à court de fer.",h="À Comté-du-Lac, les bâtisseurs ont besoin de clous en fer pour réparer le pont Everstill Bridge.",kw={"pont everstill bridge","contremaître oslow","clou en fer","rivet en fer","comté-du-lac","gnolls des carmines","les carmines"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, récupérer les fournitures volées aide à sécuriser les passages de Comté-du-Lac et à renforcer la frontière orientale de Hurlevent contre les incursions des Rochenoire.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez constater les effets de la guerre sur les forgerons locaux : ils ont dû consacrer tout leur fer brut aux armes."},sec={{t="La cargaison volée",b="Après les attaques des orcs Rochenoire, Comté-du-Lac a consacré ses réserves de métal aux armures, aux lames et aux munitions. Les bâtisseurs ont alors demandé davantage de fer à Hurlevent, mais des gnolls des Carmines ont détourné la caravane sur la route. Ils ont emporté des caisses de clous en fer et de rivets vers le nord, dans les collines, et les travaux sur le pont Everstill Bridge se sont arrêtés."},{t="Reconstruire la travée",b="Le contremaître Oslow supervise la reconstruction du pont et a besoin du matériel volé. Sans les lourds clous pour renforcer sa structure en pierre et en bois, le pont coupe en partie Comté-du-Lac de la route du nord. La ville reste aussi exposée à de nouvelles incursions."}},faq={{q="Pourquoi les gnolls transportent-ils des clous de construction ?",a="Des gnolls des Carmines ont tendu une embuscade à une caravane de ravitaillement qui allait de Hurlevent à Comté-du-Lac. Ils se sont dispersés dans les collines des Carmines avec des caisses de fournitures de construction volées, dont des clous en fer et des rivets.",al={"pourquoi les gnolls ont-ils des clous en fer","où les gnolls ont-ils trouvé des clous en fer"}},{q="Qui a besoin de ces clous en fer à Comté-du-Lac ?",a="Le contremaître Oslow a besoin des clous pour reconstruire le pont Everstill Bridge qui enjambe le lac placide. Les récentes attaques des orcs ont contraint Comté-du-Lac à fondre ses réserves de fer pour en faire des armes et des armures, sans en laisser de côté.",al={"qui veut des clous en fer","contremaître oslow clous en fer"}},{q="Où récupérer ces clous en fer ?",a="Les gnolls des Carmines gardent les clous dans leurs campements des collines et des crêtes au nord de Comté-du-Lac.",al={"où trouver des clous en fer","emplacement des clous en fer"}},{q="Pourquoi Comté-du-Lac n'a-t-il pas pu forger ses propres clous en fer ?",a="Comté-du-Lac a utilisé son fer local pour combattre les orcs Rochenoire, le fondant pour fabriquer des épées, des balles et des équipements de protection. La ville a dû demander du nouveau fer à Hurlevent pour ses travaux de construction.",al={"pourquoi comté-du-lac a-t-il commandé du fer","pénurie de fer à comté-du-lac"}}},fx={c6b2b586={q="Qu'est-ce qu'un Clou en fer ?",a="Un Clou en fer est un piquet de construction en fer lourd destiné à renforcer la maçonnerie et la pierre. Le contremaître Oslow et son équipe ont besoin de ces piquets structurels robustes pour réparer et stabiliser le pont d'Everstill, en ruine dans le Comté-du-Lac.",al={"qu'est-ce qu'un clou en fer","que sont les clous en fer","clou en fer carmines"}}},fp="9,162,20.307.0,19.266.0,47.197.0,40.193.0,40.89.0,55.180.0"}
P.entries["item:iron-pommel"] = {n="Pommeau en fer",s="En Orneval, le Pommeau en fer est le dernier fragment manquant du Bâton de Dartol. Le magicien Dartol, mort depuis longtemps, a créé le bâton, que les Elfes de la nuit d’Astranaar recherchent pour ralentir les attaques des furbolgs. Les druides du Refuge des saisons de Dor'danil gardaient le pommeau jusqu’à ce que leur sanctuaire soit envahi et qu’ils soient massacrés.",h="En Orneval, le Pommeau en fer est le dernier fragment manquant du Bâton de Dartol.",kw={"orneval","bâton de dartol","dor'danil","pommeau en fer","oso's chest","raene's cleansing","shael'dryn"},ang={["class:Druid"]="En tant que druide, vous pouvez vous souvenir des druides de Dor'Danil. Leur charge sacrée s’est achevée dans le massacre, à la lisière de la forêt.",["faction:Alliance"]="En tant que membre de l’Alliance, récupérer le pommeau rapproche le Bâton de Dartol de son achèvement. Le bâton est une aide précieuse pour défendre Orneval contre la corruption rampante."},sec={{t="Le fardeau d’un cercle massacré",b="Le Bâton de Dartol fut brisé et dispersé à travers Orneval pour protéger son pouvoir mystique. Les druides elfes de la nuit, près de la route qui mène au sud vers les Tarides, prirent en charge le Pommeau en fer. Leur cercle fut massacré au Refuge des saisons de Dor'danil, et leur abri sombra dans le silence parmi les ruines. Dans le chaos, le pommeau disparut. Des gelées bouillonnantes parcourent désormais la clairière profanée."},{t="Récupéré dans le bourbier",b="Le Pommeau en fer repose dans un coffre robuste, au creux corrompu au sud du Poste de Bois-brisé. Ceux qui fouillent les gelées corrompues découvrent le coffre intact dans la masse acide d’une gelée. Le pommeau est le dernier fragment nécessaire pour reconstituer le Bâton de Dartol."}},faq={{q="À quoi sert le Pommeau en fer ?",a="Le Pommeau en fer est le dernier fragment nécessaire pour reconstituer le Bâton de Dartol. Apportez-le à Shael'dryn, près du puits de lune, et elle pourra réparer l’antique artefact pour aider à ralentir les attaques des furbolgs contre les Elfes de la nuit d’Orneval.",al={"utilité du pommeau en fer","pourquoi ai-je besoin du pommeau en fer","à quoi sert le pommeau en fer"}},{q="Qui avait le pommeau à l’origine ?",a="Des druides elfes de la nuit, près de la route vers les Tarides, avaient la charge du pommeau. Leur cercle fut massacré avant que le bâton puisse être reconstitué, et leur refuge gît en ruines.",al={"qui gardait le pommeau","qui avait le pommeau en fer","druides de dor'danil"}},{q="Où trouve-t-on le pommeau ?",a="Le pommeau est enfermé dans un coffre transporté à l’intérieur d’une des gelées corrompues du creux souillé, à l’est de la route principale. Le creux se trouve au sud du Poste de Bois-brisé et au nord de la frontière des Tarides.",al={"emplacement du pommeau en fer","où se trouve le pommeau en fer","où trouver le pommeau en fer"}},{q="À qui dois-je apporter le pommeau ?",a="Apportez le pommeau à Shael'dryn, une dryade qui veille sur le puits de lune à l’est du Lac Iris. Elle connaît le rituel nécessaire pour reconstituer le Bâton de Dartol.",al={"rendre le pommeau en fer","où apporter le pommeau en fer","qui veut le pommeau"}}},fx={["9716c2ef"]={q="Qu'est-ce que le Pommeau en fer ?",a="Le Pommeau en fer est le dernier composant manquant requis pour reconstruire la Baguette de Dartol, un bâton créé par le magicien Dartol, mort depuis longtemps. Avant leur chute tragique, les druides résidant au Refuge des saisons de Dor'danil avaient la charge de protéger cette pièce métallique lourde. Perdu au milieu de la corruption et de la violence qui ont balayé leur sanctuaire, le pommeau a fini enfermé dans un vieux coffre dans la nature, attendant quelqu'un capable de le récupérer.",al={"qu'est-ce qu'un pommeau en fer","lore du pommeau en fer","à quoi sert le pommeau pour la baguette de dartol"}}},fp="11,302,23.366.0,23.246.1,33.213.0,30.169.0,26.199.0,29.136.0"}
P.entries["item:iron-rivet"] = {n="Rivet en fer",s="Au nord du Lac placide, des cargaisons de rivets en fer de Hurlevent sont entreposées dans des campements de gnolls. Le Contremaître Oslow en a besoin pour réparer le pont endommagé de Comté-du-Lac.",h="Au nord du Lac placide, des cargaisons de rivets en fer de Hurlevent sont entreposées dans des campements de...",kw={"pont everstill bridge","contremaître oslow","clou en fer","rivet en fer","comté-du-lac","gnolls des carmines","les carmines"},ang={["faction:Alliance"]="Récupérer les fournitures volées aidera Comté-du-Lac à réparer ses infrastructures et à contenir la menace des gnolls pour la ville.",["profession:Blacksmithing"]="Hurlevent a forgé ces lourdes fixations pour les grands travaux de construction, notamment les ponts de pierre et de bois."},sec={{t="Cargaison de la caravane volée",b="Comté-du-Lac a consacré son fer à la fabrication d’armes et d’armures lorsque les orcs Rochenoire ont attaqué. Une fois les assauts moins fréquents, le Contremaître Oslow a demandé des fournitures à Hurlevent pour réparer le pont endommagé Everstill Bridge. Les gnolls des Carmines ont attaqué la caravane avant qu’elle n’atteigne la ville. Ils ont emmené ses chariots et ses bêtes de bât dans les collines au nord du Lac placide, dispersant des rivets en fer et des piques dans leurs campements."},{t="Réparer le pont",b="De lourds rivets en fer maintiennent ensemble la structure de pierre et de bois du pont Everstill Bridge, sous le poids des charrettes et des voyageurs. Le Contremaître Oslow ne peut pas le réparer sans risque sans ces rivets. Le pont relie Comté-du-Lac aux vallées occidentales. Sa réparation aidera à protéger le périmètre de la ville contre de nouvelles incursions."}},faq={{q="À quoi servent les rivets en fer ?",a="Le Contremaître Oslow a besoin des rivets en fer pour réparer le pont Everstill Bridge endommagé de Comté-du-Lac. Le fer de la ville a été fondu pendant les combats contre les orcs Rochenoire.",al={"utilité des rivets en fer","pourquoi faut-il des rivets en fer","à quoi servent les rivets en fer"}},{q="Pourquoi les gnolls ont-ils ces rivets ?",a="Les gnolls des Carmines ont attaqué une caravane de ravitaillement de Hurlevent et se sont emparés de sa cargaison de matériaux de construction. Les rivets et les piques en fer se trouvent désormais dans leurs campements au nord de Comté-du-Lac.",al={"pourquoi les gnolls ont des rivets","comment les gnolls ont obtenu les rivets en fer","qui a volé les rivets"}},{q="Pourquoi Comté-du-Lac manquait-il de fer au départ ?",a="Les défenseurs de Comté-du-Lac ont fondu le fer entreposé dans la ville pour fabriquer des épées, des balles et des armures pendant l’invasion des orcs.",al={"pénurie de fer à comté-du-lac","pourquoi il n’y a pas de fer à comté-du-lac"}},{q="Qui recherche ces rivets ?",a="Le Contremaître Oslow, qui supervise la restauration du pont Everstill Bridge, recherche les rivets.",al={"qui veut les rivets en fer","qui prend les rivets en fer"}}},fx={["0d91405a"]={q="Qu'est-ce qu'un Rivet en fer ?",a="Un Rivet en fer est une attache métallique robuste forgée pour les travaux de construction lourds dans le royaume. Hurlevent a envoyé une cargaison de ces rivets vers le Comté-du-Lac pour aider à reconstruire l'infrastructure en ruine de la ville, en particulier le pont vital d'Everstill.",al={"rivet en fer qu'est-ce que c'est","que sont les rivets en fer","description du rivet en fer"}},a8a8e120={q="D'où viennent ces Rivets en fer, et qui les a fabriqués ?",a="Ces rivets ont été expédiés depuis Hurlevent dans le cadre d'une caravane de secours transportant des matières premières et des biens de construction vers les Carmines. Avant d'atteindre le Comté-du-Lac, la caravane a été prise en embuscade et pillée par des gnolls des Carmines, dispersant les fournitures en fer dans leurs campements à flanc de colline.",al={"d'où viennent les rivets en fer","qui a fabriqué les rivets en fer","origine du rivet en fer"}}},fp="10,141,20.378.0,18.284.0,30.169.0,36.153.0,46.111.0,32.90.0"}
P.entries["item:iron-shaft"] = {n="Hampe en fer",s="Près de Gangrebois, la Hampe en fer reste enfermée. Teronis la cherche pour compléter le bâtonnet de Dartol et tenter de freiner les assauts des furbolgs en Orneval.",h="Près de Gangrebois, la Hampe en fer reste enfermée.",kw={"orneval","ancien fou","bâtonnet de dartol","gangrebois","hampe en fer","purification de raene mène-loup","shael'dryn","ancien flétri","clé en bois"},ang={["class:Druid"]="En tant que druide, reconstituer le bâtonnet de Dartol fait appel à votre devoir de prendre soin de la terre et d’utiliser des outils oubliés pour la guérir.",["race:NightElf"]="En tant qu’Elfe de la nuit, récupérer la Hampe en fer signifie combattre les tréants de la forêt qui vous sont chers, corrompus par le fléau démoniaque qui suinte de Gangrebois."},sec={{t="Un morceau du bâtonnet de Dartol",b="Dartol a créé le bâtonnet, dont les morceaux ont été dispersés à travers Orneval. L’un d’eux fut confié aux druides de Dor'Danil. La Hampe en fer en est le robuste cœur métallique, enfermé dans un coffre, dans une clairière près de la frontière nord d’Orneval, non loin de Gangrebois."},{t="Le fléau de la forêt",b="Les clés du coffre sont détenues par des tréants qui veillaient autrefois sur ces bois. La corruption démoniaque venue de Gangrebois a rendu fous les Crazed Ancients et les Withered Ancients. Shael'dryn, une dryade, demande aux voyageurs de récupérer la hampe pour reforger le bâtonnet de Dartol et achever l’œuvre de Teronis."}},faq={{q="À quoi sert la Hampe en fer ?",a="La Hampe en fer est un morceau du bâtonnet brisé de Dartol. Shael'dryn recherche les morceaux pour reconstituer le bâtonnet et achever l’effort de Teronis visant à freiner les assauts des furbolgs en Orneval.",al={"utilité de la hampe en fer","qu’est-ce que cette hampe","pourquoi ai-je besoin de la hampe en fer"}},{q="Où trouver la Hampe en fer ?",a="La Hampe en fer se trouve dans un coffre verrouillé, dans une clairière à l’ouest de la route de Gangrebois, au nord d’Orneval.",al={"emplacement de la hampe en fer","trouver la hampe en fer","où se trouve le coffre"}},{q="Comment ouvrir le coffre qui contient la hampe ?",a="Une Clé en bois ouvre le coffre. Les Crazed Ancients et les Withered Ancients corrompus la portent en errant dans les bois, au nord-est de la Retraite de Raynebois.",al={"comment ouvrir le coffre","clé du coffre","clé de la hampe en fer"}},{q="Qui recherche la Hampe en fer ?",a="Shael'dryn, une dryade près d’un puits de lune au centre d’Orneval, envoie les voyageurs rassembler les morceaux du bâtonnet de Dartol et aider à purifier la forêt.",al={"qui veut la hampe en fer","donneur de quête de la hampe en fer"}}},fx={ad78a81b={q="Qu'est-ce que la Hampe en fer ?",a="La Hampe en fer est un segment clé de la Baguette de Dartol, une relique créée par Dartol. Les pièces de la baguette ont été dispersées à travers Orneval, et celle-ci a fini verrouillée à l'intérieur d'un coffre caché près des frontières de Gangrebois, sa clé étant portée par les tréants corrompus des environs.",al={"qu'est-ce qu'une hampe en fer","objet hampe en fer","hampe en fer baguette de dartol"}},["45340e91"]={q="D'où vient la Hampe en fer, et qui l'a fabriquée ?",a="Elle a été forgée dans le cadre d'une baguette magique créée par Dartol. Les pièces de la baguette ont été plus tard dispersées, et cette hampe particulière a été sécurisée dans un coffre usé caché dans une clairière près de Gangrebois, gardée indirectement par les tréants corrompus qui en détiennent la clé.",al={"qui a fabriqué la hampe en fer","origine de la hampe en fer","hampe en fer dartol"}},["3705c59d"]={q="Pourquoi la Hampe en fer est-elle recherchée ?",a="Raene Mène-loup et Shael'dryn cherchent à réassembler la Baguette de Dartol, que Teronis croyait capable de ralentir les attaques des furbolgs sur les elfes de la nuit d'Orneval. Reconstruire la relique nécessite de rassembler ses composants manquants, et cette hampe en fer robuste forme le manche central et le cœur nécessaires pour maintenir ensemble la gemme magique et le pommeau de la baguette.",al={"pourquoi veulent-ils la hampe en fer","pourquoi collecter la hampe en fer","motif de quête de la hampe en fer"}}},fp="10,146,23.242.0,19.262.1,32.190.0,30.104.0,47.138.0,34.139.0"}
P.entries["item:ironband-s-progress-report"] = {n="Rapport d'état de Baguefer",s="Dans l’est de Loch Modan, des troggs ont interrompu les fouilles du Prospecteur Baguefer. Son rapport réclame davantage de poudre à déflagration, alors que l’assemblée des explorateurs lui en a envoyé il y a des semaines.",h="Dans l’est de Loch Modan, des troggs ont interrompu les fouilles du Prospecteur Baguefer.",kw={"poudre à déflagration","assemblée des explorateurs","baguefer","jern casque-à-cornes","loch modan","prospecteur foudrepique","thelsamar","troggs"},ang={["profession:Mining"]="En tant que mineur, vous savez que la poudre à déflagration peut dégager la roche la plus résistante. Vous savez aussi combien il est dangereux que des provisions disparaissent en territoire trogg.",["race:Dwarf"]="En tant que nain explorateur ou mineur, vous connaissez les dangers des fouilles sur les anciens sites des titans de Khaz Modan."},sec={{t="Une demande de poudre",b="Jern Casque-à-cornes reçoit la dépêche à Thelsamar et la transmet à l’assemblée des explorateurs, à Forgefer. Baguefer signale que les travaux sont à l’arrêt et réclame de lourdes munitions. Les dirigeants de l’assemblée sont perplexes. Ils lui ont envoyé beaucoup de poudre à déflagration il y a des semaines et se demandent où elle est passée."}},faq={{q="Qu’est-ce que le Rapport d’état de Baguefer ?",a="Le rapport du Prospecteur Baguefer décrit les perturbations causées par les troggs sur son site de fouilles à Loch Modan et réclame davantage de poudre à déflagration.",al={"rapport d’état","rapport de baguefer","qu’est-ce que ce rapport"}},{q="Qui reçoit ce rapport ?",a="Jern Casque-à-cornes reçoit le rapport à Thelsamar, puis l’envoie au Prospecteur Foudrepique, au quartier général de l’assemblée des explorateurs à Forgefer.",al={"qui reçoit le rapport","à qui remettre le rapport","remettre le rapport d’état"}},{q="Pourquoi Baguefer a-t-il besoin de poudre à déflagration ?",a="Baguefer affirme avoir besoin de poudre à déflagration pour ses fouilles, mais les raids de troggs à proximité pourraient aussi rendre les explosifs utiles pour se défendre. Casque-à-cornes et Foudrepique pensent lui en avoir envoyé beaucoup il y a des semaines.",al={"pourquoi de la poudre à déflagration","qu’est devenue la poudre","pénurie de poudre"}},{q="Comment le Prospecteur Foudrepique réagit-il au rapport ?",a="Le Prospecteur Foudrepique est furieux de la lenteur des travaux. Il ne comprend pas pourquoi Baguefer ne mentionne pas la grande cargaison envoyée plus tôt et se demande où la poudre à déflagration a disparu.",al={"réaction de foudrepique","foudrepique est-il en colère"}}},fx={["9e6c80e6"]={q="D'où vient le Rapport d'état de Baguefer, et qui l'a écrit ?",a="Le document est rédigé par le prospecteur Baguefer lui-même sur son site d'excavation dans l'est du Loch Modan. Supervisant les efforts de creusement ardus au milieu du harcèlement persistant des troggs, Baguefer a écrit le rapport pour fournir des mises à jour formelles sur le rythme lent de son opération et consigner officiellement ses demandes de matériel en cours.",al={"qui a écrit le rapport d'état de baguefer","qui a fait le rapport de baguefer","d'où vient le rapport de baguefer"}},["2cf6b481"]={q="Pourquoi quelqu'un voudrait-il le Rapport d'état de Baguefer ?",a="Le rapport est une documentation vitale requise par les contacts administratifs à Thelsamar et au siège de la Ligue des explorateurs à Forgefer. Sans ce compte-rendu officiel détaillant les difficultés du site et l'interférence des troggs, des supérieurs comme le prospecteur Foudrepique n'accorderont pas l'approbation bureaucratique pour libérer et expédier de nouvelles cargaisons de poudre explosive.",al={"pourquoi le rapport d'état de baguefer est-il nécessaire","pourquoi prendre le rapport de baguefer","but du rapport d'état de baguefer"}}},fp="26,178,20.281.0,35.116.0,25.137.0,40.185.0,50.191.0"}
P.entries["item:ironfur-liver"] = {n="Ironfur Liver",s="Les Ironfur Liver proviennent des Ironfur bears de Féralas. Rhapsody Shindigger en a besoin pour préparer une boisson qui, espère-t-il, lui déliera la langue au sujet d'une aventure dans un marécage.",h="Les Ironfur Liver proviennent des Ironfur bears de Féralas.",kw={"féralas","groddoc liver","ironfur bear","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard"},sec={{t="Une boisson plus forte",b="Rhapsody Shindigger, dans Les Hinterlands, vous demande de lui apporter trois Ironfur Livers pour son Kalimdor Kocktail. Il les associe aux Groddoc Livers de Féralas et aux Roc Gizzards de Tanaris. Selon lui, cette boisson l'aidera à parler de son vol au-dessus du marécage."}},faq={{q="D'où viennent les Ironfur Livers ?",a="Les Ironfur Livers proviennent des Ironfur bears de Féralas.",al={"origine de l'ironfur liver","où trouver un foie"}},{q="Qui veut de l'Ironfur Liver ?",a="Rhapsody Shindigger, dans Les Hinterlands, veut trois Ironfur Livers pour son Kalimdor Kocktail.",al={"qui en a besoin","foie pour rhapsody"}},{q="Pourquoi Rhapsody a-t-il besoin de ces foies ?",a="Rhapsody a besoin d'Ironfur Livers, de Groddoc Livers et de Roc Gizzards pour préparer un Kalimdor Kocktail corsé. Il espère que cette boisson l'aidera à parler de son aventure dans le marécage.",al={"pourquoi un foie","à quoi sert le cocktail"}},{q="Que contient d'autre le Kalimdor Kocktail ?",a="Le Kalimdor Kocktail demande aussi des Groddoc Livers de Féralas et des Roc Gizzards de Tanaris.",al={"ingrédients du cocktail","autres organes"}}},fp="13,148,16.252.0,34.50.0,24.92.0,36.164.0,42.95.0"}
P.entries["item:ishamuhale-s-fang"] = {n="Croc d'Ishamuhale",s="Au Camp Taurajo, Jorn Oeil-des-cieux attend le Croc d'Ishamuhale, prélevé sur Dent-de-lance, un raptor écaille-de-soleil redouté des Tarides. Cette dent prouve qu'un chasseur a vaincu l'un des prédateurs naturels les plus meurtriers de Kalimdor.",h="Au Camp Taurajo, Jorn Oeil-des-cieux attend le Croc d'Ishamuhale, prélevé sur Dent-de-lance, un raptor...",kw={"tarides","croc","ishamuhale","jorn","raptor","sergra","dent-de-lance","écaille-de-soleil","taurajo"},ang={["class:Hunter"]="Pour un chasseur, prendre le croc de Dent-de-lance est un rite de passage dans les Tarides. Cette épreuve met à l'épreuve votre talent pour attirer, affronter et vaincre un prédateur rusé.",["race:Tauren"]="Pour un tauren, prendre la dent signifie s'approprier la puissance brute d'un prédateur tout en gardant discipline et équilibre."},sec={{t="Trophée de Dent-de-lance",b="Dans la savane centrale, les chasseurs craignent Ishamuhale, le plus féroce des raptors écaille-de-soleil vivants. Certains disent que ce grand chasseur tue par passion prédatrice, et non par faim. De la viande fraîche de zhevra attire la bête à découvert, près d'un arbre rabougri au nord-ouest de Cabestan. Là, Ishamuhale ne fait aucun quartier.\n\nPrendre son énorme croc prouve aux maîtres de chasse de la Horde qu'un voyageur a surmonté la sauvagerie des plaines."},{t="Une leçon de tempérance",b="Au Camp Taurajo, Jorn Oeil-des-cieux voit dans le croc d'Ishamuhale plus que de l'ivoire et du sang. Pour les taurens, le prendre transmet la force farouche du prédateur au chasseur qui l'a vaincu. Vient ensuite l'épreuve de la tempérance. Le chasseur doit maîtriser cette fureur sauvage au lieu de la laisser gouverner son âme."}},faq={{q="Qu'est-ce que le Croc d'Ishamuhale ?",a="Le Croc d'Ishamuhale est un trophée prélevé sur Ishamuhale, le célèbre raptor écaille-de-soleil Dent-de-lance qui rôde dans les Tarides.",al={"dent d'ishamuhale","croc de dent-de-lance","croc de raptor des tarides"}},{q="Qui veut le Croc d'Ishamuhale ?",a="Jorn Oeil-des-cieux, au Camp Taurajo, veut le croc. Il fait partie des épreuves de chasse qui commencent auprès de Sergra Darkthorn à la Croisée.",al={"à qui donner le croc d'ishamuhale","rendre le croc d'ishamuhale","où rapporter le croc d'ishamuhale"}},{q="Comment trouver la bête Ishamuhale ?",a="De la viande fraîche de zhevra attire Ishamuhale hors de sa cachette. On la dépose près d'un arbre rabougri au nord-ouest de Cabestan.",al={"comment faire apparaître ishamuhale","invoquer ishamuhale","où se trouve ishamuhale"}},{q="Que représente la prise du croc pour les taurens ?",a="Pour les taurens, prendre le Croc d'Ishamuhale signifie que la force légendaire du raptor réside désormais dans le chasseur. Celui-ci doit user de ce pouvoir avec tempérance et honneur.",al={"signification du croc","rituel du chasseur tauren ishamuhale"}}},fx={aa73e2a3={q="D'où vient le Croc d'Ishamuhale ?",a="Le croc est prélevé directement dans la mâchoire d'Ishamuhale, aussi connu sous le nom de Dent-de-lance. C'est le plus féroce des raptors écailles-de-soleil qui rôdent dans les Tarides, un prédateur naturel qui tue uniquement par instinct sauvage. Il n'a pas été façonné par des mains mortelles, mais a poussé naturellement comme une arme mortelle de la bête.",al={"origine du croc d'ishamuhale","d'où vient le croc d'ishamuhale","qui a fabriqué le croc d'ishamuhale"}}},fp="17,199,20.409.0,22.293.1,26.117.0,28.129.0,34.105.0,52.166.0"}
P.entries["item:ivar-s-head"] = {n="Tête d'Ivar",s="Dans le nord de la Forêt des Pins-Argentés, Rane Yorick cherche la Tête d'Ivar pour que son frère blessé, Quinn, puisse se rétablir en sécurité. La goule les a pris en embuscade alors qu'ils reconnaissaient les lieux pour le Grand exécuteur Hadrec.",h="Dans le nord de la Forêt des Pins-Argentés, Rane Yorick cherche la Tête d'Ivar pour que son frère blessé...",kw={"deathstalkers","le lopin d'ivar","ivar the foul","tête d'ivar","quinn yorick","rane yorick","forêt des pins-argentés"},ang={["faction:Horde"]="En tant que membre de la Horde, vous savez qu'éliminer les vestiges du Fléau comme Ivar protège les coursiers de la Horde qui traversent le nord de la Forêt des Pins-Argentés en direction du Sépulcre.",["race:Undead"]="En tant qu'éclaireur réprouvé, vous savez que les goules sauvages sont des fardeaux écervelés. Elles perturbent la reconnaissance militaire et menacent la sécurité encore naissante de Lordaeron."},sec={{t="Une menace décapitée",b="Rane et Quinn Yorick exploraient le nord de la Forêt des Pins-Argentés sur ordre du Grand exécuteur Hadrec quand Ivar l'Infect leur a tendu une embuscade dans une ferme abandonnée. Les Deathstalkers réprouvés ont repoussé la goule sauvage, mais Quinn a été grièvement mutilé. Rane est donc restée à la ferme en ruine pour veiller sur lui, sans pouvoir partir en sécurité et achever leur mission. La tête tranchée d'Ivar prouve qu'il ne peut plus menacer le domaine et donne à Quinn le temps de se rétablir sous les soins de Rane."}},faq={{q="À qui appartenait cette tête ?",a="Cette tête appartenait à Ivar l'Infect, une goule sauvage qui hantait la ferme abandonnée appelée le lopin d'Ivar, dans le nord de la Forêt des Pins-Argentés.",al={"qui est ivar","identité de la tête d'ivar","qu'est-ce qu'ivar"}},{q="Pourquoi Rane Yorick veut-elle la tête d'Ivar ?",a="Rane veut la preuve qu'Ivar est mort. La goule a grièvement mutilé son frère Quinn, qui a besoin de temps pour se rétablir sans craindre une nouvelle embuscade avant qu'ils ne fassent leur rapport au Grand exécuteur Hadrec.",al={"pourquoi rane veut la tête","rapporter la tête d'ivar","pourquoi tuer ivar"}},{q="Où Ivar l'Infect a-t-il été trouvé ?",a="Ivar l'Infect rôde dans la grange délabrée du lopin d'Ivar, attendant que les Deathstalkers blessés baissent leur garde.",al={"emplacement d'ivar","où se trouve ivar"}}},fx={fce823f2={q="D'où vient la Tête d'Ivar ?",a="Cette tête coupée est prélevée directement sur le cadavre d'Ivar the Foul, une goule vicieuse qui rôde dans la grange en ruine au lopin d'Ivar dans la Forêt des Pins-Argentés. Il ne s'agit pas d'un artefact ou d'un objet fabriqué, mais du trophée physique coupé sur un monstre mort-vivant pour garantir qu'il a bel et bien été détruit.",al={"origine de la tête d'ivar","d'où vient la tête d'ivar","qui a fabriqué la tête d'ivar"}}},fp="11,174,16.448.0,19.136.0,38.183.0,30.129.0"}
P.entries["item:iverron-s-antidote-item"] = {n="Antidote d'Iverron",s="À Sombrevallon, Iverron's Antidote doit parvenir à un jeune Elfe de la nuit avant de se gâter. Dirania Brillargent prépare ce remède contre le venin mortel des araignées Tisse-bois locales, mais il ne se conserve que cinq minutes.",h="À Sombrevallon, Iverron's Antidote doit parvenir à un jeune Elfe de la nuit avant de se gâter.",kw={"aldrassil","dirania brillargent","iverron","iverron's antidote","sombrevallon","venin d'araignée","teldrassil","webwood venom"},ang={["profession:Herbalism"]="En tant qu'herboriste, vous pouvez constater que les réactifs instables de Teldrassil rendent certains remèdes inutilisables s'ils ne sont pas employés immédiatement.",["race:NightElf"]="En tant que jeune aventurier elfe de la nuit à Sombrevallon, vous devez vous hâter pour apporter ce remède à Iverron. Cela montre combien la communauté dépend d'une action rapide et des connaissances en herboristerie pour lutter contre la corruption dans les ramures de Teldrassil."},sec={{t="Un remède fragile",b="Dirania Brillargent prépare Iverron's Antidote à Aldrassil pour Iverron, un jeune Elfe de la nuit mordu par des araignées Tisse-bois. Ses ingrédients instables et ses catalyseurs végétaux font que le remède ne se conserve que cinq minutes. Les messagers doivent se hâter vers le nord, jusqu'à la caverne des Tisse-bois, et le livrer avant qu'il ne se gâte."}},faq={{q="À quoi sert Iverron's Antidote ?",a="Iverron's Antidote soigne Iverron après qu'il a été mordu par une araignée Tisse-bois venimeuse, près de leur caverne au nord de Sombrevallon.",al={"utilité de l'antidote","effet d'iverron's antidote"}},{q="Pourquoi l'antidote est-il soumis à une limite de temps ?",a="Dirania Brillargent explique que ce remède fragile ne reste efficace que cinq minutes après sa préparation. Passé ce délai, ses propriétés médicinales se dégradent.",al={"pourquoi cinq minutes","délai de l'antidote","pourquoi l'antidote périme"}},{q="Qui prépare l'antidote ?",a="Dirania Brillargent, une soigneuse elfe de la nuit à Aldrassil, dans Sombrevallon, prépare la potion avec des ingrédients récoltés pour sauver Iverron.",al={"qui a préparé l'antidote","préparatrice de l'antidote"}},{q="Que se passe-t-il si l'antidote périme ?",a="Au bout de cinq minutes, le remède se gâte et cesse d'agir. Le messager doit retourner auprès de Dirania Brillargent, à Aldrassil, pour en obtenir une nouvelle préparation.",al={"antidote périmé","délai écoulé"}}},fx={["59c1ca07"]={q="Qu'est-ce que l'Antidote d'Iverron ?",a="Il s'agit d'un breuvage médicinal fraîchement préparé, concocté spécifiquement pour neutraliser le venin mortel des araignées des bois de la Toile qui rôdent dans les branches de Teldrassil. En raison de son mélange naturel délicat, le remède est hautement volatil et se gâte rapidement s'il n'est pas consommé quelques minutes après sa préparation.",al={"qu'est-ce que l'antidote d'iverron","antidote d'iverron","remède d'iverron"}}},fp="18,204,16.292.0,36.115.0,40.143.0,23.127.0,37.142.0"}
P.entries["item:jade-phial"] = {n="Flasque de jade",s="À Dolanaar, Corithras Ragelune confie la Flasque de jade aux jeunes initiés. Ils transportent l’eau sacrée des puits de lune de Teldrassil pour réapprovisionner le puits central des druides à Darnassus.",h="À Dolanaar, Corithras Ragelune confie la Flasque de jade aux jeunes initiés.",kw={"corithras ragelune","crown of the earth","dolanaar","flasque de jade","puits de lune","brise-stellaire","teldrassil"},ang={["class:Druid"]="Dès vos débuts comme druide, vous apprenez à prendre soin des puits de lune de Teldrassil. Leur vitalité exige un respect et une attention constants.",["race:NightElf"]="En tant qu’elfe de la nuit, vous savez que les puits de lune témoignent du lien durable entre les kaldorei et Elune. En prendre soin avec des récipients comme la Flasque de jade est un devoir sacré."},sec={{t="Un récipient pour les eaux sacrées",b="La Flasque de jade recueille l’eau d’un puits de lune près de Brise-stellaire. Sur Teldrassil, les puits de lune canalisent les énergies lunaires et naturelles, essentielles à la société des elfes de la nuit et au culte druidique.\n\nDe temps à autre, les druides réapprovisionnent leur puits de lune central à Darnassus avec l’eau des puits de la grande ramure. Corithras Ragelune confie la flasque aux jeunes initiés, qui recueillent de l’eau pure sans altérer la puissance spirituelle du puits de lune."}},faq={{q="À quoi sert la Flasque de jade ?",a="La Flasque de jade recueille l’eau sacrée du puits de lune juste à l’extérieur de Brise-stellaire. Une fois remplie, rapportez-la à Corithras Ragelune, à Dolanaar, afin que les druides puissent réapprovisionner leur puits de lune à Darnassus.",al={"utilité de la flasque de jade","pourquoi ai-je besoin de la flasque de jade","à quoi sert la flasque de jade"}},{q="Qui fournit la Flasque de jade ?",a="Corithras Ragelune, un druide elfe de la nuit de Dolanaar, fournit la Flasque de jade aux aventuriers qui accomplissent le rite appelé Crown of the Earth.",al={"qui donne la flasque de jade","où trouver la flasque de jade","corithras flasque de jade"}},{q="Où finit l’eau de cette flasque ?",a="L’eau recueillie dans la Flasque de jade est transportée à Darnassus pour réapprovisionner le puits de lune central entretenu par les druides Cenarion.",al={"où va l’eau des puits de lune","destination de la flasque de jade","qui utilise l’eau"}}},fx={["8250d8c3"]={q="Qu'est-ce que la Flasque de jade ?",a="La Flasque de jade est un récipient rituel spécialement conçu, fourni par Corithras Ragelune à Dolanaar. Elle est conçue pour contenir et transporter en toute sécurité les eaux sacrées et bénies puisées dans les puits de lune de Teldrassil sans perturber ou dégrader leurs propriétés magiques inhérentes.",al={"flasque de jade","qu'est-ce que la flasque de jade","qu'est-ce que flasque de jade"}}},fp="10,185,26.442.0,32.207.0,28.143.0,44.125.0"}
P.entries["item:jennea-s-flask"] = {n="Flacon de Jennea",s="Au Sanctuaire du sorcier, à Hurlevent, Jennea Cannon envoie les apprentis chercher de l’eau au Lac Miroir. Ils en rapportent un échantillon pour l’étudier.",h="Au Sanctuaire du sorcier, à Hurlevent, Jennea Cannon envoie les apprentis chercher de l’eau au Lac Miroir.",kw={"forêt d’elwynn","jennea cannon","flacon de jennea","lac miroir","hurlevent","échantillon d’eau","sanctuaire du sorcier"},ang={["class:Mage"]="En tant que mage, porter ce flacon est l’une de vos premières missions sur le terrain pour le Sanctuaire du sorcier. Cette tâche met à l’épreuve votre capacité à mener des recherches arcaniques délicates et à surveiller les changements dans les lignes telluriques."},sec={{t="Un récipient pour l’étude arcanique",b="Les luttes magiques qui ont secoué Azeroth ont arraché les courants arcaniques à leurs anciens canaux. Jennea Cannon veut comprendre leurs effets sur la Forêt d’Elwynn. Elle confie un flacon de verre aux apprentis prometteurs et les envoie au sud-ouest des portes de Hurlevent, au pied de la cascade du Lac Miroir.\n\nLe flacon protège l’échantillon d’eau pendant le trajet jusqu’au Sanctuaire du sorcier. Jennea peut alors l’examiner pour y déceler des perturbations arcaniques."},{t="Protéger les eaux",b="Grâce au Flacon de Jennea, les mages de Hurlevent peuvent vérifier si les lignes telluriques changeantes ont souillé le Lac Miroir. Une magie néfaste dans l’eau pourrait provoquer d’étranges afflictions chez les êtres vivants des environs et chez quiconque en boirait. Un échantillon peut révéler des résidus magiques avant que les courants souillés ne se répandent dans la campagne."}},faq={{q="À quoi sert le Flacon de Jennea ?",a="Utilisez le Flacon de Jennea pour recueillir de l’eau à la cascade du Lac Miroir, dans la Forêt d’Elwynn.",al={"utilité du flacon","à quoi sert le flacon","utilisation du flacon"}},{q="Qui vous remet ce flacon ?",a="Jennea Cannon, une formatrice de mages au Sanctuaire du sorcier de Hurlevent, vous remet le flacon.",al={"qui remet le flacon","origine du flacon de jennea"}},{q="Pourquoi Jennea veut-elle de l’eau du Lac Miroir ?",a="De récents conflits mystiques ont perturbé les courants magiques à travers le monde. Jennea craint que des courants errants ne s’infiltrent dans les eaux d’Elwynn et ne mettent en danger quiconque boit l’eau du lac.",al={"pourquoi l’eau du lac miroir","pourquoi un échantillon d’eau"}},{q="Où remplir le flacon ?",a="Remplissez le flacon au pied de la cascade qui se jette dans le Lac Miroir, au sud-ouest des portes principales de Hurlevent, dans la Forêt d’Elwynn.",al={"où remplir le flacon","emplacement du flacon","emplacement du lac"}}},fx={b836f408={q="Qu'est-ce que le Flacon de Jennea ?",a="Il s'agit d'un récipient à échantillon spécialisé fourni par Jennea Cannon, une instructrice du Quartier des Mages de Hurlevent. Elle le confie à des apprentis prometteurs afin qu'ils recueillent de l'eau directement à la cascade du lac Miroir, pour qu'elle puisse l'inspecter à la recherche de toute contamination magique.",al={"qu'est-ce que le flacon de jennea","flacon de jennea"}}},fp="14,138,28.439.0,19.309.0,32.86.0,25.88.0,44.184.0,28.126.0"}
P.entries["item:jer-kai-s-signet-ring"] = {n="Jer'kai's Signet Ring",s="L’anneau sigillaire de Jer'kai transmet son message des terres sauvages de Féralas à Tyrande Murmevent, à Darnassus. Il apprend à la grande prêtresse que Jer'kai et Kindal vont bien et reconnaît votre aide.",h="L’anneau sigillaire de Jer'kai transmet son message des terres sauvages de Féralas à Tyrande Murmevent, à...",kw={"darnassus","féralas","jer'kai moonweaver","anneau sigillaire de jer'kai","kindal","message","anneau sigillaire","temple de la lune","tyrande murmevent"},ang={["race:NightElf"]="En tant qu’Elfe de la nuit, vous portez le message de Jer'kai à Tyrande Murmevent, grande prêtresse d’Élune, au Temple de la Lune."},sec={{t="Un message pour Darnassus",b="À Féralas, Jer'kai Moonweaver vous confie son anneau sigillaire après que vous l’avez aidée, elle et Kindal. Elle vous demande de le porter à Tyrande Murmevent, au Temple de la Lune, à Darnassus. L’anneau annonce que toutes deux vont bien et dit à Tyrande la vérité sur votre aide."},{t="Au Temple",b="Tyrande écoute votre récit sur l’aide que vous avez apportée aux dragons et à l’une de ses prêtresses. Elle promet de rendre l’anneau de Jer'kai et envoie des éclaireurs vers Féralas avec celui-ci. Pour l’heure, l’anneau a transmis son message à la grande prêtresse."}},faq={{q="À quoi sert l’anneau sigillaire de Jer'kai ?",a="Jer'kai vous demande de porter l’anneau à Tyrande Murmevent, au Temple de la Lune, à Darnassus. Il apprend à Tyrande que Jer'kai et Kindal vont bien et reconnaît votre aide.",al={"anneau de jerkai","utilité de l’anneau sigillaire","anneau pour tyrande"}},{q="Qui m’a donné l’anneau ?",a="Jer'kai Moonweaver vous donne son anneau sigillaire à Féralas après que vous l’avez aidée, elle et Kindal.",al={"qui a donné l’anneau","qui a donné l’anneau de jerkai","origine de l’anneau"}},{q="À qui faut-il remettre l’anneau ?",a="L’anneau doit être remis à Tyrande Murmevent, la grande prêtresse du Temple de la Lune de Darnassus.",al={"destinataire de l’anneau","qui reçoit l’anneau de jerkai","anneau de tyrande"}},{q="Que fait Tyrande de l’anneau ?",a="Tyrande promet de rendre l’anneau à Jer'kai et envoie des éclaireurs vers Féralas avec celui-ci.",al={"réponse de tyrande","anneau rendu","que devient l’anneau"}}},fp="21,197,22.267.0,13.219.0,34.178.0,21.86.0,36.98.0,35.86.1"}
P.entries["item:jeweled-pendant"] = {n="Jeweled Pendant",s="Le Jeweled Pendant est un bijou noble finement ouvragé, trouvé sur des soldats de l’Alliance près de Theramore. Sa présence entre les mains de simples soldats a attiré l’attention de la Horde.",h="Le Jeweled Pendant est un bijou noble finement ouvragé, trouvé sur des soldats de l’Alliance près de...",kw={"alliance","horde","jeweled pendant","marg","muckshell","nazeer","pendentif","hurlevent","theramore","zor arbre-solitaire"},ang={["faction:Alliance"]="Un soldat de Hurlevent a été aperçu portant ce pendentif finement ouvragé près de Theramore, et son propriétaire inconnu pourrait être un noble.",["faction:Horde"]="Le pendentif pourrait fournir à la Horde un indice sur les affaires des nobles de l’Alliance. Zor Arbre-solitaire étudie sa facture et son histoire."},sec={{t="Le butin d’un soldat",b="Près de Theramore, Marg a vu un soldat de l’Alliance porter un pendentif orné de plus de gemmes qu’un simple soldat ne pouvait s’offrir. Marg l’a volé au camp, mais un muckshell l’a tué sur le chemin du retour. Le pendentif a été récupéré puis apporté à Nazeer, à Mur-de-Fougères, où sa facture soignée a soulevé une question sur son véritable propriétaire."},{t="Une œuvre de noble",b="Zor Arbre-solitaire, qui connaît bien la politique de l’Alliance, étudie maintenant le pendentif à Orgrimmar. Il reconnaît la maîtrise de sa fabrication et pense que bien des humains pourraient convoiter un tel joyau. Son propriétaire reste inconnu, tandis que la Horde attend de découvrir ce que l’ornement pourrait révéler."}},faq={{q="À qui appartenait le Jeweled Pendant ?",a="Le propriétaire du pendentif est inconnu. Marg l’a vu sur un soldat de l’Alliance près de Theramore, mais sa facture soignée laisse penser qu’il appartenait à un noble.",al={"propriétaire du pendentif","qui le portait","à qui est ce joyau"}},{q="Pourquoi Marg a-t-il volé le pendentif ?",a="Marg a vu un soldat de l’Alliance porter un pendentif chargé de gemmes et l’a volé au camp, près de Theramore.",al={"pourquoi le voler","marg et le pendentif","qu’a pris marg"}},{q="Qu’est-il arrivé à Marg ?",a="Un muckshell a tué Marg alors qu’il retournait à la base avec le pendentif qu’il avait volé au camp de l’Alliance.",al={"sort de marg","comment marg est-il mort","histoire de marg"}},{q="Pourquoi la Horde s’intéresse-t-elle au pendentif ?",a="Le pendentif semble être l’œuvre d’un noble, pourtant un soldat de l’Alliance le portait près de Theramore. Zor Arbre-solitaire l’étudie pour découvrir qui en était le propriétaire.",al={"pendentif et horde","pourquoi le signaler à zor","mystère du pendentif"}},{q="Où se trouve le pendentif maintenant ?",a="Zor Arbre-solitaire étudie le Jeweled Pendant à Orgrimmar.",al={"emplacement du pendentif","où apporter le joyau","pendentif de zor"}}},fp="15,179,19.329.0,16.264.0,30.145.0,31.105.0,22.101.1,42.143.0,25.58.0"}
P.entries["item:jitters-completed-journal"] = {n="Journal complet de la Tremblote",s="Dans le Bois de la Pénombre, la Tremblote remet son journal achevé et espère ainsi laver son nom. Il craint la vengeance de Sven Yorgen après avoir fui le massacre à la ferme de Sven.",h="Dans le Bois de la Pénombre, la Tremblote remet son journal achevé et espère ainsi laver son nom.",kw={"evêque farthing","cathédrale de la lumière","cavaliers noirs","bois de la pénombre","la masure lugubre","la tremblote","journal","morbent fel","sven yorgen"},ang={["class:Priest"]="En tant que prêtre, vous apportez le journal à l’Evêque Farthing, à la Cathédrale de la Lumière, et contribuez à purifier les souillures impies grâce aux reliques sacrées.",["faction:Alliance"]="En tant que membre de l’Alliance, vous voyez à quel point le Bois de la Pénombre est en péril tandis que les dirigeants de Hurlevent se préoccupent d’autres affaires."},sec={{t="Les aveux d’un lâche",b="La Tremblote s’est enfui de la ferme de Sven au début de l’attaque, laissant son journal inachevé dans les ruines. Dans son journal terminé, il raconte comment de mystérieux cavaliers noirs ont massacré la famille de Sven. Pendant des semaines, ses pages furent son seul réconfort alors qu’il se cachait dans le Bois de la Pénombre. À présent, il remet le volume achevé de son plein gré, espérant que la vérité lui épargnera la fureur de Sven."},{t="Au cœur des ténèbres",b="Le journal amène Sven à parler des cavaliers vêtus de noir qu’il a vus discuter avec le sorcier Morbent Fel à La masure lugubre. Sven envoie le manuscrit vers le nord avec des voyageurs qui se rendent à la Cathédrale de la Lumière, à Hurlevent. Là-bas, l’Evêque Farthing lit le récit de la Tremblote pour découvrir l’immonde corruption du Bois de la Pénombre. Ces révélations l’aident à façonner une arme sacrée capable de percer les protections magiques de Morbent Fel."}},faq={{q="Pourquoi la Tremblote a-t-il remis son journal ?",a="La Tremblote s’est enfui de la ferme de Sven pendant l’attaque et y a laissé un journal inachevé. Il remet aux aventuriers la version terminée pour qu’ils la portent à Sven, espérant que toute la vérité lavera son nom et le protégera de la colère de Sven.",al={"pourquoi la tremblote remet son journal","journal de la tremblote","pourquoi la tremblote a écrit ce journal"}},{q="Que révèle le journal sur la ferme de Sven ?",a="Le journal achevé de la Tremblote livre son témoignage direct sur le drame de la ferme de Sven Yorgen et complète ce que son journal inachevé ne racontait pas.",al={"que s’est-il passé à la ferme de sven","attaque contre la famille de sven","cavaliers noirs ferme de sven"}},{q="Qui est Morbent Fel et quel est son lien avec le journal ?",a="Morbent Fel est un nécromancien de La masure lugubre. Le journal amène Sven à révéler qu’il a vu les cavaliers vêtus de noir parler avec Fel.",al={"lien avec morbent fel","qui est morbent fel","sorcier de la masure lugubre"}},{q="Pourquoi le journal est-il emporté à Hurlevent ?",a="Sven envoie le journal à l’Evêque Farthing, à la Cathédrale de la Lumière, à Hurlevent. Farthing le lit pour comprendre la corruption du Bois de la Pénombre et contribuer à préparer une arme sacrée capable de percer les protections magiques de Morbent Fel.",al={"pourquoi l’évêque farthing","apporter le journal à la cathédrale","seeking wisdom journal"}}},fx={["3f8dfebe"]={q="Qu'est-ce que le Journal complet de la Tremblote ?",a="C'est la chronique personnelle complète tenue par la Tremblote, un vagabond terrifié se cachant dans le Bois de la Pénombre. Contrairement aux notes fragmentaires laissées derrière lui lorsqu'il a fui la ferme de Sven Yorgen, ce manuscrit complet expose toute la séquence des tragédies qui ont frappé la propriété, les horreurs envahissantes des bois et les figures sinistres se déplaçant dans l'ombre.",al={"journal complet de la tremblote","qu'est-ce que ce journal","journal de la tremblote"}},e7121643={q="D'où vient le Journal complet de la Tremblote et qui l'a créé ?",a="Le journal a été écrit par la Tremblote lui-même. Après avoir fui le massacre de la ferme de Sven et abandonné un journal précédent, il a passé des semaines à se cacher, notant frénétiquement ses pensées et relatant les forces sinistres qui traquent le Bois de la Pénombre. Il a conservé le volume fini comme seul compagnon jusqu'à ce qu'il l'abandonne pour éviter d'affronter la colère de Sven Yorgen.",al={"qui a écrit le journal complet de la tremblote","origine du journal de la tremblote","d'où vient le journal"}},["5c3c5710"]={q="Pourquoi le Journal complet de la Tremblote est-il recherché ?",a="Sven Yorgen recherche le journal pour le témoignage oculaire de la Tremblote sur la tragédie survenue dans sa ferme. Plus tard, l'évêque Farthing à la Cathédrale de la Lumière l'étudie pour aider à préparer un aventurier à affronter le mal qui afflige le Bois de la Pénombre.",al={"pourquoi veulent-ils le journal","pourquoi le journal de la tremblote est-il important","qui veut le journal"}}},fp="26,161,21.343.1,23.373.1,36.219.0,47.140.1,58.142.1,38.206.1"}
P.entries["item:johaan-s-findings"] = {n="Les découvertes de Johaan",s="À Brill, l’Apothicaire Johaan envoie ses découvertes au sud, au Sépulcre. Ses recherches transmettent les récents travaux alchimiques des Clairières de Tirisfal à l’Apothicaire Renferrel, dans la Forêt des Pins-Argentés.",h="À Brill, l’Apothicaire Johaan envoie ses découvertes au sud, au Sépulcre.",kw={"apothicaire johaan","apothicaire renferrel","brill","johaan","les découvertes de johaan","nouvelle peste","société royale des apothicaires","le sépulcre"},ang={["faction:Horde"]="En tant que membre de la Horde, transporter des recherches vers le sud vous mène des Clairières de Tirisfal, qui vous sont familières, aux conflits plus sombres de la Forêt des Pins-Argentés.",["race:Undead"]="En tant que Mort-vivant, ces découvertes témoignent de l’objectif qui anime la Société royale des apothicaires : livrer la Nouvelle Peste promise à la Dame noire."},sec={{t="Correspondance d’apothicaires",b="L’Apothicaire Johaan envoie ses recherches de Brill à l’Apothicaire Renferrel, au Sépulcre. La Société royale des apothicaires répond à la demande de Dame Sylvanas Coursevent : créer une Nouvelle Peste capable de détruire les vivants comme le Fléau. Ses chercheurs sont dispersés dans les ruines contestées de Lordaeron et se transmettent donc leurs découvertes entre avant-postes.\n\nRenferrel dirige les efforts de la Société depuis la Forêt des Pins-Argentés, tandis que Johaan consigne ses expériences locales à Brill. Ses documents contribuent aux travaux plus vastes de la Société pour perfectionner ses mixtures mortelles."}},faq={{q="Que sont les découvertes de Johaan ?",a="Les découvertes de Johaan sont des notes et des recherches alchimiques compilées par l’Apothicaire Johaan à Brill. Elles consignent ses récents tests et expériences dans les Clairières de Tirisfal.",al={"découvertes de johaan","que sont les découvertes de johaan","documents de recherche de johaan"}},{q="À qui cet objet doit-il être remis ?",a="Les découvertes sont destinées à l’Apothicaire Renferrel. C’est un membre éminent de la Société royale des apothicaires, au Sépulcre, dans le nord de la Forêt des Pins-Argentés.",al={"qui reçoit les découvertes de johaan","où remettre les découvertes de johaan","remise à renferrel"}},{q="Pourquoi les apothicaires se transmettent-ils ces recherches ?",a="La Société royale des apothicaires partage les connaissances entre ses chercheurs dispersés afin d’accélérer leurs travaux. Sylvanas Coursevent exige des progrès rapides sur la Nouvelle Peste. Les chercheurs de la Forêt des Pins-Argentés doivent donc être informés des découvertes faites à Tirisfal.",al={"pourquoi partager les découvertes","but des découvertes de johaan","recherches de la société royale des apothicaires"}},{q="Qui a rédigé ces documents ?",a="L’Apothicaire Johaan a rédigé ces documents. C’est un alchimiste de la Société royale des apothicaires, près de la potence à Brill, où il teste des spécimens locaux pour les travaux alchimiques des Réprouvés.",al={"qui est l’apothicaire johaan","qui a rédigé ceci","apothicaire johaan"}}},fp="17,181,25.524.0,26.156.0,37.156.0,55.236.0,26.169.0"}
P.entries["item:johaan-s-special-drink"] = {n="Boisson spéciale de Johaan",s="À Brill, l’Apothicaire Johaan propose une boisson qui met à l’épreuve la peste en cours d’élaboration par la Société royale des apothicaires. Son apparence de simple rafraîchissement dissimule un dessein mortel.",h="À Brill, l’Apothicaire Johaan propose une boisson qui met à l’épreuve la peste en cours d’élaboration par la...",kw={"apothicaire johaan","brill","montagnard capturé","taverne des pendus","johaan","boisson spéciale de johaan","nouvelle peste"},ang={["race:Dwarf"]="En tant que nain, vous risquez d’être capturé par les Gardes de la mort près des Clairières de Tirisfal et de servir de sujet d’expérimentation.",["race:Undead"]="En tant que Réprouvé, vous aidez la Société royale des apothicaires et faites avancer les desseins de Dame Sylvanas Coursevent contre les vivants."},sec={{t="Un breuvage toxique",b="À Brill, l’Apothicaire Johaan mélange des composants venimeux à des réactifs locaux. Le breuvage ressemble à une boisson de taverne, mais il sert à tester la virulence de la peste sur des êtres vivants. Johaan le propose comme s’il voulait étancher la soif d’un captif. Ces travaux aident les apothicaires réprouvés à créer une arme assez puissante pour accomplir les desseins de Sylvanas Coursevent pour Azeroth."},{t="L’épreuve de la cave",b="Sous la Taverne des Pendus, les Gardes de la mort gardent les intrus égarés dans une cellule de détention à la cave. Un montagnard nain capturé y est enchaîné. Prenant le breuvage pour une bière grossière, il le boit avec avidité, puis meurt sur-le-champ. Sa mort montre à la Société royale des apothicaires que sa dernière souche peut rapidement faucher des victimes vivantes."}},faq={{q="Qu’est-ce que la Boisson spéciale de Johaan ?",a="À Brill, l’Apothicaire Johaan prépare une boisson mortelle pour tester sur des êtres vivants la peste en cours d’élaboration par les Réprouvés.",al={"qu’est-ce que la boisson de johaan","boisson de johaan","qu’est-ce que cet objet"}},{q="À qui donne-t-on la boisson ?",a="La boisson est emportée dans la cave sous la Taverne des Pendus, à Brill, et donnée à un montagnard capturé détenu par les Gardes de la mort locaux.",al={"qui la boit","à qui donner la boisson","cible de la boisson"}},{q="Que se passe-t-il quand quelqu’un la boit ?",a="Le prisonnier boit le breuvage, s’attendant à une bière âpre, et meurt sur-le-champ.",al={"le nain meurt-il","effet de la boisson","que fait-elle"}},{q="Pourquoi l’Apothicaire Johaan prépare-t-il cette boisson ?",a="L’Apothicaire Johaan prépare cette boisson pour tester la nouvelle peste de la Société royale des apothicaires. Il la donne à un nain capturé pour voir avec quelle efficacité elle tue les mortels.",al={"pourquoi johaan l’a-t-il préparée","motivation de l’apothicaire johaan","pourquoi tester la peste"}}},fx={["7bd04f9d"]={q="D'où vient la Boisson spéciale de Johaan et qui l'a fabriquée ?",a="La mixture est brassée directement par l'apothicaire Johaan à Brill dans les Clairières de Tirisfal. Travaillant pour le compte de la Société royale des apothicaires et de Dame Sylvanas Coursevent, Johaan raffine des toxines expérimentales récoltées sur les créatures locales pour fabriquer ce mélange puissant et mortel.",al={"qui a fabriqué la boisson spéciale de johaan","d'où vient la boisson spéciale de johaan","qui a brassé la boisson"}}},fp="22,174,12.359.0,16.323.1,31.117.0,26.139.0,36.68.1,43.163.0"}
P.entries["item:jon-jon-s-golden-spyglass"] = {n="Longue-vue dorée de Jon-Jon",s="La Longue-vue dorée de Jon-Jon compte parmi les objets de valeur que Sea Wolf MacKinley recherche à Baie-du-Butin. Il veut la récupérer avec deux autres dettes contractées dans les ruines de la jungle.",h="La Longue-vue dorée de Jon-Jon compte parmi les objets de valeur que Sea Wolf MacKinley recherche à...",kw={"baie-du-butin","longue-vue dorée","jon-jon","jon-jon the crow","ruines d'aboraz","ruines de jubuwal","sea wolf mackinley","longue-vue","dettes vaudou"},sec={{t="Une dette en or",b="Sea Wolf MacKinley, à Baie-du-Butin, veut récupérer la Longue-vue dorée de Jon-Jon et deux autres objets de valeur. Jon-Jon the Crow est l'un des trois débiteurs dont MacKinley dit qu'ils ont disparu dans les ruines de la jungle. Leurs dettes restent impayées depuis des mois, et MacKinley réclame son dû."}},faq={{q="Qui veut la longue-vue de Jon-Jon ?",a="Sea Wolf MacKinley, de Baie-du-Butin, veut la récupérer, ainsi que deux autres objets de valeur qu'on lui doit.",al={"qui la veut","longue-vue de mackinley","dette de la longue-vue"}},{q="Qui est Jon-Jon the Crow ?",a="Jon-Jon the Crow est l'un des trois débiteurs dont MacKinley dit qu'ils ont erré dans les ruines de la jungle après avoir laissé leurs dettes impayées.",al={"jon-jon","histoire de jon-jon","the crow"}},{q="Pourquoi MacKinley veut-il la longue-vue ?",a="MacKinley dit que Jon-Jon lui est redevable et veut récupérer les objets de valeur qu'on lui doit.",al={"pourquoi la longue-vue","dette envers mackinley","pourquoi la récupérer"}},{q="Où trouver la longue-vue de Jon-Jon ?",a="MacKinley vous indique les Ruines d'Aboraz et les Ruines de Jubuwal, au nord-est de Baie-du-Butin, où errent les débiteurs.",al={"emplacement de la longue-vue","où est jon-jon","trouver la longue-vue dorée"}},{q="Quels autres objets de valeur MacKinley recherche-t-il ?",a="MacKinley recherche aussi le Fléau de Maury et le Grand anneau de Chucky.",al={"autres dettes","maury et chucky","trois objets de valeur"}},{q="Que dit MacKinley au sujet des débiteurs ?",a="MacKinley dit avoir entendu que les débiteurs avaient été maudits et ensorcelés et qu'ils errent désormais dans les ruines de la jungle.",al={"pourquoi sont-ils dans les ruines","débiteurs maudits","que leur est-il arrivé"}}},fp="25,152,14.264.0,29.90.0,24.117.0,37.80.0,38.123.0,41.65.0,42.94.0"}
P.entries["item:jordan-s-ore-shipment"] = {n="Cargaison de minerai de Jordan",s="Dans les collines du nord-est de Loch Modan, des ogres Mo'grosh détiennent la Cargaison de minerai de Jordan. Le minerai est arrivé par caravane depuis Les Paluns pour que Bailor Main-de-pierre le raffine en alliage destiné au forgeron Jordan Morpuits.",h="Dans les collines du nord-est de Loch Modan, des ogres Mo'grosh détiennent la Cargaison de minerai de Jordan.",kw={"alliage","bailor main-de-pierre","jordan morpuits","cargaison de minerai de jordan","loch modan","mo'grosh","the test of righteousness"},ang={["class:Paladin"]="En tant que paladin, récupérer l'alliage volé aux ogres Mo'grosh est une étape essentielle de la commande de Jordan Morpuits. Cela prouve votre dévouement pendant The Test of Righteousness.",["profession:Blacksmithing"]="En tant que forgeron, vous pouvez reconnaître dans l'alliage spécialisé de Bailor Main-de-pierre un bel ouvrage de métallurgie naine. Jordan Morpuits a refusé les substituts ordinaires pour son travail."},sec={{t="Une livraison prise en embuscade",b="Le minerai de Jordan Morpuits était destiné à Bailor Main-de-pierre, un nain qui devait le raffiner en son alliage spécial. La caravane le transportait vers le sud, à travers les montagnes, depuis Les Paluns jusqu'à Loch Modan. Puis des ogres Mo'grosh ont pris les voyageurs en embuscade et ont traîné la cargaison jusqu'à leur place forte dans les terres sauvages. Les gardes qui ont survécu sont morts de leurs blessures, et le projet de forge de Jordan attend le retour du minerai."}},faq={{q="Que contient la cargaison ?",a="La cargaison contient du minerai que Bailor Main-de-pierre doit raffiner en son alliage spécial. Jordan Morpuits en a besoin pour son travail des métaux à Forgefer.",al={"contenu de la cargaison de minerai de jordan","quel minerai est-ce","contenu du minerai de jordan"}},{q="Qui a volé la Cargaison de minerai de Jordan ?",a="Des ogres Mo'grosh ont pris la caravane en embuscade alors qu'elle se dirigeait vers le sud depuis Les Paluns. Ils ont massacré les escortes et emporté les caisses sur leur territoire, au nord-est du Loch.",al={"qui a pris la cargaison de minerai","qui l'a volée","ogres et cargaison de minerai"}},{q="Qui est Bailor Main-de-pierre ?",a="Bailor Main-de-pierre est un artisan nain en poste à Loch Modan et un vieil ami de Jordan Morpuits. Il avait organisé l'envoi de l'alliage avant que les ogres ne s'en emparent.",al={"bailor main-de-pierre","qui est bailor"}},{q="Pourquoi cette cargaison est-elle importante pour les paladins ?",a="Les paladins qui entreprennent The Test of Righteousness cherchent l'alliage pour aider Jordan Morpuits à forger une arme consacrée par la Lumière.",al={"cargaison de minerai pour paladin","minerai de the test of righteousness","pourquoi les paladins en ont-ils besoin"}}},fx={bb183b6f={q="Qu'est-ce que la Cargaison de minerai de Jordan ?",a="La Cargaison de minerai de Jordan est une caisse de minerai que le nain Bailor Main-de-pierre devait raffiner en son alliage spécial pour le forgeron Jordan Morpuits à Forgefer. La marchandise était transportée par une caravane en provenance des Paluns avant de tomber dans une embuscade et d'être saisie par des ogres Mo'grosh dans le nord du Loch Modan.",al={"qu'est-ce que la cargaison de minerai de jordan","infos sur la cargaison de minerai de jordan","qu'est-ce que le minerai de bailor"}},["84b5d642"]={q="D'où vient la Cargaison de minerai de Jordan, et qui l'a fabriquée ?",a="L'expédition se compose de minerai qui voyageait par caravane depuis Les Paluns jusqu'au Loch Modan, où Bailor Main-de-pierre devait l'affiner en son alliage pour son vieil ami, Jordan Morpuits. Des ogres ont intercepté le convoi et tué ses gardes avant son arrivée.",al={"qui a préparé la cargaison de minerai de jordan","d'où venait la cargaison de minerai de jordan","origine de la cargaison de minerai de jordan"}}},fp="21,201,20.399.0,28.134.0,32.168.0,24.157.0,43.126.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="Cargaison de minerai raffiné de Jordan",s="La Cargaison de minerai raffiné de Jordan arrive à Forgefer pour The Test of Righteousness. Le métal est préparé afin que le forgeron Jordan Morpuits forge une arme sacrée.",h="La Cargaison de minerai raffiné de Jordan arrive à Forgefer pour The Test of Righteousness.",kw={"bailor","forgefer","jordan morpuits","arme de paladin","minerai raffiné","the test of righteousness"},ang={["class:Paladin"]="En tant que paladin, vous devez faire preuve de patience et de dévouement pour obtenir cette cargaison raffinée. Elle fait partie des épreuves concrètes nécessaires à la création de votre arme symbolique de la Lumière.",["profession:Blacksmithing"]="En tant que forgeron, vous savez que forger une arme d’exception exige des lingots impeccables et soigneusement préparés, plutôt que du minerai brut extrait sur le terrain."},sec={{t="Matériaux de forgeron",b="Jordan Morpuits a besoin de matériaux rares pour une arme digne d’un paladin. Il lui faut une Gemme de Kor purifiée, du Bois de chêne de blanchepierre robuste, son marteau de forge perdu et du minerai raffiné. La cargaison apporte le métal à Forgefer pour cette œuvre sacrée."}},faq={{q="À quoi sert la Cargaison de minerai raffiné de Jordan ?",a="Le minerai raffiné est destiné à Jordan Morpuits, près de Forgefer. C’est l’un des quatre composants essentiels d’une arme d’exception pour les paladins qui entreprennent The Test of Righteousness.",al={"utilité du minerai raffiné","que fait jordan du minerai","utilité de la cargaison de minerai"}},{q="Qui prépare le minerai raffiné ?",a="Bailor organise l’expédition et supervise le raffinage ainsi que l’envoi du métal spécial dont Jordan Morpuits a besoin.",al={"qui a préparé le minerai","minerai de bailor","qui raffine le minerai de jordan"}},{q="Pourquoi Jordan a-t-il besoin de cette cargaison en particulier ?",a="Jordan Morpuits prévoit de fabriquer un symbole de la condition de paladin et de la Lumière. Il lui faut des matériaux de qualité supérieure, au-delà des rebuts ordinaires de forge. Le métal spécialement traité donne à la lame ou à la tête de marteau l’équilibre et la pureté dignes d’un chevalier sacré.",al={"pourquoi du minerai spécial","pourquoi jordan ne peut-il pas utiliser du fer ordinaire","raison du minerai raffiné"}}},fx={ec64bb0f={q="Qu'est-ce que la Cargaison de minerai raffiné de Jordan ?",a="La Cargaison de minerai raffiné de Jordan est une caisse de métal de haute qualité, spécialement traité, préparée pour l'armurier Jordan Morpuits. Destiné à la forge fine plutôt qu'au travail de forge ordinaire, ce minerai raffiné fournit la base métallique pure dont Jordan a besoin pour fabriquer une arme exceptionnelle digne d'un paladin dévoué de la Lumière.",al={"qu'est-ce que la cargaison de minerai raffiné de jordan","lore de la cargaison de minerai raffiné de jordan","qu'est-ce que le minerai raffiné de jordan"}}},fp="29,158,19.241.0,47.167.0,29.114.0,44.240.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="Marteau de forge de Jordan",s="Jordan Morpuits attend près de Forgefer le marteau de son père, perdu dans le Donjon d'Ombrecroc.",h="Jordan Morpuits attend près de Forgefer le marteau de son père, perdu dans le Donjon d'Ombrecroc.",kw={"dun morogh","forgefer","jordan morpuits","arme de paladin","donjon d'ombrecroc","marteau de forge","the test of righteousness"},ang={["class:Paladin"]="En tant que paladin, vous devez vous aventurer dans des terres périlleuses pour récupérer le marteau de famille et prouver votre détermination lors des épreuves de la droiture.",["profession:Blacksmithing"]="En tant que forgeron, vous connaissez le lien qui unit un maître forgeron à un marteau transmis par ses ancêtres."},sec={{t="L'héritage d'un artisan",b="Jordan Morpuits est un forgeron humain qui travaille près de Forgefer. Le marteau de son père se trouve dans le Donjon d'Ombrecroc, dans la Forêt des Pins-Argentés. Sans lui, Jordan ne peut pas forger une arme sacrée digne d'un champion de la foi, le chef-d'œuvre qu'il espère créer."}},faq={{q="Où se trouve le Marteau de forge de Jordan ?",a="Le Marteau de forge de Jordan se trouve dans le Donjon d'Ombrecroc, au cœur des forêts de la Forêt des Pins-Argentés. Les paladins qui passent The Test of Righteousness doivent pénétrer dans la forteresse occupée pour le récupérer.",al={"emplacement du marteau","où se trouve le marteau de jordan","où trouver le marteau de forge de jordan"}},{q="Pourquoi ce marteau est-il si important pour Jordan Morpuits ?",a="Jordan a hérité du marteau de son père, et il y tient beaucoup. Il en a besoin pour forger sa plus belle œuvre, une arme sacrée consacrée à la Lumière.",al={"pourquoi jordan veut le marteau","histoire du marteau de jordan morpuits"}},{q="À quoi sert le marteau une fois récupéré ?",a="Apportez le marteau à Jordan, près des portes de Forgefer, avec du bois, du minerai et une gemme. Il forgera une arme sacrée pour le paladin qui l'a aidé.",al={"que fabrique le marteau","utilité du marteau pour the test of righteousness"}}},fx={["126e648c"]={q="Qu'est-ce que le Marteau de forge de Jordan ?",a="Le Marteau de forge de Jordan est un outil de forge précieux appartenant au maître forgeron Jordan Morpuits. Au-delà de son utilisation pratique à l'enclume, il revêt une profonde valeur sentimentale en tant qu'héritage transmis à Jordan directement par son père.",al={"qu'est-ce que le marteau de forge de jordan","objet marteau de jordan","à propos du marteau de forge de jordan"}},["1df19239"]={q="D'où vient le Marteau de forge de Jordan et qui l'a fabriqué ?",a="Le marteau a été transmis à Jordan Morpuits par son père. Son fabricant exact n'est pas répertorié, mais avant que vous ne le récupériez, l'héritage avait fini par se retrouver loin de Forgefer, caché dans les sombres remparts du Donjon d'Ombrecroc.",al={"d'où vient le marteau de jordan","qui a fabriqué le marteau de forge de jordan","origine du marteau de forge de jordan"}}},fp="24,93,20.244.0,42.172.0,51.148.0,43.150.0"}
P.entries["item:jungle-remedy"] = {n="Jungle Remedy",s="Au Camp rebelle, Jungle Remedy peut aider les blessés à rester en état de combattre les forces de Kurzen. Le Sergent Yohwa a besoin de remèdes provenant de Kurzen Compound pour soigner les combattants du camp.",h="Au Camp rebelle, Jungle Remedy peut aider les blessés à rester en état de combattre les forces de Kurzen.",kw={"réducteurs de têtes","jungle remedy","kurzen","guérisseurs","camp rebelle","sergent yohwa","vallée de strangleronce","docteurs vaudou"},sec={{t="Le besoin d’un camp",b="Les Medicine Men de Kurzen utilisent les Jungle Remedies pour soigner leurs combattants dans le complexe. Le Sergent Yohwa en a besoin au Camp rebelle, où ils peuvent aider ses propres gens à rester en vie et prêts à combattre."}},faq={{q="À quoi sert Jungle Remedy ?",a="Le Sergent Yohwa a besoin des Jungle Remedies pour soigner les combattants du Camp rebelle et les maintenir en état de combattre Kurzen.",al={"utilisation de jungle remedy","effet du remède"}},{q="Qui porte des Jungle Remedies ?",a="Les Kurzen Medicine Men, Witch Doctors et Headshrinkers portent des Jungle Remedies. Les Jungle Fighters en ont parfois sur eux.",al={"où trouver des remèdes","médecine de kurzen"}},{q="Pourquoi le Sergent Yohwa en a-t-il besoin ?",a="Les forces de Kurzen utilisent les remèdes pour soigner leurs propres combattants, et le Sergent Yohwa en a besoin pour prendre soin des blessés au Camp rebelle.",al={"pourquoi yohwa les veut","médecine du camp rebelle"}},{q="Où trouver des Jungle Remedies ?",a="Cherchez dans Kurzen Compound, dans la Vallée de Strangleronce ; les guérisseurs de Kurzen et d’autres combattants portent ces remèdes.",al={"emplacement du remède","où trouver des remèdes"}}},fp="13,185,15.194.0,26.121.0,28.116.0,34.135.0,33.107.0"}
P.entries["item:jungle-stalker-feather"] = {n="Jungle Stalker Feather"}
P.entries["item:kadrak-s-flag"] = {n="Drapeau de Kadrak",s="À la frontière des Tarides, Kadrak envoie les couleurs de la Horde en territoire ennemi. La bannière est plantée dans l'antre des Serres après la mort de Rynthariel.",h="À la frontière des Tarides, Kadrak envoie les couleurs de la Horde en territoire ennemi.",kw={"tarides","horde presence","kadrak","drapeau de kadrak","rynthariel","les serres-rocheuses","pic des serres-rocheuses","antre des serres"},ang={["faction:Horde"]="Planter la bannière au plus profond de l'antre des Serres affirme la puissance de la Horde. Cela montre que la Horde frappera les sanctuaires des Elfes de la nuit si on la provoque.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous voyez la bannière de la Horde dans l'antre des Serres comme une insulte directe aux protecteurs du Pic des Serres-Rocheuses."},sec={{t="Un signe de défi",b="Kadrak envoie le drapeau de la Horde dans l'antre des Serres, au Pic des Serres-Rocheuses. Rynthariel, la dryade maîtresse des clés de l'antre, a envoyé des messages au-delà de la frontière. Kadrak estime que sa mort ne suffira pas à leur répondre. Il vous confie une bannière cramoisie à planter au plus profond de l'antre. Là, les couleurs de la Horde avertiront les Elfes de la nuit et les dryades que toute incursion à travers les Tarides entraînera des représailles en territoire de l'Alliance."}},faq={{q="À quoi sert le Drapeau de Kadrak ?",a="Après avoir tué Rynthariel, la maîtresse des clés, plantez le Drapeau de Kadrak dans l'antre des Serres, au sommet du Pic des Serres-Rocheuses. La bannière de la Horde avertit les Elfes de la nuit de ne plus envoyer d'éclaireurs ni de messagers dans les Tarides.",al={"utilité du drapeau","pourquoi planter le drapeau","à quoi sert le drapeau"}},{q="Qui vous remet le drapeau ?",a="Kadrak vous remet la bannière. C'est un éclaireur orc au poste de garde frontalier entre le nord des Tarides et Orneval, où il veille à sécuriser la région.",al={"qui remet le drapeau","où obtenir le drapeau","emplacement de kadrak"}},{q="Où planter le drapeau ?",a="Plantez la bannière dans l'antre des Serres, un sanctuaire troglodytique sur les versants ouest du Pic des Serres-Rocheuses, dans les Serres-Rocheuses.",al={"où planter le drapeau","emplacement du drapeau","emplacement du drapeau dans l'antre des serres"}},{q="Qui est Rynthariel ?",a="Rynthariel est une dryade et la maîtresse des clés de l'antre des Serres. Elle envoie des messagers en territoire de la Horde jusqu'à ce que Kadrak intercepte ses communications et ordonne sa mort.",al={"dryade rynthariel","qui est rynthariel","maîtresse des clés"}}},fx={["555b344d"]={q="Qu'est-ce que le Drapeau de Kadrak ?",a="Le Drapeau de Kadrak est un emblème de la Horde, qui vous a été confié par le commandant d'avant-poste orc Kadrak à la frontière entre les Tarides et Orneval. Portant les couleurs et le sceau de la Horde, il sert de marqueur territorial indubitable destiné à revendiquer un terrain et à diffuser un message de défi sans compromis aux forces de l'Alliance s'aventurant vers le sud.",al={"qu'est-ce que le drapeau de kadrak","drapeau de kadrak","à propos du drapeau de kadrak"}},["52bd9818"]={q="Pourquoi Kadrak veut-il que son drapeau soit planté dans l'Antre des Serres ?",a="Kadrak veut que la bannière soit plantée directement au cœur de l'Antre des Serres sur le Pic des Serres-Rocheuses après que la chef dryade Rynthariel ait été tuée. Planter l'étendard de la Horde dans leur sanctuaire garantit que tout éclaireur survivant ou sympathisant de l'Alliance comprenne que toute intrusion sur le territoire de la Horde sera accueillie par des représailles décisives et mortelles.",al={"pourquoi planter le drapeau de kadrak","pourquoi kadrak veut-il que le drapeau soit placé","but de la plantation du drapeau"}}},fp="13,140,18.386.0,31.202.0,23.145.0,26.127.0,18.161.0"}
P.entries["item:karnitol-s-satchel"] = {n="Karnitol's Satchel",s="La sacoche de Karnitol contient des effets recherchés après le naufrage de son navire en Désolace. Kreldig Ungor oriente les recherches vers les nagas Slitherblade le long de la côte.",h="La sacoche de Karnitol contient des effets recherchés après le naufrage de son navire en Désolace.",kw={"désolace","karnitol","sacoche de karnitol","kreldig ungor","nagas","ile de ranazjar","reclaimers","roetten martel-de-pierre","sacoche","slitherblade"},ang={["faction:Alliance"]="Les Reclaimers recherchent les effets de Karnitol, et Kreldig Ungor considère leur récupération comme un grand service rendu aux Reclaimers."},sec={{t="Parmi les Slitherblade",b="Kreldig Ungor vous dirige vers l’Ile de Ranazjar, où les nagas Slitherblade vivent au milieu de ruines d’elfes de la nuit sous la mer. Il pense que les puissants chasseurs des marées et les sorcières des mers ont peut-être rassemblé les effets de Karnitol. La sacoche est récupérée auprès d’eux le long de la côte de Désolace."},{t="De retour chez les Reclaimers",b="En Désolace, vous rendez la sacoche récupérée à Kreldig Ungor, qui estime que c’est un grand service rendu aux Reclaimers. Il l’envoie ensuite à Roetten Martel-de-pierre, à Forgefer. Roetten affirme que le coffre a été détruit, mais que les effets sont là, et laisse Karnitol juger de leur état."}},faq={{q="Qui recherche la sacoche de Karnitol ?",a="Kreldig Ungor dirige les recherches des effets de Karnitol au nom des Reclaimers. La sacoche est ensuite remise à Roetten Martel-de-pierre, à Forgefer.",al={"qui veut la sacoche","effets de karnitol","sacoche pour qui"}},{q="Où puis-je trouver la sacoche ?",a="Les nagas Slitherblade de la côte de Désolace ont peut-être les effets de Karnitol. Kreldig Ungor vous dirige vers leurs chasseurs des marées et leurs sorcières des mers, près de l’Ile de Ranazjar.",al={"où est la sacoche","emplacement de la sacoche","trouver le sac de karnitol"}},{q="Qui sont les Slitherblade ?",a="Les Slitherblade sont une tribu de nagas qui vivent au milieu de ruines d’elfes de la nuit sous la mer, près de l’Ile de Ranazjar, en Désolace.",al={"nagas slitherblade","nagas en désolace","qui vit sur l’ile de ranazjar"}},{q="Qui reçoit la sacoche à Forgefer ?",a="Roetten Martel-de-pierre reçoit la sacoche à Forgefer et dit que Karnitol pourra juger si les effets récupérés sont satisfaisants.",al={"sacoche à forgefer","qui reçoit le sac","sacoche de roetten"}},{q="Le coffre de Karnitol a-t-il été récupéré intact ?",a="Non. Roetten Martel-de-pierre dit que le coffre a été détruit, mais que les effets sont là pour que Karnitol les examine.",al={"qu’est-il arrivé au coffre","coffre détruit","effets de karnitol endommagés"}}},fp="18,163,22.274.0,22.283.0,38.150.0,29.164.0,26.115.0,38.132.1,38.110.1"}
P.entries["item:keg-of-shindigger-stout"] = {n="Tonneau de Croquejarret brune",s="À Dun Garok, la Croquejarret brune remplit les tonneaux des nains et attire l’attention du Moulin-de-Tarren. La Société royale des apothicaires la convoite pour un dessein plus sombre que la boisson.",h="À Dun Garok, la Croquejarret brune remplit les tonneaux des nains et attire l’attention du Moulin-de-Tarren.",kw={"apothicaire lydon","dun garok","bière naine","elixir of agony","tonneau de croquejarret brune","croquejarret brune","moulin-de-tarren"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez frapper Dun Garok, un avant-poste militaire de l’Alliance dans les collines du sud-est des Contreforts de Hautebrande.",["race:Undead"]="En tant que Réprouvé, vous pouvez utiliser de l’alcool pour masquer l’odeur et le goût des concoctions mortelles destinées à Dame Sylvanas."},sec={{t="Une bière prisée des nains",b="Les nains de Forgefer tiennent Dun Garok, dans le sud-est des Contreforts de Hautebrande. Dans les casernes et les réfectoires, les défenseurs partagent de la Croquejarret brune pour affronter le froid et le siège mené par leurs ennemis régionaux. Cette bière fait partie du quotidien de la garnison."},{t="Le récipient empoisonné de l’Apothicaire Lydon",b="L’Apothicaire Lydon, au Moulin-de-Tarren, cherche un tonneau intact de Croquejarret brune pour l’Elixir of Agony des Réprouvés. Il refuse de tester la formule sur des bêtes. Il prévoit plutôt d’empoisonner la bière pour la faire boire à des fermiers humains captifs détenus au Moulin-de-Tarren."}},faq={{q="À quoi sert la Croquejarret brune ?",a="L’Apothicaire Lydon, au Moulin-de-Tarren, veut de la Croquejarret brune pour l’Elixir of Agony. Il prévoit d’empoisonner la bière et de la tester sur des sujets humanoïdes.",al={"pourquoi obtenir de la croquejarret brune","utilité de la croquejarret brune","que fait lydon du tonneau"}},{q="Où trouver un Tonneau de Croquejarret brune ?",a="Les nains entreposent des tonneaux de Croquejarret brune à Dun Garok, dans le sud-est des Contreforts de Hautebrande. Ils les gardent dans les réfectoires et les casernes inférieures de la forteresse.",al={"emplacement du tonneau","où trouver la croquejarret brune","trouver la bière"}},{q="Qui brasse la Croquejarret brune ?",a="Les nains de Dun Garok brassent et conservent la Croquejarret brune. Ils tiennent une garnison fortifiée dans les Contreforts de Hautebrande pour Forgefer.",al={"qui brasse la croquejarret brune","est-ce une bière naine"}},{q="Pourquoi l’Apothicaire Lydon ne brasse-t-il pas son propre alcool pour l’expérience ?",a="Lydon demande un tonneau entreposé à Dun Garok pour son expérience. Le récit ne donne aucune autre raison et ne dit pas qu’il brasse lui-même de l’alcool.",al={"pourquoi voler la bière naine","pourquoi la bière de dun garok"}}},fx={b55cb0ca={q="Qu'est-ce qu'un Tonneau de Croquejarret brune ?",a="Un Tonneau de Croquejarret brune est un baril de bière naine puissante conservé par les nains de Forgefer stationnés dans la forteresse de Dun Garok. Bien qu'il soit destiné à approvisionner les soldats nains pendant leur déploiement dans les Contreforts de Hautebrande, sa forte infusion en fait un excellent vecteur pour les expériences de l'apothicaire Lydon pour le compte de la Société royale des apothicaires.",al={"qu'est-ce que le tonneau de croquejarret brune","infos sur le tonneau de croquejarret brune","qu'est-ce que la croquejarret brune"}}},fp="23,169,18.253.0,32.234.1,34.150.0,45.163.0,27.125.0,63.144.0"}
P.entries["item:ken-zigla-s-draught"] = {n="Breuvage de Ken'zigla",s="Dans les Serres-Rocheuses, Ken'zigla prépare un breuvage amer pour les blessés en très grave état. Une demi-dose peut leur rendre assez de forces pour bouger, mais une dose plus forte risque de les faire se vider de leur sang.",h="Dans les Serres-Rocheuses, Ken'zigla prépare un breuvage amer pour les blessés en très grave état.",kw={"camp taurajo","dogran","grunt logmar","breuvage de ken'zigla","kenzigla","les serres-rocheuses","quête de la succube","les tarides"},ang={["class:Warlock"]="En tant que démoniste, vous devez trouver le breuvage et le livrer au cours de vos épreuves pour invoquer et asservir une succube. La traversée des Tarides met à l'épreuve votre ingéniosité et votre sens de la piste.",["faction:Horde"]="Le Camp Taurajo étant affaibli par les patrouilles parties chercher des vivres, le breuvage est le seul espoir d'un agent capturé derrière les lignes ennemies des groinsecs."},sec={{t="Un remède amer",b="Ken'zigla prépare le breuvage dans les Serres-Rocheuses pour ceux qui sont au seuil de la mort. Sa puissance exige de la prudence. Plus d'une demi-dose à la fois peut faire se vider un patient de son sang lorsque sa circulation s'accélère. Une demi-dose donne à un blessé assez de vigueur pour bouger et fuir le danger. Le reste doit attendre que son corps se stabilise après une nuit complète de repos."},{t="La clémence dans les Tarides",b="Les démonistes de la Horde emportent le breuvage dans un campement hostile de Crins-de-rasoir, au nord du Camp Taurajo, où Dogran est retenu prisonnier. Cet agent a été capturé et torturé par des groinsecs. Le remède lui donne assez de vitalité pour s'éloigner en boitant, même si ses graves blessures l'ont privé définitivement de l'usage de ses membres."}},faq={{q="À quoi sert le Breuvage de Ken'zigla ?",a="Le Breuvage de Ken'zigla redonne des forces aux personnes mourantes ou grièvement blessées. Administré avec précaution, il peut aider un blessé à bouger et à s'échapper sans succomber à une hémorragie fatale.",al={"à quoi sert le breuvage de kenzigla","utilité du breuvage","pourquoi ai-je besoin du breuvage de kenzigla"}},{q="Qui prépare le breuvage ?",a="Ken'zigla prépare le breuvage dans les Serres-Rocheuses.",al={"qui prépare le breuvage","qui est kenzigla","emplacement de kenzigla"}},{q="Pourquoi ne faut-il prendre qu'une demi-dose à la fois ?",a="Le breuvage est exceptionnellement éprouvant pour le corps. Une demi-dose donne assez de vigueur pour bouger sans provoquer de grave hémorragie. Il faut attendre que le patient se soit reposé une nuit avant de lui donner l'autre moitié, afin d'éviter un effort fatal pour son corps.",al={"comment prendre le breuvage de kenzigla","demi-dose de breuvage","instructions pour le breuvage"}},{q="Qui reçoit le breuvage ?",a="Dogran reçoit le breuvage. C'est un agent retenu prisonnier et grièvement blessé dans un camp de groinsecs au nord du Camp Taurajo, dans les Tarides.",al={"qui boit le breuvage","qui est dogran","où livrer le breuvage"}},{q="Pourquoi envoie-t-on des démonistes récupérer ce remède ?",a="Les démonistes de la Horde qui cherchent à asservir une succube sont conduits jusqu'à Dogran, qui possède un objet chargé d'une profonde résonance émotionnelle. En lui apportant le breuvage, ils peuvent le rejoindre et obtenir ce dont ils ont besoin pour le rituel d'invocation.",al={"pourquoi les démonistes en ont-ils besoin","breuvage de la quête de la succube","quête de démoniste de kenzigla"}}},fx={["6eadaa9a"]={q="Qu'est-ce que le Breuvage de Ken'zigla ?",a="C'est un breuvage médicinal puissant au goût infect, préparé par l'apothicaire troll Ken'zigla dans les Serres-Rocheuses. Conçue pour supporter les traumatismes sévères, la mixture est assez puissante pour restaurer la vitalité d'un soldat mortellement blessé et lui permettre de bouger, bien qu'elle doive être administrée avec une grande prudence.",al={"qu'est-ce que le breuvage","breuvage de kenzigla","potion de kenzigla"}},["42d17912"]={q="Pourquoi le Breuvage de Ken'zigla est-il nécessaire ?",a="Un orc nommé Dogran a été capturé et brutalement torturé par des dos-hérissés dans les Tarides. Se vidant de son sang et proche de la mort en captivité, il ne peut survivre ou s'échapper sans la magie réparatrice du breuvage. Le Grunt Logmar au Camp Taurajo a désespérément besoin du remède pour que Dogran puisse supporter ses blessures assez longtemps pour fuir ses ravisseurs.",al={"pourquoi ont-ils besoin du breuvage","qui a besoin du breuvage de kenzigla","pourquoi fabriquer le breuvage"}}},fp="19,177,15.340.0,20.294.1,37.180.0,22.59.0,50.208.0,25.136.0,48.207.0"}
P.entries["item:khan-dez-hepah-s-head"] = {n="Khan Dez'hepah's Head",s="La tête de Khan Dez'hepah prouve que le chef des Kolkar a été vaincu. Felgur Doublecoupe la veut pour montrer sa force aux clans centaures.",h="La tête de Khan Dez'hepah prouve que le chef des Kolkar a été vaincu.",kw={"centaure","désolace","tête de dez'hepah","felgur doublecoupe","khan dez'hepah","kolkar","village des kolkar"},sec={{t="Preuve de force",b="En Désolace, les clans centaures se combattent. Felgur Doublecoupe craint qu'ils ne deviennent de redoutables ennemis s'ils s'unissaient. Il vous envoie donc perturber les Kolkar en vainquant leur chef, Khan Dez'hepah. Il vous demande de lui rapporter sa tête en guise de preuve."}},faq={{q="Qui veut la tête de Khan Dez'hepah ?",a="Felgur Doublecoupe vous demande de lui rapporter la tête de Khan Dez'hepah en Désolace.",al={"qui la veut","demande de tête de felgur"}},{q="Pourquoi Felgur veut-il cette tête ?",a="Felgur veut perturber le clan des Kolkar et montrer sa force aux clans centaures de Désolace.",al={"pourquoi prendre la tête","à quoi sert-elle"}},{q="Qui était Khan Dez'hepah ?",a="Khan Dez'hepah était le chef du clan des Kolkar en Désolace.",al={"qui est dez'hepah","chef des kolkar"}},{q="Où trouver Khan Dez'hepah ?",a="Khan Dez'hepah se trouve au Village des Kolkar, au nord-est de Felgur Doublecoupe.",al={"où est dez'hepah","emplacement du village des kolkar"}}},fp="21,145,17.256.0,32.74.0,30.91.0,23.61.0,32.65.0"}
P.entries["item:khan-jehn-s-head"] = {n="Khan Jehn's Head",s="La tête de Khan Jehn prouve que le khan Magram a été tué. Uthek la Sage, du Village des Gelkis, l’exige comme preuve d’amitié envers le clan des Gelkis.",h="La tête de Khan Jehn prouve que le khan Magram a été tué.",kw={"centaure","désolace","magie de la terre","gelkis","jehn","khan jehn","tête de khan jehn","magram","uthek la sage"},sec={{t="Un signe d’amitié",b="À Désolace, Uthek la Sage vous demande d’apporter Khan Jehn's Head au Village des Gelkis. Jehn dirige les centaures Magram rivaux, et Uthek dit que la terre lui révèle que leur clan s’affaiblit. Les Gelkis veulent la mort du khan ennemi et comptent sur vous pour prouver que vous êtes de leur côté."},{t="La chute du khan",b="À votre retour avec Khan Jehn's Head, Uthek dit que Jehn était fort, mais sot. Il croit que la magie de la terre surpasse la puissance de Jehn. Le chef Magram ayant disparu, Uthek s’attend à voir le clan s’effondrer et affirme que les Gelkis régneront sur Désolace."}},faq={{q="Qui veut Khan Jehn's Head ?",a="Uthek la Sage, du Village des Gelkis, vous demande d’apporter Khan Jehn's Head en preuve de votre amitié envers les Gelkis.",al={"qui veut la tête","tête d’uthek","requête des gelkis"}},{q="Qui était Khan Jehn ?",a="Khan Jehn était le chef des centaures Magram, rivaux du clan des Gelkis.",al={"qui est jehn","khan magram","khan jehn"}},{q="Pourquoi les Gelkis veulent-ils la mort de Jehn ?",a="Uthek dit que les Magram s’affaiblissent et vous demande de tuer leur khan. Il croit que les Gelkis pourront régner une fois Jehn disparu.",al={"pourquoi tuer jehn","gelkis contre magram","pourquoi jehn"}},{q="Où dois-je apporter Khan Jehn's Head ?",a="Apportez Khan Jehn's Head à Uthek la Sage, au Village des Gelkis, à Désolace.",al={"où apporter la tête","apporter la tête de jehn","emplacement d’uthek"}},{q="Que dit Uthek après la chute de Jehn ?",a="Uthek dit que Jehn était fort, mais sot, et que les Magram s’effondreront sans leur chef. Il s’attend à ce que les Gelkis règnent.",al={"fin de la quête d’uthek","que se passe-t-il après jehn","règne des gelkis"}}},fp="16,152,20.273.0,15.231.1,27.107.0,18.78.0,33.122.0,34.72.0,37.118.1"}
P.entries["item:khan-shaka-s-head"] = {n="Khan Shaka's Head",s="La tête de Khan Shaka est celle du khan des Gelkis, recherchée par Warug des Magram en Désolace. Elle témoigne de la force des Magram face à leur clan rival.",h="La tête de Khan Shaka est celle du khan des Gelkis, recherchée par Warug des Magram en Désolace.",kw={"centaure","désolace","gelkis","khan shaka","magram","village des magram","tête de shaka","warug"},sec={{t="La tête d’un khan",b="Warug, du Village des Magram, veut la tête de Khan Shaka après votre aide aux Magram. Shaka dirige les Gelkis, et Warug compte garder sa tête fichée sur une pique. Il veut que Shaka voie la force des Magram."}},faq={{q="Qui est Khan Shaka ?",a="Khan Shaka est le khan des centaures Gelkis en Désolace.",al={"shaka","identité de khan shaka","khan des gelkis"}},{q="Qui veut la tête de Khan Shaka ?",a="Warug la veut au Village des Magram, une fois que vous aurez fait vos preuves auprès des Magram.",al={"qui veut la tête de shaka","warug veut la tête","demande des magram"}},{q="Pourquoi Warug veut-il la tête ?",a="Warug veut garder la tête de Khan Shaka fichée sur une pique pour que Shaka voie la force des Magram.",al={"pourquoi la tête de shaka","raison de warug","force des magram"}},{q="Où faut-il apporter la tête de Khan Shaka ?",a="Vous devez apporter la tête de Khan Shaka à Warug, au Village des Magram, en Désolace.",al={"où apporter la tête","tête pour warug","tête au village des magram"}}},fp="17,153,13.201.0,18.57.0,30.79.0,29.94.1,35.74.0"}
P.entries["item:khazgorm-s-journal"] = {n="Journal de Khazgorm",s="À Bael Modan, le Prospecteur Khazgorm dirige les fouilles de Forgefer dans les Tarides du sud. Son journal consigne les travaux de la Ligue des explorateurs sur les terres revendiquées par les taurens des Totems-de-Pierre.",h="À Bael Modan, le Prospecteur Khazgorm dirige les fouilles de Forgefer dans les Tarides du sud.",kw={"bael modan","tarides","nain","ligue des explorateurs","gann cime-de-pierre","journal","khazgorm","prospecteur"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez aider Gann Cime-de-pierre à défendre Kalimdor contre les expéditions de l'Alliance qui s'aventurent en territoire de la Horde.",["race:Tauren"]="En tant que tauren, vous pouvez lire le journal comme la preuve que les envahisseurs de Forgefer ne tiennent aucun compte de la tribu des Totems-de-Pierre lorsqu'ils dynamitent ses terres ancestrales."},sec={{t="Un témoignage de destruction",b="Le Prospecteur Khazgorm dirige les machines et les opérations de dynamitage qui entaillent les collines des Tarides du sud. Les fouilles se sont éloignées de la quête de savoir promise par la Ligue des explorateurs. Elles ont déplacé la tribu des Totems-de-Pierre. Les taurens ont cherché un accord pacifique, mais les nains l'ont refusé. Gann Cime-de-pierre veut le journal pour comprendre pourquoi Forgefer se trouve sur sa terre natale et comment chasser l'expédition."},{t="Un changement de tactique",b="Gann Cime-de-pierre trouve le journal parmi les restes de Khazgorm, près des tentes et des piliers du site de fouilles. Ses notes révèlent l'organisation de l'expédition, son équipement et ses points faibles. Fort de ces informations, Gann cesse de repousser les ouvriers et s'en prend aux machines de l'excavation. Le journal change le cours de la lutte pour Bael Modan."}},faq={{q="À qui appartient ce journal ?",a="Le journal appartient au Prospecteur Khazgorm, chef des fouilles des nains de Forgefer à Bael Modan, dans les Tarides du sud.",al={"propriétaire du journal","khazgorm","prospecteur khazgorm"}},{q="Pourquoi Gann Cime-de-pierre veut-il ce livre ?",a="Gann Cime-de-pierre veut étudier les plans et les secrets des nains après qu'ils ont déplacé sa tribu. Les notes de Khazgorm l'aident à préparer de nouvelles attaques contre le campement de Bael Modan.",al={"pourquoi gann veut le journal","journal de quête de gann","livre de reconquête de gann"}},{q="Où trouver le journal ?",a="Le Prospecteur Khazgorm porte le journal parmi les tentes et les piliers rocheux du site de fouilles en activité, juste au sud de Bael Modan.",al={"où trouver le journal de khazgorm","trouver le journal de khazgorm","emplacement de khazgorm"}},{q="Que révèle le journal sur les nains ?",a="Le journal montre que la quête de la Ligue des explorateurs pour retrouver des reliques enfouies et l'héritage des titans se fait au prix de violences directes contre des tribus comme les taurens des Totems-de-Pierre.",al={"ligue des explorateurs dans les tarides","secrets du site de fouilles des nains","but de bael modan"}}},fx={["6ed76dba"]={q="D'où vient le Journal de Khazgorm et qui l'a créé ?",a="Le journal a été écrit par le prospecteur Khazgorm, un chef parmi les excavateurs nains de la Ligue des explorateurs stationnés à Bael Modan dans les Tarides du sud. Khazgorm tenait le livre pour enregistrer les découvertes de son expédition et ses affaires quotidiennes tout en labourant les terres ancestrales des taurens Piton-de-pierre.",al={"origine du journal de khazgorm","qui a écrit le journal de khazgorm","d'où vient le journal de khazgorm"}}},fp="18,180,23.415.0,18.357.1,31.122.0,40.187.0,31.123.0,47.163.0"}
P.entries["item:klaven-mortwake-s-journal"] = {n="Journal de Klaven Morteveille",s="Les agents du SI:7 récupèrent le Journal de Klaven Morteveille dans la tour défias. Il relate les recherches de la Confrérie pour trouver un moyen de relever les morts.",h="Les agents du SI:7 récupèrent le Journal de Klaven Morteveille dans la tour défias.",kw={"tour défias","coffre du bois de la pénombre","journal","klaven mortwake","mathias shaw","poisons","si:7","zanzil"},ang={["class:Rogue"]="En tant que voleur, vous prouvez votre maîtrise du crochetage et de la discrétion en pénétrant dans la tour pour prendre le journal de Mortwake. Cette mission vous initie aussi à la préparation de poisons mortels.",["faction:Alliance"]="En tant que membre de l’Alliance, vous fournissez aux maîtres-espions de Hurlevent la preuve que le soulèvement des Défias dépasse le mécontentement des ouvriers. Le journal révèle des liens avec des sorciers-docteurs trolls et la nécromancie alchimique."},sec={{t="Une formule macabre",b="La tour défias se dresse sur les crêtes du nord de la Marche de l’Ouest. D’étranges cargaisons arrivent des frontières ténébreuses du Bois de la Pénombre, et des sentinelles difformes et non humaines gardent la tour. Le SI:7 a surveillé les lieux pendant longtemps. Dans le coffre tout en haut, ses agents ont trouvé le journal de Klaven Mortwake et découvert le contenu des cargaisons.\n\nKlaven Mortwake y a consigné des recherches sur des méthodes alchimiques pour relever des serviteurs morts-vivants décérébrés. Des alchimistes associés aux trolls de Zanzil, dans la Vallée de Strangleronce, avaient trouvé un moyen grâce à des poisons et des breuvages spécialisés. La Confrérie défias cherchait à reproduire leur méthode pour ses propres rangs."},{t="Renseignements pour le SI:7",b="Maître Mathias Shaw dirige le service de renseignement de Hurlevent, le SI:7. Il cherchait le journal de Mortwake pour retracer les alliances plus vastes de la Confrérie. Les notes confirment des expériences de réanimation et un soutien illicite reliant le Bois de la Pénombre, la KapitalRisk et les Défias. Pour les voleurs au service de la couronne, récupérer ces recherches est un pas vers la maîtrise des poisons."}},faq={{q="Qu’est-ce que le Journal de Klaven Morteveille ?",a="Le Journal de Klaven Morteveille est un carnet de recherche compilé par Klaven Mortwake, un agent de la tour défias au nord-est de la Marche de l’Ouest. Il contient des notes sur la nécromancie alchimique et des voies d’approvisionnement illicites.",al={"qu’est-ce que le journal de klaven","journal de mortwake","qu’est-ce que cet objet"}},{q="Où trouve-t-on le journal ?",a="Le journal est enfermé dans un Coffre du bois de la Pénombre, au dernier étage de la tour défias, dans le nord de la Marche de l’Ouest. Des sentinelles mortes-vivantes le gardent, et une clé prise à l’un des gardes monstrueux de Klaven ouvre le coffre.",al={"où trouver le journal de klaven","emplacement du journal de klaven","emplacement du coffre du bois de la pénombre"}},{q="Quels secrets le journal renferme-t-il ?",a="Le journal indique que les trolls de Zanzil de la Vallée de Strangleronce ont conçu des potions toxiques capables de relever les morts et de les contrôler. La Confrérie défias tentait de se procurer la recette et de l’utiliser.",al={"que dit le journal","secrets du journal","poison de zanzil"}},{q="Qui veut ce journal ?",a="Maître Mathias Shaw, chef de l’agence de renseignement SI:7 de Hurlevent, veut le journal pour surveiller la logistique des Défias et enseigner aux agents de la couronne les dangers et les usages des poisons tactiques.",al={"qui récupère le journal de klaven","à qui donner le journal","journal de mathias shaw"}}},fx={["887d3337"]={q="D'où vient le Journal de Klaven Morteveille et qui l'a créé ?",a="Le journal appartient à Klaven Morteveille, qui supervisait la forteresse de The Defias Brotherhood à la tour dans la Marche de l’Ouest. Il a été expédié avec des gardes morts-vivants sinistres et un coffre arrivant du Bois de la Pénombre, détaillant des secrets alchimiques sombres provenant des trolls de Zanzil the Outcast dans la Vallée de Strangleronce.",al={"qui a écrit le journal de klaven","origine du journal de klaven morteveille","d'où klaven a-t-il obtenu le journal"}}},fp="25,137,18.586.1,21.348.0,34.203.0,27.201.0,44.188.0,23.183.0"}
P.entries["item:kodo-bone"] = {n="Kodo Bone",s="Les os de kodo du Cimetière des kodos, en Désolace, ont de la valeur pour Bibbly F'utzbuckle. Il leur trouve de nombreux usages, des meubles et instruments à la poudre explosive.",h="Les os de kodo du Cimetière des kodos, en Désolace, ont de la valeur pour Bibbly F'utzbuckle.",kw={"bibbly f'utzbuckle","ramasseur d'os","désolace","os de kodo","cimetière des kodos","hutte de kormek","proie-de-l'ombre"},sec={{t="Un commerce gobelin",b="À la Hutte de Kormek, Bibbly F'utzbuckle cherche des os de kodo dans le cimetière au sud de chez lui. Il dit que ses clients en font des meubles, des instruments de musique et de la poudre explosive. Une caravane transporte ses os jusqu'à Proie-de-l'Ombre, et Bibbly espère que ce commerce le rendra riche."}},faq={{q="Qui veut des os de kodo ?",a="À la Hutte de Kormek, Bibbly F'utzbuckle veut des os de kodo du Cimetière des kodos.",al={"acheteur d'os de kodo","qui veut les os"}},{q="À quoi servent les os de kodo ?",a="Bibbly dit que ses clients font des meubles, des instruments de musique et de la poudre explosive avec les os de kodo.",al={"usages des os de kodo","que fabrique-t-on avec les os"}},{q="Où la caravane transporte-t-elle les os ?",a="Bibbly dit qu'une caravane vend ses os de kodo à Proie-de-l'Ombre.",al={"caravane d'os","où vont les os"}}},fp="9,158,18.273.0,21.76.0,29.99.0,38.65.0"}
P.entries["item:kodo-horn"] = {n="Corne de kodo",s="Dans les Tarides, Tonga Totem-runique soigne la faune empoisonnée avec des cornes de kodo.",h="Dans les Tarides, Tonga Totem-runique soigne la faune empoisonnée avec des cornes de kodo.",kw={"tarides","cénarien","earthroot","gazelle","corne de kodo","poison","tonga totem-runique"},ang={["class:Druid"]="En tant que druide de la Horde, vous recueillez des cornes sous la direction de Tonga Totem-runique, tout en apprenant à maîtriser les poisons de la nature.",["race:Tauren"]="En tant que tauren, vous portez les kodos en haute estime. Vous leur prenez ce dont vous avez besoin avec soin et dans un but précis, afin de protéger le fragile écosystème des Tarides."},sec={{t="Un ingrédient des plaines",b="Dans les Tarides, Tonga Totem-runique utilise des cornes de kodo entières dans ses remèdes à base de plantes. Il travaille depuis la Croisée, où les cornes renforcent ses baumes. Les éclats et les fragments n’ont pas la puissance nécessaire ; il recueille donc des cornes intactes sur les kodos adultes qui parcourent les plaines."}},faq={{q="À quoi servent les cornes de kodo ?",a="Tonga Totem-runique prépare un baume avec des cornes de kodo, de l’Earthroot et de l’eau pure pour soigner les gazelles empoisonnées des Tarides. Ce remède apprend à un druide à guérir le poison avec l’aide de la nature.",al={"utilité des cornes de kodo","pourquoi recueillir des cornes de kodo","usage des cornes de kodo"}},{q="Où ces cornes sont-elles recueillies ?",a="Vous pouvez récolter des cornes de kodo sur les Barrens Kodos et les Lost Barrens Kodos, dans le nord des Tarides, entre la Croisée et les broussailles alentour.",al={"où trouver des cornes de kodo","emplacement des cornes de kodo","quels kodos donnent des cornes"}},{q="Pourquoi les druides ne peuvent-ils pas utiliser des fragments de corne ?",a="Tonga Totem-runique explique que les éclats et les fragments n’ont pas la puissance nécessaire pour équilibrer le baume. Il lui faut des cornes intactes pour préparer un remède assez puissant contre les toxines virulentes.",al={"pourquoi pas des cornes brisées","éclats de corne"}},{q="La chasse aux kodos est-elle considérée comme respectueuse pour un druide ?",a="Oui. Les druides chassent les kodos pour préserver l’équilibre de la nature et prennent ce dont ils ont besoin pour soigner des fléaux plus graves, comme l’empoisonnement mystérieux qui frappe les troupeaux de gazelles locales.",al={"chasse aux kodos par les druides","équilibre et kodos"}}},fx={f5876d60={q="Qu'est-ce qu'une Corne de kodo ?",a="C'est une corne intacte récoltée sur les kodos massifs errant dans les savanes du nord des Tarides. Bien qu'elle soit souvent utilisée dans l'artisanat tribal ou pour des outils, les cornes entières et robustes sont prisées par les chamans et les druides comme des réactifs alchimiques puissants, capables d'infuser des mélanges médicinaux d'une forte fortitude naturelle.",al={"qu'est-ce qu'une corne de kodo","corne de kodo","à propos de la corne de kodo"}},["062d3e91"]={q="D'où viennent les Cornes de kodo ?",a="Ces cornes proviennent directement des kodos des Tarides qui paissent à travers les plaines arides. Abattre l'une de ces formidables bêtes permet aux chasseurs et aux druides de récupérer une corne intacte, à condition qu'elle n'ait pas été brisée ou usée en simples éclats et fragments.",al={"d'où vient la corne de kodo","origine de la corne de kodo","comment obtenir la corne de kodo"}}},fp="9,116,23.263.0,29.184.0,32.146.0,44.156.0,51.166.0"}
P.entries["item:kodo-kombobulator"] = {n="Kombobulateur Kodo",s="Le Kombobulateur Kodo permet à Smeed Scrabblescrew de dompter des kodos âgés en Désolace. Il s’en sert pour fournir des bêtes de somme à une caravane partenaire.",h="Le Kombobulateur Kodo permet à Smeed Scrabblescrew de dompter des kodos âgés en Désolace.",kw={"kodo âgé","caravane","désolace","kodo","kombobulateur kodo","smeed scrabblescrew","domptage"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous reconnaîtrez peut-être le savoir-faire gobelin derrière l’appareil de Smeed Scrabblescrew, conçu pour contrôler les kodos âgés."},sec={{t="Un appareil gobelin",b="Au camp de Scrabblescrew, en Désolace, Smeed Scrabblescrew prête le Kombobulateur Kodo pour dompter des kodos anciens ou âgés. L’appareil secoue chaque bête jusqu’à ce qu’elle le suive, offrant ainsi une source de nouvelles montures à la caravane locale. Smeed espère que ce partenariat lui rapportera un joli bénéfice."}},faq={{q="À quoi sert le Kombobulateur Kodo ?",a="Le Kombobulateur Kodo dompte les kodos anciens ou âgés et les fait suivre Smeed Scrabblescrew.",al={"appareil à kodos","à quoi sert le kombobulateur"}},{q="Qui a fabriqué le Kombobulateur Kodo ?",a="Smeed Scrabblescrew affirme avoir appris à rajeunir et à contrôler les kodos âgés et mourants grâce à son Kombobulateur Kodo.",al={"à qui appartient l’appareil à kodos","appareil de smeed"}},{q="Pourquoi Smeed veut-il des kodos domptés ?",a="Smeed, Cork, le propriétaire de la caravane, et Rigger ont formé un partenariat autour de sa capacité à dompter les kodos. La caravane compte sur son approvisionnement.",al={"pourquoi dompter les kodos","kodos pour la caravane"}},{q="Où trouver le Kombobulateur Kodo ?",a="Smeed Scrabblescrew, au camp de Scrabblescrew en Désolace, fournit le Kombobulateur Kodo pour son travail avec les kodos âgés.",al={"emplacement du kombobulateur","où se trouve smeed"}}},fp="17,144,17.268.0,35.92.0,31.110.0,32.130.0,39.116.0"}
P.entries["item:kodo-liver"] = {n="Foie de kodo",s="À Cabestan, le Brasseur Drohn a besoin de Foie de kodo pour préparer une bière étrange. Le maître brasseur itinérant Chen Stormstout lui a appris à la brasser.",h="À Cabestan, le Brasseur Drohn a besoin de Foie de kodo pour préparer une bière étrange.",kw={"tarides","brassage","chen stormstout","drohn","kodo","foie de kodo","cabestan","bière de trogg"},ang={["profession:Cooking"]="La viande de kodo nourrit les habitants du centre de Kalimdor, mais le Foie de kodo est jugé trop répugnant et âcre pour la cuisine ordinaire. Son utilisation dans la bière de trogg de Cabestan l'a rendu célèbre.",["race:Tauren"]="Les taurens honorent chaque partie des kodos qu'ils chassent. Même les coureurs des plaines aguerris regardent de travers les gobelins et les étrangers qui préparent à Cabestan des bières fantaisie avec des entrailles de kodo."},sec={{t="Un ingrédient insolite",b="Les kodos parcourent les Tarides, où les taurens et les prédateurs les chassent pour leur cuir et leur viande. À Cabestan, le Brasseur Drohn mélange un Foie de kodo frais avec des glandes salivaires de faucon-tonnerre et des glandes d'éclair pour préparer de la bière de trogg. Chen Stormstout lui a appris la recette, et Drohn affirme que ce breuvage a du mordant pour les voyageurs aventureux. Ses ingrédients viennent des contrées sauvages du centre de Kalimdor."}},faq={{q="À quoi sert un Foie de kodo ?",a="Le Brasseur Drohn, à Cabestan, utilise le Foie de kodo pour préparer de la bière de trogg. Chen Stormstout lui a appris la recette.",al={"utilité du foie de kodo","pourquoi avoir besoin de foie de kodo","à quoi sert le foie de kodo"}},{q="Quelles créatures donnent du Foie de kodo ?",a="Les kodos des Tarides donnent du Foie de kodo. On trouve parmi eux des kodos communs, laineux, égarés et supérieurs, ainsi que Lakota'mani et Brontus.",al={"où trouver du foie de kodo","qui donne du foie de kodo","source du foie de kodo"}},{q="Pourquoi mettre des organes d'animaux dans la bière ?",a="Le Brasseur Drohn suit les recettes inhabituelles que Chen Stormstout lui a enseignées. Des organes crus comme le Foie de kodo et des glandes élémentaires donnent à la bière de trogg son mordant et sa saveur prononcée.",al={"pourquoi du foie dans la bière","foie de kodo dans l'alcool"}}},fx={c325e464={q="D'où provient le Foie de kodo ?",a="Il est récolté directement sur les kodos sauvages qui errent dans la savane des Tarides, des bêtes errantes communes aux anciens mastodontes comme Lakota'mani et Brontus. Les chasseurs et les aventuriers le découpent après avoir abattu ces créatures massives.",al={"où obtenir le foie de kodo","qui donne le foie de kodo","source du foie de kodo"}},["328036a8"]={q="Pourquoi le Brasseur Drohn veut-il un Foie de kodo ?",a="Le Brasseur Drohn, à Cabestan, cherche un foie frais pour brasser une recette de bière de trogg peu conventionnelle, apprise du maître brasseur pandaren errant, Chen Brune-d'orage. Combiné à des glandes de foudre et de la salive de faucon-tonnerre, le foie donne à cette puissante boisson son goût caractéristique.",al={"pourquoi drohn a besoin du foie de kodo","qui veut le foie de kodo","utilisation de la quête foie de kodo"}},a4c717e9={q="Qu'est-ce qu'un Foie de kodo ?",a="C'est un organe interne récolté sur les kodos massifs à la peau épaisse qui errent dans les plaines des Tarides. Bien que ce ne soit pas un plat de taverne typique, sa nature puissante en fait un composant prisé pour les maîtres brasseurs excentriques qui concoctent des mixtures avec un goût vraiment légendaire.",al={"qu'est-ce qu'un foie de kodo","lore du foie de kodo","foie de kodo"}}},fp="10,128,25.371.0,30.101.0,35.127.0,42.165.0"}
P.entries["item:kodobane-s-head"] = {n="Tête de Plaie-des-kodos",s="Près des Bassins oubliés, la tête tranchée de Barak Kodobane prouve que le chef est mort. Regthar Deathgate la reçoit comme preuve que la menace centaure dans la région a été brisée.",h="Près des Bassins oubliés, la tête tranchée de Barak Kodobane prouve que le chef est mort.",kw={"barak","tarides","centaure","la croisée","deathgate","les bassins oubliés","kodobane","kolkar","regthar"},ang={["faction:Horde"]="Les routes des Tarides relient Orgrimmar et Pitons-du-Tonnerre par voie terrestre. Réprimer des chefs centaures comme Kodobane contribue à protéger les pistes caravanières.",["race:Tauren"]="Pendant des générations, les centaures ont repoussé les taurens nomades à travers Kalimdor, au bord de l’extinction. Tuer Barak Kodobane venge des siècles de violence et protège les pâturages de Mulgore et des Tarides."},sec={{t="Un trophée de guerre",b="Les bandes Kolkar des Tarides sont divisées depuis longtemps. À présent, des chefs de guerre ambitieux menacent de les rassembler en une armée. Barak Kodobane campe près des eaux des Bassins oubliés, où l’oasis offre des ressources vitales et où les chemins voisins sont exposés aux raids. Regthar Deathgate est posté dans un bunker à l’ouest de la Croisée. Il réclame la tête tranchée de Kodobane pour prouver que le commandant ne peut plus rallier les siens contre la Horde."}},faq={{q="Qui était Barak Kodobane ?",a="Barak Kodobane est un chef éminent parmi les centaures Kolkar. Rusé et autoritaire, contrairement à nombre des siens qui manquent de discipline, il organise des bandes de guerre et campe autour des Bassins oubliés pour asseoir la domination des Kolkar sur le nord des Tarides.",al={"barak kodobane","qui est kodobane","histoire de barak"}},{q="Pourquoi Regthar Deathgate veut-il sa tête ?",a="Regthar Deathgate est chargé de sécuriser le territoire de la Horde dans les Tarides. Les centaures sont généralement querelleurs, aussi les chefs dotés d’un sens tactique attirent-ils l’attention. Regthar réclame la tête de Kodobane pour s’assurer que le chef est bien mort et qu’il n’a pas simplement été chassé.",al={"pourquoi prendre sa tête","tête de regthar deathgate","prime sur kodobane"}},{q="Où trouver Barak Kodobane ?",a="Barak Kodobane campe près des Bassins oubliés, l’oasis du nord située juste au nord-ouest de la Croisée, dans les Tarides.",al={"emplacement de barak","où trouver kodobane","apparition de barak"}},{q="La mort de Barak met-elle fin à la menace Kolkar ?",a="Non. Barak Kodobane est le premier de plusieurs chefs de guerre qui rallient les Kolkar. Sa mort affaiblit leur présence aux Bassins oubliés, mais Verog the Dervish et Hezrul Bloodmark continuent de diriger l’agression des centaures dans les Tarides.",al={"les centaures sont-ils vaincus","que se passe-t-il après la mort de barak"}}},fx={["891c4b09"]={q="Qu'est-ce que la Tête de Plaie-des-kodos ?",a="Il s'agit de la tête tranchée de Barak Plaie-des-kodos, l'un des chefs éminents des centaures Kolkar dans les Tarides. Conservée comme preuve physique de la disparition du chef, elle signifie un coup décisif porté à la menace centaure coordonnée qui pèse sur les colonies de la Horde près des Bassins oubliés.",al={"qu'est-ce que la tête de plaie-des-kodos","objet tête de barak plaie-des-kodos","lore de la tête de barak"}}},fp="15,171,15.418.0,23.242.0,41.246.0,30.114.0,42.231.0"}
P.entries["item:kravel-s-crate"] = {n="Caisse de Kravel",s="Sur la Piste des mirages, Kravel Koalbarbe envoie une caisse à l'expédition Nesingwary, dans la Vallée de Strangleronce. Elle contient des munitions spéciales pour chasser le gibier le plus redoutable de la jungle.",h="Sur la Piste des mirages, Kravel Koalbarbe envoie une caisse à l'expédition Nesingwary, dans la Vallée de...",kw={"munitions","hemet nesingwary","kravel koalbarbe","caisse de kravel","piste des mirages","les salines","vallée de strangleronce"},ang={["class:Hunter"]="En tant que chasseur, vous trouvez dans la caisse de lourdes munitions spéciales. Elles sont conçues pour les fusils de chasse nains haut de gamme et les expéditions de chasse au gros gibier.",["race:Dwarf"]="En tant que nain, vous voyez les affaires de Kravel Koalbarbe dans les salines liées au célèbre groupe de chasse Nesingwary, dans les Royaumes de l'est."},sec={{t="Une livraison dans la jungle",b="Sur la Piste des mirages, Kravel Koalbarbe confie la caisse à des voyageurs. Un riche mécène nain l’a commandée des semaines plus tôt, mais l’expédition a été retardée jusqu’au départ de l’acheteur de Kalimdor. Le mécène avait payé pour faire suivre le colis, et Kravel tient à conserver les faveurs d’un riche client. Il fait donc confiance aux voyageurs de passage pour le transporter à travers les continents jusqu’au nord de la Vallée de Strangleronce."},{t="Munitions de calibre spécial",b="La poussière de sel s’accumule sur la caisse tandis qu’elle attend dans les Salines. Elle contient de lourdes cartouches de calibre spécial conçues pour les fusils de chasse. Les voyageurs les livrent au camp de l’expédition, au nord du Campement Grom'gol. Le destinataire explique que les chasseurs de gros gibier prisent ces puissantes munitions. Face aux prédateurs qui rôdent dans la canopée de la jungle, elles sont vitales pour survivre."}},faq={{q="Que contient la Caisse de Kravel ?",a="La Caisse de Kravel contient de lourdes munitions de calibre spécial pour fusils de chasse. Les chasseurs de gros gibier les utilisent contre les bêtes dangereuses de la nature.",al={"contenu de la caisse","contenu de la caisse de kravel"}},{q="Qui a envoyé la Caisse de Kravel ?",a="Kravel Koalbarbe a envoyé la caisse. C’est un marchand nain de la Piste des mirages, au milieu des courses et des jeux d’argent des Salines, dans Mille pointes.",al={"qui remet la caisse","à qui appartient la caisse de kravel"}},{q="Où faut-il livrer cette caisse ?",a="La caisse est destinée au camp de chasse de l’expédition Nesingwary, dans le nord de la Vallée de Strangleronce. Le camp se trouve le long de la rivière, au nord du Campement Grom'gol.",al={"où livrer la caisse","destination de la caisse","qui reçoit la caisse de kravel"}},{q="Pourquoi la livraison a-t-elle été retardée ?",a="Le colis a mis des semaines à atteindre les salines de Mille pointes. À ce moment-là, le client avait déjà plié bagage et était parti pour les jungles de la Vallée de Strangleronce.",al={"pourquoi kravel a-t-il mis si longtemps","pourquoi le retard"}}},fx={["3beca7b7"]={q="Qu'est-ce que la Caisse de Kravel ?",a="C'est un colis de livraison lourd détenu par Kravel Koalbarbe à la Piste des mirages dans les Salines. Emballée soigneusement pour un transport longue distance à travers Kalimdor et la Grande mer, la caisse contient des fournitures de chasse spécialisées destinées à une expédition dans les étendues sauvages de la Vallée de Strangleronce.",al={"qu'est-ce que la caisse de kravel","infos caisse de kravel","objet caisse de kravel"}},["6061fde3"]={q="Pourquoi la Caisse de Kravel est-elle recherchée ?",a="La caisse contient des munitions de calibre spécial commandées spécifiquement pour la chasse au gros gibier. L'expédition de chasse Nesingwary dans la Vallée de Strangleronce compte sur des munitions lourdes et fiables pour abattre les bêtes les plus féroces de la jungle, faisant de cette cargaison retardée un réapprovisionnement essentiel pour leur campement.",al={"pourquoi nesingwary veut la caisse","pourquoi la caisse de kravel est importante","but de la caisse de kravel"}}},fp="14,186,24.367.0,24.340.0,30.134.0,24.154.0,33.152.0,29.147.0"}
P.entries["item:kreenig-snarlsnout-s-tusk"] = {n="Défense de Kreenig Grondegroin",s="À La Croisée, Thork attend la preuve de la mort de Kreenig Grondegroin. Sa défense marque la fin des attaques du chef Razormane contre les caravanes de la Horde dans le nord des Tarides.",h="À La Croisée, Thork attend la preuve de la mort de Kreenig Grondegroin.",kw={"les tarides","la croisée","kreenig grondegroin","huran","razormane","grondegroin","thork","défense"},ang={["faction:Horde"]="Les caravanes transportent des armes, des provisions et des colons depuis Durotar, soutenant l’expansion de la Horde dans les Tarides. Apporter cette défense à Thork aide à protéger ces voies vitales.",["race:Orc"]="En tant qu’orc de La Croisée, prendre un trophée à un commandant vaincu relève d’une stratégie de guerre pragmatique. Cela montre votre force et sème la panique chez l’ennemi."},sec={{t="Un trophée aux ambitions tranchées",b="Les caravanes de la Horde qui partent vers l’ouest depuis Durotar sont constamment attaquées dans les Tarides. Sous les ordres de Kreenig Grondegroin, un féroce chef Razormane, les raids sont devenus plus audacieux. Thork, commandant de la garde de La Croisée, a donc ordonné de tuer Kreenig pour désorganiser les hurans.\n\nLa défense de Kreenig prouve sa mort et constitue une insulte aux Razormane. Leur détermination faiblit et leurs combattants se retrouvent sans commandement central."}},faq={{q="Qui était Kreenig Grondegroin ?",a="Kreenig Grondegroin dirigeait les hurans Razormane établis au nord-est de La Croisée. Il organisait des attaques contre les caravanes de la Horde qui empruntaient la route principale depuis Durotar, rendant cette voie de ravitaillement dangereuse jusqu’à sa mort.",al={"kreenig grondegroin","qui est kreenig grondegroin","histoire de grondegroin"}},{q="Pourquoi Thork veut-il précisément la défense ?",a="Thork veut la défense comme preuve de la mort de Kreenig et pour insulter les Razormane. Prendre la défense d’un chef tombé blesse leur orgueil et démoralise les pillards survivants.",al={"pourquoi la défense","pourquoi apporter la défense à thork","défense de thork"}},{q="Où cette défense a-t-elle été prise ?",a="La défense provient du camp de Kreenig Grondegroin, au nord-est de La Croisée. Le camp se trouve près des contreforts montagneux, juste au sud du passage de la route principale entre Durotar et les Tarides.",al={"où se trouve kreenig grondegroin","où trouver la défense","emplacement de grondegroin"}},{q="Quel effet la mort de Kreenig a-t-elle sur les Tarides ?",a="Thork pense que les pillards Razormane faibliront sans Kreenig pour les diriger. Sa mort sème le désordre dans leurs rangs et freine les attaques contre les convois de ravitaillement essentiels.",al={"les raids ont-ils cessé","conséquences de la mort de kreenig"}}},fx={["4371b9f1"]={q="Qu'est-ce que la Défense de Kreenig Grondegroin ?",a="Il s'agit d'une défense de marcassin tranchée, réclamée comme un sombre trophée sur Kreenig Grondegroin, le chef des pillards Tranchecrins au nord-est de La Croisée. Thork l'a exigée à la fois comme preuve irréfutable de la mort du chef et pour insulter amèrement les marcassins, démontrant à la tribu restante que leur chef de raid est tombé.",al={"qu'est-ce que la défense de kreenig","objet défense de kreenig grondegroin"}}},fp="25,173,28.413.0,27.207.0,42.176.0,26.185.0,57.174.0"}
P.entries["item:kron-s-amulet"] = {n="Amulette de Kron",s="Le long du Fleuve Furie-du-Sud, l'amulette de Kron évoque un jeune chasseur orc disparu.",h="Le long du Fleuve Furie-du-Sud, l'amulette de Kron évoque un jeune chasseur orc disparu.",kw={"amulette","crocolisque gueule-d'effroi","kron","misha tor'kren","tranchecolline","fleuve furie-du-sud"},ang={["class:Hunter"]="En tant que chasseur, le sort de Kron rappelle cruellement le danger qu'il y a à sous-estimer des bêtes féroces dans des eaux inconnues.",["race:Orc"]="En tant qu'orc, le sort de Kron montre que l'orgueil et la quête de gloire martiale peuvent pousser à ignorer la sagesse des anciens, avec des conséquences mortelles."},sec={{t="Tragédie sur le Fleuve Furie-du-Sud",b="Kron était un jeune orc impétueux qui vivait dans une ferme au nord-ouest de Tranchecolline. Il partit chasser les féroces crocolisques Gueule-d'effroi le long du Fleuve Furie-du-Sud, à la frontière des Tarides. Sa mère, Misha Tor'kren, le mit en garde contre le danger, mais son orgueil le poussa à continuer. Kron ne revint jamais. On retrouva son amulette dans le ventre d'un des prédateurs du fleuve, ce qui confirma qu'il avait été tué puis dévoré. Elle apporte à Misha la douloureuse confirmation du sort de son fils."}},faq={{q="Qui était Kron ?",a="Kron était un jeune chasseur orc impétueux qui vivait avec sa mère, Misha Tor'kren, dans une ferme au nord-ouest de Tranchecolline. Il partit seul pour mesurer sa force aux bêtes du fleuve, malgré les avertissements sur leur férocité.",al={"qui est kron","histoire de kron","lore de kron"}},{q="Où trouver l'Amulette de Kron ?",a="Les crocolisques Gueule-d'effroi et les crocolisques Gueule-d'effroi corrompus qui longent les rives du Fleuve Furie-du-Sud, à Durotar, portent l'Amulette de Kron dans leur ventre.",al={"où trouver l'amulette","emplacement de l'amulette de kron","qui donne l'amulette de kron"}},{q="Qui souhaite récupérer l'Amulette de Kron ?",a="Misha Tor'kren souhaite récupérer l'Amulette de Kron. Elle attend des nouvelles de son fils dans sa ferme au nord-ouest de Tranchecolline, et l'amulette lui apporte la douloureuse confirmation de son sort.",al={"qui a besoin de l'amulette","où rendre l'amulette de kron","misha tor'kren"}}},fx={["5d838632"]={q="Qu'est-ce que l'Amulette de Kron ?",a="Ce bibelot personnel appartenait à Kron, un jeune orc d'une ferme au nord-ouest de Tranchecolline. Poussé par la fierté et désireux de prouver sa force, il est parti seul vers le fleuve Furie-du-Sud pour chasser les féroces crocolis Gueule-d'effroi le long de la frontière des Tarides. Au lieu de revenir en triomphe, il est devenu la proie des bêtes qu'il cherchait à terrasser. Avalé avec ses restes, ce talisman est le seul élément survivant du jeune chasseur qui puisse prouver sa sombre fin.",al={"qu'est-ce que l'amulette","lore de l'amulette de kron","à qui appartient l'amulette"}}},fp="13,87,24.445.1,13.218.0,29.141.1,33.172.1"}
P.entries["item:kurzen-s-head"] = {n="Kurzen's Head",s="Kurzen’s Head est la preuve que cherchent les rebelles dans leur camp, dans la Vallée de Strangleronce. Le lieutenant Doren en a besoin pour savoir si le commandement du Colonel Kurzen a été brisé.",h="Kurzen’s Head est la preuve que cherchent les rebelles dans leur camp, dans la Vallée de Strangleronce.",kw={"colonel kurzen","kurzen","élite de kurzen","sous-chef de kurzen","kurzen’s head","lieutenant doren","camp rebelle","stockpile","vallée de strangleronce"},sec={{t="Une preuve pour Doren",b="Le lieutenant Doren attend au Camp rebelle des nouvelles du Stockpile, où le Colonel Kurzen commande ses hommes. Les rebelles affrontent les Élites et les sous-chefs de Kurzen, ainsi que le colonel lui-même. Doren demande Kurzen’s Head pour prouver que les chefs ennemis ont été vaincus. La sécurité de sa troupe dépend de la réponse."}},faq={{q="Qui veut Kurzen’s Head ?",a="Le lieutenant Doren, au Camp rebelle, demande Kurzen’s Head pour prouver que le Colonel Kurzen et ses chefs sont vaincus.",al={"qui veut la tête","tête de doren","où apporter kurzen’s head"}},{q="Où se trouve le Colonel Kurzen ?",a="Le Colonel Kurzen commande ses hommes depuis les profondeurs du Stockpile, dans la Vallée de Strangleronce.",al={"emplacement de kurzen","où est kurzen","type du stockpile"}},{q="Pourquoi les rebelles ont-ils besoin de Kurzen’s Head ?",a="Les rebelles ont besoin de Kurzen’s Head pour prouver que le Colonel Kurzen et ses chefs ont été vaincus.",al={"pourquoi la tête","utilité de kurzen’s head","preuve pour doren"}},{q="Quelle menace Kurzen représente-t-il ?",a="Le lieutenant Doren décrit Kurzen comme un commandant cruel et redoutable, dont les hommes menacent la troupe rebelle.",al={"menace de kurzen","pourquoi combattre kurzen","passé de kurzen"}},{q="Que se passe-t-il quand Kurzen est vaincu ?",a="Le lieutenant Doren affirme que la défaite de Kurzen sauve la troupe rebelle et lui permet de respirer plus librement.",al={"kurzen vaincu","qu’arrive-t-il aux rebelles","fin de kurzen"}}},fp="13,169,15.307.0,26.114.0,24.85.0,39.96.0,29.97.0,37.90.1"}
P.entries["item:kuz-s-skull"] = {n="Crâne de Kuz",s="Dans les Tarides du sud, le Crâne de Kuz marque la chute d’une pillarde Dos-bourru redoutée. Depuis le Kraal de Tranchebauge, Kuz a aidé à mener des attaques contre les avant-postes de la Horde, jusqu’à ce qu’un ancien congénère captif cherche vengeance.",h="Dans les Tarides du sud, le Crâne de Kuz marque la chute d’une pillarde Dos-bourru redoutée.",kw={"tarides","camp taurajo","kuz","crâne de kuz","lok orcbane","mutiledent","nak","dos-bourru"},ang={["faction:Horde"]="En tant que membre de la Horde, prendre la tête de Kuz aide à protéger des colonies comme La Croisée et le Camp Taurajo contre les attaques organisées des hurans."},sec={{t="Une vieille rivalité",b="Kuz, Nak et leur chef Lok Orcbane menaient les attaques des Dos-bourru dans les Tarides du sud. Envoyés depuis le Kraal de Tranchebauge, les trois pillards s’en prenaient aux voyageurs et aux colonies comme La Croisée. Ils ont trahi Mutiledent, un huran de leur tribu, et l’ont laissé pourrir dans une cage au Camp Taurajo. De là, Mutiledent a révélé l’emplacement de Kuz aux champions de la Horde prêts à tuer la pillarde et à prendre sa tête."},{t="Preuve de représailles",b="Le Crâne de Kuz prouve à Mutiledent que l’un des trois chefs du groupe de guerre du sud est mort. Cette tête satisfait sa vengeance contre la tribu qui l’a abandonné. La mort de Kuz brise le commandement à l’origine des attaques des Dos-bourru et offre un bref répit aux routes de ravitaillement qui traversent les plaines."}},faq={{q="Qui était Kuz ?",a="Kuz était l’une des trois hurans Dos-bourru envoyés depuis le Kraal de Tranchebauge dans les Tarides du sud. Avec Nak et Lok Orcbane, elle dirigeait des embuscades et des raids contre les campements et les lignes de ravitaillement de la Horde.",al={"qui est kuz","histoire de kuz","kuz dos-bourru"}},{q="Pourquoi Mutiledent veut-il le crâne de Kuz ?",a="Mutiledent veut le crâne de Kuz, car Kuz et les autres Dos-bourru l’ont laissé mourir dans une cage au Camp Taurajo. En quête de vengeance avant sa propre mort, il indique aux champions de la Horde où trouver ses rivaux et leur demande leurs crânes en guise de preuve.",al={"pourquoi mutiledent veut la mort de kuz","vengeance de mutiledent"}},{q="Où trouver Kuz dans les Tarides ?",a="Kuz se trouve dans les Tarides du sud, parmi les hurans Dos-bourru, au sud du Camp Taurajo, près des régions frontalières épineuses.",al={"emplacement de kuz","où trouver kuz"}},{q="Que se passe-t-il après la mort de Kuz ?",a="Lorsque le Crâne de Kuz et ceux de Nak et de Lok Orcbane parviennent à Mutiledent, ils brisent le commandement à l’origine des attaques des Dos-bourru et contribuent à sécuriser les routes commerciales du sud.",al={"récompense de la quête de kuz","issue de betrayal from within"}}},fx={["9baef7d0"]={q="D'où provient le Crâne de Kuz ?",a="Le crâne est prélevé directement sur les restes de Kuz, une éminente marcassinne Tranchecrin opérant dans le sud des Tarides. Sortant du Kraal de Tranchebauge aux côtés de ses compagnons pillards, Kuz a aidé à orchestrer des attaques violentes contre la Horde avant d'être traquée.",al={"d'où vient le crâne de kuz","qui a fait le crâne de kuz","origine du crâne de kuz"}}},fp="11,189,13.399.0,20.287.1,12.193.0,38.228.0,34.120.0,32.167.0"}
P.entries["item:laced-pumpkin"] = {n="Potiron arrosé",s="Entre les mains de l’Apothicaire Johaan, le Potiron arrosé met à l’épreuve la portée de l’alchimie des Réprouvés. À Brill, la Société royale des apothicaires cherche des armes contre le Fléau et les forces humaines vivantes.",h="Entre les mains de l’Apothicaire Johaan, le Potiron arrosé met à l’épreuve la portée de l’alchimie des...",kw={"apothicaire johaan","brill","zélote écarlate capturé","taverne des pendus","potiron arrosé","société royale des apothicaires","clairières de tirisfal"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous savez qu’un zélote capturé connaîtra un sort grotesque en territoire réprouvé. Sa fin rappelle cruellement ce qui peut attendre les humains vivants capturés.",["race:Undead"]="En tant que Réprouvé, vous savez que la Société royale des apothicaires emploiera tous les moyens pour protéger les Clairières de Tirisfal contre les croisés fanatiques encore en vie. Transformer de la nourriture ordinaire en arme témoigne de leur pragmatisme."},sec={{t="Une récolte amère",b="Dans les Clairières de Tirisfal, les potirons semblent être de simples légumes sauvés d’un sol flétri. À Brill, l’Apothicaire Johaan en traite un avec des toxines expérimentales pour tester tout le potentiel de la non-mort. La Société royale des apothicaires cherche des armes contre le Fléau au nord et les forces humaines vivantes qui avancent depuis le sud. Même une simple récolte peut véhiculer infection et mort chimique."},{t="L’expérience de la cave",b="Dans la cave de la Taverne des Pendus, des geôliers réprouvés retiennent un Zélote écarlate capturé, affamé. Désespéré de trouver de quoi se nourrir, le prisonnier accepte une offrande contaminée. Le potiron arrosé contient la concoction de l’Apothicaire Johaan. En le mangeant, le prisonnier subit une violente transformation : le zélote humain devient une goule décérébrée, titube brièvement dans l’agonie, puis s’effondre, mort, sur le sol de pierre froide."}},faq={{q="Qu’est-ce que le Potiron arrosé ?",a="À Brill, l’Apothicaire Johaan traite une courge ordinaire des champs avec une formule expérimentale. La concoction sert à tester les effets de l’alchimie des Réprouvés sur des sujets vivants.",al={"potiron arrosé","potiron empoisonné","potiron johaan"}},{q="Qui mange le Potiron arrosé ?",a="Des geôliers réprouvés emprisonnent un Zélote écarlate capturé dans la cave sous la Taverne des Pendus, à Brill. Après avoir été affamé, le prisonnier mange l’offrande contaminée.",al={"qui le mange","cible du potiron","nourrir avec le potiron"}},{q="Que se passe-t-il quand on mange le potiron ?",a="La concoction du potiron déclenche une violente transformation. Le prisonnier devient une goule décérébrée, titube brièvement dans l’agonie, puis s’effondre, mort, sur le sol de pierre froide.",al={"effet du potiron","sort du zélote","zélote goule"}},{q="Pourquoi les Réprouvés ont-ils fabriqué cela ?",a="L’Apothicaire Johaan et la Société royale des apothicaires fabriquent des concoctions biologiques pour combattre le Fléau au nord et les humains vivants qui avancent depuis le sud. Ils utilisent des ennemis capturés comme sujets d’expérience.",al={"pourquoi fabriquer un potiron empoisonné","essais de peste des réprouvés"}}},fx={["242570cd"]={q="D'où provient le Potiron arrosé et qui l'a fabriqué ?",a="L'apothicaire Johaan a préparé ce potiron à Brill. Cherchant des armes pour défendre les Réprouvés contre le Fléau au nord et les humains vivants au sud, il a récolté des produits ordinaires à la Ferme des Solliden et les a traités avec sa concoction de peste expérimentale.",al={"qui a fabriqué le potiron arrosé","d'où vient le potiron arrosé","créateur du potiron arrosé"}},["071bacef"]={q="Pourquoi quelqu'un veut-il le Potiron arrosé ?",a="L'apothicaire Johaan doit faire manger le potiron à un sujet vivant pour évaluer sa dernière formule chimique. Il est offert à un prisonnier de la Croisade écarlate affamé, enfermé dans la cave sous la Taverne des Pendus à Brill, servant de test mortel pour les recherches de la Société royale des apothicaires.",al={"pourquoi vouloir le potiron arrosé","pourquoi utiliser le potiron arrosé","à quoi sert le potiron arrosé"}}},fp="13,177,16.375.0,21.383.1,26.160.0,27.168.0,43.170.1,31.201.0"}
P.entries["item:laden-dew-gland"] = {n="Laden Dew Gland",s="Une Laden Dew Gland contient l’eau recueillie par un collecteur de rosée à Tanaris. Marin Noggenfogger, à Gadgetzan, en veut une pour étancher sa soif.",h="Une Laden Dew Gland contient l’eau recueillie par un collecteur de rosée à Tanaris.",kw={"collecteur de rosée","glande de rosée","laden dew gland","marin noggenfogger","tanaris","vallée des chardonniers"},sec={{t="De l’eau pour Marin",b="Au sud-ouest de Gadgetzan, la Vallée des Chardonniers abrite des collecteurs de rosée qui stockent l’eau dans des glandes spéciales. Marin Noggenfogger vous demande de lui apporter une Laden Dew Gland, dans l’espoir d’étancher sa terrible soif."}},faq={{q="Qu’est-ce qu’une Laden Dew Gland ?",a="Une Laden Dew Gland est un organe rempli d’eau porté par les collecteurs de rosée de la Vallée des Chardonniers.",al={"glande de rosée","glande pleine"}},{q="Qui veut cette glande ?",a="Marin Noggenfogger, à Gadgetzan, veut une Laden Dew Gland pour tenter d’étancher sa soif.",al={"qui a besoin d’une glande de rosée","glande de marin"}},{q="Où trouver une Laden Dew Gland ?",a="Les Rosée des chardonniers Collectors de la Vallée des Chardonniers, au sud-ouest de Gadgetzan, portent des Laden Dew Glands.",al={"emplacement de la glande de rosée","où trouver une glande à tanaris"}},{q="Pourquoi Marin la veut-il ?",a="Marin espère que l’eau stockée dans la glande lui permettra de préparer une boisson qui étanchera sa terrible soif.",al={"marin a soif","pourquoi une glande de rosée"}}},fp="15,131,15.208.0,26.91.0,20.84.0,34.99.0,23.94.0"}
P.entries["item:laird-s-response"] = {n="Réponse de Laird",s="Sur les côtes de Teldrassil, Laird envoie un rapport curieux à Nessa Shadowsong. Les poissons y sont plus gros et plus nombreux que sur le continent de Sombrivage.",h="Sur les côtes de Teldrassil, Laird envoie un rapport curieux à Nessa Shadowsong.",kw={"auberdine","sombrivage","pêche","laird","réponse de laird","nessa shadowsong","rut'theran","teldrassil"},ang={["race:NightElf"]="En tant qu’Elfe de la nuit qui veille sur les côtes de Teldrassil, les notes de Laird pourraient vous intriguer et vous troubler. Le jeune Arbre-monde pourrait déjà influencer la nature qui l’entoure."},sec={{t="Une histoire d’écailles et de racines",b="Laird compare les prises des deux côtés de la Mer voilée. Les poissons des côtes de Teldrassil sont plus gros et plus nombreux que ceux des plages continentales de Sombrivage.\n\nDans sa réponse à Nessa Shadowsong, Laird d’Auberdine se demande si la présence et la vitalité inhabituelles du nouvel Arbre-monde planté ne changent pas la vie marine des environs. Des voyageurs transportent sa lettre par-delà les eaux jusqu’à Rut'theran, où les pêcheurs accueillent la nouvelle avec émerveillement et une discrète curiosité."}},faq={{q="Qu’est-ce que la Réponse de Laird ?",a="La Réponse de Laird est la réponse de Laird à la demande de renseignements de Nessa Shadowsong sur Teldrassil. Laird est un marchand et saleur de poisson à Auberdine.",al={"de quel objet s’agit-il","lettre de réponse de laird","qu’est-ce que la réponse de laird"}},{q="À qui Laird écrit-il ?",a="Laird écrit à Nessa Shadowsong, une Elfe de la nuit qui vit à Rut'theran, au pied sud de Teldrassil.",al={"qui reçoit la réponse de laird","qui reçoit cette lettre","lettre de nessa à laird"}},{q="Que dit la lettre au sujet des poissons ?",a="Laird rapporte que les poissons des côtes de Teldrassil sont plus gros et plus nombreux que ceux du continent de Sombrivage. Il soupçonne que l’Arbre-monde pourrait influencer la vie marine des environs.",al={"pourquoi les poissons sont-ils gros","différence entre les poissons de sombrivage et de teldrassil","qu’a découvert laird"}},{q="Comment le message retourne-t-il à Rut'theran ?",a="Un messager peut prendre le ferry régulier aux quais d’Auberdine ou organiser un vol en hippogriffe avec Caylais Moonfeather, le maître de vol.",al={"comment retourner auprès de nessa","bateau de rut'theran à sombrivage","ferry d’auberdine pour rejoindre nessa"}}},fx={aee914ad={q="D'où provient la Réponse de Laird et qui l'a écrite ?",a="Cette réponse écrite est rédigée par Laird, un résident d'Auberdine sur les côtes de Sombrivage. Il l'écrit pour répondre aux questions envoyées à travers la mer depuis Rut'theran concernant la vie marine locale.",al={"qui a écrit la réponse de laird","d'où provient la réponse de laird","origine de la réponse de laird"}},fb1c817f={q="Pourquoi Nessa veut-elle la Réponse de Laird ?",a="Nessa Shadowsong, à Rut'theran, attend avec impatience les observations de Laird sur la comparaison entre les prises du continent et les eaux de Teldrassil. Les poissons étranges et surdimensionnés autour des grandes branches de l'Arbre-Monde ont intrigué les pêcheurs, et les notes de Laird confirment que le Sombrivage continental ne voit rien de tel, suggérant que Teldrassil lui-même transforme la faune locale.",al={"pourquoi nessa veut la réponse de laird","pourquoi la réponse de laird est recherchée","qui veut la réponse de laird"}}},fp="16,154,28.461.0,25.127.0,24.108.0,40.176.0,55.135.0"}
P.entries["item:lake-creeper-moss"] = {n="Mousse de Rampant lacustre",s="Autour du sud des îles de l'aube, la Mousse de Rampant lacustre pousse sur des créatures aquatiques. La Société royale des apothicaires recherche ce composé organique, réactif essentiel à la création d'une nouvelle peste mortelle.",h="Autour du sud des îles de l'aube, la Mousse de Rampant lacustre pousse sur des créatures aquatiques.",kw={"berard","les îles de l'aube","elder lake creeper","faranell","rampant lacustre","mousse de rampant lacustre","lac lordamere","the new plague","société royale des apothicaires"},ang={["profession:Herbalism"]="Bien qu'elle pousse sur des créatures aquatiques plutôt que dans la terre, cette mousse fait partie de la flore expérimentale et plus sombre de Lordaeron. Elle est récoltée pour les recherches des apothicaires.",["race:Undead"]="Chaque échantillon apporté à l'Apothicarium rapproche les Réprouvés de la mise au point de The New Plague et leur permet d'assurer leur vengeance contre le Fléau et les vivants."},sec={{t="Récolte alchimique",b="La Mousse de Rampant lacustre pousse sur la peau des créatures d'eau douce qui vivent dans les eaux près du sud des îles de l'aube. Les eaux corrompues de Lordaeron lui confèrent des propriétés inhabituelles. Avant que la malédiction d'Arugal ne lui fasse perdre la raison, l'Apothicaire Berard a consigné l'existence de cette mousse dans son journal.\n\nIl a découvert qu'elle ressemblait aux traces relevées sur les fossiles de créatures tuées par une ancienne peste dans le lac. Les agents réprouvés envoient les échantillons récupérés à l'Apothicarium, à Fossoyeuse, où le Maître apothicaire Faranell les utilise dans ses recherches."},{t="À l'origine de The New Plague",b="La Mousse de Rampant lacustre constitue une étape essentielle dans la création de l'arme emblématique des Réprouvés. Associée à la mousse des Furtifs du lac et aux tumeurs malades prélevées sur les murlocs ailerons-viles locaux, elle forme la base organique nécessaire pour raffiner une souche destinée à exterminer les tissus vivants comme le Fléau. Bien que l'apothicaire qui a découvert son utilité ait disparu, la Société royale des apothicaires continue de préparer sa recette au service de la Dame noire."}},faq={{q="À quoi sert la Mousse de Rampant lacustre ?",a="Le Maître apothicaire Faranell et la Société royale des apothicaires utilisent la Mousse de Rampant lacustre comme réactif alchimique pour préparer et raffiner The New Plague à Fossoyeuse.",al={"utilité de la mousse de rampant","pourquoi récolter la mousse de rampant lacustre","usage de la mousse de rampant lacustre"}},{q="D'où vient cette mousse ?",a="La Mousse de Rampant lacustre pousse sur les rampants aquatiques et les Elder Lake Creepers dans les eaux autour du sud des îles de l'aube, à l'est du lac Lordamere.",al={"où trouver la mousse de rampant","emplacement de la mousse de rampant","emplacement des rampants lacustres"}},{q="Qui a découvert la valeur alchimique de cette mousse ?",a="Avant que la malédiction d'Arugal ne fasse de l'Apothicaire Berard un serviteur privé de raison à Bois-du-Bûcher, Berard a consigné les propriétés alchimiques de la mousse dans son journal de terrain. L'Apothicaire Renferrel a ensuite retrouvé ses notes.",al={"qui a découvert la mousse","mousse de berard","qui a écrit sur la mousse de rampant"}},{q="À qui la mousse récoltée est-elle remise ?",a="Le Maître apothicaire Faranell reçoit la mousse à l'Apothicarium, à Fossoyeuse. Dans ses recherches, il la mélange à de la Mousse de Furtif lacustre et à une Tumeur durcie.",al={"qui veut la mousse de rampant","remettre la mousse de rampant","mousse de faranell"}}},fx={["70aadfdf"]={q="Qu'est-ce que la Mousse de Rampant lacustre ?",a="La Mousse de Rampant lacustre est une croissance organique récoltée directement sur les corps des rampants aquatiques habitant le lac Lordamere. Bien qu'il s'agisse extérieurement d'une flore de marais ordinaire, la Société royale des apothicaires la considère comme un réactif vital dans leurs sombres expériences.",al={"qu'est-ce que la mousse de rampant","lore de la mousse de rampant lacustre","explication mousse de rampant"}}},fp="17,190,18.486.0,22.414.1,35.160.0,31.139.0,43.207.0,32.158.0"}
P.entries["item:lake-skulker-moss"] = {n="Mousse de Furtif lacustre",s="Dans le nord du lac Lordamere, la Mousse de Furtif lacustre attire l’attention de la Société royale des apothicaires. L’Apothicaire Berard a découvert comment l’utiliser pour préparer A New Plague, avant que la malédiction d’Arugal ne s’empare de son esprit.",h="Dans le nord du lac Lordamere, la Mousse de Furtif lacustre attire l’attention de la Société royale des...",kw={"berard","les îles de l'aube","faranell","lac lordamere","lake skulker","mousse de furtif lacustre","new plague","renferrel"},ang={["race:Undead"]="En tant que mort-vivant, vous rapprochez la Société royale des apothicaires de la mise au point de la New Plague. Les Réprouvés comptent l’utiliser contre le Fléau et les vivants."},sec={{t="Un réactif contre la peste",b="La Mousse de Furtif lacustre provient des Lake Skulkers et des Elder Lake Skulkers des îles de l’aube. Avant que la malédiction d’Arugal ne s’empare de son esprit, l’Apothicaire Berard a répertorié les plantes et les créatures de l’est de la Forêt des Pins-Argentés. Son journal indique que les mousses de Lake Skulker et de Lake Creeper pouvaient stabiliser d’autres ingrédients ou réagir avec eux.\n\nAprès que la malédiction l’eut changé en serviteur écervelé d’Arugal, son journal fut récupéré à Bois-du-Bûcher pour l’Apothicaire Renferrel. Renferrel envoya des champions réprouvés récolter de la mousse et une tumeur rare sur les murlocs Vile Fin des environs. Ils devaient livrer ces deux ingrédients au Maître apothicaire Faranell, à Fossoyeuse."}},faq={{q="À quoi sert la Mousse de Furtif lacustre ?",a="La Société royale des apothicaires, à Fossoyeuse, utilise la Mousse de Furtif lacustre comme base organique pour préparer la New Plague. Cela sert les desseins de Dame Sylvanas Coursevent pour les Réprouvés.",al={"utilisation de la mousse","pourquoi récolter la mousse de furtif","à quoi sert la mousse de furtif"}},{q="D’où vient cette mousse ?",a="La Mousse de Furtif lacustre est raclée sur les Lake Skulkers et les Elder Lake Skulkers qui vivent dans les eaux autour des îles de l’aube. Ces îles se trouvent au nord-est du lac Lordamere, au large de la Forêt des Pins-Argentés.",al={"où trouver la mousse de furtif","emplacement de la mousse de furtif","qui donne la mousse de furtif lacustre"}},{q="Qui a découvert l’utilité de cette mousse ?",a="L’Apothicaire Berard a découvert le potentiel de cette mousse en étudiant la Forêt des Pins-Argentés. Après que la malédiction d’Arugal l’eut changé en serviteur écervelé, son journal a aidé l’Apothicaire Renferrel et le Maître apothicaire Faranell à poursuivre leurs expériences.",al={"qui a découvert la mousse","mousse de berard","recherches de l’apothicaire berard"}},{q="Qui a besoin de ce réactif ?",a="Le Maître apothicaire Faranell dirige la Société royale des apothicaires dans l’Apothicarium de Fossoyeuse. Il a besoin de cette mousse pour ses projets de guerre biologique.",al={"qui veut la mousse de furtif","faranell et la mousse de furtif"}}},fx={["18c0a856"]={q="Qu'est-ce que la Mousse de Furtif lacustre ?",a="La Mousse de Furtif lacustre est une croissance naturelle récoltée sur le dos des furtifs lacustres, des bêtes amphibies rôdant autour des îles de l'aube du lac Lordamere. Bien que sans importance pour les pêcheurs et les voyageurs, cette matière organique possède des propriétés spécifiques qui ont attiré l'attention des alchimistes Réprouvés étudiant la flore et la faune locales.",al={"qu'est-ce que la mousse de furtif lacustre","infos mousse de furtif lacustre","explication mousse de furtif"}}},fp="17,194,16.613.0,35.178.0,31.179.0,37.225.0,26.149.0"}
P.entries["item:large-candle"] = {n="Grande bougie",s="Dans les mines de la Forêt d’Elwynn, les kobolds portent des Grandes bougies pour s’éclairer et récupérer la cire. Les apothicaires prisent cette cire pour leurs préparations.",h="Dans les mines de la Forêt d’Elwynn, les kobolds portent des Grandes bougies pour s’éclairer et récupérer la...",kw={"fargodeep mine","comté-de-l’or","goldtooth","mine veine-de-jaspe","kobold candles","grande bougie","cire","william pilon"},ang={["faction:Alliance"]="En prenant des bougies aux kobolds de la Forêt d’Elwynn, les aventuriers de l’Alliance affaiblissent la vermine des mines et fournissent des matériaux essentiels au commerce apothicaire de Hurlevent.",["profession:Mining"]="Les mineurs qui exploitent les filons de Fargodeep Mine et de la Mine Veine-de-jaspe se heurtent souvent aux kobolds qui infestent les lieux. Ceux-ci convoitent l’or autant que la lumière des Grandes bougies."},sec={{t="Lumière et cire souterraines",b="Les kobolds suivent la lumière des bougies dans les galeries obscures sous la Forêt d’Elwynn. Ils fixent les cierges sur leur tête, et les Kobold Miners, Tunnelers et Geomancers les défendent farouchement contre les intrus. Les Grandes bougies de Fargodeep Mine et de la Mine Veine-de-jaspe contiennent une cire précieuse, bien qu’elles soient fabriquées grossièrement. Les marchands de la surface ne peuvent pas produire beaucoup de cire à la fois. Ces bougies servent donc à la fois d’outils aux kobolds et de marchandise pour les alchimistes."},{t="Commerce et apothicairerie",b="William Pilon, un agent apothicaire de Hurlevent, rassemble des Grandes bougies à l’Auberge de la Fierté du Lion, à Comté-de-l’Or. Sa famille tient une apothicairerie, et il a besoin de cire fondue pour ses concoctions, baumes et onguents. Pilon engage des aventuriers de passage pour débarrasser les mines infestées et prendre les bougies aux kobolds."}},faq={{q="À quoi servent les Grandes bougies ?",a="William Pilon rassemble des Grandes bougies à Comté-de-l’Or pour l’apothicairerie qu’il tient avec son frère à Hurlevent. Ils font fondre les bougies pour obtenir la cire utilisée dans les onguents, les baumes et les recettes alchimiques.",al={"utilisation de la grande bougie","pourquoi récupérer des grandes bougies","qui veut des grandes bougies"}},{q="Où trouver des Grandes bougies ?",a="Les kobolds portent des Grandes bougies dans les mines de la Forêt d’Elwynn, notamment dans Fargodeep Mine, au sud de Comté-de-l’Or, et dans la Mine Veine-de-jaspe, à l’est. Les Tunnelers, Miners et Geomancers en portent.",al={"emplacement des grandes bougies","où trouver des grandes bougies","butin des kobolds : bougies"}},{q="Pourquoi les kobolds portent-ils des bougies sur la tête ?",a="Les kobolds s’éclairent à la bougie pour creuser et se repérer dans les tunnels souterrains obscurs. Ils fixent les bougies sur leur tête afin de garder les mains libres pour manier leurs pioches, lancer des sorts géomantiques et utiliser leurs armes.",al={"pourquoi les kobolds ont des bougies","légende des bougies sur la tête des kobolds"}},{q="Qui est William Pilon ?",a="William Pilon est un agent apothicaire de Hurlevent qui fait affaire à l’Auberge de la Fierté du Lion, à Comté-de-l’Or. Il rassemble des ingrédients bruts dans la nature et les mines pour approvisionner l’apothicairerie qu’il tient avec son frère.",al={"histoire de william pilon","qui est l’apothicaire de comté-de-l’or"}}},fx={["05873d56"]={q="Qu'est-ce qu'une Grande bougie ?",a="Une Grande bougie est un cierge de cire brut et substantiel transporté par les kobolds habitant les mines de la Forêt d’Elwynn. Les kobolds sont notoirement protecteurs de leurs sources de lumière, utilisant ces bougies imposantes pour percer l'obscurité des tunnels souterrains comme les mines de la Fargodeep et de Jasperlode pendant qu'ils creusent à la recherche d'or et de minéraux.",al={"qu'est-ce qu'une grande bougie","grande bougie elwynn","lore de la grande bougie"}}},fp="12,108,26.430.0,24.316.0,32.199.0,33.177.0,44.194.0,22.229.0"}
P.entries["item:large-soran-ruk-fragment"] = {n="Grand fragment de Soran'ruk",s="Dans le Donjon d’Ombrecroc, le Grand fragment de Soran'ruk se trouve loin des autres éclats. Son orbe brisé abritait autrefois un démon disgracié de la Légion ardente.",h="Dans le Donjon d’Ombrecroc, le Grand fragment de Soran'ruk se trouve loin des autres éclats.",kw={"légion ardente","doan karhan","grand fragment de soran'ruk","orbe de soran'ruk","donjon d'ombrecroc","soran'ruk"},ang={["class:Warlock"]="En tant que démoniste, récupérer le Grand fragment de Soran'ruk vous permet de maîtriser l’esprit démoniaque qui y est piégé. Vous pouvez aider Doan Karhan à reconstituer une arme puissante des arts démoniaques."},sec={{t="L’héritage de Soran'ruk",b="Les démons disgraciés de la Légion ardente peuvent être emprisonnés dans des orbes enchantés. Les mages et les démonistes alliés à la Légion reçoivent ces réceptacles et puisent dans les forces gangrenées qu’ils renferment. Même brisé, le démon lié à un orbe laisse une essence qui rayonne encore de puissance. Les fragments attirent donc ceux qui cherchent à maîtriser la Shadow Magic."},{t="L’éclat d’Ombrecroc",b="L’Orbe de Soran'ruk a été fendu en deux moitiés il y a bien longtemps. Des sectateurs ailleurs ont dispersé l’une d’elles en morceaux plus petits, tandis qu’un sorcier du maudit Donjon d’Ombrecroc s’est emparé de la plus grande moitié. Les Âmes noires d’Ombrecroc portent le Grand fragment de Soran'ruk. Son esprit lié demeure à l’intérieur, jusqu’à ce que quelqu’un cherche à reforger l’ancien réceptacle."}},faq={{q="Qu’est-ce que le Grand fragment de Soran'ruk ?",a="Le Grand fragment de Soran'ruk est la plus grande moitié de l’Orbe de Soran'ruk, qui renferme l’esprit lié d’un démon disgracié de la Légion ardente.",al={"grand fragment de soran'ruk","grand éclat de soran'ruk","qu’est-ce que ce fragment"}},{q="Où trouve-t-on le fragment ?",a="Les Âmes noires d’Ombrecroc détiennent le fragment dans le Donjon d’Ombrecroc, une forteresse hantée de la Forêt des Pins-Argentés.",al={"où trouver le grand fragment","emplacement du grand fragment","qui laisse tomber le grand fragment de soran'ruk"}},{q="Pourquoi l’orbe a-t-il été brisé ?",a="L’orbe d’origine a été divisé en deux morceaux principaux. La plus petite moitié a été brisée en éclats et transportée dans les cavernes côtières des Profondeurs de Brassenoire. Des sorciers maléfiques ont conservé la plus grande moitié dans le Donjon d’Ombrecroc.",al={"comment l’orbe s’est-il brisé","pourquoi l’orbe est-il fragmenté","histoire de l’orbe de soran'ruk"}},{q="Qui veut le reconstituer ?",a="Doan Karhan, un ermite reclus des Tarides du sud, a consacré sa vie à étudier et à reconstituer les orbes perdus de la Légion ardente.",al={"qui a besoin du grand fragment","qui reconstitue l’orbe"}}},fx={["0cdd1dfd"]={q="D'où provient le Grand fragment de Soran'ruk et qui l'a fabriqué ?",a="Le fragment faisait autrefois partie de The Orb of Soran'ruk, un artefact créé par la Légion ardente. Lorsque les démons de la Légion tombent en disgrâce, leurs esprits sont liés à l'intérieur d'orbes et confiés à des mages et des démonistes mortels. Soran'ruk était l'un de ces démons, son essence emprisonnée pour alimenter la magie démoniaque. L'orbe a ensuite été divisé en deux morceaux, ce plus gros éclat tombant entre les mains d'un lanceur de sorts noir au sein du Donjon d'Ombrecroc.",al={"origine du fragment de soran'ruk","qui a fabriqué l'orbe de soran'ruk","d'où vient soran'ruk"}}},fp="24,146,23.317.0,23.330.0,37.138.0,28.99.0,23.199.0,27.145.0"}
P.entries["item:large-stone-slab"] = {n="Large Stone Slab",s="Les Large Stone Slabs sont des morceaux de roche que l’on trouve sur les Terres Ingrates. Lotwil Veriatus en a besoin pour tester ses sorts.",h="Les Large Stone Slabs sont des morceaux de roche que l’on trouve sur les Terres Ingrates.",kw={"terres ingrates","élémentaire","large stone slab","lotwil veriatus","élémentaire de roche","pierre","dalle de pierre"},ang={["race:Tauren"]="Lotwil s’émerveille qu’un seul tauren lui ait apporté les dalles. Il dit qu’il pensait qu’il en faudrait une demi-douzaine."},sec={{t="Pierre d’étude",b="À l’ouest de Lotwil Veriatus, sur les Terres Ingrates, des élémentaires de roche transportent les dalles qu’il recherche. Leurs corps plus grands et plus puissants fournissent des morceaux adaptés à ses tests. Lotwil pense que ses sorts peuvent l’aider à contrôler les élémentaires, et ces pierres font partie de ses recherches."}},faq={{q="D’où viennent les Large Stone Slabs ?",a="Les élémentaires de roche des Terres Ingrates transportent des Large Stone Slabs. Lotwil Veriatus indique les collines à l’ouest de sa position ainsi que les abords des montagnes voisines.",al={"origine des dalles","source des dalles de pierre"}},{q="Qui veut les dalles ?",a="Lotwil Veriatus a besoin de Large Stone Slabs pour tester des sorts destinés à contrôler les élémentaires.",al={"qui a besoin des dalles","pierre de lotwil"}},{q="Pourquoi Lotwil les veut-il ?",a="Lotwil teste ses sorts sur les dalles, espérant les utiliser dans ses expériences pour contrôler les élémentaires.",al={"pourquoi les dalles","à quoi servent les pierres"}},{q="Quels élémentaires les transportent ?",a="Les élémentaires de roche transportent les dalles que Lotwil recherche. D’après ses indications, ils se trouvent à l’ouest de sa position et le long des abords des montagnes.",al={"élémentaire de roche","quelles pierres"}}},fp="16,122,15.246.0,37.141.0,20.92.0,26.94.0,28.113.0"}
P.entries["item:laughing-sister-s-hair"] = {n="Cheveu de soeur rieuse",s="À Orneval, les tisserands recherchent la magie naturelle des cheveux des Laughing Sisters. À La Croisée, Kil'hala s'en sert pour confectionner des robes enchantées.",h="À Orneval, les tisserands recherchent la magie naturelle des cheveux des Laughing Sisters.",kw={"orneval","tissu","la croisée","deino","dryade","cheveux","kil'hala","laughing sister","retraite de raynebois"},ang={["faction:Horde"]="En tant que membre de la Horde, vous devez pénétrer sur le territoire des Elfes de la nuit, à Orneval, et tuer des esprits des bois pour récupérer leurs mèches. Vous vous emparez de leur magie locale par la force.",["profession:Tailoring"]="En tant que couturier, vous pouvez utiliser les mèches de dryade comme fil exotique pour tisser la magie de la nature dans le tissu."},sec={{t="Un composant de tissage rare",b="Près de la Retraite de Raynebois, les Laughing Sisters sont des dryades dont les cheveux recèlent une magie naturelle. Elles gardent les bois et sont liées à Cénarius et aux Elfes de la nuit. Les artisans de la Horde prisent leurs cheveux comme matériau puissant.\n\nKil'hala, une couturière troll à La Croisée, file ces mèches pour confectionner des robes enchantées destinées aux élèves prometteurs de Deino, qui étudient les arcanes."}},faq={{q="D'où vient le Cheveu de soeur rieuse ?",a="Les Laughing Sisters sont des dryades qui parcourent les bosquets enchantés près de la Retraite de Raynebois, au centre d'Orneval. Leurs cheveux recèlent une magie naturelle.",al={"où trouver les cheveux des laughing sisters","lieu où trouver les cheveux de laughing sister","origine des cheveux de dryade"}},{q="Pourquoi Kil'hala cherche-t-elle des cheveux de dryade ?",a="Kil'hala, une couturière à La Croisée, dans les Tarides, tisse les mèches magiques pour en faire des robes de tissu enchanté destinées aux élèves prometteurs de Deino.",al={"pourquoi kil'hala veut des cheveux","utilité du cheveu de soeur rieuse","tailleur troll cheveux de dryade"}},{q="Les Laughing Sisters céderont-elles leurs cheveux de leur plein gré ?",a="Non. Les Laughing Sisters gardent la nature et protègent Orneval. Comme le fait remarquer Kil'hala, les dryades ne céderaient jamais volontairement leurs cheveux aux agents de la Horde.",al={"peut-on demander leurs cheveux aux dryades","les dryades donnent-elles leurs cheveux"}}},fx={["3a458879"]={q="Qu'est-ce qu'un Cheveu de soeur rieuse ?",a="Un Cheveu de soeur rieuse consiste en des mèches coupées rassemblées sur des soeurs rieuses, les dryades des bois habitant près de la Retraite de Raynebois à Orneval. Imprégnées de la grâce naturelle et de la magie des filles de Cénarius, ces mèches sont prisées par les tisserands qualifiés comme matériau de tissage rare pour des vêtements de lancement de sorts puissants.",al={"qu'est-ce qu'un cheveu de soeur rieuse","infos cheveu de soeur rieuse","matériau cheveux de dryade"}}},fp="22,138,24.333.0,44.136.0,39.136.0,55.149.0"}
P.entries["item:leftwitch-s-package"] = {n="Leftwitch's Package",s="Le colis de Leftwitch rapporte à Forgefer la dernière affaire de Reclaimers Inc. en Désolace. Roetten Martel-de-pierre le reçoit et rémunère le travail.",h="Le colis de Leftwitch rapporte à Forgefer la dernière affaire de Reclaimers Inc.",kw={"désolace","forgefer","leftwitch","colis de leftwitch","reclaimers inc","roetten martel-de-pierre"},sec={{t="Retour à Forgefer",b="Roetten Martel-de-pierre attend à Forgefer le colis de Leftwitch, en provenance de Désolace. Rapportez-le-lui, et Reclaimers Inc. vous paiera pour cette dernière tâche. Roetten est heureux de vous compter parmi les siens, même pour une petite mission."}},faq={{q="À qui est destiné le colis de Leftwitch ?",a="Roetten Martel-de-pierre, à Forgefer, reçoit le colis de Leftwitch pour le compte de Leftwitch.",al={"qui veut le colis","colis de leftwitch pour qui"}},{q="Où faut-il apporter le colis ?",a="Apportez le colis de Leftwitch depuis la Désolace à Roetten Martel-de-pierre, à Forgefer.",al={"où l'apporter","destination du colis"}},{q="À quoi le colis est-il lié ?",a="Le colis de Leftwitch est la dernière livraison liée aux affaires de Reagents pour Reclaimers Inc. en Désolace.",al={"pourquoi le colis","colis de reclaimers"}},{q="Que fait Roetten quand il le reçoit ?",a="Roetten vous remercie d'avoir effectué le travail à temps et vous paie au nom de Reclaimers Inc.",al={"que se passe-t-il après la livraison","roetten paie"}}},fp="19,162,17.218.0,33.88.0,26.77.0,33.101.0,37.80.0"}
P.entries["item:legacy-of-the-aspects"] = {n="Héritage des Aspects",s="Lors de l'épreuve de la Horde, les aspirants doivent trouver l'Héritage des Aspects et retenir ses leçons. Ce tome ancien se trouve dans le Refuge des saisons de Dor'danil, au sud d'Orneval, et renferme des connaissances sur les Grands Aspects qui ont façonné l'antique Azeroth.",h="Lors de l'épreuve de la Horde, les aspirants doivent trouver l'Héritage des Aspects et retenir ses leçons.",kw={"orneval","tertre funéraire","braug dimspirit","dor'danil","héritage des aspects","la perce des serres","test of lore"},ang={["class:Druid"]="En tant que druide, vous trouvez le texte au plus profond du Refuge des saisons de Dor'danil, parmi les esprits tragiques et tourmentés des druides elfes de la nuit déchus.",["faction:Horde"]="En tant qu'aventurier de la Horde, vous vous soumettez à un rite de passage traditionnel. Il vérifie si votre sagesse et vos connaissances égalent votre puissance physique."},sec={{t="Une épreuve de l'esprit",b="Braug Dimspirit envoie les aspirants chercher l'Héritage des Aspects. Les épreuves précédentes imposées par les anciens taurens testent l'endurance et la détermination. Celle-ci met l'esprit à l'épreuve. Braug attend à l'entrée de la Perce des Serres, dans les Serres-Rocheuses, tandis que le tome se trouve dans les tertres funéraires hantés de Dor'danil.\n\nLes esprits agités des druides déchus et les créatures féroces qui les ont tués gardent le texte ancien. Il repose sur un piédestal de pierre. Trouver l'ouvrage n'est que le début. Avant de le rapporter, l'aspirant doit en mémoriser le contenu. Braug l'interroge ensuite sur les leçons d'histoire qu'il contient."}},faq={{q="Où se trouve le livre ?",a="L'Héritage des Aspects repose sur un piédestal de pierre, dans les salles inférieures du Refuge des saisons de Dor'danil, au sud d'Orneval et au sud du Poste de Bois-brisé.",al={"trouver l'héritage des aspects","emplacement du livre","où se trouve le livre"}},{q="Pourquoi Braug Dimspirit veut-il ce livre ?",a="Braug Dimspirit utilise le tome pour le Test de Lore. Cette épreuve vérifie si un aventurier peut étudier et retenir des connaissances historiques essentielles, ainsi que déployer sa force physique.",al={"pourquoi braug veut le livre","but du test de lore"}},{q="Que se passe-t-il si vous n'étudiez pas le texte avant de parler à Braug ?",a="Braug interroge les aspirants sur le contenu du livre dès qu'ils le récupèrent. Une mauvaise réponse entraîne un bannissement magique immédiat, qui envoie le postulant mal préparé au loin, jusqu'au Camp Taurajo, dans les Tarides.",al={"conséquence d'une mauvaise réponse","échec à l'épreuve"}}},fx={["32a02485"]={q="Qu'est-ce que l'Héritage des Aspects ?",a="L'Héritage des Aspects est un tome ancien et précieux reposant au plus profond du Refuge des saisons de Dor'danil dans le sud d'Orneval. Gardé par les esprits agités des druides déchus et les viles créatures qui les ont tués, le livre contient des connaissances historiques concernant les Aspects draconiques, servant de test rigoureux de sagesse et de mémoire pour ceux qui osent le récupérer.",al={"qu'est-ce que l'héritage des aspects","livre héritage des aspects","qu'est-ce que ce livre"}}},fp="21,226,18.582.0,26.144.0,40.174.0,68.193.0"}
P.entries["item:letter-of-commendation"] = {n="Letter of Commendation",s="La Letter of Commendation de Brother Anton porte son sceau et témoigne de l’estime de la Croisade écarlate. Elle envoie son porteur de Désolace auprès de Raleigh le Dévot, à Austrivage.",h="La Letter of Commendation de Brother Anton porte son sceau et témoigne de l’estime de la Croisade écarlate.",kw={"brother anton","désolace","letter of commendation","lordaeron","raleigh le dévot","croisade écarlate","monastère écarlate","austrivage"},ang={["faction:Alliance"]="Pour un voyageur de l’Alliance, Austrivage est une ville familière où Raleigh le Dévot reçoit la lettre de recommandation scellée de Brother Anton."},sec={{t="Une lettre scellée",b="Raleigh le Dévot attend à Austrivage le porteur de la lettre de Brother Anton. Le message scellé fait l’éloge des bastions de la Croisade écarlate, d’Âtreval aux Clairières de Tirisfal. Il déclare que la véritable menace du Fléau se trouve au Lordaeron et demande à Raleigh de recevoir le porteur."}},faq={{q="Qui m’a remis la lettre ?",a="Brother Anton a remis la Letter of Commendation et l’a scellée de son sceau.",al={"lettre d’anton","qui l’a scellée"}},{q="À qui dois-je la remettre ?",a="Raleigh le Dévot, à Austrivage, en est le destinataire.",al={"où apporter la lettre","lettre pour raleigh","qui la reçoit"}},{q="À quoi sert la lettre ?",a="La lettre recommande son porteur à Raleigh et lui demande de l’escorter jusqu’à une place d’honneur au Monastère écarlate.",al={"à quoi sert cette lettre","que fait-elle","but de la lettre"}},{q="Que dit Brother Anton au sujet du Fléau ?",a="Brother Anton affirme que la véritable menace du Fléau se trouve au Lordaeron.",al={"menace du fléau","anton au sujet du lordaeron","où le fléau sévit le plus"}},{q="Que dit la lettre au sujet de la Croisade écarlate ?",a="La Croisade écarlate revendique des bastions d’Âtreval aux Clairières de Tirisfal et les présente comme des bastions de purification.",al={"bastions de la croisade","bastions écarlates","où la croisade revendique des terres"}}},fp="22,168,15.278.0,23.74.0,22.59.0,23.115.1,45.62.0,51.111.0"}
P.entries["item:letter-to-delgren"] = {n="Lettre à Delgren",s="Balthule Frappelombre écrit depuis la Tour d'Althalaxx, dans le nord de Sombrivage. Sa lettre avertit Delgren le Purificateur des activités démoniaques de la secte de Dark Strand. Elle doit parvenir au Poste de Maestra, en Orneval.",h="Balthule Frappelombre écrit depuis la Tour d'Althalaxx, dans le nord de Sombrivage.",kw={"orneval","balthule frappelombre","dark strand","sombrivage","delgren le purificateur","lettre à delgren","poste de maestra","tour d'althalaxx"},ang={["class:Paladin"]="En tant que paladin, vous voyez un paladin humain enseigner la Lumière sacrée à une Elfe de la nuit. Leur lien unit les terres kaldorei à la foi guerrière des Royaumes de l'est.",["faction:Alliance"]="En tant que membre de l'Alliance, vous voyez des champions humains et des Sentinelles elfes de la nuit unir leurs forces contre les sectes démoniaques du nord de Kalimdor."},sec={{t="Un avertissement vers le sud",b="Dans les ruines de la Tour d'Althalaxx, Balthule Frappelombre observe la secte de Dark Strand se rassembler. Incapable de les détruire seul, il écrit à Delgren le Purificateur, son tuteur dans la Lumière sacrée, et demande de l'aide. Leurs rites infâmes menacent bien plus que le littoral de Sombrivage. La lettre doit traverser Sombrivage vers le sud, jusqu'à l'ouest d'Orneval. Là, Delgren travaille avec les Sentinelles elfes de la nuit contre les menaces démoniaques et mort-vivantes."}},faq={{q="Qu'est-ce que la Lettre à Delgren ?",a="La lettre scellée de Balthule Frappelombre avertit Delgren le Purificateur des activités grandissantes de la secte de Dark Strand à la Tour d'Althalaxx.",al={"qu'est-ce que cette lettre","lettre à delgren","lettre de balthule"}},{q="Qui est Delgren le Purificateur ?",a="Delgren le Purificateur est un paladin humain au Poste de Maestra, dans l'ouest d'Orneval. Il sert la Lumière sacrée et aide les Sentinelles elfes de la nuit à combattre les démons et les morts-vivants dans les forêts anciennes. Il enseigne aussi à Balthule l'art du combat sacré.",al={"qui est delgren","histoire de delgren","où est delgren"}},{q="Pourquoi Balthule envoie-t-il la lettre si loin ?",a="Balthule est l'élève de Delgren et compte sur le savoir-faire de son mentor pour lutter contre la corruption démoniaque. Au Poste de Maestra, Delgren peut s'appuyer sur ses talents au combat et sur les Sentinelles locales pour contrer les rites obscurs de Dark Strand.",al={"pourquoi l'envoyer en orneval","pourquoi ne pas prévenir auberdine"}},{q="Où faut-il livrer cette lettre ?",a="Portez la lettre vers le sud, à travers Sombrivage et jusqu'en Orneval. Le Poste de Maestra se trouve le long de la route de l'ouest.",al={"où apporter la lettre","lieu de livraison de la lettre"}}},fx={["8fccd45f"]={q="D'où provient la Lettre à Delgren et qui l'a écrite ?",a="La lettre a été rédigée par Balthule Frappelombre, un elfe de la nuit posté dans le nord de Sombrivage près de la tour d'Althalaxx. Cherchant à purger la corruption démoniaque prenant racine dans les ruines antiques, Balthule a écrit cette missive urgente pour appeler à l'aide et aux conseils de son mentor, le paladin Delgren le Purificateur.",al={"qui a écrit la lettre à delgren","d'où vient la lettre à delgren","qui a envoyé la lettre à delgren"}},["99aa1720"]={q="Pourquoi la Lettre à Delgren est-elle si importante ?",a="La missive contient des renseignements critiques exposant les opérations sinistres du culte de la Dark Strand à la tour d'Althalaxx. Delgren le Purificateur s'est consacré à aider les elfes de la nuit à nettoyer les démons et les morts-vivants des forêts, et Balthule doit alerter son mentor immédiatement afin qu'ils puissent affronter la menace grandissante.",al={"pourquoi delgren a besoin de la lettre","pourquoi vouloir la lettre à delgren","importance de la lettre à delgren"}}},fp="17,204,20.414.0,30.134.0,28.229.0,47.214.0,44.122.0"}
P.entries["item:letter-to-ello"] = {n="Lettre à Ello",s="Abercrombie envoie une lettre scellée au maire Ello Ebonlocke, à Sombre-Comté. L’ermite vit dans une cabane juste au nord du Cimetière de Colline-aux-Corbeaux, prétend être un vieil ami et rédige son message dans une écriture archaïque.",h="Abercrombie envoie une lettre scellée au maire Ello Ebonlocke, à Sombre-Comté.",kw={"abercrombie","sombre-comté","bois de la pénombre","ello ebonlocke","lettre à ello","note to the mayor","sirra von'indi"},ang={["faction:Alliance"]="En tant que voyageur de l’Alliance dans le Bois de la Pénombre, vous pouvez porter un message d’un reclus excentrique au maire d’une ville. Les responsables de Sombre-Comté restent sur leurs gardes face aux missives étranges."},sec={{t="Une salutation étrange",b="Après que vous avez aidé Abercrombie à accomplir des tâches dans le Bois de la Pénombre, le vieux reclus vous remet une note pour le maire Ello Ebonlocke. Il dit que le maire est un vieil ami qui célébrera ce que vous avez accompli. Quand Ello brise le sceau, il ne se souvient de personne du nom d’Abercrombie et ne comprend pas un seul mot de cette écriture archaïque. Il envoie la note à Sirra Von'Indi, l’érudite de Sombre-Comté, pour qu’elle la traduise."},{t="Sombres présages",b="Les runes d’Abercrombie annoncent un funeste destin à Sombre-Comté. La lettre ne décrit pas une vieille amitié entre des connaissances de la ville ; elle prédit la perte de toute la ville."}},faq={{q="Qui a écrit la Lettre à Ello ?",a="Abercrombie a écrit la lettre. C’est un ermite qui vit dans une cabane délabrée près du Cimetière de Colline-aux-Corbeaux, dans l’ouest du Bois de la Pénombre.",al={"qui a écrit la lettre","auteur de la lettre à ello","qui a envoyé la lettre"}},{q="Le maire Ello Ebonlocke peut-il lire la lettre ?",a="Non. Quand Ello Ebonlocke brise le sceau, l’écriture lui est totalement incompréhensible et semble être dans une langue ancienne et inconnue.",al={"ello peut-il la lire","pourquoi ello ne peut-il pas lire la note","langue de la lettre à ello"}},{q="Qui peut traduire la note ?",a="Sirra Von'Indi peut traduire la note. Le maire Ebonlocke l’envoie à l’érudite de Sombre-Comté, qui connaît les écritures anciennes et les langues ésotériques.",al={"qui traduit la note","traduire la note d’abercrombie","qui peut lire la lettre"}},{q="Le maire Ebonlocke connaît-il vraiment Abercrombie ?",a="Non. Abercrombie prétend qu’ils sont de vieux amis, mais Ello Ebonlocke dit n’avoir jamais entendu parler d’une personne du nom d’Abercrombie.",al={"ello connaît-il abercrombie","ello et abercrombie sont-ils amis","abercrombie et ello vieux amis"}}},fx={["74d18927"]={q="Qu'est-ce que la Lettre à Ello ?",a="La Lettre à Ello est une missive mystérieuse écrite dans une langue ancienne et illisible, rédigée par Abercrombie l'ermite. Adressée directement au maire Ello Bouclenoire de Sombre-Comté, l'ermite affirme que la note informera son « vieil ami » des actes que vous avez accomplis dans le cimetière.",al={"lettre à ello","quoi est lettre à ello","note d'abercrombie"}},ee8215fa={q="Pourquoi le maire Bouclenoire veut-il la Lettre à Ello ?",a="Le maire Bouclenoire veut la lettre uniquement parce que vous arrivez avec la nouvelle qu'un vieil ami nommé Abercrombie la lui a envoyée. Cependant, une fois qu'il la reçoit, le maire constate qu'il ne peut pas lire son écriture archaïque et cherche urgemment à la faire traduire pour découvrir ce que l'ermite avait réellement l'intention de dire.",al={"pourquoi ello veut la lettre","pourquoi vouloir lettre à ello","pourquoi livrer lettre à ello"}}},fp="14,205,18.399.0,10.165.1,29.117.0,41.155.0,27.151.0,47.119.1"}
P.entries["item:letter-to-jin-zil"] = {n="Lettre à Jin'Zil",s="À la Croisée, Darsok Vivedague transmet à Jin'Zil des nouvelles du nord des Tarides. Serena Bloodfeather est morte, et la menace des Bloodfeather a pris fin.",h="À la Croisée, Darsok Vivedague transmet à Jin'Zil des nouvelles du nord des Tarides.",kw={"darsok vivedague","harpies","jin'zil","lettre à jin'zil","malaka'jin","rokhan","serena bloodfeather","les serres-rocheuses"},ang={["faction:Horde"]="En tant que voyageur de la Horde, vous portez les nouvelles de la défense des Tarides au cœur des conflits des Serres-Rocheuses.",["race:Troll"]="En tant que troll, vous pouvez remettre la lettre au féticheur Jin'Zil, un ancien pratiquant qui perpétue le vaudou traditionnel loin des Îles de l'Écho."},sec={{t="Un messager pour les Serres-Rocheuses",b="Après l'extermination des harpies des Collines arides et la mort de Serena Bloodfeather, Darsok Vivedague écrit à un vieux camarade. Les harpies des Tarides ont d'abord niché dans les pics des Serres-Rocheuses. Darsok annonce à Jin'Zil, un féticheur, la mort de leur matriarche et présente un guerrier prometteur aux frontières lointaines."},{t="Vieux souvenirs à Malaka'jin",b="Dans sa caverne de Malaka'jin, Jin'Zil accueille la nouvelle avec satisfaction et ravive de vieux souvenirs. La mort de Serena lui rappelle la fondation de Durotar après la Troisième guerre. À l'époque, Rokhan, l'ami de Jin'Zil, s'était joint à Rexxar, un maître des bêtes demi-ogre, pour tuer la sœur aînée de Serena, Bloodfeather. Serena a elle aussi péri, et Jin'Zil croit que la vengeance de la lignée des Bloodfeather a pris fin."}},faq={{q="Qui a écrit la Lettre à Jin'Zil ?",a="Darsok Vivedague, un orc de la Croisée, dans les Tarides, a écrit la lettre. Il coordonne la défense contre les tribus de harpies qui ravagent la région.",al={"qui a écrit ceci","expéditeur de la lettre","lettre de darsok"}},{q="Où se trouve Jin'Zil ?",a="Jin'Zil vit dans une caverne à Malaka'jin, un avant-poste troll Sombrelance dans les escarpements du sud-est des Serres-Rocheuses.",al={"où est jinzil","emplacement de jin'zil","trouver jin'zil"}},{q="Que contient la lettre ?",a="La lettre annonce à Jin'Zil que Serena Bloodfeather, meneuse des harpies qui descendent dans le nord des Tarides, a été tuée. Sa mort sécurise le périmètre au nord de la Croisée.",al={"que dit la lettre","contenu de la lettre"}},{q="Pourquoi les Bloodfeather intéressent-ils Jin'Zil ?",a="Jin'Zil se souvient de la fondation de Durotar après la Troisième guerre. Son compagnon Rokhan et Rexxar, un guerrier demi-ogre, ont tué la sœur aînée de Serena. Depuis, Serena cherchait à se venger de la Horde ; sa chute apporte donc une conclusion bienvenue.",al={"pourquoi jin'zil s'intéresse aux harpies","histoire des bloodfeather","rokhan et bloodfeather"}}},fx={f9426e82={q="Pourquoi Jin'Zil veut-il qu'on lui apporte la Lettre à Jin'Zil ?",a="La lettre apporte des nouvelles attendues depuis longtemps de son vieil ami Darsok Vivedague dans les Tarides. Jin'Zil n'a pas eu de nouvelles de Darsok depuis de nombreuses années, et la missive confirme la mort de Serena Bloodfeather, mettant fin aux matriarches harpies qui tourmentaient à la fois les Tarides et les Serres-Rocheuses.",al={"pourquoi livrer lettre à jinzil","qui veut lettre à jinzil","pourquoi jinzil s'intéresse à la lettre"}}},fp="17,157,25.330.0,26.369.1,32.137.0,25.116.0,41.183.0,46.243.1"}
P.entries["item:letter-to-jorgen"] = {n="Lettre à Jorgen",s="À Hurlevent, une lettre scellée appelle Jorgen à aider à retrouver un diplomate disparu.",h="À Hurlevent, une lettre scellée appelle Jorgen à aider à retrouver un diplomate disparu.",kw={"jaina portvaillant","jorgen","lettre à jorgen","diplomate disparu","hurlevent","theramore","vallée des héros"},ang={["class:Rogue"]="En tant que voleur, vous savez que des missives discrètes et des informateurs de rue réticents peuvent aider à découvrir les problèmes qui agitent la capitale.",["faction:Alliance"]="La lettre concerne la fragile stabilité de l’Alliance et cherche une réponse discrète à un incident qui menace les liens entre Hurlevent et Theramore."},sec={{t="Un appel sans émotion",b="Un diplomate en route pour Theramore n’est jamais arrivé aux pourparlers avec Dame Jaina Portvaillant. Les enquêteurs royaux ont rapidement agi pour étouffer l’affaire. Tandis que les agents officiels fouillaient la capitale, d’autres réseaux s’activaient. La lettre contourne la hiérarchie militaire et sollicite Jorgen, un vétéran bourru qui pêche sous les grandes statues de la Vallée des héros. Elle invoque d’anciennes obligations et l’entraîne dans une enquête clandestine, sur fond de rumeurs de conspiration défias."}},faq={{q="Quel est le but de cette lettre ?",a="La lettre présente son porteur et demande à Jorgen d’honorer une ancienne obligation. Elle envoie le porteur à la Vallée des héros pour enquêter discrètement sur la disparition du diplomate.",al={"à quoi sert la lettre à jorgen","pourquoi la lettre à jorgen","but de la lettre"}},{q="Qui est Jorgen ?",a="Jorgen est un contact solitaire qui vit juste à l’intérieur des portes de Hurlevent et passe son temps à pêcher dans la Vallée des héros. Il déteste être dérangé, mais une vieille dette le contraint à aider lorsqu’on lui montre la lettre.",al={"qui est jorgen","jorgen personnage non joueur","jorgen hurlevent"}},{q="À quelle disparition la lettre fait-elle référence ?",a="Un diplomate de renom a quitté Hurlevent par bateau pour Theramore, où il devait rencontrer Dame Jaina Portvaillant, puis a disparu en chemin. Les soupçons se portent sur la Confrérie défias, mais le complot dans son ensemble reste étroitement tenu secret.",al={"quel diplomate a disparu","qui a disparu","diplomate disparu"}},{q="Où la lettre doit-elle être remise ?",a="La lettre est portée à la Vallée des héros, la grande entrée de Hurlevent bordée de monuments aux héros de la Seconde guerre. Jorgen pêche près de l’eau, à proximité des portes principales.",al={"où apporter la lettre","emplacement de jorgen","où se trouve jorgen"}}},fx={["0eeb183b"]={q="Qu'est-ce que la Lettre à Jorgen ?",a="Cette lettre est un message confidentiel envoyé concernant la disparition silencieuse d'un diplomate de Hurlevent en route vers Theramore. Comme les agents royaux officiels fouillent déjà la ville au grand jour, cette note scellée recrute des contacts privés et discrets en dehors des canaux officiels de la couronne pour enquêter sur l'implication suspectée de la The Defias Brotherhood.",al={"quoi est lettre à jorgen","objet lettre à jorgen","à propos lettre à jorgen"}},["5d64bfbf"]={q="D'où vient la Lettre à Jorgen et qui l'a écrite ?",a="La lettre a été rédigée par l'Evêque DeLavey à Hurlevent, qui cherchait à mener une enquête indépendante sur le diplomate disparu. Faisant davantage confiance à des alliés personnels qu'aux enquêteurs voyants de la couronne, il a rédigé le message spécifiquement pour faire appel à un vieil ami nommé Jorgen, qui se fait actuellement discret au bord des eaux de la Vallée des héros.",al={"qui a écrit lettre à jorgen","qui a envoyé lettre à jorgen","origine lettre à jorgen"}},["9fd54092"]={q="Pourquoi la Lettre à Jorgen est-elle recherchée ?",a="Jorgen a besoin de la lettre car elle décrit une obligation secrète qu'il ne peut ignorer. Bien qu'il soit réticent à l'idée d'être arraché à sa paisible partie de pêche, le contenu de la missive le persuade d'aider à déjouer le complot des Defias avant que la panique ne s'empare de la capitale.",al={"pourquoi livrer lettre à jorgen","pourquoi jorgen a besoin de la lettre","but donner lettre à jorgen"}}},fp="16,80,23.440.0,35.174.0,14.196.0,45.206.0,30.181.0"}
P.entries["item:lewis-note"] = {n="Note de Lewis",s="À la Colline des Sentinelles, l’Intendant Lewis envoie un courrier à dos de griffon chercher des armures pour la garnison de Marche de l’Ouest. La commande est destinée à un armurier privé de Hurlevent.",h="À la Colline des Sentinelles, l’Intendant Lewis envoie un courrier à dos de griffon chercher des armures pour...",kw={"griffon","note de lewis","limited immunity","vieille ville","osric strang","intendant lewis","colline des sentinelles","thor"},ang={["race:Human"]="En tant qu’aventurier humain, transporter la commande vous apprend à emprunter les routes de griffons du royaume. Cela vous montre aussi combien les dirigeants de Hurlevent font peu pour équiper les défenseurs de Marche de l’Ouest."},sec={{t="Un appel pour de l’acier",b="À la Colline des Sentinelles, The People's Militia reçoit peu de soutien de la noblesse de Hurlevent. Les escarmouches contre la Confrérie défias épuisent peu à peu ses maigres réserves d’équipement. L’Intendant Lewis se tourne donc vers le commerce privé pour équiper les défenseurs. Sa commande passe en dehors des circuits militaires du royaume. Un courrier de l’Alliance doit voler à dos de griffon jusqu’à la Vieille ville et la remettre à Osric Strang, propriétaire de Limited Immunity."}},faq={{q="Qu’est-ce que la Note de Lewis ?",a="La Note de Lewis est une commande écrite de l’Intendant Lewis à Osric Strang, un armurier de Hurlevent, lui demandant d’envoyer de l’équipement de protection à la garnison de Marche de l’Ouest.",al={"à quoi sert cet objet","but de la note de lewis","que fait la note"}},{q="Qui a écrit cette note ?",a="L’Intendant Lewis a écrit la note. Il gère les fournitures, les provisions et l’armement de The People's Militia à la Colline des Sentinelles.",al={"qui est lewis","intendant lewis"}},{q="Qui reçoit la note ?",a="La note est d’abord remise à Thor, le maître des griffons de la Colline des Sentinelles. De là, elle voyage jusqu’à la boutique d’armures de Osric Strang, Limited Immunity, dans la Vieille ville de Hurlevent.",al={"où va la note","qui reçoit la note de lewis","note pour osric strang"}},{q="Pourquoi la garnison ne reçoit-elle pas simplement des armures du royaume ?",a="Le gouvernement de Hurlevent a largement délaissé Marche de l’Ouest. Ses défenseurs ne reçoivent ni financement militaire direct ni armures de la couronne. Lewis compte donc sur des marchands comme Osric Strang pour équiper la milice.",al={"pourquoi acheter chez osric","pourquoi hurlevent n’aide pas","aide de hurlevent à marche de l’ouest"}}},fp="11,153,16.423.0,20.153.0,20.125.0,22.166.0,57.204.0"}
P.entries["item:lieutenant-s-insignia"] = {n="Insigne de lieutenant",s="Près d’Orgrimmar, des sectateurs portent l’Insigne de lieutenant et la marque de la Lame ardente. Des aventuriers de la Horde le récupèrent sur eux.",h="Près d’Orgrimmar, des sectateurs portent l’Insigne de lieutenant et la marque de la Lame ardente.",kw={"lame ardente","la faille de l'ombre","durotar","hidden enemies","insigne de lieutenant","neeru fireblade","conseil des ombres","rocher du crâne","thrall"},ang={["class:Warlock"]="Pour un démoniste, l’Insigne de lieutenant montre que la Lame ardente met la magie gangrenée au service de la Légion ardente. Cela met à l’épreuve la tolérance de Thrall envers les démonistes de la Horde qui respectent la loi.",["faction:Horde"]="Pour la jeune Horde, l’Insigne de lieutenant signale le danger d’une corruption démoniaque qui cherche à saper de l’intérieur la nouvelle nation de Thrall."},sec={{t="La marque de la secte",b="Les sectateurs du Rocher du Crâne, sur la côte est de Durotar, portent l’Insigne de lieutenant. Cette marque désigne son porteur comme officier de la Lame ardente. Le chef de guerre Thrall ne tolérera pas de traîtres dans sa nouvelle nation. Pourtant, une purge pourrait disperser la secte avant que ses maîtres ne soient démasqués. Il confie donc l’insigne à un champion pour mettre à l’épreuve ceux que l’on soupçonne de s’infiltrer sous Orgrimmar."},{t="La Faille de l’Ombre",b="Le chef de guerre Thrall envoie son agent à la Faille de l’Ombre avec l’Insigne de lieutenant, pour le montrer à Neeru Lamefeu. Neeru prend l’agent pour un subordonné récemment promu. Sûr de sa position, le démoniste se vante que la Lame ardente sert le Conseil des ombres et la Légion ardente. Ces paroles donnent à Thrall un moyen de révéler la corruption qui règne sous la ville."}},faq={{q="D’où vient l’Insigne de lieutenant ?",a="Les fanatiques et les apprentis de la Lame ardente portent l’Insigne de lieutenant au Rocher du Crâne. La caverne se trouve sur la côte de Durotar, à l’est d’Orgrimmar.",al={"comment obtenir l’insigne de lieutenant","qui fait tomber l’insigne de lieutenant","source de l’insigne de lieutenant"}},{q="À quoi sert l’insigne ?",a="Le chef de guerre Thrall donne l’Insigne de lieutenant à son agent pour le déguiser. Un jeune aventurier qui le porte peut se faire passer pour un officier de la Lame ardente et accéder à des lieux où les agents de Thrall ne peuvent aller, afin de découvrir qui dirige la secte.",al={"pourquoi avoir besoin de l’insigne de lieutenant","utilité de l’insigne de lieutenant dans la quête","que faire de l’insigne"}},{q="Qui est Neeru Lamefeu ?",a="Neeru Lamefeu est un démoniste orc dans la Faille de l’Ombre, à Orgrimmar. Il prétend servir Thrall en montrant comment les démonistes peuvent aider la Horde, mais dirige secrètement la secte locale de la Lame ardente.",al={"qui est neeru","histoire de neeru lamefeu"}},{q="Pourquoi Thrall ne tue-t-il pas Neeru Lamefeu sur-le-champ ?",a="Thrall sait que Neeru est un traître, mais une attaque prématurée pourrait avertir les véritables maîtres de la secte et disperser son réseau. Il se sert de Neeru comme informateur involontaire pour découvrir l’ampleur de la présence du Conseil des ombres en Durotar.",al={"pourquoi thrall ne tue pas neeru","pourquoi garder neeru en vie","pourquoi infiltrer neeru"}}},fx={["2e1cfb76"]={q="Qu'est-ce que l'Insigne de lieutenant ?",a="Il s'agit d'un emblème porté par les officiers du culte de la Lame ardente, marquant le porteur comme un lieutenant de haut rang reconnu parmi leurs rangs. Pour les cultistes démoniaques opérant en secret dans tout Durotar, présenter ce jeton signifie loyauté, statut et autorité au sein du réseau du Conseil des ombres.",al={"quoi est insigne de lieutenant","insigne lieutenant quoi c'est","insigne lame ardente"}}},fp="21,121,18.363.0,19.359.1,47.135.0,30.207.1,23.183.2,57.211.1"}
P.entries["item:lightning-gland"] = {n="Glande d'éclair",s="Dans les Tarides, les peaux-d’orage portent des glandes d’éclair dont le Brasseur Drohn a besoin à Cabestan. Chen Stormstout lui a appris à brasser une bière de trogg ardente.",h="Dans les Tarides, les peaux-d’orage portent des glandes d’éclair dont le Brasseur Drohn a besoin à Cabestan.",kw={"tarides","brasseur drohn","chen stormstout","glande d'éclair","cabestan","peau-d’orage","bière de trogg"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez voir comment le Brasseur Drohn et Chen Stormstout utilisent des organes de bêtes crus dans leurs spiritueux. Les glandes d’éclair ne sont pas des aliments ordinaires."},sec={{t="Un ingrédient électrisant",b="Les peaux-d’orage parcourent les savanes des Tarides parmi d’autres prédateurs touchés par les éléments. Leur chair renferme des glandes d’éclair chargées d’électricité latente. Elles sont peu nourrissantes seules, mais les brasseurs prisent le piquant qu’elles donnent à une bière."},{t="La bière de trogg de Drohn",b="À Cabestan, le Brasseur Drohn perpétue les traditions brassicoles de Chen Stormstout. Pour préparer une bière de trogg corsée, il lui faut cinq glandes d’éclair, une glande salivaire de faucon-tonnerre et un foie de kodo frais. La boisson obtenue a du mordant, ce que les aventuriers trouvent revigorant et puissant."}},faq={{q="Quelles créatures portent des glandes d’éclair ?",a="Les peaux-d’orage qui parcourent les savanes des Tarides portent des glandes d’éclair.",al={"où trouver la glande d’éclair","qui laisse tomber la glande d’éclair","glande d’éclair de peau-d’orage"}},{q="Qui veut des glandes d’éclair, et pourquoi ?",a="Le Brasseur Drohn, à Cabestan, veut des glandes d’éclair pour sa bière de trogg. Chen Stormstout, le brasseur errant, lui a appris la recette.",al={"qui a besoin de la glande d’éclair","rendre la glande d’éclair","utilité de la glande d’éclair"}},{q="Que faut-il en plus de la glande d’éclair ?",a="Drohn a besoin de cinq glandes d’éclair, d’une glande salivaire de faucon-tonnerre prélevée sur de grands faucons-tonnerre et d’un foie de kodo frais provenant des bêtes des Tarides.",al={"ingrédients de la bière de trogg de drohn","les trois ingrédients du tonnelet de chen"}}},fx={f0cc18d7={q="Qu'est-ce qu'une Glande d'éclair ?",a="Une Glande d'éclair est un organe prélevé sur des bêtes-tempêtes errant dans les Tarides. Imprégnée des énergies électriques naturelles qui parcourent ces créatures, la glande contient une puissante charge élémentaire qui la rend prisée comme ingrédient de brassage exotique.",al={"quoi est glande d'éclair","lore glande d'éclair","qu'est-ce qu'une glande d'éclair"}},ba679c5d={q="D'où vient une Glande d'éclair ?",a="Les Glandes d'éclair ne sont pas fabriquées par des mains mortelles ; ce sont des organes biologiques prélevés directement sur les bêtes-tempêtes qui rôdent dans les savanes des Tarides. Ces bêtes sauvages développent naturellement ces glandes pour canaliser l'énergie électrique crépitante.",al={"d'où viennent les glandes d'éclair","origine glande d'éclair","comment sont faites les glandes d'éclair"}}},fp="15,155,21.241.0,17.277.0,38.63.0,35.131.0,50.143.0"}
P.entries["item:logging-rope"] = {n="Corde de bûcheron",s="Au Camp de bûcherons Chanteguerre, la Corde de bûcheron approvisionne les scieries et les machines. Des tribus de furbolgs ont volé des cargaisons à travers Orneval, et les Chanteguerre doivent récupérer les cordes dont ils ont besoin.",h="Au Camp de bûcherons Chanteguerre, la Corde de bûcheron approvisionne les scieries et les machines.",kw={"orneval","foulweald","locke okarr","corde de bûcheron","poste de bois-brisé","thistlefur","camp de bûcherons chanteguerre","warsong supplies"},ang={["faction:Horde"]="Récupérer la Corde de bûcheron aide à approvisionner le clan Chanteguerre en bois malgré les embuscades des furbolgs.",["race:Orc"]="En tant qu’orc, vous dépendez du bois d’Orneval pour vous installer en Kalimdor. Les fournitures de bûcheronnage volées menacent ces travaux."},sec={{t="Cordes volées",b="Les furbolgs de Foulweald et Thistlefur ont volé des cargaisons de Corde de bûcheron destinées au Camp de bûcherons Chanteguerre. Ils ont intercepté les cordes avant qu’elles n’atteignent les bûcherons. Elles sont gardées dans des tanières et des campements de village, dans le nord et le centre d’Orneval. La corruption a rendu les furbolgs fous, et ils défendent farouchement leurs bois ancestraux."},{t="Approvisionner l’effort de guerre",b="Au Poste de Bois-brisé, Locke Okarr cherche à récupérer les fournitures volées avant que le travail ne s’arrête au Camp de bûcherons Chanteguerre. Cette corde épaisse sert à attacher le bois, à lier les grumes et à monter les scies mécaniques. Les furbolgs continuent de résister dans toute la forêt."}},faq={{q="À quoi sert la Corde de bûcheron ?",a="Le Camp de bûcherons Chanteguerre utilise la Corde de bûcheron pour attacher le bois abattu, transporter les grumes et monter les machines lourdes en Orneval.",al={"utilisation de la corde de bûcheron","pourquoi les chanteguerre ont besoin de cordes","corde de bûcheron chanteguerre"}},{q="Qui a volé les cordes de bûcheron ?",a="Les furbolgs de Foulweald et Thistlefur ont volé les cordes de bûcheron. Ils les gardent dans leurs tanières et leurs campements de village, à travers Orneval.",al={"qui a pris les cordes","voleur de cordes","quels furbolgs ont des cordes"}},{q="Qui veut récupérer ces cordes ?",a="Locke Okarr, au Poste de Bois-brisé, veut récupérer les cordes avec les autres fournitures volées afin que le travail puisse continuer au Camp de bûcherons Chanteguerre.",al={"qui a besoin de cordes de bûcheron","donneur de quête de la corde de bûcheron"}},{q="Pourquoi les furbolgs volent-ils les fournitures de bûcheronnage ?",a="Les furbolgs volent les fournitures de bûcheronnage pour perturber les scieries de la Horde et résister à l’exploitation de leurs bois ancestraux.",al={"motif des furbolgs","pourquoi les furbolgs attaquent les cargaisons"}}},fx={["26f07746"]={q="Qu'est-ce qu'une Corde de bûcheron ?",a="La Corde de bûcheron est un cordage robuste vital pour les opérations forestières étendues du clan Chanteguerre à travers Orneval. Utilisée pour sécuriser, transporter et lier les arbres abattus massifs, c'est un élément indispensable de la récolte quotidienne du camp de bûcherons.",al={"quoi est corde de bûcheron","info corde de bûcheron","corde de bûcheron chanteguerre"}}},fp="12,184,12.342.0,24.231.0,30.118.0,27.130.0,25.136.0,43.120.0"}
P.entries["item:lok-s-skull"] = {n="Crâne de Lok",s="Dans les Tarides du sud, le Crâne de Lok marque la chute d’un chef Tranchecrin redouté. Lok Orcbane menait de féroces raids de sangliers contre les routes de ravitaillement de la Horde, et le crâne est sa tête tranchée.",h="Dans les Tarides du sud, le Crâne de Lok marque la chute d’un chef Tranchecrin redouté.",kw={"betrayal from within","camp taurajo","la croisée","lok orcbane","crâne de lok","mutiledent","tranchecrin","thork"},ang={["faction:Horde"]="En tant que membre de la Horde, prendre le crâne de Lok Orcbane brise le pouvoir des chefs sangliers du sud qui harcèlent les caravanes de ravitaillement entre le Camp Taurajo et la Croisée.",["race:Orc"]="En tant qu’orc, exhiber la tête tranchée d’un chef sanglier nommé « Orcbane » procure une profonde satisfaction et rassure ceux qui défendent les Tarides."},sec={{t="La chute d’un chef",b="Lok Orcbane menait des assauts agressifs de sangliers Tranchecrin contre les lignes de ravitaillement de la Horde dans les Tarides du sud. Il a surgi du Kraal de Tranchebauge avec ses lieutenants Nak et Kuz. Après avoir trahi Mutiledent et l’avoir laissé captif au Camp Taurajo, Lok s’est fait connaître des défenseurs orcs par ses raids impitoyables, qu’ils peinaient à contenir. Mutiledent dirige les champions de la Horde vers le camp de Lok. S’emparer du Crâne de Lok venge le captif et frappe les chefs qui alimentent l’offensive Tranchecrin."},{t="Une preuve pour la Croisée",b="Mutiledent exige les crânes des trois conspirateurs pour assouvir sa vengeance. Puis il envoie le Crâne de Lok au nord, à Thork, à la Croisée. Thork et le commandement de la Horde soupçonnaient qu’un autre sanglier menait les raids. Le Crâne de Lok fut une sinistre surprise et prouva que la menace pesant sur les routes commerciales centrales des Tarides avait été éliminée."}},faq={{q="Qui était Lok Orcbane ?",a="Lok Orcbane était un redoutable guerrier Tranchecrin qui a surgi du Kraal de Tranchebauge pour mener des bandes de pillards sangliers dans les Tarides du sud. Il haïssait les orcs et menait des assauts agressifs contre les caravanes et les avant-postes de la Horde avec ses fidèles alliés Nak et Kuz.",al={"qui est lok","histoire de lok orcbane","qui était lok orcbane"}},{q="Pourquoi Mutiledent veut-il le Crâne de Lok ?",a="Lok Orcbane et ses compagnons ont trahi Mutiledent et l’ont laissé aux taurens, qui l’ont capturé et mis en cage au Camp Taurajo. Certain que sa propre mort est proche, Mutiledent veut se venger de ceux qui l’ont abandonné. Il envoie des aventuriers de la Horde tuer ses anciens camarades.",al={"pourquoi mutiledent veut le crâne","vengeance de mutiledent","pourquoi tuer lok"}},{q="Pourquoi apporter le crâne à Thork, à la Croisée ?",a="Thork supervise la défense de la Croisée et s’efforce de protéger les routes de ravitaillement de la Horde contre les attaques des sangliers. Le Crâne de Lok prouve au commandant orc que le chef des raids du sud a été tué, ce qui met les voyageurs de la région en sécurité.",al={"pourquoi apporter le crâne à thork","thork et le crâne de lok","qui reçoit le crâne de lok"}},{q="Qui étaient Nak et Kuz ?",a="Nak et Kuz menaient des raids aux côtés de Lok Orcbane dans les Tarides du sud. Mutiledent dit que l’un était un lanceur de sorts et l’autre un pisteur, ce qui renforçait les capacités de Lok au combat lors des raids contre la Horde.",al={"nak et kuz","lieutenants de lok orcbane","kuz et nak"}}},fx={a8e2f7c2={q="Qu'est-ce que le Crâne de Lok ?",a="Le Crâne de Lok est la tête tranchée de Lok Orcbane, un guerrier féroce qui a mené des raids impitoyables de Quillboars Tranchecrins contre les routes de ravitaillement de la Horde à travers les Tarides du sud. Pris comme preuve macabre de sa mort, il sert à la fois d'instrument de vengeance pour un membre de tribu trahi et de preuve indéniable pour les défenseurs de la Croisée que la menace a été écartée.",al={"quoi est crâne de lok","objet crâne de lok","quoi est ce crâne"}},["4d726f58"]={q="D'où vient le Crâne de Lok ?",a="Il est prélevé directement sur le corps de Lok Orcbane dans les Tarides du sud. Lok et ses lieutenants émergeaient du Kraal de Tranchebauge pour organiser des groupes de pillards contre la Horde, jusqu'à ce que Mutiledent, un Quillboar exilé retenu au Camp Taurajo, révèle leur bastion afin que Lok puisse être abattu.",al={"d'où vient crâne de lok","qui a fait crâne de lok","source crâne de lok"}}},fp="11,183,18.461.0,24.319.1,20.250.0,38.265.0,52.240.0,21.196.0"}
P.entries["item:lonebrow-s-journal"] = {n="Journal de Lonebrow",s="Au pied de La Grande élévation, le journal de Henrig Lonebrow consigne son dernier voyage. Il a traversé les Tarides tandis que le danger grandissait au Kraal de Tranchebauge.",h="Au pied de La Grande élévation, le journal de Henrig Lonebrow consigne son dernier voyage.",kw={"the crone of the kraul","falfindel gardevoie","la grande élévation","henrig lonebrow","kraal de tranchebauge","thalanaar","mille pointes"},ang={["faction:Alliance"]="Les derniers écrits de Henrig Lonebrow rapprochent les éclaireurs de l’Alliance des druides qui gardent la frontière de Féralas. Ils apportent leur aide contre la menace des hurans.",["race:Dwarf"]="Découvrir un nain mort dans ces contrées reculées et hostiles vous rappelle les dangers auxquels les explorateurs nains sont confrontés loin de Khaz Modan."},sec={{t="Un dernier vœu à La Grande élévation",b="Henrig Lonebrow est mort près du pied de La Grande élévation, le passage entre Les Tarides et Mille pointes. Ses os reposent sur une corniche rocheuse, son journal usé par le temps toujours serré dans sa main.\n\nLes pages racontent ses derniers voyages et demandent à la personne qui le trouvera de transmettre un message à Falfindel Gardevoie, un druide elfe de la nuit à Thalanaar. L’avant-poste se trouve à la frontière de Féralas. Les notes de Lonebrow mettent en garde contre la menace grandissante des hurans dans les Tarides du sud."},{t="Liens avec Tranchebauge",b="Falfindel Gardevoie reçoit des écrits qui confirment les craintes de l’Alliance au sujet des hurans du Kraal de Tranchebauge. Le récit de Lonebrow appelle à frapper au cœur du dédale épineux. Charlga Trancheflanc, The Crone of the Kraul, dirige la menace."}},faq={{q="Qui était Henrig Lonebrow ?",a="Henrig Lonebrow était un voyageur nain mort au pied de La Grande élévation, dans Mille pointes. Son journal est resté dans sa main, destiné à transmettre son récit aux elfes de la nuit de Thalanaar.",al={"henrig lonebrow","qui est lonebrow","nain mort élévation"}},{q="Où trouve-t-on le journal ?",a="Le journal repose près du squelette de Henrig Lonebrow, sur une corniche rocheuse basse juste à côté de la rampe, au pied de La Grande élévation, dans le nord de Mille pointes.",al={"où se trouve le journal de lonebrow","trouver le journal de lonebrow","squelette à la grande élévation"}},{q="À qui faut-il remettre le Journal de Lonebrow ?",a="Emportez le Journal de Lonebrow vers l’ouest, à travers Mille pointes, jusqu’à Falfindel Gardevoie, un druide elfe de la nuit à Thalanaar, à la frontière de Féralas.",al={"à qui apporter le journal","falfindel gardevoie","où remettre le journal"}},{q="À quoi mène le journal ?",a="Le journal transmet à Falfindel Gardevoie des informations sur les hurans. Le récit appelle à frapper le Kraal de Tranchebauge et Charlga Trancheflanc.",al={"quête the crone of the kraul","suite du journal de lonebrow"}}},fx={a9190e03={q="Qu'est-ce que le Journal de Lonebrow ?",a="Le Journal de Lonebrow est un journal personnel usé trouvé serré dans les mains squelettiques du Nain Henrig Lonebrow. Découvert au pied de la Grande élévation dans les Mille pointes, il documente ses voyages et ses dernières volontés avant qu'il ne trouve la mort dans le canyon.",al={"quoi est journal de lonebrow","quoi est ce livre","journal d'henrig lonebrow"}},["090ee1d4"]={q="D'où vient le Journal de Lonebrow et qui l'a fait ?",a="Le journal a été rédigé par Henrig Lonebrow, un voyageur nain qui a parcouru les canyons périlleux des Mille pointes. Il l'a gardé avec lui jusqu'à sa mort près de la base de la Grande élévation, où sa dépouille et le volume ont finalement été découverts.",al={"qui a écrit journal de lonebrow","auteur journal de lonebrow","d'où vient le journal"}},ea8f453f={q="Pourquoi quelqu'un veut-il le Journal de Lonebrow ?",a="Remettre le journal accomplit les dernières volontés du nain défunt. Falfindel Gardevoie, un druide elfe de la nuit stationné à Thalanaar à la frontière de Féralas, cherche à lire son contenu pour comprendre le destin d'Henrig et découvrir les dangers qui se préparent dans le Kraal de Tranchebauge.",al={"pourquoi livrer journal de lonebrow","qui a besoin journal de lonebrow","pourquoi vouloir journal de lonebrow"}}},fp="18,144,30.432.0,20.245.1,24.192.0,27.150.0,38.134.0,30.133.1"}
P.entries["item:lookout-s-spyglass"] = {n="Longue-vue de guetteur",s="La Longue-vue de guetteur est un instrument volé que la Confrérie du thorium tient en haute estime. Sa perte prive les guetteurs de la Gorge des Vents brûlants d’un excellent outil pour surveiller la région.",h="La Longue-vue de guetteur est un instrument volé que la Confrérie du thorium tient en haute estime.",kw={"dark iron lookouts","longue-vue de guetteur","gorge des vents brûlants","la fosse aux scories","longue-vue","instrument volé","sous-chef scrange","confrérie du thorium"},sec={{t="Un instrument volé",b="Des nains Dark Iron ont dérobé la Longue-vue de guetteur à la Confrérie du thorium, dans la Gorge des Vents brûlants. La Confrérie veut la remettre à Sous-chef Scrange, qui attend les biens volés."}},faq={{q="Qu’est-ce que la Longue-vue de guetteur ?",a="La Longue-vue de guetteur est un excellent outil de surveillance utilisé par les guetteurs.",al={"longue-vue","longue-vue de guetteur","qu’est-ce que la longue-vue"}},{q="Qui a volé la longue-vue ?",a="La Confrérie du thorium affirme que des nains Dark Iron ont volé la Longue-vue de guetteur dans la Gorge des Vents brûlants.",al={"qui l’a prise","dark iron a volé la longue-vue","voleurs de la longue-vue"}},{q="Qui veut récupérer la longue-vue ?",a="Sous-chef Scrange, de la Confrérie du thorium, veut récupérer la Longue-vue de guetteur volée.",al={"qui la veut","récupérer la longue-vue","longue-vue scrange"}},{q="Où se trouvent les Dark Iron Lookouts ?",a="Les Dark Iron Lookouts surveillent les environs depuis des tours autour de la Fosse aux scories, dans la Gorge des Vents brûlants.",al={"emplacement des guetteurs","où sont les guetteurs","tours des dark iron lookouts"}},{q="Pourquoi la Confrérie la veut-elle ?",a="La Longue-vue de guetteur est un outil de surveillance inestimable pour les guetteurs.",al={"importance de la longue-vue","utilité de la longue-vue","à quoi sert-elle"}}},fp="18,170,19.180.0,31.72.0,23.93.0,28.96.0,33.74.0,33.73.0"}
P.entries["item:lorgalis-manuscript"] = {n="Manuscrit de Lorgalis",s="Sous Orneval, le Manuscrit de Lorgalis repose dans les ruines englouties des Profondeurs de Brassenoire. Ce texte ancien parle des Dieux très anciens, et de sombres érudits convoitent ses mots sur les puissances endormies.",h="Sous Orneval, le Manuscrit de Lorgalis repose dans les ruines englouties des Profondeurs de Brassenoire.",kw={"profondeurs de brassenoire","forlorn cavern","gerrig poigne-d'os","forgefer","lorgalis","manuscrit","dieu très ancien","ceux qui dorment"},ang={["class:Warlock"]="En tant que Démoniste, vous découvrez un rare aperçu du savoir interdit sur les Dieux très anciens et les entités des profondeurs, un savoir convoité par ceux qui pratiquent les arts sombres.",["race:NightElf"]="En tant qu'Elfe de la nuit, vous découvrez le texte dans des ruines noyées où votre peuple a vécu autrefois. Sa vénération d'Aku'mai et des Dieux très anciens révèle le culte sombre qui s'est enraciné dans ces salles déchues."},sec={{t="Un tome sur ceux qui dorment",b="Le Manuscrit de Lorgalis repose au fond des Profondeurs de Brassenoire, parmi les ruines où vivaient autrefois des elfes disparus depuis longtemps. Lorgalis a écrit au sujet des Dieux très anciens, qui se déchaînaient à travers Azeroth lorsque le monde était jeune et qui gisent désormais enchaînés dans le sommeil. Le texte loue Aku'mai, serviteur des Dieux très anciens, qui réside dans les Profondeurs.\n\nOn dit que son savoir ouvre des portes mystiques et éveille d'antiques êtres endormis dans les profondeurs du monde. Le manuscrit repose dans un coffre en fer piqué, au milieu des couloirs inondés. Sectateurs et érudits de l'ombre convoitent ses mots."},{t="Des yeux dans l'ombre",b="Dans la Forlorn Cavern de Forgefer, l'excentrique collectionneur Gerrig Poigne-d'os engage des aventuriers pour traverser la mer et récupérer le manuscrit. Poigne-d'os parle avec vénération des derniers jours et de l'éveil des divinités endormies. Il compte faire copier le texte et le partager avec son cercle secret de frères et de sœurs, répandant un savoir interdit que les gens de la surface n'étaient pas censés comprendre."}},faq={{q="Qu'est-ce que le Manuscrit de Lorgalis ?",a="Le Manuscrit de Lorgalis est un ancien texte écrit par Lorgalis au sujet des Dieux très anciens. On dit que son contenu révèle comment ouvrir des portes et éveiller des êtres primordiaux assoupis.",al={"qu'est-ce que le manuscrit de lorgalis","lore du livre de lorgalis","que fait le manuscrit"}},{q="Où se trouve le manuscrit ?",a="Le manuscrit repose dans un coffre en fer piqué, au fond des Profondeurs de Brassenoire, un temple en ruines des elfes de la nuit, le long de la grève de Zoram, en Orneval.",al={"où trouver le manuscrit de lorgalis","emplacement du manuscrit","coffre de brassenoire"}},{q="Qui veut le manuscrit ?",a="Gerrig Poigne-d'os opère depuis la Forlorn Cavern de Forgefer et veut récupérer le manuscrit. Il compte le faire copier et partager ses enseignements avec ses pairs discrets.",al={"qui veut le manuscrit de lorgalis","quête de gerrig poigne-d'os","qui est poigne-d'os"}},{q="Pourquoi Gerrig Poigne-d'os parle-t-il des derniers jours ?",a="Poigne-d'os vénère les Dieux très anciens et les étudie. Il recherche d'anciens écrits des elfes au sujet de l'éveil de Ceux qui dorment, qu'il croit annonciateur de la fin des temps.",al={"gerrig et les derniers jours","poigne-d'os sectateur","poigne-d'os et les dieux très anciens"}}},fx={["61ae2bf7"]={q="D'où vient le Manuscrit de Lorgalis, et qui l'a fabriqué ?",a="Le manuscrit a été écrit par un certain Lorgalis et repose au fond des Profondeurs de Brassenoire, les ruines englouties où vivaient autrefois des elfes morts depuis longtemps avant la chute de leur cité. L'identité de Lorgalis n'a pas été consignée. Le texte consigne des connaissances interdites sur les Très Anciens Dieux et Ceux qui dorment, et loue Aku'mai, un serviteur des Très Anciens Dieux qui réside dans les Profondeurs. Il repose enfermé dans un coffre en fer piqué de rouille dans les salles inondées.",al={"origine du manuscrit de lorgalis","qui a écrit le manuscrit de lorgalis","où le manuscrit de lorgalis a-t-il été fabriqué"}}},fp="19,187,25.525.0,19.394.1,32.172.0,32.139.0,25.164.0,49.155.0"}
P.entries["item:lotwil-s-shackles-of-elemental-binding"] = {n="Lotwil's Shackles of Elemental Binding",s="Lotwil Veriatus a forgé ces entraves pour tenter hardiment d'invoquer un élémentaire dans les Terres Ingrates. Les récupérer est important pour ses travaux.",h="Lotwil Veriatus a forgé ces entraves pour tenter hardiment d'invoquer un élémentaire dans les Terres Ingrates.",kw={"alchimie","terres ingrates","élémentaire","ingénierie","gardien fam'retor","lotwil veriatus","entraves de lotwil","entraves de liaison élémentaire"},sec={{t="Une invocation préparée",b="Dans les Terres Ingrates, Lotwil Veriatus a terminé les entraves pour une expérience remarquable. Il convie Lucien et Servo à assister à son mélange d'alchimie, d'ingénierie et de magie des arcanes. Une fois le lien prêt, Lotwil compte invoquer un puissant élémentaire."},{t="Le résultat",b="Le Gardien Fam'retor abandonne les entraves de Lotwil. Quand vous les lui rapportez, il vous remercie de vous en être chargé et affirme que sa magie a renvoyé la créature chez elle. Quoi qu'il se soit passé, les entraves sont rendues à leur créateur."}},faq={{q="Lotwil's Shackles of Elemental Binding",a="Ce sont des entraves forgées par Lotwil Veriatus pour tenter de lier un puissant élémentaire.",al={"entraves de lotwil","entraves de liaison élémentaire","que sont les entraves"}},{q="Qui a forgé les entraves ?",a="Lotwil Veriatus les a forgées dans le cadre d'une expérience mêlant alchimie, ingénierie et magie des arcanes.",al={"qui les a forgées","qui a forgé les entraves de lotwil","qui est lotwil"}},{q="Où trouver les entraves ?",a="Le Gardien Fam'retor abandonne les entraves de Lotwil dans les Terres Ingrates.",al={"où trouver les entraves","emplacement des entraves","gardien fam'retor"}},{q="Pourquoi Lotwil veut-il récupérer les entraves ?",a="Lotwil doit les récupérer après que sa tentative d'invoquer un puissant élémentaire a mal tourné.",al={"pourquoi rapporter les entraves","que veut lotwil","entraves pour lotwil"}}},fp="38,130,20.249.0,11.217.1,48.83.0,22.99.0,30.71.1,39.86.1"}
P.entries["item:lunar-fungus"] = {n="Champignon lunaire",s="Dans les grottes de Sombrivage, les druides récoltent le Champignon lunaire pour soigner les cerfs malades. Mélangé à de l’Earthroot et à de l’eau, il renforce un baume curatif.",h="Dans les grottes de Sombrivage, les druides récoltent le Champignon lunaire pour soigner les cerfs malades.",kw={"alanndarian chantenuit","auberdine","soigner un empoisonnement","sombrivage","earthroot","floraison fongique lunaire","champignon lunaire"},ang={["class:Druid"]="En tant que jeune druide, vous recherchez le Champignon lunaire dans les grottes de Sombrivage, au début de votre apprentissage de la magie curative et du soin de la faune empoisonnée.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous aidez à soigner les créatures sylvestres corrompues autour d’Auberdine avec des remèdes locaux tels que le Champignon lunaire."},sec={{t="Propriétés et écologie",b="Le Champignon lunaire pousse sur les Lunar Fungal Blooms, dans les cavernes souterraines de Sombrivage. Le Cercle cénarien apprécie sa capacité à renforcer les remèdes. Mélangé à de l’eau apaisante et à de l’Earthroot commun, il fortifie un baume qui combat les affections débilitantes. Des moonkin territoriaux fréquentent les grottes humides, alors prenez garde en récoltant le champignon."},{t="Une leçon de guérison",b="À Auberdine, Alanndarian Chantenuit demande aux jeunes druides de récolter le Champignon lunaire pendant qu’ils étudient les arts curatifs de la nature. Ils apprennent comment des ingrédients physiques, tels que ce champignon, peuvent contrer les poisons qui touchent les cerfs de la région. En étudiant les remèdes à base de plantes, les initiés se préparent à canaliser des antidotes naturels grâce au métamorphisme et à la puissance spirituelle."}},faq={{q="À quoi sert le Champignon lunaire ?",a="Le Champignon lunaire renforce un baume curatif. Alanndarian Chantenuit le mélange à de l’Earthroot et à de l’eau propre pour soigner les cerfs malades de Sombrivage.",al={"utilité du champignon lunaire","effets du champignon lunaire","pourquoi récolter le champignon lunaire"}},{q="Où pousse le Champignon lunaire ?",a="Le Champignon lunaire pousse sur les Lunar Fungal Blooms, dans les grottes à l’est d’Auberdine, à Sombrivage. Des moonkin irritables partagent ces cavernes et défendent leur territoire contre les intrus.",al={"emplacement du champignon lunaire","où trouver le champignon lunaire","floraisons fongiques lunaires"}},{q="Qui a besoin de ce champignon à Auberdine ?",a="Alanndarian Chantenuit demande aux élèves de la nature de récolter le Champignon lunaire dans le cadre de leur formation. Ce champignon entre dans la composition de remèdes destinés aux animaux forestiers malades.",al={"qui a besoin du champignon lunaire","quête d’herboristerie à auberdine"}},{q="Pourquoi les initiés druides doivent-ils récolter des plantes pour soigner les empoisonnements ?",a="Comprendre le fonctionnement des antidotes physiques est une étape essentielle de la formation druidique. Récolter des plantes telles que le Champignon lunaire et observer comment elles neutralisent les toxines enseigne aux élèves les principes de la guérison, avant qu’ils n’apprennent à purger le poison par la magie spirituelle.",al={"pourquoi les druides récoltent des plantes","formation druidique au soin des empoisonnements"}}},fx={["2a41e7eb"]={q="Qu'est-ce que le Champignon lunaire ?",a="Le Champignon lunaire est un champignon médicinal puissant originaire de Sombrivage. Il prospère à l'intérieur de cavernes sombres à l'est d'Auberdine, récolté à partir de plus grands amas connus sous le nom de fleurs fongiques lunaires. Les druides prisent ce champignon pour sa puissance naturelle, utilisant ses propriétés comme ingrédient essentiel lors du brassage d'onguents alchimiques pour soigner la faune empoisonnée.",al={"quoi est champignon lunaire","info champignon lunaire","à propos champignon lunaire"}}},fp="12,136,22.338.0,19.318.0,30.136.0,29.166.0,38.154.0,68.254.0"}
P.entries["item:lurker-venom"] = {n="Venin de rôdeuse",s="À Loch Modan, les défenseurs nains ont besoin de Venin de rôdeuse pour contrer le sabotage des Sombrefer. Les araignées prédatrices des collines rocheuses et des bois fournissent cette toxine.",h="À Loch Modan, les défenseurs nains ont besoin de Venin de rôdeuse pour contrer le sabotage des Sombrefer.",kw={"chief engineer hinderweir","cliff lurker","loch modan","venin de rôdeuse","shanda the spinner","venin d’araignée","barrage de formepierre","wood lurker"},ang={["profession:Engineering"]="L’emploi de toxines organiques pour neutraliser des explosifs ennemis montre comment les ingénieurs nains improvisent avec des matières réactives au combat.",["race:Dwarf"]="En tant que nain, vous savez que les montagnards et les défenseurs de Loch Modan utilisent les dangers de la faune locale pour protéger les ouvrages vitaux de Khaz Modan contre le clan Sombrefer."},sec={{t="Un réactif volatil",b="Le Venin de rôdeuse aide les nains à désamorcer les explosifs posés par les Sombrefer. Ashlan Rictus-de-pierre, expert en explosifs, a désigné le poison d’araignée comme ingrédient du mélange que prépare Chief Engineer Hinderweir. Le solvant associe le venin à des minéraux rares et aux larmes des crocolisques du loch. Ensemble, ils forment un composé réactif capable de désamorcer des explosifs complexes.\n\nLes araignées rôdeuses vont des communes Wood Lurkers à leur matriarche, Shanda the Spinner. Leurs morsures menacent les voyageurs et les montagnards des collines et des crêtes de Loch Modan."}},faq={{q="D’où vient le Venin de rôdeuse ?",a="Les araignées rôdeuses de Loch Modan fournissent le venin. On trouve parmi elles Cliff Lurkers, Forest Lurkers, Wood Lurkers et leur matriarche, Shanda the Spinner.",al={"comment obtenir du venin de rôdeuse","qui donne du venin de rôdeuse","où trouver du venin de rôdeuse"}},{q="À quoi sert le Venin de rôdeuse ?",a="Chief Engineer Hinderweir utilise le venin dans un mélange chimique pour neutraliser et désamorcer les explosifs posés par les infiltrateurs Sombrefer autour du Barrage de Formepierre.",al={"pourquoi ai-je besoin de venin de rôdeuse","utilité du venin de rôdeuse","que fait hinderweir avec le venin"}},{q="Pourquoi utiliser du venin pour désamorcer un explosif ?",a="Les ingénieurs nains utilisent des mélanges réactifs, acides ou caustiques pour dissoudre de délicates pièces mécaniques ou neutraliser des poudres explosives instables sans les faire détoner.",al={"pourquoi du poison d’araignée pour les bombes","comment le venin arrête les bombes sombrefer"}},{q="Shanda the Spinner est-elle la seule source ?",a="Shanda the Spinner porte ce venin, mais les araignées rôdeuses sauvages communes des bois et des falaises rocheuses de Loch Modan peuvent aussi en fournir.",al={"dois-je tuer shanda","shanda venin de rôdeuse"}}},fx={["0e11e6d3"]={q="Qu'est-ce que le Venin de rôdeuse ?",a="Le Venin de rôdeuse est une toxine naturelle puissante récoltée sur les araignées rôdeuses prédatrices originaires de la nature sauvage et accidentée du Loch Modan. Bien qu'il soit mortel pour les proies, ses propriétés chimiques distinctes le rendent précieux pour les artisans spécialisés et les ingénieurs. L'ingénieur en chef Hinderweir utilise spécifiquement ce fluide volatil comme réactif crucial dans un solvant neutralisant alchimique conçu pour désamorcer en toute sécurité les explosifs des nains Sombrefer.",al={"quoi est venin de rôdeuse","lore venin de rôdeuse","quel genre d'objet est venin de rôdeuse"}}},fp="12,147,18.533.0,34.147.0,30.160.0,37.163.0,38.133.0"}
P.entries["item:lydon-s-toxin"] = {n="Toxine de Lydon",s="À Moulin-de-Tarren, l’Apothicaire Lydon a créé une toxine pour perturber l’exploitation forestière de la KapitalRisk dans les Serres-Rocheuses. Des aventuriers de la Horde la transportent jusqu’à Apothecary Zamah, à Pitons-du-Tonnerre, qui doit trouver un moyen de la répandre.",h="À Moulin-de-Tarren, l’Apothicaire Lydon a créé une toxine pour perturber l’exploitation forestière de la...",kw={"apothicaire lydon","apothecary zamah","toxine de lydon","société royale des apothicaires","pitons-du-tonnerre","brouillard toxique","kapitalrisk"},ang={["race:Tauren"]="Les Tauren accueillent favorablement l’aide contre la destruction de la nature par la KapitalRisk. Pourtant, les méthodes chimiques de la Société royale des apothicaires mettent à l’épreuve leurs sensibilités chamaniques.",["race:Undead"]="Le transport de la Toxine de Lydon montre jusqu’où s’étend le réseau de la Société royale des apothicaires. Celle-ci coordonne les recherches sur le terrain entre Lordaeron et Kalimdor, montrant l’utilité des Réprouvés pour leurs alliés."},sec={{t="Une solution royale d’apothicaire",b="L’Apothicaire Lydon a créé sa toxine dans les Contreforts de Hautebrande, à un continent des bûcherons qu’elle vise. Selon lui, elle tue au contact et peut passer d’une cible à l’autre.\n\nAvant d’atteindre les gobelins près de la Combe des Cisailles, le mélange doit traverser des continents jusqu’à Pitons-du-Tonnerre. Là, Apothecary Zamah, représentante de la Société royale des apothicaires, a besoin de la toxine brute pour concevoir un dispositif de dispersion à grande échelle appelé Brouillard toxique."}},faq={{q="À quoi sert la Toxine de Lydon ?",a="L’Apothicaire Lydon a créé cette toxine pour perturber les activités de la KapitalRisk autour de la Combe des Cisailles. Elle tue au contact et peut se propager parmi les ouvriers gobelins.",al={"utilité de la toxine de lydon","effets de la toxine","pourquoi créer la toxine de lydon"}},{q="Qui est l’Apothicaire Lydon ?",a="L’Apothicaire Lydon est membre de la Société royale des apothicaires et travaille à Moulin-de-Tarren, dans les Contreforts de Hautebrande. Il fabrique des poisons virulents et des composés expérimentaux pour servir les desseins des Réprouvés.",al={"qui est lydon","apothicaire lydon","créateur de la toxine de lydon"}},{q="Pourquoi la toxine doit-elle être transportée à Pitons-du-Tonnerre ?",a="Apothecary Zamah, à Pitons-du-Tonnerre, a besoin de la toxine parce qu’on ne peut pas encore la répandre largement. Elle étudie la flore régionale et coordonne les efforts de la Société en Kalimdor. Elle transforme le mélange en un appareil de fumigation portable.",al={"pourquoi pitons-du-tonnerre","pourquoi apporter la toxine à zamah","rôle d’apothecary zamah"}},{q="Que se passe-t-il après que Zamah a reçu la toxine ?",a="Apothecary Zamah transforme la toxine en un dispositif aérosol pressurisé appelé Brouillard toxique. Un agent peut s’en servir pour répandre la toxine dans le campement de la KapitalRisk.",al={"création du brouillard toxique","que fait zamah de la toxine"}}},fx={["73882111"]={q="Qu'est-ce que la Toxine de Lydon ?",a="La Toxine de Lydon est une concoction alchimique virulente formulée par l'Apothicaire Lydon de la Société royale des apothicaires. Conçue spécifiquement pour être utilisée contre la KapitalRisk dirigée par des gobelins, la substance est destinée à produire des résultats dévastateurs et potentiellement contagieux lorsqu'elle est déployée contre les rangs ennemis.",al={"quoi est toxine de lydon","toxine de lydon","à propos toxine de lydon"}},["105322cc"]={q="Pourquoi quelqu'un veut-il la Toxine de Lydon ?",a="Les apothicaires Réprouvés et leurs alliés de la Horde veulent la toxine pour éradiquer les agents envahissants de la KapitalRisk. L'Apothecary Zamah a besoin du mélange de Lydon pour pouvoir construire un mécanisme de distribution efficace, permettant à la Horde de disperser ses effets mortels et contagieux sur les chantiers ennemis.",al={"pourquoi vouloir toxine de lydon","pourquoi la toxine est nécessaire","but toxine de lydon"}}},fp="13,212,27.420.0,31.148.0,24.179.0,47.216.0,44.177.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="Viande séchée de MacGrann",s="À Dun Morogh, Old Icebeard a emporté la viande d’hiver de Tundra MacGrann.",h="À Dun Morogh, Old Icebeard a emporté la viande d’hiver de Tundra MacGrann.",kw={"vallée de la bise","dun morogh","viande séchée de macgrann","casier à viande","old icebeard","tundra macgrann"},ang={["profession:Cooking"]="En tant que cuisinier, vous pouvez saler et faire sécher le gibier pour conserver la viande malgré le froid glacial de Dun Morogh. Des chasseurs comme MacGrann comptent sur ces provisions pour passer l’hiver.",["race:Dwarf"]="En tant que nain, vous savez que la préparation est une question de survie dans les hauts sommets. Perdre une cache d’hiver peut faire la différence entre la vie et la mort."},sec={{t="Une cache d’hiver",b="Tundra MacGrann chassait le gibier et le salait pour l’hiver. Il avait rangé plusieurs semaines de provisions dans un coffre solide, à l’intérieur d’un casier à viande en thorium, pour protéger sa propriété des ours charognards et des prédateurs rôdeurs. Pourtant, il ne s’attendait pas à ce qu’un intrus assez puissant emporte le coffre tout entier."},{t="Dans l’antre du yéti",b="Old Icebeard a pillé le campement de MacGrann pendant que le nain traquait le cerf. Le yéti a traîné le lourd coffre jusqu’à son antre, dans la Vallée de la bise. Son blindage massif en thorium tient bon, mais la jambe blessée de MacGrann l’empêche de se lancer rapidement dans la caverne pour le récupérer. Sans aide pour retrouver sa cache avant l’hiver, le chasseur isolé risque de mourir de faim dans les neiges de la montagne."}},faq={{q="Que sont les Viandes séchées de MacGrann ?",a="Tundra MacGrann a salé et conservé un mois de provisions pour traverser l’hiver à Dun Morogh.",al={"que sont les viandes séchées de macgrann","viande de tundra","réserve de viande de macgrann"}},{q="Pourquoi les viandes étaient-elles enfermées dans un coffre ?",a="Les prédateurs affamés de Dun Morogh, notamment les ours des montagnes, risquaient de déchirer la viande séchée. MacGrann a enfermé ses provisions d’hiver dans un casier à viande renforcé en thorium pour les tenir à l’écart.",al={"pourquoi enfermer la viande","pourquoi un casier en thorium","coffre de macgrann"}},{q="Qui a volé le casier à viande ?",a="Old Icebeard a volé le casier tout entier pendant que MacGrann était parti chasser le cerf, puis l’a traîné jusqu’à son antre, dans la Vallée de la bise.",al={"qui a pris la viande","qui l’a volée","voleur du casier à viande"}},{q="Pourquoi Tundra MacGrann ne peut-il pas récupérer ses viandes lui-même ?",a="Sa jambe est blessée. Il ne peut donc pas entrer dans la caverne d’Old Icebeard et en ressortir le coffre lui-même.",al={"pourquoi macgrann ne la récupère-t-il pas","pourquoi tundra a-t-il besoin d’aide","tundra blessé"}}},fx={["1f8f3b04"]={q="D'où vient la Viande séchée de MacGrann et qui l'a préparée ?",a="Cette viande séchée a été préparée et salée par Tundra MacGrann, un alpiniste vivant dans la nature sauvage et glaciale de Dun Morogh. Il a préparé des rations pour tout un mois afin de survivre à la rude saison hivernale à venir, en les stockant soigneusement dans un coffre en thorium avant que la bête locale, Vieux Barbe-de-glace, n'intervienne.",al={"qui a fabriqué la viande séchée de macgrann","d'où vient la viande séchée","origine de la viande de macgrann"}},["6a0307bf"]={q="Pourquoi Tundra MacGrann veut-il récupérer sa viande séchée ?",a="Sans ces provisions, Tundra MacGrann risque de mourir de faim lorsque les violentes tempêtes de neige balayeront Dun Morogh. Cela représente un mois entier de rations salées. Comme une blessure à la jambe l'empêche d'affronter l'antre de Vieux Barbe-de-glace pour les récupérer, retrouver cette viande est vital pour sa survie durant l'hiver à venir.",al={"pourquoi tundra veut la viande","pourquoi récupérer la viande séchée","pourquoi la viande de macgrann est nécessaire"}}},fp="22,76,14.284.0,20.360.0,32.102.0,37.177.0,26.124.0,53.94.0"}
P.entries["item:mackreel-s-moonshine"] = {n="Tord-boyaux de MacKreel",s="Sur le Viaduc de Thandol brisé, Foggy MacKreel prépare un tord-boyaux assez fort pour terrasser une sentinelle. Le Brasseur Sentine, à Austrivage, reçoit une fournée pour régler la dette de Foggy.",h="Sur le Viaduc de Thandol brisé, Foggy MacKreel prépare un tord-boyaux assez fort pour terrasser une...",kw={"brasseur sentine","bière naine","foggy mackreel","tord-boyaux de mackreel","tord-boyaux","austrivage","les paluns"},ang={["profession:Cooking"]="En tant que cuisinier, vous savez que les alcools régionaux puissants comme le tord-boyaux âpre de Foggy sont des marchandises courantes dans les tavernes des régions frontalières.",["race:Dwarf"]="En tant que nain, vous savez reconnaître un bon alcool fort à son odeur. Le tord-boyaux de Foggy a assez de punch pour terrasser un montagnard."},sec={{t="Un breuvage puissant",b="Foggy MacKreel prépare du tord-boyaux tout en gardant le Viaduc de Thandol. Même des sentinelles naines endurcies peuvent être terrassées après une nuit à en boire. Elles se réveillent avec une migraine qui leur donne l’impression que des engins de siège roulent au-dessus de leur tête. Les voyageurs prisent sa chaleur face au froid humide de Lordaeron et de Khaz Modan."},{t="Règlement à Austrivage",b="Foggy MacKreel devait de l’argent au Brasseur Sentine, tavernier et maître brasseur d’Austrivage. Pour régler son ardoise, il lui a envoyé une fournée de tord-boyaux au lieu de pièces. Le Brasseur Sentine accepte l’alcool en guise d’or et ajoute le puissant breuvage de MacKreel à son stock pour les fraîches journées côtières des Contreforts de Hautebrande."}},faq={{q="Qui prépare le Tord-boyaux de MacKreel ?",a="Foggy MacKreel, une sentinelle naine postée sur le Viaduc de Thandol brisé entre les Paluns et les Hautes-terres Arathies, distille le tord-boyaux.",al={"qui prépare le tord-boyaux de mackreel","qui l’a brassé","alcool de foggy mackreel"}},{q="Pourquoi envoyer ce tord-boyaux à Austrivage ?",a="Foggy MacKreel devait de l’argent au Brasseur Sentine, à Austrivage. Il a accepté de régler sa dette en lui envoyant une nouvelle fournée de tord-boyaux au lieu de pièces.",al={"pourquoi austrivage","livraison de tord-boyaux","dette du brasseur sentine"}},{q="Quelle est la force du Tord-boyaux de MacKreel ?",a="Le Tord-boyaux de MacKreel est exceptionnellement fort. Foggy a avoué s’être évanoui en service après en avoir bu, puis s’être réveillé avec une migraine comme si des engins de siège roulaient sur son crâne.",al={"quelle est sa force","force du tord-boyaux","effets du tord-boyaux de mackreel"}},{q="Pourquoi la livraison doit-elle être faite en urgence ?",a="Foggy a beaucoup bu et a dormi pendant sa garde. À son réveil, il ne lui restait que quelques minutes avant la date limite pour régler sa dette auprès du Brasseur Sentine.",al={"pourquoi un délai","la quête est-elle chronométrée","pourquoi se dépêcher"}}},fx={abca7076={q="Qu'est-ce que le Tord-boyaux de MacKreel ?",a="Le Tord-boyaux de MacKreel est une liqueur artisanale puissante brassée par Foggy MacKreel dans les Paluns. Réputé pour être extrêmement fort, il est assez puissant pour donner ne serait-ce qu'à un robuste Nain une gueule de bois telle qu'il aurait l'impression qu'une brigade de machines de siège lui roule sur la tête. Au-delà de sa force redoutable, il sert de monnaie d'échange précieuse, recherchée jusque dans le nord, dans les contreforts de Hautebrande, pour réchauffer les gens lors des journées fraîches.",al={"qu'est-ce que le tord-boyaux de mackreel","tord-boyaux de mackreel","boisson de foggy mackreel"}}},fp="20,161,13.281.0,21.302.0,31.138.0,47.148.0,35.182.0,40.134.0"}
P.entries["item:maggot-eye-s-paw"] = {n="Patte d'Oeil-de-ver",s="À l'Antre de Garren, la Patte d'Oeil-de-ver confirme l'exécution du chef gnoll. Elle est rapportée à Brill comme preuve qu'il a volé des cadavres pour le Fléau.",h="À l'Antre de Garren, la Patte d'Oeil-de-ver confirme l'exécution du chef gnoll.",kw={"prime","brill","exécuteur zygand","antre de garren","gnoll","oeil-de-ver","patte d'oeil-de-ver","clairières de tirisfal"},ang={["race:Undead"]="En tant que Réprouvé de Brill, rapporter la patte d'Oeil-de-ver revient à frapper les voleurs de corps qui fournissent le détesté Roi-liche."},sec={{t="Preuve de l'exécution",b="Oeil-de-ver pillait les tombes et la campagne près de l'Antre de Garren. Il fournissait les cadavres volés aux armées du Roi-liche. Les Réprouvés l'ont donc condamné à mort et ont affiché une prime à Brill. Les chasseurs doivent rapporter sa patte tranchée en ville pour toucher la prime et clore l'affaire. L'Exécuteur Zygand accepte la patte comme preuve de la mort d'Oeil-de-ver, et non comme une simple rumeur."}},faq={{q="Pourquoi l'Exécuteur Zygand veut-il la patte d'Oeil-de-ver ?",a="L'Exécuteur Zygand veut la patte d'Oeil-de-ver pour prouver que le gnoll condamné a été tué. Brill verse la prime une fois son exécution confirmée.",al={"pourquoi sa patte","preuve de la prime d'oeil-de-ver","patte de zygand"}},{q="Quels crimes Oeil-de-ver a-t-il commis contre les Réprouvés ?",a="Oeil-de-ver menait des raids dans le nord des Clairières de Tirisfal et volait des cadavres enterrés dans des fermes comme l'Antre de Garren. Il fournissait les corps aux armées du Roi-liche.",al={"crimes d'oeil-de-ver","pourquoi oeil-de-ver est-il recherché","qu'a fait oeil-de-ver"}},{q="Où trouve-t-on Oeil-de-ver ?",a="Oeil-de-ver se trouve à l'Antre de Garren, une ferme en ruine au nord de Brill, dans les Clairières de Tirisfal. Il se cache généralement dans la ferme délabrée.",al={"emplacement d'oeil-de-ver","où trouver oeil-de-ver","gnoll de l'antre de garren"}},{q="Pourquoi les gnolls travaillent-ils avec les forces du Roi-liche ?",a="Dans les Clairières de Tirisfal, des bandes de gnolls renégats se sont alliées au Fléau ou sont tombées sous son emprise. Elles pillent les tombes des humains et des Réprouvés, puis livrent les corps aux nécromanciens.",al={"gnolls et fléau","pourquoi les gnolls volent-ils des corps","gnolls du fléau"}}},fx={["9017e45e"]={q="Qu'est-ce que la Patte d'Oeil-de-ver ?",a="Il s'agit de la patte tranchée du célèbre gnoll Oeil-de-ver. La rapporter sert de preuve physique indéniable de l'exécution de la bête pour les autorités de Brill.",al={"qu'est-ce que la patte d'oeil-de-ver","patte d'oeil-de-ver","qu'est-ce que cette patte"}},e496e47e={q="D'où vient la Patte d'Oeil-de-ver et qui l'a fabriquée ?",a="Ce n'est pas un objet fabriqué, mais un trophée découpé directement sur le cadavre d'Oeil-de-ver lui-même, un gnoll traître opérant aux alentours de l'antre de Garren dans les Clairières de Tirisfal.",al={"d'où vient la patte d'oeil-de-ver","origine de la patte d'oeil-de-ver","qui a fabriqué la patte d'oeil-de-ver"}}},fp="16,148,18.356.0,47.139.0,55.167.0,26.138.0,51.166.0"}
P.entries["item:maggran-s-reserve-letter"] = {n="Lettre de réserve de Maggran",s="À la Retraite de Roche-Soleil, Maggran Lieur-de-terre envoie un guerrier relever Grish Long-coureur à la Grande élévation. Les ordres permettent à Grish de rentrer chez lui et de rendre visite à sa famille.",h="À la Retraite de Roche-Soleil, Maggran Lieur-de-terre envoie un guerrier relever Grish Long-coureur à la...",kw={"tarides","lieur-de-terre","grish","lettre","élévation","long-coureur","maggran","réserve","les serres-rocheuses"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez voir comment elle envoie des renforts dans ses avant-postes isolés à travers Kalimdor pour prendre soin de ses troupes dispersées."},sec={{t="Une sentinelle relevée",b="Depuis la Retraite de Roche-Soleil, Maggran Lieur-de-terre envoie ses ordres à la Grande élévation. Grish Long-coureur, une sentinelle de la Horde qui y est postée, doit être relevé par un guerrier de remplacement.\n\nLes treuils en bois de la Grande élévation se dressent loin au sud. Grish y a monté la garde, mais le nouveau guerrier prend maintenant sa place. Grish peut quitter son poste et rentrer chez lui rendre visite à sa famille."}},faq={{q="À quoi sert la Lettre de réserve de Maggran ?",a="Les ordres de Maggran Lieur-de-terre relèvent Grish Long-coureur de son poste à la Grande élévation, dans les Tarides du sud. Un remplaçant prend sa place afin que Grish puisse rentrer chez lui rendre visite à sa famille.",al={"à quoi sert cette lettre","but de la lettre de maggran","pourquoi remettre la lettre"}},{q="Qui a écrit la lettre ?",a="Maggran Lieur-de-terre a écrit la lettre. C'est un ancien de la Retraite de Roche-Soleil, dans les Serres-Rocheuses.",al={"qui l'a écrite","auteur de la lettre de réserve","maggran lieur-de-terre"}},{q="À qui est-elle destinée ?",a="La lettre est adressée à Grish Long-coureur, un garde de la Horde posté au sommet de la Grande élévation. Celle-ci relie les Tarides du sud à Mille pointes.",al={"qui reçoit la lettre","destinataire de la lettre","où va-t-elle"}},{q="Où la lettre doit-elle être remise ?",a="Portez la lettre vers le sud à travers les Tarides, jusqu'au bord du canyon de Mille pointes, où se dresse la Grande élévation.",al={"lieu de livraison","où se trouve grish","emplacement de la grande élévation"}}},fx={["419ae143"]={q="Qu'est-ce que la Lettre de réserve de Maggran ?",a="Il s'agit d'une dépêche officielle écrite par Maggran Lieur-de-terre à la Retraite de Roche-Soleil dans les Serres-Rocheuses. Le message informe un garde de la Horde en poste, Grish Long-coureur, qu'un guerrier de renfort des réserves est envoyé pour prendre sa place, lui accordant ainsi une permission pour rendre visite à sa famille.",al={"qu'est-ce que la lettre de réserve de maggran","lettre de maggran","lettre de réserve"}},eb8a36e5={q="Pourquoi Grish Long-coureur veut-il la Lettre de réserve de Maggran ?",a="Grish a demandé à être relevé de son poste il y a longtemps et attend des nouvelles avec impatience. Garder la Grande élévation dans les Tarides du sud est une tâche monotone, et cette lettre autorise officiellement son remplacement par un guerrier de réserve, lui accordant enfin le temps tant attendu pour rendre visite à sa famille.",al={"pourquoi grish veut la lettre","pourquoi la lettre de réserve est voulue","pourquoi avoir besoin de la lettre de réserve de maggran"}}},fp="24,172,17.346.0,48.187.0,21.101.0,27.158.0,30.114.0"}
P.entries["item:magma-core-classic"] = {n="Coeur de magma",s="Le Cœur de magma est le cœur de Magma Lord Bokk, un élémentaire des Steppes Ardentes. Mux Brouillemana a besoin de sa chaleur constante pour alimenter un révélateur de fantômes extradimensionnel.",h="Le Cœur de magma est le cœur de Magma Lord Bokk, un élémentaire des Steppes Ardentes.",kw={"bokk","steppes ardentes","ectoplasme","gadgetzan","révélateur de fantômes","coeur de magma","magma lord bokk","mux brouillemana","source d’énergie portable"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous comprendrez peut-être pourquoi Mux veut une source d’énergie portable : il compte utiliser le Cœur de magma pour alimenter un révélateur de fantômes extradimensionnel."},sec={{t="Un cœur ardent",b="Magma Lord Bokk vit dans les Steppes Ardentes, au sud du Mont Rochenoire. Son Cœur de magma renferme une source inépuisable de chaleur. Mux Brouillemana, à Gadgetzan, le convoite pour maintenir l’ectoplasme actif et alimenter un révélateur de fantômes extradimensionnel."}},faq={{q="Qu’est-ce que le Cœur de magma ?",a="Le Cœur de magma est le cœur de Magma Lord Bokk, un puissant élémentaire des Steppes Ardentes. Il renferme une grande quantité de chaleur.",al={"coeur de magma","cœur de bokk"}},{q="Qui veut le Cœur de magma ?",a="Mux Brouillemana, à Gadgetzan, veut le Cœur de magma pour alimenter un révélateur de fantômes extradimensionnel.",al={"qui a besoin du cœur de magma","source d’énergie de mux"}},{q="Où se trouve Magma Lord Bokk ?",a="Magma Lord Bokk se trouve dans les Steppes Ardentes, au sud du Mont Rochenoire.",al={"où se trouve bokk","emplacement de bokk"}},{q="Pourquoi Mux en a-t-il besoin ?",a="Mux a besoin d’une source d’énergie stable et portable pour maintenir l’ectoplasme actif et alimenter son révélateur de fantômes extradimensionnel.",al={"pourquoi le cœur de magma","énergie du révélateur de fantômes"}}},fp="10,170,15.235.0,23.126.0,25.97.0,25.81.0,21.118.0"}
P.entries["item:maiden-s-folly-charts"] = {n="Maiden's Folly Charts",s="Les cartes du Maiden's Folly sont des documents de navigation retrouvés dans une épave des Hautes-terres Arathies. Le Second Nilzlix veut les mettre en sûreté avant le départ des navires de la crique.",h="Les cartes du Maiden's Folly sont des documents de navigation retrouvés dans une épave des Hautes-terres...",kw={"hautes-terres arathies","baie-du-butin","cartes","récupération en haute mer","second nilzlix","maiden's folly","cartes du maiden's folly"},sec={{t="Cartes de l'épave",b="Dans les Hautes-terres Arathies, le Maiden's Folly gît en épave près du Spirit de la Forêt des Pins-Argentés. Leurs cartes et leurs journaux consignent des informations que l'équipage craint de voir tomber aux mains de l'ennemi. Le Second Nilzlix vous demande de récupérer les cartes, y compris celles du Maiden's Folly, et de les rapporter à la Baie-du-Butin."}},faq={{q="Que sont les cartes du Maiden's Folly ?",a="Ce sont des cartes de navigation qui appartenaient au Maiden's Folly, aujourd'hui échoué dans les Hautes-terres Arathies.",al={"cartes du maiden's folly","cartes du folly","quelles cartes"}},{q="Où puis-je trouver les cartes ?",a="Le Maiden's Folly gît en épave dans une crique des Hautes-terres Arathies.",al={"où sont les cartes","trouver les cartes du folly","emplacement des cartes"}},{q="Qui veut récupérer les cartes ?",a="Le Second Nilzlix vous demande de récupérer les cartes du Maiden's Folly ainsi que les autres documents des navires.",al={"qui les veut","cartes de nilzlix","second"}},{q="Pourquoi faut-il mettre les cartes en sûreté ?",a="L'équipage craint que les cartes et les journaux tombent aux mains de l'ennemi, et l'Amiral Corne-de-mer les tiendrait pour responsables.",al={"pourquoi récupérer les cartes","mains de l'ennemi","importance des cartes"}},{q="Où seront envoyées les cartes ?",a="Les cartes récupérées sont destinées au commandement de la Baie-du-Butin.",al={"où rapporter les cartes","cartes de la baie-du-butin","destination des cartes"}}},fp="21,165,21.292.0,35.102.0,28.66.0,31.94.0,31.117.0,25.60.0"}
P.entries["item:maiden-s-folly-log"] = {n="Maiden's Folly Log",s="Le journal du Maiden's Folly vient d'un navire échoué sur le récif d'Arathi. Ses pages et ses cartes contiennent des renseignements que l'Amiral Corne-de-mer veut garder secrets.",h="Le journal du Maiden's Folly vient d'un navire échoué sur le récif d'Arathi.",kw={"arathi","baie-du-butin","journal du capitaine","récupération en haute mer","journal","maiden's folly","nilzlix","récif","corne-de-mer","temple"},sec={{t="Le journal d'une épave",b="Le Second Nilzlix recherche le journal du Maiden's Folly, échoué avec le Spirit de la Forêt des Pins-Argentés. Les navires se sont échoués sur un temple du récif après le début de la marée descendante, puis ont rapidement sombré. Leurs registres sont importants pour le commandement de Baie-du-Butin, qui craint que ces renseignements ne tombent aux mains de l'ennemi."}},faq={{q="Qu'est-ce que le journal du Maiden's Folly ?",a="C'est le journal du capitaine du Maiden's Folly, l'un des navires échoués sur le récif d'Arathi.",al={"journal du maiden's folly","journal du capitaine","journal de bord"}},{q="Où le Maiden's Folly a-t-il sombré ?",a="Le Maiden's Folly s'est échoué sur un temple du récif d'Arathi, puis a sombré.",al={"où se trouve l'épave","emplacement du maiden's folly","épave de navire à arathi"}},{q="Pourquoi le Second Nilzlix veut-il le journal ?",a="Le Second Nilzlix veut récupérer le journal et les cartes du Maiden's Folly avant que leurs renseignements ne tombent aux mains de l'ennemi.",al={"pourquoi récupérer le journal","que veut nilzlix","pourquoi récupérer le livre"}},{q="Qu'est-il arrivé au Maiden's Folly ?",a="La marée a commencé à descendre alors que le Maiden's Folly approchait d'une crique. Le navire s'est échoué sur un temple du récif, puis a sombré.",al={"épave du maiden's folly","comment a-t-il sombré","qu'est-il arrivé au navire"}},{q="Qui veut protéger les registres ?",a="Le commandement de l'Amiral Corne-de-mer à Baie-du-Butin veut garder les journaux et les cartes à l'abri des regards indiscrets.",al={"qui veut les cartes","amiral corne-de-mer","registres de baie-du-butin"}}},fp="18,172,16.292.0,31.91.0,34.67.0,41.119.0,36.122.0,32.92.0"}
P.entries["item:malem-pendant"] = {n="Pendentif de Malem",s="Le Pendentif de Malem se trouve dans un chariot en Désolace. Vahlarriel Demonslayer, à Nijel’s Point, en a besoin ainsi que des nouvelles des traces vers le sud.",h="Le Pendentif de Malem se trouve dans un chariot en Désolace.",kw={"désolace","empreintes","fort","malem","pendentif de malem","combe de nijel","vahlarriel demonslayer","chariot"},sec={{t="Un signe dans le chariot",b="Des empreintes partent vers le sud depuis le chariot où vous trouvez le Pendentif de Malem. De la fumée s’élève d’un fort proche, et son feu constant laisse penser que des gens s’y trouvent. Vahlarriel Demonslayer, à Nijel’s Point, a besoin de voir le pendentif et d’entendre ce que vous avez découvert."}},faq={{q="Où apporter le Pendentif de Malem ?",a="Apportez le Pendentif de Malem à Vahlarriel Demonslayer, à Nijel’s Point, en Désolace.",al={"où apporter le pendentif","remettre le pendentif","où trouver le pendentif de malem"}},{q="Où le pendentif a-t-il été trouvé ?",a="Vous trouvez le Pendentif de Malem dans un chariot en Désolace.",al={"où se trouve le pendentif","emplacement du pendentif","trouver le pendentif de malem"}},{q="Quels indices se trouvaient près du pendentif ?",a="Des empreintes partent vers le sud depuis le chariot, et de la fumée s’élève d’un fort proche.",al={"traces et fumée","quels indices","indices près du chariot"}},{q="Pourquoi Vahlarriel doit-il être informé au sujet du fort ?",a="Vahlarriel recherche les Malems, et les traces ainsi que la fumée laissent penser qu’ils ont peut-être été emmenés vers le fort.",al={"pourquoi informer vahlarriel","nouvelles du fort","de quoi vahlarriel a-t-il besoin"}}},fp="13,143,19.241.0,34.80.0,28.50.0,33.73.0,48.114.1"}
P.entries["item:mangy-claw"] = {n="Griffe galeuse",s="À Dun Morogh, la Griffe galeuse marque la fin d’une chasse mortelle. Le grand ours des glaces Mangeclaw a tué un pilote nain isolé, et sa serre arrachée prouve que la bête a été abattue.",h="À Dun Morogh, la Griffe galeuse marque la fin d’une chasse mortelle.",kw={"dun morogh","hildelve","ours des glaces","mangeclaw","griffe galeuse","pilote martèlepied","brigade des sapeurs"},ang={["class:Hunter"]="En tant que chasseur, traquer Mangeclaw dans les violentes tempêtes de neige des montagnes de Dun Morogh met votre talent à l’épreuve face à des bêtes dangereuses et territoriales.",["race:Dwarf"]="En tant que nain, exaucer le dernier vœu d’un compagnon tombé au combat et venger un membre de la Brigade des sapeurs de Forgefer sont des actes qui touchent à l’honneur personnel et clanique."},sec={{t="Le vœu d’un pilote mourant",b="Le char à vapeur du pilote Hildelve est tombé en panne dans les collines gelées de Dun Morogh. Il est parti chercher du minerai à pied et s’est retrouvé seul face à la nature sauvage de la montagne. Dans son journal, il raconte comment il a repoussé Mangeclaw, un ours des glaces, mais a été sauvagement mutilé. L’ours est revenu et a tué le pilote affaibli. Dans sa dernière entrée, Hildelve implorait qu’on le venge. Prendre la Griffe galeuse sur la dépouille de l’ours exauce son vœu."},{t="Venger la brigade des sapeurs",b="Le Pilote Martèlepied a envoyé des équipes dans les congères, espérant retrouver son ami Hildelve vivant. Le journal d’Hildelve et la Griffe galeuse révèlent qu’il est mort et que son dernier vœu a été exaucé. Les apporter à Martèlepied permet à la Brigade des sapeurs de Forgefer de faire son deuil et vaut la gratitude des pilotes de Forgefer."}},faq={{q="Qu’est-ce que la Griffe galeuse ?",a="La Griffe galeuse est la serre arrachée de Mangeclaw, un ours des glaces féroce de Dun Morogh. Elle prouve que la bête a été traquée et tuée.",al={"utilité de la griffe galeuse","qu’est-ce que cette griffe","objet mangeclaw"}},{q="Qui veut la Griffe galeuse ?",a="Le Pilote Martèlepied veut la Griffe galeuse et le journal de son ami Hildelve, tombé au combat. Ils confirment que l’ours meurtrier est mort. Martèlepied est posté près des cols montagneux de Dun Morogh.",al={"qui prend la griffe galeuse","où remettre la griffe galeuse","remettre à la pilote martèlepied"}},{q="Pourquoi fallait-il chasser Mangeclaw ?",a="Mangeclaw a mutilé puis fini par tuer Hildelve, un pilote nain parti chercher du minerai à pied après la panne de son char à vapeur. Dans son journal, Hildelve consigne son dernier vœu : que quelqu’un le venge.",al={"pourquoi tuer mangeclaw","qui a été tué par mangeclaw","histoire de hildelve"}},{q="Où rôde la bête Mangeclaw ?",a="Mangeclaw rôde sur les crêtes enneigées et dans les collines de Dun Morogh, près de l’endroit où les restes du Pilote Hildelve ont été retrouvés.",al={"emplacement de mangeclaw","où trouver mangeclaw","mangeclaw à dun morogh"}}},fx={["554d85fa"]={q="D'où vient la Griffe galeuse ?",a="La Griffe galeuse est prélevée directement sur Mangeclaw, un ours à griffes de glace sauvage qui rôde dans la nature glacée de Dun Morogh. Ce n'est pas un artefact fabriqué, mais un trophée physique macabre découpé sur la bête après l'avoir abattue.",al={"source de la griffe galeuse","où trouver la griffe galeuse","qui possède la griffe galeuse"}}},fp="10,173,20.396.0,31.302.1,23.125.0,25.184.0,36.192.0,36.105.0"}
P.entries["item:maraudine-key-fragment"] = {n="Maraudine Key Fragment",s="Le Maraudine Key Fragment est détenu par Khan Hratha en Désolace. Les Gelkis et les Magram le convoitent dans leur lutte contre les Maraudine.",h="Le Maraudine Key Fragment est détenu par Khan Hratha en Désolace.",kw={"gelkis","khan hratha","magram","maraudine","maraudine key fragment","uthek la sage","vallée des lances","warug"},sec={{t="Un morceau de clé",b="Khan Hratha porte le Maraudine Key Fragment dans la Vallée des Lances. Après sa mort, les Gelkis le réclament, tout comme les Magram. Chaque clan convoite le fragment dans sa lutte contre les Maraudine."}},faq={{q="Qui détient le Maraudine Key Fragment ?",a="Khan Hratha détient le Maraudine Key Fragment dans la Vallée des Lances.",al={"qui détient le fragment","morceau de clé hratha","fragment maraudine"}},{q="Qui veut le fragment ?",a="Uthek la Sage réclame le fragment au Village des Gelkis, tandis que Warug le réclame au Village des Magram.",al={"qui veut la clé","gelkis ou magram","où apporter le fragment"}},{q="Pourquoi les Gelkis le veulent-ils ?",a="Les Gelkis vous demandent de leur apporter le fragment après la mort de Khan Hratha.",al={"gelkis veulent fragment","morceau de clé uthek","pourquoi les gelkis veulent la clé"}},{q="Pourquoi les Magram le veulent-ils ?",a="Les Magram vous demandent de leur apporter le fragment après la mort de Khan Hratha.",al={"magram veulent fragment","morceau de clé warug","pourquoi les magram veulent la clé"}}},fp="22,133,16.225.0,35.69.0,23.98.0,26.73.1,26.68.1"}
P.entries["item:margol-s-gigantic-horn"] = {n="Margol's Gigantic Horn",s="Margol’s Gigantic Horn est un trophée cabossé de la Gorge des Vents brûlants. La Montagnarde Pebblebitty en a besoin avant d’envisager d’ouvrir le Passage de Formepierre.",h="Margol’s Gigantic Horn est un trophée cabossé de la Gorge des Vents brûlants.",kw={"tête de hache brisée","loch modan","margol","margol the rager","margol’s gigantic horn","montagnarde pebblebitty","gorge des vents brûlants","passage de formepierre"},sec={{t="Un trophée grossier",b="Dans la Gorge des Vents brûlants, Margol’s Gigantic Horn est une trouvaille curieuse pour quiconque cherche un passage à travers le Passage de Formepierre. Des éraflures et des fissures marquent sa surface rugueuse, où est fiché un étrange morceau de métal. La Montagnarde Pebblebitty est celle qui veut voir la corne."}},faq={{q="Qui veut la corne de Margol ?",a="La Montagnarde Pebblebitty veut voir Margol’s Gigantic Horn. Elle se trouve au passage entre Loch Modan et la Gorge des Vents brûlants.",al={"qui la veut","corne de pebblebitty","où apporter la corne"}},{q="Où puis-je trouver la corne ?",a="Margol’s Gigantic Horn vient de Margol the Rager, dans la Gorge des Vents brûlants.",al={"emplacement de la corne","trouver la corne de margol","où est la corne"}},{q="Pourquoi Pebblebitty a-t-elle besoin de la corne ?",a="Pebblebitty demande à voir Margol’s Gigantic Horn avant d’envisager d’ouvrir le Passage de Formepierre entre Loch Modan et la Gorge des Vents brûlants.",al={"pourquoi pebblebitty la veut","à quoi sert la corne","pourquoi apporter la corne"}},{q="Qu’est-ce qui est fiché dans la corne ?",a="Une tête de hache brisée est fichée dans la surface rugueuse. Les mots « Propriété de la Montagnarde Pebblebitty » sont gravés sur le métal.",al={"métal dans la corne","qu’est-ce qui y est fiché","tête de hache"}},{q="Pourquoi Pebblebitty dit-elle que c’est une fausse ?",a="Pebblebitty insiste sur le fait que la corne est trop petite pour appartenir à Margol, affirmant que celle de Margol est au moins huit fois plus grande.",al={"fausse corne","pebblebitty dit que c’est faux","est-elle authentique"}}},fp="22,149,14.266.0,26.118.0,26.70.0,35.136.0,27.118.1,34.116.1"}
P.entries["item:marshal-haggard-s-badge"] = {n="Plaque du maréchal Haggard",s="Dans les collines de la Forêt d’Elwynn, le maréchal Haggard vit retiré du service de Hurlevent. Dead-tooth Jack l’a trompé et lui a fait remettre son ancienne plaque, que les défias pourraient utiliser pour se faire passer pour des officiers de la cité.",h="Dans les collines de la Forêt d’Elwynn, le maréchal Haggard vit retiré du service de Hurlevent.",kw={"dead-tooth jack","défias","forêt d’elwynn","maréchal dughan","marshal haggard","plaque du maréchal haggard","hurlevent","coffre-fort"},ang={["class:Warrior"]="En tant que guerrier, récupérer la plaque de Haggard prouve votre valeur à un vétéran de l’armée de Hurlevent. Il récompense les guerriers prometteurs avec des armes de surplus bien entretenues, issues de ses années de combat.",["faction:Alliance"]="En tant que membre de l’Alliance, récupérer la plaque protège le commandement militaire de Hurlevent et empêche la Confrérie défias de saper les défenses locales de l’intérieur."},sec={{t="Un insigne dérobé",b="Une nuit, Dead-tooth Jack s’est présenté à la ferme de Haggard vêtu d’un tabard de Hurlevent. Le voleur défias s’est fait passer pour le maréchal Dughan, commandant de la garnison de Comté-de-l’Or, et a prétendu que les anciens pairs de Haggard avaient besoin de l’insigne pour une affaire officielle.\n\nLe vieux maréchal le lui a remis sans méfiance. Jack s’est enfui dans les bois avant que Haggard ne comprenne la supercherie. Entre les mains des défias, la plaque conserve toute l’autorité des maréchaux de Hurlevent. Des hors-la-loi pourraient s’en servir pour franchir des postes de contrôle ou semer la confusion parmi les patrouilles locales."}},faq={{q="Qu’est-ce que la Plaque du maréchal Haggard ?",a="Le maréchal Haggard portait la plaque pour marquer son rang lorsqu’il servait le royaume de Hurlevent. Bien qu’il soit à la retraite, la plaque conserve une véritable autorité.",al={"plaque de haggard","plaque du maréchal"}},{q="Comment Dead-tooth Jack a-t-il obtenu la plaque ?",a="Dead-tooth Jack s’est présenté de nuit chez le maréchal Haggard, vêtu d’un tabard de Hurlevent. Haggard l’a pris pour le maréchal Dughan de Comté-de-l’Or et lui a remis la plaque à sa demande.",al={"comment la plaque a été volée","qui a volé la plaque","ruse de dead-tooth jack"}},{q="Pourquoi la plaque est-elle dangereuse entre les mains des défias ?",a="Un agent défias muni de la véritable plaque et d’un déguisement pourrait se faire passer pour un haut responsable de Hurlevent. Il pourrait contourner les sentinelles, pénétrer dans des garnisons ou donner de faux ordres aux gardes des villes.",al={"pourquoi jack veut la plaque","usage de la plaque par les défias","danger de la plaque"}},{q="Où la plaque est-elle gardée ?",a="Dead-tooth Jack a enfermé la plaque dans son coffre-fort, à son campement au sud de la ferme du maréchal Haggard, dans la Forêt d’Elwynn.",al={"emplacement de la plaque","où trouver la plaque","coffre-fort de dead-tooth jack"}}},fp="23,205,17.489.0,32.160.0,38.185.0,54.192.0,24.115.0"}
P.entries["item:mary-s-looking-glass"] = {n="Miroir de Marie",s="Dans le Bois de la Pénombre, le miroir abandonné de Marie passe d’une goule à un astronome.",h="Dans le Bois de la Pénombre, le miroir abandonné de Marie passe d’une goule à un astronome.",kw={"marie l'aveugle","sombre-comté","bois de la pénombre","goule folle","look to the stars","miroir","miroir de marie","cimetière des jardins paisibles","viktori prism'antras"},ang={["faction:Alliance"]="Récupérer des reliques aux mains des horreurs du Cimetière des jardins paisibles aide les citoyens tourmentés de Sombre-Comté à tourner la page et contribue aux projets de la ville.",["profession:Engineering"]="Les ingénieurs apprécieront la façon dont Viktori réutilise un antique miroir domestique comme réflecteur optique dans un appareil d’observation des étoiles."},sec={{t="Un trésor des Réprouvés",b="Marie l'aveugle chérissait autrefois ce miroir poli. Après sa mort et la perte de ses yeux, son reflet lui rappelait cruellement ce qu’elle avait perdu. Elle jeta le miroir derrière sa grange. La pénombre du Bois de la Pénombre l’enveloppa jusqu’à ce qu’une Goule folle le trouve parmi les faubourgs en ruine et l’emporte vers le sud, dans les cryptes du Cimetière des jardins paisibles."},{t="Les yeux vers le ciel",b="À Sombre-Comté, l’astronome Viktori Prism'Antras rêve de percer le crépuscule éternel du Bois de la Pénombre pour contempler le ciel dégagé. Son télescope nécessite des lentilles optiques spéciales et du verre réfléchissant. Marie envoie des aventuriers à la chapelle en ruine du cimetière, où des morts-vivants sauvages détiennent son miroir. Viktori en a besoin comme réflecteur dans son appareil d’observation des étoiles."}},faq={{q="Pourquoi Marie a-t-elle jeté le miroir ?",a="Le miroir était autrefois l’un des plus beaux trésors de Marie, mais elle le jeta derrière la grange après un incident qu’elle ne décrit pas entièrement. Lors d’une autre rencontre, elle explique s’être arraché les yeux, car elle ne supportait pas son apparence.",al={"pourquoi marie l’a jeté","pourquoi jeter le miroir","histoire du miroir de marie l’aveugle"}},{q="Qui a récupéré le miroir après que Marie l’a jeté ?",a="Une Goule folle qui rôdait dans les bois derrière l’ancienne ferme de Marie a récupéré le miroir abandonné. La créature morte-vivante a fini par s’installer dans la chapelle abandonnée du Cimetière des jardins paisibles.",al={"qui a le miroir","qui a récupéré le miroir","où se trouve le miroir"}},{q="Pourquoi Viktori Prism'Antras veut-il le miroir de Marie ?",a="Viktori construit un télescope complexe pour percer la pénombre du Bois de la Pénombre et étudier les étoiles. Il lui faut une surface réfléchissante de qualité pour diriger la lumière à travers l’appareil, et le miroir de Marie convient à son projet.",al={"pourquoi viktori a besoin du miroir","usage du miroir par viktori","miroir de télescope"}},{q="Où trouver la Goule folle qui détient le miroir ?",a="La Goule folle rôde à l’extrême sud-est du Bois de la Pénombre, dans la chapelle de pierre en ruine du Cimetière des jardins paisibles.",al={"emplacement de la goule folle","où se trouve la goule folle","goule du cimetière des jardins paisibles"}}},fx={afb2ba8d={q="Qu'est-ce que le Miroir de Marie ?",a="Le Miroir de Marie est un miroir à main réfléchissant qui appartenait autrefois à Marie l'aveugle avant qu'une tragédie ne la frappe. Considéré par Marie comme l'un de ses plus beaux trésors personnels, elle a fini par le jeter derrière sa grange à la suite d'un incident terrifiant. Il est tombé plus tard entre les griffes d'une goule morte-vivante errante dans le Bois de la Pénombre.",al={"qu'est-ce que le miroir de marie","objet miroir de marie","miroir de marie l'aveugle"}}},fp="20,79,19.356.0,19.366.0,42.247.0,53.196.0,56.195.0,55.124.0"}
P.entries["item:mathystra-relic"] = {n="Relique de Mathystra",s="Dans le nord de Sombrivage, les antiques reliques de Mathystra portent encore des traces de magie. Le Marteau du crépuscule s'y intéresse.",h="Dans le nord de Sombrivage, les antiques reliques de Mathystra portent encore des traces de magie.",kw={"sombrivage","bosquet des anciens","le glaive du maître","mathystra","relique de mathystra","onu","ruines de mathystra","marteau du crépuscule"},ang={["class:Druid"]="En tant que druide, vous travaillez avec des anciens comme Onu pour protéger l'équilibre de Sombrivage. Vous contribuez à empêcher que la magie oubliée n'aide de sombres invocations.",["race:NightElf"]="En tant que Kaldorei, récupérer ces reliques aide à protéger l'ancienne magie dangereuse du Marteau du crépuscule. C'est aussi rendre hommage à une cité perdue lors de la Fracture."},sec={{t="Vestiges d'un bastion déchu",b="Mathystra se dressait autrefois sur la côte de Kalimdor, cité et bastion de la civilisation elfique. Avant la Grande Fracture, c'était un lieu fier. À présent, des colonnes renversées et des pierres fissurées reposent à demi englouties par les broussailles et la brume marine. Des esprits agités et des bêtes tapies se déplacent parmi elles.\n\nDes reliques de cette époque sont éparpillées dans les ruines. Dix mille ans d'abandon les ont usées, mais elles conservent des traces du savoir-faire arcanique elfique. Entre des mains imprudentes, ces reliques sont dangereuses."},{t="Un péril grandissant",b="Onu, l'ancien du savoir, recherche les reliques de Mathystra. Il a appris que le culte du Marteau du crépuscule tente de transformer en armes des écrits elfiques oubliés trouvés au Glaive du Maître. Le culte veut manier l'ancienne magie kaldorei et hâter le retour de ses sombres maîtres.\n\nOnu et les gardiens de Sombrivage étudient les vestiges éparpillés pour découvrir les intentions du culte. Ils cherchent à empêcher que le pouvoir déclinant de Mathystra ne serve de sombres desseins."}},faq={{q="Que sont les reliques de Mathystra ?",a="Les reliques de Mathystra sont des fragments et des artefacts de l'ancienne cité des elfes de la nuit. Elles portent encore des traces du savoir-faire magique elfique d'avant la Fracture, malgré les milliers d'années écoulées.",al={"relique de mathystra","reliques elfiques de mathystra","que sont ces reliques"}},{q="Où trouve-t-on ces reliques ?",a="Les reliques sont éparpillées parmi les pierres brisées, les piliers renversés et les hautes herbes des Ruines de Mathystra, dans le nord de Sombrivage.",al={"emplacement de la relique de mathystra","où trouver les reliques","emplacements des reliques"}},{q="Qui veut les reliques de Mathystra ?",a="Onu, un ancien du savoir, demande aux voyageurs de rassembler les reliques pour les étudier. Il vit au Bosquet des Anciens, dans le sud de Sombrivage.",al={"qui a besoin des reliques","à qui apporter les reliques","reliques onu"}},{q="Pourquoi le Marteau du crépuscule s'y intéresse-t-il ?",a="Le culte du Marteau du crépuscule étudie d'anciens textes elfiques trouvés au Glaive du Maître. Il cherche à pervertir l'ancienne magie des elfes et à l'utiliser pour invoquer ses maîtres ténébreux dans le monde.",al={"pourquoi le marteau du crépuscule veut les reliques","marteau du crépuscule mathystra"}}},fx={bddb4f1c={q="D'où viennent les Mathystra Relics et qui les a fabriquées ?",a="Ces artefacts proviennent de l'ancienne cité elfe de la nuit de Mathystra, fabriqués il y a longtemps à une époque où le grand bastion rayonnait sur le nord de Sombrivage. Abandonnés après que l'ancienne colonie soit tombée en ruine, ils contiennent encore des fragments persistants de magie elfe.",al={"origine des mathystra relics","qui a fabriqué les mathystra relics","d'où viennent les mathystra relics"}}},fp="15,130,28.460.0,15.426.1,30.195.0,29.128.0,31.132.0,48.180.0"}
P.entries["item:maury-s-clubbed-foot"] = {n="Fléau de Maury",s="Maury “Club Foot” Wilkins fait partie des débiteurs que Sea Wolf MacKinley veut faire payer à Baie-du-Butin. Son pied bot renferme quelque chose que MacKinley croit précieux.",h="Maury “Club Foot” Wilkins fait partie des débiteurs que Sea Wolf MacKinley veut faire payer à Baie-du-Butin.",kw={"baie-du-butin","pied bot","maury","maury wilkins","ruines d'aboraz","sea wolf mackinley","dettes vaudou"},sec={{t="Une dette dans la jungle",b="Parmi les débiteurs que MacKinley nomme, Maury “Club Foot” Wilkins erre dans les ruines de la jungle avec Jon-Jon the Crow et Chucky “Ten Thumbs”. Leurs dettes restent impayées depuis des mois, et MacKinley vous envoie les retrouver aux Ruines d'Aboraz et aux Ruines de Jubuwal. Le pied bot de Maury fait partie des objets de valeur qu'il veut récupérer et rapporter à Baie-du-Butin."},{t="Le prix de MacKinley",b="Quand vous rapportez les trois objets de valeur, MacKinley dit qu'il peut en tirer un bon prix. Il parle de ce qui se trouve dans le pied de Maury, puis prévient que tous trois auraient dû faire attention à ceux avec qui ils jouaient."}},faq={{q="Qui est Maury “Club Foot” Wilkins ?",a="Maury “Club Foot” Wilkins est un débiteur de Sea Wolf MacKinley qui erre dans les ruines de la jungle.",al={"qui est maury","maury pied bot","maury wilkins"}},{q="Pourquoi MacKinley veut-il le pied de Maury ?",a="MacKinley veut récupérer Maury’s Clubbed Foot parmi les objets de valeur des débiteurs.",al={"pourquoi son pied","pied de maury","ce que veut mackinley"}},{q="Que contient le pied de Maury ?",a="MacKinley dit que le pied de Maury renferme quelque chose qu'il peut vendre à bon prix.",al={"dans le pied","secret du pied de maury","que contient le pied"}},{q="Où trouver Maury ?",a="Maury erre dans les ruines de la jungle, près des Ruines d'Aboraz et des Ruines de Jubuwal.",al={"où est maury","emplacement de maury","où trouver pied bot"}},{q="Qui d'autre doit de l'argent à MacKinley ?",a="Jon-Jon the Crow et Chucky “Ten Thumbs” font aussi partie des débiteurs de MacKinley.",al={"autres débiteurs","jon-jon et chucky","qui doit de l'argent à sea wolf"}}},fp="20,169,20.345.0,19.207.1,37.93.0,39.88.0,30.90.1,25.81.0,24.82.0"}
P.entries["item:maury-s-key"] = {n="Maury's Key",s="La clé de Maury est recherchée par Sea Wolf MacKinley à Baie-du-Butin. Il en a besoin pour ouvrir le cadenas du pied de Maury et récupérer ce qui lui est dû.",h="La clé de Maury est recherchée par Sea Wolf MacKinley à Baie-du-Butin.",kw={"baie-du-butin","jeu","clé","pied verrouillé","maury","clé de maury","mosh'ogg","sea wolf mackinley"},sec={{t="Un pied verrouillé",b="MacKinley dit que Maury a verrouillé son pied, rendant le butin qu'il contient inaccessible. Le parieur défunt jouait autrefois contre les ogres Mosh'Ogg à leur tertre, au nord-est de Baie-du-Butin. Après avoir trop gagné, Maury a été chassé, et MacKinley soupçonne les ogres d'avoir sa clé."}},faq={{q="À quoi sert la clé de Maury ?",a="Sea Wolf MacKinley a besoin de la clé de Maury pour ouvrir le cadenas du pied de Maury et récupérer le butin qu'il contient.",al={"clé de maury","clé du pied de maury","déverrouiller le pied"}},{q="Qui veut la clé de Maury ?",a="Sea Wolf MacKinley, à Baie-du-Butin, veut la clé de Maury pour ouvrir le cadenas du pied de Maury.",al={"qui a besoin de la clé de maury","clé de mac kinley","clé de sea wolf"}},{q="Où Maury a-t-il perdu la clé ?",a="MacKinley pense que les ogres Mosh'Ogg, à leur tertre au nord-est de Baie-du-Butin, pourraient avoir la clé de Maury.",al={"où est la clé","clé des mosh'ogg","clé perdue par maury"}},{q="Pourquoi les ogres pourraient-ils l'avoir ?",a="Maury a joué aux dés contre les ogres Mosh'Ogg et a été chassé après avoir trop gagné. MacKinley soupçonne qu'ils ont gardé la clé.",al={"pourquoi les ogres ont la clé","maury et les ogres","clé de jeu"}}},fp="11,130,13.264.0,24.94.0,22.90.0,29.95.0,28.119.0"}
P.entries["item:melenas-head"] = {n="Tête de Melenas",s="À Gangreroche, la Tête de Melenas met fin à la menace du Seigneur Melenas. Le commandant satyre y avait établi son camp, et sa tête prouve sa mort.",h="À Gangreroche, la Tête de Melenas met fin à la menace du Seigneur Melenas.",kw={"gangreroche","grell","seigneur melenas","tête de melenas","satyre","teldrassil","twisted hatred"},ang={["class:Warrior"]="En tant que guerrier, vous savez que la tête tranchée d’un chef de guerre ennemi prouve sans équivoque qu’un adversaire dangereux et ses guerriers grells ont été vaincus.",["race:NightElf"]="En tant qu’elfe de la nuit, vous savez que les satyres sont une corruption démoniaque tragique de votre ancienne lignée. L’exécution discrète du Seigneur Melenas était nécessaire, mais demeure une source de honte culturelle."},sec={{t="Une disgrâce passée sous silence",b="La présence de satyres sur le nouvel Arbre-Monde de Teldrassil fait honte aux elfes de la nuit qui gardent Sombrevallon et les terres alentour. Le Seigneur Melenas avait établi son repaire dans les cavernes tortueuses de Gangreroche, juste au nord des colonies elfiques. Là, il rallia des guerriers grells agressifs à sa bannière.\n\nLes kaldorei privilégient la discrétion quand la corruption s’approche autant de leurs terres ancestrales. La Tête de Melenas est une preuve confidentielle que ses complots ont pris fin avant que son influence ne puisse s’étendre."}},faq={{q="Qui était le Seigneur Melenas ?",a="Le Seigneur Melenas était un commandant satyre qui se cachait à Gangreroche, sur Teldrassil. Il rassembla des guerriers grells sous ses ordres pour comploter contre les avant-postes kaldorei voisins.",al={"histoire du seigneur melenas","qui est melenas","récit de melenas"}},{q="Pourquoi sa mort doit-elle rester secrète ?",a="Les satyres sont d’anciens elfes de la nuit, maudits et déformés par la corruption démoniaque. Leur présence si près des branches sacrées de Teldrassil embarrasse profondément les autorités kaldorei. Éliminer Melenas rapidement et discrètement évite la panique et limite la honte.",al={"pourquoi le secret","secret de twisted hatred","pourquoi rester discret"}},{q="D’où vient la Tête de Melenas ?",a="La Tête de Melenas a été prise au fond de Gangreroche, une caverne corrompue juste au nord de Dolanaar, au centre de Teldrassil.",al={"où trouver melenas","emplacement de gangreroche","emplacement de melenas"}}},fx={b9c077d0={q="Pourquoi Tallonkai veut-il la Tête de Melenas ?",a="Tallonkai Viveracine cherche la tête comme preuve absolue de la mort de lord Melenas. La présence d'un satyre si près de Sombrevallon est considérée comme une humiliation dangereuse pour les elfes de la nuit. Livrer sa tête garantit que le sinistre comploteur a été réduit au silence rapidement et discrètement avant que ses plans ne puissent se propager davantage à travers Teldrassil.",al={"pourquoi apporter la tête de melenas","qui veut la tête de melenas","pourquoi tallonkai veut la tête"}},["05bed8f4"]={q="Qu'est-ce que la Tête de Melenas ?",a="C'est la tête tranchée du Seigneur Melenas, un vil satyre qui avait établi son repaire au sein de Gangreroche, juste au nord de Dolanaar. Melenas a rallié à ses côtés des grells agressifs et a comploté de sombres desseins inconfortablement proches du foyer sacré des elfes de la nuit, faisant de sa tête tranchée la preuve irréfutable que son influence corruptrice a été anéantie.",al={"qu'est-ce que la tête de melenas","objet tête de melenas","à qui est cette tête"}}},fp="13,141,20.426.0,21.159.0,32.242.0,35.110.0"}
P.entries["item:menethil-statuette"] = {n="Statuette de Menethil",s="Au large des côtes des Paluns, la Statuette de Menethil repose, perdue après un naufrage. Cette rare effigie d’argent rend hommage au roi déchu de Lordaeron.",h="Au large des côtes des Paluns, la Statuette de Menethil repose, perdue après un naufrage.",kw={"blind princess","bluegill","bolvar fordragon","cathédrale de la lumière","grayson shadowbreaker","statuette de menethil","terenas menethil","les paluns"},ang={["class:Paladin"]="En tant que paladin, vous voyez le roi Terenas en jeune guerrier de la Lumière, le marteau levé. Son portrait parle aux chevaliers sacrés qui pleurent le royaume déchu.",["faction:Alliance"]="En tant que membre de l’Alliance, vous connaissez Terenas comme le chef rassembleur qui fonda la Grande Alliance. Tout mémorial de lui qui subsiste est un trésor inspirant dans un monde fracturé."},sec={{t="Une rare relique de Lordaeron",b="Le roi Terenas Menethil II est représenté jeune paladin, les cheveux longs et le marteau levé vers les cieux. Humble de son vivant, il n’aimait pas les monuments à sa gloire, et peu d’effigies furent créées en son honneur. Quand le Fléau fit tomber Lordaeron, presque toutes furent détruites. Cette effigie rescapée est précieuse pour l’Alliance."},{t="Perdue dans les marécages",b="La Blind Princess transportait la statuette vers le port de Menethil de l’Alliance lorsque des murlocs Bluegill attaquèrent au large de la côte marécageuse. L’assaut dispersa la cargaison du navire marchand, et la statuette échoua dans un tonneau à moitié enfoui sur le rivage.\n\nDes orcs Dragonmaw et d’autres menaces locales rôdaient encore dans les environs, alors les défenseurs s’empressèrent de transporter l’icône récupérée vers le sud, à Hurlevent. Là, le Généralissime Bolvar Fordragon la confia à la Cathédrale de la Lumière."}},faq={{q="Qui est représenté sur la statuette ?",a="La statuette représente le roi Terenas Menethil II, ancien souverain de Lordaeron et architecte de l’Alliance originelle. Il apparaît jeune paladin, levant un marteau de guerre.",al={"qui figure sur la statue","que représente la statuette","qui est la statuette de menethil"}},{q="Comment la statuette a-t-elle été perdue ?",a="La Blind Princess transportait la statuette à travers la Grande mer. Des murlocs Bluegill attaquèrent le navire dans les Paluns, et sa cargaison échoua sur le rivage avant d’être ensevelie dans la boue.",al={"comment a-t-elle été perdue","qui a perdu la statuette","statue naufrage paluns"}},{q="Pourquoi les représentations du roi Terenas sont-elles si rares ?",a="Le roi Terenas n’aimait pas les monuments à sa gloire, si bien que peu de statues furent créées à son effigie. Les ravages du Fléau à Lordaeron détruisirent presque tous les portraits et les statues qui subsistaient dans le nord.",al={"pourquoi y a-t-il peu de statues de terenas","mémoriaux de terenas"}},{q="Où la statuette finit-elle ?",a="Après avoir été récupérée dans les Paluns, la statuette est apportée au Généralissime Bolvar Fordragon, au Donjon de Hurlevent. Il reconnaît la Lumière qui habite la relique et la confie au Seigneur Grayson Brisombre, à la Cathédrale de la Lumière.",al={"où apporter la statuette","qui garde la statuette","statuette cathédrale"}}},fx={["00c7d589"]={q="Qu'est-ce que la Statuette de Menethil ?",a="La Statuette de Menethil est une figurine argentée représentant le roi Terenas Menethil II dans sa jeunesse, en tant que paladin aux cheveux longs, son marteau levé. Au-delà d'être un portrait exquis du monarque déchu de Lordaeron, la relique semble condenser la Lumière elle-même, ce qui en fait à la fois un précieux monument historique et un objet sacré béni.",al={"qu'est-ce que la statuette de menethil","statue de menethil","qu'est-ce que la statuette"}},["0d8a0354"]={q="Pourquoi la Statuette de Menethil est-elle si recherchée ?",a="Le roi Terenas méprisait les monuments et mémoriaux personnels, laissant derrière lui extrêmement peu de représentations, dont la quasi-totalité fut détruite lorsque Lordaeron tomba face au Fléau. Sa rareté, la Lumière sacrée qu'elle porte et son lien sentimental profond avec le fondateur de l'Alliance en font un héritage irremplaçable, que des ennemis comme les orcs Gueule-de-dragon locaux seraient ravis de profaner ou de piller si elle restait sans surveillance.",al={"pourquoi les gens veulent la statuette de menethil","pourquoi la statuette est-elle précieuse","qui veut la statuette"}}},fp="18,131,25.338.0,16.448.0,30.162.0,27.169.0,43.200.0,32.222.1"}
P.entries["item:meridith-s-love-letter"] = {n="Meridith's Love Letter",s="La lettre d’amour de Meridith transmet son message à Narain Divinambolesque, à Tanaris. C’est une petite supplique née d’une rencontre après le crash d’une machine volante.",h="La lettre d’amour de Meridith transmet son message à Narain Divinambolesque, à Tanaris.",kw={"poisson","machine volante","gnome","lettre d’amour","meridith","narain divinambolesque","tanaris"},ang={["race:Gnome"]="En tant que gnome, vous transmettez les sentiments de Meridith à Narain Divinambolesque, un gnome comme vous, que son message surprend."},sec={{t="Un message pour Narain",b="Après avoir secouru Narain Divinambolesque, dont la machine volante s’est écrasée, Meridith vous demande de lui remettre sa lettre. Elle est tombée amoureuse du gnome et espère qu’il entendra ses sentiments."},{t="La réponse de Narain",b="Narain recule en apprenant qui a envoyé la lettre. Meridith est un poisson, proteste-t-il, et lui est un gnome ; il ne voit pas comment leur amour pourrait fonctionner."}},faq={{q="Qui a écrit la lettre d’amour de Meridith ?",a="Meridith a écrit la lettre pour Narain Divinambolesque, le gnome qu’elle a secouru après le crash d’une machine volante.",al={"qui a écrit la lettre","lettre de meridith","auteur de la lettre d’amour"}},{q="À qui la lettre est-elle destinée ?",a="La lettre est destinée à Narain Divinambolesque, un gnome de Tanaris.",al={"qui reçoit la lettre","lettre pour narain","à qui remettre"}},{q="Pourquoi Meridith envoie-t-elle une lettre ?",a="Meridith croit être tombée amoureuse de Narain et veut lui faire savoir ce qu’elle ressent.",al={"pourquoi une lettre","qui aime meridith","message de meridith"}},{q="Comment Meridith a-t-elle rencontré Narain ?",a="Meridith a secouru Narain dans les débris d’une machine volante écrasée.",al={"où se sont-ils rencontrés","épave de narain","machine volante écrasée"}},{q="Que dit Narain au sujet de la lettre ?",a="Narain dit que Meridith est un poisson et qu’il est un gnome, alors il croit qu’ils ne pourront jamais être ensemble.",al={"réaction de narain","narain aime-t-il meridith","poisson et gnome"}}},fp="22,158,20.184.0,14.140.1,33.101.0,22.56.0,32.89.0,29.70.0,38.94.1"}
P.entries["item:merrin-s-letter"] = {n="Lettre de Merrin",s="À Whelgar's Excavation, Merrin Tisseroche envoie un message urgent depuis les Paluns. Les raptors ont envahi le site, mais elle assure à ses proches qu'elle a survécu.",h="À Whelgar's Excavation, Merrin Tisseroche envoie un message urgent depuis les Paluns.",kw={"explorers' league","merrin tisseroche","lettre de merrin","mottled raptors","tarrel tisseroche","les paluns","excavations de whelgar"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous apportez des renseignements vitaux et un réconfort doux-amer aux sentinelles qui surveillent la route des Paluns lorsque vous leur remettez la note.",["race:Dwarf"]="En tant que nain, vous pouvez constater le prix personnel que paie l'Explorers' League pour mettre au jour l'histoire ancienne dans les contrées sauvages et dangereuses de Khaz Modan."},sec={{t="Un message des ruines",b="Merrin Tisseroche écrit depuis le site en ruines des Excavations de Whelgar, dans les Paluns. L'expédition naine avait mis au jour d'immenses fossiles préhistoriques et des reliques lorsqu'elle a dérangé un nid de Mottled Raptors. Les bêtes ont envahi les tranchées, tué plusieurs ouvriers et isolé les chercheurs survivants.\n\nAu milieu du chaos, Merrin envoie un message à son époux Tarrel, à Port de Menethil. Elle, le Prospecteur Whelgar et Ormer Tressefer ont survécu dans un abri barricadé."}},faq={{q="Qui a écrit la Lettre de Merrin ?",a="Merrin Tisseroche a écrit la lettre pendant l'expédition archéologique sur le site de fouilles à l'est de Port de Menethil, dans les Paluns.",al={"auteur de la lettre de merrin","qui est merrin"}},{q="À qui la lettre est-elle adressée ?",a="Merrin a adressé la lettre à Tarrel Tisseroche, qui attend anxieusement des nouvelles sur le pont de Port de Menethil.",al={"destinataire de la lettre de merrin","qui reçoit la lettre de merrin"}},{q="Qu'est-il arrivé à l'équipe de fouilles ?",a="Les Mottled Raptors ont envahi l'équipe archéologique alors qu'elle mettait au jour d'immenses ossements fossilisés. De nombreux ouvriers nains ont été tués, et seule une poignée a survécu derrière des barricades dans un camp de fortune.",al={"que s'est-il passé sur le site de fouilles","pourquoi l'expédition a-t-elle échoué"}},{q="Qui a aidé Merrin à survivre à l'attaque ?",a="Ormer Tressefer a aidé Merrin à survivre à l'attaque. Il a défendu Merrin et le prospecteur en chef, leur donnant le temps de se réfugier dans un abri pendant que les raptors submergeaient le reste du site de fouilles.",al={"qui a sauvé merrin","ormer tressefer"}}},fx={bce088a8={q="Qu'est-ce que la Lettre de Merrin ?",a="La Lettre de Merrin est un message urgent écrit par Merrin Tisseroche, une survivante de l'assaut catastrophique des raptors sur le site de fouilles des Paluns. Adressée à son cher Tarrel Tisseroche, la note relate le désastre qui s'est abattu sur leur équipe d'excavation et confirme qu'elle, le prospecteur Whelgar et Ormer Tressefer ont réussi à s'échapper de justesse.",al={"lettre de merrin","qu'est-ce que la lettre de merrin","note de merrin"}},ded8799c={q="Pourquoi Tarrel veut-il la Lettre de Merrin ?",a="Tarrel Tisseroche vous a envoyé dans les marécages dangereux spécifiquement pour obtenir des nouvelles de l'être aimé et du sort de l'équipe de fouilles disparue. La Lettre de Merrin lui fournit la confirmation vitale qu'elle est toujours en vie, tout en détaillant la perte tragique du site de fouilles et leur refuge désespéré face aux raptors environnants.",al={"pourquoi livrer la lettre de merrin","pourquoi tarrel veut la lettre","but de la lettre de merrin"}}},fp="15,152,25.471.0,26.142.0,31.112.0,37.190.0,37.183.0"}
P.entries["item:middle-of-gelkak-s-key"] = {n="Clé médiane de Gelkak",s="Au large de Sombrivage, des threschaders coulèrent le navire de Gelkak Gyromast et dispersèrent sa clé en trois morceaux. Des murlocs Greymist prirent le fragment du milieu.",h="Au large de Sombrivage, des threschaders coulèrent le navire de Gelkak Gyromast et dispersèrent sa clé en...",kw={"mécanisme d’horlogerie","sombrivage","gelkak gyromast","greymist","clé médiane de gelkak","murloc","épave"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous pouvez voir comment ce composant mécanique personnalisé permet de remonter et de faire fonctionner un second mécanique, témoin de l’ingéniosité des gnomes aux mains d’un pirate."},sec={{t="Un fragment dans le limon",b="La clé de remontage de Gelkak Gyromast se brisa quand des threschaders entraînèrent son navire sous les flots. Le pirate gnome aborda avec ses biens brisés sur les hauts-fonds rocheux. Sa clé spéciale était conçue pour son second mécanique, mais le naufrage la fendit en trois morceaux dispersés le long du rivage. Des bêtes côtières emportèrent les morceaux du haut et du bas. Des murlocs Greymist qui rôdaient dans les vagues de Sombrivage prirent le morceau du milieu et le gardèrent dans leurs camps, parmi les épaves qu’ils détiennent."}},faq={{q="À quoi sert la Clé médiane de Gelkak ?",a="Gelkak Gyromast a besoin de la Clé médiane de Gelkak, qui est l’un des trois morceaux. Réunie aux morceaux du haut et du bas, elle forme la clé qui réactive son second mécanique.",al={"à quoi sert la clé de gelkak","utilité de la clé médiane de gelkak","pourquoi ai-je besoin de cette clé"}},{q="Où a fini ce morceau de clé ?",a="Les murlocs Greymist ont récupéré le fragment du milieu. On peut le prendre aux pilleurs, aux oracles, aux pêcheurs au filet, aux chasseurs des marées et aux autres membres de la tribu, le long des plages et des épaves de Sombrivage.",al={"qui détient le morceau du milieu","où trouver la clé médiane de gelkak","qui lâche le morceau du milieu"}},{q="Pourquoi la clé s’est-elle brisée ?",a="Des threschaders agressifs coulèrent le navire de Gelkak juste au large. La clé se brisa en trois morceaux contre les rochers côtiers alors que le gnome était rejeté sur le rivage, puis les charognards des environs emportèrent les morceaux.",al={"comment la clé s’est-elle brisée","pourquoi est-elle en morceaux"}}},fx={d3714d13={q="Qu'est-ce que la Clé médiane de Gelkak ?",a="Il s'agit de la section centrale d'une clé en trois parties appartenant au pirate gnome naufragé, Gelkak Gyromast. Lorsque son navire a fait naufrage au large des côtes de Sombrivage et qu'il a été rejeté par les flots, la clé s'est brisée sur les rochers escarpés, laissant ce fragment parmi l'épave.",al={"clé médiane de gelkak","pièce centrale de la clé de gelkak","qu'est-ce que cette pièce de clé"}},["55a592b4"]={q="D'où vient la Clé médiane de Gelkak et qui l'a fabriquée ?",a="La clé appartient à Gelkak Gyromast, apportée à bord de son navire avant qu'il ne soit détruit par des threshedons au large des côtes de Sombrivage. Bien que Gelkak possédât la clé pour faire fonctionner son second mécanique, son fabricant précis est inconnu.",al={"qui a fabriqué la clé de gelkak","origine de la pièce de clé médiane","d'où vient la clé"}},["7cf04b1b"]={q="Pourquoi Gelkak Gyromast veut-il le fragment de clé médian ?",a="Gelkak Gyromast a besoin de cette pièce centrale ainsi que des deux autres fragments pour réassembler la clé complète. Sans la clé complète, il ne peut pas remonter et réactiver son second mécanique pour se venger des bêtes locales du rivage.",al={"pourquoi gelkak veut cette clé","qui veut la clé de gelkak","pourquoi la clé est-elle nécessaire"}}},fp="22,138,22.481.0,44.163.0,32.176.0,42.190.0"}
P.entries["item:milly-s-harvest"] = {n="Récolte de Milly",s="Dans le Vignoble de Comté-du-Nord, la Récolte de Milly est abandonnée après l’arrivée des Défias. Des caisses et des seaux de raisins risquent d’être volés ou écrasés sous les bottes des gardes de l’abbaye.",h="Dans le Vignoble de Comté-du-Nord, la Récolte de Milly est abandonnée après l’arrivée des Défias.",kw={"défias","forêt d’elwynn","raisins","milly osworth","récolte de milly","abbaye de comté-du-nord","vignoble de comté-du-nord"},ang={["faction:Alliance"]="La menace qui pèse sur les fermiers de Comté-du-Nord montre à quel point la garnison de Hurlevent est réduite. Les gens ordinaires comptent sur les aventuriers de passage pour protéger leurs moyens de subsistance.",["race:Human"]="Si vous commencez votre aventure en tant qu’humain à Comté-du-Nord, vous pourriez découvrir les méfaits de la Confrérie défias jusque sur le pas de votre porte en récupérant les raisins de Milly."},sec={{t="Une récolte fragile",b="Milly Osworth cueille des raisins dans le Vignoble de Comté-du-Nord. La récolte compte pour les vignerons locaux et la communauté de l’abbaye. Quand des brigands armés de masques rouges entrent dans les champs, Milly s’enfuit sur les terres de l’abbaye. Ses raisins fraîchement cueillis restent éparpillés entre les rangs."},{t="Dégâts collatéraux",b="Les gardes de Hurlevent surveillent l’entrée de la vallée, mais leurs effectifs réduits rendent Comté-du-Nord vulnérable. La garnison promet de chasser les Défias. Milly craint qu’un long combat entre gardes et voleurs ne ruine sa récolte. Les caisses risquent d’être piétinées ou emportées comme provisions, privant Comté-du-Nord de l’une de ses rares récoltes paisibles."}},faq={{q="Qu’est-ce que la Récolte de Milly ?",a="La Récolte de Milly désigne les raisins que Milly Osworth a cueillis et rangés dans des caisses et des seaux avant que les voyous défias ne s’emparent du Vignoble de Comté-du-Nord.",al={"récolte de milly","qu’est-ce que la récolte","raisins de milly osworth"}},{q="Pourquoi les caisses ont-elles été abandonnées dans le vignoble ?",a="Des bandits défias ont attaqué les vignobles pendant que Milly faisait les vendanges. Elle a dû abandonner les raisins et s’enfuir à l’Abbaye de Comté-du-Nord.",al={"pourquoi abandonnée","pourquoi milly a-t-elle laissé les raisins","pourquoi abandonner la récolte"}},{q="Pourquoi les gardes de Comté-du-Nord n’ont-ils pas pu récupérer la récolte ?",a="Les gardes de Comté-du-Nord sont débordés par les incursions défias et les menaces locales. Milly craint aussi que leurs bottes n’écrasent les raisins lorsqu’ils chasseront les bandits.",al={"pourquoi pas les gardes","pourquoi les gardes ne peuvent-ils pas les récupérer","gardes de hurlevent à comté-du-nord"}},{q="Quels bandits menacent la récolte ?",a="Les bandits qui menacent la récolte appartiennent à la Confrérie défias, une bande de hors-la-loi et de brigands qui sèment le trouble dans toute la Forêt d’Elwynn.",al={"qui a pris le vignoble","qui attaque le vignoble","bandits du vignoble"}}},fx={["1d7cbab4"]={q="Pourquoi Milly veut-elle que sa récolte soit récupérée ?",a="Milly Osworth a récolté les fruits elle-même et en dépend pour gagner sa vie, mais a dû les abandonner lorsque les bandits de la Confrérie défias ont envahi le vignoble. Elle craint que si les voleurs ne s'emparent pas des fruits en premier, les gardes de l'abbaye ne piétinent les raisins fragiles dans la boue en chassant les brigands.",al={"pourquoi milly veut la récolte","pourquoi récupérer la récolte de milly","pourquoi les raisins sont importants"}}},fp="15,174,15.261.0,17.328.0,24.138.0,48.128.0,56.161.0,44.141.0"}
P.entries["item:mind-s-eye"] = {n="Vue de l'esprit",s="Mind’s Eye est un artefact détenu par Mai’Zoth, un mage ogre de la Vallée de Strangleronce. Sa magie est redoutée, car elle corrompt et renforce ceux qui la manient.",h="Mind’s Eye est un artefact détenu par Mai’Zoth, un mage ogre de la Vallée de Strangleronce.",kw={"frère nimetz","kin'weelay","kurzen","mai'zoth","vue de l'esprit","mosh'ogg","mage ogre","vallée de strangleronce","yenniku"},ang={["faction:Horde"]="En tant que membre de la Horde, vous êtes concerné par les efforts des Sombrelance pour sauver Yenniku, le fils du chef."},sec={{t="Le mage ogre",b="Frère Nimetz pense que Mai’Zoth s’est servi de Mind’s Eye pour corrompre Kurzen. Le mage ogre garde l’artefact dans le tertre ogre de Mosh’Ogg, à l’est de la Vallée de Strangleronce. Nimetz craint que son influence ne corrompe également d’autres personnes."},{t="Un choix pour Mind’s Eye",b="Kin’weelay voit en Mind’s Eye le seul espoir de sauver Yenniku. Une fois l’artefact récupéré, Kin’weelay compte plier son pouvoir aux besoins des Sombrelance. Frère Nimetz prévoit d’étudier l’artefact et de décider s’il peut servir le bien ou s’il doit être détruit."}},faq={{q="Qu’est-ce que Mind’s Eye ?",a="Mind’s Eye est un artefact détenu par le mage ogre Mai’Zoth. On dit que sa magie accroît son pouvoir et corrompt les autres.",al={"mind’s eye","qu’est-ce que mind’s eye","l’œil"}},{q="Qui détient Mind’s Eye ?",a="Mai’Zoth, un mage ogre, détient Mind’s Eye au fond du tertre ogre de Mosh’Ogg, dans la Vallée de Strangleronce.",al={"qui détient l’œil","œil de mai'zoth","détenteur de mind’s eye"}},{q="Qu’a fait Mind’s Eye à Kurzen ?",a="Frère Nimetz pense que Mai’Zoth s’est servi de Mind’s Eye pour corrompre Kurzen. Il craint que son influence ne corrompe d’autres personnes.",al={"corruption de kurzen","pourquoi kurzen est mauvais","mind’s eye et kurzen"}},{q="Pourquoi Kin’weelay veut-il Mind’s Eye ?",a="Kin’weelay voit en Mind’s Eye le seul espoir de sauver Yenniku, le fils du chef Sombrelance.",al={"kin’weelay et l’œil","sauver yenniku","pourquoi l’œil"}},{q="Que compte faire Frère Nimetz de l’artefact ?",a="Frère Nimetz prévoit d’étudier Mind’s Eye et de décider s’il peut servir le bien ou s’il doit être détruit.",al={"nimetz et l’œil","détruire mind’s eye","étudier l’œil"}},{q="Où se trouve Mai’Zoth ?",a="Mai’Zoth vit dans le tertre ogre de Mosh’Ogg, à l’est de la Vallée de Strangleronce.",al={"emplacement de mai'zoth","tertre de mosh'ogg","où se trouve le mage ogre"}}},fp="10,160,13.229.0,20.267.0,25.133.0,25.109.0,39.120.0,44.100.0,36.111.0,20.81.0"}
P.entries["item:miners-gear"] = {n="Equipement de mineur",s="Dans le nord de Loch Modan, l’Equipement de mineur attend dans la Mine du Ru d'argent. Les kobolds ont envahi les tunnels, et la Miners' League veut récupérer ses outils avant l’attaque des gardes locaux.",h="Dans le nord de Loch Modan, l’Equipement de mineur attend dans la Mine du Ru d'argent.",kw={"filthy paws","kobold","loch modan","équipement de mineur","miners' league","montagnard foudrepique","mine du ru d'argent"},ang={["profession:Mining"]="En tant que mineur, vous connaissez la valeur du fer nain bien forgé. Laisser des pioches et des pelles de grande qualité à des pillards munis de bougies est une petite tragédie.",["race:Dwarf"]="En tant que nain, vous pourriez juger intolérable que les kobolds mettent leurs sales pattes sur l’artisanat nain. La mine appelle à être nettoyée sans attendre."},sec={{t="Fournitures de la Miners' League",b="La Mine du Ru d'argent n’avait plus de minerai, alors la Miners' League a transformé ses tunnels silencieux en dépôt de matériel minier. Les kobolds ont envahi la mine, se sont emparés des marchandises entreposées et ont établi leurs nids parmi les caisses. La ligue craint qu’un assaut des Mountaineers ne détruise l’équipement nain, ou que des pillards ne l’abîment. Entrez dans la mine et mettez les caisses à l’abri avant que l’un ou l’autre de ces sorts ne leur tombe dessus."}},faq={{q="Qu’est-ce que l’Equipement de mineur ?",a="L’Equipement de mineur désigne les caisses d’outils d’excavation nains de la Miners' League, notamment des pioches et des pelles, entreposées dans les tunnels secs de la Mine du Ru d'argent.",al={"qu’est-ce que l’équipement de mineur","objets de l’équipement de mineur","équipement de mineur à loch modan"}},{q="Pourquoi l’équipement a-t-il été laissé dans la mine ?",a="Après que la Mine du Ru d'argent s’est retrouvée à court de minerai, la Miners' League a transformé ses tunnels vides en dépôt. L’équipement y est resté jusqu’à ce que les kobolds infestent les galeries.",al={"pourquoi l’équipement est-il dans la mine du ru d’argent","pourquoi laisser l’équipement là-bas"}},{q="Qui veut récupérer cet équipement ?",a="Le Montagnard foudrepique dirige les opérations de récupération de la Miners' League. Il veut sauver les outils avant que ses compagnons d’armes ne marchent sur la mine pour tuer les kobolds.",al={"qui veut l’équipement de mineur","qui a besoin de l’équipement","équipement du montagnard foudrepique"}},{q="Où trouve-t-on l’Equipement de mineur ?",a="Les caisses de la Miners' League sont éparpillées dans les galeries de la Mine du Ru d'argent, au nord de Loch Modan, à l’est du Poste d’Algaz.",al={"emplacement de l’équipement de mineur","où trouver l’équipement de mineur","emplacement des caisses de la miners' league"}}},fp="12,184,30.382.0,21.149.0,34.167.0,30.152.0,32.128.0"}
P.entries["item:miners-union-card"] = {n="Carte du syndicat des mineurs",s="À Ruisselune, les cartes du syndicat restent auprès des ouvriers perdus sous terre. Les travailleurs les portaient autrefois dans les mines ; elles reposent désormais avec les morts squelettiques dans les galeries obscures.",h="À Ruisselune, les cartes du syndicat restent auprès des ouvriers perdus sous terre.",kw={"éboulement","collecting memories","les mortemines","carte du syndicat des mineurs","ruisselune","mineur squelettique","hurlevent","carte du syndicat"},ang={["faction:Alliance"]="Récupérer les cartes peut réconforter les familles de tout le royaume de Hurlevent, qui n'ont jamais su ce qu'étaient devenus leurs proches ouvriers.",["profession:Mining"]="Pour les prospecteurs et les mineurs, ces cartes rappellent les risques mortels des éboulements et des puits de mine mal entretenus."},sec={{t="Tragédie dans les profondeurs",b="Avant que la Confrérie défias ne prenne le contrôle de Ruisselune, les mineurs travaillaient sous terre pour la guilde et extrayaient du minerai précieux pour le royaume. Puis un tunnel s'effondra, écrasant un puits majeur et tuant des dizaines de personnes sous la roche.\n\nLes morts se relevèrent sous forme de mineurs, d'excavateurs et de dynamiteurs squelettiques. Leurs cartes du syndicat restent dans leurs poches osseuses, dernière preuve de leur identité. À Hurlevent, leurs collègues survivants cherchent les cartes pour identifier les ouvriers morts et apporter du réconfort à leurs familles."}},faq={{q="Qu'est-ce qu'une Carte du syndicat des mineurs ?",a="Une Carte du syndicat des mineurs identifiait un membre de la guilde qui travaillait dans les mines de Ruisselune. Les travailleurs survivants se servent des cartes pour savoir qui est mort dans l'éboulement.",al={"qu'est-ce qu'une carte du syndicat","carte de mineur","carte du syndicat"}},{q="D'où viennent ces cartes ?",a="On trouve ces cartes sur les ouvriers morts-vivants dans les galeries effondrées sous Ruisselune, notamment sur les mineurs, les excavateurs et les dynamiteurs squelettiques.",al={"où trouver les cartes du syndicat","qui donne les cartes de mineurs","lieu d'obtention des cartes"}},{q="Pourquoi les mineurs sont-ils morts-vivants ?",a="Un éboulement a piégé les mineurs dans un puits profond. On ignore ce qui les a relevés sous forme de morts-vivants ; leurs dépouilles hantent désormais les galeries effondrées sous Ruisselune.",al={"pourquoi des mineurs squelettiques","comment les mineurs sont-ils morts","morts-vivants de deadmines"}},{q="Qui veut récupérer ces cartes ?",a="Les collègues survivants, qui ont échappé à l'éboulement et vivent désormais à Hurlevent, cherchent les cartes. Ils espèrent raconter aux familles des mineurs tombés ce qui s'est passé et leur apporter la paix.",al={"qui récupère les cartes du syndicat","donneur de quête collecting memories","rendre les cartes du syndicat"}}},fp="18,179,19.484.0,29.152.0,31.150.0,26.147.0,31.173.0"}
P.entries["item:miniaturization-residue"] = {n="Miniaturization Residue",s="Miniaturization Residue subsiste sur les géants de Féralas rétrécis par l’appareil de Zorbin Fandazzle. Il l’étudie pour améliorer son rayon rétrécissant et en demande davantage aux quais de La Côte oubliée.",h="Miniaturization Residue subsiste sur les géants de Féralas rétrécis par l’appareil de Zorbin Fandazzle.",kw={"ingénierie","féralas","la côte oubliée","géants","résidu de miniaturisation","cartel gentepression","zorbin fandazzle","ultra-shrinker de zorpin"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous reconnaîtrez peut-être dans l’intérêt de Zorbin pour ces résidus un moyen d’améliorer ses appareils rétrécissants."},sec={{t="Résidus de géants",b="Le long de La Côte oubliée, Zorbin Fandazzle cherche des résidus de géants rétrécis avec son Ultra-Shrinker. Les Cliff Giants, Deep Striders, Land Walkers, Shore Striders et Wave Striders en laissent après l’utilisation de l’appareil. Zorbin affirme que ces résidus l’aident à empêcher ses autres zapper d’exploser sur leurs utilisateurs."}},faq={{q="Qu’est-ce que Miniaturization Residue ?",a="On trouve Miniaturization Residue sur les géants de Féralas après les avoir rétrécis avec l’Ultra-Shrinker de Zorbin.",al={"résidu de miniaturisation","qu’est-ce que ce résidu","résidu de géant"}},{q="Qui veut les résidus ?",a="Zorbin Fandazzle, aux quais de La Côte oubliée, demande Miniaturization Residue.",al={"qui veut les résidus","résidu de zorbin","à qui dois-je l’apporter"}},{q="Pourquoi Zorbin en a-t-il besoin ?",a="Zorbin étudie ces résidus pour éviter que ses autres appareils rétrécissants n’explosent sur leurs utilisateurs.",al={"pourquoi ces résidus","à quoi servent ces résidus","recherche sur les zappers"}},{q="Quels géants en ont ?",a="Les Cliff Giants, Deep Striders, Land Walkers, Shore Striders et Wave Striders de Féralas peuvent laisser des résidus après avoir été rétrécis.",al={"résidus laissés par les géants","quels géants","géants de féralas"}}},fp="23,179,19.310.0,32.110.0,22.88.0,24.100.0,21.124.0"}
P.entries["item:minshina-s-skull"] = {n="Crâne de Minshina",s="Sur les Îles de l'Écho, l'âme de Minshina reste liée à son crâne par la magie noire de Zalazane. Minshina était un troll Sombrelance et le frère de Maître Gadrin. Zalazane s'empara des îles et chassa la tribu, puis utilisa le crâne de Minshina dans ses rituels.",h="Sur les Îles de l'Écho, l'âme de Minshina reste liée à son crâne par la magie noire de Zalazane.",kw={"cercle de puissance","sombrelance","îles de l'écho","gadrin","minshina","village de sen'jin","crâne","zalazane"},ang={["faction:Horde"]="Récupérer le crâne porte un premier coup à l'emprise de Zalazane sur les Îles de l'Écho, au large des côtes de Durotar.",["race:Troll"]="Pour les Sombrelance, la profanation de Minshina par Zalazane va à l'encontre des traditions ancestrales. Récupérer son crâne est une question d'honneur tribal."},sec={{t="Un esprit captif",b="Minshina fut capturé et tué lorsque Zalazane s'empara des Îles de l'Écho et chassa les Sombrelance. Le féticheur traître lia son âme à son crâne tranché, au lieu de le laisser rejoindre la mort. À présent, le crâne repose dans un cercle de puissance sur l'île la plus au sud, qui retient Minshina sous l'emprise de la magie de Zalazane.\n\nMaître Gadrin rêve que son frère l'appelle et cherche de braves voyageurs prêts à pénétrer dans les îles occupées. Il leur demande de récupérer le crâne et de libérer l'esprit de Minshina de l'emprise de Zalazane."}},faq={{q="Qui était Minshina ?",a="Minshina était un troll Sombrelance et le frère de Maître Gadrin, du Village de Sen'jin. Zalazane l'assassina lors de sa trahison sur les Îles de l'Écho.",al={"histoire de minshina","qui est minshina","frère de maître gadrin"}},{q="Pourquoi l'âme de Minshina est-elle prisonnière de son crâne ?",a="Zalazane usa de magie noire pour lier l'esprit de Minshina à sa tête tranchée. Il plaça le crâne dans un cercle de puissance sur l'île principale, maintenant Minshina sous son emprise au lieu de le laisser rejoindre ses ancêtres.",al={"pourquoi piéger son âme","rituel du crâne de zalazane","âme prisonnière d'un crâne"}},{q="Où se trouve le crâne ?",a="Le crâne repose sur la plus grande île, au sud des Îles de l'Écho. Il se trouve au sommet d'une colline, dans un cercle de puissance entouré de bougies, de marques rituelles et d'autres crânes, sous la garde des séides de Zalazane.",al={"où se trouve le crâne de minshina","emplacement du cercle de puissance","emplacement du crâne aux îles de l'écho"}},{q="Que se passe-t-il quand on rapporte le crâne à Maître Gadrin ?",a="Quand vous rapportez le crâne à Maître Gadrin, au Village de Sen'jin, l'enchantement maléfique se brise. La forme spectrale de Minshina apparaît brièvement, s'incline en signe de gratitude, puis part en paix rejoindre le royaume des ancêtres.",al={"libérer minshina","récompense du crâne de gadrin","qu'arrive-t-il à minshina"}}},fx={["5c3b75e4"]={q="Qu'est-ce que le Crâne de Minshina ?",a="Le Crâne de Minshina est la dépouille de Minshina, un troll Sombrelance déchu et frère du Maître Gadrin. Plutôt que de reposer en paix dans la mort, l'âme même de Minshina a été liée à son crâne tranché par un vaudou noir, le laissant prisonnier et appelant à la libération.",al={"qu'est-ce que le crâne de minshina","identité du crâne de minshina","qu'est-ce que ce crâne"}},["1b71ee0f"]={q="D'où vient le Crâne de Minshina et qui l'a créé ?",a="Le crâne appartenait à Minshina, qui fut capturé et tué par le traître féticheur Zalazane sur les Îles de l'Écho. Utilisant une magie corrompue, Zalazane a tranché la tête et lié l'esprit de Minshina directement à l'os, le plaçant au sein d'un cercle de pouvoir aux côtés d'autres restes pour alimenter ses sombres rituels.",al={"d'où vient le crâne de minshina","qui a créé le crâne de minshina","origine du crâne de minshina"}},b6c5f4d1={q="Pourquoi quelqu'un voudrait-il le Crâne de Minshina ?",a="Le Maître Gadrin cherche le crâne pour sauver l'esprit tourmenté de son frère. Minshina appelle constamment Gadrin dans ses rêves, incapable de trouver le repos tant qu'il est emprisonné par la magie de Zalazane. Récupérer le crâne du cercle de pouvoir sur les Îles de l'Écho est le seul moyen de briser le lien et d'offrir la liberté à son âme.",al={"pourquoi vouloir le crâne de minshina","pourquoi récupérer le crâne de minshina","qui veut le crâne de minshina"}}},fp="16,242,16.507.0,17.142.0,44.206.0,27.192.0,56.206.1"}
P.entries["item:mirefin-head"] = {n="Mirefin Head"}
P.entries["item:mirror-lake-water-sample"] = {n="Echantillon d'eau du lac Miroir",s="Au lac Miroir, dans la Forêt d’Elwynn, on prélève de l’eau pour Jennea Cannon, à Hurlevent. Les mages l’analyseront pour détecter si les courants arcaniques ont altéré l’eau locale.",h="Au lac Miroir, dans la Forêt d’Elwynn, on prélève de l’eau pour Jennea Cannon, à Hurlevent.",kw={"souillure arcanique","forêt d’elwynn","flacon","jennea cannon","lac miroir","hurlevent","échantillon d’eau","sanctuaire du sorcier"},ang={["class:Mage"]="En tant que mage en formation au Sanctuaire du sorcier, vous allez chercher cet échantillon pour l’une de vos premières tâches. Cela vous apprend à surveiller les lignes telluriques de l’environnement et à repérer les infiltrations de magie sauvage."},sec={{t="Tester les eaux d’Elwynn",b="Jennea Cannon envoie ses apprentis les plus prometteurs prélever de l’eau au lac Miroir. Le lac se trouve juste au sud-ouest des Portes de Hurlevent. Ils remplissent un flacon spécialement préparé au pied de sa cascade.\n\nAu Sanctuaire du sorcier, à Hurlevent, on craint que les voies mystiques du monde soient encore perturbées après des conflits catastrophiques. Les mages examineront l’échantillon pour y détecter toute souillure magique dans les cours d’eau utilisés par les habitants des environs."}},faq={{q="Qu’est-ce que l’échantillon d’eau du lac Miroir ?",a="L’échantillon d’eau du lac Miroir est de l’eau de la cascade de la Forêt d’Elwynn, conservée dans le Flacon de Jennea. Les mages novices la recueillent pour la faire analyser au Sanctuaire du sorcier.",al={"échantillon du lac miroir","objet échantillon d’eau","eau de jennea"}},{q="Pourquoi Jennea Cannon veut-elle cet échantillon d’eau ?",a="De récents bouleversements mystiques sur Azeroth ont perturbé les courants magiques stables. Jennea Cannon craint qu’une énergie magique incontrôlée altère le monde naturel et empoisonne l’eau potable locale.",al={"pourquoi analyser le lac miroir","but de jennea cannon","souillure magique de l’eau"}},{q="Où l’échantillon est-il prélevé ?",a="L’échantillon provient du pied de la cascade qui se jette dans le lac Miroir, au sud-ouest des Portes de Hurlevent, dans la Forêt d’Elwynn.",al={"où prélever l’échantillon","emplacement du lac miroir","cascade de l’échantillon"}},{q="Que se passe-t-il si l’eau s’avère souillée par la magie ?",a="Jennea Cannon craint que boire longtemps l’eau du lac Miroir puisse entraîner des effets magiques néfastes si les courants telluriques ont contaminé les réserves d’eau.",al={"effets de l’eau souillée","le lac miroir est-il empoisonné"}}},fx={["935f4959"]={q="D'où provient l'Echantillon d'eau du lac Miroir et qui l'a collecté ?",a="L'échantillon est collecté directement au pied de la cascade qui se déverse dans le lac Miroir, juste au sud-ouest des portes de Hurlevent dans la Forêt d’Elwynn. À l'aide d'une fiole vide fournie par l'entraîneuse de mages Jennea Cannon, vous puisez l'eau vous-même pour le compte des lanceurs de sorts de Hurlevent afin qu'ils puissent examiner l'état des courants sauvages environnants.",al={"d'où vient l'echantillon d'eau du lac miroir","qui a créé l'echantillon d'eau du lac miroir","origine de l'echantillon d'eau du lac miroir"}}},fp="24,166,28.411.0,37.151.0,46.177.0,30.123.0,60.154.0"}
P.entries["item:miscellaneous-goblin-supplies"] = {n="Miscellaneous Goblin Supplies",s="Miscellaneous Goblin Supplies sont des livraisons régulières destinées au camp du Lieutenant Doren, près de l’entrée de la Vallée de Strangleronce. Elles contiennent des mines terrestres pour se défendre contre Kurzen et ses hommes.",h="Miscellaneous Goblin Supplies sont des livraisons régulières destinées au camp du Lieutenant Doren, près de...",kw={"bois de la pénombre","fournitures gobelines","kurzen","mines terrestres","lieutenant doren","miscellaneous goblin supplies","soldat thorsen","vallée de strangleronce"},sec={{t="Une livraison attendue",b="Le Soldat Thorsen réceptionne les fournitures au camp du Lieutenant Doren, au nord-ouest de la route qui mène du Bois de la Pénombre à la Vallée de Strangleronce. Les attaques des Trolls ont retardé la livraison régulière, dont les partisans de Doren ont besoin. Thorsen peut se trouver au camp ou patrouiller au sud de celui-ci. Les mines doivent aider à défendre le camp contre Kurzen et ses hommes."}},faq={{q="Que contiennent les fournitures gobelines ?",a="Ce sont des mines terrestres fournies par les gobelins pour le camp du Lieutenant Doren.",al={"fournitures gobelines","fournitures diverses","contenu du colis"}},{q="Qui a besoin de ces fournitures ?",a="Le Soldat Thorsen réceptionne les fournitures destinées aux partisans du Lieutenant Doren dans leur camp.",al={"destinataire des fournitures","qui en a besoin","à qui livrer"}},{q="Où se trouve le camp de Doren ?",a="Le camp se trouve au nord-ouest de la route, à l’entrée de la Vallée de Strangleronce depuis le Bois de la Pénombre.",al={"emplacement du camp de doren","où se trouve le camp","camp près de strangleronce"}},{q="Pourquoi les mines sont-elles nécessaires ?",a="Les mines aideront à défendre le camp de Doren contre Kurzen et ses hommes.",al={"pourquoi des mines","à quoi servent les mines","défense contre kurzen"}}},fp="29,183,17.333.0,29.74.0,25.87.0,24.88.0,25.66.0"}
P.entries["item:mist-veil-s-lockbox"] = {n="Coffret du Voile de brume",s="Au large de Sombrivage, des murlocs côtiers ont pris le Voile de brume en embuscade et l’ont coulé. Le navire elfe de la nuit repose désormais sous les flots, avec le journal de bord du capitaine et ses effets personnels dans son coffret.",h="Au large de Sombrivage, des murlocs côtiers ont pris le Voile de brume en embuscade et l’ont coulé.",kw={"auberdine","sombrivage","gorbold main-d'acier","coffret","voile de brume","murloc","épave","silver dawning"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez honorer l’équipage disparu et aider la communauté maritime d’Auberdine.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous pouvez aider à rendre le journal de bord du capitaine disparu et à apaiser son esprit dans les eaux au large de Sombrivage."},sec={{t="Perdu dans les profondeurs",b="Le navire elfe de la nuit Voile de brume a sombré alors qu’il faisait route vers Auberdine. Des murlocs côtiers l’ont submergé, lui et son navire jumeau, le Silver Dawning. Le capitaine a péri, et le journal de bord ainsi que ses effets personnels sont toujours enfermés dans le coffret, dans la cale inondée. Des murlocs encerclent encore l’épave."},{t="Un repos pour l’équipage",b="Les marins survivants ont atteint Auberdine, mais pleurent toujours la perte de leur navire et de leur commandant. Gorbold Main-d'acier cherche le Coffret du Voile de brume afin que les derniers effets du capitaine puissent être honorés et reposer en paix. Le récupérer dans l’épave inondée pourrait réconforter les survivants restés sur le continent."}},faq={{q="Que contient le Coffret du Voile de brume ?",a="Le Coffret du Voile de brume contient le journal de bord du capitaine et ses effets personnels. Le capitaine a péri lorsque le navire a sombré, et l’équipage survivant d’Auberdine souhaite récupérer ces souvenirs pour honorer son chef disparu.",al={"contenu du coffret du voile de brume","que contient le coffret","que trouve-t-on dans le coffre"}},{q="Comment le Voile de brume a-t-il sombré ?",a="Des murlocs côtiers ont pris le Voile de brume en embuscade alors qu’il faisait route vers Auberdine. Ils l’ont submergé, lui et son navire jumeau, le Silver Dawning, et les deux navires ont sombré.",al={"pourquoi le navire a-t-il fait naufrage","qui a coulé le voile de brume","qu’est-il arrivé au voile de brume"}},{q="Où se trouve le coffret ?",a="Le coffret repose sous l’eau au large de Sombrivage, au nord d’Auberdine, dans la coque inondée du Voile de brume. Des murlocs infestent l’épave.",al={"où se trouve le coffret du voile de brume","emplacement du voile de brume","emplacement du coffret"}},{q="Qui veut récupérer le coffret ?",a="Gorbold Main-d'acier, à Auberdine, cherche à récupérer le coffret pour l’équipage survivant. Il espère honorer le capitaine disparu et apporter la paix aux marins.",al={"qui récupère le coffret","qui donne la quête","quête du coffret de gorbold"}}},fx={fab3edd7={q="Qu'est-ce que le Coffret du Voile de brume ?",a="Il s'agit du coffre du capitaine récupéré sur l'épave du Voile de brume, qui repose sous les vagues au large de Sombrivage, au nord d'Auberdine. Conservé en sécurité à bord du navire jusqu'à ce que des murlocs ne le fassent couler, il préserve les journaux de bord, les carnets et les effets personnels du défunt capitaine elfe de la nuit, témoins du voyage tragique.",al={"qu'est-ce que le coffret du voile de brume","coffret du voile de brume","qu'est-ce que le coffret"}}},fp="19,179,18.284.0,17.291.0,35.199.0,27.152.0,27.131.0,32.131.0"}
P.entries["item:mo-grosh-crystal"] = {n="Cristal mo'grosh",s="Dans le nord-est de Loch Modan, les ogres mo'grosh extraient et gardent de rares cristaux aux propriétés alchimiques inhabituelles. Les ingénieurs nains s'en servent pour neutraliser les explosifs Sombrefer.",h="Dans le nord-est de Loch Modan, les ogres mo'grosh extraient et gardent de rares cristaux aux propriétés...",kw={"la menace sombrefer plane","hinderweir","loch modan","cristal mo'grosh","mo'grosh","barrage de formepierre"},ang={["profession:Mining"]="En tant que mineur, vous pouvez voir que ces minéraux bruts viennent des profondeurs du territoire ogre. Ils réagissent de façon inhabituelle lorsqu'on les mélange à des réactifs organiques.",["race:Dwarf"]="En tant que nain, vous savez que défendre le Barrage de Formepierre demande de l'ingéniosité. Les ingénieurs nains transforment le trésor extrait par les ogres en protection contre la traîtrise Sombrefer."},sec={{t="Une denrée rare chez les ogres",b="Les ogres mo'grosh extraient les cristaux dans leur bastion, au nord-est de Loch Modan. Bien que le clan préfère la force brute au travail délicat du métal, ses membres tiennent à ces pierres. Exécutants, chamans mystiques et chefs imposants en portent. Les cristaux sont rares, alors les ogres les gardent de près dans le Bastion des Mo'grosh."},{t="Contre la menace Sombrefer",b="L'ingénieur en chef Hinderweir cherche un Cristal mo'grosh, du venin de rôdeuse et des larmes de crocolisque. Il a appris que des saboteurs Sombrefer prévoient d'attaquer le Barrage de Formepierre. Les ingénieurs nains mélangent le minéral à ces réactifs pour créer un composé qui désarme et désamorce les explosifs instables avant que la vallée ne soit inondée."}},faq={{q="D'où viennent les cristaux mo'grosh ?",a="Les ogres mo'grosh extraient et gardent les cristaux dans le nord-est de Loch Modan. N'importe quel membre du clan dans le Bastion des Mo'grosh peut en porter un, notamment les mystiques, les brutes, les exécutants et les chamans.",al={"emplacement du cristal mo'grosh","où trouver le cristal mo'grosh","qui donne le cristal mo'grosh"}},{q="À quoi sert le cristal ?",a="L'ingénieur en chef Hinderweir, au Barrage de Formepierre, a besoin d'un cristal pour préparer un mélange neutralisant. Associé à du venin de rôdeuse et à des larmes de crocolisque, il désarme les explosifs Sombrefer destinés à saboter le barrage.",al={"effet du cristal mo'grosh","utilisation du cristal mo'grosh","pourquoi hinderweir veut un cristal"}},{q="Pourquoi les ogres extraient-ils ces cristaux ?",a="Les ogres mo'grosh extraient de rares cristaux dans les collines autour de leur bastion. L'usage qu'ils en font n'est pas consigné.",al={"pourquoi les ogres ont des cristaux","histoire des cristaux ogres"}}},fx={["1713c585"]={q="Qu'est-ce qu'un Cristal mo'grosh ?",a="Un Cristal mo'grosh est un minéral exceptionnellement rare extrait par les ogres Mo'grosh dans leur bastion au nord-est de Loch Modan. Prisé pour ses propriétés inhabituelles, l'ingénieur en chef Hinderweir l'identifie comme un composant essentiel de la préparation d'un mélange spécialisé destiné à désamorcer les explosifs des Nains de Fer noir menaçant le Barrage de Formepierre.",al={"qu'est-ce qu'un cristal mo'grosh","connaissances sur le cristal mo'grosh","identité du cristal mo'grosh"}}},fp="16,170,23.326.0,31.326.1,37.180.0,29.200.0,40.119.0"}
P.entries["item:modr-fragment"] = {n="Fragment Modr",s="Au site de fouilles de Whelgar, le Fragment Modr repose parmi des reliques et de la terre meuble, dans un chantier envahi par les raptors. Son ancienne écriture des Titans comble l'une des quatre lacunes de la Pierre de Goaz.",h="Au site de fouilles de Whelgar, le Fragment Modr repose parmi des reliques et de la terre meuble, dans un...",kw={"ados","fouilles","pierre de goaz","golm","fragment modr","neru","dieux très anciens","titan","les paluns","whelgar"},ang={["faction:Alliance"]="En tant que voyageur de l'Alliance, vous aidez le Prospecteur Whelgar à braver le site de fouilles envahi et à préserver de précieuses recherches historiques pour Forgefer.",["race:Dwarf"]="En tant que nain, vous savez que la Ligue des explorateurs recherche des fragments perdus comme le Fragment Modr pour déchiffrer l'héritage des Titans et découvrir l'histoire profonde de votre peuple."},sec={{t="Un morceau de la Pierre de Goaz",b="Le Prospecteur Whelgar a découvert la Pierre de Goaz sur son site de fouilles des Paluns. Cette imposante tablette porte une ancienne écriture des Titans. Des raptors féroces ont chassé la Ligue des explorateurs du site avant que ses membres puissent achever leur travail. L'inscription traduite s'interrompt à quatre endroits, laissant inachevés des avertissements sur un plan divin et une funeste prophétie. Le Fragment Modr est l'un des morceaux manquants, abandonné parmi les reliques et la terre retournée lorsque les fouilleurs ont fui pour sauver leur vie."},{t="Secrets sous la terre",b="Le Prospecteur Whelgar peut reconstituer l'inscription complète en assemblant le Fragment Modr avec les fragments Ados, Golm et Neru. Les mots traduits racontent l'aube du monde et évoquent des « Dieux très anciens... enchaînés sous la terre ». Sous le sol marécageux, les fouilles ont mis au jour des traces d'un combat remontant aux origines du monde."}},faq={{q="Qu'est-ce que le Fragment Modr ?",a="Le Fragment Modr est un éclat de pierre gravée, détaché de la Pierre de Goaz. Le Prospecteur Whelgar a découvert cette ancienne relique des Titans au site de fouilles de Whelgar, dans les Paluns.",al={"fragment modr","qu'est-ce que modr","relique modr"}},{q="Qui cherche ce fragment ?",a="Le Prospecteur Whelgar, archéologue de la Ligue des explorateurs, cherche le Fragment Modr pour compléter le texte manquant de la tablette. Il se trouve à la lisière du site de fouilles infesté de raptors.",al={"qui cherche le fragment modr","quête du fragment de whelgar"}},{q="Que se passe-t-il lorsque les quatre fragments sont réunis ?",a="Assembler le Fragment Modr avec les fragments Ados, Golm et Neru permet au Prospecteur Whelgar de reconstituer la Pierre de Goaz. L'intégralité de son écriture des Titans évoque des « Dieux très anciens... enchaînés sous la terre ».",al={"pierre de goaz reconstituée","fin d'uncovering the past","que dit la pierre de goaz"}},{q="Où trouver le fragment ?",a="Vous trouverez le Fragment Modr éparpillé sur le site de fouilles de Whelgar, à l'est du Port de Menethil, dans les Paluns. Il se trouve dans d'anciennes urnes à reliques ou dans des amas de terre meuble gardés par des raptors agressifs.",al={"emplacement du fragment modr","où trouver modr"}}},fx={c1df2f2b={q="D'où vient le Fragment Modr et qui l'a fabriqué ?",a="Le Fragment Modr est un morceau de la Pierre de Goaz, une ancienne relique découverte sur le site de fouilles à l'est de Port de Menethil dans Les Paluns. Gravée d'inscriptions des Titans, la pierre est un artéfact des Titans, qui ont façonné le monde aux temps primordiaux et ont laissé derrière eux de mystérieux récits de leur dessein divin et de prophéties funestes.",al={"origine du fragment modr","qui a fabriqué le fragment modr","d'où vient le fragment modr"}}},fp="13,167,25.455.0,25.315.1,26.164.0,33.181.0,50.181.1,28.194.0"}
P.entries["item:moldy-tome"] = {n="Tome moisi",s="Sur la côte de Hautebrande, le Tome moisi gît, ruiné par un naufrage. Il appartenait au Tome of the Cabal et attire encore les démonistes en quête de savoir sur l’invocation des démons.",h="Sur la côte de Hautebrande, le Tome moisi gît, ruiné par un naufrage.",kw={"mine de veine-azur","chasseur corrompu","hautebrande","tome moisi","austrivage","manuscrit en lambeaux","tome of the cabal","démoniste"},ang={["class:Warlock"]="En tant que démoniste, vous recherchez le Tome moisi pour retrouver les rituels nécessaires à la maîtrise d’un chasseur corrompu."},sec={{t="Perdu dans les flots",b="Le Tome of the Cabal était un ouvrage rare consacré aux arts occultes, conservé à Lordaeron. Quelqu’un l’a vandalisé et déchiré en deux. Une moitié, désormais appelée le Tome moisi, naviguait vers le sud, en direction du Port de Menethil et de Forgefer. Le navire n’arriva jamais à destination. Il sombra dans les eaux dangereuses à l’ouest d’Austrivage, et la moitié qui survécut s’échoua au sud de la Mine de Veine-Azur. L’humidité et les vagues abîmèrent ses pages, tandis que des murlocs fouillaient la côte de Hautebrande."},{t="Récupérer l’ouvrage maudit",b="Bien que son vélin soit moisi et pourrissant, le Tome moisi renferme toujours un puissant savoir sur les démons. Les démonistes qui le convoitent bravent les campements côtiers. Krom Rudebras guide certains d’entre eux à Forgefer, tandis que Jorah Annison en guide d’autres à Fossoyeuse. Réuni à son pendant, le Manuscrit en lambeaux des grottes des Mille pointes, l’ouvrage restauré révèle les paroles précises nécessaires pour invoquer et lier un chasseur corrompu."}},faq={{q="Qu’est-ce que le Tome moisi ?",a="Le Tome moisi est une moitié du rare Tome of the Cabal, un livre sombre de rituels servant à invoquer des démons. Détrempée et délabrée, c’est la moitié qui a été perdue dans un naufrage.",al={"livre moisi","qu’est-ce que cet objet","histoire du tome moisi"}},{q="Où le Tome moisi a-t-il échoué ?",a="Le Tome moisi s’est échoué dans les Contreforts de Hautebrande, à l’ouest d’Austrivage et au sud de la Mine de Veine-Azur. Des murlocs de la côte le gardent dans leur campement.",al={"emplacement du tome moisi","où se trouve le tome moisi","où trouver le tome moisi"}},{q="Pourquoi le tome se trouvait-il sur un navire ?",a="Un navire transportait le Tome moisi depuis Lordaeron vers le Port de Menethil, à destination des érudits de Forgefer. Il sombra au large de la côte de Hautebrande avant d’achever son voyage.",al={"pourquoi a-t-il été perdu en mer","tome naufragé","transport du tome"}},{q="Que faut-il pour compléter le Tome of the Cabal ?",a="Pour compléter le Tome of the Cabal, il faut réunir le Tome moisi et le Manuscrit en lambeaux, son autre moitié. Le manuscrit a échoué au Bastion du Sabot fendu, dans les Mille pointes.",al={"autre moitié du tome","pages manquantes","parties du tome of the cabal"}}},fx={f96f31c9={q="D'où vient le Tome moisi ?",a="Le Tome moisi faisait à l'origine partie d'un volume unique connu sous le nom de Tome of the Cabal, autrefois conservé dans les grandes salles de Lordaeron. Il y a longtemps, le grimoire unique fut vandalisé et une partie substantielle de son parchemin fut arrachée de la reliure. La partie survivante du livre devait être expédiée vers le sud, depuis Hautebrande, à travers la mer vers Port de Menethil et Forgefer, mais le navire qui la transportait fit naufrage le long de la côte à l'ouest d'Austrivage, laissant les pages humides pourrir dans les eaux peu profondes.",al={"origine du tome moisi","qui a créé le tome moisi","où était conservé le tome moisi","histoire du tome moisi"}},["53a1a6b9"]={q="Pourquoi quelqu'un voudrait-il le Tome moisi ?",a="Les érudits et les pratiquants des arts obscurs le recherchent car une seule copie du Tome of the Cabal a jamais été écrite. Ses passages arcaniques contiennent des connaissances démonistes rares et étroitement gardées, y compris des secrets essentiels pour maîtriser l'invocation et le lien des chasseurs corrompus. Des érudits comme Krom Rudebras à Forgefer et Jorah Annison à Fossoyeuse convoitent même un bref aperçu de son texte interdit, rendant la récupération de ce vestige détrempé essentielle pour réunir l'ouvrage complet.",al={"pourquoi trouver le tome moisi","qui veut le tome moisi","pourquoi le tome moisi est-il important","pourquoi les démonistes veulent le tome moisi"}}},fp="10,171,17.420.0,24.412.1,23.159.0,32.145.0,27.166.0,49.169.0"}
P.entries["item:monstrous-crawler-leg"] = {n="Monstrous Crawler Leg",s="Une Patte de clampant monstrueux provient des immenses Monstrous Crawlers du littoral du Marais des Chagrins. Dar en cherche dix pour ses clients d’Orgrimmar, qui raffolent de leur viande.",h="Une Patte de clampant monstrueux provient des immenses Monstrous Crawlers du littoral du Marais des Chagrins.",kw={"viande de monstrous crawler","dar","monstrous crawler","patte de clampant monstrueux","orgrimmar","marais des chagrins"},sec={{t="Spécialités du littoral",b="Dar, dans le Marais des Chagrins, veut dix Pattes de clampant monstrueux pour ses clients d’Orgrimmar. Les créatures courent le long des plages de l’est et sous la mer. Leur viande est prisée pour son goût savoureux, et Dar compte la faire expédier vers le nord."}},faq={{q="D’où viennent les Pattes de clampant monstrueux ?",a="Les Pattes de clampant monstrueux proviennent des Monstrous Crawlers qui vivent le long des plages et sous la mer, sur le littoral du Marais des Chagrins.",al={"origine des pattes de clampant","où trouver des pattes monstrueuses"}},{q="Qui veut ces pattes ?",a="Dar, dans le Marais des Chagrins, veut dix Pattes de clampant monstrueux à envoyer à ses clients d’Orgrimmar.",al={"qui veut des pattes de clampant","pattes de dar"}},{q="Pourquoi Dar les veut-il ?",a="Les clients de Dar raffolent du goût savoureux de la viande de Monstrous Crawler, surtout de celle des Monstrous Crawlers.",al={"pourquoi des pattes de clampant","à quoi servent les pattes"}},{q="Où se trouve la côte ?",a="La côte se trouve à l’est de Dar, dans le Marais des Chagrins. Les Monstrous Crawlers courent le long de ses plages et sous la mer.",al={"direction de la côte du marais","plage des monstrous crawlers"}}},fp="21,148,12.239.0,42.120.0,21.95.0,23.103.0,19.116.0"}
P.entries["item:moonpetal-lily"] = {n="Lys pétale de lune",s="Autour des bassins d’eau douce de Teldrassil, les Lys pétales de lune offrent des pétales réputés pour leurs vertus réparatrices. Les soigneurs les utilisent dans des remèdes et des potions de soins.",h="Autour des bassins d’eau douce de Teldrassil, les Lys pétales de lune offrent des pétales réputés pour leurs...",kw={"aldrassil","antidote","dirania brillargent","iverron","pétale de lune","lys pétale de lune","sombrevallon","teldrassil"},ang={["profession:Herbalism"]="Lorsqu’une crise exige d’agir vite, les soigneurs cueillent les Lys pétales de lune à la main. Ces fleurs témoignent des vertus réparatrices des plantes de Teldrassil.",["race:NightElf"]="Jeune kaldorei en formation à Sombrevallon, vous apprenez que les plantes locales comme le Lys pétale de lune peuvent soigner. C’est une première leçon pour vivre en harmonie avec la nature."},sec={{t="La flore des bassins",b="Les Lys pétales de lune poussent sur les berges humides des bassins et des mares d’eau douce. Ils sont fréquents au nord-ouest d’Aldrassil, à Sombrevallon. Comme les autres plantes qui poussent au sommet du jeune Arbre-Monde, ils puisent dans l’essence des bosquets abrités de Teldrassil. Leurs larges pétales brillent au bord de l’eau, où l’humidité leur permet de prospérer."},{t="Des antidotes naturels",b="Les soigneurs et herboristes elfes de la nuit apprécient les Lys pétales de lune pour leurs propriétés curatives. Mélangés à des plantes de la forêt comme les Hyacinth Mushrooms, ils contribuent à apaiser et à stabiliser. Les soigneurs en tirent des antidotes contre les toxines mortelles, notamment le venin des araignées Tissebois de la Grotte de Sombrefil."}},faq={{q="Où poussent les Lys pétales de lune ?",a="Les Lys pétales de lune poussent sur les berges de deux mares d’eau douce au nord-ouest d’Aldrassil, à Sombrevallon, sur Teldrassil.",al={"où trouver les lys pétales de lune","emplacement du lys pétale de lune","lieux où trouver les lys"}},{q="À quoi servent les Lys pétales de lune ?",a="Les Lys pétales de lune ont des vertus réparatrices et curatives. À Sombrevallon, Dirania Brillargent les associe à des Hyacinth Mushrooms et à de l’Ichor d’araignée Tissebois pour préparer un antidote contre le venin d’araignée.",al={"utilisations du lys pétale de lune","à quoi sert le lys pétale de lune"}},{q="Qui a besoin d’un antidote préparé avec ces lys ?",a="Iverron est un elfe de la nuit mordu par des araignées Tissebois près de la Grotte de Sombrefil. Pour survivre, il a besoin d’un antidote préparé avec des Lys pétales de lune.",al={"pour qui est l’antidote","poison d’iverron"}},{q="Les Lys pétales de lune poussent-ils ailleurs qu’à Teldrassil ?",a="Les Lys pétales de lune poussent autour des bassins isolés de Teldrassil. On les connaît dans les frondaisons abritées de Sombrevallon.",al={"les lys poussent-ils ailleurs","lys pétale de lune dans d’autres zones"}}},fx={["1aae6896"]={q="Qu'est-ce qu'un Lys pétale de lune ?",a="Le Lys pétale de lune est une grande fleur aquatique originaire des eaux tranquilles de Teldrassil. Réputé pour ses puissantes propriétés curatives naturelles, il s'épanouit dans un sol humide le long des bords des étangs et des mares forestières ombragées, comme ceux nichés près d'Aldrassil à Sombrevallon.",al={"qu'est-ce qu'un lys pétale de lune","infos sur le lys pétale de lune","à propos du lys pétale de lune"}}},fp="14,156,18.314.0,17.289.0,31.114.0,35.186.0,45.132.0,55.110.0"}
P.entries["item:moonstalker-fang"] = {n="Croc de traquelune",s="Près d’Auberdine, les voyageurs récoltent des Crocs de traquelune pour les appareils d’échantillonnage de Crackboum Tournelevier. Ces dents viennent des traqueurs des brumes de Sombrivage.",h="Près d’Auberdine, les voyageurs récoltent des Crocs de traquelune pour les appareils d’échantillonnage de...",kw={"buzzbox 323","sombrivage","traqueur des brumes","croc de traquelune","shadowclaw","crackboum tournelevier"},ang={["class:Hunter"]="En tant que chasseur, vous devez aiguiser vos sens pour affronter les traqueurs des brumes, des prédateurs qui tendent des embuscades et se fondent dans la canopée sombre de Sombrivage.",["race:Gnome"]="En tant que gnome, vous reconnaîtrez peut-être l’ingénierie gnome dans les appareils de communication à distance de Crackboum Tournelevier. Son élocution pâteuse et ses choix d’échantillons inhabituels font tout de même sourciller."},sec={{t="Un mécanisme de broyage",b="Les Crocs de traquelune proviennent de félins à dents de sabre qui chassent aux lisières forestières de Sombrivage. Leurs longues dents peuvent trancher la chair et les os. Crackboum Tournelevier, un gnome bricoleur excentrique, leur donne un autre usage. Au nord d’Auberdine, près du pont, Buzzbox 323 broie ces crocs résistants en fine poussière pour ses études écologiques."}},faq={{q="D’où viennent les Crocs de traquelune ?",a="Les Crocs de traquelune viennent des traqueurs des brumes de Sombrivage, des petits et des adultes jusqu’aux mâles dominants, aux matriarches et au rôdeur Shadowclaw.",al={"où trouver des crocs de traquelune","qui donne des crocs de traquelune","origine des crocs"}},{q="Qui veut des Crocs de traquelune ?",a="Crackboum Tournelevier a besoin de six Crocs de traquelune pour Buzzbox 323, son dispositif de surveillance automatisé au nord d’Auberdine, près du pont sur la rivière.",al={"qui a besoin de crocs","quelle quête utilise des crocs","remettre les crocs à buzzbox 323"}},{q="Que deviennent les crocs dans la machine ?",a="Les engrenages de Buzzbox 323 réduisent les crocs durs en fine poussière pour les expériences de terrain de Crackboum Tournelevier.",al={"que fait buzzbox 323","pourquoi broyer les crocs"}}},fx={fbcb9ad4={q="Qu'est-ce qu'un Croc de traquelune ?",a="Un Croc de traquelune est une canine prédatrice acérée prélevée sur les traquelunes prédateurs qui errent dans les forêts brumeuses de Sombrivage. Ces chats à dents de sabre nocturnes utilisent leurs crocs redoutables pour chasser le gibier des bois, ce qui en fait des trophées prisés et un matériau étonnamment durable pour des engins locaux particuliers.",al={"croc de traquelune","que sont les crocs de traquelune","dents de traquelune"}}},fp="16,140,20.312.0,37.125.0,28.138.0,45.88.0"}
P.entries["item:moonwell-water-tube"] = {n="Tube d'eau du Puits de lune",s="À Auberdine, l’eau du puits de lune porte une magie naturelle purificatrice. Le tube sert à tester un mystérieux cristal rouge dans les crêtes orientales de Sombrivage.",h="À Auberdine, l’eau du puits de lune porte une magie naturelle purificatrice.",kw={"as water cascades","auberdine","sombrivage","tube d'eau vide","gangrebois","tube d'eau du puits de lune","cristal rouge"},ang={["class:Druid"]="Les druides savent que l’eau des puits de lune est un réceptacle essentiel de l’équilibre naturel, capable de contrer la corruption contre nature.",["race:NightElf"]="Pour les Elfes de la nuit, sonder une corruption étrangère avec l’eau bénite d’un puits de lune témoigne de leur confiance en la grâce d’Elune, qui révèle les vérités cachées."},sec={{t="Un réceptacle d’eaux purificatrices",b="L’eau du puits de lune d’Auberdine remplit le tube. Ce bassin sacré est lié à Elune et possède une magie réparatrice et purificatrice. Même en petite quantité, elle peut contrer la corruption ou servir à tester d’étranges forces mystiques."},{t="À l’étude du cristal rouge",b="Les chercheurs ont préparé le tube pour tester un immense cristal rouge apparu le long de la falaise orientale de Sombrivage. Les hauteurs corrompues de Gangrebois dominent la paroi montagneuse, et ils craignaient que le cristal ne partage cette sombre origine. Lorsque l’eau bénite ruisselle sur ses facettes, la pierre opaque devient brièvement transparente et révèle les mystères qu’elle renferme."}},faq={{q="D’où vient l’eau ?",a="L’eau provient du puits de lune sacré d’Auberdine, le refuge des Elfes de la nuit sur la côte occidentale de Sombrivage.",al={"où remplir le tube","origine de l’eau du tube","eau du puits de lune d’auberdine"}},{q="Pourquoi utiliser l’eau du puits de lune sur le cristal rouge ?",a="L’eau du puits de lune porte une magie naturelle et lunaire concentrée. Versée sur le mystérieux cristal rouge, elle permet d’éprouver sa nature mystique et clarifie brièvement sa surface opaque.",al={"pourquoi l’eau du puits de lune","utilité du tube d’eau","effet de l’eau"}},{q="Pourquoi les chercheurs s’inquiètent-ils du cristal ?",a="Le cristal se trouve sous les montagnes orientales qui bordent Gangrebois. Sa profonde souillure démoniaque a fait craindre aux érudits que cette formation étrangère ne répande la corruption jusqu’à Sombrivage.",al={"pourquoi tester le cristal","danger du cristal rouge","lien avec gangrebois"}}},fx={f51af5d3={q="Qu'est-ce que le Tube d'eau du Puits de lune ?",a="Le Tube d'eau du Puits de lune est une simple fiole en verre remplie d'eau bénite puisée directement au puits de lune d'Auberdine. Les puits de lune renferment une magie sacrée puissante nourrie par les druides et les prêtresses elfes de la nuit, rendant le liquide à l'intérieur bien plus qu'une simple eau de source. Le transporter permet aux chercheurs d'apporter une petite mesure concentrée du pouvoir purificateur d'Élune sur le terrain pour tester des phénomènes inconnus.",al={"qu'est-ce que le tube d'eau du puits de lune","objet tube d'eau du puits de lune","qu'est-ce que ce tube d'eau"}},["21e1d317"]={q="Pourquoi le Tube d'eau du Puits de lune est-il nécessaire ?",a="Les enquêteurs d'Auberdine ont besoin du Tube d'eau du Puits de lune pour analyser un cristal rouge inquiétant incrusté le long des montagnes orientales de Sombrivage. Parce que l'on soupçonne le cristal de partager un lien obscur avec le Gangrebois corrompu situé plus haut, les chercheurs pensent que verser la magie pure et puissante du puits de lune sur sa surface réagira sans danger avec la pierre et révélera sa composition interne.",al={"pourquoi ai-je besoin du tube d'eau du puits de lune","pourquoi vouloir l'eau du puits de lune","but du tube d'eau du puits de lune"}}},fp="19,146,28.203.0,29.339.1,30.106.0,42.174.0,52.175.0"}
P.entries["item:mossy-tumor"] = {n="Tumeur moussue",s="Autour du lac d’Aigue-vive, des tumeurs moussues se répandent sur les sylveniers de Teldrassil. Prélevées sur leur écorce et leur chair, ces excroissances toxiques révèlent la corruption qui s’empare du jeune Arbre-Monde.",h="Autour du lac d’Aigue-vive, des tumeurs moussues se répandent sur les sylveniers de Teldrassil.",kw={"corruption","darnassus","tumeur moussue","rellian greenspyre","teldrassil","sylvenier","lac d'aigue-vive"},ang={["class:Druid"]="En tant que druide voué à l’équilibre de la nature, vous pouvez voir dans des tumeurs toxiques sur des gardiens végétaux comme les sylveniers un signe inquiétant. Quelque chose ne va vraiment pas sur Teldrassil.",["race:NightElf"]="En tant qu’Elfe de la nuit, vous savez que votre peuple a planté Teldrassil pour renouer le lien perdu avec la nature. Des excroissances maladives sur votre nouveau foyer sont un présage inquiétant."},sec={{t="Un symptôme du mal de Teldrassil",b="Les sylveniers de Teldrassil veillaient autrefois sur les branches du grand arbre. Beaucoup sont désormais hostiles et malades, et leurs tumeurs moussues témoignent clairement de leur mal. Gorgées de toxines, ces excroissances couvrent les Bêtes des bourbiers, les Écraseurs et les Vieux sylveniers autour du lac d’Aigue-vive. Rellian Greenspyre et les gardiens de Darnassus envoient des voyageurs les couper et les brûler entièrement. Leur poison ne doit pas s’enraciner plus profondément dans le sol de l’île."}},faq={{q="Qu’est-ce qu’une tumeur moussue ?",a="Une tumeur moussue est une excroissance malade prélevée sur un sylvenier corrompu. Son poison révèle qu’une corruption contre nature afflige les esprits de la nature de Teldrassil.",al={"tumeur moussue","qu’est-ce que cette tumeur","tumeur de sylvenier"}},{q="Où trouve-t-on des tumeurs moussues ?",a="Vous trouverez des tumeurs moussues sur les sylveniers corrompus autour du lac d’Aigue-vive, dans le nord de Teldrassil. Elles poussent sur les Écraseurs sylveniers, les Bêtes des bourbiers et les Vieux sylveniers.",al={"où trouver des tumeurs","butin de tumeur moussue","emplacement des sylveniers"}},{q="Pourquoi Rellian Greenspyre veut-il ces tumeurs ?",a="Rellian Greenspyre rassemble les tumeurs pour contenir la corruption qui afflige Teldrassil. Il les fait réduire en cendres afin que leur poison concentré ne s’infiltre pas de nouveau dans le sol et l’eau.",al={"tumeurs de rellian greenspyre","pourquoi brûler les tumeurs"}},{q="Pourquoi les sylveniers tombent-ils malades ?",a="Une malveillance s’empare de Teldrassil et déforme ses gardiens comme ses créatures sauvages. Les Elfes de la nuit enquêtent sur la véritable origine de la maladie, tandis que les sylveniers portant des tumeurs visibles sont considérés comme irrécupérables.",al={"pourquoi les sylveniers sont malades","corruption des sylveniers"}}},fp="11,189,33.427.0,22.149.0,31.164.0,46.184.0,42.220.0"}
P.entries["item:mountain-lion-blood"] = {n="Sang de lion des montagnes",s="Dans Hautebrande et les Montagnes d’Alterac, l’Apothicaire Lydon cherche du Sang de lion des montagnes. Au Moulin-de-Tarren, il lui faut du sang frais pour l’Elixir de douleur de la Société royale des apothicaires.",h="Dans Hautebrande et les Montagnes d’Alterac, l’Apothicaire Lydon cherche du Sang de lion des montagnes.",kw={"alterac","apothicaire lydon","elixir de douleur","hautebrande","sang de lion des montagnes","société royale des apothicaires","moulin-de-tarren"},ang={["faction:Horde"]="En tant que membre de la Horde, récolter des réactifs de bêtes autour du Moulin-de-Tarren renforce votre présence face aux enclaves humaines hostiles de Hautebrande.",["race:Undead"]="En tant que Mort-vivant, chaque fiole récoltée aide la Société royale des apothicaires à mettre au point des armes biologiques pour assurer aux Réprouvés le contrôle de Lordaeron."},sec={{t="Réactif des collines",b="Les lions des montagnes chassent dans les hautes terres et les contreforts de Hautebrande et d’Alterac. Les chasseurs convoitent leurs peaux et leurs griffes, tandis que les Réprouvés de la Société royale des apothicaires recherchent le sang qui coule dans leurs veines. L’Apothicaire Lydon, au Moulin-de-Tarren, pense que le sang frais de lion des montagnes peut servir de base à une puissante mixture. Il veut qu’elle apporte la misère aux vivants."},{t="Au service de The New Plague",b="Les travaux de l’Apothicaire Lydon au Moulin-de-Tarren soutiennent les efforts de la Société royale des apothicaires pour perfectionner The New Plague des Réprouvés. Il recueille le sang de bêtes sauvages vigoureuses afin d’affiner une concoction appelée l’Elixir de douleur. Ses expériences cherchent à déterminer comment retourner des composés organiques locaux contre les ennemis de la Dame noire."}},faq={{q="À quoi sert le Sang de lion des montagnes ?",a="L’Apothicaire Lydon, au Moulin-de-Tarren, a besoin de dix fioles de Sang de lion des montagnes pour l’Elixir de douleur. La Société royale des apothicaires étudie de nouvelles maladies.",al={"à quoi sert le sang de lion des montagnes","qui a besoin de sang de lion","sang pour l’élixir de douleur"}},{q="Où peut-on récolter le Sang de lion des montagnes ?",a="Vous pouvez récolter du Sang de lion des montagnes sur les lions qui chassent dans les Contreforts de Hautebrande et les crêtes enneigées des Montagnes d’Alterac voisines.",al={"où trouver du sang de lion des montagnes","emplacement du sang de lion des montagnes","quels lions donnent du sang"}},{q="Pourquoi l’Apothicaire Lydon veut-il précisément du sang de félin sauvage ?",a="Lydon pense que les fluides vitaux de lions des montagnes robustes et agressifs peuvent servir à préparer une mixture toxique. Il veut qu’elle inflige de grandes souffrances aux habitants vivants de Hautebrande.",al={"pourquoi du sang de lion","pourquoi lydon veut-il du sang de lion"}},{q="Le Sang de lion des montagnes sert-il dans les recettes d’alchimie ?",a="Non. Le Sang de lion des montagnes est un réactif expérimental utilisé dans les travaux de l’Apothicaire Lydon, pas un ingrédient des recettes d’alchimie habituelles.",al={"les alchimistes peuvent-ils utiliser le sang de lion des montagnes","le sang de lion sert-il en alchimie"}}},fx={dcf44a54={q="Qu'est-ce que le Sang de lion des montagnes ?",a="Il s'agit de sang frais récolté sur les lions des montagnes prédateurs rôdant sur les pentes escarpées des Contreforts de Hautebrande et des Montagnes d’Alterac. Bien qu'inutile pour les alchimistes ou les commerçants ordinaires, il possède des qualités biologiques prisées par la Société royale des apothicaires pour leurs expériences alchimiques mortelles.",al={"qu'est-ce que le sang de lion des montagnes","connaissances sur le sang de lion des montagnes","qu'est-ce que ce sang"}},["7c379830"]={q="D'où vient le Sang de lion des montagnes et qui l'a créé ?",a="Il n'est ni fabriqué ni manufacturé, mais prélevé directement sur les félins sauvages indigènes du nord de Lordaeron. Les lions des montagnes qui errent dans les hautes terres entre Hautebrande et Alterac sont chassés et saignés par des agents travaillant pour le compte des apothicaires Réprouvés stationnés au Moulin-de-Tarren.",al={"d'où vient le sang de lion des montagnes","source du sang de lion des montagnes","qui a créé le sang de lion des montagnes"}}},fp="19,159,20.341.0,22.323.0,37.145.0,43.138.0,59.159.0,59.128.0"}
P.entries["item:muddy-journal-pages"] = {n="Pages de journal maculées de boue",s="Les Pages de journal maculées de boue furent retrouvées il y a des années sur une scène de meurtre dans le Bois de la Pénombre. Usées par le temps et tachées de terre, elles sont toujours conservées par Smitts l'aubergiste, qui les a gardées comme pièce à conviction dans une enquête locale non résolue, sans preuve de leur auteur.",h="Les Pages de journal maculées de boue furent retrouvées il y a des années sur une scène de meurtre dans le...",kw={"sombre-comté","bouclenoire","haggard","pages de journal maculées de boue","smitts"},ang={["class:Rogue"]="En tant que Voleur, reconstituer des échantillons d'écriture oubliés et des fragments de journal usés montre le travail méthodique d'enquête nécessaire avant d'abattre un tueur caché.",["faction:Alliance"]="Pour l'Alliance, résoudre le massacre de nobles de Hurlevent apporte enfin une conclusion à une vieille affaire dans les villages assiégés du Bois de la Pénombre."},sec={{t="Les preuves du massacre",b="Smitts l'aubergiste trouva les pages dans la fange après le massacre de nobles en visite dans le Bois de la Pénombre. Il s'était rendu sur les lieux avec Haggard, l'enquêteur. La ville ne disposait ni d'échantillons d'écriture ni de documents confirmés permettant de relier le texte à un suspect, alors Smitts conserva discrètement les pages dans l'auberge de Sombre-Comté. Il attendit qu'un enquêteur rassemble des documents épars venus des royaumes du sud et compare l'écriture à celle du reclus vivant au plus profond des bois."}},faq={{q="Où les pages de journal maculées de boue ont-elles été trouvées ?",a="Smitts l'aubergiste et Haggard trouvèrent les pages sur les lieux du massacre de nobles en visite, dans les bois du Bois de la Pénombre, plusieurs années auparavant.",al={"où smitts a-t-il trouvé les pages","origine des pages maculées","lieu où trouver le journal maculé"}},{q="Pourquoi Smitts ne pouvait-il pas utiliser les pages lorsqu'il les a trouvées ?",a="Les enquêteurs locaux n'avaient aucun échantillon d'écriture à comparer aux pages et ne pouvaient donc pas relier l'écriture à un suspect.",al={"pourquoi garder les pages secrètes","pourquoi smitts ne les a-t-il pas remises","problème de preuves de smitts"}},{q="À qui faut-il remettre ces pages ?",a="Les pages doivent être remises à la Commandant Althea Bouclenoire, cheffe des Veilleurs à Sombre-Comté, afin de rendre compte de l'enquête sur le massacre des nobles.",al={"à qui remettre les pages maculées","remettre les pages de journal maculées","pages maculées bouclenoire"}},{q="À quel crime ces pages sont-elles liées ?",a="Les pages sont liées au massacre de nobles en visite dans les bois du Bois de la Pénombre, plusieurs années auparavant, un crime que Sombre-Comté n'avait pas pu résoudre à l'époque.",al={"quel massacre","qu'a fait stalvan","massacre de nobles en visite"}}},fx={["7e79311d"]={q="Que sont les Pages de journal maculées de boue ?",a="Il s'agit de feuilles de journal souillées et déchirées, récupérées il y a des années sur le site d'un massacre brutal de nobles en visite dans le Bois de la Pénombre. Écrites par Stalvan Mantebrume, elles documentent sa déchéance et fournissent la preuve écrite longtemps recherchée de sa présence et de sa folie sur les lieux du carnage.",al={"que sont les pages de journal maculées de boue","pages de journal maculées de boue","qu'est-ce que cet objet"}},bcc5553e={q="D'où viennent les Pages de journal maculées de boue et qui les a écrites ?",a="Elles ont été écrites par Stalvan Mantebrume et abandonnées dans la boue lorsque les nobles ont été assassinés. Smitts l'aubergiste et Haggard les ont découvertes alors qu'ils enquêtaient sur le bain de sang, mais Smitts les a gardées pendant des années car il manquait d'échantillons d'écriture pour confirmer qui les avait rédigées.",al={"qui a écrit les pages de journal maculées de boue","d'où viennent les pages maculées","auteur des pages de journal maculées de boue"}},f7c3dc88={q="Pourquoi le Commandant Bouclenoire a-t-il besoin des Pages de journal maculées de boue ?",a="Le Commandant Althea Bouclenoire supervise la défense de Sombre-Comté et nécessite une preuve définitive avant d'agir contre la menace dans les bois. Associées aux preuves d'écriture que vous avez rassemblées à travers le royaume, ces pages établissent la culpabilité de Stalvan sans l'ombre d'un doute et poussent les Veilleurs à enfin s'occuper de lui.",al={"pourquoi apporter les pages à ebonlocke","qui veut les pages de journal maculées de boue","pourquoi les pages maculées sont-elles importantes"}}},fp="19,238,28.458.1,41.141.0,59.129.0,29.152.1,37.144.0"}
P.entries["item:muddy-note"] = {n="Muddy Note",s="Une note boueuse et presque illisible, trouvée parmi les biens d’un coffre-fort. Les détails qu’elle contient sur les patrouilles du Soldat Thorsen pourraient aider le Lieutenant Doren à démasquer un traître au Camp rebelle.",h="Une note boueuse et presque illisible, trouvée parmi les biens d’un coffre-fort.",kw={"lieutenant doren","note boueuse","soldat thorsen","camp rebelle","vallée de strangleronce","coffre-fort","traître"},sec={{t="La Note gribouillée",b="Les itinéraires de patrouille et les habitudes du Soldat Thorsen sont consignés dans une note boueuse trouvée dans un coffre-fort de la Vallée de Strangleronce. Elle indique aussi à qui il parle parmi les rebelles. L’écriture est difficile à déchiffrer, mais le Lieutenant Doren a besoin de cette note pour trouver le traître."}},faq={{q="Que dit la note boueuse ?",a="La note consigne les itinéraires de patrouille du Soldat Thorsen, ses conversations et la façon dont il passe son temps avec les rebelles. Son écriture est presque illisible.",al={"contenu de la note","détails de la note boueuse","note de thorsen"}},{q="Où dois-je apporter la note ?",a="Apportez la note boueuse au Lieutenant Doren, au Camp rebelle.",al={"qui veut la note","où l’apporter","note de doren"}},{q="Qui a écrit la note ?",a="La note est signée de la seule lettre M. Elle ne révèle pas le nom de son auteur.",al={"qui l’a signée","auteur de la note","qui est m"}},{q="Pourquoi la note est-elle importante ?",a="La note montre que son auteur connaissait les habitudes et les relations du Soldat Thorsen. Le Lieutenant Doren en a besoin comme indice pour trouver le traître parmi les rebelles.",al={"pourquoi doren en a besoin","indice sur le traître","à quoi sert la note"}}},fp="10,172,18.252.0,29.145.0,25.54.0,19.85.0,26.152.0"}
P.entries["item:mudsnout-blossom"] = {n="Mudsnout Blossom",s="À la Ferme des Nethander, les spores et la chair des Mudsnout Blossom empoisonnent les êtres vivants. Les gnolls Mudsnout gardent les champignons, qu'Apothicaire Lydon recherche pour ses travaux sur les élixirs.",h="À la Ferme des Nethander, les spores et la chair des Mudsnout Blossom empoisonnent les êtres vivants.",kw={"apothicaire lydon","elixir of agony","contreforts de hautebrande","mudsnout blossom","gnolls mudsnout","ferme des nethander","moulin-de-tarren"},ang={["profession:Herbalism"]="En tant qu'herboriste, vous pourriez vous attendre à trouver une fleur, mais la Mudsnout Blossom est un champignon volatil et nauséabond, recherché par les toxicologues et les alchimistes des ténèbres.",["race:Undead"]="En tant que Réprouvé, vous savez que la Société royale des apothicaires récolte les Fleurs de fangemufle pour leurs propriétés toxiques et pour perfectionner des armes biochimiques."},sec={{t="Un champignon toxique",b="Au sud du Moulin-de-Tarren, les Fleurs de fangemufle poussent à la Ferme des Nethander. Leur nom évoque des fleurs, mais ce sont de gros champignons nauséabonds. Ils prospèrent dans la terre souillée des campements des gnolls Mudsnout, qui défendent farouchement ce territoire. Leurs spores et leur chair empoisonnent les êtres vivants, provoquant l'agonie et une décomposition rapide du corps."},{t="Au service de la Société royale des apothicaires",b="À Moulin-de-Tarren, Apothicaire Lydon utilise les Fleurs de fangemufle dans ses expériences chimiques. Dame Sylvanas Coursevent a chargé la Société royale des apothicaires de créer un fléau capable d'éradiquer à la fois le Fléau et l'humanité vivante. Les champignons dessèchent la chair par leur poison caustique, ce qui en fait la base de l'Elixir of Agony de Lydon."}},faq={{q="Qu'est-ce qu'une Mudsnout Blossom ?",a="Malgré leur nom, les Fleurs de fangemufle sont de gros champignons nauséabonds et toxiques que l'on trouve dans les sols humides des Contreforts de Hautebrande.",al={"histoire de la mudsnout blossom","la mudsnout blossom est-elle une fleur","quel type de plante est la mudsnout blossom"}},{q="Où poussent les Fleurs de fangemufle ?",a="Les Fleurs de fangemufle poussent dans toute la Ferme des Nethander, une ferme abandonnée au sud du Moulin-de-Tarren et à l'est de la rivière qui passe près d'Austrivage. Les gnolls Mudsnout infestent largement la région.",al={"emplacement de la mudsnout blossom","où trouver les fleurs de fangemufle","champignons de la ferme des nethander"}},{q="Pourquoi la Société royale des apothicaires les récolte-t-elle ?",a="Apothicaire Lydon, au Moulin-de-Tarren, a besoin de Fleurs de fangemufle pour préparer l'Elixir of Agony. Les Réprouvés étudient les toxines pour contribuer à créer un fléau capable d'anéantir les êtres vivants comme le Fléau.",al={"pourquoi lydon veut-il des fleurs de fangemufle","ingrédients de l'elixir of agony","champignon apothicaire lydon"}},{q="Que fait la Société royale des apothicaires avec les fleurs ?",a="Apothicaire Lydon récolte ces champignons nauséabonds pour préparer son prochain élixir. Ils entrent dans les recherches des Réprouvés sur les maladies et les poisons.",al={"expériences sur la mudsnout blossom","utilisation des fleurs dans les élixirs"}}},fx={f0998bd9={q="D'où viennent les Fleurs de fangemufle ?",a="Les Fleurs de fangemufle sont de gros champignons à l'odeur fétide qui poussent dans les champs de la Ferme des Nethander, dans le sud des Contreforts de Hautebrande. Ils prospèrent autour des gnolls Fangemufle locaux qui y habitent et gardent farouchement la zone, bien qu'il soit incertain si les gnolls cultivent intentionnellement les champignons piquants ou s'ils nichent simplement parmi eux.",al={"origine de la fleur de fangemufle","d'où viennent les fleurs de fangemufle","qui a créé la fleur de fangemufle"}}},fp="16,166,14.327.0,37.322.1,27.124.0,32.184.0,52.183.0,60.137.0"}
P.entries["item:mudsnout-composite"] = {n="Poudre de fangemufle",s="À Moulin-de-Tarren, la Poudre de fangemufle est destinée à la recherche d'une nouvelle peste. L'Apothicaire Lydon la prépare avec des Fleurs de fangemufle cueillies dans les Contreforts de Hautebrande, puis l'envoie à Fossoyeuse.",h="À Moulin-de-Tarren, la Poudre de fangemufle est destinée à la recherche d'une nouvelle peste.",kw={"l'apothicarium","apothicaire lydon","elixir of agony","maître apothicaire faranell","mudsnout blossom","poudre de fangemufle","société royale des apothicaires"},ang={["profession:Herbalism"]="En tant qu'herboriste, vous voyez comment un apothicaire broie des Fleurs de fangemufle pour en faire une arme.",["race:Undead"]="En tant que mort-vivant, vous savez que chaque cargaison de Poudre de fangemufle sert les desseins de la Dame noire : assurer l'avenir des Réprouvés grâce à une peste contre les vivants et le Fléau."},sec={{t="Une base pour le pourrissement",b="L'Apothicaire Lydon prépare la Poudre de fangemufle avec des Fleurs de fangemufle cueillies dans les Contreforts de Hautebrande. La pâte est nocive à elle seule. Maître apothicaire Faranell la lie à un colloïde de pourrissement, révélant ainsi ses propriétés les plus meurtrières. Ensemble, les ingrédients forment un composant chimique essentiel de l'Elixir of Agony de la Dame noire."},{t="Correspondance des apothicaires",b="La Société royale des apothicaires reçoit la Poudre de fangemufle à l'Apothicarium de Fossoyeuse, après son transport depuis Moulin-de-Tarren. Les chercheurs de terrain récoltent des réactifs dans différentes régions et envoient des échantillons aux maîtres de la capitale pour les raffiner. Dame Sylvanas exige des résultats rapides contre les humains vivants et le Fléau. Faranell loue la poudre, qui constitue un travail préparatoire ingénieux vers leur objectif."}},faq={{q="À quoi sert la Poudre de fangemufle ?",a="La Poudre de fangemufle est une pâte préparée à partir de Fleurs de fangemufle. À Fossoyeuse, Maître apothicaire Faranell la traite avec un colloïde de pourrissement pour contribuer à la formulation de l'Elixir of Agony.",al={"utilité de la poudre de fangemufle","effet de la poudre de fangemufle"}},{q="Qui a créé cette poudre ?",a="L'Apothicaire Lydon a créé la poudre à Moulin-de-Tarren, dans les Contreforts de Hautebrande. Lydon broie des fleurs fraîches pour en faire une pâte avant de l'envoyer vers le nord.",al={"créateur de la poudre de fangemufle","qui a créé la poudre de fangemufle"}},{q="Pourquoi Maître apothicaire Faranell en a-t-il besoin ?",a="Maître apothicaire Faranell a besoin de cette poudre pour les recherches de la Société royale des apothicaires sur une nouvelle peste. La pâte de Lydon fournit la base végétale de leurs recherches sur les toxines mortelles.",al={"pourquoi l'apporter à faranell","faranell et fangemufle"}}},fx={["432a2438"]={q="Qu'est-ce que la Poudre de fangemufle ?",a="La Poudre de fangemufle est un mélange raffiné concocté par l'Apothicaire Lydon au Moulin-de-Tarren. Fabriquée en broyant de rares Fleurs de fangemufle trouvées dans les Contreforts de Hautebrande, cette substance puissante sert de base alchimique essentielle dans les recherches de la Société royale des apothicaires pour concevoir une nouvelle peste dévastatrice pour les Réprouvés.",al={"poudre de fangemufle","qu'est-ce que la poudre de fangemufle","brouet de fangemufle"}}},fp="18,193,16.326.0,25.385.1,40.176.0,26.148.0,44.174.0"}
P.entries["item:mudsnout-mixture"] = {n="Brouet de fangemufle",s="À Fossoyeuse, Maître apothicaire Faranell prépare la base d’un poison mortel des Réprouvés. Des champignons envoyés de Moulin-de-Tarren amorcent le mélange.",h="À Fossoyeuse, Maître apothicaire Faranell prépare la base d’un poison mortel des Réprouvés.",kw={"apothicaire","colloïde de décomposition","elixir of agony","faranell","hautebrande","lydon","brouet de fangemufle","fossoyeuse"},ang={["faction:Horde"]="En tant qu’aventurier de la Horde à Moulin-de-Tarren, vous transportez des concoctions toxiques à travers Lordaeron comme coursier et agent de terrain. Vous contribuez à consolider la position des Réprouvés en Hautebrande.",["race:Undead"]="En tant que mort-vivant, vous pouvez voir à l’œuvre l’ingéniosité impitoyable de la Société royale des apothicaires. Ses membres transforment des ingrédients sauvages en armes chimiques destinées à tuer les vivants."},sec={{t="Un colloïde de décomposition",b="L’Apothicaire Lydon, à Moulin-de-Tarren, cherche à créer une nouvelle arme biologique virulente. Il envoie vers le nord, à Fossoyeuse, un composé de Fleurs de fangemufle. Ces champignons toxiques poussent à la Ferme des Nethander, occupée par des gnolls.\n\nMaître apothicaire Faranell voit du potentiel dans ce composé et y ajoute son colloïde alchimique de décomposition. Le Brouet de fangemufle qui en résulte est volatil. Il stabilise le composé de champignons et prépare ses propriétés virulentes à un raffinage catalytique ultérieur dans les contreforts."},{t="Catalyser l’agonie",b="Avant que les agents contaminants puissent agir, le Brouet de fangemufle a besoin de catalyseurs essentiels. Faranell renvoie des coursiers à Moulin-de-Tarren avec la fiole, un puissant Élixir de sang de Troll, des écailles venimeuses de naga Daggerspine et des yeux de murloc Torn Fin.\n\nL’Apothicaire Lydon catalyse le mélange avec ces ingrédients pour créer l’Elixir of Agony mortel. Ce poison emblématique est destiné à semer la ruine parmi les ennemis vivants des Réprouvés."}},faq={{q="À quoi sert le Brouet de fangemufle ?",a="Le Brouet de fangemufle fournit la base chimique de l’Elixir of Agony. L’Apothicaire Lydon perfectionne ce poison expérimental à Moulin-de-Tarren pour tuer les ennemis des Réprouvés.",al={"utilité du brouet de fangemufle","effet du brouet de fangemufle","usage du brouet de fangemufle"}},{q="Qui crée le Brouet de fangemufle ?",a="Maître apothicaire Faranell crée le Brouet de fangemufle à Fossoyeuse. Il ajoute son colloïde alchimique de décomposition à une poudre de fangemufle brute.",al={"créateur du brouet de fangemufle","qui fabrique le brouet de fangemufle"}},{q="Pourquoi faut-il des composants de gnoll ?",a="Le Brouet de fangemufle ne nécessite aucune partie de gnoll. Le composé provient des Fleurs de fangemufle, des champignons toxiques qui poussent à la Ferme des Nethander, parmi les gnolls Mudsnout. L’Apothicaire Lydon les mélange pour en faire un composé avant que Faranell n’y ajoute son colloïde alchimique de décomposition.",al={"pourquoi fangemufle","lore du poison des gnolls"}},{q="Comment le mélange est-il activé ?",a="L’Apothicaire Lydon active les agents contaminants dormants avec un puissant Élixir de sang de Troll, des écailles de naga Daggerspine et des yeux de murloc Torn Fin recueillis le long de la côte d’Hautebrande.",al={"activer le brouet de fangemufle","réactifs de l’élixir d’agonie"}}},fx={ac01c76e={q="Pourquoi l'Apothicaire Lydon veut-il le Brouet de fangemufle ?",a="L'Apothicaire Lydon, au Moulin-de-Tarren, en a besoin pour synthétiser l'Elixir of Agony, un mélange expérimental destiné à répandre la maladie et la mort parmi les ennemis des Réprouvés. En activant ses agents contaminants avec du sang de troll et des réactifs côtiers, il compte faire avancer les recherches sur la peste de la Société royale des apothicaires.",al={"pourquoi le brouet de fangemufle est nécessaire","pourquoi lydon veut le brouet de fangemufle","à quoi sert le brouet de fangemufle"}},f656f7cb={q="Qu'est-ce que le Brouet de fangemufle ?",a="Il s'agit d'une préparation alchimique expérimentale formulée par la Société royale des apothicaires. Construite autour d'un composite de Fleurs de fangemufle, de champignons toxiques de la Ferme des Nethander, le mélange incorpore le colloïde de décomposition du Maître apothicaire Faranell lui-même pour servir de base volatile aux recherches sur la peste des apothicaires.",al={"qu'est-ce que le brouet de fangemufle","brouet de fangemufle","poudre de fangemufle"}}},fp="16,147,18.462.0,20.418.1,38.170.0,33.127.0,37.241.0,29.181.0"}
P.entries["item:murloc-head"] = {n="Tête de murloc",s="Sur le Rivage occidental, la Tête de murloc apporte à Austrivage la preuve sinistre d’une menace qu’on veut maîtriser. Le lieutenant Farren Orinelle rassemble les têtes tranchées pour le maréchal Redpath, qui exige des preuves de l’élimination des murlocs.",h="Sur le Rivage occidental, la Tête de murloc apporte à Austrivage la preuve sinistre d’une menace qu’on veut...",kw={"farren orinelle","farren's proof","contreforts de hautebrande","maréchal redpath","murloc","tête de murloc","austrivage","rivage occidental"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, débarrasser le Rivage occidental des murlocs contribue à protéger l’économie de la pêche d’Austrivage et à sécuriser le littoral de Lordaeron."},sec={{t="Une preuve plus macabre",b="Des murlocs agressifs menacent les pêcheurs d’Austrivage et les voyageurs du Rivage occidental. Les combattants de l’Alliance nettoient souvent les plages, mais le maréchal Marcus Redpath veut des preuves avant d’approuver les rapports annonçant le recul de la menace.\n\nLe lieutenant Farren Orinelle engage donc des combattants pour lui rapporter des têtes de murlocs. Farren trouve cette tâche répugnante, et cette vue lui a coupé l’appétit pour les fruits de mer d’Austrivage."}},faq={{q="Pourquoi Farren Orinelle veut-il des têtes de murlocs ?",a="Le maréchal Marcus Redpath veut une preuve tangible que les plages ont été débarrassées des murlocs. Le lieutenant Farren Orinelle collecte leurs têtes tranchées pour le satisfaire.",al={"preuve de farren","pourquoi des têtes de murlocs","qui veut des têtes de murlocs à austrivage"}},{q="Où trouve-t-on ces murlocs ?",a="Les murlocs se trouvent le long du Rivage occidental, sur la côte à l’ouest d’Austrivage, dans les Contreforts de Hautebrande.",al={"emplacement de la tête de murloc","où trouver des têtes de murlocs dans les contreforts de hautebrande","murlocs du rivage occidental"}},{q="Pourquoi Farren est-il si dégoûté par eux ?",a="Farren trouve les murlocs contre nature et écœurants. Leurs têtes tranchées le dégoûtent tant qu’il refuse de manger du poisson, un aliment de base à Austrivage.",al={"réaction de farren","farren mange du poisson"}},{q="La collecte des têtes règle-t-elle le problème des murlocs à Austrivage ?",a="Les têtes donnent au maréchal Redpath les preuves qu’il a demandées. Il les accepte et envoie Farren s’occuper des menaces sur le Rivage oriental.",al={"les murlocs cessent-ils d’attaquer","suite de quêtes de farren"}}},fx={ab7abae9={q="Qu'est-ce qu'une Tête de murloc ?",a="Il s'agit du crâne fraîchement tranché d'un murloc tué le long de la côte des Contreforts de Hautebrande. Froid, visqueux et suintant de fluides fétides, il sert de preuve physique indéniable d'une bête abattue pour défendre Austrivage.",al={"qu'est-ce qu'une tête de murloc","infos sur la tête de murloc","objet tête de murloc"}},["598cfa24"]={q="D'où proviennent les Têtes de murloc ?",a="Elles sont directement tranchées sur les corps des murlocs qui rôdent sur le Rivage occidental, juste à l'ouest d'Austrivage. Plutôt que des objets artisanaux, ce sont des trophées macabres pris aux pillards côtiers qui harcèlent la garnison de l'Alliance.",al={"où trouver les têtes de murloc","qui a fabriqué la tête de murloc","source de la tête de murloc"}}},fp="11,228,24.399.0,43.164.0,30.100.0,35.155.0,60.131.0"}
P.entries["item:musquash-root"] = {n="Racine de Musquash",s="Sous le Barrage de Formepierre, la Racine de Musquash pousse dans les Paluns. Peu de gens la récoltent, bien qu’un cercle caché sous Hurlevent en ait besoin pour préparer une infusion.",h="Sous le Barrage de Formepierre, la Racine de Musquash pousse dans les Paluns.",kw={"a noble brew","lord wishock","racine de musquash","barrage de formepierre","larme de tilloa","les paluns","zardeth"},ang={["class:Warlock"]="En tant que démoniste sous The Slaughtered Lamb, vous avez besoin de cette racine pour faire taire les nobles indiscrets et protéger votre fragile sanctuaire en ville.",["profession:Herbalism"]="En tant qu’herboriste, vous pouvez constater que le sol humide au pied des chutes du Barrage de Formepierre favorise une flore inhabituelle et dangereuse."},sec={{t="Un ingrédient rare",b="La Racine de Musquash pousse dans le sol humide au pied des chutes du Barrage de Formepierre. La brume et l’isolement rendent sa récolte difficile. Peu d’herboristes la recherchent, mais les adeptes des arts sombres prisent ses propriétés chimiques et alchimiques."},{t="Le plan du démoniste",b="Zardeth de la Griffe noire recherche la Racine de Musquash et la Larme de Tilloa sous Hurlevent, dans The Slaughtered Lamb. Ces plantes rares serviront à préparer une infusion discrète pour neutraliser Lord Wishock. Membre de la Chambre des nobles, il a commencé à enquêter sur le cercle de démonistes caché de la ville."}},faq={{q="Où trouve-t-on la Racine de Musquash ?",a="La Racine de Musquash pousse dans les Paluns, au pied des chutes sous le Barrage de Formepierre.",al={"où trouver la racine de musquash","emplacement de la racine de musquash","comment trouver la racine de musquash"}},{q="À quoi sert la Racine de Musquash ?",a="Zardeth de la Griffe noire veut la Racine de Musquash et la Larme de Tilloa pour préparer une infusion destinée à occuper Lord Wishock. Il espère ainsi freiner les efforts de Wishock pour faire enquêter sur le cercle de démonistes de Hurlevent.",al={"à quoi sert la racine de musquash","utilité de la racine de musquash","pourquoi ai-je besoin de la racine de musquash"}},{q="Qui veut que cette racine soit récoltée ?",a="Zardeth de la Griffe noire charge des agents de récupérer la Racine de Musquash. C’est un démoniste qui se trouve dans les catacombes sous The Slaughtered Lamb, dans le Quartier des Mages de Hurlevent.",al={"qui a besoin de la racine de musquash","donneur de quête de la racine de musquash","qui demande la racine de musquash"}},{q="Qui est Lord Wishock ?",a="Lord Wishock est membre de la Chambre des nobles de Hurlevent. Après avoir appris l’existence du cercle de démonistes de la ville, il a commencé à exhorter le conseil à ouvrir une enquête officielle.",al={"qui est wishock","lord wishock"}}},fx={["32cf7ee1"]={q="Qu'est-ce que la Racine de Musquash ?",a="La Racine de Musquash est un spécimen botanique rare qui pousse spécifiquement dans la brume humide au pied de la cascade située sous le Barrage de Formepierre, dans Les Paluns. Reconnue parmi les apothicaires noirs et les démonistes pour ses puissantes propriétés naturelles, elle sert de réactif crucial dans la préparation de breuvages trompeurs et de poisons lorsqu'elle est combinée à d'autres flores rares.",al={"qu'est-ce que la racine de musquash","connaissances sur la racine de musquash","informations sur la racine de musquash"}},d9341dd1={q="D'où vient la Racine de Musquash et qui l'a créée ?",a="La Racine de Musquash est une plante naturelle plutôt qu'une création artificielle. Elle prospère exclusivement dans Les Paluns, enracinée dans la pierre humide et le sol saturé au pied des chutes d'eau directement sous le grand Barrage de Formepierre.",al={"origine de la racine de musquash","où pousse la racine de musquash","qui a créé la racine de musquash"}}},fp="13,142,17.226.0,20.283.1,29.90.0,31.201.0,30.158.0,20.160.0"}
P.entries["item:mysterious-artifact-searing-gorge"] = {n="Artefact mystérieux",s="L’Artefact mystérieux est une relique gardée par les Idolaters du Marteau du crépuscule dans la Gorge des Vents brûlants. Elle est recherchée pour l’Altar of Suntara, dans la Fosse aux scories.",h="L’Artefact mystérieux est une relique gardée par les Idolaters du Marteau du crépuscule dans la Gorge des...",kw={"altar of suntara","idolaters","artefact mystérieux","gorge des vents brûlants","la fosse aux scories","artefact du crépuscule","marteau du crépuscule"},sec={{t="Une relique dans les collines",b="Au-dessus d’une grotte, dans les collines du nord-ouest de la Gorge des Vents brûlants, les Idolaters du Marteau du crépuscule gardent l’Artefact mystérieux. L’Altar of Suntara attend, vide, dans la Fosse aux scories. L’archéologue mourant vous demande d’y porter la relique et de la déposer sur l’autel."}},faq={{q="Où se trouve l’Artefact mystérieux ?",a="Les Idolaters du Marteau du crépuscule gardent l’Artefact mystérieux dans les collines du nord-ouest de la Gorge des Vents brûlants, au-dessus d’une grotte.",al={"emplacement de l’artefact","où se trouve la relique"}},{q="Qui garde l’artefact ?",a="Les Idolaters du Marteau du crépuscule gardent l’Artefact mystérieux dans les collines de la Gorge des Vents brûlants.",al={"qui le détient","relique du marteau du crépuscule"}},{q="Où faut-il le porter ?",a="L’Artefact mystérieux doit être déposé sur l’Altar of Suntara, dans la Fosse aux scories.",al={"emplacement de l’autel","où porter l’artefact"}},{q="Pourquoi recherche-t-on l’artefact ?",a="L’archéologue mourant vous demande de récupérer la relique et de la déposer sur l’Altar of Suntara.",al={"à quoi sert-il","pourquoi chercher la relique"}}},fp="19,136,20.247.0,33.112.0,24.88.0,25.72.0,27.92.0"}
P.entries["item:mysterious-fossil"] = {n="Mystérieux fossile",s="Sur la côte de Sombrivage, le Prospecteur Songerrance découvre le Mystérieux fossile. La Ligue des explorateurs l’envoie par-delà la mer pour l’étudier.",h="Sur la côte de Sombrivage, le Prospecteur Songerrance découvre le Mystérieux fossile.",kw={"sombrivage","ligue des explorateurs","outrepanse","grisemoustache","port de menethil","mystérieux fossile","songerrance"},ang={["faction:Alliance"]="En tant que membre de l’Alliance, vous pouvez suivre le parcours de la relique, des éclaireurs de terrain de Sombrivage aux érudits de Darnassus et du Port de Menethil.",["race:Dwarf"]="En tant que nain, vous pouvez voir dans ce fossile une nouvelle pièce manquante dans la quête de la Ligue des explorateurs, qui cherche à retrouver l’héritage antique des titans et des mystères oubliés."},sec={{t="Une découverte intrigante",b="Le Prospecteur Songerrance découvre un fossile inhabituel sur la côte sauvage de Sombrivage. Il s’arrange pour le remettre à des érudits nains plutôt que de le laisser dans la nature. À Darnassus, le Chef archéologue Grisemoustache reconnaît parmi les pierres de Kalimdor une trouvaille extraordinaire."},{t="Des liens par-delà l’océan",b="Le Chef archéologue Grisemoustache reconnaît une ressemblance avec un fossile rare présenté autrefois lors d’un rassemblement de la Ligue des explorateurs à Forgefer. L’Archéologue Outrepanse a étudié ce fossile et soupçonnait qu’il renfermait un pouvoir attendant d’être éveillé. Pour confirmer l’origine du nouveau fossile et découvrir ce qu’il pourrait renfermer, Grisemoustache l’envoie par-delà la mer à Outrepanse. Celui-ci attend à la Taverne de l'Eau-profonde, au Port de Menethil."}},faq={{q="Où le Mystérieux fossile a-t-il été découvert ?",a="Le Prospecteur Songerrance a découvert le Mystérieux fossile en travaillant sur l’ancienne côte nord de Sombrivage.",al={"lieu de découverte du fossile","où a-t-il été découvert","origine du fossile"}},{q="Pourquoi la Ligue des explorateurs s’intéresse-t-elle à ce fossile ?",a="Le Chef archéologue Grisemoustache voit un lien entre le fossile et les recherches de l’Archéologue Outrepanse. Outrepanse soupçonne que ces fossiles pourraient renfermer un pouvoir susceptible d’être éveillé.",al={"pourquoi les nains le veulent","intérêt de la ligue des explorateurs","que fait le fossile"}},{q="Qui est l’Archéologue Outrepanse ?",a="L’Archéologue Outrepanse mène des recherches pour la Ligue des explorateurs et a étudié des reliques pétrifiées similaires. Il séjourne à la Taverne de l'Eau-profonde, au Port de Menethil, en attendant une escorte pour le Site de fouilles de Whelgar, dans les Paluns.",al={"qui est outrepanse","lieu où se trouve outrepanse","où est outrepanse"}},{q="Qui est le Chef archéologue Grisemoustache ?",a="Le Chef archéologue Grisemoustache est le représentant principal de la Ligue des explorateurs à Darnassus. Grisemoustache supervise les recherches naines et les travaux archéologiques dans tout le nord de Kalimdor.",al={"grisemoustache","qui est grisemoustache","archéologue nain de darnassus"}}},fx={dc519f37={q="Qu'est-ce que le Mystérieux fossile ?",a="Le Mystérieux fossile est une relique ancienne déterrée dans la nature sauvage de Sombrivage par le nain, le Prospecteur Songerrance. Contrairement aux restes pétrifiés ordinaires, ce spécimen ressemble étrangement à un artefact extraordinaire précédemment présenté à la Ligue des explorateurs à Forgefer. Sa nature particulière suggère qu'il renferme des secrets ou un pouvoir endormi qui attend d'être révélé par un archéologue expérimenté.",al={"lore du mystérieux fossile","qu'est-ce que ce fossile","infos sur le mystérieux fossile"}}},fp="17,134,19.267.0,21.388.1,38.104.0,48.171.0,31.232.0,39.182.0"}
P.entries["item:mysterious-relic"] = {n="Relique mystérieuse",s="La Relique mystérieuse est un appareil inconnu découvert lors d'une fouille naga sur l'Île de l'effroi. Le Bastion de Pennelune veut l'étudier pour découvrir ce que c'est.",h="La Relique mystérieuse est un appareil inconnu découvert lors d'une fouille naga sur l'Île de l'effroi.",kw={"bastion de pennelune","île de l'effroi","latronicus moonspear","seigneur shalzaru","relique mystérieuse","fouille naga","relique","vestia moonspear"},sec={{t="Une étrange découverte",b="Des éclaireurs ont localisé la fouille du Seigneur Shalzaru dans une grotte au sud des ruines principales de l'Île de l'effroi. Le seigneur naga y a découvert la Relique mystérieuse, et Latronicus Moonspear a demandé qu'on l'apporte au Bastion de Pennelune pour l'étudier.\n\nLatronicus n'a pas su déterminer grand-chose au sujet de l'appareil, alors il l'a envoyé à son épouse Vestia, prêtresse et érudite. Elle l'a trouvé différent des objets habituels des ruines et des ouvrages nagas. Sa nature reste incertaine pendant qu'elle l'étudie."}},faq={{q="Où la Relique mystérieuse a-t-elle été trouvée ?",a="Le Seigneur Shalzaru a découvert la Relique mystérieuse dans une grotte de fouille naga au sud des ruines principales de l'Île de l'effroi.",al={"lieu de la relique","où trouver la relique","relique de l'île de l'effroi"}},{q="Qui veut la relique ?",a="Latronicus Moonspear a demandé qu'on apporte la Relique mystérieuse au Bastion de Pennelune pour qu'elle y soit étudiée.",al={"qui veut la relique","relique de latronicus","relique pour qui"}},{q="Qui étudie la Relique mystérieuse ?",a="Vestia Moonspear, épouse de Latronicus, prêtresse et érudite, étudie la Relique mystérieuse.",al={"vestia moonspear","qui étudie la relique","érudit de la relique"}},{q="Qu'est-ce que la Relique mystérieuse ?",a="Selon Vestia, la Relique mystérieuse ne ressemble pas aux objets des Ruines de Solarsal et n'est pas de conception naga. Elle a besoin de temps pour l'étudier.",al={"qu'est-ce que la relique","appareil étrange","signification de la relique"}},{q="Les nagas ont-ils fabriqué la relique ?",a="Selon Vestia, la Relique mystérieuse n'est pas de conception naga, mais son créateur reste inconnu.",al={"relique naga","fabriquée par les nagas","qui a fabriqué la relique"}}},fp="16,158,14.461.0,37.116.0,20.115.0,33.96.0,29.134.0,28.89.0"}
P.entries["item:nak-s-skull"] = {n="Crâne de Nak",s="Le Crâne de Nak a du poids dans les Tarides du sud, où les raids des Razormane menacent la Horde. Au Camp Taurajo, Mutiledent veut se venger des siens qui l'ont laissé mourir.",h="Le Crâne de Nak a du poids dans les Tarides du sud, où les raids des Razormane menacent la Horde.",kw={"tarides","betrayal from within","camp taurajo","kuz","lok orcbane","mutiledent","nak","crâne de nak","hurans","razormane"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez alléger la pression sur les lignes de ravitaillement entre le Camp Taurajo et La Croisée en rapportant les têtes de seigneurs de guerre Razormane comme Nak."},sec={{t="Un gage de vengeance",b="Nak, Kuz et Lok Orcbane mènent des raids depuis le Kraal de Tranchebauge à travers les Tarides. Leurs bandes de guerre frappent les colonies et les routes de la Horde, tandis que les défenseurs de La Croisée ignorent tout de leurs plans et les prennent pour de simples escarmouches tribales.\n\nAu Camp Taurajo, Mutiledent, un huran Razormane captif, a été laissé à mourir dans une cage par les siens. Il cherche maintenant à se venger de ses anciens frères. Il exige les crânes tranchés de Nak, Kuz et Lok Orcbane pour prouver leur mort, et demande à des aventuriers de la Horde de les lui apporter. Avec cette preuve, il compte briser les bandes de pillards du sud."}},faq={{q="Qui était Nak ?",a="Nak est un commandant huran Razormane qui mène des raids aux côtés de Kuz et de Lok Orcbane. Tous trois viennent du Kraal de Tranchebauge et attaquent les voyageurs et les colonies de la Horde dans les Tarides du sud.",al={"qui est nak","histoire de nak","nak dans les tarides"}},{q="Qui veut le Crâne de Nak ?",a="Mutiledent, un huran Razormane captif au Camp Taurajo, veut le Crâne de Nak. Les siens l'ont abandonné, et il cherche à se venger des chefs qui l'ont trahi.",al={"qui veut le crâne","à qui donner le crâne de nak","crâne de mutiledent"}},{q="Pourquoi Mutiledent veut-il les crânes des siens ?",a="Nak, Kuz et Lok Orcbane ont laissé Mutiledent mourir en captivité. Il aide la Horde à les retrouver et exige leurs têtes tranchées pour prouver leur mort.",al={"pourquoi trahir sa tribu","motivations de mutiledent","pourquoi mutiledent veut-il des crânes"}},{q="Récupérer le Crâne de Nak aide-t-il à protéger La Croisée ?",a="Oui. Selon Mutiledent, Nak et ses alliés dirigent les raids des Razormane contre La Croisée et les principales routes commerciales. Leur défaite affaiblit les attaques coordonnées de la tribu.",al={"la croisée est-elle en sécurité","arrêter les raids des hurans"}}},fx={["96a0c2b0"]={q="D'où vient le Crâne de Nak ?",a="Le crâne est prélevé directement sur la dépouille de Nak, un éminent hurans Razormane venu du Kraal de Tranchebauge. Nak et ses frères se sont aventurés loin dans le sud des Tarides pour orchestrer des raids impitoyables contre les campements de la Horde. Lorsque vous traquez Nak parmi les ronces du sud et le terrassez, son crâne détaché sert de preuve incontestable que ce dangereux pillard huran a été éliminé.",al={"origine crâne de nak","d'où vient le crâne de nak","qui possède le crâne de nak"}}},fp="11,169,20.535.0,12.191.0,22.158.0,55.148.0,56.172.0"}
P.entries["item:nek-rosh-s-head"] = {n="Tête de Nek'rosh",s="Dans les Paluns, la Tête de Nek'rosh parvient au Capitaine Rudepoing, preuve que le chef du clan Gueule-de-dragon est tombé. Les défenseurs de Port de Menethil savent désormais que la menace est brisée.",h="Dans les Paluns, la Tête de Nek'rosh parvient au Capitaine Rudepoing, preuve que le chef du clan...",kw={"capitaine rudepoing","chef","gueule-de-dragon","menethil","nek'rosh","nekrosh","les paluns"},ang={["faction:Alliance"]="Pour l'Alliance, remettre la Tête de Nek'rosh au Capitaine Rudepoing aide à défendre Port de Menethil contre une attaque imminente et vaut les faveurs du royaume de Forgefer.",["race:Dwarf"]="En tant que nain, vous savez que le clan Gueule-de-dragon sévit au Khaz Modan depuis la Seconde Guerre. Porter la tête tranchée du chef apporte une justice attendue depuis longtemps aux défenseurs des marécages."},sec={{t="Une frappe décisive",b="Dans les marécages, le clan Gueule-de-dragon rassemble des troupes et des armes de siège contre Port de Menethil, port de l'Alliance. Après l'incendie des catapultes du clan, la défense du port dépend de la mort du chef Nek'rosh. Sa tête tranchée prouve au Capitaine Rudepoing et aux autorités de Forgefer que le seigneur de guerre a perdu son emprise sur les Paluns."}},faq={{q="Qui était Nek'rosh ?",a="Nek'rosh dirigeait les derniers membres du clan Gueule-de-dragon dans les Paluns. Il menait les attaques et les opérations de guerre contre les territoires de l'Alliance voisins.",al={"qui est nek'rosh","chef nek'rosh","qui était nek'rosh"}},{q="Qui veut la Tête de Nek'rosh ?",a="Le Capitaine Rudepoing veut la Tête de Nek'rosh pour prouver que le chef est tombé. Il commande la défense de Port de Menethil et offre une récompense au nom de Forgefer.",al={"qui prend la tête","remettre la tête de nek'rosh","où apporter la tête de nek'rosh"}},{q="Pourquoi voulait-on tuer Nek'rosh ?",a="Nek'rosh dirigeait les forces du clan Gueule-de-dragon qui menaçaient Port de Menethil. L'Alliance cherchait à affaiblir la présence du clan dans la région en détruisant ses armes de siège et en tuant son chef.",al={"pourquoi tuer nek'rosh","pourquoi vaincre nek'rosh"}}},fx={e464fcda={q="Qu'est-ce que la Tête de Nek'rosh ?",a="Il s'agit de la tête tranchée du chef Nek'rosh, le seigneur de guerre commandant le clan Gueule-de-Dragon dans les Paluns. Elle sert de preuve macabre et indéniable que le plus grand ennemi local des Montagnards de Forgefer a enfin été tué.",al={"qu'est-ce que la tête de nek'rosh","objet tête de nek'rosh","tête tranchée de nek'rosh"}},["160e4c8d"]={q="D'où provient la Tête de Nek'rosh et qui l'a fabriquée ?",a="Elle est prélevée directement sur le chef Nek'rosh après que vous l'avez vaincu au campement Gueule-de-Dragon dans les Paluns. Elle n'a pas été fabriquée ou manufacturée, mais tranchée sur le chef orc déchu en guise de trophée et de confirmation de sa mort.",al={"d'où vient la tête de nek'rosh","comment obtenir la tête de nek'rosh","origine de la tête de nek'rosh"}},ce210494={q="Pourquoi le Capitaine Rudepoing veut-il la Tête de Nek'rosh ?",a="Le Capitaine Rudepoing exige une preuve indiscutable que le chef du clan Gueule-de-Dragon est tombé. Avec la mort de Nek'rosh et la destruction de leurs catapultes de guerre, Rudepoing sait que les Gueule-de-Dragon auront du mal à se relever, garantissant ainsi que le Port de Menethil et les Paluns sont enfin à l'abri d'un assaut organisé.",al={"pourquoi rudepoing veut la tête de nek'rosh","pourquoi veulent-ils la tête de nek'rosh","utilité de la tête de nek'rosh"}}},fp="15,176,17.341.0,17.130.0,26.160.0,36.191.0"}
P.entries["item:neru-fragment"] = {n="Fragment Neru",s="À l’Excavation de Whelgar, dans Les Paluns, le Fragment Neru préserve une partie de l’ancienne écriture des Titans de la Pierre de Goaz. Ses mots racontent l’histoire primordiale d’Azeroth.",h="À l’Excavation de Whelgar, dans Les Paluns, le Fragment Neru préserve une partie de l’ancienne écriture des...",kw={"excavation","pierre de goaz","terre meuble","fragment neru","prospecteur whelgar","uncovering the past","les paluns"},ang={["race:Dwarf"]="Pour l’Explorer's League, récupérer des morceaux de tablette comme le Fragment Neru aide à percer les secrets des Titans et à reconstituer les origines du peuple nain."},sec={{t="Morceau de la Pierre de Goaz",b="Le Prospecteur Whelgar a dirigé l’expédition naine qui a découvert la Pierre de Goaz. La relique s’est brisée en quatre morceaux : Ados, Modr, Golm et Neru. Puis des raptors ont envahi le site et interrompu les travaux. Le Fragment Neru est resté sous la terre meuble, parmi les bêtes agressives.\n\nUne fois récupéré, le fragment peut rejoindre les autres pour restaurer la tablette. Les mots qui subsistent évoquent un plan divin et une prophétie funeste. Les érudits nains ont un texte à déchiffrer."},{t="Lecture de la tablette restaurée",b="Le Prospecteur Whelgar restaure la Pierre de Goaz une fois les quatre fragments réunis. Il poursuit la traduction de son écriture des Titans. Les mots désormais lisibles parlent de Dieux très anciens enchaînés sous la terre."}},faq={{q="Qu’est-ce que le Fragment Neru ?",a="Le Fragment Neru est un morceau de pierre détaché de la Pierre de Goaz, une relique plus grande. L’expédition naine l’a découvert dans Les Paluns avant que des raptors n’envahissent le site de fouilles.",al={"histoire du fragment neru","qu’est-ce que le fragment neru","morceau de tablette neru"}},{q="Où trouve-t-on le fragment ?",a="Le Fragment Neru est éparpillé dans les Excavations de Whelgar, à l’est du Port de Menethil, dans Les Paluns. Il est généralement enfoui sous la terre meuble ou caché parmi des artefacts abandonnés.",al={"où trouver le fragment neru","emplacement du fragment neru","comment obtenir le fragment neru"}},{q="Que se passe-t-il lorsque les quatre fragments sont réunis ?",a="Une fois les quatre fragments réunis, le Prospecteur Whelgar reconstitue la Pierre de Goaz et poursuit la traduction de son écriture des Titans. Il cherche à percer le mystère suggéré par le texte qui subsiste.",al={"pierre de goaz complète","que dit la pierre de goaz","fin de uncovering the past"}}},fx={["1f660d59"]={q="D'où provient le Fragment Neru et qui l'a fabriqué ?",a="Le fragment provient de l'ancienne Pierre de Goaz découverte lors des fouilles de Whelgar dans les Paluns. Son inscription utilise l'écriture des Titans, mais le texte de quête récupéré n'identifie pas son créateur.",al={"origine du fragment neru","qui a fabriqué le fragment neru","d'où provient le fragment neru"}},b6f45f31={q="Pourquoi le Prospecteur Whelgar veut-il le Fragment Neru ?",a="Le Prospecteur Whelgar a déterré la Pierre de Goaz juste avant que le site de fouilles ne soit envahi par des raptors, mais il a constaté que l'inscription était brisée en quatre endroits distincts. Il a besoin de toute urgence du Fragment Neru, ainsi que des trois autres morceaux, pour assembler la tablette et continuer à déchiffrer les références à un plan divin et à une prophétie funeste.",al={"pourquoi trouver le fragment neru","pourquoi whelgar a besoin du fragment neru","utilité du fragment neru"}}},fp="13,161,23.442.0,27.190.1,26.162.0,28.175.0,50.193.1"}
P.entries["item:nessa-s-collection"] = {n="Collection de Nessa",s="À Rut'theran, la Collection de Nessa part pour Laird, à Auberdine, avec la preuve de poissons géants près des racines de Teldrassil.",h="À Rut'theran, la Collection de Nessa part pour Laird, à Auberdine, avec la preuve de poissons géants près des...",kw={"auberdine","arêtes de poisson","laird","nessa shadowsong","collection de nessa","rut'theran","teldrassil","vesprystus"},ang={["race:NightElf"]="En tant qu'Elfe de la nuit, vous pouvez voir en quoi les eaux autour de Teldrassil diffèrent de celles du continent."},sec={{t="Les trésors de l'Arbre-monde",b="Nessa Shadowsong vit à Rut'theran, au pied de Teldrassil. Elle a rassemblé des arêtes et des écailles pour comparer la vie marine de l'île à celle du Kalimdor continental. Les prises des eaux autour du Grand Arbre atteignent une taille remarquable. Nessa a donc envoyé des preuves par-delà la mer à Laird, un marchand de poissons installé le long des quais d'Auberdine. Le colis passe par Vesprystus, le maître des hippogriffes de Rut'theran, et témoigne de la vitalité croissante de Teldrassil."},{t="Une comparaison étonnante",b="À Sombrivage, Laird constate que ces spécimens dépassent de loin leurs équivalents continentaux. La collection contient des mâchoires presque deux fois plus grandes que celles des poissons originaires du littoral de Sombrivage. Ses écailles sont aussi grandes qu'un poing fermé. Pour les Elfes de la nuit de la côte, le colis montre à quel point les eaux de Teldrassil diffèrent des rivages sombres du nord de Kalimdor."}},faq={{q="Que contient la Collection de Nessa ?",a="La collection contient des arêtes et des écailles de poisson. Ses mâchoires sont presque deux fois plus grandes que celles des poissons originaires du littoral de Sombrivage, et ses écailles sont aussi grandes qu'un poing fermé. Ces poissons viennent des eaux autour de Rut'theran.",al={"contenu de la collection de nessa","contenu du colis","colis d'arêtes de poisson"}},{q="À qui la collection est-elle envoyée ?",a="Nessa envoie la collection à Laird, un vendeur de poissons elfe de la nuit installé le long des quais d'Auberdine, à Sombrivage.",al={"destinataire de la collection de nessa","qui est laird","destination de la livraison"}},{q="Pourquoi Nessa a-t-elle rassemblé ces spécimens de poissons ?",a="Nessa a rassemblé ces spécimens pour comparer les gros poissons qui prospèrent autour de Teldrassil à la vie marine du Kalimdor continental.",al={"raison de l'envoi des arêtes de poisson","comparaison des poissons de nessa","raison des trésors de teldrassil"}},{q="Comment la collection parvient-elle à Auberdine ?",a="Vous portez le colis à Vesprystus, le maître des hippogriffes de Rut'theran. Il organise son transport par-delà les eaux jusqu'à Auberdine, où il sera remis à Laird.",al={"mode de livraison","livraison par vesprystus","colis transporté par hippogriffe"}}},fx={["6bde19ac"]={q="Qu'est-ce que la Collection de Nessa ?",a="La Collection de Nessa est un paquet d'arêtes et d'écailles de poisson rassemblées dans les eaux autour de Rut'theran. Il représente l'abondance marine inhabituelle qui prospère à la base de l'Arbre-Monde Teldrassil, emballé soigneusement pour le transport à travers la mer vers le continent de Kalimdor.",al={"qu'est-ce que la collection de nessa","collection de nessa","objet collection de nessa"}},eb414ab6={q="D'où provient la Collection de Nessa et qui l'a faite ?",a="La collection a été assemblée par Nessa Shadowsong, une elfe de la nuit résidant à Rut'theran, à la base sud de Teldrassil. Puisant dans les prises remarquablement grosses rapportées par les pêcheurs locaux de l'île, elle a rassemblé des spécimens de choix à envoyer outre-mer.",al={"qui a fait la collection de nessa","d'où vient la collection de nessa","origine de la collection de nessa"}},d01c5154={q="Pourquoi quelqu'un voudrait-il la Collection de Nessa ?",a="Un marchand de poisson nommé Laird à Auberdine attend les spécimens pour pouvoir les étudier. Nessa espère comparer la taille et la vigueur étonnantes des prises de Rut'theran avec celles du continent, et Laird est impatient d'examiner des mâchoires deux fois plus grandes que la normale et des écailles grosses comme le poing.",al={"pourquoi laird veut la collection de nessa","pourquoi livrer la collection de nessa","utilité de la collection de nessa"}}},fp="18,132,24.419.0,20.355.0,34.237.0,36.98.0,42.120.0,40.145.0"}
P.entries["item:nether-gem"] = {n="Gemme du Néant",s="Dans les Clairières de Tirisfal, la Gemme du Néant transporte une silhouette mystérieuse du Lac Etincelant jusqu’à Bethor Glacéclat, à Fossoyeuse. À vous de découvrir ce qui les relie.",h="Dans les Clairières de Tirisfal, la Gemme du Néant transporte une silhouette mystérieuse du Lac Etincelant...",kw={"bethor glacéclat","lac etincelant","gunther arcanus","gemme du néant","liche prodigue","fossoyeuse"},ang={["class:Mage"]="En tant que mage, vous voyez comment les maîtres des arcanes peuvent franchir de grandes distances grâce à la scrutation magique et à la projection de leur visage, sans risquer le voyage.",["race:Undead"]="En tant que mort-vivant, vous savez que la livraison de la pierre marque un triomphe diplomatique pour les Réprouvés. Elle leur assure l’alliance de Gunther Arcanus, puissant allié contre le Fléau et la Croisade écarlate."},sec={{t="Un conduit de communion arcanique",b="Gunther Arcanus a forgé ou enchanté la Gemme du Néant sur son île du Lac Etincelant. Il s’était libéré de son plein gré de l’emprise du Roi-liche, mais la méfiance le tenait à l’écart de la jeune nation des Réprouvés. Quand son grimoire perdu lui est rendu, Gunther confie la gemme à un émissaire en signe de bonne volonté.\n\nAu sommet du Quartier de la Magie, à Fossoyeuse, Bethor Glacéclat canalise la magie à travers la pierre. Le visage magique de Gunther apparaît devant le chef de la guilde des mages, et les deux mages conversent à travers les Clairières de Tirisfal. Leur rencontre ouvre à Gunther la voie pour rejoindre dame Sylvanas et les Réprouvés."}},faq={{q="À quoi sert la Gemme du Néant ?",a="La Gemme du Néant permet à Gunther Arcanus de parler à grande distance avec Bethor Glacéclat. Lorsque Bethor canalise la magie dans la pierre, à Fossoyeuse, le visage éthéré de Gunther apparaît et les deux mages peuvent se parler directement.",al={"utilité de la gemme du néant","qu’est-ce que la gemme du néant","que fait la gemme du néant"}},{q="Qui a créé la Gemme du Néant ?",a="Gunther Arcanus fournit la Gemme du Néant. Il vit sur une île du Lac Etincelant et la remet à un émissaire pour son ancien camarade Bethor, après avoir récupéré son grimoire perdu.",al={"qui a créé la gemme du néant","d’où vient la gemme du néant","gemme de gunther"}},{q="Pourquoi la Gemme du Néant est-elle importante pour les Réprouvés ?",a="La Gemme du Néant aide Gunther Arcanus à rejoindre les Réprouvés. Il se méfiait des autres morts-vivants, craignant qu’ils ne soient encore les esclaves du Fléau. Grâce à la gemme, il reprend contact avec Bethor Glacéclat et prête allégeance à dame Sylvanas.",al={"importance de la gemme du néant","gunther et les réprouvés","gemme du néant des réprouvés"}}},fx={aa73e2cb={q="Qu'est-ce que la Gemme du Néant ?",a="La Gemme du Néant est un foyer magique qui vous est confié par Gunther Arcanus, un puissant mage mort-vivant résidant sur une île du Lac Etincelant. Chargée d'énergies arcaniques mystiques, elle agit comme un conduit magique qui permet à Gunther de communiquer sur de grandes distances et de projeter son visage directement à son vieil allié Bethor Glacéclat à Fossoyeuse.",al={"qu'est-ce que la gemme du néant","lore de la gemme du néant","objet gemme du néant"}}},fp="10,160,29.595.1,28.211.0,27.175.1,50.228.1"}
P.entries["item:nether-wing"] = {n="Nether Wing",s="Un Nether Wing est une aile de démon recherchée par Reclaimers Inc. à Désolace. Kreldig Ungor en a besoin de dix pour les expériences d’un mage, avec d’autres composants dangereux.",h="Un Nether Wing est une aile de démon recherchée par Reclaimers Inc.",kw={"désolace","kreldig ungor","nether maiden","nether sister","nether sorceress","nether wing","nether wings","composants pour reclaimers inc"},sec={{t="L’aile d’un démon",b="Les Nether Maidens, les Nether Sorceresses et les Nether Sisters de Désolace portent les ailes que recherche Kreldig Ungor. Il en demande dix pour compléter une collection de composants destinés aux expériences d’un mage. Il faut aussi des Felhound Brains et des fioles de Doomwarder Blood, ce qui rend cette collecte périlleuse."}},faq={{q="Qui recherche des Nether Wings ?",a="Kreldig Ungor, à Désolace, recherche dix Nether Wings pour les expériences d’un mage.",al={"qui a besoin de nether wing","nether wings pour qui"}},{q="D’où viennent les Nether Wings ?",a="Les Nether Wings proviennent des Nether Maidens, des Nether Sorceresses et des Nether Sisters de Désolace.",al={"d’où viennent les nether wings","origine des nether wings"}},{q="Pourquoi Kreldig Ungor en a-t-il besoin ?",a="Kreldig Ungor rassemble des Nether Wings comme composants pour les expériences d’un mage.",al={"pourquoi des nether wings","à quoi servent les ailes"}},{q="Quels autres composants faut-il ?",a="La collection nécessite aussi des Felhound Brains et des fioles de Doomwarder Blood.",al={"autres composants","de quoi d’autre kreldig a-t-il besoin"}}},fp="11,160,14.287.0,23.76.0,27.90.0,33.74.0,31.75.0"}
P.entries["item:nezzliok-s-head"] = {n="Nezzliok's Head",s="Nezzliok's Head est prélevée sur le sorcier-docteur Sombrecroc de Zul'Kunda. Nimboya en a besoin au Campement Grom'gol pour découvrir la vérité sur Yenniku.",h="Nezzliok's Head est prélevée sur le sorcier-docteur Sombrecroc de Zul'Kunda.",kw={"sombrecroc","grom'gol","nezzliok","nezzliok the dire","nezzliok's head","nimboya","sorcier-docteur","yenniku","zul'kunda"},ang={["faction:Horde"]="En tant que membre de la Horde, vous pouvez aider Nimboya et la tribu Sombrelance à découvrir la vérité sur Yenniku, leur parent disparu.",["race:Troll"]="En tant que troll, vous connaissez peut-être la rivalité entre les tribus Sombrelance et Sombrecroc. Nimboya cherche la vérité sur Yenniku auprès des chefs Sombrecroc."},sec={{t="Une offrande amère",b="Au Campement Grom'gol, Nimboya demande les têtes de Gan'zulah et de Nezzliok. Les deux chefs Sombrecroc savent peut-être ce qu'est devenu Yenniku, qui ne figurait pas parmi les têtes déjà retrouvées. Nezzliok's Head est apportée avec celle de Gan'zulah au chaudron bouillonnant, près de Nimboya."}},faq={{q="Qui est Nezzliok ?",a="Nezzliok the Dire est un sorcier-docteur de la tribu Sombrecroc, que l'on trouve à Zul'Kunda, dans le nord-ouest de la Vallée de Strangleronce.",al={"nezzliok","nezzliok the dire","sorcier-docteur sombrecroc"}},{q="Pourquoi Nimboya veut-il la tête de Nezzliok ?",a="Nimboya pense que Nezzliok et le chef Sombrecroc Gan'zulah connaissent peut-être la vérité sur Yenniku. Il demande donc leurs deux têtes.",al={"pourquoi la tête","nimboya veut la tête","nezzliok's head"}},{q="Où apporter Nezzliok's Head ?",a="Apportez Nezzliok's Head au chaudron bouillonnant du Campement Grom'gol, près de Nimboya.",al={"où apporter la tête","l'apporter à nimboya","chaudron"}},{q="Qu'est-il arrivé à Yenniku ?",a="Yenniku ne figurait pas parmi les têtes retrouvées par Nimboya. Celui-ci craint que seuls le chef Sombrecroc et le sorcier-docteur connaissent la vérité.",al={"yenniku disparu","où est yenniku","que s'est-il passé"}}},fp="15,153,17.264.0,16.113.0,38.127.0,32.85.0,25.123.0"}
P.entries["item:ng-5"] = {n="NG-5",s="Dans les Serres-Rocheuses, Gaxim Larguerouille prépare une diversion avec le NG-5. Le produit chimique volatil, le Nitromirglycéronium, est le composé d’allumage dont il a besoin pour les chariots chargés de dynamite.",h="Dans les Serres-Rocheuses, Gaxim Larguerouille prépare une diversion avec le NG-5.",kw={"dynamite","explosifs","gaxim larguerouille","gnome","ng-5","ng5","nitromirglycéronium","les serres-rocheuses"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous connaissez peut-être le NG-5 sous le nom de Nitromirglycéronium, un catalyseur capricieux prisé des bricoleurs quand la poudre noire ordinaire manque de puissance pour les munitions lourdes.",["race:Gnome"]="En tant que gnome, vous reconnaîtrez peut-être l’ingéniosité risquée qui consiste à faire sauter des chariots entiers de dynamite avec un produit chimique instable, pour créer une simple diversion."},sec={{t="Un réactif volatil",b="Gaxim Larguerouille est un agent gnome dans les Serres-Rocheuses, et le NG-5 est le composé dont il a besoin pour ses projets d’ingénierie. Son nom complet est Nitromirglycéronium. Cette solution dangereuse provoque la réaction nécessaire pour faire exploser des chariots chargés de dynamite, déclenchant une puissante explosion qui détournera l’attention de ses adversaires dans la région."}},faq={{q="Qu’est-ce que le NG-5 ?",a="Le NG-5 est l’abréviation de Nitromirglycéronium, un produit chimique très instable utilisé pour allumer des explosifs dans l’ingénierie gnome.",al={"qu’est-ce que le ng5","qu’est-ce que le nitromirglycéronium","objet ng-5"}},{q="Qui a besoin du NG-5 et pourquoi ?",a="Gaxim Larguerouille, un ingénieur gnome dans les Serres-Rocheuses, a besoin du NG-5 pour allumer plusieurs chariots remplis de dynamite. Il compte utiliser les explosions pour créer une diversion.",al={"qui a besoin du ng-5","gaxim larguerouille ng-5","pourquoi obtenir le ng5"}},{q="Le NG-5 est-il dangereux à manipuler ?",a="Le NG-5 est extrêmement dangereux à manipuler. Son fournisseur recommande aux coursiers de le manier avec la plus grande précaution et plaisante en disant que quiconque n’est pas un allié de Gaxim risque de se faire exploser en morceaux.",al={"le ng5 est-il sans danger","explosif ng-5","le ng5 va-t-il exploser"}}},fx={["43a87313"]={q="D'où provient le NG-5 et qui l'a fabriqué ?",a="Le NG-5, également connu sous le nom de Nitromirglycéronium, est obtenu auprès d'une connaissance de Gaxim Larguerouille qui brasse des composés chimiques spécialisés. Il s'agit d'un mélange alchimique extrêmement volatil concocté spécifiquement pour des réactions explosives, remis uniquement avec des avertissements sévères sur la facilité avec laquelle il peut mettre en pièces un coursier imprudent.",al={"qui a fabriqué le ng-5","où obtient-on le ng-5","créateur du ng-5"}}},fp="4,190,18.319.0,13.115.0,23.170.0,28.183.0"}
P.entries["item:nida-s-necklace"] = {n="Collier d'Hilary",s="À Comté-du-Lac, Hilary cherche dans le Lac placide le collier que son père lui a offert. Il a coulé pendant qu'elle pêchait avec les autres enfants près des quais.",h="À Comté-du-Lac, Hilary cherche dans le Lac placide le collier que son père lui a offert.",kw={"effsee","boue scintillante","hilary","lac placide","comté-du-lac","nida","collier de nida","les carmines","shawn"},ang={["faction:Alliance"]="Les défenseurs de Comté-du-Lac font face aux menaces des environs. Les aventuriers de l'Alliance de passage peuvent aider les enfants du coin à retrouver leurs objets précieux perdus."},sec={{t="Perdu dans les profondeurs",b="Hilary a perdu son collier en pêchant avec son ami Shawn près des rives de Comté-du-Lac. Son père le lui a offert et elle tient beaucoup à ce cadeau.\n\nDes bêtes féroces et des murlocs agressifs vivent dans les profondeurs du lac, alors les enfants du coin restent sur les quais. Le collier d'Hilary repose sous l'eau, enfoui dans la vase du fond du lac."}},faq={{q="À qui appartient ce collier ?",a="Hilary, une jeune fille de Comté-du-Lac, dans les Carmines, possède le collier. Son père le lui a offert.",al={"à qui appartient le collier","propriétaire du collier de nida","à qui est ce collier","propriétaire du collier d'hilary"}},{q="Comment le collier a-t-il atterri dans le Lac placide ?",a="Hilary pêchait au bord de l'eau avec Shawn lorsque le collier a glissé et coulé dans le Lac placide.",al={"comment le collier est-il arrivé dans le lac","pourquoi le collier est-il dans l'eau","comment le collier a-t-il été perdu"}},{q="Pourquoi les enfants n'ont-ils pas plongé pour le récupérer ?",a="Leurs parents leur interdisent de se baigner dans le Lac placide. Des prédateurs dangereux et des murlocs agressifs vivent dans ses eaux profondes et menacent les habitants.",al={"pourquoi nida n'a-t-elle pas nagé pour le récupérer","pourquoi shawn ne peut-il pas récupérer le collier","pourquoi hilary n'a-t-elle pas nagé pour le récupérer"}},{q="Qui est Effsee ?",a="Effsee est le chat de compagnie d'Hilary. Il reste à ses côtés à Comté-du-Lac et se réjouit que le collier ait retrouvé sa jeune propriétaire.",al={"qui est le petit chat","chat de nida","chat d'hilary"}}},fx={a22bd4db={q="D'où vient le collier d'Hilary ?",a="Le collier était un cadeau du père d'Hilary. Sans grande renommée historique ou magique, il reste un précieux souvenir familial offert à une fillette vivant à Comté-du-Lac.",al={"qui a fabriqué le collier d'hilary","d'où vient le collier d'hilary","qui a donné le collier à hilary"}},["14f3017c"]={q="Pourquoi recherche-t-on le Collier d'Hilary ?",a="Hilary a perdu son collier en pêchant près des quais du Lac placide. Comme ses parents interdisent aux enfants de plonger dans ces eaux infestées de monstres, son ami Shawn demande aux aventuriers de passage de braver les profondeurs du lac pour lui rapporter ce précieux souvenir.",al={"pourquoi retrouver le collier d'hilary","qui veut le collier d'hilary","pourquoi hilary veut récupérer son collier"}}},fp="17,165,18.314.0,33.106.0,46.102.0,47.157.0,14.120.0"}
P.entries["item:nightmare-shard"] = {n="Eclat de cauchemar",s="Dans les Cavernes des lamentations, l’Eclat de cauchemar porte une souillure que Falla Vent-de-sagesse ne peut ignorer. Elle y enferme l’essence pure et troublée du Rêve d’émeraude et l’envoie aux druides chevronnés, avec un avertissement qui leur est réservé.",h="Dans les Cavernes des lamentations, l’Eclat de cauchemar porte une souillure que Falla Vent-de-sagesse ne...",kw={"rêve d'émeraude","falla vent-de-sagesse","eclat luminescent","hamuul runetotem","in nightmares","mathrengyl pasdelours","eclat de cauchemar","cavernes des lamentations"},ang={["class:Druid"]="Pour les druides, l’éclat révèle que la corruption a atteint le Rêve d’émeraude. Il confirme leurs inquiétudes quant au sort de Naralex dans les Cavernes des lamentations.",["faction:Horde"]="Pour les voyageurs de la Horde, l’éclat apporte de sinistres nouvelles à la Cime des Anciens, à Pitons-du-Tonnerre. Là, Hamuul Runetotem s’efforce d’ancrer la place des taurens au sein de la grande fraternité cénarienne."},sec={{t="Une vision corrompue",b="Au plus profond des Cavernes des lamentations, Falla Vent-de-sagesse examine un éclat luminescent. Son énergie est plus sombre qu’elle ne l’imaginait. Elle reflète une affliction contre nature dans le Rêve d’émeraude, comme un cauchemar éveillé. Falla enferme cette essence souillée dans l’Eclat de cauchemar et ordonne de le porter sans délai aux dirigeants anciens du Cercle cénarien."},{t="Présages étouffés",b="L’Eclat de cauchemar parvient à l’archidruide Hamuul Runetotem sur la Cime des Anciens ou à Mathrengyl Pasdelours à Darnassus. Chacun scrute ses profondeurs avec consternation. La vision les trouble et confirme leurs soupçons silencieux : quelque chose a terriblement mal tourné dans le Rêve. Craignant la panique, les druides gardent l’éclat et avertissent le messager de ne plus parler de ce qu’il a vu."}},faq={{q="Qu’est-ce que l’Eclat de cauchemar ?",a="Après avoir examiné un fragment luminescent des Cavernes des lamentations, Falla Vent-de-sagesse confie l’Eclat de cauchemar à un messager. Il contient l’essence pure et troublée du Rêve d’émeraude, ainsi qu’une vision sombre et corruptrice plutôt que les paisibles énergies de la nature.",al={"qu’est-ce que l’éclat de cauchemar","histoire de l’éclat de cauchemar"}},{q="Qui a créé l’Eclat de cauchemar ?",a="Falla Vent-de-sagesse examine un fragment luminescent venu des Cavernes des lamentations et reconnaît sa corruption. Elle charge le messager de porter l’éclat directement aux druides chevronnés pour qu’ils l’étudient.",al={"qui a créé l’éclat de cauchemar","d’où vient l’éclat"}},{q="Pourquoi les chefs druides sont-ils si alarmés ?",a="En scrutant l’éclat, Hamuul Runetotem et Mathrengyl Pasdelours voient un cauchemar déformer le Rêve d’émeraude. Craignant le danger et la panique, ils font taire toute discussion et gardent l’affaire entre les membres chevronnés du Cercle cénarien.",al={"pourquoi hamuul est-il inquiet","pourquoi mathrengyl cache-t-il l’éclat"}},{q="Où faut-il livrer l’éclat ?",a="Les voyageurs de la Horde doivent porter l’éclat à l’archidruide Hamuul Runetotem, sur la Cime des Anciens, à Pitons-du-Tonnerre. Les voyageurs de l’Alliance le portent à Mathrengyl Pasdelours, auprès du Cercle cénarien, à Darnassus.",al={"à qui apporter l’éclat","remise de l’éclat de cauchemar"}}},fp="15,214,18.327.0,12.369.1,28.241.0,32.186.0,43.240.1,42.205.0"}
P.entries["item:nightsaber-fang"] = {n="Croc de sabre-de-nuit",s="À Teldrassil, les chasseurs prélèvent les crocs des sabres-de-nuit qui rôdent dans la forêt. Les habitants des bois recherchent ces dents comme composants.",h="À Teldrassil, les chasseurs prélèvent les crocs des sabres-de-nuit qui rôdent dans la forêt.",kw={"dolanaar","croc","sabre-de-nuit","composant","satyre","teldrassil","zenn vilsabot"},ang={["class:Hunter"]="En tant que chasseur, vous prouvez votre talent dans la nature en abattant un sabre-de-nuit et en prenant son croc. Donner ses parties à des esprits corrompus des bois dénature l'esprit de la chasse.",["race:NightElf"]="En tant qu'elfe de la nuit, vous connaissez les sabres-de-nuit comme des compagnons chers et des symboles d'Elune. Chasser ces prédateurs sacrés pour un satyre perfide est une honte."},sec={{t="Trophée de chasse",b="Sous la canopée de Teldrassil, les sabres-de-nuit chassent parmi les prédateurs naturels les plus redoutables du nord de Kalimdor. Les elfes de la nuit les vénèrent pour leur agilité, leur férocité et leur profond lien spirituel avec Elune. Un chasseur qui en tue un peut prendre ses crocs acérés comme preuve de son talent. Pourtant, certaines figures de la forêt recherchent ces crocs pour des rites plus sombres."},{t="Un composant pour un satyre",b="Aux abords de Dolanaar, le satyre Zenn Vilsabot s'en prend aux voyageurs enthousiastes et inexpérimentés. Il prétend avoir besoin de composants sylvestres, puis persuade les nouveaux venus de récolter des crocs de sabre-de-nuit, des plumes de strigidé et de la Soie d'araignée Tissebois. Lui donner ces matériaux aide l'imposteur. Lorsqu'ils les lui remettent, il se moque ouvertement du héros naïf."}},faq={{q="D'où viennent les crocs de sabre-de-nuit ?",a="Les crocs de sabre-de-nuit proviennent des prédateurs qui rôdent à Teldrassil, en particulier dans la forêt autour de Dolanaar.",al={"où trouver des crocs de sabre-de-nuit","qui donne des crocs de sabre-de-nuit","source des crocs de sabre-de-nuit"}},{q="Qui veut des crocs de sabre-de-nuit à Teldrassil ?",a="Zenn Vilsabot, un satyre aux abords de Dolanaar, demande aux aventuriers de passage de lui apporter des crocs de sabre-de-nuit.",al={"qui a besoin de crocs de sabre-de-nuit","à qui remettre des crocs de sabre-de-nuit","qui achète des crocs de sabre-de-nuit"}},{q="Pourquoi Zenn Vilsabot veut-il des crocs de sabre-de-nuit ?",a="Zenn prétend avoir besoin de composants animaux pour ses travaux dans la forêt, mais il en cache le but. Il adore duper les voyageurs crédules.",al={"pourquoi zenn veut des crocs","utilité des composants de zenn vilsabot","motif de la demande de zenn"}},{q="Quels autres composants Zenn demande-t-il avec les crocs ?",a="En plus de deux crocs de sabre-de-nuit, Zenn demande deux plumes de chouette strigidée et deux morceaux de Soie d'araignée Tissebois.",al={"de quoi zenn a-t-il aussi besoin","objets demandés par zenn","autres composants pour zenn"}}},fx={bc504af2={q="Qu'est-ce qu'un Croc de sabre-de-nuit ?",a="Un Croc de sabre-de-nuit est une canine acérée prélevée sur les sabres-de-nuit qui rôdent dans les forêts de Teldrassil. Bien qu'il s'agisse simplement d'une partie naturelle de ces grands félins prédateurs, ces crocs sont recherchés par les praticiens des arts sombres qui les prisent comme réactifs bruts pour des rituels clandestins et des concoctions non autorisées.",al={"qu'est-ce qu'un croc de sabre-de-nuit","lore du croc de sabre-de-nuit","à propos des crocs de sabre-de-nuit"}}},fp="15,118,18.331.0,17.310.1,36.115.0,41.98.0,45.138.1,58.112.0"}
P.entries["item:nimboya-s-pike"] = {n="Nimboya's Pike",s="Nimboya’s Pike est une arme que Nimboya prête pour adresser un sinistre message aux trolls Witherbark des Hinterlands. Leur trahison envers Thrall a attiré la colère de la Horde sur leurs villages.",h="Nimboya’s Pike est une arme que Nimboya prête pour adresser un sinistre message aux trolls Witherbark des...",kw={"sinistre message","hinterlands","horde","pique chargée","nimboya","nimboya’s pike","pique","thrall","witherbark"},ang={["faction:Horde"]="La pique porte la colère de la Horde contre les Witherbark pour avoir trahi Thrall, leur ancien allié."},sec={{t="Un sinistre message",b="À Strangleronce, Nimboya vous remet sa pique et vous envoie vers le nord, dans les Hinterlands. Les trolls Witherbark ont autrefois combattu aux côtés de la Horde, mais ils ont trahi Thrall. Nimboya entend leur faire payer cette trahison. Il nomme Hiri’watha et Zun’watha comme endroits où laisser son message."}},faq={{q="À qui s’adresse Nimboya’s Pike ?",a="Nimboya vous prête la pique pour porter son message aux trolls Witherbark des Hinterlands.",al={"nimboya’s pike","pour qui est la pique"}},{q="Pourquoi Nimboya veut-il punir les Witherbark ?",a="Les trolls Witherbark étaient autrefois alliés à la Horde, mais ils ont trahi Thrall.",al={"pourquoi punir les witherbark","trahison des witherbark"}},{q="Où dois-je apporter la pique ?",a="Nimboya vous envoie dans les Hinterlands, au nord-est du Moulin-de-Tarren, pour laisser le message à Hiri’watha ou à Zun’watha.",al={"où apporter la pique","pique des hinterlands"}},{q="Qu’est-ce que Nimboya’s Laden Pike ?",a="C’est Nimboya’s Pike ornée de crânes Witherbark, destinée à être déposée dans l’un de leurs villages en guise de sinistre message.",al={"pique chargée","pique à crânes"}}},fp="14,182,14.292.0,28.96.0,48.78.0,29.116.0,31.112.1"}
P.entries["item:nissa-s-remains"] = {n="Cadavre de Nissa",s="Dans le nord des Clairières de Tirisfal, le Cadavre de Nissa est celui d’une noble des Agamand. Le Fléau l’a tuée avec les siens durant la Troisième guerre, puis les a asservis. Aujourd’hui, d’anciens ouvriers traquent la famille pour se venger.",h="Dans le nord des Clairières de Tirisfal, le Cadavre de Nissa est celui d’une noble des Agamand.",kw={"moulins d'agamand","brill","coleman farthing","deaths in the family","nissa agamand","cadavre de nissa","clairières de tirisfal"},ang={["faction:Horde"]="Tuer les Agamand réanimés et nettoyer leurs moulins contribue à protéger le nord des Clairières de Tirisfal contre les poches du Fléau qui menacent Brill et Fossoyeuse.",["race:Undead"]="Pour les Réprouvés, reconquérir Tirisfal signifie purger leurs anciens oppresseurs du Fléau et les aristocrates fortunés dont l’orgueil a condamné les ouvriers à la non-mort."},sec={{t="Un héritage d’orgueil",b="Avant la Troisième guerre, les Agamand étaient la famille la plus riche et la plus influente des Clairières de Tirisfal. Leurs moulins prospères s’étendaient sur les collines du nord. Lorsque la peste de la non-mort se répandit dans Lordaeron, les patriarches refusèrent de fuir. Ils fortifièrent leurs domaines et convainquirent leurs serviteurs et leurs ouvriers de rester pour combattre. Leur orgueil leur coûta la vie. Le Fléau tua les Agamand et les releva en esclaves écervelés, soumis à la volonté du Roi-liche."},{t="Une vengeance amère",b="À Brill, les survivants qui se libérèrent plus tard sous la reine Sylvanas Coursevent se souviennent encore de l’orgueil fatal des Agamand. Coleman Farthing a jadis travaillé dans leurs moulins et en veut à ses anciens maîtres d’avoir entraîné les ouvriers dans la non-mort. Il envoie des aventuriers abattre les Agamand relevés et récupérer leurs restes physiques, dont ceux de Nissa. Pour Farthing et les autres Réprouvés, détruire ces reliques apporte un sombre sentiment de conclusion et de vengeance."}},faq={{q="Qui était Nissa Agamand ?",a="Nissa Agamand était une noble de la famille Agamand, qui possédait les vastes Moulins d’Agamand dans les Clairières de Tirisfal. Quand le Fléau déferla sur Lordaeron, elle mourut avec les siens et fut relevée en servante morte-vivante, sous le contrôle du Roi-liche.",al={"qui est nissa","histoire de nissa","nissa agamand"}},{q="Pourquoi Coleman Farthing veut-il les restes de Nissa ?",a="Coleman Farthing travaillait dans les moulins des Agamand de son vivant. Il en veut à la famille d’avoir refusé de fuir et d’avoir persuadé ses fidèles ouvriers de rester et de mourir. Rassembler les restes de la famille lui permet de se venger de ses anciens maîtres.",al={"pourquoi coleman veut les restes","pourquoi tuer les agamand","motivations de coleman farthing"}},{q="Où ces restes sont-ils rassemblés ?",a="Nissa Agamand hante les Moulins d’Agamand en ruine, dans le nord des Clairières de Tirisfal. Elle erre parmi les fermes délabrées avec ses proches réanimés et les serviteurs écervelés du Fléau.",al={"où trouver nissa","emplacement de nissa agamand"}},{q="Nissa a-t-elle conservé sa volonté propre comme les Réprouvés ?",a="Non. Nissa et sa famille sont restées asservies au Fléau en tant que morts-vivants écervelés, contrairement aux Réprouvés qui se sont libérés du Roi-liche. Elles n’avaient ni la conscience ni la liberté des citoyens de Fossoyeuse.",al={"nissa est-elle réprouvée","nissa avait-elle sa volonté propre","nissa fait-elle partie du fléau"}}},fx={a9aa03e3={q="Qu'est-ce que le Cadavre de Nissa ?",a="Il s'agit des restes physiques de Nissa Agamand, membre de la riche dynastie Agamand qui possédait autrefois les moulins dans le nord des Clairières de Tirisfal. Lorsque le Fléau a balayé Lordaeron, la famille a fortifié son domaine et a convaincu ses travailleurs de tenir bon. Comme le reste de sa famille, Nissa a succombé à la peste et s'est relevée en tant qu'esclave sans cervelle au service du roi Liche.",al={"qu'est-ce que le cadavre de nissa","cadavre de nissa","à qui appartient le cadavre de nissa"}},["4cb46b58"]={q="D'où provient le Cadavre de Nissa et qui l'a fait ?",a="Ils sont récupérés directement sur le cadavre détruit de Nissa Agamand aux Moulins d'Agamand. Autrefois une fière aristocrate, elle a succombé à la peste de la non-mort et a persisté sur ses terres ancestrales en tant que créature mort-vivante. Les restes sont ce que vous récupérez après avoir mis au repos sa forme de servante du Fléau sans cervelle.",al={"où obtient-on le cadavre de nissa","comment obtenir le cadavre de nissa","qui a donné le cadavre de nissa"}}},fp="15,240,17.460.0,18.437.0,22.243.0,47.228.0,33.176.0,49.195.0"}
P.entries["item:nitroglycerin"] = {n="Nitroglycérine",s="À Bael Modan, la Nitroglycérine permet aux nains de pousser leurs fouilles sur les terres des taurens. Les soldats et les officiers transportent ce produit chimique volatil, qui peut aussi être retourné contre la forteresse.",h="À Bael Modan, la Nitroglycérine permet aux nains de pousser leurs fouilles sur les terres des taurens.",kw={"bael modan","bael'dun","tarides","explosifs","gann cime-de-pierre","nitroglycérine","revenge of gann"},ang={["profession:Engineering"]="En tant qu’ingénieur, vous connaissez la Nitroglycérine comme un explosif composé. La Pulpe de bois l’absorbe, tandis que le Nitrate de sodium aide à la stabiliser et à la faire détoner.",["race:Tauren"]="En tant que tauren, vous voyez dans les produits chimiques volatils autour de Bael Modan la marque amère des ravages infligés à la tribu Stonespire."},sec={{t="Démolition industrielle",b="À Bael Modan, les nains creusent dans les terres ancestrales des taurens Stonespire. De lourdes foreuses et des produits chimiques volatils les aident à faire avancer les fouilles. Sur le site et dans son donjon fortifié, ils utilisent de la Nitroglycérine pour creuser des trous profonds et démolir les collines. Les soldats et les officiers transportent des fioles pendant les travaux, parmi eux le seigneur Cyrik Blackforge."},{t="À leur propre jeu",b="Après la mort du prospecteur Khazgorm, Gann Cime-de-pierre cherche à détruire la forteresse qui empiète sur les terres de son peuple. Ce tauren déplacé étudie les plans d’ingénierie nains malgré le danger. Il apprend que la Nitroglycérine, la Pulpe de bois et le Nitrate de sodium peuvent être combinés en une charge assez puissante pour frapper la garnison militaire de Bael Modan."}},faq={{q="D’où vient la Nitroglycérine ?",a="Les forces naines de Bael Modan, dans les Tarides du sud, transportent de la Nitroglycérine. Parmi elles se trouvent les Bael'dun Soldiers, les Bael'dun Riflemen, les Bael'dun Officers et le seigneur Cyrik Blackforge, dans le donjon.",al={"où trouver la nitroglycérine","qui lâche de la nitroglycérine","source de nitroglycérine"}},{q="À quoi sert la Nitroglycérine ?",a="Gann Cime-de-pierre combine la Nitroglycérine avec de la Pulpe de bois et du Nitrate de sodium pour fabriquer une puissante charge contre la forteresse militaire de Bael Modan.",al={"à quoi sert la nitroglycérine","utilité de la nitroglycérine","ingrédients de revenge of gann"}},{q="Pourquoi les nains en transportaient-ils au départ ?",a="Sur leur site de fouilles archéologiques, les prospecteurs et soldats de Bael Modan utilisent des explosifs, des machines à vapeur et des produits chimiques volatils pour creuser la terre.",al={"pourquoi les nains ont de la nitroglycérine","explosifs de bael modan"}},{q="Qui est Gann Cime-de-pierre ?",a="Gann Cime-de-pierre est un guerrier tauren exilé. Les nains ont bâti le site de fouilles de Bael Modan et son donjon sur les terres ancestrales de sa tribu, chassant les Stonespire par la destruction industrielle.",al={"qui est gann","gann cime-de-pierre"}}},fx={["9ba54f78"]={q="Qu'est-ce que la Nitroglycérine ?",a="La Nitroglycérine est une substance chimique volatile transportée par les forces naines retranchées à Bael Modan, dans les Tarides du sud. L'expédition Bael'dun s'appuie sur une ingénierie lourde et des matériaux de dynamitage pour excaver les terres ancestrales des taurens et éventrer la terre. Dans les mélanges volatils, elle constitue un composant essentiel à la construction de charges explosives à haut rendement.",al={"qu'est-ce que la nitroglycérine","histoire de l'objet nitroglycérine","à quoi sert la nitroglycérine"}}},fp="13,181,21.348.0,29.333.1,35.166.0,35.138.0,52.142.0,23.199.0"}
P.entries["item:nondescript-letter"] = {n="Lettre quelconque",s="Calvin Montague envoie une Lettre quelconque du Glas à Renée l'aubergiste, à Brill. Il demande aux Réprouvés fraîchement réveillés de la porter vers l'est, leur donnant une raison de quitter la vallée pour la Taverne des Pendus.",h="Calvin Montague envoie une Lettre quelconque du Glas à Renée l'aubergiste, à Brill.",kw={"a rogue's deal","brill","calvin montague","le glas","renée l'aubergiste","lettre quelconque","renée"},ang={["class:Rogue"]="Le comportement fuyant de Calvin Montague et le changement soudain d'humeur de Renée évoquent une intrigue et des messages codés des bas-fonds.",["race:Undead"]="En tant que Réprouvé fraîchement relevé, porter cette lettre vous donne une première raison de quitter le Glas et d'explorer les communautés des Clairières de Tirisfal."},sec={{t="La course d'un coursier",b="Près du Glas, Calvin Montague demande aux Réprouvés fraîchement relevés de porter vers l'est une enveloppe sans marque jusqu'à Brill. Il dit être las de combattre des zombies et des araignées, et précise que la lettre est destinée à Renée l'aubergiste. Sa promesse d'une généreuse récompense sonne faux. Cette course mène les voyageurs hors de la vallée, vers la Taverne des Pendus."},{t="Une correspondance suspecte",b="À Brill, Renée l'aubergiste prétend que la lettre apporte de douces nouvelles de sa sainte mère, au Glas. Quand le coursier comprend qu'elle ment, son air joyeux laisse place à l'irritation. Elle lui arrache la lettre et refuse de dire qui l'a envoyée ou ce qu'elle contient. À moins que le porteur ne compte payer une chambre, elle lui ordonne de partir."}},faq={{q="Qu'est-ce que la Lettre quelconque ?",a="La Lettre quelconque est une enveloppe sans marque que Calvin Montague confie près du Glas aux Réprouvés fraîchement réveillés, pour qu'ils la portent à Renée l'aubergiste, à Brill.",al={"lettre quelconque","qu'est-ce que cette lettre","lettre de calvin"}},{q="Qui envoie la lettre et qui la reçoit ?",a="Calvin Montague confie la lettre à des coursiers au Glas. Elle est adressée à Renée l'aubergiste, à la Taverne des Pendus, à Brill.",al={"qui a envoyé la lettre","qui reçoit la lettre","expéditeur de la lettre"}},{q="Que dit réellement la lettre ?",a="Le contenu de la lettre n'est jamais révélé. Quand vous l'interrogez, Renée l'aubergiste abandonne son air joyeux et vous répond avec colère que ses origines et son contenu ne vous regardent pas.",al={"que dit la lettre","contenu de la lettre","peut-on lire la lettre"}},{q="Pourquoi Calvin Montague veut-il la faire livrer ?",a="Calvin dit qu'il est trop occupé à combattre les zombies et les araignées alentour pour porter la lettre lui-même. La livraison fait sortir les voyageurs du Glas et les conduit aux auberges et aux lieux de repos de Brill.",al={"pourquoi envoyer la lettre","motif de calvin","pourquoi brill"}}},fp="18,205,18.327.0,25.323.1,31.146.0,42.131.0,34.163.0,43.190.0"}
